CREATE OR REPLACE FUNCTION public._test_tickets_v2_compute_function()
 RETURNS TABLE(test_name text, passed boolean, detail text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  z_any UUID;
BEGIN
  SELECT id INTO z_any FROM public.event_ticket_zones ORDER BY created_at DESC NULLS LAST LIMIT 1;

  IF z_any IS NULL THEN
    RETURN QUERY SELECT 'T0 sem-zonas:skip'::TEXT, true, 'Sem zonas de bilheteira disponíveis para teste'::TEXT;
    RETURN;
  END IF;

  SELECT * INTO r FROM public.compute_ticket_type_for_lot(
    'Tag | Nome Sem Lote', z_any, false, NULL, 1, NULL
  );
  RETURN QUERY SELECT
    'regex-sem-sufixo-lote:base-puro'::TEXT,
    (r.base_name = 'Nome Sem Lote'),
    ('base=' || COALESCE(r.base_name, 'null'))::TEXT;

  SELECT * INTO r FROM public.compute_ticket_type_for_lot(
    'Nome Direto', z_any, false, NULL, 1, NULL
  );
  RETURN QUERY SELECT
    'regex-sem-pipe:base-puro'::TEXT,
    (r.base_name = 'Nome Direto'),
    ('base=' || COALESCE(r.base_name, 'null'))::TEXT;

  SELECT * INTO r FROM public.compute_ticket_type_for_lot(
    'Tag | Nome Composto - Lote 7', z_any, false, NULL, 1, NULL
  );
  RETURN QUERY SELECT
    'regex-sufixo-lote-maiusculo:remove'::TEXT,
    (r.base_name = 'Nome Composto'),
    ('base=' || COALESCE(r.base_name, 'null'))::TEXT;

  SELECT * INTO r FROM public.compute_ticket_type_for_lot(
    'Passe Estranho', z_any, true, ARRAY[]::uuid[], 2, NULL
  );
  RETURN QUERY SELECT
    'combo-consumes-vazio:warning'::TEXT,
    ('combo_with_empty_consumes' = ANY(COALESCE(r.warnings, ARRAY[]::text[]))),
    ('warnings=' || COALESCE(array_to_string(r.warnings, ','), ''))::TEXT;

  SELECT * INTO r FROM public.compute_ticket_type_for_lot(
    'Whatever', '00000000-0000-0000-0000-000000000000'::uuid,
    false, NULL, 1, NULL
  );
  RETURN QUERY SELECT
    'zona-inexistente:warning'::TEXT,
    (r.found_type_id IS NULL
     AND r.base_name IS NULL
     AND EXISTS (SELECT 1 FROM unnest(COALESCE(r.warnings, ARRAY[]::text[])) w WHERE w LIKE 'orphan_zone:%')),
    ('warnings=' || COALESCE(array_to_string(r.warnings, ','), ''))::TEXT;
END $function$

CREATE OR REPLACE FUNCTION public.artist_content_normalize_song_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.song_id IS NULL THEN
    NEW.song_link_status := 'none';
    NEW.song_link_reason := NULL;
  ELSIF coalesce(NEW.song_link_status, 'none') = 'none' THEN
    NEW.song_link_status := 'estimated';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.batch_insert_event_forecasts(_event_id uuid, _version_id uuid DEFAULT NULL::uuid, _inserts jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
  v_caller uuid := auth.uid();
  v_can_edit boolean;
  v_is_partner_editor boolean := false;
  v_ins jsonb;
  v_cat record;
  v_iva int;
  v_amount numeric;
  v_type text;
  v_desc text;
  v_form text;
  v_new_id uuid;
  v_ids uuid[] := ARRAY[]::uuid[];
  v_count int := 0;
  v_idx int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT company_id INTO v_company_id FROM events WHERE id = _event_id;
  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Event % not found', _event_id USING ERRCODE = 'P0002';
  END IF;

  -- Quem escreve no BP é quem tem a permissão manage_bp NA EMPRESA DO EVENTO
  -- (has_permission_in, não has_permission — esta usa current_company_id()).
  v_can_edit := public.is_platform_admin()
             OR public.has_permission_in(v_caller, 'manage_bp', v_company_id);

  IF NOT v_can_edit THEN
    SELECT (
      public.has_permission(v_caller, 'edit_approved_bp')
      AND EXISTS (
        SELECT 1 FROM public.partner_event_access pea
        WHERE pea.user_id = v_caller
          AND pea.is_active = true
          AND pea.can_edit_bp = true
          AND (
            pea.event_id = _event_id
            OR pea.event_id IN (SELECT id FROM events WHERE parent_event_id = _event_id)
            OR _event_id IN (SELECT id FROM events WHERE parent_event_id = pea.event_id)
          )
      )
    ) INTO v_is_partner_editor;
    v_can_edit := v_is_partner_editor;
  END IF;

  IF NOT v_can_edit THEN
    RAISE EXCEPTION 'Insufficient permission to edit BP' USING ERRCODE = '42501';
  END IF;


  -- #297: só se escreve na linha viva (_version_id NULL) ou num cenário working_draft.
  IF _version_id IS NOT NULL THEN
    PERFORM 1 FROM public.bp_versions bv WHERE bv.id = _version_id AND bv.state = 'working_draft';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Esta versão do Business Plan está congelada (só cenários em rascunho são editáveis).' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _inserts IS NULL OR jsonb_array_length(_inserts) = 0 THEN
    RETURN jsonb_build_object('inserted', 0, 'ids', '[]'::jsonb);
  END IF;

  FOR v_ins IN SELECT * FROM jsonb_array_elements(_inserts) LOOP
    v_idx := v_idx + 1;

    v_type := lower(coalesce(v_ins->>'type', ''));
    IF v_is_partner_editor AND v_type <> 'expense' THEN
      RAISE EXCEPTION 'Linha %: parceiros só podem criar linhas de despesa', v_idx USING ERRCODE = '42501';
    END IF;
    IF v_type NOT IN ('income', 'expense') THEN
      RAISE EXCEPTION 'Linha %: tipo inválido (%)', v_idx, v_type;
    END IF;

    v_desc := trim(coalesce(v_ins->>'description', ''));
    IF length(v_desc) = 0 THEN
      RAISE EXCEPTION 'Linha %: descrição obrigatória', v_idx;
    END IF;

    v_amount := coalesce((v_ins->>'amount')::numeric, 0);
    IF v_amount < 0 THEN
      RAISE EXCEPTION 'Linha %: valor não pode ser negativo', v_idx;
    END IF;

    v_iva := coalesce((v_ins->>'iva_rate')::int, 23);
    IF v_iva NOT IN (0, 6, 13, 23) THEN
      RAISE EXCEPTION 'Linha %: IVA inválido (%)', v_idx, v_iva;
    END IF;

    v_form := coalesce(NULLIF(v_ins->>'formalidade', ''), 'estimado');
    IF v_form NOT IN ('estimado', 'negociacao', 'fechado', 'pago_parcial', 'pago_total') THEN
      RAISE EXCEPTION 'Linha %: formalidade inválida (%)', v_idx, v_form;
    END IF;

    IF (v_ins->>'category_id') IS NOT NULL AND length(v_ins->>'category_id') > 0 THEN
      SELECT id, type, parent_id INTO v_cat
      FROM account_categories
      WHERE id = (v_ins->>'category_id')::uuid
        AND company_id = v_company_id;
      IF v_cat.id IS NULL THEN
        RAISE EXCEPTION 'Linha %: categoria não encontrada', v_idx;
      END IF;
      IF v_cat.type <> v_type THEN
        RAISE EXCEPTION 'Linha %: categoria não corresponde ao tipo (%)', v_idx, v_type;
      END IF;
      IF EXISTS (SELECT 1 FROM account_categories WHERE parent_id = v_cat.id) THEN
        RAISE EXCEPTION 'Linha %: selecione uma categoria L3 (sem filhos)', v_idx;
      END IF;
    END IF;

    INSERT INTO event_forecasts (
      event_id, type, description, specification, amount, iva_rate, category_id,
      notes, formalidade, company_id, version_id,
      is_overhead, exclude_from_result, ordering_partner_id, paying_partner_id, status
    ) VALUES (
      _event_id,
      v_type,
      v_desc,
      NULLIF(v_ins->>'specification', ''),
      v_amount,
      v_iva,
      NULLIF(v_ins->>'category_id', '')::uuid,
      NULLIF(v_ins->>'notes', ''),
      v_form::bp_formalidade,
      v_company_id,
      _version_id,
      false,
      false,
      CASE WHEN v_type = 'expense' THEN NULLIF(v_ins->>'ordering_partner_id', '')::uuid ELSE NULL END,
      CASE WHEN v_type = 'expense' THEN NULLIF(v_ins->>'paying_partner_id', '')::uuid ELSE NULL END,
      'draft'
    ) RETURNING id INTO v_new_id;

    v_ids := array_append(v_ids, v_new_id);
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('inserted', v_count, 'ids', to_jsonb(v_ids));
END;
$function$

CREATE OR REPLACE FUNCTION public.calibrate_forecast_boost(p_event_id uuid, p_window_days integer DEFAULT 30)
 RETURNS TABLE(event_id uuid, event_name text, event_date date, window_days integer, total_qty bigint, first_sale_date date, last_sale_date date, base_window_days integer, base_qty bigint, base_velocity numeric, final_qty bigint, final_velocity numeric, observed_boost numeric, warning text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_date date;
  v_event_name text;
  v_first_sale date;
  v_last_sale date;
  v_window int := GREATEST(1, COALESCE(p_window_days, 30));
  v_cutoff date;
  v_total bigint := 0;
  v_base_qty bigint := 0;
  v_final_qty bigint := 0;
  v_base_days int := 0;
  v_base_vel numeric := 0;
  v_final_vel numeric := 0;
  v_boost numeric := NULL;
  v_warn text := NULL;
BEGIN
  SELECT e.date, e.name INTO v_event_date, v_event_name
  FROM public.events e WHERE e.id = p_event_id;

  IF v_event_date IS NULL THEN
    v_warn := 'Evento não tem data definida';
  END IF;

  SELECT MIN(ts.sale_date), MAX(ts.sale_date), COALESCE(SUM(ts.quantity), 0)
    INTO v_first_sale, v_last_sale, v_total
  FROM public.ticket_sales ts
  JOIN public.event_ticket_lots l ON l.id = ts.lot_id
  JOIN public.event_ticket_zones z ON z.id = l.zone_id
  WHERE z.event_id = p_event_id AND ts.sale_date IS NOT NULL;

  IF v_total = 0 THEN
    RETURN QUERY SELECT p_event_id, v_event_name, v_event_date, v_window,
      0::bigint, NULL::date, NULL::date, 0, 0::bigint, 0::numeric,
      0::bigint, 0::numeric, NULL::numeric,
      'Sem vendas datadas para este evento'::text;
    RETURN;
  END IF;

  -- Reta final = últimos v_window dias contados a partir da última venda registada
  -- (ou data do evento, se for anterior à última venda — improvável mas defensivo)
  v_cutoff := COALESCE(v_event_date, v_last_sale) - v_window;

  SELECT COALESCE(SUM(ts.quantity), 0)
    INTO v_final_qty
  FROM public.ticket_sales ts
  JOIN public.event_ticket_lots l ON l.id = ts.lot_id
  JOIN public.event_ticket_zones z ON z.id = l.zone_id
  WHERE z.event_id = p_event_id
    AND ts.sale_date IS NOT NULL
    AND ts.sale_date > v_cutoff;

  SELECT COALESCE(SUM(ts.quantity), 0)
    INTO v_base_qty
  FROM public.ticket_sales ts
  JOIN public.event_ticket_lots l ON l.id = ts.lot_id
  JOIN public.event_ticket_zones z ON z.id = l.zone_id
  WHERE z.event_id = p_event_id
    AND ts.sale_date IS NOT NULL
    AND ts.sale_date <= v_cutoff;

  v_base_days := GREATEST(1, (v_cutoff - v_first_sale)::int);
  v_final_vel := v_final_qty::numeric / v_window::numeric;
  v_base_vel  := v_base_qty::numeric  / v_base_days::numeric;

  IF v_base_vel > 0 THEN
    v_boost := ROUND(v_final_vel / v_base_vel, 3);
  ELSE
    v_warn := COALESCE(v_warn || ' · ', '') || 'Sem vendas antes da reta final — boost indeterminado';
  END IF;

  IF v_first_sale > COALESCE(v_event_date, v_last_sale) - v_window THEN
    v_warn := COALESCE(v_warn || ' · ', '')
           || 'Janela de venda mais curta que a reta final — boost pouco fiável';
  END IF;

  RETURN QUERY SELECT
    p_event_id, v_event_name, v_event_date, v_window,
    v_total, v_first_sale, v_last_sale,
    v_base_days, v_base_qty, ROUND(v_base_vel, 3),
    v_final_qty, ROUND(v_final_vel, 3),
    v_boost, v_warn;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_partner_total_percentage()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE total numeric;
BEGIN
  SELECT COALESCE(SUM(percentage), 0) INTO total
  FROM public.event_partners
  WHERE event_id = NEW.event_id AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  total := total + NEW.percentage;
  IF total > 100 THEN
    RAISE EXCEPTION 'Total percentage exceeds 100: %', total;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_ticket_type_for_lot(p_lot_name text, p_zone_id uuid, p_is_combo boolean, p_consumes_zones uuid[], p_applies_to_days integer, p_version_id uuid)
 RETURNS TABLE(base_name text, is_real_combo boolean, zone_signature uuid[], proposed_type_name text, proposed_kind text, found_type_id uuid, warnings text[])
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id UUID; v_zone_name TEXT; v_session_label TEXT;
  v_base_name TEXT; v_is_real_combo BOOLEAN; v_zone_signature UUID[];
  v_kind TEXT; v_proposed_name TEXT;
  v_existing_with_name INT; v_existing_with_name_zone INT;
  v_found_id UUID; v_warnings TEXT[] := ARRAY[]::TEXT[];
BEGIN
  SELECT z.event_id, z.name, s.label INTO v_event_id, v_zone_name, v_session_label
  FROM public.event_ticket_zones z
  LEFT JOIN public.event_sessions s ON s.id = z.session_id
  WHERE z.id = p_zone_id;

  IF v_event_id IS NULL THEN
    v_warnings := array_append(v_warnings, 'orphan_zone:' || COALESCE(p_zone_id::text,'null'));
    RETURN QUERY SELECT NULL::TEXT, NULL::BOOLEAN, NULL::UUID[], NULL::TEXT, NULL::TEXT, NULL::UUID, v_warnings;
    RETURN;
  END IF;

  v_base_name := TRIM(REGEXP_REPLACE(REGEXP_REPLACE(
    CASE WHEN p_lot_name ~* '\s\|\s' THEN SPLIT_PART(p_lot_name, '|', 2) ELSE p_lot_name END,
    '\s*-\s*[Ll]ote\s*\d+\s*$', '', 'g'), '\s+', ' ', 'g'));

  v_is_real_combo := COALESCE(p_is_combo, false)
                     AND p_consumes_zones IS NOT NULL
                     AND cardinality(p_consumes_zones) >= 2;

  IF v_is_real_combo THEN
    SELECT array_agg(zid ORDER BY zid::text) INTO v_zone_signature FROM unnest(p_consumes_zones) zid;
  ELSE
    v_zone_signature := ARRAY[p_zone_id];
  END IF;

  v_kind := CASE
    WHEN v_is_real_combo AND COALESCE(p_applies_to_days, 1) >= 2 THEN 'multi_day_pass'
    ELSE 'single_day' END;

  SELECT count(*) INTO v_existing_with_name
  FROM public.event_ticket_types tt
  WHERE tt.event_id = v_event_id AND tt.name = v_base_name
    AND COALESCE(tt.version_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_version_id, '00000000-0000-0000-0000-000000000000'::uuid);

  SELECT count(*) INTO v_existing_with_name_zone
  FROM public.event_ticket_types tt
  WHERE tt.event_id = v_event_id AND tt.name = (v_base_name || ' — ' || v_zone_name)
    AND COALESCE(tt.version_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_version_id, '00000000-0000-0000-0000-000000000000'::uuid);

  SELECT tt.id INTO v_found_id
  FROM public.event_ticket_types tt
  WHERE tt.event_id = v_event_id
    AND COALESCE(tt.version_id, '00000000-0000-0000-0000-000000000000'::uuid)
        = COALESCE(p_version_id, '00000000-0000-0000-0000-000000000000'::uuid)
    AND (SELECT array_agg(zone_id ORDER BY zone_id::text)
         FROM public.event_ticket_type_zones WHERE ticket_type_id = tt.id) = v_zone_signature
    AND (tt.name = v_base_name
         OR tt.name = (v_base_name || ' — ' || v_zone_name)
         OR tt.name = (v_base_name || ' — ' || v_zone_name || ' (' || COALESCE(v_session_label,'') || ')'))
  ORDER BY CASE WHEN tt.name = v_base_name THEN 0
                WHEN tt.name = (v_base_name || ' — ' || v_zone_name) THEN 1
                ELSE 2 END
  LIMIT 1;

  IF v_found_id IS NULL THEN
    IF v_existing_with_name = 0 THEN
      v_proposed_name := v_base_name;
    ELSIF v_existing_with_name_zone = 0 THEN
      v_proposed_name := v_base_name || ' — ' || v_zone_name;
    ELSE
      v_proposed_name := v_base_name || ' — ' || v_zone_name
                       || COALESCE(' (' || v_session_label || ')', '');
    END IF;
  ELSE
    v_proposed_name := (SELECT name FROM public.event_ticket_types WHERE id = v_found_id);
  END IF;

  IF p_consumes_zones IS NOT NULL AND cardinality(p_consumes_zones) > 0
     AND NOT (p_zone_id = ANY(p_consumes_zones)) THEN
    v_warnings := array_append(v_warnings, 'consumes_does_not_include_anchor');
  END IF;
  IF COALESCE(p_is_combo, false) AND (p_consumes_zones IS NULL OR cardinality(p_consumes_zones) = 0) THEN
    v_warnings := array_append(v_warnings, 'combo_with_empty_consumes');
  END IF;

  RETURN QUERY SELECT v_base_name, v_is_real_combo, v_zone_signature,
    v_proposed_name, v_kind, v_found_id, v_warnings;
END $function$

CREATE OR REPLACE FUNCTION public.create_card_session_load(p_session_id uuid, p_amount numeric, p_load_date date, p_source_account_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sess public.card_sessions%ROWTYPE;
  v_src_name TEXT;
  v_card_name TEXT;
  v_cat_id UUID;
  v_out_id UUID;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'Valor da carga inválido.';
  END IF;
  IF p_source_account_id IS NULL THEN
    RAISE EXCEPTION 'Conta de origem obrigatória.';
  END IF;

  SELECT * INTO v_sess FROM public.card_sessions WHERE id = p_session_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sessão de cartão não encontrada.';
  END IF;
  IF v_sess.company_id IS NULL THEN
    RAISE EXCEPTION 'Sessão de cartão sem empresa associada.';
  END IF;
  IF v_sess.status = 'closed' THEN
    RAISE EXCEPTION 'Sessão fechada: não aceita novas recargas.';
  END IF;

  SELECT name INTO v_src_name  FROM public.financial_accounts WHERE id = p_source_account_id;
  SELECT name INTO v_card_name FROM public.financial_accounts WHERE id = v_sess.card_account_id;

  SELECT id INTO v_cat_id
    FROM public.account_categories
   WHERE code = '10.3'
     AND (company_id IS NULL OR company_id = v_sess.company_id)
   ORDER BY (company_id IS NULL)
   LIMIT 1;
  IF v_cat_id IS NULL THEN
    RAISE EXCEPTION 'Rubrica 10.3 (transferências entre contas) não encontrada.';
  END IF;

  INSERT INTO public.transactions (
    company_id, type, description, amount, iva_rate, date, status,
    is_transitory, transitory_reason, exclude_from_result, category_id, account_id
  ) VALUES (
    v_sess.company_id, 'expense',
    'Carga cartão — ' || COALESCE(v_card_name, 'cartão') || ' (' || COALESCE(v_src_name, 'origem') || ' → ' || COALESCE(v_card_name, 'cartão') || ')',
    p_amount, 0, p_load_date, 'pending',
    true, 'carga_cartao', true, v_cat_id, p_source_account_id
  )
  RETURNING id INTO v_out_id;

  INSERT INTO public.card_session_loads (
    company_id, session_id, amount, load_date, source_account_id,
    out_transaction_id, in_transaction_id, notes, created_by
  ) VALUES (
    v_sess.company_id, p_session_id, p_amount, p_load_date, p_source_account_id,
    v_out_id, NULL, NULLIF(btrim(COALESCE(p_notes, '')), ''), auth.uid()
  );

  RETURN v_out_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_registro_with_media(p_registro jsonb, p_media jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_registro_id uuid;
  v_company_id  uuid;
BEGIN
  IF p_registro IS NULL THEN
    RAISE EXCEPTION 'p_registro is required' USING ERRCODE = '22023';
  END IF;
  IF (p_registro->>'company_id') IS NULL THEN
    RAISE EXCEPTION 'company_id is required' USING ERRCODE = '22023';
  END IF;
  IF (p_registro->>'frente_id') IS NULL THEN
    RAISE EXCEPTION 'frente_id is required' USING ERRCODE = '22023';
  END IF;
  IF (p_registro->>'author_profile_id') IS NULL THEN
    RAISE EXCEPTION 'author_profile_id is required' USING ERRCODE = '22023';
  END IF;
  IF (p_registro->>'kind') IS NULL THEN
    RAISE EXCEPTION 'kind is required' USING ERRCODE = '22023';
  END IF;

  v_company_id := (p_registro->>'company_id')::uuid;

  INSERT INTO operacao_registros (
    id, frente_id, etapa_id, author_profile_id, company_id,
    kind, text, audio_url, metadata
  )
  VALUES (
    COALESCE(NULLIF(p_registro->>'id','')::uuid, gen_random_uuid()),
    (p_registro->>'frente_id')::uuid,
    NULLIF(p_registro->>'etapa_id','')::uuid,
    (p_registro->>'author_profile_id')::uuid,
    v_company_id,
    p_registro->>'kind',
    NULLIF(p_registro->>'text',''),
    NULLIF(p_registro->>'audio_url',''),
    COALESCE(p_registro->'metadata', '{}'::jsonb)
  )
  RETURNING id INTO v_registro_id;

  IF p_media IS NOT NULL AND jsonb_array_length(p_media) > 0 THEN
    INSERT INTO operacao_registro_media (
      registro_id, company_id, file_url, thumbnail_url, file_type, sort_order
    )
    SELECT
      v_registro_id,
      v_company_id,
      m->>'file_url',
      NULLIF(m->>'thumbnail_url',''),
      m->>'file_type',
      COALESCE((m->>'sort_order')::int, (ord - 1)::int)
    FROM jsonb_array_elements(p_media) WITH ORDINALITY AS arr(m, ord);
  END IF;

  RETURN v_registro_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.current_company_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_active uuid;
  v_company uuid;
  v_is_pa boolean;
  v_has_active_membership boolean := false;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;

  SELECT active_company_id, company_id INTO v_active, v_company
    FROM public.profiles WHERE id = v_uid;

  SELECT EXISTS(SELECT 1 FROM public.user_roles
    WHERE user_id = v_uid AND role = 'platform_admin'::app_role) INTO v_is_pa;

  -- 1) active_company_id válido (platform_admin OU user tem membership lá)
  IF v_active IS NOT NULL THEN
    IF v_is_pa THEN
      RETURN v_active;
    END IF;
    SELECT EXISTS(SELECT 1 FROM public.user_roles
      WHERE user_id = v_uid AND company_id = v_active) INTO v_has_active_membership;
    IF v_has_active_membership THEN RETURN v_active; END IF;
  END IF;

  -- 2) fallback: profiles.company_id se ainda tem membership lá
  IF v_company IS NOT NULL THEN
    IF v_is_pa OR EXISTS(SELECT 1 FROM public.user_roles
        WHERE user_id = v_uid AND company_id = v_company) THEN
      RETURN v_company;
    END IF;
  END IF;

  -- 3) fallback: primeira empresa onde tem membership
  RETURN (SELECT ur.company_id FROM public.user_roles ur
    JOIN public.companies c ON c.id = ur.company_id
    WHERE ur.user_id = v_uid AND c.status='active'
    ORDER BY ur.id LIMIT 1);
END;
$function$

