CREATE OR REPLACE FUNCTION public.generate_reimbursement_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  current_year text;
  next_seq integer;
BEGIN
  current_year := EXTRACT(YEAR FROM now())::text;
  SELECT COALESCE(MAX(
    CAST(SPLIT_PART(SPLIT_PART(code, '-', 2), '/', 1) AS integer)
  ), 0) + 1
  INTO next_seq
  FROM public.reimbursement_notes
  WHERE code LIKE 'R-%/' || current_year;

  NEW.code := 'R-' || LPAD(next_seq::text, 3, '0') || '/' || current_year;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_sealed_event_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_parent_sealed boolean; v_seal_op boolean;
BEGIN
  v_seal_op := COALESCE(current_setting('app.settlement_seal_op', true), '') = 'on';

  IF TG_OP = 'INSERT' THEN
    IF NEW.parent_id IS NOT NULL THEN
      SELECT is_sealed INTO v_parent_sealed FROM public.event_settlements WHERE id = NEW.parent_id;
      IF COALESCE(v_parent_sealed, false) THEN
        RAISE EXCEPTION 'Fechamento selado: não é possível criar fechamentos dependentes dele';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.is_sealed THEN
      RAISE EXCEPTION 'Fechamento selado: não é possível apagar. Reabra primeiro.';
    END IF;
    RETURN OLD;
  END IF;

  IF NOT v_seal_op AND (
       NEW.is_sealed IS DISTINCT FROM OLD.is_sealed
    OR NEW.sealed_at IS DISTINCT FROM OLD.sealed_at
    OR NEW.sealed_by IS DISTINCT FROM OLD.sealed_by
    OR NEW.sealed_bp_version_id IS DISTINCT FROM OLD.sealed_bp_version_id
    OR NEW.sealed_snapshot IS DISTINCT FROM OLD.sealed_snapshot
    OR NEW.seal_note IS DISTINCT FROM OLD.seal_note
    OR NEW.unsealed_at IS DISTINCT FROM OLD.unsealed_at
    OR NEW.unsealed_by IS DISTINCT FROM OLD.unsealed_by
    OR NEW.unseal_reason IS DISTINCT FROM OLD.unseal_reason
  ) THEN
    RAISE EXCEPTION 'O selo só se altera por selar/reabrir';
  END IF;

  IF OLD.is_sealed AND NOT v_seal_op AND (
       NEW.name IS DISTINCT FROM OLD.name
    OR NEW.parent_id IS DISTINCT FROM OLD.parent_id
    OR NEW.parent_share_pct IS DISTINCT FROM OLD.parent_share_pct
    OR NEW.parent_share_basis IS DISTINCT FROM OLD.parent_share_basis
  ) THEN
    RAISE EXCEPTION 'Fechamento selado: nome e quota não podem ser alterados. Reabra primeiro.';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_camarim_split_child_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  parent_still_exists boolean;
BEGIN
  -- Só nos interessa quando estamos a apagar uma linha-filha
  IF OLD.parent_item_id IS NULL THEN
    RETURN OLD;
  END IF;

  -- Se o pai ainda existe na BD neste momento, é uma tentativa de apagar
  -- a filha isoladamente. Se não existe, é cascade do DELETE do pai → permitir.
  SELECT EXISTS (
    SELECT 1 FROM public.camarim_items WHERE id = OLD.parent_item_id
  ) INTO parent_still_exists;

  IF parent_still_exists THEN
    RAISE EXCEPTION 'Não é possível eliminar uma linha-filha de um talão dividido isoladamente. Use "Redividir" no talão-mãe para ajustar a divisão, ou elimine o talão-mãe (apaga todas as linhas).';
  END IF;

  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_delete_event_settlement_with_lines()
