CREATE OR REPLACE FUNCTION public.prevent_event_partner_role_disable_if_used()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
  v_name text;
BEGIN
  IF OLD.can_order = true AND NEW.can_order = false THEN
    SELECT count(*) INTO v_count
      FROM public.event_forecasts
     WHERE ordering_partner_id = OLD.id;
    IF v_count > 0 THEN
      SELECT COALESCE(s.name, 'Sócio') INTO v_name
        FROM public.event_partners ep
        LEFT JOIN public.suppliers s ON s.id = ep.supplier_id
       WHERE ep.id = OLD.id;
      RAISE EXCEPTION 'Não é possível desligar "Pode ser ordenador de despesas" para "%": existem % linha(s) do BP a usar este sócio como Ordenador.', v_name, v_count USING ERRCODE = '23514';
    END IF;
  END IF;

  IF OLD.can_pay = true AND NEW.can_pay = false THEN
    SELECT count(*) INTO v_count
      FROM public.event_forecasts
     WHERE paying_partner_id = OLD.id;
    IF v_count > 0 THEN
      SELECT COALESCE(s.name, 'Sócio') INTO v_name
        FROM public.event_partners ep
        LEFT JOIN public.suppliers s ON s.id = ep.supplier_id
       WHERE ep.id = OLD.id;
      RAISE EXCEPTION 'Não é possível desligar "Pode ser pagador de despesas" para "%": existem % linha(s) do BP a usar este sócio como Pagador.', v_name, v_count USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_master_split_forecast_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  has_split_children boolean := false;
  has_child_transactions boolean := false;
begin
  if tg_op <> 'UPDATE' then
    return new;
  end if;

  if old.type <> 'expense' then
    return new;
  end if;

  if old.transaction_id is null or new.transaction_id is not distinct from old.transaction_id then
    return new;
  end if;

  select exists (
    select 1
    from public.events se
    where se.parent_event_id = old.event_id
  ) into has_split_children;

  if not has_split_children then
    return new;
  end if;

  select exists (
    select 1
    from public.transactions t
    join public.events se on se.id = t.event_id
    where se.parent_event_id = old.event_id
      and t.parent_transaction_id = old.transaction_id
  ) into has_child_transactions;

  if has_child_transactions then
    raise exception 'Não é permitido alterar/remover transaction_id de um BP Master com transações-filhas vinculadas nos subeventos';
  end if;

  return new;
end;
$function$

