CREATE OR REPLACE FUNCTION public.tickets_v2_sync_lot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id     UUID;
  v_event_id       UUID;
  v_sync_mode      TEXT;
  v_feature_v2     BOOLEAN;
  v_compute        RECORD;
  v_action         TEXT;
  v_matched_via    TEXT;
  v_lot_row        public.event_ticket_lots;
  v_zone_id        UUID;
  v_new_type_id    UUID;
  v_zone_company_id UUID;
BEGIN
  -- DELETE: trabalho mínimo, registar e sair
  IF TG_OP = 'DELETE' THEN
    -- A zona pode já ter sido apagada (cascade). O lote sabe sempre a empresa.
    SELECT z.event_id, z.company_id INTO v_event_id, v_zone_company_id
    FROM public.event_ticket_zones z WHERE z.id = OLD.zone_id;

    v_company_id := COALESCE(OLD.company_id, v_zone_company_id);

    v_sync_mode := COALESCE(
      (SELECT c.tickets_config -> 'sync_mode' #>> '{}'
         FROM public.companies c WHERE c.id = v_company_id),
      'log_only');

    IF v_sync_mode = 'off' THEN
      RETURN OLD;
    END IF;

    INSERT INTO public.tickets_v2_sync_log (
      operation, trigger_action, lot_id, event_id, company_id,
      sync_mode, context
    ) VALUES (
      'DELETE', 'would_unlink', OLD.id, v_event_id, v_company_id, v_sync_mode,
      jsonb_build_object(
        'old_ticket_type_id', OLD.ticket_type_id,
        'old_zone_id', OLD.zone_id,
        'old_name', OLD.name
      )
    );
    RETURN OLD;
  END IF;

  -- INSERT/UPDATE: usar NEW
  v_lot_row := NEW;

  -- 1) Resolver company_id e sync_mode
  SELECT z.event_id, z.company_id INTO v_event_id, v_company_id
  FROM public.event_ticket_zones z
  WHERE z.id = NEW.zone_id;

  IF v_company_id IS NULL THEN
    INSERT INTO public.tickets_v2_sync_log (
      operation, trigger_action, lot_id, event_id, company_id,
      warnings, sync_mode, context
    ) VALUES (
      TG_OP, 'would_warn_orphan', NEW.id, v_event_id, NULL,
      ARRAY['cannot_resolve_company'], 'log_only',
      jsonb_build_object('zone_id', NEW.zone_id)
    );
    RETURN NEW;
  END IF;

  SELECT
    COALESCE(c.tickets_config -> 'sync_mode' #>> '{}', 'log_only'),
    COALESCE(c.feature_tickets_v2, false)
  INTO v_sync_mode, v_feature_v2
  FROM public.companies c WHERE c.id = v_company_id;

  -- Escape hatch
  IF v_sync_mode = 'off' THEN
    RETURN NEW;
  END IF;

  -- 2) Se NEW.ticket_type_id já vem preenchido pela aplicação, validar e respeitar
  IF NEW.ticket_type_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.event_ticket_types tt
      WHERE tt.id = NEW.ticket_type_id AND tt.event_id = v_event_id
    ) THEN
      INSERT INTO public.tickets_v2_sync_log (
        operation, trigger_action, lot_id, event_id, company_id,
        proposed_type_id, warnings, sync_mode, context
      ) VALUES (
        TG_OP, 'would_warn_invalid_type', NEW.id, v_event_id, v_company_id,
        NEW.ticket_type_id,
        ARRAY['ticket_type_id_not_in_event_or_missing'],
        v_sync_mode,
        jsonb_build_object('lot', to_jsonb(NEW))
      );
      IF v_sync_mode = 'active' THEN
        RAISE EXCEPTION 'tickets_v2: ticket_type_id % não pertence ao evento %',
          NEW.ticket_type_id, v_event_id;
      END IF;
    ELSE
      INSERT INTO public.tickets_v2_sync_log (
        operation, trigger_action, lot_id, event_id, company_id,
        proposed_type_id, matched_via, sync_mode, context
      ) VALUES (
        TG_OP, 'would_skip_explicit_id', NEW.id, v_event_id, v_company_id,
        NEW.ticket_type_id, 'preserved_existing', v_sync_mode,
        jsonb_build_object('lot_name', NEW.name)
      );
    END IF;
    RETURN NEW;
  END IF;

  -- 3) Não veio ticket_type_id → aplicar heurística
  SELECT * INTO v_compute
  FROM public.compute_ticket_type_for_lot(
    NEW.name, NEW.zone_id, NEW.is_combo, NEW.consumes_zone_ids,
    NEW.applies_to_days, NEW.version_id
  );

  IF v_compute.found_type_id IS NOT NULL THEN
    v_action := CASE WHEN v_sync_mode = 'active' THEN 'linked_existing' ELSE 'would_link_existing' END;
    v_matched_via := 'exact_name_signature';

    IF v_sync_mode = 'active' THEN
      NEW.ticket_type_id := v_compute.found_type_id;
    END IF;

  ELSE
    IF v_feature_v2 THEN
      v_action := 'would_warn_missing_type';
      v_compute.warnings := array_append(
        COALESCE(v_compute.warnings, ARRAY[]::TEXT[]),
        'feature_v2_active_but_no_explicit_type'
      );
      IF v_sync_mode = 'active' THEN
        RAISE EXCEPTION
          'tickets_v2: feature_v2 ativo mas ticket_type_id não foi fornecido para lot "%".'
          ' Crie o tipo explicitamente na UI nova ou desactive feature_v2.',
          NEW.name;
      END IF;
    ELSE
      v_action := CASE WHEN v_sync_mode = 'active' THEN 'created_type' ELSE 'would_create_type' END;
      v_matched_via := 'created_new';

      IF v_sync_mode = 'active' THEN
        INSERT INTO public.event_ticket_types (
          event_id, company_id, name, kind,
          entries_per_unit, max_total_quantity,
          parent_ticket_type_id, variant_kind, variant_label,
          visibility, version_id
        ) VALUES (
          v_event_id, v_company_id, v_compute.proposed_type_name, v_compute.proposed_kind,
          1, NULL,
          NULL, NULL, NULL,
          'public', NEW.version_id
        )
        ON CONFLICT (event_id, name, COALESCE(version_id, '00000000-0000-0000-0000-000000000000'::uuid))
        DO UPDATE SET name = EXCLUDED.name
        RETURNING id INTO v_new_type_id;

        FOREACH v_zone_id IN ARRAY v_compute.zone_signature LOOP
          INSERT INTO public.event_ticket_type_zones (
            ticket_type_id, zone_id, display_order, price_share, company_id
          ) VALUES (
            v_new_type_id, v_zone_id, 0, NULL, v_company_id
          )
          ON CONFLICT (ticket_type_id, zone_id) DO NOTHING;
        END LOOP;

        NEW.ticket_type_id := v_new_type_id;
      END IF;
    END IF;
  END IF;

  -- 4) Registar no log
  INSERT INTO public.tickets_v2_sync_log (
    operation, trigger_action, lot_id, event_id, company_id,
    proposed_type_id, proposed_type_name, proposed_zone_signature,
    matched_via, warnings, sync_mode, context
  ) VALUES (
    TG_OP, v_action, NEW.id, v_event_id, v_company_id,
    COALESCE(NEW.ticket_type_id, v_compute.found_type_id),
    v_compute.proposed_type_name, v_compute.zone_signature,
    v_matched_via,
    NULLIF(v_compute.warnings, ARRAY[]::TEXT[]),
    v_sync_mode,
    jsonb_build_object(
      'lot_name', NEW.name,
      'is_combo', NEW.is_combo,
      'consumes_zone_ids', NEW.consumes_zone_ids,
      'applies_to_days', NEW.applies_to_days,
      'base_name_extracted', v_compute.base_name,
      'is_real_combo', v_compute.is_real_combo,
      'proposed_kind', v_compute.proposed_kind,
      'feature_tickets_v2', v_feature_v2,
      'created_new_type_id', v_new_type_id
    )
  );

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_operacao_set_sla()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_mins int;
BEGIN
  IF NEW.kind='chamado' AND NEW.priority IS NOT NULL THEN
    SELECT sla_minutes INTO v_mins FROM public.operacao_chamado_sla WHERE priority=NEW.priority;
    IF v_mins IS NOT NULL THEN
      NEW.sla_due_at := COALESCE(NEW.created_at, now()) + (v_mins * interval '1 minute');
      NEW.sla_half_at := COALESCE(NEW.created_at, now()) + ((v_mins/2.0) * interval '1 minute');
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_forecast_partner_roles()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_parent_id uuid;
  v_partner record;
BEGIN
  IF NEW.ordering_partner_id IS NOT NULL THEN
    SELECT ep.id, ep.event_id, ep.can_order, s.name AS supplier_name
      INTO v_partner
      FROM public.event_partners ep
      LEFT JOIN public.suppliers s ON s.id = ep.supplier_id
     WHERE ep.id = NEW.ordering_partner_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ordenador inválido: sócio não encontrado.' USING ERRCODE = '23503';
    END IF;

    SELECT parent_event_id INTO v_event_parent_id
      FROM public.events
     WHERE id = NEW.event_id;

    IF v_partner.event_id <> NEW.event_id AND v_partner.event_id IS DISTINCT FROM v_event_parent_id THEN
      RAISE EXCEPTION 'Ordenador inválido: o sócio "%" pertence a outro evento.', COALESCE(v_partner.supplier_name, 'Sócio') USING ERRCODE = '23514';
    END IF;

    IF NOT COALESCE(v_partner.can_order, false) THEN
      RAISE EXCEPTION 'Ordenador inválido: o sócio "%" não tem a opção "Pode ser ordenador de despesas" ligada.', COALESCE(v_partner.supplier_name, 'Sócio') USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.paying_partner_id IS NOT NULL THEN
    SELECT ep.id, ep.event_id, ep.can_pay, s.name AS supplier_name
      INTO v_partner
      FROM public.event_partners ep
      LEFT JOIN public.suppliers s ON s.id = ep.supplier_id
     WHERE ep.id = NEW.paying_partner_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Pagador inválido: sócio não encontrado.' USING ERRCODE = '23503';
    END IF;

    SELECT parent_event_id INTO v_event_parent_id
      FROM public.events
     WHERE id = NEW.event_id;

    IF v_partner.event_id <> NEW.event_id AND v_partner.event_id IS DISTINCT FROM v_event_parent_id THEN
      RAISE EXCEPTION 'Pagador inválido: o sócio "%" pertence a outro evento.', COALESCE(v_partner.supplier_name, 'Sócio') USING ERRCODE = '23514';
    END IF;

    IF NOT COALESCE(v_partner.can_pay, false) THEN
      RAISE EXCEPTION 'Pagador inválido: o sócio "%" não tem a opção "Pode ser pagador de despesas" ligada.', COALESCE(v_partner.supplier_name, 'Sócio') USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_ticket_lot_applies_to_days()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.applies_to_days IS NULL OR NEW.applies_to_days < 1 OR NEW.applies_to_days > 31 THEN
    RAISE EXCEPTION 'applies_to_days must be between 1 and 31';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_forecast_addback()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settlement_event uuid;
  v_parent uuid;
  v_sealed boolean;
BEGIN
  IF NEW.addback_settlement_id IS NULL THEN
    NEW.addback_reason := NULL;
    RETURN NEW;
  END IF;

  IF lower(coalesce(NEW.type, '')) <> 'expense' THEN
    RAISE EXCEPTION 'Só linhas de despesa podem ser devolvidas a um fechamento.';
  END IF;

  IF NEW.addback_reason IS NULL OR btrim(NEW.addback_reason) = '' THEN
    RAISE EXCEPTION 'Indique o motivo da devolução da linha ao fechamento.';
  END IF;

  SELECT s.event_id, s.parent_id, coalesce(s.is_sealed, false)
    INTO v_settlement_event, v_parent, v_sealed
  FROM public.event_settlements s
  WHERE s.id = NEW.addback_settlement_id;

  IF v_settlement_event IS NULL THEN
    RAISE EXCEPTION 'Fechamento de devolução inexistente.';
  END IF;

  IF v_settlement_event <> NEW.event_id THEN
    RAISE EXCEPTION 'O fechamento de devolução tem de pertencer ao mesmo evento da linha.';
  END IF;

  IF v_parent IS NULL THEN
    RAISE EXCEPTION 'Não é possível devolver uma linha ao fechamento raiz.';
  END IF;

  IF v_sealed THEN
    RAISE EXCEPTION 'O fechamento de devolução está selado.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_forecast_event_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_event uuid; v_sealed boolean; v_old_sealed boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.event_settlement_id IS NOT NULL
     AND NEW.event_settlement_id IS DISTINCT FROM OLD.event_settlement_id THEN
    SELECT is_sealed INTO v_old_sealed FROM public.event_settlements WHERE id = OLD.event_settlement_id;
    IF COALESCE(v_old_sealed, false) THEN
      RAISE EXCEPTION 'Fechamento selado: as linhas do BP não podem ser desmarcadas. Reabra primeiro.';
    END IF;
  END IF;

  IF NEW.event_settlement_id IS NULL THEN RETURN NEW; END IF;
  SELECT event_id, is_sealed INTO v_event, v_sealed FROM public.event_settlements WHERE id = NEW.event_settlement_id;
  IF v_event IS NULL THEN
    RAISE EXCEPTION 'Fechamento % não existe', NEW.event_settlement_id;
  END IF;
  IF COALESCE(v_sealed, false) AND (TG_OP = 'INSERT' OR NEW.event_settlement_id IS DISTINCT FROM OLD.event_settlement_id) THEN
    RAISE EXCEPTION 'Fechamento selado: não é possível marcar novas linhas do BP. Reabra primeiro.';
  END IF;
  IF NEW.event_id IS NULL OR NEW.event_id <> v_event THEN
    RAISE EXCEPTION 'A linha do BP só pode ser ligada a um fechamento do próprio evento';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_operation_participation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_op_event uuid; v_st_event uuid; v_sealed boolean;
BEGIN
  SELECT event_id INTO v_op_event FROM public.event_third_party_operations WHERE id = NEW.operation_id;
  SELECT event_id, is_sealed INTO v_st_event, v_sealed FROM public.event_settlements WHERE id = NEW.settlement_id;
  IF v_op_event IS NULL OR v_st_event IS NULL THEN
    RAISE EXCEPTION 'Operação ou fechamento inexistente'; END IF;
  IF v_op_event <> v_st_event OR NEW.event_id <> v_st_event THEN
    RAISE EXCEPTION 'A operação e o fechamento têm de pertencer ao mesmo evento'; END IF;
  IF COALESCE(v_sealed, false) AND COALESCE(current_setting('app.settlement_seal_op', true), '') <> 'on' THEN
    RAISE EXCEPTION 'Fechamento selado: a participação não pode ser alterada. Reabra primeiro.'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_paid_amount_not_exceeds_gross()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gross numeric;
  v_old_gross numeric;
BEGIN
  IF NEW.paid_amount IS NULL THEN
    RETURN NEW;
  END IF;

  v_gross := COALESCE(NEW.amount, 0) * (1 + COALESCE(NEW.iva_rate, 0) / 100.0);

  IF v_gross <= 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.paid_amount > v_gross + 0.01 THEN
    -- Estado legado já excedido: permitir desde que não aumente.
    v_old_gross := COALESCE(OLD.amount, 0) * (1 + COALESCE(OLD.iva_rate, 0) / 100.0);
    IF COALESCE(OLD.paid_amount, 0) > v_old_gross + 0.01
       AND NEW.paid_amount <= COALESCE(OLD.paid_amount, 0) THEN
      RETURN NEW;
    END IF;

    RAISE EXCEPTION 'Valor pago (% €) excede o valor bruto da transação (% €).',
      ROUND(NEW.paid_amount::numeric, 2), ROUND(v_gross::numeric, 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_paid_requires_payment_date()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hoje date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  IF NEW.status = 'paid' AND NEW.payment_date IS NULL THEN
    RAISE EXCEPTION 'Transações pagas devem ter uma data de pagamento (payment_date)';
  END IF;

  IF NEW.payment_date IS NOT NULL AND NEW.payment_date > v_hoje THEN
    RAISE EXCEPTION 'Data de pagamento no futuro (%). Um pagamento regista dinheiro que já saiu — para uma saída prevista use a data de vencimento.', NEW.payment_date;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_settlement_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_event uuid; v_sealed boolean;
BEGIN
  SELECT event_id, is_sealed INTO v_event, v_sealed
    FROM public.event_settlements WHERE id = NEW.settlement_id;
  IF v_event IS NULL THEN RAISE EXCEPTION 'Fechamento % não existe', NEW.settlement_id; END IF;
  IF COALESCE(v_sealed, false) AND COALESCE(current_setting('app.settlement_seal_op', true), '') <> 'on' THEN
    RAISE EXCEPTION 'Fechamento selado: os participantes não podem ser alterados. Reabra primeiro.';
  END IF;
  IF NEW.event_id <> v_event THEN
    RAISE EXCEPTION 'O participante tem de pertencer ao mesmo evento do fechamento'; END IF;
  IF NEW.mode = 'settles' AND NEW.participant_kind = 'partner' THEN
    IF EXISTS (
      SELECT 1 FROM public.event_settlement_participants p
      WHERE p.event_id = NEW.event_id AND p.supplier_id = NEW.supplier_id
        AND p.mode = 'settles' AND p.id <> COALESCE(NEW.id, gen_random_uuid())
    ) THEN
      RAISE EXCEPTION 'Este sócio já é pago por outro fechamento deste evento (só pode haver um "settles")';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_transaction_event_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_event uuid; v_sealed boolean; v_old_sealed boolean;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.event_settlement_id IS NOT NULL
     AND NEW.event_settlement_id IS DISTINCT FROM OLD.event_settlement_id THEN
    SELECT is_sealed INTO v_old_sealed FROM public.event_settlements WHERE id = OLD.event_settlement_id;
    IF COALESCE(v_old_sealed, false) THEN
      RAISE EXCEPTION 'Fechamento selado: as transações não podem ser desmarcadas. Reabra primeiro.';
    END IF;
  END IF;

  IF NEW.event_settlement_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.event_id IS NULL THEN
    RAISE EXCEPTION 'Uma transação sem evento (mãe de rateio) não pode ser ligada a um fechamento';
  END IF;
  SELECT event_id, is_sealed INTO v_event, v_sealed FROM public.event_settlements WHERE id = NEW.event_settlement_id;
  IF v_event IS NULL THEN
    RAISE EXCEPTION 'Fechamento % não existe', NEW.event_settlement_id;
  END IF;
  IF COALESCE(v_sealed, false) AND (TG_OP = 'INSERT' OR NEW.event_settlement_id IS DISTINCT FROM OLD.event_settlement_id) THEN
    RAISE EXCEPTION 'Fechamento selado: não é possível marcar novas transações. Reabra primeiro.';
  END IF;
  IF NEW.event_id <> v_event THEN
    RAISE EXCEPTION 'A transação só pode ser ligada a um fechamento do próprio evento';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._tmp_rollback_probe()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare v jsonb; ctx text;
begin
  begin
    update restore_shadow.public__transactions set currency='XXX' where id=(select id from restore_shadow.public__transactions limit 1);
    update restore_shadow.public__events set name = name || ' CORROMPIDO';
    select public.restore_apply_from_shadow('rows','7c858982-6ccd-47ca-bd65-e0dd3eebf01c',
      array['events','bp_versions','bp_version_audit_log','event_cache_configs','event_cache_deductions','event_simulator_config','transactions','payment_list_items','transaction_payments','transaction_documents','transaction_audit_log','event_forecasts','bank_statement_lines','shared_cost_mirror','partner_aporte_mirror','event_forecast_formalidade_log','forecast_audit_log'],'{}'::jsonb) into v;
    raise exception 'PROBE_OK %', v::text;
  exception when others then
    if sqlerrm like 'PROBE_OK%' then return sqlerrm; end if;
    get stacked diagnostics ctx = PG_EXCEPTION_CONTEXT;
    return 'ERRO ' || sqlstate || ' :: ' || sqlerrm;
  end;
end $function$

CREATE OR REPLACE FUNCTION public.copy_event_tour_content(p_source uuid, p_targets uuid[], p_include_text boolean DEFAULT true, p_include_creatives boolean DEFAULT true, p_include_faqs boolean DEFAULT true, p_include_lineup boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  t uuid;
  src jsonb;
  src_text jsonb;
  src_creatives jsonb := '{}'::jsonb;
  base jsonb;
  merged jsonb;
  v_company uuid;
  creative_keys text[] := array['hero_image_url','poster_vertical_url','og_image_url','hero_video_url','gallery_urls'];
  k text;
  n_marketing int := 0; n_faqs int := 0; n_lineup int := 0; c int;
begin
  if p_include_text or p_include_creatives then
    select to_jsonb(em) - 'id' - 'created_at' - 'updated_at' - 'created_by' - 'updated_by' - 'published_at'
      into src
    from public.event_marketing em where em.event_id = p_source;
    if src is not null then
      src_text := src;
      foreach k in array creative_keys loop
        if src ? k then
          src_creatives := src_creatives || jsonb_build_object(k, src->k);
          src_text := src_text - k;
        end if;
      end loop;
    end if;
  end if;

  foreach t in array coalesce(p_targets, '{}'::uuid[]) loop
    if t = p_source then continue; end if;
    select company_id into v_company from public.events where id = t;

    if src is not null and (p_include_text or p_include_creatives) then
      select to_jsonb(em) - 'id' - 'created_at' - 'updated_at' - 'created_by' - 'updated_by' - 'published_at'
        into base
      from public.event_marketing em where em.event_id = t;
      base := coalesce(base, jsonb_build_object('status','draft'));

      merged := base;
      if p_include_text then merged := merged || src_text; end if;
      if p_include_creatives then merged := merged || src_creatives; end if;
      merged := merged || jsonb_build_object('event_id', t, 'company_id', v_company, 'created_at', now(), 'updated_at', now());

      delete from public.event_marketing where event_id = t;
      insert into public.event_marketing
        select (jsonb_populate_record(null::public.event_marketing, merged)).*;
      n_marketing := n_marketing + 1;
    end if;

    if p_include_faqs then
      delete from public.event_faqs where event_id = t;
      insert into public.event_faqs (company_id, event_id, question_pt, question_en, answer_pt, answer_en, category, display_order)
      select v_company, t, f.question_pt, f.question_en, f.answer_pt, f.answer_en, f.category, f.display_order
      from public.event_faqs f where f.event_id = p_source;
      get diagnostics c = row_count; n_faqs := n_faqs + c;
    end if;

    if p_include_lineup then
      delete from public.event_lineups where event_id = t;
      insert into public.event_lineups (company_id, event_id, artist_name, artist_image_url, artist_bio_pt, artist_bio_en, stage, performance_date, performance_time, display_order)
      select v_company, t, l.artist_name, l.artist_image_url, l.artist_bio_pt, l.artist_bio_en, l.stage, l.performance_date, l.performance_time, l.display_order
      from public.event_lineups l where l.event_id = p_source;
      get diagnostics c = row_count; n_lineup := n_lineup + c;
    end if;
  end loop;

  return jsonb_build_object(
    'targets', array_length(coalesce(p_targets,'{}'::uuid[]),1),
    'marketing_rows', n_marketing, 'faq_rows', n_faqs, 'lineup_rows', n_lineup
  );
end $function$

CREATE OR REPLACE FUNCTION public.publish_event_to_portal(p_event_id uuid)
 RETURNS TABLE(id uuid, name text, slug text, portal_visible boolean)
 LANGUAGE plpgsql
AS $function$
declare v_type text; v_name text; v_slug text; v_mother_slug text; r record; v_city text; v_base text;
begin
  select e.event_type, e.name, e.slug into v_type, v_name, v_slug
  from public.events e where e.id = p_event_id;
  if not found then raise exception 'Evento % não encontrado', p_event_id; end if;

  if v_slug is null or v_slug = '' then
    v_slug := public.unique_event_slug(public.slugify(v_name), p_event_id);
  end if;
  update public.events set slug = v_slug, portal_visible = true where events.id = p_event_id;
  v_mother_slug := v_slug;

  if v_type = 'multi_day' then
    for r in select e.id, e.name, e.slug, e.city_id from public.events e where e.parent_event_id = p_event_id loop
      if r.slug is null or r.slug = '' then
        select c.name into v_city from public.cities c where c.id = r.city_id;
        v_base := v_mother_slug || '-' || public.slugify(coalesce(v_city, r.name));
        update public.events set slug = public.unique_event_slug(v_base, r.id), portal_visible = true where events.id = r.id;
      else
        update public.events set portal_visible = true where events.id = r.id;
      end if;
    end loop;
  end if;

  return query
    select e.id, e.name, e.slug, e.portal_visible
    from public.events e
    where e.id = p_event_id or e.parent_event_id = p_event_id
    order by e.parent_event_id nulls first, e.date;
end $function$

CREATE OR REPLACE FUNCTION public.set_updated_at_blog_posts()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.unique_event_slug(base text, exclude_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare s text := coalesce(base,'evento'); i int := 2;
begin
  if s = '' or s is null then s := 'evento'; end if;
  while exists (
    select 1 from public.events
    where slug = s and id <> coalesce(exclude_id,'00000000-0000-0000-0000-000000000000'::uuid)
  ) loop
    s := base || '-' || i; i := i + 1;
  end loop;
  return s;
end $function$

CREATE OR REPLACE FUNCTION public.unpublish_event_from_portal(p_event_id uuid)
 RETURNS TABLE(id uuid, name text, portal_visible boolean)
 LANGUAGE plpgsql
AS $function$
declare v_type text;
begin
  select e.event_type into v_type from public.events e where e.id = p_event_id;
  if not found then raise exception 'Evento % não encontrado', p_event_id; end if;
  update public.events set portal_visible = false where events.id = p_event_id;
  if v_type = 'multi_day' then
    update public.events set portal_visible = false where events.parent_event_id = p_event_id;
  end if;
  return query
    select e.id, e.name, e.portal_visible
    from public.events e
    where e.id = p_event_id or e.parent_event_id = p_event_id
    order by e.parent_event_id nulls first, e.date;
end $function$

CREATE OR REPLACE FUNCTION public._artist_user_access_sync_modes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.area_modes IS NULL OR NEW.area_modes = '{}'::jsonb
     OR (TG_OP = 'UPDATE' AND NEW.area_modes IS NOT DISTINCT FROM OLD.area_modes
         AND (NEW.areas IS DISTINCT FROM OLD.areas OR NEW.access_level IS DISTINCT FROM OLD.access_level)) THEN
    SELECT coalesce(jsonb_object_agg(ar, CASE WHEN NEW.access_level='traffic_manager' AND ar='traffic' THEN 'edit' ELSE 'view' END), '{}'::jsonb)
      INTO NEW.area_modes
      FROM (SELECT DISTINCT unnest(NEW.areas || CASE WHEN NEW.access_level='traffic_manager' THEN ARRAY['traffic'] ELSE ARRAY[]::text[] END) ar) s;
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_each_text(NEW.area_modes) e
             WHERE e.key <> ALL(ARRAY['overview','channels','traffic','financial','reports','songs','content'])
                OR e.value NOT IN ('view','edit')) THEN
    RAISE EXCEPTION 'area_modes inválido';
  END IF;
  NEW.areas := ARRAY(SELECT jsonb_object_keys(NEW.area_modes));
  NEW.access_level := CASE WHEN NEW.area_modes->>'traffic' = 'edit' THEN 'traffic_manager' ELSE 'viewer' END;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.event_trackers_sync_company()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT e.company_id INTO NEW.company_id FROM public.events e WHERE e.id = NEW.event_id;
  IF NEW.company_id IS NULL THEN RAISE EXCEPTION 'evento % inexistente', NEW.event_id; END IF;
  NEW.tracker_id := btrim(NEW.tracker_id);
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.events_meta_pixel_to_trackers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.meta_pixel_id IS NOT DISTINCT FROM OLD.meta_pixel_id THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.meta_pixel_id IS NOT NULL THEN
    DELETE FROM public.event_trackers WHERE event_id = NEW.id AND platform = 'meta' AND tracker_id = btrim(OLD.meta_pixel_id);
  END IF;
  IF NEW.meta_pixel_id IS NOT NULL AND btrim(NEW.meta_pixel_id) <> '' AND NEW.company_id IS NOT NULL THEN
    INSERT INTO public.event_trackers (company_id, event_id, platform, tracker_id, tracker_metadata)
    VALUES (NEW.company_id, NEW.id, 'meta', btrim(NEW.meta_pixel_id), jsonb_build_object('custom_event_type','PURCHASE','origem','events.meta_pixel_id'))
    ON CONFLICT (event_id, platform, tracker_id) DO UPDATE SET updated_at = now();
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_payment_date_not_future()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hoje date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  IF NEW.payment_date IS NOT NULL AND NEW.payment_date > v_hoje THEN
    RAISE EXCEPTION 'Data de pagamento no futuro (%). Um pagamento regista dinheiro que já saiu — para uma saída prevista use a data de vencimento na transação.', NEW.payment_date;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION graphql_public.graphql("operationName" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_cron_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
    revoke trigger on cron.job_run_details from postgres;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8.0', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
    if not exists (
        select 1
        from pg_catalog.pg_event_trigger_ddl_commands() ev
        join pg_catalog.pg_extension e on ev.objid = e.oid
        where e.extname = 'pg_graphql'
    ) then
        return;
    end if;

    drop function if exists graphql_public.graphql;
    create or replace function graphql_public.graphql(
        "operationName" text default null,
        query text default null,
        variables jsonb default null,
        extensions jsonb default null
    )
        returns jsonb
        language sql
    as $$
        select graphql.resolve(
            query := query,
            variables := coalesce(variables, '{}'),
            "operationName" := "operationName",
            extensions := extensions
        );
    $$;

    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,
    -- which in turn triggers set_graphql_placeholder to reinstall the "not enabled" stub.
    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);

    grant usage on schema graphql to postgres, anon, authenticated, service_role;
    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;
    grant usage on schema graphql to postgres with grant option;
    grant usage on schema graphql_public to postgres with grant option;
end;
$function$

