CREATE OR REPLACE FUNCTION public.artist_ads_campaign_goal_upsert(p_artist_id uuid, p_platform text, p_external_campaign_id text, p_nivel text, p_external_adgroup_id text, p_resultado_nome text, p_meta_tipo text, p_meta_valor numeric, p_moeda text, p_notas text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_company uuid; v_id uuid; v_nivel text := coalesce(nullif(p_nivel,''),'campaign');
BEGIN
  v_company := public.artist_access_check(p_artist_id,'traffic_write',NULL);
  IF nullif(trim(p_external_campaign_id),'') IS NULL THEN RAISE EXCEPTION 'campanha obrigatória' USING ERRCODE='22023'; END IF;
  IF p_meta_valor IS NULL OR p_meta_valor <= 0 THEN RAISE EXCEPTION 'meta_valor tem de ser > 0' USING ERRCODE='22023'; END IF;
  IF v_nivel = 'adgroup' AND nullif(trim(p_external_adgroup_id),'') IS NULL THEN
    RAISE EXCEPTION 'nível adgroup exige external_adgroup_id' USING ERRCODE='22023'; END IF;
  UPDATE public.artist_ads_campaign_goals SET
    resultado_nome = p_resultado_nome, meta_tipo = p_meta_tipo, meta_valor = p_meta_valor,
    moeda = upper(p_moeda), notas = p_notas, origem = 'pedro', artist_id = p_artist_id
  WHERE company_id = v_company AND platform = p_platform AND external_campaign_id = p_external_campaign_id
    AND nivel = v_nivel AND external_adgroup_id IS NOT DISTINCT FROM nullif(trim(p_external_adgroup_id),'')
    AND valido_desde = current_date
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN
    INSERT INTO public.artist_ads_campaign_goals (company_id, artist_id, platform, external_campaign_id, nivel,
      external_adgroup_id, resultado_nome, meta_tipo, meta_valor, moeda, origem, notas)
    VALUES (v_company, p_artist_id, p_platform, p_external_campaign_id, v_nivel,
      nullif(trim(p_external_adgroup_id),''), p_resultado_nome, p_meta_tipo, p_meta_valor, upper(p_moeda), 'pedro', p_notas)
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_plan_validate(p_plan jsonb, p_smart_link text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_obj text; v_link text; v_adsets jsonb; v_a jsonb; v_n int := 0; v_geo jsonb;
  v_pub jsonb; v_k text; v_x jsonb; v_min numeric; v_max numeric; v_pos jsonb;
BEGIN
  IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN
    RAISE EXCEPTION 'plano inválido' USING ERRCODE = '22023';
  END IF;
  v_obj := upper(coalesce(p_plan->>'objetivo',''));
  -- Meta: AWARENESS/TRAFFIC/ENGAGEMENT; TikTok: REACH/VIDEO_VIEWS/TRAFFIC (D-ERP107)
  IF v_obj NOT IN ('AWARENESS','TRAFFIC','ENGAGEMENT','REACH','VIDEO_VIEWS') THEN
    RAISE EXCEPTION 'objetivo inválido: usa AWARENESS, TRAFFIC ou ENGAGEMENT (Meta) ou REACH, VIDEO_VIEWS ou TRAFFIC (TikTok); conversões não são aceites em campanhas de música' USING ERRCODE = '22023';
  END IF;
  v_adsets := p_plan->'adsets';
  IF v_adsets IS NULL OR jsonb_typeof(v_adsets) <> 'array' OR jsonb_array_length(v_adsets) < 1 THEN
    RAISE EXCEPTION 'o plano precisa de pelo menos um conjunto de anúncios' USING ERRCODE = '22023';
  END IF;
  FOR v_a IN SELECT * FROM jsonb_array_elements(v_adsets) LOOP
    v_n := v_n + 1;
    IF coalesce((v_a->>'orcamento_cents')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'conjunto %: orçamento diário tem de ser maior que zero', v_n USING ERRCODE = '22023';
    END IF;
    IF v_a->'anuncios' IS NULL OR jsonb_typeof(v_a->'anuncios') <> 'array'
       OR jsonb_array_length(v_a->'anuncios') < 1 THEN
      RAISE EXCEPTION 'conjunto %: precisa de pelo menos um anúncio', v_n USING ERRCODE = '22023';
    END IF;
    v_geo := v_a->'publico_sugerido'->'geo';
    IF v_geo IS NULL OR jsonb_typeof(v_geo) <> 'array'
       OR NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements_text(v_geo) g
         WHERE btrim(coalesce(g, '')) <> ''
       ) THEN
      RAISE EXCEPTION 'conjunto %: indica pelo menos um país em publico_sugerido.geo (ex.: ["BR"])', v_n USING ERRCODE = '22023';
    END IF;
    v_pub := v_a->'publico_sugerido';
    -- Idade 13–65 (opcional)
    IF v_pub ? 'idade_min' THEN
      IF jsonb_typeof(v_pub->'idade_min') <> 'number' THEN RAISE EXCEPTION 'conjunto %: idade_min tem de ser número', v_n USING ERRCODE='22023'; END IF;
      v_min := (v_pub->>'idade_min')::numeric;
      IF v_min < 13 OR v_min > 65 THEN RAISE EXCEPTION 'conjunto %: idade_min entre 13 e 65', v_n USING ERRCODE='22023'; END IF;
    END IF;
    IF v_pub ? 'idade_max' THEN
      IF jsonb_typeof(v_pub->'idade_max') <> 'number' THEN RAISE EXCEPTION 'conjunto %: idade_max tem de ser número', v_n USING ERRCODE='22023'; END IF;
      v_max := (v_pub->>'idade_max')::numeric;
      IF v_max < 13 OR v_max > 65 THEN RAISE EXCEPTION 'conjunto %: idade_max entre 13 e 65', v_n USING ERRCODE='22023'; END IF;
      IF v_min IS NOT NULL AND v_min > v_max THEN RAISE EXCEPTION 'conjunto %: idade_min maior que idade_max', v_n USING ERRCODE='22023'; END IF;
    END IF;
    v_min := NULL; v_max := NULL;
    -- Listas [{id, nome}] com id numérico
    FOREACH v_k IN ARRAY ARRAY['interesses','publicos_personalizados','publicos_excluidos'] LOOP
      IF v_pub ? v_k THEN
        IF jsonb_typeof(v_pub->v_k) <> 'array' THEN
          RAISE EXCEPTION 'conjunto %: publico_sugerido.% tem de ser lista [{id, nome}]', v_n, v_k USING ERRCODE='22023';
        END IF;
        FOR v_x IN SELECT * FROM jsonb_array_elements(v_pub->v_k) LOOP
          IF jsonb_typeof(v_x) <> 'object' OR coalesce(v_x->>'id','') !~ '^[0-9]+$' THEN
            RAISE EXCEPTION 'conjunto %: publico_sugerido.% com id inválido (%)', v_n, v_k, left(v_x::text, 80) USING ERRCODE='22023';
          END IF;
        END LOOP;
      END IF;
    END LOOP;
    -- Posicionamentos (opcional)
    IF v_pub ? 'posicionamentos' THEN
      v_pos := v_pub->'posicionamentos';
      IF jsonb_typeof(v_pos) <> 'object' THEN RAISE EXCEPTION 'conjunto %: posicionamentos tem de ser objeto', v_n USING ERRCODE='22023'; END IF;
      IF v_pos ? 'publisher_platforms' AND (jsonb_typeof(v_pos->'publisher_platforms') <> 'array' OR EXISTS (
          SELECT 1 FROM jsonb_array_elements_text(v_pos->'publisher_platforms') p
          WHERE p NOT IN ('facebook','instagram','messenger','audience_network','threads'))) THEN
        RAISE EXCEPTION 'conjunto %: publisher_platforms inválido', v_n USING ERRCODE='22023';
      END IF;
      IF v_pos ? 'instagram_positions' AND (jsonb_typeof(v_pos->'instagram_positions') <> 'array' OR EXISTS (
          SELECT 1 FROM jsonb_array_elements_text(v_pos->'instagram_positions') p
          WHERE p NOT IN ('stream','story','explore','explore_home','reels','profile_feed','ig_search','profile_reels'))) THEN
        RAISE EXCEPTION 'conjunto %: instagram_positions inválido', v_n USING ERRCODE='22023';
      END IF;
      IF v_pos ? 'facebook_positions' AND (jsonb_typeof(v_pos->'facebook_positions') <> 'array' OR EXISTS (
          SELECT 1 FROM jsonb_array_elements_text(v_pos->'facebook_positions') p
          WHERE p NOT IN ('feed','right_hand_column','marketplace','video_feeds','story','search','instream_video','facebook_reels','facebook_reels_overlay','profile_feed','notification'))) THEN
        RAISE EXCEPTION 'conjunto %: facebook_positions inválido', v_n USING ERRCODE='22023';
      END IF;
    END IF;
  END LOOP;
  v_link := nullif(btrim(coalesce(p_plan->>'link_destino','')), '');
  IF v_link IS NULL THEN v_link := p_smart_link; END IF;
  IF v_obj = 'TRAFFIC' AND (v_link IS NULL OR v_link !~ '^https://') THEN
    RAISE EXCEPTION 'objetivo Tráfego exige link de destino https:// (no plano ou no smart link da música)' USING ERRCODE = '22023';
  END IF;
  RETURN jsonb_build_object('objetivo', v_obj, 'link_destino', v_link, 'adsets', v_adsets);
END $function$

CREATE OR REPLACE FUNCTION public.artist_audience_set_manual(p_artist_id uuid, p_platform text, p_audience_type text, p_dimension text, p_snapshot_date date, p_rows jsonb, p_timeframe text DEFAULT 'manual'::text, p_note text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_company uuid; v_n integer := 0; v_bad text;
BEGIN
  IF p_platform NOT IN ('tiktok','instagram','youtube','spotify','deezer','apple-music','other') THEN RAISE EXCEPTION 'plataforma inválida: %', p_platform; END IF;
  IF p_audience_type NOT IN ('followers','engaged','reached','listeners') THEN RAISE EXCEPTION 'audience_type inválido: %', p_audience_type; END IF;
  IF p_dimension NOT IN ('age','gender','city','country') THEN RAISE EXCEPTION 'dimensão inválida: %', p_dimension; END IF;
  IF jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN RAISE EXCEPTION 'p_rows tem de ser um array não vazio'; END IF;
  SELECT COALESCE(r->>'unit','count') INTO v_bad
    FROM jsonb_array_elements(p_rows) AS r
   WHERE COALESCE(r->>'unit','count') NOT IN ('count','pct')
   LIMIT 1;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'unit inválida: % (aceita count ou pct)', v_bad; END IF;
  SELECT company_id INTO v_company FROM public.artists WHERE id = p_artist_id;
  IF v_company IS NULL THEN RAISE EXCEPTION 'artista não encontrado'; END IF;
  -- D-ERP168: papel na empresa do artista (não na empresa ativa).
  IF auth.uid() IS NOT NULL AND NOT public.user_has_company_access(v_company, ARRAY['admin','manager','marketing_manager']::public.app_role[]) THEN
    RAISE EXCEPTION 'sem permissão para registar demografia manual';
  END IF;
  INSERT INTO public.artist_audience_demographics (company_id, artist_id, platform, audience_type, dimension, dim_key, value, unit, timeframe, snapshot_date, source)
  SELECT v_company, p_artist_id, p_platform, p_audience_type, p_dimension, r->>'dim_key', (r->>'value')::numeric, COALESCE(r->>'unit','count'), p_timeframe, p_snapshot_date, 'manual'
  FROM jsonb_array_elements(p_rows) AS r
  WHERE COALESCE(r->>'dim_key','') <> '' AND (r->>'value') IS NOT NULL
  ON CONFLICT (artist_id, platform, audience_type, dimension, dim_key, snapshot_date, song_id)
  DO UPDATE SET value = EXCLUDED.value, unit = EXCLUDED.unit, timeframe = EXCLUDED.timeframe, source = 'manual';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  INSERT INTO public.system_audit_log (company_id, entity_type, entity_id, action, changed_by, metadata)
  VALUES (v_company, 'artist_audience', p_artist_id::text, 'demographics_manual', COALESCE(auth.uid()::text, 'service_role'),
          jsonb_build_object('platform', p_platform, 'audience_type', p_audience_type, 'dimension', p_dimension, 'snapshot_date', p_snapshot_date, 'linhas', v_n, 'note', p_note));
  RETURN v_n;
END; $function$

CREATE OR REPLACE FUNCTION public.artist_content_link_songs(p_artist_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true)
 RETURNS TABLE(content_id uuid, song_id uuid, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_artist_id IS NULL THEN
    IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN
      RAISE EXCEPTION 'artist_content_link_songs: indica o artista' USING ERRCODE = '42501';
    END IF;
    PERFORM public._assert_row_company(NULL, 'artist_content_link_songs');
  ELSE
    PERFORM public._assert_row_company((SELECT company_id FROM public.artists WHERE id = p_artist_id), 'artist_content_link_songs');
  END IF;
  RETURN QUERY SELECT * FROM public.artist_content_link_songs__impl(p_artist_id, p_dry_run);
END; $function$

CREATE OR REPLACE FUNCTION public.artist_content_set_song(p_content_id uuid, p_song_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'confirmed'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old record;
  v_song_id uuid;
BEGIN
  IF p_status NOT IN ('none','estimated','confirmed','rejected') THEN
    RAISE EXCEPTION 'estado inválido: %', p_status;
  END IF;

  SELECT id, artist_id, company_id, song_id, song_link_status, song_link_reason
    INTO v_old
    FROM public.artist_content
   WHERE id = p_content_id;

  IF v_old.id IS NULL THEN
    RAISE EXCEPTION 'vídeo não encontrado';
  END IF;
  -- D-ERP168: papel na empresa do vídeo (não na empresa ativa).
  IF NOT public.artist_access_ok(v_old.artist_id,'traffic_write',NULL) THEN
    RAISE EXCEPTION 'sem permissão para alterar a ligação vídeo→música';
  END IF;

  IF p_status IN ('rejected','none') THEN
    v_song_id := NULL;
  ELSE
    v_song_id := COALESCE(p_song_id, v_old.song_id);
    IF v_song_id IS NULL THEN
      RAISE EXCEPTION 'estado % exige uma música', p_status;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.artist_songs s
       WHERE s.id = v_song_id AND s.artist_id = v_old.artist_id
    ) THEN
      RAISE EXCEPTION 'a música não pertence a este artista';
    END IF;
  END IF;

  UPDATE public.artist_content
     SET song_id = v_song_id,
         song_link_status = p_status,
         song_link_reason = CASE
           WHEN p_status = 'confirmed' THEN 'confirmado manualmente'
           WHEN p_status = 'rejected' THEN 'rejeitado manualmente'
           WHEN p_status = 'none' THEN NULL
           ELSE song_link_reason
         END,
         updated_at = now()
   WHERE id = p_content_id;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, metadata)
  VALUES ('artist_content', p_content_id::text, 'set_song',
          COALESCE(auth.uid()::text, 'service_role'),
          jsonb_build_object(
            'old_song_id', v_old.song_id,
            'old_status', v_old.song_link_status,
            'new_song_id', v_song_id,
            'new_status', p_status
          ));
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_song_link_upsert(p_song_id uuid, p_slug text, p_default_mode text, p_title text DEFAULT NULL::text, p_cover_url text DEFAULT NULL::text, p_destinations jsonb DEFAULT '{}'::jsonb, p_meta_pixel_id text DEFAULT NULL::text, p_active boolean DEFAULT true, p_canal text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_artist uuid; v_company uuid; v_slug text; v_ex public.song_links; v_id uuid;
BEGIN
  SELECT artist_id INTO v_artist FROM public.artist_songs WHERE id = p_song_id;
  IF v_artist IS NULL THEN
    RAISE EXCEPTION 'música inexistente' USING ERRCODE = '22023';
  END IF;
  v_company := public.artist_access_check(v_artist,'traffic_write',NULL);

  v_slug := lower(btrim(coalesce(p_slug,'')));
  IF p_destinations IS NULL OR jsonb_typeof(p_destinations) <> 'object' THEN
    RAISE EXCEPTION 'destinations tem de ser um objecto' USING ERRCODE = '22023';
  END IF;
  IF p_meta_pixel_id IS NOT NULL AND btrim(p_meta_pixel_id) <> '' AND btrim(p_meta_pixel_id) !~ '^[0-9]{5,20}$' THEN
    RAISE EXCEPTION 'meta_pixel_id inválido' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ex FROM public.song_links WHERE slug = v_slug;
  IF v_ex.id IS NOT NULL THEN
    IF v_ex.song_id <> p_song_id THEN
      RAISE EXCEPTION 'slug já usado por outra música' USING ERRCODE = '23505';
    END IF;
    UPDATE public.song_links SET
      default_mode = p_default_mode, title = p_title, cover_url = p_cover_url,
      destinations = p_destinations, meta_pixel_id = nullif(btrim(p_meta_pixel_id),''),
      active = coalesce(p_active, true), canal = nullif(btrim(p_canal),'')
    WHERE id = v_ex.id RETURNING id INTO v_id;
  ELSE
    INSERT INTO public.song_links (company_id, artist_id, song_id, slug, default_mode, title,
      cover_url, destinations, meta_pixel_id, active, created_by, canal)
    VALUES (v_company, v_artist, p_song_id, v_slug, p_default_mode, p_title, p_cover_url,
      p_destinations, nullif(btrim(p_meta_pixel_id),''), coalesce(p_active, true), auth.uid(), nullif(btrim(p_canal),''))
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_song_metric_set_manual(p_song_id uuid, p_platform text, p_metric text, p_metric_date date, p_value numeric, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_song record;
  v_old numeric;
  v_existe boolean;
BEGIN
  IF p_platform NOT IN ('tiktok','instagram','youtube','spotify','deezer','apple-music','other') THEN
    RAISE EXCEPTION 'plataforma inválida: %', p_platform;
  END IF;
  IF p_value IS NULL OR p_value < 0 THEN RAISE EXCEPTION 'valor inválido'; END IF;
  SELECT id, artist_id, company_id INTO v_song FROM public.artist_songs WHERE id = p_song_id;
  IF v_song.id IS NULL THEN RAISE EXCEPTION 'música não encontrada'; END IF;
  -- D-ERP168: papel na empresa da música (não na empresa ativa).
  IF NOT public.artist_access_ok(v_song.artist_id,'traffic_write',NULL) THEN
    RAISE EXCEPTION 'sem permissão para registar métricas manuais';
  END IF;

  SELECT value INTO v_old FROM public.artist_song_metrics_daily
   WHERE song_id = p_song_id AND platform = p_platform AND metric = p_metric
     AND metric_date = p_metric_date AND source = 'manual';
  v_existe := FOUND;

  INSERT INTO public.artist_song_metrics_daily (company_id, song_id, artist_id, platform, metric, metric_date, value, source, source_ref, captured_at)
  VALUES (v_song.company_id, p_song_id, v_song.artist_id, p_platform, p_metric, p_metric_date, p_value, 'manual',
          COALESCE(p_note, 'registo manual'), now())
  ON CONFLICT (song_id, platform, metric, metric_date, source)
  DO UPDATE SET value = EXCLUDED.value, source_ref = EXCLUDED.source_ref, captured_at = now();

  -- Relatório desactualizado só em valor NOVO ou DIFERENTE (D-ERP54 adenda).
  IF (NOT v_existe) OR v_old IS DISTINCT FROM p_value THEN
    PERFORM public.artist_song_mark_report_stale(p_song_id);
  END IF;

  INSERT INTO public.system_audit_log (company_id, entity_type, entity_id, action, changed_by, metadata)
  VALUES (v_song.company_id, 'artist_song', p_song_id::text, 'metric_manual', COALESCE(auth.uid()::text, 'service_role'),
          jsonb_build_object('platform', p_platform, 'metric', p_metric, 'date', p_metric_date, 'value', p_value, 'note', p_note));
END; $function$

