CREATE OR REPLACE FUNCTION public.card_load_on_out_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_in_id UUID;
BEGIN
  SELECT in_transaction_id INTO v_in_id
  FROM public.card_session_loads
  WHERE out_transaction_id = OLD.id;
  IF NOT FOUND THEN
    RETURN OLD;
  END IF;

  DELETE FROM public.card_session_loads WHERE out_transaction_id = OLD.id;
  IF v_in_id IS NOT NULL THEN
    DELETE FROM public.transactions WHERE id = v_in_id;
  END IF;

  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.card_load_on_out_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_load  public.card_session_loads%ROWTYPE;
  v_sess  public.card_sessions%ROWTYPE;
  v_src_name TEXT;
  v_card_name TEXT;
  v_cat_id UUID;
  v_in_id UUID;
BEGIN
  IF NEW.status <> 'paid' OR OLD.status = 'paid' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_load
  FROM public.card_session_loads
  WHERE out_transaction_id = NEW.id
    AND in_transaction_id IS NULL
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_sess FROM public.card_sessions WHERE id = v_load.session_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  SELECT name INTO v_src_name  FROM public.financial_accounts WHERE id = v_load.source_account_id;
  SELECT name INTO v_card_name FROM public.financial_accounts WHERE id = v_sess.card_account_id;
  SELECT id   INTO v_cat_id    FROM public.account_categories  WHERE code = '10.3' LIMIT 1;

  INSERT INTO public.transactions (
    company_id, type, description, amount, iva_rate, date,
    status, paid_amount, payment_date,
    is_transitory, transitory_reason, exclude_from_result, category_id, account_id
  ) VALUES (
    NEW.company_id, 'income',
    'Carga de ' || COALESCE(v_src_name,'origem') || ' (' || COALESCE(v_src_name,'origem') || ' → ' || COALESCE(v_card_name,'cartão') || ')',
    v_load.amount, 0, v_load.load_date,
    'paid', v_load.amount, COALESCE(NEW.payment_date, v_load.load_date),
    TRUE, 'carga_cartao', TRUE, v_cat_id, v_sess.card_account_id
  ) RETURNING id INTO v_in_id;

  UPDATE public.card_session_loads
     SET in_transaction_id = v_in_id
   WHERE id = v_load.id;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_leads_capi_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pending int;
  v_last_sent timestamptz;
  v_stuck int;
  v_stalled boolean;
  v_msg text;
begin
  select count(*) into v_pending
  from public.leads
  where capi_status is null or capi_status = 'retry';

  select max(capi_sent_at) into v_last_sent
  from public.leads where capi_status = 'sent';

  select count(*) into v_stuck
  from public.leads
  where capi_status = 'processing' and capi_sent_at < now() - interval '1 hour';

  v_stalled := (v_pending > 100)
            or (v_last_sent is null or v_last_sent < now() - interval '6 hours')
            or (v_stuck > 0);

  if v_stalled then
    v_msg := format(
      'Envio de leads para o Meta CAPI parado. Por enviar: %s. Presos em processing: %s. Ultimo envio: %s.',
      v_pending, v_stuck, coalesce(v_last_sent::text, 'nunca'));

    insert into public.system_reminders (key, title, message, due_date, frequency, link_url, is_active)
    values ('leads_capi_stalled', 'CAPI de leads parado', v_msg, current_date, 'daily', '/admin', true)
    on conflict (key) do update
      set message = excluded.message,
          due_date = current_date,
          is_active = true,
          updated_at = now(),
          completed_at = null;
  else
    update public.system_reminders
      set is_active = false, completed_at = now(), updated_at = now()
      where key = 'leads_capi_stalled' and is_active;
  end if;

  return jsonb_build_object(
    'pending', v_pending, 'stuck_processing', v_stuck,
    'last_sent_at', v_last_sent, 'stalled', v_stalled);
end;
$function$

CREATE OR REPLACE FUNCTION public.check_rpc_smoke()
 RETURNS TABLE(code text, ok boolean, error text, checked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid uuid := gen_random_uuid();
  v_today date := current_date;
  v_sql text;
  v_name text;
  v_names text[] := ARRAY[
    'select count(*) from public.current_company_id()|current_company_id',
    'select count(*) from public.get_sales_position()|get_sales_position',
    'select count(*) from public.get_sales_position_by_provider()|get_sales_position_by_provider',
    'select count(*) from public.get_sales_last_sync()|get_sales_last_sync',
    'select count(*) from public.get_daily_sales_series($1::date, $2::date, null, null)|get_daily_sales_series',
    'select count(*) from public.get_event_bp_changes($3, 30)|get_event_bp_changes',
    'select count(*) from public.list_orphan_transactions_for_event($3)|list_orphan_transactions_for_event',
    'select count(*) from public.list_bp_versions($3)|list_bp_versions',
    'select count(*) from public.bp_version_linked_tx_count($3)|bp_version_linked_tx_count',
    'select count(*) from public.calibrate_forecast_boost($3, 14)|calibrate_forecast_boost',
    'select count(*) from public.get_partner_bp_realized($3)|get_partner_bp_realized',
    'select count(*) from public.get_partner_event_tx_aggregates(array[$3])|get_partner_event_tx_aggregates',
    'select count(*) from public.get_partner_event_partner_expenses(array[$3])|get_partner_event_partner_expenses',
    'select count(*) from public.get_bp_l3_attachments(array[$3])|get_bp_l3_attachments',
    'select count(*) from public.analyze_formalidade_bulk(array[$3])|analyze_formalidade_bulk',
    'select count(*) from public.formalidade_audit_stats(array[$3])|formalidade_audit_stats',
    'select count(*) from public.get_supplier_bank_details(array[$3])|get_supplier_bank_details',
    'select count(*) from public.check_supplier_iban_duplicate(''PT50000000000000000000000'', $3)|check_supplier_iban_duplicate',
    'select count(*) from public.get_leads_geo_stats(''30d'')|get_leads_geo_stats',
    'select count(*) from public.crm_meta_capi_dashboard(7)|crm_meta_capi_dashboard',
    'select count(*) from public.crm_meta_audiences_dashboard()|crm_meta_audiences_dashboard',
    'select count(*) from public.list_endorsable_companies($3)|list_endorsable_companies',
    'select count(*) from public.list_endorsable_events($3, null, null, true, 10)|list_endorsable_events',
    'select count(*) from public.get_event_cash_position($3, $1::date, $2::date)|get_event_cash_position'
  ];
  v_item text;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'manager')) THEN
    RAISE EXCEPTION 'check_rpc_smoke: apenas admin ou manager';
  END IF;

  FOREACH v_item IN ARRAY v_names LOOP
    v_sql := split_part(v_item, '|', 1);
    v_name := split_part(v_item, '|', 2);
    BEGIN
      EXECUTE v_sql USING v_today, v_today, v_uuid;
      RETURN QUERY SELECT v_name, true, NULL::text, v_now;
    EXCEPTION WHEN OTHERS THEN
      RETURN QUERY SELECT v_name, false, SQLSTATE || ': ' || SQLERRM, v_now;
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_supplier_iban_duplicate(p_iban text, p_supplier_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_norm text;
  v_row record;
BEGIN
  IF NOT public.can_view_supplier_bank_data() THEN
    RAISE EXCEPTION 'Sem permissão para validar dados bancários';
  END IF;

  v_norm := upper(regexp_replace(coalesce(p_iban, ''), '\s', '', 'g'));
  IF v_norm = '' THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  SELECT id, name, nif, is_active
    INTO v_row
    FROM public.suppliers
   WHERE company_id = public.current_company_id()
     AND (
       upper(regexp_replace(coalesce(iban,   ''), '\s', '', 'g')) = v_norm OR
       upper(regexp_replace(coalesce(iban_2, ''), '\s', '', 'g')) = v_norm OR
       upper(regexp_replace(coalesce(iban_3, ''), '\s', '', 'g')) = v_norm
     )
     AND (p_supplier_id IS NULL OR id <> p_supplier_id)
   ORDER BY (coalesce(is_active, false)) DESC, name
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  RETURN jsonb_build_object(
    'exists', true,
    'is_active', coalesce(v_row.is_active, false),
    'supplier_id', v_row.id,
    'supplier_name', v_row.name,
    'nif', v_row.nif
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_operation_key(_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_affected int;
  v_actor text;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NOT (public.has_role(auth.uid(), 'admin') OR public.is_platform_admin(auth.uid())) THEN
      RAISE EXCEPTION 'Apenas administradores podem apagar chaves de operação' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;

  _key := btrim(coalesce(_key, ''));
  IF _key = '' THEN
    RAISE EXCEPTION 'Chave inválida' USING ERRCODE = '22023';
  END IF;
  IF _key LIKE 'CAMARIM-%' OR _key LIKE 'CARTAO-%' THEN
    RAISE EXCEPTION 'Chaves geradas pelo sistema (CAMARIM-/CARTAO-) não podem ser apagadas' USING ERRCODE = '42501';
  END IF;

  v_actor := coalesce((SELECT email FROM auth.users WHERE id = auth.uid()), 'sistema');

  INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value, company_id)
  SELECT id, v_actor, 'Chave de operação (apagar grupo)', _key, NULL, v_company
  FROM public.transactions
  WHERE company_id = v_company AND operation_key = _key;

  UPDATE public.transactions
  SET operation_key = NULL
  WHERE company_id = v_company AND operation_key = _key;
  GET DIAGNOSTICS v_affected = ROW_COUNT;

  IF v_affected = 0 THEN
    RAISE EXCEPTION 'Chave % não encontrada nesta empresa', _key USING ERRCODE = 'no_data_found';
  END IF;

  RETURN jsonb_build_object('key', _key, 'affected', v_affected);
END;
$function$

CREATE OR REPLACE FUNCTION public.club_decide_attendance(p_claim uuid, p_valid boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; BEGIN
  IF NOT public.portal_can_write() THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT * INTO c FROM club_attendance_claims WHERE id = p_claim;
  IF NOT FOUND OR NOT public.row_belongs_to_current_company(c.company_id) THEN RAISE EXCEPTION 'não encontrado'; END IF;
  UPDATE club_attendance_claims SET status = CASE WHEN p_valid THEN 'valido' ELSE 'recusado' END, matched_source = 'manual', decided_at = now() WHERE id = p_claim;
  IF p_valid THEN PERFORM club_award(c.member_id, 'attended_year', c.year::text); END IF;
END $function$

CREATE OR REPLACE FUNCTION public.club_decide_guess(p_guess uuid, p_correct boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g record; pts int; BEGIN
  IF NOT public.portal_can_write() THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT cg.*, cm.site_id INTO g FROM club_guesses cg JOIN club_members cm ON cm.id = cg.member_id WHERE cg.id = p_guess;
  IF NOT FOUND OR NOT public.row_belongs_to_current_company(g.company_id) THEN RAISE EXCEPTION 'não encontrado'; END IF;
  UPDATE club_guesses SET status = CASE WHEN p_correct THEN 'certo' ELSE 'errado' END, decided_by = auth.uid(), decided_at = now() WHERE id = p_guess;
  SELECT points INTO pts FROM club_point_rules WHERE site_id = g.site_id AND rule_key = 'guess_correct' AND active;
  PERFORM club_points_set(g.member_id, 'guess_correct', g.reveal_id::text, pts, p_correct, 'Palpite marcado como errado');
END $function$

CREATE OR REPLACE FUNCTION public.club_mission_review(p_subs uuid[], p_status text, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n int := 0; BEGIN
  IF NOT public.portal_can_write() THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF p_status NOT IN ('pendente','aprovada','rejeitada','finalista','vencedora') THEN RAISE EXCEPTION 'estado inválido'; END IF;
  IF p_status = 'rejeitada' AND coalesce(trim(p_reason),'') = '' THEN RAISE EXCEPTION 'indica o motivo'; END IF;
  FOR r IN SELECT x.id, x.company_id, x.mission_id, x.member_id, x.status, m.kind FROM club_mission_submissions x
             JOIN club_missions m ON m.id = x.mission_id WHERE x.id = ANY(p_subs) LOOP
    IF NOT public.row_belongs_to_current_company(r.company_id) THEN RAISE EXCEPTION 'não encontrado'; END IF;
    IF p_status IN ('finalista','vencedora') AND r.kind <> 'desafio' THEN RAISE EXCEPTION 'finalista/vencedora só em desafios'; END IF;
    IF r.status = 'rejeitada' AND p_status <> 'rejeitada' AND EXISTS (SELECT 1 FROM club_mission_submissions
         WHERE mission_id = r.mission_id AND member_id = r.member_id AND status <> 'rejeitada' AND id <> r.id) THEN
      RAISE EXCEPTION 'o membro já tem outra submissão ativa nesta missão'; END IF;
    UPDATE club_mission_submissions SET status = p_status,
      reject_reason = CASE WHEN p_status = 'rejeitada' THEN trim(p_reason) ELSE NULL END,
      reviewed_by = auth.uid(), reviewed_at = now() WHERE id = r.id;
    PERFORM club_mission_sync_points(r.id);
    n := n + 1;
  END LOOP;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.club_points_void(p_points uuid[], p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r club_points; n int := 0; BEGIN
  IF NOT public.portal_can_write() THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF coalesce(trim(p_reason),'') = '' THEN RAISE EXCEPTION 'indica o motivo'; END IF;
  FOR r IN SELECT * FROM club_points WHERE id = ANY(p_points) LOOP
    IF NOT public.row_belongs_to_current_company(r.company_id) THEN RAISE EXCEPTION 'não encontrado'; END IF;
    n := n + _club_points_void_row(r, p_reason);
  END LOOP;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.club_terms_publish(p_site uuid, p_body text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; v int; d uuid; BEGIN
  IF NOT public.portal_can_write() THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF coalesce(trim(p_body),'') = '' THEN RAISE EXCEPTION 'regulamento vazio'; END IF;
  SELECT * INTO s FROM portal_sites WHERE id = p_site;
  IF NOT FOUND OR NOT public.row_belongs_to_current_company(s.company_id) THEN RAISE EXCEPTION 'site inválido'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('club_terms:'||p_site));
  SELECT id, version INTO d, v FROM club_terms WHERE site_id = p_site AND status = 'rascunho';
  IF d IS NOT NULL THEN
    UPDATE club_terms SET body_md = p_body, status = 'publicada', published_at = now(), published_by = auth.uid(), updated_at = now() WHERE id = d;
  ELSE
    v := coalesce((SELECT max(version) FROM club_terms WHERE site_id = p_site), 0) + 1;
    INSERT INTO club_terms(company_id, site_id, version, body_md, status, published_at, published_by, created_by)
      VALUES (s.company_id, p_site, v, p_body, 'publicada', now(), auth.uid(), auth.uid());
  END IF;
  RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.coala_capture_category_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fallback_id uuid;
  v_desc_norm text;
  v_src text;
  v_actor uuid;
BEGIN
  -- só interessa quando categoria mudou para algo válido
  IF NEW.category_id IS NULL OR NEW.supplier_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.category_id IS NOT DISTINCT FROM NEW.category_id THEN
    RETURN NEW;
  END IF;
  IF NEW.company_id IS NULL THEN RETURN NEW; END IF;

  -- Ramo Capital (10.1.x): movimentos de capital — aportes, devoluções, distribuições,
  -- empréstimos a sócio — não são classificação de despesa e não alimentam o mapa de
  -- sugestão. Sem esta guarda, cada aporte espelhado automático escrevia uma linha aqui.
  IF EXISTS (
    SELECT 1 FROM public.account_categories c
     WHERE c.id = NEW.category_id AND c.code LIKE '10.1.%'
  ) THEN
    RETURN NEW;
  END IF;

  -- ignorar se for a categoria fallback "A Classificar"
  SELECT id INTO v_fallback_id
    FROM public.account_categories
   WHERE company_id = NEW.company_id
     AND code IN ('0.0.99','2.6.08')
   ORDER BY (code = '0.0.99') DESC
   LIMIT 1;
  IF v_fallback_id IS NOT NULL AND NEW.category_id = v_fallback_id THEN
    RETURN NEW;
  END IF;

  v_desc_norm := public.norm_coala_desc(NEW.description);
  IF v_desc_norm IS NULL OR length(v_desc_norm) < 3 THEN RETURN NEW; END IF;

  v_src := COALESCE(NULLIF(current_setting('app.coala_match_source', true), ''), 'inline_edit');
  v_actor := auth.uid();

  INSERT INTO public.coala_supplier_category_map AS m (
    company_id, supplier_id, description_normalized, category_id,
    confirmed_count, matched_via, created_by, last_used_at
  ) VALUES (
    NEW.company_id, NEW.supplier_id, v_desc_norm, NEW.category_id,
    1, v_src, v_actor, now()
  )
  ON CONFLICT (company_id, supplier_id, description_normalized) DO UPDATE
    SET category_id   = EXCLUDED.category_id,
        confirmed_count = CASE
          WHEN m.category_id = EXCLUDED.category_id THEN m.confirmed_count + 1
          ELSE 1
        END,
        matched_via   = EXCLUDED.matched_via,
        last_used_at  = now(),
        updated_at    = now();

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'coala_capture_category_change failed: %', SQLERRM;
  RETURN NEW;
END $function$

