CREATE OR REPLACE FUNCTION public.coala_scm_validate_l3()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_parent uuid; v_grand uuid;
BEGIN
  SELECT parent_id INTO v_parent FROM public.account_categories WHERE id = NEW.category_id;
  IF v_parent IS NULL THEN
    RAISE EXCEPTION 'category_id % não é L3 (sem parent)', NEW.category_id;
  END IF;
  SELECT parent_id INTO v_grand FROM public.account_categories WHERE id = v_parent;
  IF v_grand IS NULL THEN
    RAISE EXCEPTION 'category_id % não é L3 (parent é L1)', NEW.category_id;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.collect_event_benchmarks(_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ev record; v_total numeric; v_buckets int := 0; v_pax int := 0; v_pc numeric; v_n int;
BEGIN
  SELECT id, date, company_id INTO v_ev FROM public.events WHERE id = _event_id;
  IF v_ev.id IS NULL THEN RAISE EXCEPTION 'Evento % não existe', _event_id; END IF;
  IF auth.uid() IS NOT NULL THEN
    IF NOT (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')
            OR has_permission(auth.uid(),'manage_bp') OR is_platform_admin(auth.uid())) THEN
      RAISE EXCEPTION 'Sem permissão para colher benchmarks' USING ERRCODE = '42501';
    END IF;
    IF v_ev.company_id IS DISTINCT FROM current_company_id() AND NOT is_platform_admin(auth.uid()) THEN
      RAISE EXCEPTION 'Evento de outra empresa' USING ERRCODE = '42501';
    END IF;
  END IF;
  IF v_ev.date IS NULL THEN RAISE EXCEPTION 'Evento sem data — não há dia relativo'; END IF;

  DELETE FROM public.event_simulator_sales_curve_buckets WHERE event_id = _event_id;
  SELECT COALESCE(sum(ts.quantity),0) INTO v_total
    FROM public.ticket_sales ts JOIN public.event_ticket_zones z ON z.id = ts.zone_id
   WHERE z.event_id = _event_id;
  IF v_total > 0 THEN
    INSERT INTO public.event_simulator_sales_curve_buckets (event_id, days_before, cumulative_pct)
    SELECT _event_id, d.db,
           round(100.0 * COALESCE((SELECT sum(ts.quantity)
              FROM public.ticket_sales ts JOIN public.event_ticket_zones z ON z.id = ts.zone_id
             WHERE z.event_id = _event_id
               AND (v_ev.date - COALESCE(ts.sale_date_to, ts.sale_date)) >= d.db), 0) / v_total, 4)
      FROM generate_series(0,180) AS d(db);
    GET DIAGNOSTICS v_buckets = ROW_COUNT;
  END IF;

  SELECT sum(a.faturacao_real_bebidas),
         sum(COALESCE(a.participants_manual,
             (SELECT sum(ts.quantity) FROM public.ticket_sales ts WHERE ts.zone_id = a.source_ticket_zone_id)))::int,
         count(DISTINCT a.event_id)::int
    INTO v_pc, v_pax, v_n
    FROM public.event_ab_zones a JOIN public.events e ON e.id = a.event_id
   WHERE e.company_id = v_ev.company_id AND a.faturacao_real_bebidas IS NOT NULL;
  DELETE FROM public.event_simulator_pax_benchmarks
   WHERE company_id = v_ev.company_id AND scope = 'global' AND category_code = '1.1.02';
  IF COALESCE(v_pax,0) > 0 THEN
    INSERT INTO public.event_simulator_pax_benchmarks
      (company_id, scope, scope_value, category_code, sample_size, avg_ticket_per_pax, last_calculated_at)
    VALUES (v_ev.company_id, 'global', 'all', '1.1.02', v_n, round(v_pc / v_pax, 4), now());
  END IF;

  RETURN jsonb_build_object('ok', true, 'event_id', _event_id, 'tickets', v_total,
    'curve_buckets', v_buckets, 'ab_events', COALESCE(v_n,0), 'ab_pax', COALESCE(v_pax,0),
    'ab_per_capita', CASE WHEN COALESCE(v_pax,0) > 0 THEN round(v_pc / v_pax, 4) END);
END $function$

CREATE OR REPLACE FUNCTION public.confirm_ticket_office_statement(p_statement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; v_sum numeric; v_pending int;
BEGIN
  SELECT * INTO s FROM public.ticket_office_statements WHERE id = p_statement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Apuramento não encontrado.'; END IF;
  IF NOT public.row_belongs_to_current_company(s.company_id) THEN RAISE EXCEPTION 'Sem acesso a este apuramento.'; END IF;
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager') OR public.has_role(auth.uid(),'platform_admin')) THEN
    RAISE EXCEPTION 'Só admin ou manager confirmam apuramentos.';
  END IF;
  IF s.status = 'confirmed' THEN RAISE EXCEPTION 'Apuramento já confirmado.'; END IF;
  IF s.document_total IS NULL THEN RAISE EXCEPTION 'Falta o total do documento.'; END IF;
  SELECT count(*) FILTER (WHERE pending_document), COALESCE(sum(amount),0)
    INTO v_pending, v_sum FROM public.ticket_office_statement_lines WHERE statement_id = p_statement_id;
  IF v_pending > 0 THEN RAISE EXCEPTION 'Há % linha(s) pendente(s) de documento.', v_pending; END IF;
  IF abs(round(v_sum,2) - s.document_total) > 0.004 THEN
    RAISE EXCEPTION 'Σ linhas (%) ≠ total do documento (%).', round(v_sum,2), s.document_total;
  END IF;
  UPDATE public.ticket_office_statements SET status='confirmed', confirmed_at=now(), confirmed_by=auth.uid(), updated_at=now()
   WHERE id = p_statement_id;
END $function$

CREATE OR REPLACE FUNCTION public.consume_recovery_code(_code_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  IF auth.uid() IS NULL OR _code_hash IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT id INTO v_id
  FROM public.mfa_recovery_codes
  WHERE user_id = auth.uid()
    AND code_hash = _code_hash
    AND used_at IS NULL
  LIMIT 1;

  IF v_id IS NULL THEN
    RETURN FALSE;
  END IF;

  UPDATE public.mfa_recovery_codes
  SET used_at = now()
  WHERE id = v_id;

  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_bp_snapshot(_event_id uuid, _description text DEFAULT NULL::text, _approve_immediately boolean DEFAULT false, _scenario_label text DEFAULT NULL::text, _scenario_assumptions jsonb DEFAULT NULL::jsonb, _is_pinned_scenario boolean DEFAULT false, _created_by uuid DEFAULT NULL::uuid, _created_by_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event RECORD; v_is_master boolean := false;
  v_next_version int; v_state text;
  v_master_version_id uuid; v_now timestamptz := now();
  v_payload jsonb; v_split RECORD; v_split_payload jsonb;
  v_split_version_id uuid; v_split_next_version int;
  v_previous_active_id uuid; v_split_previous_active_id uuid;
  v_session_map jsonb;
  v_zone_map jsonb;
  v_old_id uuid; v_new_id uuid;
  v_session_row RECORD; v_zone_row RECORD; v_lot_row RECORD;
  v_company_id uuid;
  v_split_company_id uuid;
BEGIN
  -- D-ERP38: portao de permissao e isolamento de empresa.
  DECLARE
    v_uid uuid := auth.uid();
    v_company uuid;
  BEGIN
    -- auth.uid() NULL = service_role / cron / edge function: isencao deliberada,
    -- mesmo padrao de enforce_transaction_approval_permission.
    IF v_uid IS NOT NULL THEN
      IF NOT (public.is_platform_admin(v_uid)
              OR public.has_role(v_uid, 'admin'::app_role)
              OR public.has_permission(v_uid, 'manage_bp')) THEN
        RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
      END IF;
      IF NOT public.is_platform_admin(v_uid) THEN
        SELECT e.company_id INTO v_company FROM public.events e WHERE e.id = _event_id;
        IF v_company IS NULL OR v_company IS DISTINCT FROM public.current_company_id() THEN
          RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;
  END;
  -- D-ERP38: autoria nao forjavel. Com utilizador, ignora o parametro recebido;
  -- com auth.uid() NULL (service_role) usa-se o parametro como antes.
  _created_by := COALESCE(auth.uid(), _created_by);
  SELECT id, name, parent_event_id, status, company_id INTO v_event FROM public.events WHERE id = _event_id;
  IF v_event IS NULL THEN RAISE EXCEPTION 'Event % not found', _event_id; END IF;
  IF v_event.parent_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'Cannot create snapshot directly on a Split event (%). Snapshot the Master instead.', _event_id;
  END IF;
  v_company_id := v_event.company_id;
  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'create_bp_snapshot: event % has no company_id', _event_id;
  END IF;
  SELECT EXISTS (SELECT 1 FROM public.events WHERE parent_event_id = _event_id) INTO v_is_master;
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_version FROM public.bp_versions WHERE event_id = _event_id;
  IF _scenario_label IS NOT NULL THEN v_state := 'draft';
  ELSIF _approve_immediately THEN v_state := 'active';
  ELSE v_state := 'draft'; END IF;

  v_payload := jsonb_build_object(
    'event', jsonb_build_object('id', v_event.id, 'name', v_event.name, 'status', v_event.status),
    'snapshot_taken_at', v_now,
    'forecasts', COALESCE((SELECT jsonb_agg(to_jsonb(f.*) ORDER BY f.created_at)
      FROM public.event_forecasts f WHERE f.event_id = _event_id AND f.version_id IS NULL), '[]'::jsonb)
  );

  IF v_state = 'active' THEN
    SELECT id INTO v_previous_active_id FROM public.bp_versions WHERE event_id = _event_id AND state = 'active' LIMIT 1;
    IF v_previous_active_id IS NOT NULL THEN
      UPDATE public.bp_versions SET state = 'superseded', superseded_at = v_now WHERE id = v_previous_active_id;
    END IF;
  END IF;

  INSERT INTO public.bp_versions (
    event_id, version_number, state, created_by, created_by_label, description,
    snapshot_payload, approved_at, approved_by, scenario_label, scenario_assumptions, is_pinned_scenario, company_id)
  VALUES (_event_id, v_next_version, v_state, _created_by, _created_by_label, _description, v_payload,
    CASE WHEN v_state = 'active' THEN v_now ELSE NULL END,
    CASE WHEN v_state = 'active' THEN _created_by ELSE NULL END,
    _scenario_label, _scenario_assumptions, COALESCE(_is_pinned_scenario, false), v_company_id)
  RETURNING id INTO v_master_version_id;

  INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata, company_id)
  VALUES (v_master_version_id, _event_id,
    CASE WHEN _scenario_label IS NOT NULL THEN 'scenario_created' ELSE 'created' END,
    _created_by, _created_by_label,
    jsonb_build_object('version_number', v_next_version, 'state', v_state, 'is_master', v_is_master, 'scenario_label', _scenario_label),
    v_company_id);

  IF v_state = 'active' AND v_previous_active_id IS NOT NULL THEN
    UPDATE public.bp_versions SET superseded_by_version_id = v_master_version_id WHERE id = v_previous_active_id;
    INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata, company_id)
    VALUES (v_previous_active_id, _event_id, 'superseded', _created_by, _created_by_label,
      jsonb_build_object('superseded_by_version_id', v_master_version_id), v_company_id);
  END IF;

  IF _scenario_label IS NOT NULL THEN
    v_session_map := '{}'::jsonb;
    v_zone_map := '{}'::jsonb;

    FOR v_session_row IN
      SELECT * FROM public.event_sessions
       WHERE event_id = _event_id AND version_id IS NULL
    LOOP
      v_old_id := v_session_row.id;
      v_new_id := gen_random_uuid();
      INSERT INTO public.event_sessions (id, event_id, date, label, start_time, sort_order, version_id)
      VALUES (v_new_id, _event_id, v_session_row.date, v_session_row.label, v_session_row.start_time,
              v_session_row.sort_order, v_master_version_id);
      v_session_map := v_session_map || jsonb_build_object(v_old_id::text, v_new_id::text);
    END LOOP;

    FOR v_zone_row IN
      SELECT * FROM public.event_ticket_zones
       WHERE event_id = _event_id AND version_id IS NULL
    LOOP
      v_old_id := v_zone_row.id;
      v_new_id := gen_random_uuid();
      INSERT INTO public.event_ticket_zones (id, event_id, name, total_capacity, session_id, version_id)
      VALUES (v_new_id, _event_id, v_zone_row.name, v_zone_row.total_capacity,
              CASE WHEN v_zone_row.session_id IS NULL THEN NULL
                   ELSE NULLIF(v_session_map->>(v_zone_row.session_id::text), '')::uuid END,
              v_master_version_id);
      v_zone_map := v_zone_map || jsonb_build_object(v_old_id::text, v_new_id::text);
    END LOOP;

    FOR v_lot_row IN
      SELECT l.* FROM public.event_ticket_lots l
       JOIN public.event_ticket_zones z ON z.id = l.zone_id
      WHERE z.event_id = _event_id AND z.version_id IS NULL AND l.version_id IS NULL
    LOOP
      INSERT INTO public.event_ticket_lots (id, zone_id, lot_number, name, quantity, price, iva_rate, lot_type, version_id)
      VALUES (gen_random_uuid(),
              NULLIF(v_zone_map->>(v_lot_row.zone_id::text), '')::uuid,
              v_lot_row.lot_number, v_lot_row.name, v_lot_row.quantity, v_lot_row.price,
              v_lot_row.iva_rate, v_lot_row.lot_type, v_master_version_id);
    END LOOP;
  END IF;

  IF v_is_master THEN
    FOR v_split IN SELECT id, name, status, company_id FROM public.events WHERE parent_event_id = _event_id LOOP
      v_split_company_id := COALESCE(v_split.company_id, v_company_id);
      v_split_payload := jsonb_build_object(
        'event', jsonb_build_object('id', v_split.id, 'name', v_split.name, 'status', v_split.status, 'parent_event_id', _event_id),
        'snapshot_taken_at', v_now, 'cascaded_from_event_id', _event_id,
        'forecasts', COALESCE((SELECT jsonb_agg(to_jsonb(f.*) ORDER BY f.created_at)
          FROM public.event_forecasts f WHERE f.event_id = v_split.id AND f.version_id IS NULL), '[]'::jsonb));
      SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_split_next_version FROM public.bp_versions WHERE event_id = v_split.id;
      v_split_previous_active_id := NULL;
      IF v_state = 'active' THEN
        SELECT id INTO v_split_previous_active_id FROM public.bp_versions WHERE event_id = v_split.id AND state = 'active' LIMIT 1;
        IF v_split_previous_active_id IS NOT NULL THEN
          UPDATE public.bp_versions SET state = 'superseded', superseded_at = v_now WHERE id = v_split_previous_active_id;
        END IF;
      END IF;
      INSERT INTO public.bp_versions (event_id, version_number, state, created_by, created_by_label, description,
        snapshot_payload, approved_at, approved_by, cascaded_from_version_id,
        scenario_label, scenario_assumptions, is_pinned_scenario, company_id)
      VALUES (v_split.id, v_split_next_version, v_state, _created_by, _created_by_label, _description, v_split_payload,
        CASE WHEN v_state = 'active' THEN v_now ELSE NULL END,
        CASE WHEN v_state = 'active' THEN _created_by ELSE NULL END,
        v_master_version_id, _scenario_label, _scenario_assumptions, COALESCE(_is_pinned_scenario, false), v_split_company_id)
      RETURNING id INTO v_split_version_id;
      INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata, company_id)
      VALUES (v_split_version_id, v_split.id, 'cascaded_from_master', _created_by, _created_by_label,
        jsonb_build_object('master_version_id', v_master_version_id, 'master_event_id', _event_id, 'state', v_state),
        v_split_company_id);
      IF v_state = 'active' AND v_split_previous_active_id IS NOT NULL THEN
        UPDATE public.bp_versions SET superseded_by_version_id = v_split_version_id WHERE id = v_split_previous_active_id;
        INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata, company_id)
        VALUES (v_split_previous_active_id, v_split.id, 'superseded', _created_by, _created_by_label,
          jsonb_build_object('superseded_by_version_id', v_split_version_id), v_split_company_id);
      END IF;

      IF _scenario_label IS NOT NULL THEN
        v_session_map := '{}'::jsonb;
        v_zone_map := '{}'::jsonb;

        FOR v_session_row IN
          SELECT * FROM public.event_sessions WHERE event_id = v_split.id AND version_id IS NULL
        LOOP
          v_old_id := v_session_row.id;
          v_new_id := gen_random_uuid();
          INSERT INTO public.event_sessions (id, event_id, date, label, start_time, sort_order, version_id)
          VALUES (v_new_id, v_split.id, v_session_row.date, v_session_row.label, v_session_row.start_time,
                  v_session_row.sort_order, v_split_version_id);
          v_session_map := v_session_map || jsonb_build_object(v_old_id::text, v_new_id::text);
        END LOOP;

        FOR v_zone_row IN
          SELECT * FROM public.event_ticket_zones WHERE event_id = v_split.id AND version_id IS NULL
        LOOP
          v_old_id := v_zone_row.id;
          v_new_id := gen_random_uuid();
          INSERT INTO public.event_ticket_zones (id, event_id, name, total_capacity, session_id, version_id)
          VALUES (v_new_id, v_split.id, v_zone_row.name, v_zone_row.total_capacity,
                  CASE WHEN v_zone_row.session_id IS NULL THEN NULL
                       ELSE NULLIF(v_session_map->>(v_zone_row.session_id::text), '')::uuid END,
                  v_split_version_id);
          v_zone_map := v_zone_map || jsonb_build_object(v_old_id::text, v_new_id::text);
        END LOOP;

        FOR v_lot_row IN
          SELECT l.* FROM public.event_ticket_lots l
           JOIN public.event_ticket_zones z ON z.id = l.zone_id
          WHERE z.event_id = v_split.id AND z.version_id IS NULL AND l.version_id IS NULL
        LOOP
          INSERT INTO public.event_ticket_lots (id, zone_id, lot_number, name, quantity, price, iva_rate, lot_type, version_id)
          VALUES (gen_random_uuid(),
                  NULLIF(v_zone_map->>(v_lot_row.zone_id::text), '')::uuid,
                  v_lot_row.lot_number, v_lot_row.name, v_lot_row.quantity, v_lot_row.price,
                  v_lot_row.iva_rate, v_lot_row.lot_type, v_split_version_id);
        END LOOP;
      END IF;
    END LOOP;
  END IF;

  -- #172 (20/09/2026): removida a chamada a reconcile_bp_overrides_for_event.
  -- Escrevia em transactions.pl_mode/notes (colunas inexistentes) e vivia dentro de
  -- BEGIN … EXCEPTION WHEN OTHERS THEN RAISE WARNING, logo falhava sempre em silêncio.

  RETURN v_master_version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_cache_advance(p_event_id uuid, p_artist_supplier_id uuid, p_supplier_id uuid, p_amount numeric, p_due_date date, p_description text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_line_choices jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := public._cache_assert_actor(); v_root uuid; v_company uuid; v_cat uuid; v_mother uuid;
  v_events uuid[]; v_lines uuid[]; v_caps numeric[]; v_abs boolean[]; v_names text[]; v_absorber int; v_n int; i int;
  v_total numeric := 0; v_used numeric; v_free numeric; v_alloc numeric[]; v_acc numeric := 0; v_city numeric;
  v_desc text; v_today date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  PERFORM set_config('cache.line_choices', coalesce(p_line_choices::text, ''), true);
  SELECT coalesce(parent_event_id, id), company_id INTO v_root, v_company FROM public.events WHERE id = p_event_id;
  IF v_root IS NULL OR v_company <> public.current_company_id() THEN RAISE EXCEPTION 'evento_inexistente'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('cache:' || v_root || ':' || p_artist_supplier_id, 0));
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_mother FROM public.transactions WHERE company_id = v_company AND operation_key = 'cache_adv:' || p_idempotency_key;
    IF FOUND THEN RETURN v_mother; END IF;
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> round(p_amount,2) THEN RAISE EXCEPTION 'valor_invalido'; END IF;
  v_cat := public._cache_category(v_company);
  SELECT array_agg(event_id ORDER BY idx), array_agg(forecast_id ORDER BY idx), array_agg(cap ORDER BY idx),
         array_agg(is_absorber ORDER BY idx), array_agg(event_name ORDER BY idx)
    INTO v_events, v_lines, v_caps, v_abs, v_names FROM public._cache_cities(v_root, p_artist_supplier_id);
  IF v_events IS NULL THEN RAISE EXCEPTION 'sem_linha_cache: não há linha de cachê (2.1.01) no BP desta cidade. Crie-a no BP ou configure o cachê.'; END IF;
  PERFORM public._cache_assert_lines(v_root, p_artist_supplier_id, p_line_choices);
  IF EXISTS (SELECT 1 FROM public._cache_cities_x(v_root, p_artist_supplier_id, p_line_choices) x WHERE x.source = 'config' AND x.frozen) THEN
    RAISE EXCEPTION 'cache_ja_congelado: O cachê já está congelado: lance o adiantamento dentro de um contrato.';
  END IF;
  v_n := array_length(v_events,1);
  FOR i IN 1..v_n LOOP v_total := v_total + v_caps[i]; IF v_abs[i] THEN v_absorber := i; END IF; END LOOP;
  SELECT coalesce(sum(gross),0) INTO v_used FROM public.cache_payment_contracts
   WHERE root_event_id = v_root AND artist_supplier_id = p_artist_supplier_id AND cancelled_at IS NULL;
  SELECT coalesce(sum(amount),0) INTO v_free FROM public._cache_free_advances(v_root, p_artist_supplier_id);
  IF p_amount > v_total - v_used - v_free + 0.005 THEN
    RAISE EXCEPTION 'sem_restante_por_contratar: restante %; lance o adiantamento dentro de um contrato', v_total - v_used - v_free;
  END IF;
  v_alloc := public._cache_alloc(p_amount, v_caps, v_absorber);
  FOR i IN 1..v_n LOOP
    SELECT coalesce(sum(cc.quota),0) + coalesce((SELECT sum(amount) FROM public._cache_free_advances(v_root, p_artist_supplier_id) WHERE event_id = v_events[i]),0)
      INTO v_city FROM public.cache_payment_contract_cities cc JOIN public.cache_payment_contracts k ON k.id = cc.contract_id
     WHERE k.root_event_id = v_root AND k.artist_supplier_id = p_artist_supplier_id AND k.cancelled_at IS NULL AND cc.event_id = v_events[i];
    IF v_city + v_alloc[i] > v_caps[i] + 0.005 THEN RAISE EXCEPTION 'teto_cidade_excedido: %', v_names[i]; END IF;
  END LOOP;
  v_desc := coalesce(nullif(trim(p_description),''), 'Adiantamento cachê ' || coalesce((SELECT name FROM public.suppliers WHERE id = p_artist_supplier_id),''));
  INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, supplier_id, date, due_date, status, paid_amount,
      split_mode, company_id, cache_role, cache_root_event_id, cache_artist_supplier_id, operation_key)
  VALUES (v_desc, 'expense', p_amount, 0, NULL, v_cat, coalesce(p_supplier_id, p_artist_supplier_id), v_today, p_due_date, 'approved', 0,
      'percentage', v_company, 'advance', v_root, p_artist_supplier_id, CASE WHEN p_idempotency_key IS NOT NULL THEN 'cache_adv:' || p_idempotency_key END)
  RETURNING id INTO v_mother;
  FOR i IN 1..v_n LOOP IF i <> v_absorber AND v_alloc[i] > 0 THEN v_acc := v_acc + round(v_alloc[i]/p_amount*100,4); END IF; END LOOP;
  FOR i IN 1..v_n LOOP
    IF v_alloc[i] > 0 THEN
      INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, date, due_date, status,
          paid_amount, parent_transaction_id, split_percentage, split_mode, company_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
      VALUES (v_desc, 'expense', v_alloc[i], 0, v_events[i], v_cat, v_lines[i], coalesce(p_supplier_id, p_artist_supplier_id), v_today, p_due_date,
          'approved', 0, v_mother, CASE WHEN i = v_absorber THEN 100 - v_acc ELSE round(v_alloc[i]/p_amount*100,4) END,
          'percentage', v_company, 'advance', v_root, p_artist_supplier_id);
    END IF;
  END LOOP;
  RETURN v_mother;
END $function$

CREATE OR REPLACE FUNCTION public.create_cache_payment_contract(p_event_id uuid, p_artist_supplier_id uuid, p_beneficiary_supplier_id uuid, p_gross numeric, p_withholding_applies boolean, p_withholding_rate numeric, p_withholding_due_date date, p_artist_due_date date, p_advance_ids uuid[] DEFAULT '{}'::uuid[], p_label text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_line_choices jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._cache_assert_actor(); v_root uuid; v_company uuid; v_cid uuid;
BEGIN
  PERFORM set_config('cache.line_choices', coalesce(p_line_choices::text, ''), true);
  SELECT coalesce(parent_event_id, id), company_id INTO v_root, v_company FROM public.events WHERE id = p_event_id;
  IF v_root IS NULL OR v_company <> public.current_company_id() THEN RAISE EXCEPTION 'evento_inexistente'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('cache:' || v_root || ':' || p_artist_supplier_id, 0));
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_cid FROM public.cache_payment_contracts WHERE company_id = v_company AND idempotency_key = p_idempotency_key;
    IF FOUND THEN RETURN v_cid; END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public._cache_resolve_lines(v_root, p_artist_supplier_id, p_line_choices)) THEN
    RAISE EXCEPTION 'sem_linha_cache: não há linha de cachê (2.1.01) no BP desta cidade. Crie-a no BP ou configure o cachê.';
  END IF;
  PERFORM public._cache_assert_lines(v_root, p_artist_supplier_id, p_line_choices);
  IF EXISTS (SELECT 1 FROM public._cache_cities_x(v_root, p_artist_supplier_id, p_line_choices) x WHERE x.source = 'config' AND NOT x.frozen) THEN
    RAISE EXCEPTION 'cache_nao_congelado: Congele primeiro o cachê no modal; só depois pode criar o contrato de pagamento.';
  END IF;
  RETURN public._cache_create_contract(v_uid, v_root, p_artist_supplier_id, p_beneficiary_supplier_id, p_gross,
    p_withholding_applies, p_withholding_rate, p_withholding_due_date, p_artist_due_date, p_advance_ids, p_label, p_idempotency_key);
END $function$

CREATE OR REPLACE FUNCTION public.create_settlement_transfer(p_settlement_id uuid, p_from_account_id uuid, p_to_account_id uuid, p_amount numeric, p_date date, p_credited boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_settlement record;
  v_from_name text;
  v_to_name text;
  v_key text;
  v_desc text;
  v_out uuid;
  v_status text;
  v_paid numeric;
  v_pay_date date;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    IF NOT (
      public.has_role(auth.uid(), 'admin')
      OR public.is_platform_admin(auth.uid())
      OR public.has_permission(auth.uid(), 'manage_accounts')
    ) THEN
      RAISE EXCEPTION 'Sem permissão para lançar a transferência do fecho' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_settlement FROM public.ticket_office_settlements WHERE id = p_settlement_id;

  IF v_settlement.id IS NULL THEN
    RAISE EXCEPTION 'Fecho não encontrado' USING ERRCODE = 'no_data_found';
  END IF;
  IF v_settlement.company_id IS DISTINCT FROM v_company THEN
    RAISE EXCEPTION 'Fecho de outra empresa' USING ERRCODE = '42501';
  END IF;
  IF v_settlement.transfer_transaction_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este fecho já tem transferência lançada' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Valor da transferência tem de ser positivo' USING ERRCODE = '22023';
  END IF;
  IF p_from_account_id IS NULL OR p_to_account_id IS NULL THEN
    RAISE EXCEPTION 'Contas de origem e destino são obrigatórias' USING ERRCODE = '22023';
  END IF;
  IF p_from_account_id = p_to_account_id THEN
    RAISE EXCEPTION 'Conta de origem e destino não podem ser a mesma' USING ERRCODE = '22023';
  END IF;

  SELECT name INTO v_from_name FROM public.financial_accounts WHERE id = p_from_account_id;
  SELECT name INTO v_to_name FROM public.financial_accounts WHERE id = p_to_account_id;

  v_key := 'TRF-FECHO-' || upper(substring(replace(p_settlement_id::text, '-', '') FROM 1 FOR 8));
  v_desc := 'Transferência fecho bilheteira ' || coalesce(v_from_name, '?')
            || ' -> ' || coalesce(v_to_name, '?')
            || CASE WHEN p_credited THEN '' ELSE ' (a receber)' END;

  IF p_credited THEN
    v_status := 'paid'; v_paid := p_amount; v_pay_date := p_date;
  ELSE
    v_status := 'pending'; v_paid := 0; v_pay_date := NULL;
  END IF;

  INSERT INTO public.transactions (
    company_id, event_id, type, category_id, description, amount, iva_rate, date,
    status, paid_amount, payment_date, account_id, payment_method,
    exclude_from_result, currency, settlement_id, operation_key
  ) VALUES (
    v_company, v_settlement.event_id, 'expense', 'b32df086-c995-4747-a3f9-bfefa0063d0a',
    v_desc, p_amount, 0, p_date,
    v_status, v_paid, v_pay_date, p_from_account_id, 'transfer',
    true, 'EUR', p_settlement_id, v_key
  ) RETURNING id INTO v_out;

  INSERT INTO public.transactions (
    company_id, event_id, type, category_id, description, amount, iva_rate, date,
    status, paid_amount, payment_date, account_id, payment_method,
    exclude_from_result, currency, settlement_id, operation_key
  ) VALUES (
    v_company, v_settlement.event_id, 'income', 'b32df086-c995-4747-a3f9-bfefa0063d0a',
    v_desc, p_amount, 0, p_date,
    v_status, v_paid, v_pay_date, p_to_account_id, 'transfer',
    true, 'EUR', NULL, v_key
  );

  UPDATE public.ticket_office_settlements
  SET transfer_transaction_id = v_out,
      net_transferred = p_amount,
      transfer_account_id = p_to_account_id
  WHERE id = p_settlement_id;

  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_transaction_cascade(p_transaction_id uuid, p_reason text DEFAULT NULL::text, p_cascade_invoice_group boolean DEFAULT true, p_caller_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_caller text;
  v_group uuid;
  v_roots uuid[];
  v_children uuid[];
  v_all uuid[];
  v_reason text;
  v_tx record;
  v_n int;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão em falta' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_role(v_uid, 'admin') OR public.has_role(v_uid, 'manager') OR public.is_platform_admin()) THEN
    RAISE EXCEPTION 'Sem permissão para eliminar transações (só admin ou manager).' USING ERRCODE = '42501';
  END IF;
  v_caller := coalesce(nullif(trim(p_caller_name), ''), v_uid::text);

  SELECT invoice_group_id INTO v_group FROM transactions WHERE id = p_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transação não encontrada' USING ERRCODE = 'P0002'; END IF;

  IF p_cascade_invoice_group AND v_group IS NOT NULL THEN
    SELECT array_agg(id) INTO v_roots FROM transactions WHERE invoice_group_id = v_group OR id = p_transaction_id;
  ELSE
    v_roots := ARRAY[p_transaction_id];
  END IF;

  PERFORM 1 FROM transactions WHERE id = ANY(v_roots) FOR UPDATE;
  IF EXISTS (SELECT 1 FROM transactions WHERE id = ANY(v_roots) AND NOT public.row_belongs_to_current_company(company_id)) THEN
    RAISE EXCEPTION 'Transação de outra empresa' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg(id), '{}') INTO v_children FROM transactions WHERE parent_transaction_id = ANY(v_roots) AND NOT (id = ANY(v_roots));
  v_all := v_roots || v_children;
  v_reason := CASE WHEN array_length(v_roots, 1) > 1
    THEN coalesce(p_reason || ' · ', '') || 'Grupo fatura (' || array_length(v_roots, 1) || ' linhas IVA)'
    ELSE p_reason END;

  -- Lixo: uma entrada por raiz, com as próprias filhas.
  INSERT INTO trash (entity_type, entity_id, entity_data, related_data, deleted_by, company_id)
  SELECT 'transaction', r.id, to_jsonb(r),
         (SELECT jsonb_build_object('transactions', jsonb_agg(to_jsonb(c))) FROM transactions c WHERE c.parent_transaction_id = r.id),
         v_caller, r.company_id
    FROM transactions r WHERE r.id = ANY(v_roots);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('trash', v_n);

  UPDATE event_forecasts SET transaction_id = NULL WHERE transaction_id = ANY(v_all) AND version_id IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('event_forecasts', v_n);
  UPDATE event_cache_payments SET transaction_id = NULL WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('cache_payments', v_n);
  UPDATE event_cache_payments SET withholding_transaction_id = NULL WHERE withholding_transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('cache_withholding', v_n);
  UPDATE ticket_office_settlements SET transfer_transaction_id = NULL WHERE transfer_transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('settlements', v_n);
  UPDATE reimbursement_notes SET payment_transaction_id = NULL WHERE payment_transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('reimbursement_notes', v_n);

  DELETE FROM payment_list_items WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('payment_list_items', v_n);
  DELETE FROM reimbursement_note_items WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('reimbursement_note_items', v_n);
  DELETE FROM partner_paid_expenses WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('partner_paid_expenses', v_n);
  DELETE FROM partner_advance_expenses WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('partner_advance_expenses', v_n);
  DELETE FROM supplier_credit_usages WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('supplier_credit_usages', v_n);
  DELETE FROM transaction_payments WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('transaction_payments', v_n);
  DELETE FROM transaction_documents WHERE transaction_id = ANY(v_all);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('transaction_documents', v_n);

  -- Auditoria (fica em system_audit_log; transaction_audit_log desaparece com a transação).
  FOR v_tx IN SELECT * FROM transactions WHERE id = ANY(v_all) LOOP
    INSERT INTO system_audit_log (entity_type, entity_id, action, changed_by, old_data, metadata, company_id)
    VALUES ('transaction', v_tx.id::text, 'delete', v_caller, to_jsonb(v_tx),
            jsonb_build_object('reason', v_reason, 'root', v_tx.id = ANY(v_roots), 'rpc', 'delete_transaction_cascade',
                               'invoice_group_size', array_length(v_roots, 1)),
            v_tx.company_id);
  END LOOP;

  DELETE FROM transactions WHERE id = ANY(v_children);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('children', v_n);
  DELETE FROM transactions WHERE id = ANY(v_roots);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('roots', v_n);
  IF v_n <> array_length(v_roots, 1) THEN
    RAISE EXCEPTION 'Eliminação incompleta: % de % transações' , v_n, array_length(v_roots, 1);
  END IF;

  RETURN jsonb_build_object('root_ids', to_jsonb(v_roots), 'child_ids', to_jsonb(v_children), 'counts', v_counts);
END $function$

CREATE OR REPLACE FUNCTION public.discard_bp_version_draft(_version_id uuid, _performed_by uuid DEFAULT NULL::uuid, _performed_by_label text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version RECORD; v_non_scenario_cascades int;
BEGIN
  -- D-ERP38: portao de permissao e isolamento de empresa.
  DECLARE
    v_uid uuid := auth.uid();
    v_company uuid;
  BEGIN
    -- auth.uid() NULL = service_role / cron / edge function: isencao deliberada,
    -- mesmo padrao de enforce_transaction_approval_permission.
    IF v_uid IS NOT NULL THEN
      IF NOT (public.is_platform_admin(v_uid)
              OR public.has_role(v_uid, 'admin'::app_role)
              OR public.has_permission(v_uid, 'manage_bp')) THEN
        RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
      END IF;
      IF NOT public.is_platform_admin(v_uid) THEN
        SELECT e.company_id INTO v_company FROM public.bp_versions v JOIN public.events e ON e.id = v.event_id WHERE v.id = _version_id;
        IF v_company IS NULL OR v_company IS DISTINCT FROM public.current_company_id() THEN
          RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;
  END;
  -- D-ERP38: autoria nao forjavel. Com utilizador, ignora o parametro recebido;
  -- com auth.uid() NULL (service_role) usa-se o parametro como antes.
  _performed_by := COALESCE(auth.uid(), _performed_by);
  SELECT * INTO v_version FROM public.bp_versions WHERE id = _version_id;
  IF v_version IS NULL THEN RAISE EXCEPTION 'Version % not found', _version_id; END IF;
  IF v_version.state <> 'draft' THEN RAISE EXCEPTION 'Apenas rascunhos podem ser descartados (estado atual: %)', v_version.state; END IF;
  SELECT COUNT(*) INTO v_non_scenario_cascades FROM public.bp_versions
   WHERE cascaded_from_version_id = _version_id AND state <> 'draft';
  IF v_non_scenario_cascades > 0 THEN
    RAISE EXCEPTION 'Não é possível descartar: existem % versão(ões) ativas/superseded em Splits que descendem deste rascunho.', v_non_scenario_cascades USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata)
  VALUES (_version_id, v_version.event_id, 'discarded', _performed_by, _performed_by_label,
    jsonb_build_object('version_number', v_version.version_number, 'scenario_label', v_version.scenario_label,
      'is_scenario', v_version.scenario_label IS NOT NULL));
  DELETE FROM public.bp_versions WHERE cascaded_from_version_id = _version_id AND state = 'draft';
  DELETE FROM public.bp_versions WHERE id = _version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.eaba_enforce_max_attachments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  SELECT count(*) INTO v_count
  FROM public.event_ab_attachments
  WHERE event_id = NEW.event_id;
  IF v_count >= 20 THEN
    RAISE EXCEPTION 'O separador A&B suporta no máximo 20 anexos por evento.';
  END IF;
  RETURN NEW;
END;
$function$

