CREATE OR REPLACE FUNCTION public.enforce_event_close_blockers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_blockers jsonb;
  v_cam jsonb;
  v_card jsonb;
  v_cam_n int;
  v_card_n int;
  v_card_list text;
  v_cam_list text;
BEGIN
  IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' THEN
    v_blockers := public.event_close_blockers(NEW.id);
    v_cam := v_blockers -> 'hard' -> 'camarim_sessions';
    v_card := v_blockers -> 'hard' -> 'card_sessions';
    v_cam_n := jsonb_array_length(COALESCE(v_cam, '[]'::jsonb));
    v_card_n := jsonb_array_length(COALESCE(v_card, '[]'::jsonb));

    IF v_cam_n > 0 OR v_card_n > 0 THEN
      SELECT string_agg(
               COALESCE(e ->> 'holder_name', 'sem portador')
               || COALESCE(' · ' || (e ->> 'card_name'), ''), '; ')
        INTO v_card_list
        FROM jsonb_array_elements(COALESCE(v_card, '[]'::jsonb)) e;

      SELECT string_agg(COALESCE(e ->> 'title', 'sessão'), '; ')
        INTO v_cam_list
        FROM jsonb_array_elements(COALESCE(v_cam, '[]'::jsonb)) e;

      RAISE EXCEPTION
        'Não é possível fechar o evento: % sessão(ões) de cartão aberta(s)%; % sessão(ões) de camarim por integrar%.',
        v_card_n,
        CASE WHEN v_card_n > 0 THEN ' (' || v_card_list || ')' ELSE '' END,
        v_cam_n,
        CASE WHEN v_cam_n > 0 THEN ' (' || v_cam_list || ')' ELSE '' END
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_event_reopen_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Só morde ao SAIR de 'completed'. Fechar continua guardado pelo
  -- enforce_event_close_blockers, que não se toca.
  IF OLD.status IS DISTINCT FROM 'completed' OR NEW.status = 'completed' THEN
    RETURN NEW;
  END IF;

  -- crons, syncs e edge functions com service_role: sem identidade de utilizador.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT (
    public.is_platform_admin()
    OR public.has_permission_in(auth.uid(), 'reopen_event', NEW.company_id)
  ) THEN
    RAISE EXCEPTION 'Sem permissao para reabrir um evento concluido.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_forecast_tx_same_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_event uuid;
  v_tx_company uuid;
  v_tx_found boolean := false;
  v_tx_ev_name text;
  v_fc_ev_name text;
BEGIN
  IF NEW.transaction_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.transaction_id IS NOT DISTINCT FROM NEW.transaction_id THEN RETURN NEW; END IF;
  IF NEW.version_id IS NOT NULL THEN RETURN NEW; END IF;

  SELECT t.event_id, t.company_id, true
    INTO v_tx_event, v_tx_company, v_tx_found
    FROM public.transactions t WHERE t.id = NEW.transaction_id;

  IF NOT COALESCE(v_tx_found, false) THEN RETURN NEW; END IF;

  IF public.bp_tx_link_allowed(v_tx_event, v_tx_company, NEW.event_id, NEW.company_id) THEN
    RETURN NEW;
  END IF;

  SELECT name INTO v_tx_ev_name FROM public.events WHERE id = v_tx_event;
  SELECT name INTO v_fc_ev_name FROM public.events WHERE id = NEW.event_id;

  RAISE EXCEPTION 'Vínculo recusado: a transação pertence ao evento "%" e a linha do Business Plan ao evento "%". Uma linha de BP só pode ser vinculada a transações do mesmo evento (ou sem evento, no desenho master/subeventos) e da mesma empresa.',
    COALESCE(v_tx_ev_name, '(sem evento)'), COALESCE(v_fc_ev_name, '(sem evento)');
END $function$

CREATE OR REPLACE FUNCTION public.ensure_camarim_advance_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_acc_id uuid;
  v_name text;
BEGIN
  IF NEW.advance_account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_name := 'Camarim · ' || COALESCE(NEW.title, NEW.id::text);

  INSERT INTO public.financial_accounts (
    name, type, description, initial_balance,
    is_active, balance_visible_to_all, is_hidden,
    skip_balance_check, company_id
  ) VALUES (
    left(v_name, 200),
    'camarim_session',
    'Conta-corrente automática da sessão de camarim ' || NEW.id::text,
    0,
    true,
    false,
    true,        -- oculta dos seletores globais
    true,        -- não bloquear por saldo negativo temporário
    NEW.company_id
  )
  RETURNING id INTO v_acc_id;

  NEW.advance_account_id := v_acc_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.event_bp_evolution(_event_id uuid, _from date DEFAULT NULL::date, _to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_audit_from constant timestamptz := '2026-06-17'::timestamptz;
  v_company uuid;
  v_to date;
  v_from date;
  v_day date;
  r record;
  v_state jsonb := '{}'::jsonb;
  v_days jsonb := '[]'::jsonb;
  v_series jsonb;
  v_origin jsonb;
  v_markers jsonb;
  v_old_amt numeric;
  v_new_amt numeric;
  v_k text;
BEGIN
  SELECT e.company_id INTO v_company FROM public.events e WHERE e.id = _event_id;
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Evento não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.is_platform_admin(auth.uid())
    OR public.has_permission_in(auth.uid(), 'view_bp', v_company)
    OR public.user_has_event_access(auth.uid(), _event_id)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para consultar a evolução do BP deste evento.' USING ERRCODE = '42501';
  END IF;

  v_to := LEAST(COALESCE(_to, current_date), current_date);
  v_from := GREATEST(COALESCE(_from, v_to - 89), v_audit_from::date);
  IF v_from > v_to THEN v_from := v_to; END IF;

  SELECT COALESCE(jsonb_object_agg(t.category_id::text, t.amt), '{}'::jsonb) INTO v_state
  FROM (
    SELECT f.category_id, SUM(COALESCE(f.amount, 0)) AS amt
    FROM public.event_forecasts f
    WHERE f.event_id = _event_id
      AND f.version_id IS NULL
      AND f.type = 'expense'
      AND f.category_id IS NOT NULL
    GROUP BY f.category_id
  ) t;

  v_day := current_date;

  FOR r IN
    SELECT l.created_at,
           l.action,
           NULLIF(l.old_data->>'category_id','')::uuid AS old_cat,
           NULLIF(l.new_data->>'category_id','')::uuid AS new_cat,
           NULLIF(l.old_data->>'amount','')::numeric   AS old_amount,
           NULLIF(l.new_data->>'amount','')::numeric   AS new_amount,
           (l.old_data->>'type') AS old_type,
           (l.new_data->>'type') AS new_type,
           (l.old_data->>'version_id') AS old_version,
           (l.new_data->>'version_id') AS new_version
    FROM public.system_audit_log l
    WHERE l.entity_type = 'event_forecasts'
      AND COALESCE(l.new_data->>'event_id', l.old_data->>'event_id') = _event_id::text
      AND l.created_at >= v_audit_from
    ORDER BY l.created_at DESC
  LOOP
    WHILE v_day >= v_from AND r.created_at < (v_day + 1)::timestamptz LOOP
      IF v_day <= v_to THEN
        v_days := v_days || jsonb_build_object('day', v_day, 'state', v_state);
      END IF;
      v_day := v_day - 1;
    END LOOP;
    EXIT WHEN v_day < v_from;

    v_old_amt := COALESCE(r.old_amount, 0);
    v_new_amt := COALESCE(r.new_amount, 0);

    IF r.action IN ('create','update') AND r.new_cat IS NOT NULL
       AND r.new_type = 'expense' AND r.new_version IS NULL THEN
      v_k := r.new_cat::text;
      v_state := jsonb_set(v_state, ARRAY[v_k],
        to_jsonb(COALESCE((v_state->>v_k)::numeric, 0) - v_new_amt), true);
    END IF;

    IF r.action IN ('delete','update') AND r.old_cat IS NOT NULL
       AND r.old_type = 'expense' AND r.old_version IS NULL THEN
      v_k := r.old_cat::text;
      v_state := jsonb_set(v_state, ARRAY[v_k],
        to_jsonb(COALESCE((v_state->>v_k)::numeric, 0) + v_old_amt), true);
    END IF;
  END LOOP;

  WHILE v_day >= v_from LOOP
    IF v_day <= v_to THEN
      v_days := v_days || jsonb_build_object('day', v_day, 'state', v_state);
    END IF;
    v_day := v_day - 1;
  END LOOP;

  -- série montada num único passo (dia × rubrica L3)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'day', d.day,
           'l3_code', c.code,
           'l3_name', c.name,
           'l2_code', p2.code,
           'l1_code', p1.code,
           'amount', round(e.v::numeric, 2)
         ) ORDER BY d.day, c.code), '[]'::jsonb) INTO v_series
  FROM jsonb_array_elements(v_days) AS x
  CROSS JOIN LATERAL (SELECT (x->>'day')::date AS day, x->'state' AS state) d
  CROSS JOIN LATERAL jsonb_each_text(d.state) AS e(k, v)
  JOIN public.account_categories c ON c.id = e.k::uuid
  LEFT JOIN public.account_categories p2 ON p2.id = c.parent_id
  LEFT JOIN public.account_categories p1 ON p1.id = p2.parent_id
  WHERE round(e.v::numeric, 2) <> 0;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'l3_code'), '[]'::jsonb) INTO v_origin
  FROM (
    SELECT jsonb_build_object(
             'l3_code', c.code, 'l3_name', c.name,
             'l2_code', p2.code, 'l1_code', p1.code,
             'amount', round(SUM(COALESCE(f.baseline_amount, f.amount, 0)), 2)
           ) AS x
    FROM public.event_forecasts f
    JOIN public.account_categories c ON c.id = f.category_id
    LEFT JOIN public.account_categories p2 ON p2.id = c.parent_id
    LEFT JOIN public.account_categories p1 ON p1.id = p2.parent_id
    WHERE f.event_id = _event_id AND f.version_id IS NULL AND f.type = 'expense'
    GROUP BY c.code, c.name, p2.code, p1.code
  ) q;

  SELECT COALESCE(jsonb_agg(m ORDER BY m->>'at'), '[]'::jsonb) INTO v_markers
  FROM (
    SELECT jsonb_build_object(
             'kind', 'version', 'at', v.created_at,
             'label', 'Versão ' || v.version_number,
             'total', (
               SELECT round(COALESCE(SUM(COALESCE((fx->>'amount')::numeric, 0)), 0), 2)
               FROM jsonb_array_elements(COALESCE(v.snapshot_payload->'forecasts', '[]'::jsonb)) fx
               WHERE fx->>'type' = 'expense'
             )
           ) AS m
    FROM public.bp_versions v
    WHERE v.event_id = _event_id AND v.state IN ('active','superseded')
    UNION ALL
    -- #122: field_name = 'Elevação de verba' distingue a elevação (D2) de uma edição anotada.
    SELECT jsonb_build_object(
             'kind', CASE WHEN a.field_name = 'Elevação de verba' THEN 'budget_raise' WHEN a.field_name = 'Redução de verba' THEN 'budget_reduction' ELSE 'annotated_change' END,
             'at', a.created_at,
             'label', a.observation, 'total', NULL
           ) AS m
    FROM public.forecast_audit_log a
    JOIN public.event_forecasts f ON f.id = a.forecast_id
    WHERE f.event_id = _event_id AND f.type = 'expense'
      AND a.observation IS NOT NULL AND btrim(a.observation) <> ''
      AND a.created_at >= v_audit_from
  ) q2;

  RETURN jsonb_build_object(
    'series', v_series,
    'origin', v_origin,
    'markers', v_markers,
    'audit_from', to_char(v_audit_from, 'YYYY-MM-DD'),
    'from', v_from,
    'to', v_to
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.event_budget_mode(_event_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_company uuid;
  v_mode text;
BEGIN
  SELECT e.company_id, COALESCE(e.budget_mode, c.default_budget_mode, 'with_bp')
    INTO v_company, v_mode
  FROM public.events e
  JOIN public.companies c ON c.id = e.company_id
  WHERE e.id = _event_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Isenção deliberada: sem identidade de utilizador (service_role, crons,
  -- edge functions, syncs) passa sem verificar. Não "corrigir" isto.
  IF v_uid IS NOT NULL
     AND NOT public.is_platform_admin(v_uid)
     AND v_company IS DISTINCT FROM public.current_company_id() THEN
    RAISE EXCEPTION 'Evento de outra empresa.' USING ERRCODE = '42501';
  END IF;

  RETURN v_mode;
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_supplier_credits()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
  -- D-ERP38: portao de permissao. Normalmente corre por cron como
  -- service_role (auth.uid() NULL) - isencao deliberada.
  DECLARE
    v_uid uuid := auth.uid();
  BEGIN
    IF v_uid IS NOT NULL AND NOT (public.is_platform_admin(v_uid)
        OR public.has_role(v_uid, 'admin'::app_role)
        OR public.has_permission(v_uid, 'manage_bp')) THEN
      RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
    END IF;
  END;
  UPDATE public.supplier_credits
     SET status = 'expired', updated_at = now()
   WHERE status = 'active'
     AND valid_until IS NOT NULL
     AND valid_until < current_date;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_leads_geo_stats(p_period text DEFAULT 'all'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid := public.current_company_id();
  v_since timestamptz := NULL;
  v_total int := 0;
  v_by_country jsonb;
  v_by_city jsonb;
BEGIN
  IF v_company IS NULL THEN
    RETURN jsonb_build_object('total', 0, 'by_country', '[]'::jsonb, 'by_city', '[]'::jsonb);
  END IF;

  IF p_period = '30d' THEN
    v_since := now() - interval '30 days';
  END IF;

  SELECT count(*) INTO v_total
  FROM public.leads l
  WHERE l.company_id = v_company
    AND (v_since IS NULL OR l.created_at >= v_since);

  SELECT coalesce(jsonb_agg(jsonb_build_object('key', key, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_country
  FROM (
    SELECT
      CASE WHEN l.geo_country IS NULL OR btrim(l.geo_country) = '' THEN '__none__'
           ELSE upper(btrim(l.geo_country)) END AS key,
      count(*)::int AS cnt
    FROM public.leads l
    WHERE l.company_id = v_company
      AND (v_since IS NULL OR l.created_at >= v_since)
    GROUP BY 1
  ) t;

  SELECT coalesce(jsonb_agg(jsonb_build_object('key', key, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
  INTO v_by_city
  FROM (
    SELECT
      CASE WHEN l.geo_city IS NULL OR btrim(l.geo_city) = '' THEN '__none__'
           ELSE btrim(l.geo_city) END AS key,
      count(*)::int AS cnt
    FROM public.leads l
    WHERE l.company_id = v_company
      AND (v_since IS NULL OR l.created_at >= v_since)
    GROUP BY 1
  ) t;

  RETURN jsonb_build_object(
    'total', v_total,
    'by_country', v_by_country,
    'by_city', v_by_city
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_event_shares(p_event_id uuid, p_settlement_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(partner_name text, percentage numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sup uuid;
  v_node uuid := p_settlement_id;
  v_own numeric;
  v_house numeric;
  v_others numeric;
BEGIN
  IF auth.uid() IS NULL OR NOT public.user_has_event_access(auth.uid(), p_event_id) THEN
    RETURN;
  END IF;

  IF public.has_staff_role(auth.uid()) THEN
    RETURN QUERY
      SELECT COALESCE(s.name, CASE WHEN p.participant_kind = 'house' THEN 'MUNDO PROPÍCIO' ELSE 'Sócio' END)::text,
             SUM(p.profit_pct)::numeric
      FROM public.event_settlement_participants p
      LEFT JOIN public.suppliers s ON s.id = p.supplier_id
      WHERE p.event_id = p_event_id
        AND p.mode = 'settles'
        AND (v_node IS NULL OR p.settlement_id = v_node)
      GROUP BY 1
      ORDER BY 2 DESC NULLS LAST, 1;
    RETURN;
  END IF;

  v_sup := public.user_supplier_id(auth.uid());
  IF v_sup IS NULL THEN RETURN; END IF;

  IF v_node IS NULL THEN
    SELECT settlement_id INTO v_node
      FROM public.get_partner_visible_settlements(p_event_id) LIMIT 1;
  END IF;
  IF v_node IS NULL THEN RETURN; END IF;

  SELECT COALESCE(SUM(p.profit_pct), 0) INTO v_own
  FROM public.event_settlement_participants p
  WHERE p.settlement_id = v_node AND p.event_id = p_event_id
    AND p.mode = 'settles' AND p.supplier_id = v_sup;

  IF v_own = 0 THEN RETURN; END IF;

  RETURN QUERY
    SELECT COALESCE(s.name, 'Sócio')::text, v_own
    FROM public.suppliers s WHERE s.id = v_sup;

  IF v_own >= 100 THEN RETURN; END IF;

  SELECT COALESCE(SUM(CASE WHEN p.participant_kind = 'house' THEN p.profit_pct ELSE 0 END), 0),
         COALESCE(SUM(CASE WHEN p.participant_kind <> 'house' THEN p.profit_pct ELSE 0 END), 0)
    INTO v_house, v_others
  FROM public.event_settlement_participants p
  WHERE p.settlement_id = v_node AND p.event_id = p_event_id
    AND p.mode = 'settles' AND COALESCE(p.supplier_id, '00000000-0000-0000-0000-000000000000') <> v_sup;

  IF v_others = 0 THEN
    RETURN QUERY SELECT 'MUNDO PROPÍCIO'::text, (100 - v_own)::numeric;
  ELSE
    RETURN QUERY SELECT 'Sócios locais'::text, (100 - v_own)::numeric;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_settlement_summary(_event_id uuid, _settlement_id uuid, _partner_share numeric DEFAULT 0, _transfer_with_vat boolean DEFAULT false)
 RETURNS TABLE(partner_share numeric, disbursement numeric, adjustments numeric, revenues_held numeric, extras numeric, transfer_base numeric, transfer_vat numeric, transfer_total numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_supplier uuid;
  v_gross boolean := false;
  v_ids uuid[];
  v_pids uuid[];
  v_disb numeric := 0;
  v_adj numeric := 0;
  v_held numeric := 0;
  v_extras numeric := 0;
  v_base numeric := 0;
  v_vat numeric := 0;
BEGIN
  v_supplier := public.user_supplier_id(auth.uid());
  IF v_supplier IS NULL THEN RETURN; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.event_settlement_participants sp
    WHERE sp.settlement_id = _settlement_id
      AND sp.event_id = _event_id
      AND sp.mode = 'settles'
      AND sp.supplier_id = v_supplier
  ) THEN
    RETURN;
  END IF;

  SELECT (s.doc_locale = 'pt-BR') INTO v_gross FROM public.suppliers s WHERE s.id = v_supplier;

  SELECT array_agg(e.id) INTO v_ids
  FROM public.events e
  WHERE e.id = _event_id OR e.parent_event_id = _event_id;

  SELECT array_agg(x) INTO v_pids
  FROM public.user_event_partner_ids(auth.uid(), v_ids) x;
  v_pids := COALESCE(v_pids, ARRAY[]::uuid[]);

  SELECT COALESCE(SUM(t.amount * CASE WHEN v_gross THEN 1 + COALESCE(t.iva_rate, 0) / 100.0 ELSE 1 END), 0)
    INTO v_disb
  FROM public.partner_paid_expenses ppe
  JOIN public.transactions t ON t.id = ppe.transaction_id
  WHERE ppe.partner_id = ANY (v_pids) AND ppe.event_id = ANY (v_ids);

  SELECT v_disb + COALESCE(SUM(f.amount * CASE WHEN v_gross THEN 1 + COALESCE(f.iva_rate, 0) / 100.0 ELSE 1 END), 0)
    INTO v_disb
  FROM public.event_forecasts f
  WHERE f.paying_partner_id = ANY (v_pids)
    AND f.event_id = ANY (v_ids)
    AND f.type = 'expense'
    AND f.status = 'approved'
    AND f.version_id IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.partner_paid_expenses ppe2
      WHERE ppe2.transaction_id = f.transaction_id AND ppe2.partner_id = ANY (v_pids)
    );

  SELECT
    COALESCE(SUM(CASE WHEN x.kind = 'disbursement_adjustment' THEN x.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN x.kind = 'extra' THEN x.amount ELSE 0 END), 0)
    INTO v_adj, v_extras
  FROM public.event_partner_extras x
  WHERE x.partner_id = ANY (v_pids) AND x.event_id = ANY (v_ids);

  SELECT COALESCE(SUM(t.amount), 0) INTO v_held
  FROM public.transactions t
  JOIN public.financial_accounts fa ON fa.id = t.account_id
  WHERE fa.partner_id = ANY (v_pids)
    AND t.event_id = ANY (v_ids)
    AND t.type = 'income'
    AND t.reversed_at IS NULL
    AND t.status IN ('paid', 'approved');

  SELECT v_held + COALESCE(SUM(o.operator_result), 0) INTO v_held
  FROM public.event_third_party_operations o
  WHERE o.held_by_supplier_id = v_supplier AND o.event_id = ANY (v_ids);

  SELECT v_held + COALESCE(SUM(t.amount), 0) INTO v_held
  FROM public.transactions t
  WHERE t.held_by_supplier_id = v_supplier
    AND t.event_id = ANY (v_ids)
    AND t.type = 'income'
    AND t.reversed_at IS NULL
    AND t.status IN ('paid', 'approved');

  v_base := ROUND(COALESCE(_partner_share, 0) + v_disb + v_adj - v_held - v_extras, 2);
  IF _transfer_with_vat AND v_base > 0 THEN
    v_vat := ROUND(v_base * 0.23, 2);
  END IF;

  RETURN QUERY SELECT
    ROUND(COALESCE(_partner_share, 0), 2),
    ROUND(v_disb, 2), ROUND(v_adj, 2), ROUND(v_held, 2), ROUND(v_extras, 2),
    v_base, v_vat, ROUND(v_base + v_vat, 2);
END;
$function$

CREATE OR REPLACE FUNCTION public.launch_from_bank_lines(p_items jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_tx jsonb;
  v_line_ids uuid[];
  v_all_ids uuid[] := '{}';
  v_company uuid;
  v_current uuid;
  v_n_lines int;
  v_n_found int;
  v_bad uuid;
  v_cols text[];
  v_key text;
  v_sql text;
  v_tx_id uuid;
  v_out uuid[] := '{}';
  v_matched_by text;
  v_note text;
  v_rows int;
  v_was_paid boolean;
  v_pay_amount numeric;
  v_gross numeric;
  v_pay_date date;
  v_pay_acc uuid;
  v_pay_method text;
  v_currency text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Nada a lançar: p_items tem de ser um array com pelo menos um item.';
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    if jsonb_typeof(v_item -> 'transaction') <> 'object' then
      raise exception 'Item sem objecto "transaction".';
    end if;
    if v_item ? 'line_ids' and jsonb_typeof(v_item -> 'line_ids') = 'array' then
      select v_all_ids || coalesce(array_agg((x)::uuid), '{}')
        into v_all_ids
        from jsonb_array_elements_text(v_item -> 'line_ids') x;
    end if;
  end loop;

  if array_length(v_all_ids, 1) is null then
    raise exception 'Nenhuma linha do banco indicada — o lançamento tem de ficar ligado ao extrato.';
  end if;

  v_n_lines := array_length(v_all_ids, 1);

  select count(*), count(distinct l.company_id), (array_agg(distinct l.company_id))[1]
    into v_n_found, v_rows, v_company
    from public.bank_statement_lines l
   where l.id = any(v_all_ids);

  if v_n_found <> v_n_lines then
    raise exception 'Linha(s) do banco inexistente(s) ou sem acesso: pedidas %, encontradas %.', v_n_lines, v_n_found;
  end if;
  if v_rows <> 1 or v_company is null then
    raise exception 'As linhas do banco não pertencem todas à mesma empresa.';
  end if;

  v_current := public.current_company_id();
  if v_current is null or v_current <> v_company then
    raise exception 'As linhas do banco pertencem a outra empresa (%) — empresa activa %.', v_company, v_current;
  end if;

  select l.id into v_bad
    from public.bank_statement_lines l
   where l.id = any(v_all_ids)
     and (l.status <> 'unmatched'
          or l.matched_transaction_id is not null
          or l.created_transaction_id is not null)
   limit 1;

  if v_bad is not null then
    raise exception 'Linha do banco já está conciliada: %', v_bad;
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_tx := v_item -> 'transaction';

    -- D-ERP157: nasce 'approved' sem valor pago; o pagamento nasce em transaction_payments.
    v_was_paid := (v_tx ->> 'status') = 'paid'
                  or coalesce(nullif(v_tx ->> 'paid_amount', '')::numeric, 0) > 0.01;
    v_pay_amount := nullif(coalesce(nullif(v_tx ->> 'paid_amount', '')::numeric, 0), 0);
    v_pay_method := nullif(v_tx ->> 'payment_method', '');
    v_tx := v_tx - 'paid_amount' - 'payment_date';
    if (v_tx ->> 'status') = 'paid' then
      v_tx := jsonb_set(v_tx, '{status}', '"approved"');
    end if;

    v_cols := '{}';
    for v_key in select k from jsonb_object_keys(v_tx) k loop
      if v_key in ('id', 'company_id', 'created_at', 'updated_at') then
        continue;
      end if;
      if not exists (
        select 1 from information_schema.columns c
         where c.table_schema = 'public' and c.table_name = 'transactions'
           and c.column_name = v_key
      ) then
        raise exception 'Coluna inexistente em transactions: %', v_key;
      end if;
      v_cols := v_cols || v_key;
    end loop;

    if array_length(v_cols, 1) is null then
      raise exception 'Item sem colunas válidas para transactions.';
    end if;

    v_sql := format(
      'insert into public.transactions (company_id, %s) select $2, %s from jsonb_populate_record(null::public.transactions, $1) r returning id',
      (select string_agg(quote_ident(c), ', ') from unnest(v_cols) c),
      (select string_agg('r.' || quote_ident(c), ', ') from unnest(v_cols) c)
    );
    execute v_sql into v_tx_id using v_tx, v_company;

    if v_tx_id is null then
      raise exception 'A transação não foi criada.';
    end if;
    v_out := v_out || v_tx_id;

    v_line_ids := '{}';
    if v_item ? 'line_ids' and jsonb_typeof(v_item -> 'line_ids') = 'array' then
      select coalesce(array_agg((x)::uuid), '{}') into v_line_ids
        from jsonb_array_elements_text(v_item -> 'line_ids') x;
    end if;

    if array_length(v_line_ids, 1) is not null then
      v_matched_by := coalesce(v_item ->> 'matched_by', 'created:sistema');
      v_note := nullif(v_item ->> 'note', '');

      update public.bank_statement_lines
         set status = 'matched',
             created_transaction_id = v_tx_id,
             matched_transaction_id = v_tx_id,
             matched_by = v_matched_by,
             matched_at = now(),
             note = v_note
       where id = any(v_line_ids);

      get diagnostics v_rows = row_count;
      if v_rows <> array_length(v_line_ids, 1) then
        raise exception 'Só % de % linhas do banco ficaram ligadas — nada fica gravado.', v_rows, array_length(v_line_ids, 1);
      end if;
    end if;

    if v_was_paid then
      select round((t.amount * (1 + coalesce(t.iva_rate, 0) / 100.0))::numeric, 2),
             coalesce(t.currency, 'EUR'), t.account_id, t.date
        into v_gross, v_currency, v_pay_acc, v_pay_date
        from public.transactions t where t.id = v_tx_id;

      if array_length(v_line_ids, 1) is not null then
        select max(coalesce(l.value_date, l.booking_date)),
               (array_agg(l.financial_account_id))[1]
          into v_pay_date, v_pay_acc
          from public.bank_statement_lines l
         where l.id = any(v_line_ids);
      end if;

      insert into public.transaction_payments
        (transaction_id, amount, payment_date, account_id, payment_method,
         status, closes_transaction, company_id, created_by, notes)
      values
        (v_tx_id, coalesce(v_pay_amount, v_gross), coalesce(v_pay_date, current_date),
         v_pay_acc,
         case when v_pay_acc is null then 'compensation'
              when v_pay_method in ('transfer','service_payment','direct_debit','state_payment') then v_pay_method
              else 'transfer' end,
         'paid', v_currency <> 'EUR', v_company,
         coalesce(auth.jwt() ->> 'email', 'sistema'),
         'Lançado a partir da linha do banco');
    end if;
  end loop;

  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION public.move_operacao_etapa(p_etapa_id uuid, p_new_frente_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_etapa RECORD;
  v_old_frente RECORD;
  v_new_frente RECORD;
  v_uid uuid := auth.uid();
  v_can_manage boolean;
  v_registros_moved int := 0;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  SELECT * INTO v_etapa FROM operacao_etapas WHERE id = p_etapa_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Etapa não encontrada';
  END IF;

  -- No-op
  IF v_etapa.frente_id = p_new_frente_id THEN
    RETURN jsonb_build_object('moved', false, 'etapa_id', p_etapa_id);
  END IF;

  SELECT * INTO v_old_frente FROM operacao_frentes WHERE id = v_etapa.frente_id;
  SELECT * INTO v_new_frente FROM operacao_frentes WHERE id = p_new_frente_id;
  IF v_new_frente.id IS NULL THEN
    RAISE EXCEPTION 'Frente de destino não existe';
  END IF;

  IF v_new_frente.company_id <> v_etapa.company_id THEN
    RAISE EXCEPTION 'Frente de destino pertence a outra empresa';
  END IF;

  IF v_new_frente.event_id <> v_old_frente.event_id THEN
    RAISE EXCEPTION 'Frente de destino pertence a outro evento';
  END IF;

  IF v_new_frente.type NOT IN ('zone','service') THEN
    RAISE EXCEPTION 'Frente de destino inválida (tipo)';
  END IF;

  -- Permissão: manage_operacao_etapas OU lead da origem OU lead do destino
  v_can_manage := has_permission(v_uid, 'manage_operacao_etapas')
               OR v_old_frente.current_lead_id = v_uid
               OR v_new_frente.current_lead_id = v_uid;

  IF NOT v_can_manage THEN
    RAISE EXCEPTION 'Sem permissão para mover esta etapa';
  END IF;

  -- Mover etapa
  UPDATE operacao_etapas
     SET frente_id = p_new_frente_id,
         zone_id = CASE WHEN v_new_frente.type = 'zone' THEN NULL ELSE zone_id END,
         updated_at = now()
   WHERE id = p_etapa_id;

  -- Mover registos (campo denormalizado NOT NULL)
  WITH upd AS (
    UPDATE operacao_registros
       SET frente_id = p_new_frente_id
     WHERE etapa_id = p_etapa_id
       AND frente_id <> p_new_frente_id
    RETURNING 1
  )
  SELECT count(*) INTO v_registros_moved FROM upd;

  RETURN jsonb_build_object(
    'moved', true,
    'etapa_id', p_etapa_id,
    'from_frente_id', v_old_frente.id,
    'to_frente_id', p_new_frente_id,
    'registros_moved', v_registros_moved
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_chamado_aberto()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid;
  v_target_event uuid := '5a1da5fb-3115-4ae3-af50-15ce1f869a5c'; -- Coala Festival Portugal 2026
  v_super_admin uuid := 'd8e502f7-9ceb-4dae-bd73-7291832d0d6f';  -- Pedro Neto
BEGIN
  IF NEW.kind <> 'chamado' THEN
    RETURN NEW;
  END IF;

  BEGIN
    SELECT event_id INTO v_event_id
      FROM public.operacao_frentes
      WHERE id = NEW.frente_id;

    IF v_event_id = v_target_event THEN
      PERFORM public.enqueue_whatsapp_notification(
        'chamado_ocorrencia',
        v_super_admin,
        '{}'::jsonb,
        v_event_id,
        'operacao_registro',
        NEW.id
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Notificação é secundária: nunca rebenta o INSERT do registo
    RAISE WARNING 'notify_chamado_aberto failed: %', SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_delete_processed_standalone_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.status <> 'new' THEN
    RAISE EXCEPTION 'Fatura avulsa processada não pode ser apagada. Reabre para "nova" primeiro.';
