CREATE OR REPLACE FUNCTION public.promote_scenario_to_active(_scenario_version_id uuid, _description text DEFAULT NULL::text, _performed_by uuid DEFAULT NULL::uuid, _performed_by_label text DEFAULT NULL::text, _force boolean DEFAULT false, _other_scenarios_actions jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scenario RECORD;
  v_event RECORD;
  v_now timestamptz := now();
  v_next_version int;
  v_new_version_id uuid;
  v_previous_active_id uuid;
  v_split RECORD;
  v_split_scenario RECORD;
  v_split_next_version int;
  v_split_new_version_id uuid;
  v_split_previous_active_id uuid;
  v_action_record RECORD;
  v_target_scenario RECORD;
  v_session_map jsonb;
  v_zone_map jsonb;
  v_old_id uuid; v_new_id uuid;
  v_session_row RECORD; v_zone_row RECORD; v_lot_row RECORD;
  v_audit_log_id uuid;
  v_tx_links jsonb;
  v_tx_result jsonb;
BEGIN
  -- D-ERP38: portao de permissao e isolamento de empresa.
  DECLARE
    v_uid uuid := auth.uid();
    v_company uuid;
  BEGIN
    -- auth.uid() NULL = service_role / cron / edge function: isencao deliberada,
    -- mesmo padrao de enforce_transaction_approval_permission.
    IF v_uid IS NOT NULL THEN
      IF NOT (public.is_platform_admin(v_uid)
              OR public.has_role(v_uid, 'admin'::app_role)
              OR public.has_permission(v_uid, 'manage_bp')) THEN
        RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
      END IF;
      IF NOT public.is_platform_admin(v_uid) THEN
        SELECT e.company_id INTO v_company FROM public.bp_versions v JOIN public.events e ON e.id = v.event_id WHERE v.id = _scenario_version_id;
        IF v_company IS NULL OR v_company IS DISTINCT FROM public.current_company_id() THEN
          RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;
  END;
  -- D-ERP38: autoria nao forjavel. Com utilizador, ignora o parametro recebido;
  -- com auth.uid() NULL (service_role) usa-se o parametro como antes.
  _performed_by := COALESCE(auth.uid(), _performed_by);
  SELECT * INTO v_scenario FROM public.bp_versions WHERE id = _scenario_version_id;
  IF v_scenario IS NULL THEN
    RAISE EXCEPTION 'Scenario % not found', _scenario_version_id;
  END IF;
  IF v_scenario.scenario_label IS NULL THEN
    RAISE EXCEPTION 'A versão alvo não é um cenário (sem scenario_label).';
  END IF;
  IF v_scenario.state = 'archived' THEN
    RAISE EXCEPTION 'Cenário arquivado — desarquive antes de promover.';
  END IF;

  SELECT id, name, parent_event_id INTO v_event
    FROM public.events WHERE id = v_scenario.event_id;
  IF v_event.parent_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'Promova o cenário do Master — os Splits são propagados automaticamente.';
  END IF;

  SELECT id INTO v_previous_active_id
    FROM public.bp_versions
   WHERE event_id = v_scenario.event_id AND state = 'active'
   LIMIT 1;

  IF v_previous_active_id IS NOT NULL THEN
    UPDATE public.bp_versions
       SET state = 'superseded', superseded_at = v_now
     WHERE id = v_previous_active_id;
  END IF;

  SELECT COALESCE(MAX(version_number), 0) + 1
    INTO v_next_version
    FROM public.bp_versions
   WHERE event_id = v_scenario.event_id;

  INSERT INTO public.bp_versions (
    event_id, version_number, state, created_by, created_by_label,
    description, snapshot_payload, approved_at, approved_by
  )
  VALUES (
    v_scenario.event_id, v_next_version, 'active', _performed_by, _performed_by_label,
    COALESCE(_description, format('Promovido do cenário "%s" (v%s)', v_scenario.scenario_label, v_scenario.version_number)),
    v_scenario.snapshot_payload, v_now, _performed_by
  )
  RETURNING id INTO v_new_version_id;

  IF v_previous_active_id IS NOT NULL THEN
    UPDATE public.bp_versions
       SET superseded_by_version_id = v_new_version_id
     WHERE id = v_previous_active_id;

    INSERT INTO public.bp_version_audit_log (
      version_id, event_id, action, performed_by, performed_by_label, metadata
    ) VALUES (
      v_previous_active_id, v_scenario.event_id, 'superseded',
      _performed_by, _performed_by_label,
      jsonb_build_object('superseded_by_version_id', v_new_version_id, 'cause', 'scenario_promoted')
    );
  END IF;

  UPDATE public.bp_versions
     SET is_pinned_scenario = false
   WHERE id = _scenario_version_id;

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    v_new_version_id, v_scenario.event_id, 'scenario_promoted',
    _performed_by, _performed_by_label,
    jsonb_build_object(
      'source_scenario_id', _scenario_version_id,
      'source_scenario_label', v_scenario.scenario_label,
      'source_version_number', v_scenario.version_number,
      'new_version_number', v_next_version,
      'force', _force,
      'other_scenarios_actions', _other_scenarios_actions
    )
  )
  RETURNING id INTO v_audit_log_id;

  -- Opção C: snapshot da formalidade + baseline da Ativa atual (por categoria+descrição) ANTES de apagar
  CREATE TEMP TABLE _formalidade_carry ON COMMIT DROP AS
  SELECT
    category_id,
    description,
    formalidade,
    formalidade_changed_at,
    formalidade_changed_by,
    baseline_amount,
    id AS old_forecast_id
  FROM public.event_forecasts
  WHERE event_id = v_scenario.event_id AND version_id IS NULL;

  -- Vínculos BP↔TX: capturar antes do DELETE (FK ON DELETE SET NULL apaga-os)
  v_tx_links := public.bp_capture_tx_links(v_scenario.event_id);

  DELETE FROM public.event_forecasts WHERE event_id = v_scenario.event_id AND version_id IS NULL;

  INSERT INTO public.event_forecasts (
    id, event_id, category_id, type, description, amount, currency,
    original_amount, fx_rate, fx_rate_source,
    formula_type, formula_value, iva_rate, status,
    approved_at, approved_by, transaction_id, cache_config_id,
    master_forecast_id, invoice_group_id, attachment_refs,
    historic_overrides, is_overhead, is_retroactive_override,
    is_transitory, exclude_from_result, notes, specification,
    created_at, updated_at, version_id,
    formalidade, formalidade_changed_at, formalidade_changed_by,
    ordering_partner_id, paying_partner_id, baseline_amount
  )
  SELECT
    COALESCE(carry.old_forecast_id, (r->>'id')::uuid, gen_random_uuid()),
    v_scenario.event_id,
    NULLIF(r->>'category_id', '')::uuid,
    r->>'type',
    r->>'description',
    COALESCE((r->>'amount')::numeric, 0),
    COALESCE(r->>'currency', 'EUR'),
    NULLIF(r->>'original_amount', '')::numeric,
    NULLIF(r->>'fx_rate', '')::numeric,
    r->>'fx_rate_source',
    COALESCE(r->>'formula_type', 'fixed'),
    COALESCE((r->>'formula_value')::numeric, 0),
    COALESCE((r->>'iva_rate')::numeric, 0),
    COALESCE(r->>'status', 'draft'),
    NULLIF(r->>'approved_at', '')::timestamptz,
    NULLIF(r->>'approved_by', '')::uuid,
    NULLIF(r->>'transaction_id', '')::uuid,
    NULLIF(r->>'cache_config_id', '')::uuid,
    NULLIF(r->>'master_forecast_id', '')::uuid,
    NULLIF(r->>'invoice_group_id', '')::uuid,
    COALESCE(r->'attachment_refs', '[]'::jsonb),
    COALESCE(r->'historic_overrides', '[]'::jsonb),
    COALESCE((r->>'is_overhead')::boolean, false),
    COALESCE((r->>'is_retroactive_override')::boolean, false),
    COALESCE((r->>'is_transitory')::boolean, false),
    COALESCE((r->>'exclude_from_result')::boolean, false),
    r->>'notes',
    r->>'specification',
    v_now, v_now, NULL,
    COALESCE(carry.formalidade, 'estimado'::bp_formalidade),
    carry.formalidade_changed_at,
    carry.formalidade_changed_by,
    NULLIF(r->>'ordering_partner_id', '')::uuid,
    NULLIF(r->>'paying_partner_id', '')::uuid,
    -- D3: baseline preservada da Ativa anterior; linha nova cai no trigger (NULL -> amount)
    carry.baseline_amount
  FROM jsonb_array_elements(COALESCE(v_scenario.snapshot_payload->'forecasts', '[]'::jsonb)) AS r
  LEFT JOIN _formalidade_carry carry
    ON carry.category_id IS NOT DISTINCT FROM NULLIF(r->>'category_id', '')::uuid
   AND carry.description IS NOT DISTINCT FROM (r->>'description');

  DROP TABLE IF EXISTS _formalidade_carry;

  -- Repõe os vínculos nas linhas novas (já vivas) e registra no audit log
  v_tx_result := public.bp_restore_tx_links(v_scenario.event_id, v_tx_links);

  UPDATE public.bp_version_audit_log
     SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('tx_links', v_tx_result)
   WHERE id = v_audit_log_id;

  DELETE FROM public.event_ticket_lots l
   USING public.event_ticket_zones z
   WHERE l.zone_id = z.id AND z.event_id = v_scenario.event_id AND z.version_id IS NULL AND l.version_id IS NULL;
  DELETE FROM public.event_ticket_zones WHERE event_id = v_scenario.event_id AND version_id IS NULL;
  DELETE FROM public.event_sessions WHERE event_id = v_scenario.event_id AND version_id IS NULL;

  v_session_map := '{}'::jsonb;
  v_zone_map := '{}'::jsonb;

  FOR v_session_row IN
    SELECT * FROM public.event_sessions
     WHERE event_id = v_scenario.event_id AND version_id = _scenario_version_id
  LOOP
    v_old_id := v_session_row.id;
    v_new_id := gen_random_uuid();
    INSERT INTO public.event_sessions (id, event_id, date, label, start_time, sort_order, version_id)
    VALUES (v_new_id, v_scenario.event_id, v_session_row.date, v_session_row.label, v_session_row.start_time,
            v_session_row.sort_order, NULL);
    v_session_map := v_session_map || jsonb_build_object(v_old_id::text, v_new_id::text);
  END LOOP;

  FOR v_zone_row IN
    SELECT * FROM public.event_ticket_zones
     WHERE event_id = v_scenario.event_id AND version_id = _scenario_version_id
  LOOP
    v_old_id := v_zone_row.id;
    v_new_id := gen_random_uuid();
    INSERT INTO public.event_ticket_zones (id, event_id, name, total_capacity, session_id, version_id)
    VALUES (v_new_id, v_scenario.event_id, v_zone_row.name, v_zone_row.total_capacity,
            CASE WHEN v_zone_row.session_id IS NULL THEN NULL
                 ELSE NULLIF(v_session_map->>(v_zone_row.session_id::text), '')::uuid END,
            NULL);
    v_zone_map := v_zone_map || jsonb_build_object(v_old_id::text, v_new_id::text);
  END LOOP;

  FOR v_lot_row IN
    SELECT l.* FROM public.event_ticket_lots l
     JOIN public.event_ticket_zones z ON z.id = l.zone_id
    WHERE z.event_id = v_scenario.event_id AND z.version_id = _scenario_version_id AND l.version_id = _scenario_version_id
  LOOP
    INSERT INTO public.event_ticket_lots (id, zone_id, lot_number, name, quantity, price, iva_rate, lot_type, version_id)
    VALUES (gen_random_uuid(),
            NULLIF(v_zone_map->>(v_lot_row.zone_id::text), '')::uuid,
            v_lot_row.lot_number, v_lot_row.name, v_lot_row.quantity, v_lot_row.price,
            v_lot_row.iva_rate, v_lot_row.lot_type, NULL);
  END LOOP;

  IF NOT _force THEN
    BEGIN
      PERFORM public.reconcile_bypasses_after_version_change(
        v_scenario.event_id, v_new_version_id, _performed_by, _performed_by_label
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Reconciliation failed for event %: %', v_scenario.event_id, SQLERRM;
    END;
  END IF;

  IF jsonb_typeof(_other_scenarios_actions) = 'array' THEN
    FOR v_action_record IN
      SELECT
        (e->>'version_id')::uuid AS version_id,
        e->>'action' AS action
      FROM jsonb_array_elements(_other_scenarios_actions) AS e
    LOOP
      SELECT * INTO v_target_scenario
        FROM public.bp_versions
       WHERE id = v_action_record.version_id
         AND event_id = v_scenario.event_id
         AND scenario_label IS NOT NULL
         AND id <> _scenario_version_id;

      IF v_target_scenario IS NULL THEN
        CONTINUE;
      END IF;

      IF v_action_record.action = 'archive' THEN
        UPDATE public.bp_versions
           SET state = 'archived',
               archived_at = v_now,
               is_pinned_scenario = false
         WHERE id = v_target_scenario.id;

        INSERT INTO public.bp_version_audit_log (
          version_id, event_id, action, performed_by, performed_by_label, metadata
        ) VALUES (
          v_target_scenario.id, v_scenario.event_id, 'archived',
          _performed_by, _performed_by_label,
          jsonb_build_object('cause', 'sibling_scenario_promoted',
                             'promoted_version_id', v_new_version_id)
        );

      ELSIF v_action_record.action = 'discard' THEN
        IF v_target_scenario.state = 'draft' THEN
          PERFORM public.discard_bp_version_draft(
            v_target_scenario.id, _performed_by, _performed_by_label
          );
        END IF;

      ELSIF v_action_record.action = 'keep' THEN
        INSERT INTO public.bp_version_audit_log (
          version_id, event_id, action, performed_by, performed_by_label, metadata
        ) VALUES (
          v_target_scenario.id, v_scenario.event_id, 'kept_after_sibling_promotion',
          _performed_by, _performed_by_label,
          jsonb_build_object('promoted_version_id', v_new_version_id)
        );
      END IF;
    END LOOP;
  END IF;

  FOR v_split IN
    SELECT id FROM public.events WHERE parent_event_id = v_scenario.event_id
  LOOP
    SELECT * INTO v_split_scenario
      FROM public.bp_versions
     WHERE event_id = v_split.id
       AND cascaded_from_version_id = _scenario_version_id
     LIMIT 1;

    IF v_split_scenario.id IS NULL THEN
      CONTINUE;
    END IF;

    SELECT id INTO v_split_previous_active_id
      FROM public.bp_versions
     WHERE event_id = v_split.id AND state = 'active'
     LIMIT 1;

    IF v_split_previous_active_id IS NOT NULL THEN
      UPDATE public.bp_versions
         SET state = 'superseded', superseded_at = v_now
       WHERE id = v_split_previous_active_id;
    END IF;

    SELECT COALESCE(MAX(version_number), 0) + 1
      INTO v_split_next_version
      FROM public.bp_versions
     WHERE event_id = v_split.id;

    INSERT INTO public.bp_versions (
      event_id, version_number, state, created_by, created_by_label,
      description, snapshot_payload, approved_at, approved_by,
      cascaded_from_version_id
    )
    VALUES (
      v_split.id, v_split_next_version, 'active', _performed_by, _performed_by_label,
      COALESCE(_description, 'Promovido via cascade do Master'),
      v_split_scenario.snapshot_payload, v_now, _performed_by,
      v_new_version_id
    )
    RETURNING id INTO v_split_new_version_id;

    IF v_split_previous_active_id IS NOT NULL THEN
      UPDATE public.bp_versions
         SET superseded_by_version_id = v_split_new_version_id
       WHERE id = v_split_previous_active_id;
    END IF;

    -- Opção C para o Split: preservar formalidade + baseline da Ativa do Split
    CREATE TEMP TABLE _formalidade_carry_split ON COMMIT DROP AS
    SELECT
      category_id,
      description,
      formalidade,
      formalidade_changed_at,
      formalidade_changed_by,
      baseline_amount,
      id AS old_forecast_id
    FROM public.event_forecasts
    WHERE event_id = v_split.id AND version_id IS NULL;

    v_tx_links := public.bp_capture_tx_links(v_split.id);

    DELETE FROM public.event_forecasts WHERE event_id = v_split.id AND version_id IS NULL;

    INSERT INTO public.event_forecasts (
      id, event_id, category_id, type, description, amount, currency,
      original_amount, fx_rate, fx_rate_source,
      formula_type, formula_value, iva_rate, status,
      approved_at, approved_by, transaction_id, cache_config_id,
      master_forecast_id, invoice_group_id, attachment_refs,
      historic_overrides, is_overhead, is_retroactive_override,
      is_transitory, exclude_from_result, notes, specification,
      created_at, updated_at, version_id,
      formalidade, formalidade_changed_at, formalidade_changed_by,
      ordering_partner_id, paying_partner_id, baseline_amount
    )
    SELECT
      COALESCE(carry.old_forecast_id, (r->>'id')::uuid, gen_random_uuid()),
      v_split.id,
      NULLIF(r->>'category_id', '')::uuid,
      r->>'type', r->>'description',
      COALESCE((r->>'amount')::numeric, 0),
      COALESCE(r->>'currency', 'EUR'),
      NULLIF(r->>'original_amount', '')::numeric,
      NULLIF(r->>'fx_rate', '')::numeric,
      r->>'fx_rate_source',
      COALESCE(r->>'formula_type', 'fixed'),
      COALESCE((r->>'formula_value')::numeric, 0),
      COALESCE((r->>'iva_rate')::numeric, 0),
      COALESCE(r->>'status', 'draft'),
      NULLIF(r->>'approved_at', '')::timestamptz,
      NULLIF(r->>'approved_by', '')::uuid,
      NULLIF(r->>'transaction_id', '')::uuid,
      NULLIF(r->>'cache_config_id', '')::uuid,
      NULLIF(r->>'master_forecast_id', '')::uuid,
      NULLIF(r->>'invoice_group_id', '')::uuid,
      COALESCE(r->'attachment_refs', '[]'::jsonb),
      COALESCE(r->'historic_overrides', '[]'::jsonb),
      COALESCE((r->>'is_overhead')::boolean, false),
      COALESCE((r->>'is_retroactive_override')::boolean, false),
      COALESCE((r->>'is_transitory')::boolean, false),
      COALESCE((r->>'exclude_from_result')::boolean, false),
      r->>'notes', r->>'specification',
      v_now, v_now, NULL,
      COALESCE(carry.formalidade, 'estimado'::bp_formalidade),
      carry.formalidade_changed_at,
      carry.formalidade_changed_by,
      NULLIF(r->>'ordering_partner_id', '')::uuid,
      NULLIF(r->>'paying_partner_id', '')::uuid,
      carry.baseline_amount
    FROM jsonb_array_elements(COALESCE(v_split_scenario.snapshot_payload->'forecasts', '[]'::jsonb)) AS r
    LEFT JOIN _formalidade_carry_split carry
      ON carry.category_id IS NOT DISTINCT FROM NULLIF(r->>'category_id', '')::uuid
     AND carry.description IS NOT DISTINCT FROM (r->>'description');

    DROP TABLE IF EXISTS _formalidade_carry_split;

    v_tx_result := public.bp_restore_tx_links(v_split.id, v_tx_links);

    INSERT INTO public.bp_version_audit_log (
      version_id, event_id, action, performed_by, performed_by_label, metadata
    ) VALUES (
      v_split_new_version_id, v_split.id, 'scenario_promoted_cascade',
      _performed_by, _performed_by_label,
      jsonb_build_object(
        'parent_scenario_id', _scenario_version_id,
        'master_version_id', v_new_version_id,
        'tx_links', v_tx_result
      )
    );

    DELETE FROM public.event_ticket_lots l
     USING public.event_ticket_zones z
     WHERE l.zone_id = z.id AND z.event_id = v_split.id AND z.version_id IS NULL AND l.version_id IS NULL;
    DELETE FROM public.event_ticket_zones WHERE event_id = v_split.id AND version_id IS NULL;
    DELETE FROM public.event_sessions WHERE event_id = v_split.id AND version_id IS NULL;

    v_session_map := '{}'::jsonb;
    v_zone_map := '{}'::jsonb;

    FOR v_session_row IN
      SELECT * FROM public.event_sessions
       WHERE event_id = v_split.id AND version_id = v_split_scenario.id
    LOOP
      v_old_id := v_session_row.id;
      v_new_id := gen_random_uuid();
      INSERT INTO public.event_sessions (id, event_id, date, label, start_time, sort_order, version_id)
      VALUES (v_new_id, v_split.id, v_session_row.date, v_session_row.label, v_session_row.start_time,
              v_session_row.sort_order, NULL);
      v_session_map := v_session_map || jsonb_build_object(v_old_id::text, v_new_id::text);
    END LOOP;

    FOR v_zone_row IN
      SELECT * FROM public.event_ticket_zones
       WHERE event_id = v_split.id AND version_id = v_split_scenario.id
    LOOP
      v_old_id := v_zone_row.id;
      v_new_id := gen_random_uuid();
      INSERT INTO public.event_ticket_zones (id, event_id, name, total_capacity, session_id, version_id)
      VALUES (v_new_id, v_split.id, v_zone_row.name, v_zone_row.total_capacity,
              CASE WHEN v_zone_row.session_id IS NULL THEN NULL
                   ELSE NULLIF(v_session_map->>(v_zone_row.session_id::text), '')::uuid END,
              NULL);
      v_zone_map := v_zone_map || jsonb_build_object(v_old_id::text, v_new_id::text);
    END LOOP;

    FOR v_lot_row IN
      SELECT l.* FROM public.event_ticket_lots l
       JOIN public.event_ticket_zones z ON z.id = l.zone_id
      WHERE z.event_id = v_split.id AND z.version_id = v_split_scenario.id AND l.version_id = v_split_scenario.id
    LOOP
      INSERT INTO public.event_ticket_lots (id, zone_id, lot_number, name, quantity, price, iva_rate, lot_type, version_id)
      VALUES (gen_random_uuid(),
              NULLIF(v_zone_map->>(v_lot_row.zone_id::text), '')::uuid,
              v_lot_row.lot_number, v_lot_row.name, v_lot_row.quantity, v_lot_row.price,
              v_lot_row.iva_rate, v_lot_row.lot_type, NULL);
    END LOOP;

    IF NOT _force THEN
      BEGIN
        PERFORM public.reconcile_bypasses_after_version_change(
          v_split.id, v_split_new_version_id, _performed_by, _performed_by_label
        );
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Reconciliation failed for split %: %', v_split.id, SQLERRM;
      END;
    END IF;
  END LOOP;

  RETURN v_new_version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.raise_forecast_budget(_forecast_id uuid, _new_amount numeric, _observation text)
 RETURNS event_forecasts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.event_forecasts;
  v_old_amount numeric;
  v_actor text;
  v_is_service boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    -- #122: service_role (cron / edge function) é aceite e identificado como tal.
    v_is_service := COALESCE(
      current_setting('request.jwt.claims', true)::jsonb->>'role', ''
    ) = 'service_role';
    IF NOT v_is_service THEN
      RAISE EXCEPTION 'Sem identidade de utilizador para elevar verbas de BP.' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT * INTO v_row FROM public.event_forecasts WHERE id = _forecast_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Linha de BP não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_service THEN
    IF NOT (
      public.is_platform_admin(v_uid)
      OR public.has_permission_in(v_uid, 'raise_budget', v_row.company_id)
    ) THEN
      RAISE EXCEPTION 'Sem permissão para elevar verbas de BP nesta empresa.' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _observation IS NULL OR btrim(_observation) = '' THEN
    RAISE EXCEPTION 'Observação obrigatória para elevar a verba da linha de BP.' USING ERRCODE = '22023';
  END IF;

  v_old_amount := COALESCE(v_row.amount, 0);

  IF _new_amount IS NULL OR _new_amount <= v_old_amount THEN
    RAISE EXCEPTION 'A nova verba tem de ser superior à verba actual da linha.' USING ERRCODE = '22023';
  END IF;

  IF v_is_service THEN
    v_actor := 'service_role';
  ELSE
    SELECT COALESCE(p.email, v_uid::text) INTO v_actor
    FROM public.profiles p WHERE p.id = v_uid;
    v_actor := COALESCE(v_actor, v_uid::text);
  END IF;

  -- NUNCA toca em baseline_amount (D3): o previsto original é fixo.
  UPDATE public.event_forecasts
     SET amount = _new_amount,
         updated_at = now()
   WHERE id = _forecast_id
  RETURNING * INTO v_row;

  INSERT INTO public.forecast_audit_log (
    forecast_id, changed_by, field_name, old_value, new_value, observation, company_id
  ) VALUES (
    _forecast_id,
    v_actor,
    'Elevação de verba',
    to_char(v_old_amount, 'FM999999999990.00'),
    to_char(_new_amount, 'FM999999999990.00'),
    btrim(_observation),
    v_row.company_id
  );

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_pax_benchmarks(_company_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _rows integer := 0;
  _active uuid := public.current_company_id();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória';
  END IF;
  IF _active IS NULL THEN
    RAISE EXCEPTION 'Sem empresa activa';
  END IF;
  IF _company_id IS NULL THEN
    _company_id := _active;
  ELSIF _company_id <> _active THEN
    RAISE EXCEPTION 'A empresa indicada não é a empresa activa';
  END IF;
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager') OR public.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Insufficient privileges';
  END IF;

  WITH agg AS (
    SELECT e.company_id, ac.code AS category_code, COUNT(DISTINCT e.id) AS sample_size,
      CASE WHEN SUM(e.tickets_sold) > 0 THEN SUM(t.amount) / SUM(e.tickets_sold) ELSE 0 END AS avg_ticket
    FROM public.transactions t
    JOIN public.account_categories ac ON ac.id = t.category_id
    JOIN public.events e ON e.id = t.event_id
    WHERE t.type = 'income' AND t.status IN ('approved','paid')
      AND ac.code IN ('1.1.02','1.1.03') AND e.tickets_sold > 0
      AND e.company_id = _company_id
    GROUP BY e.company_id, ac.code
    HAVING COUNT(DISTINCT e.id) >= 1
  )
  INSERT INTO public.event_simulator_pax_benchmarks
    (company_id, scope, scope_value, category_code, sample_size, avg_ticket_per_pax, last_calculated_at)
  SELECT company_id, 'global', NULL, category_code, sample_size, ROUND(avg_ticket::numeric, 2), now() FROM agg
  ON CONFLICT (company_id, scope, scope_value, category_code) DO UPDATE
    SET sample_size = EXCLUDED.sample_size, avg_ticket_per_pax = EXCLUDED.avg_ticket_per_pax, last_calculated_at = now();
  GET DIAGNOSTICS _rows = ROW_COUNT;
  RETURN _rows;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_bank_line(p_line_id uuid, p_items jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_line public.bank_statement_lines;
  v_current uuid;
  v_email text;
  v_sign_type text;
  v_target numeric;
  v_sum numeric := 0;
  v_n int;
  v_item jsonb;
  v_tx public.transactions;
  v_tx_id uuid;
  v_mode text;
  v_amount numeric;
  v_gross numeric;
  v_open numeric;
  v_ids uuid[] := '{}';
  v_pay_date date;
  v_rows int;
  v_action text;
  v_sys_date date;
  v_pending jsonb := '[]'::jsonb;
  v_kept jsonb := '[]'::jsonb;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Nada a conciliar: p_items tem de ser um array com pelo menos um item.';
  end if;

  select * into v_line from public.bank_statement_lines where id = p_line_id;
  if v_line.id is null then
    raise exception 'Linha do banco inexistente ou sem acesso: %', p_line_id;
  end if;

  v_current := public.current_company_id();
  if v_current is null or v_current <> v_line.company_id then
    raise exception 'A linha do banco pertence a outra empresa (%) — empresa activa %.', v_line.company_id, v_current;
  end if;

  if v_line.status <> 'unmatched'
     or v_line.matched_transaction_id is not null
     or v_line.created_transaction_id is not null
     or exists (select 1 from public.bank_line_transactions b where b.line_id = v_line.id) then
    raise exception 'Linha do banco já está conciliada: %', v_line.id;
  end if;

  v_sign_type := case when v_line.amount >= 0 then 'income' else 'expense' end;
  v_target := round(abs(coalesce(v_line.amount, 0))::numeric, 2);
  v_pay_date := coalesce(v_line.value_date, v_line.booking_date);

  v_email := coalesce(
    nullif(auth.jwt() ->> 'email', ''),
    (select p.email from public.profiles p where p.id = auth.uid()),
    'sistema'
  );

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_tx_id := nullif(v_item ->> 'transaction_id', '')::uuid;
    v_mode := coalesce(v_item ->> 'mode', 'link');
    v_amount := round(coalesce((v_item ->> 'amount')::numeric, 0), 2);
    v_action := nullif(v_item ->> 'date_action', '');

    if v_tx_id is null then
      raise exception 'Item sem transaction_id.';
    end if;
    if v_mode not in ('link', 'settle') then
      raise exception 'Modo inválido (%) — só "link" ou "settle".', v_mode;
    end if;
    if v_action is not null and v_action not in ('align', 'keep') then
      raise exception 'date_action inválida (%) — só "align" ou "keep".', v_action;
    end if;
    if v_amount <= 0 then
      raise exception 'Valor inválido para a transação %: %.', v_tx_id, v_amount;
    end if;
    if v_tx_id = any(v_ids) then
      raise exception 'Transação repetida no mesmo pedido: %', v_tx_id;
    end if;

    select * into v_tx from public.transactions where id = v_tx_id;
    if v_tx.id is null then
      raise exception 'Transação inexistente ou sem acesso: %', v_tx_id;
    end if;
    if v_tx.company_id <> v_current then
      raise exception 'A transação % pertence a outra empresa.', v_tx_id;
    end if;
    if v_tx.reversed_at is not null then
      raise exception 'A transação % está revertida.', v_tx_id;
    end if;
    if v_tx.type <> v_sign_type then
      raise exception 'Sinal incompatível: a linha do banco é % e a transação % é "%".',
        case when v_sign_type = 'income' then 'a crédito (receita)' else 'a débito (despesa)' end,
        v_tx_id, v_tx.type;
    end if;

    if v_mode = 'link' then
      -- #233: a data no sistema tem de bater com a do banco, ou a pessoa decide.
      v_sys_date := coalesce(v_tx.payment_date,
        (select max(tp.payment_date) from public.transaction_payments tp
          where tp.transaction_id = v_tx_id and tp.status = 'paid'));
      if v_pay_date is not null and v_sys_date is distinct from v_pay_date then
        if v_action is null then
          v_pending := v_pending || jsonb_build_object('transaction_id', v_tx_id, 'system_date', v_sys_date,
                                                      'bank_date', v_pay_date, 'amount', v_amount);
        elsif v_action = 'align' then
          update public.transaction_payments
             set payment_date = v_pay_date, updated_at = now()
           where transaction_id = v_tx_id and status = 'paid' and payment_date is not distinct from v_sys_date;
          get diagnostics v_rows = row_count;
          if v_rows = 0 then
            update public.transactions set payment_date = v_pay_date where id = v_tx_id;
          end if;
          insert into public.transaction_audit_log (transaction_id, changed_by, changed_at, field_name, old_value, new_value, company_id)
          values (v_tx_id, v_email, now(), 'payment_date', v_sys_date::text,
                  v_pay_date::text || ' (alinhada pela data do banco, #233)', v_current);
        else
          v_kept := v_kept || jsonb_build_object('transaction_id', v_tx_id, 'system_date', v_sys_date,
                     'bank_date', v_pay_date, 'amount', v_amount, 'accepted_by', v_email, 'accepted_at', now());
        end if;
      end if;
    end if;

    if v_mode = 'settle' then
      v_gross := round(coalesce(v_tx.amount, 0) * (1 + coalesce(v_tx.iva_rate, 0) / 100.0), 2);
      v_open := round(v_gross - coalesce(v_tx.paid_amount, 0), 2);
      if v_open <= 0 then
        raise exception 'A transação % não tem valor em aberto.', v_tx_id;
      end if;
      if v_amount > v_open + 0.01 then
        raise exception 'Valor a liquidar (%) acima do que está em aberto (%) na transação %.', v_amount, v_open, v_tx_id;
      end if;

      insert into public.transaction_payments
        (transaction_id, amount, payment_date, account_id, payment_method,
         payment_reference, notes, created_by)
      values
        (v_tx_id, v_amount, v_pay_date, v_line.financial_account_id, 'transfer',
         left(coalesce(v_line.description, ''), 500), 'Liquidação pela conciliação bancária', v_email);

      if v_tx.account_id is null then
        update public.transactions set account_id = v_line.financial_account_id where id = v_tx_id;
      end if;
    end if;

    v_ids := v_ids || v_tx_id;
    v_sum := v_sum + v_amount;
  end loop;

  if jsonb_array_length(v_pending) > 0 then
    raise exception 'Data de pagamento diferente da do banco — escolher alinhar ou manter.'
      using errcode = 'P0410', detail = v_pending::text;
  end if;

  v_sum := round(v_sum, 2);
  if abs(v_sum - v_target) > 0.01 then
    raise exception 'A soma dos valores (%) não bate com a linha do banco (%).', v_sum, v_target;
  end if;

  v_n := array_length(v_ids, 1);

  update public.bank_statement_lines
     set status = 'matched',
         matched_transaction_id = case when v_n = 1 then v_ids[1] else null end,
         matched_payment_list_id = null,
         matched_sepa_export_id = null,
         matched_by = case when v_n = 1 then 'manual:' else 'manual-multi:' end || v_email,
         matched_at = now(),
         date_divergence = case when jsonb_array_length(v_kept) > 0 then v_kept else null end
   where id = v_line.id;

  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'A linha do banco não ficou conciliada.';
  end if;

  delete from public.bank_line_transactions where line_id = v_line.id;
  if v_n > 1 then
    insert into public.bank_line_transactions (line_id, transaction_id)
    select v_line.id, x from unnest(v_ids) x;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_document_download(p_resource_type text, p_resource_id uuid DEFAULT NULL::uuid, p_bucket text DEFAULT NULL::text, p_file_path text DEFAULT NULL::text, p_file_name text DEFAULT NULL::text, p_period_from date DEFAULT NULL::date, p_period_to date DEFAULT NULL::date, p_extra jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_email text;
  v_role text;
  v_company uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  IF p_resource_type NOT IN ('transaction_document','zip_export','supplier_document','camarim_document','card_document') THEN
    RAISE EXCEPTION 'invalid resource_type %', p_resource_type USING ERRCODE = '22023';
  END IF;

  SELECT email INTO v_email FROM auth.users WHERE id = v_uid;

  SELECT role::text INTO v_role
  FROM public.user_roles
  WHERE user_id = v_uid
  ORDER BY CASE role::text
    WHEN 'platform_admin' THEN 0
    WHEN 'admin' THEN 1
    WHEN 'manager' THEN 2
    WHEN 'accountant' THEN 3
    ELSE 9
  END
  LIMIT 1;

  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'no active company' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.document_download_audit (
    company_id, user_id, user_email, user_role,
    resource_type, resource_id, bucket, file_path, file_name,
    period_from, period_to, extra_metadata
  ) VALUES (
    v_company, v_uid, COALESCE(v_email,'unknown'), COALESCE(v_role,'unknown'),
    p_resource_type, p_resource_id, p_bucket, p_file_path, p_file_name,
    p_period_from, p_period_to, COALESCE(p_extra,'{}'::jsonb)
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reduce_forecast_budget(_forecast_id uuid, _new_amount numeric, _observation text)
 RETURNS event_forecasts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.event_forecasts;
  v_old_amount numeric;
  v_realized numeric;
  v_is_service boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    v_is_service := COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '') = 'service_role';
    IF NOT v_is_service THEN
      RAISE EXCEPTION 'Sem identidade de utilizador para ajustar verbas de BP.' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT * INTO v_row FROM public.event_forecasts WHERE id = _forecast_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Linha de BP não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT v_is_service THEN
    IF NOT (public.is_platform_admin(v_uid) OR public.has_permission_in(v_uid, 'manage_bp', v_row.company_id)) THEN
      RAISE EXCEPTION 'Sem permissão para ajustar verbas de BP nesta empresa.' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF _observation IS NULL OR btrim(_observation) = '' THEN
    RAISE EXCEPTION 'Observação obrigatória para ajustar a verba da linha de BP.' USING ERRCODE = '22023';
  END IF;

  v_old_amount := COALESCE(v_row.amount, 0);
  IF _new_amount IS NULL OR _new_amount >= v_old_amount THEN
    RAISE EXCEPTION 'A nova verba tem de ser inferior à verba actual da linha.' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(t.amount), 0) INTO v_realized
  FROM public.transactions t
  WHERE t.forecast_id = _forecast_id
    AND t.type = 'expense'
    AND t.status IN ('approved','paid','partially_paid')
    AND COALESCE(t.is_transitory, false) = false
    AND COALESCE(t.exclude_from_result, false) = false
    AND t.reversed_at IS NULL
    AND COALESCE(t.is_hidden, false) = false;

  IF _new_amount < v_realized - 0.005 THEN
    RAISE EXCEPTION 'A nova verba (%) não pode ficar abaixo do realizado da linha (%).',
      to_char(_new_amount, 'FM999999999990.00'), to_char(v_realized, 'FM999999999990.00')
      USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('mp.bp_change_observation', '[ajuste de fecho] ' || btrim(_observation), true);

  -- NUNCA toca em baseline_amount (D3). O audit é escrito por trg_enforce_forecast_amount_floor.
  UPDATE public.event_forecasts SET amount = _new_amount, updated_at = now()
   WHERE id = _forecast_id RETURNING * INTO v_row;

  PERFORM set_config('mp.bp_change_observation', '', true);
  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.rename_operation_key(_old_key text, _new_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid;
  v_affected int;
  v_target_existing int;
  v_actor text;
BEGIN
  IF auth.uid() IS NOT NULL THEN
    -- service_role / crons (auth.uid() IS NULL) ficam isentos do portão.
    IF NOT (public.has_role(auth.uid(), 'admin') OR public.is_platform_admin(auth.uid())) THEN
      RAISE EXCEPTION 'Apenas administradores podem renomear chaves de operação' USING ERRCODE = '42501';
    END IF;
  END IF;

  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;

  _old_key := btrim(coalesce(_old_key, ''));
  _new_key := btrim(coalesce(_new_key, ''));

  IF _new_key !~ '^[A-Z0-9]+(-[A-Z0-9]+)+$' THEN
    RAISE EXCEPTION 'Chave nova fora da convenção: %', _new_key USING ERRCODE = '22023';
  END IF;
  IF _old_key = '' OR _old_key = _new_key THEN
    RAISE EXCEPTION 'Chave antiga inválida' USING ERRCODE = '22023';
  END IF;
  IF _old_key LIKE 'CAMARIM-%' OR _old_key LIKE 'CARTAO-%'
     OR _new_key LIKE 'CAMARIM-%' OR _new_key LIKE 'CARTAO-%' THEN
    RAISE EXCEPTION 'Chaves geradas pelo sistema (CAMARIM-/CARTAO-) não podem ser renomeadas' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_target_existing
  FROM public.transactions
  WHERE company_id = v_company AND operation_key = _new_key;

  v_actor := coalesce((SELECT email FROM auth.users WHERE id = auth.uid()), 'sistema');

  INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value, company_id)
  SELECT id, v_actor, 'Chave de operação (renomear grupo)', _old_key, _new_key, v_company
  FROM public.transactions
  WHERE company_id = v_company AND operation_key = _old_key;

  UPDATE public.transactions
  SET operation_key = _new_key
  WHERE company_id = v_company AND operation_key = _old_key;
  GET DIAGNOSTICS v_affected = ROW_COUNT;

  IF v_affected = 0 THEN
    RAISE EXCEPTION 'Chave % não encontrada nesta empresa', _old_key USING ERRCODE = 'no_data_found';
  END IF;

  RETURN jsonb_build_object(
    'old_key', _old_key,
    'new_key', _new_key,
    'affected', v_affected,
    'merged_into_existing', v_target_existing,
    'total_after', v_affected + v_target_existing
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.renegotiate_transaction_installments(p_transaction_id uuid, p_installments jsonb, p_changed_by text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- Renegocia uma despesa de pagamento único num grupo estrutural de N parcelas.
--
-- p_installments: array ORDENADO de { "due_date": "YYYY-MM-DD", "amount": <BASE, sem IVA> }.
-- O cliente converte bruto->base (computeInstallmentNets) ANTES de chamar.
DECLARE
  v_uid uuid := auth.uid();
  v_tx public.transactions%ROWTYPE;
  v_n int;
  v_sum numeric := 0;
  v_group_id uuid;
  v_base_desc text;
  v_item jsonb;
  v_i int;
  v_amount numeric;
  v_due date;
  v_first_amount numeric;
  v_first_due date;
  v_old_amount numeric;
  v_old_due date;
  v_new_id uuid;
  v_event_status text;
BEGIN
  IF NOT (
    public.has_role(v_uid, 'admin'::app_role)
    OR public.has_role(v_uid, 'manager'::app_role)
    OR public.has_permission(v_uid, 'manage_transactions')
  ) THEN
    RAISE EXCEPTION 'permission_denied: sem permissão para renegociar em parcelas';
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction_not_found: %', p_transaction_id;
  END IF;

  IF v_tx.type <> 'expense' THEN
    RAISE EXCEPTION 'not_expense: apenas despesas podem ser renegociadas em parcelas';
  END IF;

  IF coalesce(v_tx.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'already_paid: a transação já tem valor pago (%)', v_tx.paid_amount;
  END IF;

  IF EXISTS (SELECT 1 FROM public.transaction_payments WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'has_payments: a transação já tem pagamentos registados';
  END IF;

  IF v_tx.installment_group_id IS NOT NULL THEN
    RAISE EXCEPTION 'already_installment_group: a transação já pertence a um grupo de parcelas';
  END IF;

  IF v_tx.split_percentage IS NOT NULL THEN
    RAISE EXCEPTION 'is_split: transações de rateio não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.transactions
     WHERE parent_transaction_id = p_transaction_id
       AND split_percentage IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'is_split_parent: transações rateadas entre eventos não podem ser renegociadas em parcelas; ajuste o rateio primeiro';
  END IF;

  IF coalesce(v_tx.is_reimbursement, false) THEN
    RAISE EXCEPTION 'is_reimbursement: notas de reembolso não podem ser renegociadas em parcelas';
  END IF;

  IF coalesce(v_tx.is_transitory, false) THEN
    RAISE EXCEPTION 'is_transitory: transações transitórias não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (SELECT 1 FROM public.partner_paid_expenses WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'is_partner_paid: despesas pagas por sócio não podem ser renegociadas em parcelas';
  END IF;

  IF EXISTS (SELECT 1 FROM public.partner_advance_expenses WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'is_partner_extra: extras de sócio não podem ser renegociados em parcelas';
  END IF;

  IF v_tx.event_id IS NOT NULL THEN
    SELECT status INTO v_event_status FROM public.events WHERE id = v_tx.event_id;
    IF v_event_status = 'completed' THEN
      RAISE EXCEPTION 'event_completed: o evento associado está fechado';
    END IF;
  END IF;

  IF p_installments IS NULL OR jsonb_typeof(p_installments) <> 'array' THEN
    RAISE EXCEPTION 'invalid_installments: lista de parcelas inválida';
  END IF;

  v_n := jsonb_array_length(p_installments);
  IF v_n < 2 THEN
    RAISE EXCEPTION 'too_few_installments: são necessárias pelo menos 2 parcelas (recebidas %)', v_n;
  END IF;

  FOR v_i IN 0..v_n - 1 LOOP
    v_item := p_installments -> v_i;
    IF v_item ->> 'due_date' IS NULL OR trim(v_item ->> 'due_date') = '' THEN
      RAISE EXCEPTION 'invalid_due_date: parcela % sem data de vencimento', v_i + 1;
    END IF;
    v_amount := (v_item ->> 'amount')::numeric;
    IF v_amount IS NULL OR v_amount <= 0 THEN
      RAISE EXCEPTION 'invalid_amount: parcela % com valor inválido', v_i + 1;
    END IF;
    v_sum := v_sum + v_amount;
  END LOOP;

  IF abs(v_sum - v_tx.amount) > 0.01 THEN
    RAISE EXCEPTION 'installments_sum_mismatch: soma das parcelas % difere do valor da transação %', v_sum, v_tx.amount;
  END IF;

  v_group_id := gen_random_uuid();
  v_base_desc := trim(regexp_replace(coalesce(v_tx.description, ''), '\(\s*\d+\s*/\s*\d+\s*\)\s*$', ''));
  v_old_amount := v_tx.amount;
  v_old_due := v_tx.due_date;
  v_first_amount := ((p_installments -> 0) ->> 'amount')::numeric;
  v_first_due := ((p_installments -> 0) ->> 'due_date')::date;

  UPDATE public.transactions
     SET description = v_base_desc || ' (1/' || v_n || ')',
         amount = v_first_amount,
         due_date = v_first_due,
         installment_group_id = v_group_id,
         installment_number = 1,
         installment_total = v_n,
         original_amount = CASE
           WHEN coalesce(v_tx.currency, 'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND coalesce(v_old_amount, 0) <> 0
             THEN round(v_tx.original_amount * v_first_amount / v_old_amount, 2)
           ELSE v_tx.original_amount
         END,
         updated_at = now()
   WHERE id = p_transaction_id;

  INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
  VALUES
    (p_transaction_id, p_changed_by, 'Valor (renegociação em parcelas)', round(v_old_amount, 2)::text, round(v_first_amount, 2)::text),
    (p_transaction_id, p_changed_by, 'Data Vencimento (renegociação em parcelas)', coalesce(v_old_due::text, ''), v_first_due::text);

  FOR v_i IN 1..v_n - 1 LOOP
    v_item := p_installments -> v_i;
    v_amount := (v_item ->> 'amount')::numeric;
    v_due := (v_item ->> 'due_date')::date;

    INSERT INTO public.transactions (
      description, type, amount, iva_rate, event_id, category_id, supplier_id, account_id,
      specification, date, due_date, status, paid_amount, payment_date,
      is_reimbursement, is_transitory, exclude_from_result,
      invoice_ref, invoice_group_id, payment_method, payment_entity, payment_reference,
      operation_key,
      ordering_partner_id, paying_partner_id,
      currency, fx_rate, fx_rate_source, original_amount,
      parent_transaction_id, installment_group_id, installment_number, installment_total,
      split_percentage, split_amount, company_id
    ) VALUES (
      v_base_desc || ' (' || (v_i + 1) || '/' || v_n || ')',
      v_tx.type, v_amount, v_tx.iva_rate, v_tx.event_id, v_tx.category_id, v_tx.supplier_id, v_tx.account_id,
      v_tx.specification, v_tx.date, v_due, v_tx.status, 0, NULL,
      false, false, coalesce(v_tx.exclude_from_result, false),
      v_tx.invoice_ref, v_tx.invoice_group_id, coalesce(v_tx.payment_method, 'transfer'), v_tx.payment_entity, v_tx.payment_reference,
      v_tx.operation_key,
      v_tx.ordering_partner_id, v_tx.paying_partner_id,
      coalesce(v_tx.currency, 'EUR'), v_tx.fx_rate, v_tx.fx_rate_source,
      CASE
        WHEN coalesce(v_tx.currency, 'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND coalesce(v_old_amount, 0) <> 0
          THEN round(v_tx.original_amount * v_amount / v_old_amount, 2)
        ELSE NULL
      END,
      p_transaction_id, v_group_id, v_i + 1, v_n,
      NULL, NULL, v_tx.company_id
    )
    RETURNING id INTO v_new_id;

    INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
    VALUES (
      v_new_id, p_changed_by, 'Criação (renegociação em parcelas)', NULL,
      v_base_desc || ' (' || (v_i + 1) || '/' || v_n || ') — ' || round(v_amount, 2)::text || ' € (base) — venc. ' || v_due::text
    );
  END LOOP;

  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.restore_bp_versions_from_trash(_trash_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_trash record;
  v_versions jsonb;
  v_audit jsonb;
  v_inserted_versions int := 0;
  v_inserted_audit int := 0;
  v_row jsonb;
BEGIN
  IF NOT (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'manager'::app_role)) THEN
    RAISE EXCEPTION 'Apenas admin ou manager podem restaurar versões do BP';
  END IF;

  SELECT * INTO v_trash FROM public.trash WHERE id = _trash_id AND entity_type = 'bp_versions';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Snapshot de versões não encontrado na trash (id=%)', _trash_id;
  END IF;

  v_versions := COALESCE(v_trash.related_data->'versions', '[]'::jsonb);
  v_audit := COALESCE(v_trash.related_data->'audit_log', '[]'::jsonb);

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_versions)
  LOOP
    BEGIN
      INSERT INTO public.bp_versions
      SELECT * FROM jsonb_populate_record(NULL::public.bp_versions, v_row)
      ON CONFLICT (id) DO NOTHING;
      v_inserted_versions := v_inserted_versions + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'restore_bp_versions: skip version %: %', v_row->>'id', SQLERRM;
    END;
  END LOOP;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_audit)
  LOOP
    BEGIN
      INSERT INTO public.bp_version_audit_log
      SELECT * FROM jsonb_populate_record(NULL::public.bp_version_audit_log, v_row)
      ON CONFLICT (id) DO NOTHING;
      v_inserted_audit := v_inserted_audit + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'restore_bp_versions: skip audit %: %', v_row->>'id', SQLERRM;
    END;
  END LOOP;

  UPDATE public.trash SET restored_at = now() WHERE id = _trash_id;

  RETURN jsonb_build_object(
    'restored_versions', v_inserted_versions,
    'restored_audit_entries', v_inserted_audit
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_payment(p_payment_id uuid, p_kind text, p_reason text, p_valid_until date DEFAULT NULL::date, p_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_payment public.transaction_payments%ROWTYPE;
  v_tx public.transactions%ROWTYPE;
  v_credit_id uuid;
  v_credit_amount numeric;
BEGIN
  IF NOT public.has_role(v_uid, 'admin'::app_role) THEN
    RAISE EXCEPTION 'permission_denied: apenas administradores podem estornar pagamentos';
  END IF;

  IF p_kind NOT IN ('cash_refund','supplier_credit') THEN
    RAISE EXCEPTION 'invalid_kind: % (esperado cash_refund | supplier_credit)', p_kind;
  END IF;

  IF coalesce(trim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'reason_required: motivo do estorno é obrigatório';
  END IF;

  SELECT * INTO v_payment FROM public.transaction_payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_not_found: %', p_payment_id;
  END IF;

  IF v_payment.reversal_kind IS NOT NULL THEN
    RAISE EXCEPTION 'already_reversed: este pagamento já foi estornado (%)', v_payment.reversal_kind;
  END IF;

  IF v_payment.status <> 'paid' THEN
    RAISE EXCEPTION 'payment_not_paid: só parcelas pagas podem ser estornadas (status atual: %)', v_payment.status;
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = v_payment.transaction_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'transaction_not_found';
  END IF;

  IF p_kind = 'supplier_credit' THEN
    IF v_tx.supplier_id IS NULL THEN
      RAISE EXCEPTION 'no_supplier: a transação não tem fornecedor definido — não é possível criar crédito';
    END IF;

    v_credit_amount := coalesce(p_amount, v_payment.amount);
    IF v_credit_amount <= 0 OR v_credit_amount > v_payment.amount + 0.01 THEN
      RAISE EXCEPTION 'invalid_amount: valor do crédito deve estar entre 0 e % (valor do pagamento)', v_payment.amount;
    END IF;

    INSERT INTO public.supplier_credits (
      supplier_id, origin_event_id, amount, used_amount, reason, valid_until, status, created_by, company_id
    )
    VALUES (
      v_tx.supplier_id,
      v_tx.event_id,
      v_credit_amount,
      0,
      'Estorno: ' || p_reason || ' (TX ref ' || v_tx.id::text || ')',
      p_valid_until,
      'active',
      coalesce((SELECT email FROM auth.users WHERE id = v_uid), 'sistema'),
      v_payment.company_id
    )
    RETURNING id INTO v_credit_id;

    UPDATE public.transaction_payments
       SET reversal_kind = 'supplier_credit',
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = v_credit_id,
           updated_at = now()
     WHERE id = p_payment_id;

  ELSE
    UPDATE public.transaction_payments
       SET status = 'reversed',
           reversal_kind = 'cash_refund',
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           updated_at = now()
     WHERE id = p_payment_id;

    IF NOT public.tx_has_installment_schedule(v_tx.id) THEN
      DECLARE
        v_paid_sum numeric;
        v_max_date date;
        v_gross numeric := v_tx.amount * (1 + coalesce(v_tx.iva_rate, 0) / 100.0);
      BEGIN
        SELECT coalesce(SUM(amount),0), MAX(payment_date) INTO v_paid_sum, v_max_date
          FROM public.transaction_payments
         WHERE transaction_id = v_tx.id AND status = 'paid';

        IF v_paid_sum <= 0.01 THEN
          UPDATE public.transactions
             SET paid_amount = 0,
                 status = CASE WHEN status IN ('paid','partially_paid') THEN 'approved' ELSE status END,
                 payment_date = NULL,
                 updated_at = now()
           WHERE id = v_tx.id;
        ELSIF v_paid_sum >= v_gross - 0.01 THEN
          UPDATE public.transactions
             SET paid_amount = v_paid_sum, status = 'paid', payment_date = v_max_date, updated_at = now()
           WHERE id = v_tx.id;
        ELSE
          UPDATE public.transactions
             SET paid_amount = v_paid_sum, status = 'partially_paid', payment_date = NULL, updated_at = now()
           WHERE id = v_tx.id;
        END IF;
      END;
    END IF;

    DELETE FROM public.payment_list_items
     WHERE transaction_id = v_tx.id
       AND payment_list_id IN (
         SELECT id FROM public.payment_lists
          WHERE status IN ('draft','pending_approval')
       );
  END IF;

  BEGIN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata)
    VALUES (
      'transaction_payment',
      p_payment_id::text,
      'reverse_payment_' || p_kind,
      coalesce((SELECT email FROM auth.users WHERE id = v_uid), 'sistema'),
      jsonb_build_object('status', v_payment.status, 'amount', v_payment.amount, 'account_id', v_payment.account_id),
      jsonb_build_object('reversal_kind', p_kind, 'reason', p_reason, 'supplier_credit_id', v_credit_id, 'credit_amount', v_credit_amount),
      jsonb_build_object('transaction_id', v_tx.id, 'event_id', v_tx.event_id)
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', p_kind,
    'payment_id', p_payment_id,
    'transaction_id', v_tx.id,
    'supplier_credit_id', v_credit_id,
    'credit_amount', v_credit_amount
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_ticket_office_settlement(p_settlement_id uuid, p_reason text, p_caller_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_s record;
  v_key text;
  v_exp uuid[];
  v_n int;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão em falta' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_role(v_uid, 'admin') OR public.is_platform_admin()) THEN
    RAISE EXCEPTION 'Só um admin pode estornar um fecho de bilheteira.' USING ERRCODE = '42501';
  END IF;
  IF coalesce(trim(p_reason), '') = '' THEN RAISE EXCEPTION 'Motivo do estorno obrigatório' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_s FROM ticket_office_settlements WHERE id = p_settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fecho não encontrado' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.row_belongs_to_current_company(v_s.company_id) THEN RAISE EXCEPTION 'Fecho de outra empresa' USING ERRCODE = '42501'; END IF;
  IF v_s.status = 'reversed' THEN RAISE EXCEPTION 'Fecho já estornado' USING ERRCODE = 'P0001'; END IF;

  IF v_s.transfer_transaction_id IS NOT NULL THEN
    SELECT operation_key INTO v_key FROM transactions WHERE id = v_s.transfer_transaction_id;
    UPDATE ticket_office_settlements SET transfer_transaction_id = NULL WHERE id = p_settlement_id;
    IF v_key IS NOT NULL THEN
      DELETE FROM transactions WHERE operation_key = v_key;
    ELSE
      DELETE FROM transactions WHERE id = v_s.transfer_transaction_id;
    END IF;
    GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('transfer_legs', v_n);
  END IF;

  SELECT coalesce(array_agg(id), '{}') INTO v_exp FROM transactions WHERE settlement_id = p_settlement_id AND type = 'expense';
  DELETE FROM transaction_payments WHERE transaction_id = ANY(v_exp);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('payments', v_n);
  UPDATE transactions SET settlement_id = NULL, status = 'pending', payment_date = NULL, paid_amount = 0, account_id = NULL
   WHERE id = ANY(v_exp);
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('expenses', v_n);

  UPDATE event_ticket_office_advances SET settlement_id = NULL WHERE settlement_id = p_settlement_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('advances', v_n);

  UPDATE ticket_office_settlements SET status = 'reversed', reversed_at = now(), reversed_by = v_uid,
         reversal_reason = p_reason, transfer_transaction_id = NULL, net_transferred = 0, transfer_account_id = NULL
   WHERE id = p_settlement_id;

  UPDATE event_ticket_office_assignments SET is_conciliated = false, conciliated_at = NULL, conciliated_by = NULL
   WHERE event_id = v_s.event_id AND financial_account_id = v_s.financial_account_id;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('assignments', v_n);

  INSERT INTO system_audit_log (entity_type, entity_id, action, changed_by, metadata, company_id)
  VALUES ('ticket_office_settlement', p_settlement_id::text, 'reverse', coalesce(nullif(trim(p_caller_name), ''), v_uid::text),
          jsonb_build_object('reason', p_reason, 'counts', v_counts), v_s.company_id);

  RETURN jsonb_build_object('settlement_id', p_settlement_id, 'counts', v_counts);
END $function$

CREATE OR REPLACE FUNCTION public.reverse_transaction(p_tx_id uuid, p_kind text, p_reason text, p_valid_until date, p_release_for_repayment boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx RECORD;
  v_uid uuid := auth.uid();
  v_credit_id uuid;
  v_paid_amount numeric;
  v_account_name text;
  v_removed_from_lists jsonb := '[]'::jsonb;
  v_list RECORD;
BEGIN
  IF NOT (public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'platform_admin'::app_role)) THEN
    RAISE EXCEPTION 'Apenas administradores podem estornar transações';
  END IF;

  IF p_kind NOT IN ('cash_refund','supplier_credit') THEN
    RAISE EXCEPTION 'Tipo de estorno inválido: %', p_kind;
  END IF;

  IF coalesce(trim(p_reason),'') = '' THEN
    RAISE EXCEPTION 'Motivo é obrigatório';
  END IF;

  SELECT * INTO v_tx FROM public.transactions WHERE id = p_tx_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transação não encontrada'; END IF;
  IF v_tx.status = 'reversed' THEN RAISE EXCEPTION 'Transação já está estornada'; END IF;
  IF coalesce(v_tx.paid_amount,0) <= 0 AND v_tx.status <> 'paid' THEN
    RAISE EXCEPTION 'Só transações com pagamento registado podem ser estornadas';
  END IF;

  v_paid_amount := coalesce(v_tx.paid_amount, 0);

  SELECT name INTO v_account_name FROM public.financial_accounts WHERE id = v_tx.account_id;

  IF p_kind = 'supplier_credit' THEN
    IF v_tx.supplier_id IS NULL THEN
      RAISE EXCEPTION 'Transação não tem fornecedor — não é possível criar crédito';
    END IF;

    INSERT INTO public.supplier_credits (
      supplier_id, origin_event_id, amount, reason, valid_until,
      document_ref, status, created_by, company_id
    ) VALUES (
      v_tx.supplier_id, v_tx.event_id, v_paid_amount,
      'Estorno tx ' || v_tx.id::text || ' — ' || p_reason,
      p_valid_until, 'reverse_tx:' || v_tx.id::text, 'active',
      coalesce(v_uid::text, 'system'), v_tx.company_id
    ) RETURNING id INTO v_credit_id;

    UPDATE public.transaction_payments
       SET reversal_kind = 'supplier_credit', reversal_reason = p_reason,
           reversed_at = now(), reversed_by = v_uid, supplier_credit_id = v_credit_id
     WHERE transaction_id = p_tx_id AND status = 'paid' AND reversal_kind IS NULL;
  ELSE
    UPDATE public.transaction_payments
       SET status = 'reversed', reversal_kind = 'cash_refund',
           reversal_reason = p_reason, reversed_at = now(), reversed_by = v_uid
     WHERE transaction_id = p_tx_id AND status = 'paid';
  END IF;

  DELETE FROM public.payment_list_items pli
   USING public.payment_lists pl
   WHERE pli.transaction_id = p_tx_id
     AND pli.payment_list_id = pl.id
     AND pl.status IN ('draft','pending_approval');

  IF p_release_for_repayment THEN
    FOR v_list IN
      SELECT pl.id AS list_id, pl.title AS list_name, pl.status AS list_status, pli.id AS pli_id
        FROM public.payment_list_items pli
        JOIN public.payment_lists pl ON pl.id = pli.payment_list_id
       WHERE pli.transaction_id = p_tx_id
         AND pl.status IN ('partially_approved','approved','paid')
    LOOP
      DELETE FROM public.payment_list_items WHERE id = v_list.pli_id;
      v_removed_from_lists := v_removed_from_lists || jsonb_build_object(
        'list_id', v_list.list_id, 'list_name', v_list.list_name, 'list_status', v_list.list_status
      );
    END LOOP;
  ELSE
    FOR v_list IN
      SELECT pl.id AS list_id, pl.title AS list_name, pl.status AS list_status
        FROM public.payment_list_items pli
        JOIN public.payment_lists pl ON pl.id = pli.payment_list_id
       WHERE pli.transaction_id = p_tx_id
         AND pl.status IN ('partially_approved','approved','paid')
    LOOP
      INSERT INTO public.transaction_audit_log (
        transaction_id, changed_by, field_name, old_value, new_value, company_id
      ) VALUES (
        p_tx_id, coalesce(v_uid::text, 'system'),
        'Estorno — lista mantida',
        v_list.list_name || ' (' || v_list.list_status || ')',
        'Transação estornada mas mantida na lista (modo conservador). Para libertar, refaça o estorno com "libertar para nova liquidação".',
        v_tx.company_id
      );
    END LOOP;
  END IF;

  IF p_release_for_repayment THEN
    UPDATE public.transactions
       SET status = 'pending',
           paid_amount = 0,
           payment_date = NULL,
           reversal_kind = p_kind,
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = CASE WHEN p_kind='supplier_credit' THEN v_credit_id ELSE supplier_credit_id END,
           updated_at = now()
     WHERE id = p_tx_id;
  ELSE
    UPDATE public.transactions
       SET status = 'reversed',
           paid_amount = CASE WHEN p_kind='cash_refund' THEN 0 ELSE paid_amount END,
           payment_date = CASE WHEN p_kind='cash_refund' THEN NULL ELSE payment_date END,
           reversal_kind = p_kind,
           reversal_reason = p_reason,
           reversed_at = now(),
           reversed_by = v_uid,
           supplier_credit_id = CASE WHEN p_kind='supplier_credit' THEN v_credit_id ELSE supplier_credit_id END,
           updated_at = now()
     WHERE id = p_tx_id;
  END IF;

  INSERT INTO public.transaction_audit_log (
    transaction_id, changed_by, field_name, old_value, new_value, company_id
  ) VALUES (
    p_tx_id,
    coalesce(v_uid::text, 'system'),
    'Estorno',
    'paid',
    CASE WHEN p_kind = 'cash_refund'
         THEN 'Devolução em dinheiro — ' || to_char(v_paid_amount,'FM999G999G990D00') || ' € repostos' ||
              coalesce(' em ' || v_account_name, '') || ' — ' || p_reason
         ELSE 'Crédito do fornecedor — ' || to_char(v_paid_amount,'FM999G999G990D00') || ' € — ' || p_reason
    END
      || CASE WHEN p_release_for_repayment
              THEN ' · Libertada para nova liquidação (status → A pagar)'
              ELSE ' · Estornada (status → Estornada)'
         END,
    v_tx.company_id
  );

  INSERT INTO public.system_audit_log (
    entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id
  ) VALUES (
    'transaction', p_tx_id::text, 'reverse_transaction_' || p_kind,
    coalesce(v_uid::text, 'system'), to_jsonb(v_tx),
    jsonb_build_object(
      'status', CASE WHEN p_release_for_repayment THEN 'pending' ELSE 'reversed' END,
      'reversal_kind', p_kind,
      'reversal_reason', p_reason,
      'supplier_credit_id', v_credit_id,
      'released_for_repayment', p_release_for_repayment,
      'removed_from_lists', v_removed_from_lists
    ),
    jsonb_build_object(
      'reason', p_reason,
      'amount', v_paid_amount,
      'supplier_credit_id', v_credit_id,
      'valid_until', p_valid_until,
      'released_for_repayment', p_release_for_repayment
    ),
    v_tx.company_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'transaction_id', p_tx_id,
    'kind', p_kind,
    'supplier_credit_id', v_credit_id,
    'released_for_repayment', p_release_for_repayment,
    'new_status', CASE WHEN p_release_for_repayment THEN 'pending' ELSE 'reversed' END,
    'removed_from_lists', v_removed_from_lists
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.revert_to_bp_version(_version_id uuid, _force boolean DEFAULT false, _performed_by uuid DEFAULT NULL::uuid, _performed_by_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target RECORD;
  v_event RECORD;
  v_split RECORD;
  v_split_target_id uuid;
BEGIN
  -- D-ERP38: portao de permissao e isolamento de empresa.
  DECLARE
    v_uid uuid := auth.uid();
    v_company uuid;
  BEGIN
    -- auth.uid() NULL = service_role / cron / edge function: isencao deliberada,
    -- mesmo padrao de enforce_transaction_approval_permission.
    IF v_uid IS NOT NULL THEN
      IF NOT (public.is_platform_admin(v_uid)
              OR public.has_role(v_uid, 'admin'::app_role)
              OR public.has_permission(v_uid, 'manage_bp')) THEN
        RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
      END IF;
      IF NOT public.is_platform_admin(v_uid) THEN
        SELECT e.company_id INTO v_company FROM public.bp_versions v JOIN public.events e ON e.id = v.event_id WHERE v.id = _version_id;
        IF v_company IS NULL OR v_company IS DISTINCT FROM public.current_company_id() THEN
          RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;
  END;
  -- D-ERP38: autoria nao forjavel. Com utilizador, ignora o parametro recebido;
  -- com auth.uid() NULL (service_role) usa-se o parametro como antes.
  _performed_by := COALESCE(auth.uid(), _performed_by);
  SELECT * INTO v_target FROM public.bp_versions WHERE id = _version_id;
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Version % not found', _version_id;
  END IF;

  IF v_target.state = 'archived' THEN
    RAISE EXCEPTION 'Não é possível reverter para uma versão arquivada. Desarquive-a primeiro.';
  END IF;

  IF v_target.scenario_label IS NOT NULL THEN
    RAISE EXCEPTION 'Cenários de trabalho não podem ser usados para reversão. Promova-o a versão oficial primeiro.';
  END IF;

  IF v_target.state = 'active' THEN
    RAISE EXCEPTION 'A versão alvo já é a versão ativa.';
  END IF;

  SELECT id, parent_event_id INTO v_event FROM public.events WHERE id = v_target.event_id;
  IF v_event.parent_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'Reverta no Master para sincronizar todos os Splits.';
  END IF;

  -- Revert master/standalone first
  PERFORM public._revert_event_to_version(
    v_target.event_id, _version_id, _performed_by, _performed_by_label, _force
  );

  -- Cascade to splits — pick each split's version cascaded from this master version
  FOR v_split IN
    SELECT id FROM public.events WHERE parent_event_id = v_event.id
  LOOP
    SELECT id INTO v_split_target_id
      FROM public.bp_versions
     WHERE event_id = v_split.id
       AND cascaded_from_version_id = _version_id
     LIMIT 1;

    IF v_split_target_id IS NOT NULL THEN
      PERFORM public._revert_event_to_version(
        v_split.id, v_split_target_id, _performed_by, _performed_by_label, _force
      );
    END IF;
  END LOOP;

  RETURN _version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_ticket_office_settlement(p_settlement_id uuid, p_payload jsonb, p_confirm boolean, p_selected jsonb, p_transfer jsonb, p_retained_payment_notes text, p_remainder_payment_notes text, p_audit_user text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_company uuid;
  v_id uuid;
  v_prev public.ticket_office_settlements%ROWTYPE;
  v_has_prev boolean := false;
  v_office uuid := (p_payload->>'financial_account_id')::uuid;
  v_event uuid := nullif(p_payload->>'event_id','')::uuid;
  v_date date := (p_payload->>'settlement_date')::date;
  v_ids uuid[];
  v_ret_amt numeric := coalesce((p_payload->>'venue_retained_amount')::numeric, 0);
  v_inv uuid := nullif(p_payload->>'venue_retained_invoice_id','')::uuid;
  v_rem_applied boolean := coalesce((p_payload->>'venue_invoice_remainder_paid')::boolean, false);
  v_rem_amt numeric := coalesce((p_payload->>'venue_invoice_remainder_amount')::numeric, 0);
  v_need_rev boolean;
  v_need_rev_rem boolean;
  v_tx record;
  v_pay uuid;
  r record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão obrigatória' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.has_role(v_uid, 'admin') OR public.is_platform_admin(v_uid)
          OR public.has_permission(v_uid, 'manage_accounts')) THEN
    RAISE EXCEPTION 'Sem permissão para gravar o fecho de bilheteira' USING ERRCODE = '42501';
  END IF;
  v_company := public.current_company_id();
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Empresa activa não resolvida' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_office AND company_id = v_company) THEN
    RAISE EXCEPTION 'Bilheteira de outra empresa' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(array_agg((x->>'id')::uuid), '{}') INTO v_ids FROM jsonb_array_elements(coalesce(p_selected,'[]'::jsonb)) x;
  IF EXISTS (SELECT 1 FROM public.transactions t WHERE t.id = ANY(v_ids) AND t.company_id IS DISTINCT FROM v_company) THEN
    RAISE EXCEPTION 'Dedução de outra empresa' USING ERRCODE = '42501';
  END IF;
  IF v_inv IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.transactions WHERE id = v_inv AND company_id = v_company) THEN
    RAISE EXCEPTION 'Fatura de outra empresa' USING ERRCODE = '42501';
  END IF;

  IF p_settlement_id IS NOT NULL THEN
    SELECT * INTO v_prev FROM public.ticket_office_settlements WHERE id = p_settlement_id FOR UPDATE;
    IF v_prev.id IS NULL OR v_prev.company_id IS DISTINCT FROM v_company THEN
      RAISE EXCEPTION 'Fecho não encontrado nesta empresa' USING ERRCODE = '42501';
    END IF;
    v_has_prev := true;
    v_id := p_settlement_id;
    UPDATE public.ticket_office_settlements SET
      financial_account_id = v_office, event_id = v_event, settlement_date = v_date,
      gross_revenue = (p_payload->>'gross_revenue')::numeric,
      total_deductions = (p_payload->>'total_deductions')::numeric,
      net_calculated = (p_payload->>'net_calculated')::numeric,
      net_adjusted = nullif(p_payload->>'net_adjusted','')::numeric,
      adjustment_notes = p_payload->>'adjustment_notes',
      gross_adjustment_notes = p_payload->>'gross_adjustment_notes',
      forma_liquidacao_manual = p_payload->>'forma_liquidacao_manual',
      forma_liquidacao_manual_notes = p_payload->>'forma_liquidacao_manual_notes',
      net_transferred = coalesce((p_payload->>'net_transferred')::numeric, 0),
      transfer_account_id = nullif(p_payload->>'transfer_account_id','')::uuid,
      document_url = p_payload->>'document_url',
      document_name = p_payload->>'document_name',
      notes = p_payload->>'notes',
      venue_retained_amount = v_ret_amt,
      venue_retained_invoice_id = v_inv,
      venue_retained_notes = p_payload->>'venue_retained_notes',
      venue_invoice_remainder_paid = v_rem_applied,
      venue_invoice_remainder_amount = v_rem_amt,
      status = CASE WHEN p_confirm THEN 'confirmed' ELSE 'draft' END,
      closed_at = CASE WHEN p_confirm THEN now() ELSE closed_at END,
      closed_by = CASE WHEN p_confirm THEN v_uid ELSE closed_by END
    WHERE id = v_id;
  ELSE
    INSERT INTO public.ticket_office_settlements (
      company_id, financial_account_id, event_id, settlement_date, gross_revenue, total_deductions,
      net_calculated, net_adjusted, adjustment_notes, gross_adjustment_notes,
      forma_liquidacao_manual, forma_liquidacao_manual_notes, net_transferred, transfer_account_id,
      document_url, document_name, notes, venue_retained_amount, venue_retained_invoice_id,
      venue_retained_notes, venue_invoice_remainder_paid, venue_invoice_remainder_amount,
      status, closed_at, closed_by, created_by
    ) VALUES (
      v_company, v_office, v_event, v_date, (p_payload->>'gross_revenue')::numeric,
      (p_payload->>'total_deductions')::numeric, (p_payload->>'net_calculated')::numeric,
      nullif(p_payload->>'net_adjusted','')::numeric, p_payload->>'adjustment_notes',
      p_payload->>'gross_adjustment_notes', p_payload->>'forma_liquidacao_manual',
      p_payload->>'forma_liquidacao_manual_notes', coalesce((p_payload->>'net_transferred')::numeric, 0),
      nullif(p_payload->>'transfer_account_id','')::uuid, p_payload->>'document_url',
      p_payload->>'document_name', p_payload->>'notes', v_ret_amt, v_inv,
      p_payload->>'venue_retained_notes', v_rem_applied, v_rem_amt,
      CASE WHEN p_confirm THEN 'confirmed' ELSE 'draft' END,
      CASE WHEN p_confirm THEN now() END, CASE WHEN p_confirm THEN v_uid END, v_uid
    ) RETURNING id INTO v_id;
  END IF;

  IF p_confirm AND p_transfer IS NOT NULL AND coalesce((p_transfer->>'amount')::numeric,0) > 0
     AND NOT (v_has_prev AND v_prev.transfer_transaction_id IS NOT NULL) THEN
    PERFORM public.create_settlement_transfer(v_id, v_office, (p_transfer->>'to_account_id')::uuid,
      (p_transfer->>'amount')::numeric, v_date, coalesce((p_transfer->>'credited')::boolean, false));
  END IF;

  IF v_has_prev THEN
    UPDATE public.transactions t SET settlement_id = NULL
     WHERE t.settlement_id = v_id
       AND NOT (t.id = ANY(v_ids))
       AND t.id IS DISTINCT FROM (SELECT transfer_transaction_id FROM public.ticket_office_settlements WHERE id = v_id)
       AND coalesce(t.operation_key,'') NOT LIKE 'TRF-FECHO-%';
  END IF;

  IF array_length(v_ids,1) > 0 THEN
    IF p_confirm THEN
      FOR r IN SELECT (x->>'id')::uuid AS id, (x->>'paid_amount')::numeric AS paid
                 FROM jsonb_array_elements(p_selected) x LOOP
        IF r.paid IS NULL THEN
          UPDATE public.transactions SET settlement_id = v_id WHERE id = r.id;
          CONTINUE;
        END IF;
        SELECT id, reversed_at INTO v_tx FROM public.transactions WHERE id = r.id FOR UPDATE;
        IF v_tx.id IS NULL THEN RAISE EXCEPTION 'Dedução % não encontrada', r.id; END IF;
        UPDATE public.transactions SET settlement_id = v_id, status = 'paid', payment_date = v_date,
               account_id = v_office, paid_amount = r.paid,
               reversed_at = CASE WHEN v_tx.reversed_at IS NOT NULL THEN NULL ELSE reversed_at END,
               reversal_kind = CASE WHEN v_tx.reversed_at IS NOT NULL THEN NULL ELSE reversal_kind END
         WHERE id = r.id;
        IF v_tx.reversed_at IS NOT NULL THEN
          INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
          VALUES (r.id, p_audit_user, 'Estorno', 'Estornada em ' || to_char(v_tx.reversed_at, 'YYYY-MM-DD'),
                  'Carimbo de estorno limpo — transação voltou a ser paga');
        END IF;
      END LOOP;
    ELSE
      UPDATE public.transactions SET settlement_id = v_id WHERE id = ANY(v_ids);
    END IF;
  END IF;

  v_need_rev := v_has_prev AND v_prev.venue_retained_payment_id IS NOT NULL AND (
    NOT p_confirm OR v_inv IS NULL OR v_inv IS DISTINCT FROM v_prev.venue_retained_invoice_id
    OR abs(v_ret_amt - coalesce(v_prev.venue_retained_amount,0)) > 0.005);
  IF v_need_rev THEN
    DELETE FROM public.transaction_payments WHERE id = v_prev.venue_retained_payment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento de compensação anterior não encontrado'; END IF;
    UPDATE public.ticket_office_settlements SET venue_retained_payment_id = NULL WHERE id = v_id;
  END IF;

  IF p_confirm AND v_ret_amt > 0 AND v_inv IS NOT NULL
     AND (v_need_rev OR NOT v_has_prev OR v_prev.venue_retained_payment_id IS NULL) THEN
    INSERT INTO public.transaction_payments (transaction_id, amount, payment_date, payment_method, account_id, notes, created_by)
    VALUES (v_inv, v_ret_amt, v_date, 'compensation', NULL, p_retained_payment_notes, p_audit_user)
    RETURNING id INTO v_pay;
    UPDATE public.ticket_office_settlements SET venue_retained_payment_id = v_pay WHERE id = v_id;
  END IF;

  v_need_rev_rem := v_has_prev AND v_prev.venue_invoice_remainder_payment_id IS NOT NULL AND (
    NOT p_confirm OR NOT v_rem_applied OR v_inv IS NULL
    OR v_inv IS DISTINCT FROM v_prev.venue_retained_invoice_id
    OR abs(v_rem_amt - coalesce(v_prev.venue_invoice_remainder_amount,0)) > 0.005);
  IF v_need_rev_rem THEN
    DELETE FROM public.transaction_payments WHERE id = v_prev.venue_invoice_remainder_payment_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento do saldo restante anterior não encontrado'; END IF;
    UPDATE public.ticket_office_settlements SET venue_invoice_remainder_payment_id = NULL WHERE id = v_id;
  END IF;

  IF p_confirm AND v_rem_applied AND v_inv IS NOT NULL
     AND (v_need_rev_rem OR NOT v_has_prev OR v_prev.venue_invoice_remainder_payment_id IS NULL) THEN
    INSERT INTO public.transaction_payments (transaction_id, amount, payment_date, payment_method, account_id, notes, created_by)
    VALUES (v_inv, v_rem_amt, v_date, 'transfer', v_office, p_remainder_payment_notes, p_audit_user)
    RETURNING id INTO v_pay;
    UPDATE public.ticket_office_settlements SET venue_invoice_remainder_payment_id = v_pay WHERE id = v_id;
  END IF;

  IF p_confirm AND v_event IS NOT NULL THEN
    UPDATE public.event_ticket_office_assignments
       SET is_conciliated = true, conciliated_at = now(), conciliated_by = coalesce(nullif(p_payload->>'conciliated_by',''), 'system')
     WHERE event_id = v_event AND financial_account_id = v_office;
  END IF;

  RETURN jsonb_build_object('settlement_id', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.seal_event_settlement(_settlement_id uuid, _snapshot jsonb, _bp_version_id uuid DEFAULT NULL::uuid, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.event_settlements; v_c1 numeric; v_c2 numeric; v_bp_event uuid; v_tol numeric := 0.005; v_bench jsonb;
BEGIN
  IF NOT (has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')
          OR has_permission(auth.uid(),'manage_bp')) THEN
    RAISE EXCEPTION 'Sem permissão para selar fechamentos';
  END IF;

  SELECT * INTO v_row FROM public.event_settlements WHERE id = _settlement_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Fechamento % não existe', _settlement_id; END IF;
  IF v_row.company_id <> current_company_id() THEN RAISE EXCEPTION 'Fechamento de outra empresa'; END IF;
  IF v_row.is_sealed THEN RAISE EXCEPTION 'Este fechamento já está selado'; END IF;
  IF _snapshot IS NULL THEN RAISE EXCEPTION 'Snapshot do resultado em falta'; END IF;

  v_c1 := COALESCE((_snapshot->>'check1')::numeric, 0);
  v_c2 := COALESCE((_snapshot->>'check2')::numeric, 0);
  IF abs(v_c1) > v_tol OR abs(v_c2) > v_tol THEN
    RAISE EXCEPTION 'Só é possível selar com as verificações a zero (C1=%, C2=%)', v_c1, v_c2;
  END IF;

  IF _bp_version_id IS NOT NULL THEN
    SELECT event_id INTO v_bp_event FROM public.bp_versions WHERE id = _bp_version_id;
    IF v_bp_event IS NULL OR v_bp_event <> v_row.event_id THEN
      RAISE EXCEPTION 'A versão de BP não pertence a este evento';
    END IF;
  END IF;

  PERFORM set_config('app.settlement_seal_op', 'on', true);

  UPDATE public.event_settlements SET
    is_sealed = true,
    sealed_at = now(),
    sealed_by = auth.uid(),
    sealed_bp_version_id = _bp_version_id,
    sealed_snapshot = _snapshot,
    seal_note = _note,
    unsealed_at = NULL, unsealed_by = NULL, unseal_reason = NULL
  WHERE id = _settlement_id;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, new_data, company_id)
  VALUES ('event_settlements', _settlement_id::text, 'settlement_sealed', COALESCE(auth.uid()::text,'system'),
          jsonb_build_object('bp_version_id', _bp_version_id, 'note', _note, 'check1', v_c1, 'check2', v_c2),
          v_row.company_id);

  IF v_row.parent_id IS NULL THEN
    BEGIN
      v_bench := public.collect_event_benchmarks(v_row.event_id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'collect_event_benchmarks falhou para %: %', v_row.event_id, SQLERRM;
    END;
  END IF;

  RETURN jsonb_build_object('ok', true, 'settlement_id', _settlement_id, 'bp_version_id', _bp_version_id, 'benchmarks', v_bench);
END $function$

CREATE OR REPLACE FUNCTION public.set_active_company(target_company_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_ok boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  PERFORM set_config('app.via_set_active_company', 'on', true);
  IF target_company_id IS NULL THEN
    UPDATE public.profiles SET active_company_id = NULL WHERE id = v_uid;
    RETURN NULL;
  END IF;
  IF public.is_platform_admin(v_uid) THEN
    SELECT EXISTS(SELECT 1 FROM public.companies
      WHERE id = target_company_id AND status='active') INTO v_ok;
  ELSE
    SELECT EXISTS(SELECT 1 FROM public.user_roles ur
      JOIN public.companies c ON c.id = ur.company_id
      WHERE ur.user_id = v_uid AND ur.company_id = target_company_id
        AND c.status='active') INTO v_ok;
  END IF;
  IF NOT v_ok THEN
    RAISE EXCEPTION 'No membership in target company %', target_company_id;
  END IF;
  UPDATE public.profiles SET active_company_id = target_company_id WHERE id = v_uid;
  RETURN target_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_company_default_budget_mode(_mode text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_company uuid := public.current_company_id(); v_n int;
BEGIN
  IF _mode NOT IN ('with_bp','without_bp') THEN
    RAISE EXCEPTION 'Modo orçamental inválido: %', _mode USING ERRCODE = '22023';
  END IF;
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'Sem empresa activa.' USING ERRCODE = '42501';
  END IF;
  IF NOT (public.is_platform_admin(auth.uid())
          OR public.has_role_in(auth.uid(), 'admin', v_company)
          OR public.has_role_in(auth.uid(), 'manager', v_company)) THEN
    RAISE EXCEPTION 'Sem permissão para alterar o modo orçamental da empresa.' USING ERRCODE = '42501';
  END IF;
  UPDATE public.companies SET default_budget_mode = _mode WHERE id = v_company;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 1 THEN RAISE EXCEPTION 'Empresa não encontrada.' USING ERRCODE = 'P0002'; END IF;
  RETURN _mode;
END $function$

CREATE OR REPLACE FUNCTION public.set_forecast_amount_observed(_forecast_id uuid, _amount numeric, _observation text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_row record;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão em falta' USING ERRCODE = '42501'; END IF;
  SELECT id, company_id, amount INTO v_row FROM event_forecasts WHERE id = _forecast_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Linha de BP não encontrada' USING ERRCODE = 'P0002'; END IF;
  IF NOT public.row_belongs_to_current_company(v_row.company_id) THEN RAISE EXCEPTION 'Linha de outra empresa' USING ERRCODE = '42501'; END IF;
  IF NOT (public.is_platform_admin() OR public.has_permission_in(v_uid, 'manage_bp', v_row.company_id)) THEN
    RAISE EXCEPTION 'Sem permissão para editar o BP (manage_bp).' USING ERRCODE = '42501';
  END IF;
  IF _amount IS NULL OR _amount < 0 THEN RAISE EXCEPTION 'Valor inválido' USING ERRCODE = '22023'; END IF;

  PERFORM set_config('mp.bp_change_observation', coalesce(trim(_observation), ''), true);
  UPDATE event_forecasts SET amount = _amount, updated_at = now() WHERE id = _forecast_id;
  PERFORM set_config('mp.bp_change_observation', '', true);
  RETURN jsonb_build_object('id', _forecast_id, 'old_amount', v_row.amount, 'new_amount', _amount);
END $function$

CREATE OR REPLACE FUNCTION public.set_partner_portal_user(_supplier_id uuid, _profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sup_company uuid;
  _prof_company uuid;
  _caller_email text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessao invalida.' USING ERRCODE = '42501';
  END IF;

  SELECT company_id INTO _sup_company FROM public.suppliers WHERE id = _supplier_id;
  IF _sup_company IS NULL THEN
    RAISE EXCEPTION 'Entidade nao encontrada.' USING ERRCODE = '42704';
  END IF;

  IF NOT (public.is_platform_admin(auth.uid())
          OR (public.has_role(auth.uid(), 'admin'::app_role)
              AND EXISTS (SELECT 1 FROM public.profiles me
                          WHERE me.id = auth.uid() AND me.company_id = _sup_company))) THEN
    RAISE EXCEPTION 'Sem permissao para ligar utilizadores do Portal.' USING ERRCODE = '42501';
  END IF;

  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'Indique o utilizador a ligar ou a desligar.' USING ERRCODE = '22023';
  END IF;

  SELECT company_id INTO _prof_company FROM public.profiles WHERE id = _profile_id;
  IF _prof_company IS NULL THEN
    RAISE EXCEPTION 'Utilizador nao encontrado.' USING ERRCODE = '42704';
  END IF;
  IF _prof_company IS DISTINCT FROM _sup_company THEN
    RAISE EXCEPTION 'Utilizador e entidade pertencem a empresas diferentes.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_roles ur
                 WHERE ur.user_id = _profile_id AND ur.role = 'partner'::app_role) THEN
    RAISE EXCEPTION 'So utilizadores com perfil de parceiro podem ser ligados a um socio.' USING ERRCODE = '42501';
  END IF;

  -- Um sócio tem N representantes. Ligar um utilizador NUNCA desliga outro:
  -- a ligação é do utilizador, e cada utilizador representa um sócio.
  UPDATE public.profiles SET linked_supplier_id = _supplier_id WHERE id = _profile_id;

  SELECT email INTO _caller_email FROM public.profiles WHERE id = auth.uid();

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, company_id, metadata)
  VALUES ('partner_portal_link', _supplier_id, 'link',
          COALESCE(_caller_email, auth.uid()::text), _sup_company,
          jsonb_build_object('supplier_id', _supplier_id, 'profile_id', _profile_id,
                             'profile_email', (SELECT email FROM public.profiles WHERE id = _profile_id),
                             'caller_id', auth.uid()));

  RETURN _profile_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.settlement_partner_quota_context(_settlement_id uuid, _supplier_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.event_settlements; v_p public.event_settlement_participants;
        v_event_name text; v_partner_name text; v_gross boolean; v_locals numeric;
BEGIN
  SELECT * INTO v_row FROM public.event_settlements WHERE id = _settlement_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Fechamento % não existe', _settlement_id; END IF;
  IF v_row.company_id <> current_company_id() THEN RAISE EXCEPTION 'Fechamento de outra empresa'; END IF;

  SELECT * INTO v_p FROM public.event_settlement_participants
   WHERE settlement_id = _settlement_id AND supplier_id = _supplier_id LIMIT 1;
  IF v_p.id IS NULL THEN RAISE EXCEPTION 'Este sócio não participa neste fechamento'; END IF;

  SELECT name INTO v_event_name FROM public.events WHERE id = v_row.event_id;
  SELECT name INTO v_partner_name FROM public.suppliers WHERE id = _supplier_id;

  SELECT COALESCE(v_p.expense_includes_iva, e.partner_calc_basis = 'gross')
    INTO v_gross FROM public.events e WHERE e.id = v_row.event_id;

  v_locals := v_row.parent_share_pct; -- percentagem contratada do resultado do evento

  RETURN jsonb_build_object(
    'event_name', v_event_name,
    'partner_name', v_partner_name,
    'gross_expenses', COALESCE(v_gross, false),
    'share_pct', v_locals,
    'share_basis', v_row.parent_share_basis,
    'partner_pct', v_p.profit_pct,
    'partner_loss_pct', v_p.loss_pct,
    'is_sealed', v_row.is_sealed,
    'sealed_at', v_row.sealed_at,
    'sealed_snapshot', CASE WHEN v_row.is_sealed THEN v_row.sealed_snapshot ELSE NULL END
  );
END $function$

CREATE OR REPLACE FUNCTION public.split_transaction_by_bp_lines(p_transaction_id uuid, p_lines jsonb, p_changed_by text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tx public.transactions%ROWTYPE; v_n int; v_sum numeric := 0; v_i int; v_item jsonb;
        v_fc record; v_amount numeric; v_group uuid; v_new_id uuid; v_event_status text; v_seen uuid[] := '{}';
BEGIN
  SELECT * INTO v_tx FROM public.transactions WHERE id = p_transaction_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'transaction_not_found' USING ERRCODE = 'P0002'; END IF;
  IF NOT (public.is_platform_admin(auth.uid())
          OR public.has_role_in(auth.uid(), 'admin', v_tx.company_id)
          OR public.has_role_in(auth.uid(), 'manager', v_tx.company_id)
          OR public.has_permission_in(auth.uid(), 'manage_transactions', v_tx.company_id)) THEN
    RAISE EXCEPTION 'Sem permissão para repartir a transação.' USING ERRCODE = '42501';
  END IF;
  IF v_tx.type <> 'expense' THEN RAISE EXCEPTION 'Só despesas podem ser repartidas por linhas de BP.'; END IF;
  IF v_tx.event_id IS NULL THEN RAISE EXCEPTION 'A transação não tem evento.'; END IF;
  IF coalesce(v_tx.paid_amount,0) > 0 OR v_tx.status IN ('paid','reversed')
     OR EXISTS (SELECT 1 FROM public.transaction_payments WHERE transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'A transação já tem pagamentos — reparte antes de pagar.';
  END IF;
  IF v_tx.parent_transaction_id IS NOT NULL OR v_tx.split_percentage IS NOT NULL
     OR EXISTS (SELECT 1 FROM public.transactions WHERE parent_transaction_id = p_transaction_id) THEN
    RAISE EXCEPTION 'Transações de rateio entre eventos não podem ser repartidas aqui.';
  END IF;
  IF v_tx.installment_group_id IS NOT NULL THEN RAISE EXCEPTION 'A transação pertence a um parcelamento.'; END IF;
  IF coalesce(v_tx.is_reimbursement,false) OR coalesce(v_tx.is_transitory,false) THEN
    RAISE EXCEPTION 'Reembolsos e transitórias não podem ser repartidos.';
  END IF;
  SELECT status INTO v_event_status FROM public.events WHERE id = v_tx.event_id;
  IF v_event_status = 'completed' THEN RAISE EXCEPTION 'O evento está fechado.'; END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' THEN RAISE EXCEPTION 'Lista de linhas inválida.'; END IF;
  v_n := jsonb_array_length(p_lines);
  IF v_n < 2 THEN RAISE EXCEPTION 'São precisas pelo menos 2 linhas de BP.'; END IF;

  FOR v_i IN 0..v_n-1 LOOP
    v_item := p_lines -> v_i;
    v_amount := round((v_item->>'amount')::numeric, 2);
    IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'Linha % com valor inválido.', v_i+1; END IF;
    SELECT id, event_id, category_id, type, version_id, company_id INTO v_fc
      FROM public.event_forecasts WHERE id = (v_item->>'forecast_id')::uuid;
    IF NOT FOUND OR v_fc.event_id <> v_tx.event_id OR v_fc.company_id <> v_tx.company_id
       OR v_fc.version_id IS NOT NULL OR v_fc.type <> 'expense' THEN
      RAISE EXCEPTION 'Linha % não é uma linha de despesa do BP vivo deste evento.', v_i+1;
    END IF;
    IF v_fc.id = ANY(v_seen) THEN RAISE EXCEPTION 'Linha de BP repetida.'; END IF;
    v_seen := v_seen || v_fc.id;
    v_sum := v_sum + v_amount;
  END LOOP;
  IF abs(v_sum - v_tx.amount) > 0.01 THEN
    RAISE EXCEPTION 'A soma das partes (% €) tem de igualar o valor da transação (% €, s/IVA).', v_sum, v_tx.amount;
  END IF;

  v_group := coalesce(v_tx.invoice_group_id, gen_random_uuid());

  FOR v_i IN 0..v_n-1 LOOP
    v_item := p_lines -> v_i;
    v_amount := round((v_item->>'amount')::numeric, 2);
    SELECT id, category_id INTO v_fc FROM public.event_forecasts WHERE id = (v_item->>'forecast_id')::uuid;
    IF v_i = 0 THEN
      UPDATE public.transactions
         SET amount = v_amount, forecast_id = v_fc.id, category_id = v_fc.category_id,
             invoice_group_id = v_group,
             original_amount = CASE WHEN coalesce(v_tx.currency,'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND v_tx.amount <> 0
                                    THEN round(v_tx.original_amount * v_amount / v_tx.amount, 2) ELSE v_tx.original_amount END,
             updated_at = now()
       WHERE id = p_transaction_id;
      INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value) VALUES
        (p_transaction_id, p_changed_by, 'Valor (repartir por linhas de BP)', round(v_tx.amount,2)::text, v_amount::text),
        (p_transaction_id, p_changed_by, 'Linha de BP (repartir)', coalesce(v_tx.forecast_id::text,''), v_fc.id::text);
    ELSE
      INSERT INTO public.transactions (
        description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        specification, date, due_date, status, paid_amount, payment_date,
        is_reimbursement, is_transitory, exclude_from_result,
        invoice_ref, invoice_group_id, payment_method, payment_entity, payment_reference, operation_key,
        ordering_partner_id, paying_partner_id, currency, fx_rate, fx_rate_source, original_amount, company_id
      ) VALUES (
        v_tx.description, v_tx.type, v_amount, v_tx.iva_rate, v_tx.event_id, v_fc.category_id, v_fc.id, v_tx.supplier_id, v_tx.account_id,
        v_tx.specification, v_tx.date, v_tx.due_date, v_tx.status, 0, NULL,
        false, false, coalesce(v_tx.exclude_from_result,false),
        v_tx.invoice_ref, v_group, v_tx.payment_method, v_tx.payment_entity, v_tx.payment_reference, v_tx.operation_key,
        v_tx.ordering_partner_id, v_tx.paying_partner_id, coalesce(v_tx.currency,'EUR'), v_tx.fx_rate, v_tx.fx_rate_source,
        CASE WHEN coalesce(v_tx.currency,'EUR') <> 'EUR' AND v_tx.original_amount IS NOT NULL AND v_tx.amount <> 0
             THEN round(v_tx.original_amount * v_amount / v_tx.amount, 2) ELSE NULL END,
        v_tx.company_id
      ) RETURNING id INTO v_new_id;
      INSERT INTO public.transaction_documents (transaction_id, name, file_url, doc_type, uploaded_by, uploaded_at, is_accounting, company_id, partner_visible)
        SELECT v_new_id, name, file_url, doc_type, uploaded_by, uploaded_at, is_accounting, company_id, partner_visible
          FROM public.transaction_documents WHERE transaction_id = p_transaction_id;
      INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
        VALUES (v_new_id, p_changed_by, 'Criação (repartir por linhas de BP)', p_transaction_id::text, v_amount::text || ' € (base) → linha ' || v_fc.id::text);
    END IF;
  END LOOP;
  RETURN v_group;
END $function$

CREATE OR REPLACE FUNCTION public.supplier_resolve_or_create(p_name text, p_nif text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_company uuid := public.current_company_id();
BEGIN
  IF auth.uid() IS NULL OR v_company IS NULL THEN RAISE EXCEPTION 'Empresa activa não definida' USING ERRCODE = '42501'; END IF;
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'manager') OR public.has_role(auth.uid(), 'editor')) THEN
    RAISE EXCEPTION 'Sem permissão para criar fornecedores' USING ERRCODE = '42501';
  END IF;
  IF p_source NOT IN ('sponsors_import') THEN RAISE EXCEPTION 'Origem inválida'; END IF;
  RETURN public._supplier_resolve_or_create(v_company, p_name, p_nif, p_source);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_etapa_principal_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.role = 'principal' THEN
      UPDATE public.operacao_etapas SET supplier_id = NULL WHERE id = OLD.etapa_id;
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.role = 'principal' THEN
    UPDATE public.operacao_etapas SET supplier_id = NEW.supplier_id WHERE id = NEW.etapa_id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_paid_amount_from_payments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  PERFORM public._derive_paid_amount(COALESCE(NEW.transaction_id, OLD.transaction_id));
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_partner_aporte_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_src       record;
  v_acc       record;
  v_partner   record;
  v_cat_id    uuid;
  v_amount    numeric := 0;
  v_bridge_id uuid;
  v_aporte_id uuid;
  v_ret       record;
begin
  if TG_OP = 'DELETE' then v_src := OLD; else v_src := NEW; end if;
  if TG_OP = 'DELETE' then v_ret := OLD; else v_ret := NEW; end if;

  -- Só despesas geram aporte. O aporte espelhado e receita, logo nunca se espelha a si proprio.
  if v_src.type is distinct from 'expense' then
    return v_ret;
  end if;

  select id, aporte_transaction_id into v_bridge_id, v_aporte_id
    from partner_aporte_mirror
   where source_transaction_id = v_src.id;

  if TG_OP <> 'DELETE' then
    select * into v_acc from financial_accounts where id = NEW.account_id;
    if v_acc.id is not null
       and coalesce(v_acc.mirror_partner_aporte, false)
       and v_acc.partner_id is not null
       and NEW.status = 'paid'
       and NEW.reversed_at is null
    then
      v_amount := coalesce(NEW.paid_amount, 0);
    end if;
  end if;

  -- Nada a fazer
  if v_amount <= 0 and v_bridge_id is null then
    return v_ret;
  end if;

  -- Deixou de haver aporte: apagar o espelho (a ponte e o movimento de capital caem por cascata)
  if v_amount <= 0 then
    delete from transactions where id = v_aporte_id;
    return v_ret;
  end if;

  select * into v_partner from event_partners where id = v_acc.partner_id;
  select id into v_cat_id from account_categories
   where company_id = NEW.company_id and code = '10.1.01' limit 1;
  if v_cat_id is null then
    raise exception 'Conta-espelho: rubrica 10.1.01 nao existe na empresa %', NEW.company_id;
  end if;

  if v_bridge_id is null then
    insert into transactions (
      company_id, type, description, amount, paid_amount, iva_rate,
      date, payment_date, status, account_id, event_id, supplier_id,
      category_id, payment_method
    ) values (
      NEW.company_id, 'income',
      'Aporte automatico — ' || NEW.description,
      v_amount, v_amount, 0,
      coalesce(NEW.payment_date, NEW.date), coalesce(NEW.payment_date, NEW.date), 'paid',
      NEW.account_id, v_partner.event_id, v_partner.supplier_id,
      v_cat_id, 'transfer'
    ) returning id into v_aporte_id;

    insert into partner_aporte_mirror
      (company_id, account_id, source_transaction_id, aporte_transaction_id)
    values (NEW.company_id, NEW.account_id, NEW.id, v_aporte_id);

    insert into partner_capital_moves
      (company_id, event_id, partner_id, transaction_id, kind, flow)
    values (NEW.company_id, v_partner.event_id, v_acc.partner_id, v_aporte_id,
            'aporte', 'partner_settlement');
  else
    update transactions set
      description  = 'Aporte automatico — ' || NEW.description,
      amount       = v_amount,
      paid_amount  = v_amount,
      date         = coalesce(NEW.payment_date, NEW.date),
      payment_date = coalesce(NEW.payment_date, NEW.date),
      account_id   = NEW.account_id,
      event_id     = v_partner.event_id,
      supplier_id  = v_partner.supplier_id,
      updated_at   = now()
    where id = v_aporte_id;

    update partner_aporte_mirror
       set account_id = NEW.account_id, updated_at = now()
     where id = v_bridge_id;
  end if;

  return v_ret;
end;
$function$

CREATE OR REPLACE FUNCTION public.transaction_offset_create(p_receivable uuid, p_payable uuid, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid; v_pay uuid;
BEGIN
  INSERT INTO public.transaction_offsets (receivable_transaction_id, payable_transaction_id, amount, note)
  VALUES (p_receivable, p_payable, round(p_amount, 2), NULLIF(trim(COALESCE(p_note, '')), ''))
  RETURNING id INTO v_id;

  SELECT x.id INTO v_pay
    FROM public.transaction_payments x
   WHERE x.transaction_id IN (p_receivable, p_payable)
     AND x.payment_method <> 'compensation' AND x.status = 'paid' AND x.reversed_at IS NULL
   ORDER BY x.payment_date DESC, x.created_at DESC
   LIMIT 1;
  IF v_pay IS NOT NULL THEN
    PERFORM public._apply_transaction_offset(v_id, v_pay);
  END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.transaction_offset_remove(p_offset_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.transaction_payments x
              WHERE x.offset_id = p_offset_id AND x.status = 'paid' AND x.reversed_at IS NULL) THEN
    RAISE EXCEPTION 'Esta compensação já foi aplicada (há um pagamento por compensação ativo). Estorna primeiro o pagamento de origem.'
      USING ERRCODE = 'check_violation';
  END IF;
  UPDATE public.transaction_payments SET offset_id = NULL WHERE offset_id = p_offset_id;
  DELETE FROM public.transaction_offsets WHERE id = p_offset_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ligação de compensação não encontrada ou sem permissão.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_notify_co_lead_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_name text;
  v_event_name text;
  v_event_id uuid;
  v_frente_name text;
  v_frente_type text;
  v_current_lead uuid;
  v_was_lead boolean := false;
BEGIN
  -- Only notify if this row is an active lead
  IF NEW.role_in_frente <> 'lead' OR NEW.active IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  -- On UPDATE, only fire if this row just became a lead (or just became active)
  IF TG_OP = 'UPDATE' THEN
    v_was_lead := (OLD.role_in_frente = 'lead' AND OLD.active = true);
    IF v_was_lead THEN
      RETURN NEW;
    END IF;
  END IF;

  SELECT event_id, name,
         CASE type WHEN 'zone' THEN 'Zona' WHEN 'service' THEN 'Serviço' ELSE 'Frente' END,
         current_lead_id
    INTO v_event_id, v_frente_name, v_frente_type, v_current_lead
  FROM public.operacao_frentes WHERE id = NEW.frente_id;

  -- Avoid duplicate: if this profile is/will be the primary, trg_notify_lead_assigned
  -- on operacao_frentes will already enqueue the notification.
  IF v_current_lead = NEW.profile_id THEN
    RETURN NEW;
  END IF;

  SELECT full_name INTO v_user_name FROM public.profiles WHERE id = NEW.profile_id;
  SELECT name INTO v_event_name FROM public.events WHERE id = v_event_id;

  PERFORM public.enqueue_whatsapp_notification(
    'lead_atribuido_zona_servico',
    NEW.profile_id,
    jsonb_build_array(
      COALESCE(v_user_name,''), v_frente_type,
      COALESCE(v_frente_name,''), COALESCE(v_event_name,'')
    ),
    v_event_id, 'frente', NEW.frente_id
  );

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_notify_lead_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_name text; v_event_name text; v_frente_type text;
BEGIN
  IF NEW.current_lead_id IS DISTINCT FROM OLD.current_lead_id
     AND NEW.current_lead_id IS NOT NULL THEN
    SELECT full_name INTO v_user_name FROM public.profiles WHERE id = NEW.current_lead_id;
    SELECT name INTO v_event_name FROM public.events WHERE id = NEW.event_id;
    v_frente_type := CASE NEW.type
      WHEN 'zone' THEN 'Zona'
      WHEN 'service' THEN 'Serviço'
      ELSE 'Frente'
    END;
    PERFORM public.enqueue_whatsapp_notification(
      'lead_atribuido_zona_servico',
      NEW.current_lead_id,
      jsonb_build_array(
        COALESCE(v_user_name,''), v_frente_type,
        COALESCE(NEW.name,''), COALESCE(v_event_name,'')
      ),
      NEW.event_id, 'frente', NEW.id
    );
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_operacao_frente_lead_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current uuid;
  v_handover timestamptz;
  v_current_still_lead boolean;
BEGIN
  IF NEW.is_permanent_lead = true AND NEW.role_in_frente = 'lead' THEN
    SELECT current_lead_id, lead_handover_until
      INTO v_current, v_handover
    FROM public.operacao_frentes
    WHERE id = NEW.frente_id;

    -- Don't touch during active handover
    IF v_handover IS NOT NULL THEN
      RETURN NEW;
    END IF;

    -- Set as primary if frente has no primary yet
    IF v_current IS NULL THEN
      UPDATE public.operacao_frentes
        SET current_lead_id = NEW.profile_id
        WHERE id = NEW.frente_id;
      RETURN NEW;
    END IF;

    -- If the same profile already is the primary, nothing to do
    IF v_current = NEW.profile_id THEN
      RETURN NEW;
    END IF;

    -- Check whether the current primary still has an active permanent-lead row
    SELECT EXISTS (
      SELECT 1 FROM public.operacao_frente_team t
      WHERE t.frente_id = NEW.frente_id
        AND t.profile_id = v_current
        AND t.role_in_frente = 'lead'
        AND t.is_permanent_lead = true
        AND t.active = true
    ) INTO v_current_still_lead;

    -- Only take over the pointer if current primary is no longer a valid lead
    IF NOT v_current_still_lead THEN
      UPDATE public.operacao_frentes
        SET current_lead_id = NEW.profile_id
        WHERE id = NEW.frente_id;
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trg_vip_coupon_email_immediate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base text;
  v_key text;
BEGIN
  IF NEW.source IS NULL OR NEW.source NOT LIKE 'vip%' THEN
    RETURN NEW;
  END IF;
  IF NEW.email IS NULL OR btrim(NEW.email) = '' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.consent_email, false) IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  v_base := public.vip_coupon_functions_base_url();
  SELECT decrypted_secret INTO v_key
  FROM vault.decrypted_secrets
  WHERE name = 'email_queue_service_role_key'
  LIMIT 1;

  IF v_base IS NULL OR v_key IS NULL THEN
    RAISE WARNING 'trg_vip_coupon_email_immediate: base_url ou service_role secret em falta — e-mail nao disparado (lead %)', NEW.id;
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := v_base || '/functions/v1/vip-coupon-email?mode=immediate',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object('mode', 'immediate', 'lead_id', NEW.id),
    timeout_milliseconds := 30000
  );

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.unarchive_bp_version(_version_id uuid, _performed_by uuid DEFAULT NULL::uuid, _performed_by_label text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_version RECORD; v_split_version RECORD; v_new_state text;
BEGIN
  -- D-ERP38: portao de permissao e isolamento de empresa.
  DECLARE
    v_uid uuid := auth.uid();
    v_company uuid;
  BEGIN
    -- auth.uid() NULL = service_role / cron / edge function: isencao deliberada,
    -- mesmo padrao de enforce_transaction_approval_permission.
    IF v_uid IS NOT NULL THEN
      IF NOT (public.is_platform_admin(v_uid)
              OR public.has_role(v_uid, 'admin'::app_role)
              OR public.has_permission(v_uid, 'manage_bp')) THEN
        RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
      END IF;
      IF NOT public.is_platform_admin(v_uid) THEN
        SELECT e.company_id INTO v_company FROM public.bp_versions v JOIN public.events e ON e.id = v.event_id WHERE v.id = _version_id;
        IF v_company IS NULL OR v_company IS DISTINCT FROM public.current_company_id() THEN
          RAISE EXCEPTION 'Sem permissão para gerir o Business Plan deste evento.' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;
  END;
  -- D-ERP38: autoria nao forjavel. Com utilizador, ignora o parametro recebido;
  -- com auth.uid() NULL (service_role) usa-se o parametro como antes.
  _performed_by := COALESCE(auth.uid(), _performed_by);
  SELECT * INTO v_version FROM public.bp_versions WHERE id = _version_id;
  IF v_version IS NULL THEN RAISE EXCEPTION 'Version % not found', _version_id; END IF;
  IF v_version.state <> 'archived' THEN RETURN; END IF;
  IF v_version.approved_at IS NOT NULL THEN v_new_state := 'superseded'; ELSE v_new_state := 'draft'; END IF;
  UPDATE public.bp_versions SET state = v_new_state, archived_at = NULL WHERE id = _version_id;
  INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata)
  VALUES (_version_id, v_version.event_id, 'unarchived', _performed_by, _performed_by_label,
    jsonb_build_object('restored_state', v_new_state));
  FOR v_split_version IN SELECT * FROM public.bp_versions WHERE cascaded_from_version_id = _version_id LOOP
    IF v_split_version.state = 'archived' THEN
      UPDATE public.bp_versions SET state = v_new_state, archived_at = NULL WHERE id = v_split_version.id;
      INSERT INTO public.bp_version_audit_log (version_id, event_id, action, performed_by, performed_by_label, metadata)
      VALUES (v_split_version.id, v_split_version.event_id, 'unarchived', _performed_by, _performed_by_label,
        jsonb_build_object('restored_state', v_new_state, 'cascaded_from', _version_id));
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.unseal_event_settlement(_settlement_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.event_settlements;
BEGIN
  IF NOT has_permission(auth.uid(),'manage_bp') THEN
    RAISE EXCEPTION 'Sem permissão para reabrir fechamentos';
  END IF;
  IF _reason IS NULL OR btrim(_reason) = '' THEN
    RAISE EXCEPTION 'É obrigatório indicar o motivo da reabertura';
  END IF;

  SELECT * INTO v_row FROM public.event_settlements WHERE id = _settlement_id;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'Fechamento % não existe', _settlement_id; END IF;
  IF v_row.company_id <> current_company_id() THEN RAISE EXCEPTION 'Fechamento de outra empresa'; END IF;
  IF NOT v_row.is_sealed THEN RAISE EXCEPTION 'Este fechamento não está selado'; END IF;

  PERFORM set_config('app.settlement_seal_op', 'on', true);

  UPDATE public.event_settlements SET
    is_sealed = false,
    sealed_snapshot = NULL,
    unsealed_at = now(),
    unsealed_by = auth.uid(),
    unseal_reason = btrim(_reason)
  WHERE id = _settlement_id;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, company_id)
  VALUES ('event_settlements', _settlement_id::text, 'settlement_unsealed', COALESCE(auth.uid()::text,'system'),
          jsonb_build_object('sealed_at', v_row.sealed_at, 'sealed_by', v_row.sealed_by,
                             'sealed_bp_version_id', v_row.sealed_bp_version_id),
          jsonb_build_object('reason', btrim(_reason)),
          v_row.company_id);

  RETURN jsonb_build_object('ok', true, 'settlement_id', _settlement_id);
END $function$

CREATE OR REPLACE FUNCTION public.unset_partner_portal_user(_profile_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _prof_company uuid;
  _old_supplier uuid;
  _caller_email text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessao invalida.' USING ERRCODE = '42501';
  END IF;

  SELECT company_id, linked_supplier_id INTO _prof_company, _old_supplier
    FROM public.profiles WHERE id = _profile_id;
  IF _prof_company IS NULL THEN
    RAISE EXCEPTION 'Utilizador nao encontrado.' USING ERRCODE = '42704';
  END IF;

  IF NOT (public.is_platform_admin(auth.uid())
          OR (public.has_role(auth.uid(), 'admin'::app_role)
              AND EXISTS (SELECT 1 FROM public.profiles me
                          WHERE me.id = auth.uid() AND me.company_id = _prof_company))) THEN
    RAISE EXCEPTION 'Sem permissao para desligar utilizadores do Portal.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.profiles SET linked_supplier_id = NULL WHERE id = _profile_id;

  SELECT email INTO _caller_email FROM public.profiles WHERE id = auth.uid();

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, company_id, metadata)
  VALUES ('partner_portal_link', COALESCE(_old_supplier, _profile_id), 'unlink',
          COALESCE(_caller_email, auth.uid()::text), _prof_company,
          jsonb_build_object('supplier_id', _old_supplier, 'profile_id', _profile_id,
                             'profile_email', (SELECT email FROM public.profiles WHERE id = _profile_id),
                             'caller_id', auth.uid()));

  RETURN _old_supplier;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_cache_payment_contract(p_contract_id uuid, p_beneficiary_supplier_id uuid, p_gross numeric, p_withholding_applies boolean, p_withholding_rate numeric, p_withholding_due_date date, p_artist_due_date date, p_advance_ids uuid[] DEFAULT '{}'::uuid[], p_label text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := public._cache_assert_actor(); v_c record; v_new uuid;
BEGIN
  SELECT root_event_id, artist_supplier_id INTO v_c FROM public.cache_payment_contracts WHERE id = p_contract_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'contrato_inexistente'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('cache:' || v_c.root_event_id || ':' || v_c.artist_supplier_id, 0));
  PERFORM public._cache_cancel_contract(v_uid, p_contract_id, 'alterado');
  v_new := public._cache_create_contract(v_uid, v_c.root_event_id, v_c.artist_supplier_id, p_beneficiary_supplier_id, p_gross,
    p_withholding_applies, p_withholding_rate, p_withholding_due_date, p_artist_due_date, p_advance_ids, p_label, NULL);
  UPDATE public.cache_payment_contracts SET replaced_by = v_new WHERE id = p_contract_id;
  RETURN v_new;
END $function$

CREATE OR REPLACE FUNCTION public.update_planned_installments(p_transaction_id uuid, p_rows jsonb, p_changed_by text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_company uuid; v_old_sum numeric; v_new_sum numeric := 0; v_item jsonb; v_row record;
        v_amount numeric; v_date date; v_n int := 0; v_ids uuid[] := '{}';
BEGIN
  SELECT company_id INTO v_company FROM public.transactions WHERE id = p_transaction_id FOR UPDATE;
  IF v_company IS NULL THEN RAISE EXCEPTION 'transaction_not_found' USING ERRCODE = 'P0002'; END IF;
  IF NOT (public.is_platform_admin(auth.uid())
          OR public.has_role_in(auth.uid(), 'admin', v_company)
          OR public.has_role_in(auth.uid(), 'manager', v_company)) THEN
    RAISE EXCEPTION 'Sem permissão para editar o cronograma de parcelas.' USING ERRCODE = '42501';
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'Lista de parcelas inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(sum(amount),0) INTO v_old_sum FROM public.transaction_payments
   WHERE transaction_id = p_transaction_id AND status = 'planned';

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
    SELECT * INTO v_row FROM public.transaction_payments
     WHERE id = (v_item->>'id')::uuid AND transaction_id = p_transaction_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Parcela % não pertence a esta transação.', v_item->>'id' USING ERRCODE = '42501'; END IF;
    IF v_row.status <> 'planned' THEN
      RAISE EXCEPTION 'Só parcelas planeadas são editáveis aqui (parcela paga/cancelada travada).' USING ERRCODE = '42501';
    END IF;
    v_amount := round((v_item->>'amount')::numeric, 2);
    v_date := nullif(v_item->>'scheduled_date','')::date;
    IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'Parcela com valor inválido.' USING ERRCODE = '22023'; END IF;
    IF v_date IS NULL THEN RAISE EXCEPTION 'Parcela sem vencimento.' USING ERRCODE = '22023'; END IF;
    v_ids := v_ids || v_row.id;

    IF abs(v_amount - v_row.amount) > 0.001 OR v_date IS DISTINCT FROM v_row.scheduled_date THEN
      UPDATE public.transaction_payments SET amount = v_amount, scheduled_date = v_date, updated_at = now() WHERE id = v_row.id;
      IF abs(v_amount - v_row.amount) > 0.001 THEN
        INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
        VALUES (p_transaction_id, p_changed_by, 'Valor parcela planeada', round(v_row.amount,2)::text, v_amount::text);
      END IF;
      IF v_date IS DISTINCT FROM v_row.scheduled_date THEN
        INSERT INTO public.transaction_audit_log (transaction_id, changed_by, field_name, old_value, new_value)
        VALUES (p_transaction_id, p_changed_by, 'Vencimento parcela planeada', coalesce(v_row.scheduled_date::text,''), v_date::text);
      END IF;
      v_n := v_n + 1;
    END IF;
  END LOOP;

  SELECT coalesce(sum(amount),0) INTO v_new_sum FROM public.transaction_payments
   WHERE transaction_id = p_transaction_id AND status = 'planned';
  IF abs(v_new_sum - v_old_sum) > 0.01 THEN
    RAISE EXCEPTION 'A soma das parcelas planeadas (% €) tem de manter-se igual a % € para bater com o total.', v_new_sum, v_old_sum USING ERRCODE = '22023';
  END IF;
  RETURN v_n;
END $function$

CREATE OR REPLACE FUNCTION public.validate_camarim_item_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'approved' AND COALESCE(NEW.approved_without_document, false) = false THEN
    -- Fornecedor deixou de ser obrigatório: pequenas despesas de camarim
    -- (lanchonete, combustível, farmácia…) não devem sujar o cadastro.
    -- Sem fornecedor associado, usa-se o genérico "Diversos — Camarim" da empresa.
    IF NEW.supplier_id IS NULL THEN
      NEW.supplier_id := public.get_or_create_generic_camarim_supplier(
        COALESCE(NEW.company_id, public.current_company_id())
      );
    END IF;
    IF NEW.document_number IS NULL OR btrim(NEW.document_number) = '' THEN
      RAISE EXCEPTION 'Número do documento é obrigatório para aprovar um item de camarim';
    END IF;
    IF NEW.document_date IS NULL THEN
      RAISE EXCEPTION 'Data do documento é obrigatória para aprovar um item de camarim';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_team_member_zone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_event uuid;
  v_zone_event uuid;
  v_zone_type text;
BEGIN
  SELECT event_id INTO v_member_event FROM public.event_team_members WHERE id = NEW.member_id;
  SELECT event_id, type INTO v_zone_event, v_zone_type FROM public.operacao_frentes WHERE id = NEW.zone_id;
  IF v_zone_type IS DISTINCT FROM 'zone' THEN
    RAISE EXCEPTION 'zone_id % não é frente type=zone', NEW.zone_id;
  END IF;
  IF v_zone_event IS DISTINCT FROM v_member_event THEN
    RAISE EXCEPTION 'zone_id e member pertencem a eventos diferentes';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_installments_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_amount numeric;
  v_iva_rate numeric;
  v_gross numeric;
  v_others numeric;
  v_sum numeric;
  v_old_sum numeric;
BEGIN
  SELECT amount, COALESCE(iva_rate, 0)
    INTO v_tx_amount, v_iva_rate
    FROM public.transactions
    WHERE id = NEW.transaction_id;

  IF v_tx_amount IS NULL THEN
    RETURN NEW;
  END IF;

  v_gross := v_tx_amount * (1 + v_iva_rate / 100.0);

  IF v_gross <= 0 THEN
    RETURN NEW;
  END IF;

  -- Soma das outras linhas (planned + paid; cancelled não conta)
  SELECT COALESCE(SUM(amount), 0)
    INTO v_others
    FROM public.transaction_payments
    WHERE transaction_id = NEW.transaction_id
      AND status IN ('planned','paid')
      AND id <> NEW.id;

  v_sum := v_others;
  IF NEW.status IN ('planned','paid') THEN
    v_sum := v_sum + NEW.amount;
  END IF;

  IF v_sum > v_gross + 0.01 THEN
    IF TG_OP = 'UPDATE' THEN
      v_old_sum := v_others;
      IF OLD.status IN ('planned','paid') THEN
        v_old_sum := v_old_sum + OLD.amount;
      END IF;
      -- linha legada: permitir desde que não piore
      IF v_sum <= v_old_sum THEN
        RETURN NEW;
      END IF;
    END IF;

    RAISE EXCEPTION 'Soma das parcelas (% €) excede o valor bruto da transação (% €).',
      ROUND(v_sum::numeric, 2), ROUND(v_gross::numeric, 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_trusted_device(_token_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  IF auth.uid() IS NULL OR _token_hash IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT id INTO v_id
  FROM public.mfa_trusted_devices
  WHERE user_id = auth.uid()
    AND device_token_hash = _token_hash
    AND revoked_at IS NULL
    AND expires_at > now()
  LIMIT 1;

  IF v_id IS NULL THEN
    RETURN FALSE;
  END IF;

  UPDATE public.mfa_trusted_devices
  SET last_used_at = now()
  WHERE id = v_id;

  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_ads_budget_cap_remove(p_connection_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_company uuid; v_artist uuid;
BEGIN
  SELECT company_id, artist_id INTO v_company, v_artist FROM crm.ad_platform_connections
  WHERE id = p_connection_id AND connection_scope = 'artist';
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'ligação de anúncios de artista inexistente' USING ERRCODE = '42501';
  END IF;
  PERFORM public.artist_access_check(v_artist,'admin',NULL);
  DELETE FROM crm.artist_ads_budget_caps WHERE connection_id = p_connection_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_budget_cap_set(p_connection_id uuid, p_daily_cap numeric, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_conn crm.ad_platform_connections; v_id uuid;
BEGIN
  SELECT * INTO v_conn FROM crm.ad_platform_connections
  WHERE id = p_connection_id AND connection_scope = 'artist';
  IF v_conn.id IS NULL THEN
    RAISE EXCEPTION 'ligação de anúncios de artista inexistente' USING ERRCODE = '42501';
  END IF;
  PERFORM public.artist_access_check(v_conn.artist_id,'admin',NULL);
  IF v_conn.selected_ad_account_currency IS NULL THEN
    RAISE EXCEPTION 'a conta ainda não tem moeda definida' USING ERRCODE = '22023';
  END IF;
  IF p_daily_cap IS NULL OR p_daily_cap <= 0 THEN
    RAISE EXCEPTION 'o teto diário tem de ser maior que zero' USING ERRCODE = '22023';
  END IF;

  INSERT INTO crm.artist_ads_budget_caps
    (company_id, artist_id, connection_id, platform, daily_cap, currency, notes, set_by, set_at)
  VALUES (v_conn.company_id, v_conn.artist_id, v_conn.id, v_conn.platform,
          p_daily_cap, upper(v_conn.selected_ad_account_currency), p_notes, auth.uid(), now())
  ON CONFLICT (connection_id) DO UPDATE
    SET daily_cap = EXCLUDED.daily_cap,
        currency = EXCLUDED.currency,
        notes = EXCLUDED.notes,
        set_by = EXCLUDED.set_by,
        set_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_link_song(p_platform text, p_campaign_id text, p_song_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_company uuid; v_n int := 0;
BEGIN
  IF p_platform NOT IN ('google','meta') THEN
    RAISE EXCEPTION 'plataforma inválida' USING ERRCODE = '22023';
  END IF;
  SELECT company_id INTO v_company FROM public.artist_songs WHERE id = p_song_id;
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'música inexistente' USING ERRCODE = '22023';
  END IF;
  IF NOT public.artist_access_ok((SELECT s.artist_id FROM public.artist_songs s WHERE s.id = p_song_id),'traffic_write',NULL) THEN
    RAISE EXCEPTION 'sem permissão para ligar campanha a música' USING ERRCODE = '42501';
  END IF;
  IF p_platform = 'google' THEN
    UPDATE crm.google_campaign SET linked_song_id = p_song_id, linked_song_locked = true,
      link_kind = 'song', link_kind_locked = true
    WHERE external_campaign_id = p_campaign_id AND company_id = v_company;
  ELSE
    UPDATE crm.meta_campaign_snapshot SET linked_song_id = p_song_id, linked_song_locked = true,
      link_kind = 'song', link_kind_locked = true
    WHERE external_campaign_id = p_campaign_id AND company_id = v_company;
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_plan_create(p_artist_id uuid, p_song_id uuid, p_connection_id uuid, p_plan jsonb, p_platform text DEFAULT 'meta'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_company uuid; v_conn crm.ad_platform_connections; v_smart text; v_ok jsonb; v_id uuid;
BEGIN
  IF p_platform NOT IN ('meta','tiktok','google') THEN
    RAISE EXCEPTION 'plataforma não suportada' USING ERRCODE = '22023';
  END IF;

  v_company := public.artist_access_check(p_artist_id,'traffic_write',NULL);

  SELECT * INTO v_conn FROM crm.ad_platform_connections
  WHERE id = p_connection_id AND connection_scope = 'artist'
    AND artist_id = p_artist_id AND company_id = v_company;
  IF v_conn.id IS NULL THEN
    RAISE EXCEPTION 'ligação de anúncios do artista inexistente ou fora do âmbito' USING ERRCODE = '42501';
  END IF;
  IF v_conn.platform IS DISTINCT FROM p_platform THEN
    RAISE EXCEPTION 'a ligação não é da plataforma indicada' USING ERRCODE = '22023';
  END IF;
  IF v_conn.selected_ad_account_currency IS NULL THEN
    RAISE EXCEPTION 'a ligação não tem moeda da conta de anúncios definida' USING ERRCODE = '22023';
  END IF;

  -- D-ERP167: só o smart link MP activo da música (song_links).
  SELECT 'https://www.mundopropicio.com/m/' || l.slug INTO v_smart
  FROM public.song_links l
  WHERE l.song_id = p_song_id AND l.active AND l.company_id = v_company
  ORDER BY l.updated_at DESC LIMIT 1;
  v_ok := public.artist_ads_plan_validate(p_plan, v_smart);

  INSERT INTO crm.meta_publish_plan (
    company_id, event_id, design_id, artist_id, song_id, connection_id, platform,
    objetivo, orcamento_total_cents, moeda, link_destino,
    adsets, resumo, estado, created_by, start_time, end_time)
  VALUES (
    v_company, NULL, NULL, p_artist_id, p_song_id, p_connection_id, p_platform,
    v_ok->>'objetivo',
    nullif(p_plan->>'orcamento_total_cents','')::bigint,
    v_conn.selected_ad_account_currency,
    v_ok->>'link_destino',
    v_ok->'adsets',
    p_plan->'resumo',
    'rascunho', auth.uid(),
    nullif(p_plan->>'start_time','')::timestamptz,
    nullif(p_plan->>'end_time','')::timestamptz)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_plan_update(p_plan_id uuid, p_plan jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_p crm.meta_publish_plan; v_company uuid; v_smart text; v_ok jsonb;
BEGIN
  SELECT * INTO v_p FROM crm.meta_publish_plan
  WHERE id = p_plan_id AND song_id IS NOT NULL;
  IF v_p.id IS NULL THEN
    RAISE EXCEPTION 'plano de alvo música inexistente' USING ERRCODE = '22023';
  END IF;
  v_company := public.artist_access_check(v_p.artist_id,'traffic_write',NULL);
  IF v_p.company_id <> v_company THEN
    RAISE EXCEPTION 'plano fora do âmbito' USING ERRCODE = '42501';
  END IF;
  IF v_p.estado NOT IN ('rascunho','falhado') THEN
    RAISE EXCEPTION 'só é possível editar planos em rascunho ou falhados (estado: %)', v_p.estado USING ERRCODE = '22023';
  END IF;

  -- D-ERP167: só o smart link MP activo da música (song_links).
  SELECT 'https://www.mundopropicio.com/m/' || l.slug INTO v_smart
  FROM public.song_links l
  WHERE l.song_id = v_p.song_id AND l.active AND l.company_id = v_company
  ORDER BY l.updated_at DESC LIMIT 1;
  v_ok := public.artist_ads_plan_validate(p_plan, v_smart);

  UPDATE crm.meta_publish_plan SET
    objetivo = v_ok->>'objetivo',
    orcamento_total_cents = nullif(p_plan->>'orcamento_total_cents','')::bigint,
    link_destino = v_ok->>'link_destino',
    adsets = v_ok->'adsets',
    resumo = coalesce(p_plan->'resumo', resumo),
    start_time = nullif(p_plan->>'start_time','')::timestamptz,
    end_time = nullif(p_plan->>'end_time','')::timestamptz,
    updated_at = now()
  WHERE id = p_plan_id;
  RETURN p_plan_id;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_register_external(p_artist_id uuid, p_platform text, p_external_id text, p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_ok      boolean;
  v_id      uuid;
  v_ext     text;
BEGIN
  IF p_platform NOT IN ('google', 'tiktok') THEN
    RAISE EXCEPTION 'plataforma invalida: %', p_platform;
  END IF;

  v_ext := regexp_replace(coalesce(p_external_id, ''), '\D', '', 'g');
  IF v_ext = '' THEN
    RAISE EXCEPTION 'external_id invalido';
  END IF;

  SELECT company_id INTO v_company FROM public.artists WHERE id = p_artist_id;
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'artista nao encontrado';
  END IF;

  IF v_uid IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM public.user_roles ur
      WHERE ur.user_id = v_uid
        AND ur.role IN ('admin','platform_admin','manager','marketing_manager')
        AND (ur.role = 'platform_admin' OR ur.company_id IS NULL OR ur.company_id = v_company)
    ) INTO v_ok;
    IF NOT v_ok THEN
      RAISE EXCEPTION 'sem permissao para registar contas de anuncios deste artista';
    END IF;
  END IF;

  SELECT c.id INTO v_id FROM crm.ad_platform_connections c
  WHERE c.company_id = v_company AND c.artist_id = p_artist_id AND c.platform = p_platform
  ORDER BY c.connected_at DESC NULLS LAST
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE crm.ad_platform_connections c SET
      external_business_id   = v_ext,
      external_business_name = coalesce(p_name, c.external_business_name),
      disconnected_at        = NULL
    WHERE c.id = v_id;
    RETURN v_id;
  END IF;

  INSERT INTO crm.ad_platform_connections (
    company_id, artist_id, connection_scope, platform,
    external_business_id, external_business_name,
    status, connected_by, connected_at
  ) VALUES (
    v_company, p_artist_id, 'artist', p_platform,
    v_ext, p_name,
    'pending_link', v_uid, now()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_ads_set_link_kind(p_platform text, p_campaign_id text, p_artist_id uuid, p_kind text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_company uuid; v_n int := 0;
BEGIN
  IF p_platform NOT IN ('google','meta','tiktok') THEN
    RAISE EXCEPTION 'plataforma inválida' USING ERRCODE = '22023';
  END IF;
  IF p_kind IS NOT NULL AND p_kind NOT IN ('song','profile','event') THEN
    RAISE EXCEPTION 'tipo inválido' USING ERRCODE = '22023';
  END IF;
  v_company := public.artist_access_check(p_artist_id,'traffic_write',NULL);
  IF v_uid IS NOT NULL AND NOT public.user_has_company_access(v_company, ARRAY['admin','manager','marketing_manager']::public.app_role[]) THEN
    RAISE EXCEPTION 'sem permissão' USING ERRCODE = '42501';
  END IF;
  IF p_platform = 'google' THEN
    UPDATE crm.google_campaign x SET link_kind = p_kind, link_kind_locked = true
    WHERE x.external_campaign_id = p_campaign_id AND EXISTS (SELECT 1 FROM crm.ad_platform_connections c
      WHERE c.id = x.connection_id AND c.connection_scope='artist' AND c.artist_id = p_artist_id AND c.company_id = v_company);
  ELSIF p_platform = 'meta' THEN
    UPDATE crm.meta_campaign_snapshot x SET link_kind = p_kind, link_kind_locked = true
    WHERE x.external_campaign_id = p_campaign_id AND EXISTS (SELECT 1 FROM crm.ad_platform_connections c
      WHERE c.id = x.connection_id AND c.connection_scope='artist' AND c.artist_id = p_artist_id AND c.company_id = v_company);
  ELSE
    UPDATE crm.tiktok_campaign x SET link_kind = p_kind, link_kind_locked = true
    WHERE x.external_campaign_id = p_campaign_id AND EXISTS (SELECT 1 FROM crm.ad_platform_connections c
      WHERE c.id = x.connection_id AND c.connection_scope='artist' AND c.artist_id = p_artist_id AND c.company_id = v_company);
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_set_market_country(p_platform text, p_campaign_id text, p_country text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_c text := upper(nullif(trim(p_country),'')); v_n int := 0;
BEGIN
  IF p_platform NOT IN ('google','meta','tiktok') THEN RAISE EXCEPTION 'plataforma inválida' USING ERRCODE='22023'; END IF;
  IF v_c IS NOT NULL AND v_c !~ '^([A-Z]{2}|MULTI)$' THEN RAISE EXCEPTION 'país inválido (ISO-2 ou MULTI)' USING ERRCODE='22023'; END IF;
  IF p_platform = 'google' THEN
    UPDATE crm.google_campaign x SET market_country = coalesce(v_c, x.market_country), market_country_locked = (v_c IS NOT NULL)
    WHERE x.external_campaign_id = p_campaign_id AND public.artist_access_ok((SELECT pc.artist_id FROM crm.ad_platform_connections pc WHERE pc.id = x.connection_id),'traffic_write',NULL);
  ELSIF p_platform = 'meta' THEN
    UPDATE crm.meta_campaign_snapshot x SET market_country = coalesce(v_c, x.market_country), market_country_locked = (v_c IS NOT NULL)
    WHERE x.external_campaign_id = p_campaign_id AND public.artist_access_ok((SELECT pc.artist_id FROM crm.ad_platform_connections pc WHERE pc.id = x.connection_id),'traffic_write',NULL);
  ELSE
    UPDATE crm.tiktok_campaign x SET market_country = coalesce(v_c, x.market_country), market_country_locked = (v_c IS NOT NULL)
    WHERE x.external_campaign_id = p_campaign_id AND public.artist_access_ok((SELECT pc.artist_id FROM crm.ad_platform_connections pc WHERE pc.id = x.connection_id),'traffic_write',NULL);
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE EXCEPTION 'campanha não encontrada ou sem permissão' USING ERRCODE='42501'; END IF;
  RETURN v_n;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_sync_status(p_artist_id uuid)
 RETURNS TABLE(platform text, escopo text, last_sync_at timestamp with time zone, cadencia text, cadencia_minutos integer, atrasado boolean, last_error text, connection_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
-- D-ERP155: só plataformas com ligação de anúncios do artista; horas por ligação.
-- D-ERP178: TikTok passa a uma linha POR LIGAÇÃO (sync por API; manual como fallback).
-- D-ERP258: connection_id nas linhas TikTok (NULL nas agregadas).
DECLARE
  v_meta_ids uuid[]; v_google_ids uuid[];
  v_meta timestamptz; v_meta_err text; v_google timestamptz; v_rec timestamptz;
  t record; v_api timestamptz; v_api_err text; v_man timestamptz;
BEGIN
  PERFORM public.artist_access_check(p_artist_id,'read','traffic');

  SELECT array_agg(c.id) FILTER (WHERE c.platform = 'meta' AND c.status = 'active'),
         array_agg(c.id) FILTER (WHERE c.platform = 'google' AND c.status = 'active')
    INTO v_meta_ids, v_google_ids
    FROM crm.ad_platform_connections c
   WHERE c.artist_id = p_artist_id AND c.connection_scope = 'artist';

  IF v_meta_ids IS NOT NULL THEN
    SELECT max(s.last_sync_at) INTO v_meta FROM crm.meta_sync_state s WHERE s.connection_id = ANY(v_meta_ids);
    SELECT s.last_error INTO v_meta_err FROM crm.meta_sync_state s
     WHERE s.connection_id = ANY(v_meta_ids) AND s.last_error IS NOT NULL
     ORDER BY s.last_error_at DESC NULLS LAST LIMIT 1;
  END IF;

  IF v_google_ids IS NOT NULL THEN
    SELECT greatest(
      (SELECT max(gc.last_synced_at) FROM crm.google_campaign gc WHERE gc.connection_id = ANY(v_google_ids)),
      (SELECT max(r.finished_at) FROM public.sync_runs r
        WHERE r.function_name IN ('crm-google-sync-campaigns','crm-google-video-metrics-sync')
          AND NOT r.dry_run AND r.status IN ('success','partial')
          AND EXISTS (SELECT 1 FROM unnest(v_google_ids) g WHERE r.details->'per_connection' ? g::text))
    ) INTO v_google;
  END IF;

  IF v_meta_ids IS NOT NULL OR v_google_ids IS NOT NULL THEN
    SELECT max(r.finished_at) INTO v_rec FROM public.sync_runs r
     WHERE r.function_name IN ('crm-meta-sync-insights:breakdowns','crm-google-sync-campaigns:breakdowns')
       AND NOT r.dry_run
       AND EXISTS (SELECT 1 FROM unnest(coalesce(v_meta_ids,'{}') || coalesce(v_google_ids,'{}')) x
                    WHERE r.details->'per_connection' ? x::text OR r.details->'params'->>'connection_id' = x::text);
  END IF;

  IF v_meta_ids IS NOT NULL THEN
    RETURN QUERY SELECT 'meta'::text, 'campanhas e resultados'::text, v_meta, 'de hora a hora'::text, 60,
      (v_meta IS NULL OR v_meta < now() - interval '120 minutes'), v_meta_err, NULL::uuid;
  END IF;
  IF v_google_ids IS NOT NULL THEN
    RETURN QUERY SELECT 'google'::text, 'campanhas e vídeo'::text, v_google, 'de 3 em 3 horas'::text, 180,
      (v_google IS NULL OR v_google < now() - interval '360 minutes'), NULL::text, NULL::uuid;
  END IF;
  IF v_meta_ids IS NOT NULL OR v_google_ids IS NOT NULL THEN
    RETURN QUERY SELECT 'recortes'::text, 'região, idade e género'::text, v_rec, '1x por dia'::text, 1440,
      (v_rec IS NULL OR v_rec < now() - interval '2880 minutes'), NULL::text, NULL::uuid;
  END IF;

  FOR t IN SELECT c.id, c.status, c.selected_ad_account_currency AS cur, c.selected_ad_account_id AS acc
             FROM crm.ad_platform_connections c
            WHERE c.artist_id = p_artist_id AND c.connection_scope = 'artist' AND c.platform = 'tiktok'
              AND c.status IN ('active','pending_link','error')
            ORDER BY c.connected_at NULLS LAST, c.id LOOP
    v_api := NULL; v_api_err := NULL; v_man := NULL;
    SELECT max(r.finished_at) INTO v_api FROM public.sync_runs r
     WHERE r.function_name = 'artist-ads-tiktok-sync' AND NOT r.dry_run
       AND (r.details->'per_connection'->t.id::text->>'ok')::boolean IS TRUE;
    SELECT r.details->'per_connection'->t.id::text->>'error' INTO v_api_err FROM public.sync_runs r
     WHERE r.function_name = 'artist-ads-tiktok-sync' AND NOT r.dry_run AND r.details->'per_connection' ? t.id::text
     ORDER BY r.started_at DESC LIMIT 1;
    IF v_api IS NOT NULL OR v_api_err IS NOT NULL THEN
      RETURN QUERY SELECT 'tiktok'::text, ('campanhas e resultados (' || coalesce(t.cur,'?') || ')')::text, v_api,
        '3x por dia (API)'::text, 360, (v_api IS NULL OR v_api < now() - interval '720 minutes'), v_api_err, t.id;
    ELSE
      SELECT max(i.recorded_at) INTO v_man FROM crm.tiktok_insights_daily i WHERE i.connection_id = t.id AND i.source = 'manual';
      IF v_man IS NOT NULL THEN
        RETURN QUERY SELECT 'tiktok'::text, ('registo manual (' || coalesce(t.cur,'?') || ')')::text, v_man, 'manual'::text, NULL::integer, false, NULL::text, t.id;
      END IF;
    END IF;
  END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.artist_ads_tiktok_manual_upsert(p_connection_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_conn record;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sessão obrigatória' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_conn FROM crm.ad_platform_connections WHERE id = p_connection_id;
  IF NOT FOUND OR v_conn.platform <> 'tiktok' OR v_conn.connection_scope <> 'artist' THEN
    RAISE EXCEPTION 'ligação TikTok de artista não encontrada' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles r
    WHERE r.user_id = v_uid
      AND (r.role = 'platform_admin'
           OR (r.role IN ('admin','manager','marketing_manager') AND r.company_id = v_conn.company_id))
  ) THEN
    RAISE EXCEPTION 'sem permissão na empresa da ligação' USING ERRCODE = '42501';
  END IF;
  RETURN crm.tiktok_manual_upsert_core(p_connection_id, p_payload, v_uid::text);
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_ads_unlink_song(p_platform text, p_campaign_id text, p_artist_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_company uuid; v_n int := 0;
BEGIN
  IF p_platform NOT IN ('google','meta') THEN
    RAISE EXCEPTION 'plataforma inválida' USING ERRCODE = '22023';
  END IF;
  v_company := public.artist_access_check(p_artist_id,'traffic_write',NULL);
  IF v_uid IS NOT NULL AND NOT public.user_has_company_access(v_company, ARRAY['admin','manager','marketing_manager']::public.app_role[]) THEN
    RAISE EXCEPTION 'sem permissão para desligar campanha de música' USING ERRCODE = '42501';
  END IF;
  IF p_platform = 'google' THEN
    UPDATE crm.google_campaign gc
      SET linked_song_id = NULL, linked_song_locked = true
    WHERE gc.external_campaign_id = p_campaign_id
      AND EXISTS (
        SELECT 1 FROM crm.ad_platform_connections c
        WHERE c.id = gc.connection_id AND c.connection_scope = 'artist'
          AND c.artist_id = p_artist_id AND c.company_id = v_company
      );
  ELSE
    UPDATE crm.meta_campaign_snapshot ms
      SET linked_song_id = NULL, linked_song_locked = true
    WHERE ms.external_campaign_id = p_campaign_id
      AND EXISTS (
        SELECT 1 FROM crm.ad_platform_connections c
        WHERE c.id = ms.connection_id AND c.connection_scope = 'artist'
          AND c.artist_id = p_artist_id AND c.company_id = v_company
      );
  END IF;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$

CREATE OR REPLACE FUNCTION public.crm_get_meta_decrypted_token(p_connection_id uuid, p_master_key text)
 RETURNS TABLE(access_token text, external_business_id text, external_business_name text, company_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_encrypted text;
  v_business_id text;
  v_business_name text;
  v_company_id uuid;
  v_caller_company uuid;
  v_jwt_role text;
BEGIN
  v_jwt_role := COALESCE((NULLIF(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role'), '');

  IF v_jwt_role = 'service_role' THEN
    SELECT apc.access_token_encrypted, apc.external_business_id, apc.external_business_name, apc.company_id
      INTO v_encrypted, v_business_id, v_business_name, v_company_id
    FROM crm.ad_platform_connections apc
    WHERE apc.id = p_connection_id
      AND apc.platform IN ('meta', 'tiktok')
      AND apc.status = 'active';

    IF v_encrypted IS NULL THEN
      RAISE EXCEPTION 'Active Meta/TikTok connection not found for service role caller (id=%)', p_connection_id;
    END IF;
  ELSE
    v_caller_company := public.current_company_id();
    IF v_caller_company IS NULL THEN
      RAISE EXCEPTION 'No active company for caller (auth.uid()=%)', auth.uid();
    END IF;

    SELECT apc.access_token_encrypted, apc.external_business_id, apc.external_business_name, apc.company_id
      INTO v_encrypted, v_business_id, v_business_name, v_company_id
    FROM crm.ad_platform_connections apc
    WHERE apc.id = p_connection_id
      AND apc.platform IN ('meta', 'tiktok')
      AND apc.status = 'active'
      AND apc.company_id = v_caller_company;

    IF v_encrypted IS NULL THEN
      RAISE EXCEPTION 'Active Meta/TikTok connection not found or not authorised (id=%, caller_company=%)', p_connection_id, v_caller_company;
    END IF;
  END IF;

  RETURN QUERY SELECT
    extensions.pgp_sym_decrypt(decode(v_encrypted, 'base64'), p_master_key)::text,
    v_business_id,
    v_business_name,
    v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_ads_investment_report(p_artist_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'crm', 'pg_catalog'
AS $function$
DECLARE
 v_company uuid; v_ref text; v_from date; v_to date:=coalesce(p_to,current_date); v_start date;
 v_report jsonb; v_daily jsonb; v_campaigns jsonb; v_active jsonb; v_projection jsonb; v_missing jsonb; v_totals jsonb; v_fx jsonb;
 v_kpis jsonb:='[]'; v_series jsonb:='[]'; v_marks jsonb; spec record; v_base record; v_current record; pts jsonb;
 v_spend numeric; v_arrivals numeric; v_traffic numeric; v_streams numeric; v_projected numeric; v_month numeric;
BEGIN
 v_company:=public.artist_access_check(p_artist_id,'read','financial');
 SELECT coalesce(a.reporting_currency,c.currency,'EUR') INTO v_ref FROM public.artists a LEFT JOIN public.companies c ON c.id=a.company_id WHERE a.id=p_artist_id;
 -- Campaign schedule and active budget legs. Never treat lifetime budgets as daily budgets.
 WITH conns AS (SELECT * FROM crm.ad_platform_connections WHERE artist_id=p_artist_id AND company_id=v_company AND connection_scope='artist'),
 legs AS (
 SELECT 'meta'::text platform,c.selected_ad_account_id account,c.selected_ad_account_currency currency,s.external_campaign_id cid,s.name nome,s.objective objective,
  coalesce(s.effective_status,s.status) status,
  coalesce(s.start_time,(SELECT min(start_time) FROM crm.meta_adset_snapshot WHERE connection_id=s.connection_id AND external_campaign_id=s.external_campaign_id))::date starts,
  coalesce(s.stop_time,(SELECT max(end_time) FROM crm.meta_adset_snapshot WHERE connection_id=s.connection_id AND external_campaign_id=s.external_campaign_id))::date ends,
  s.market_country country,s.raw,
  coalesce((SELECT jsonb_agg(jsonb_build_object('budget',x.daily_budget_cents/100.0,'start',x.start_time::date,'end',x.end_time::date,'state',coalesce(x.effective_status,x.status),'geo',x.targeting->'geo_locations')) FROM crm.meta_adset_snapshot x WHERE x.connection_id=s.connection_id AND x.external_campaign_id=s.external_campaign_id),'[]'::jsonb) parts,
  s.daily_budget_cents/100.0 campaign_budget
 FROM crm.meta_campaign_snapshot s JOIN conns c ON c.id=s.connection_id
 UNION ALL
 SELECT 'google',c.selected_ad_account_id,c.selected_ad_account_currency,g.external_campaign_id,g.name,g.advertising_channel_type,g.status,g.start_date,g.end_date,g.market_country,g.raw,
  jsonb_build_array(jsonb_build_object('budget',g.budget_amount_micros/1000000.0,'start',g.start_date,'end',g.end_date,'state',g.status,'geo',(SELECT jsonb_agg(x->'localizacao') FROM jsonb_array_elements(coalesce(g.settings->'criterios','[]')) x WHERE x->>'tipo'='LOCATION' AND coalesce((x->>'negativo')::boolean,false)=false))),coalesce(g.budget_amount_micros/1000000.0,CASE WHEN g.end_date IS NOT NULL AND g.end_date>=current_date AND (g.raw->'campaignBudget'->>'totalAmountMicros') IS NOT NULL THEN round(greatest(0,(g.raw->'campaignBudget'->>'totalAmountMicros')::numeric/1000000.0-coalesce((SELECT sum(gi.spend_cents)/100.0 FROM crm.google_campaign_insights_daily gi WHERE gi.connection_id=g.connection_id AND gi.external_campaign_id=g.external_campaign_id AND gi.date_start<=current_date),0))/greatest(1,g.end_date-current_date),2) END)
 FROM crm.google_campaign g JOIN conns c ON c.id=g.connection_id
 UNION ALL
 SELECT 'tiktok',c.selected_ad_account_id,coalesce(t.currency,c.selected_ad_account_currency),t.external_campaign_id,t.name,t.objective,t.status,
  coalesce(substring(t.raw->>'start_time' from '^\d{4}-\d{2}-\d{2}'),substring(t.raw->>'create_time' from '^\d{4}-\d{2}-\d{2}'))::date,
  substring(t.raw->>'end_time' from '^\d{4}-\d{2}-\d{2}')::date,t.market_country,t.raw,
  coalesce((SELECT jsonb_agg(jsonb_build_object('budget',CASE WHEN coalesce(x.raw->>'budget_mode','BUDGET_MODE_DAY') IN ('BUDGET_MODE_DAY','BUDGET_MODE_DYNAMIC_DAILY_BUDGET') THEN x.budget_cents/100.0 END,
    'start',substring(coalesce(x.raw->>'schedule_start_time',x.raw->>'start_time') from '^\d{4}-\d{2}-\d{2}'),
    'end',substring(coalesce(x.raw->>'schedule_end_time',x.raw->>'end_time') from '^\d{4}-\d{2}-\d{2}'),'state',x.status,'geo',coalesce(x.raw->'location_ids',x.raw->'geo_locations')))
   FROM crm.tiktok_adgroup x WHERE x.connection_id=t.connection_id AND x.external_campaign_id=t.external_campaign_id),'[]'::jsonb),
  CASE WHEN t.raw->>'budget_mode' IN ('BUDGET_MODE_DAY','BUDGET_MODE_DYNAMIC_DAILY_BUDGET') THEN nullif(t.budget_cents,0)/100.0 END
 FROM crm.tiktok_campaign_carreira t JOIN conns c ON c.id=t.connection_id
 ), normalized AS (
 SELECT l.*,coalesce(l.starts,substring(l.nome from '(\d{4}-\d{2}-\d{2})')::date) start_date,
 CASE WHEN coalesce(l.ends,(SELECT max((p->>'end')::date) FROM jsonb_array_elements(l.parts) p))>current_date+365 THEN NULL ELSE coalesce(l.ends,(SELECT max((p->>'end')::date) FROM jsonb_array_elements(l.parts) p)) END end_date,
 coalesce(nullif(l.campaign_budget,0),(SELECT CASE WHEN bool_or(p->>'budget' IS NULL) THEN NULL ELSE sum((p->>'budget')::numeric) END FROM jsonb_array_elements(l.parts) p WHERE upper(p->>'state') IN ('ACTIVE','ENABLED','ENABLE','CAMPAIGN_STATUS_ENABLE') AND coalesce((p->>'start')::date,current_date)<=current_date AND coalesce((p->>'end')::date,current_date)>=current_date)) daily_budget
 FROM legs l)
 SELECT coalesce(jsonb_agg(to_jsonb(n)),'[]') INTO v_campaigns FROM normalized n;
 SELECT min((c->>'start_date')::date) INTO v_start FROM jsonb_array_elements(v_campaigns) c WHERE c->>'nome' ~* '^\s*\[mp\]';
 -- If schedule is absent, the first actual [MP] insight is the honest management start.
 IF v_start IS NULL THEN
  SELECT min(d) INTO v_start FROM (
   SELECT i.date_start d FROM crm.meta_campaign_insights_daily i JOIN crm.meta_campaign_snapshot s USING(connection_id,external_campaign_id) JOIN crm.ad_platform_connections c ON c.id=i.connection_id WHERE c.artist_id=p_artist_id AND c.company_id=v_company AND s.name ~* '^\s*\[mp\]'
   UNION ALL SELECT i.date_start FROM crm.google_campaign_insights_daily i JOIN crm.google_campaign s USING(connection_id,external_campaign_id) JOIN crm.ad_platform_connections c ON c.id=i.connection_id WHERE c.artist_id=p_artist_id AND c.company_id=v_company AND s.name ~* '^\s*\[mp\]'
   UNION ALL SELECT i.date_start FROM crm.tiktok_insights_daily_carreira i JOIN crm.tiktok_campaign_carreira s USING(connection_id,external_campaign_id) JOIN crm.ad_platform_connections c ON c.id=i.connection_id WHERE c.artist_id=p_artist_id AND c.company_id=v_company AND s.name ~* '^\s*\[mp\]') z;
 END IF;
 v_from:=coalesce(p_from,v_start,v_to);
 IF v_from>v_to THEN RAISE EXCEPTION 'período inválido' USING ERRCODE='22023'; END IF;
 v_report:=public._artist_ads_investment_source(p_artist_id,v_from,v_to);
 -- Totals, traffic objective classification and arrivals come from D-ERP185, not a new interpretation.
 SELECT coalesce(sum((c->>'gasto_ref')::numeric),0) INTO v_spend FROM jsonb_array_elements(v_report->'plataformas') p,jsonb_array_elements(p->'campanhas') c;
 IF (v_report->'totais'->>'fx_missing_days')::integer>0 THEN v_spend:=NULL; END IF;
 SELECT coalesce(sum((p->>'gasto_trafego')::numeric),0),coalesce(sum((p->>'chegadas')::numeric),0) INTO v_traffic,v_arrivals FROM jsonb_array_elements(v_report->'plataformas') p;
 SELECT jsonb_agg(jsonb_build_object('plataforma',p->>'platform','gasto_ref',(SELECT sum((c->>'gasto_ref')::numeric) FROM jsonb_array_elements(p->'campanhas') c),
 'pct',CASE WHEN v_spend>0 THEN round((SELECT sum((c->>'gasto_ref')::numeric) FROM jsonb_array_elements(p->'campanhas') c)/v_spend*100,2) END,'campanhas',jsonb_array_length(p->'campanhas'))) INTO v_totals FROM jsonb_array_elements(v_report->'plataformas') p;


 SELECT coalesce(jsonb_agg(jsonb_build_object('dia',dia,'plataforma',plat,'conta',acc,'moeda',cur,'gasto',sp,'gasto_ref',gr,'gasto_trafego_ref',gt) ORDER BY dia,plat,acc,cur),'[]') INTO v_daily FROM
 (SELECT j->>'dia' dia,j->>'plataforma' plat,j->>'conta' acc,j->>'moeda' cur,sum((j->>'gasto')::numeric) sp,
 CASE WHEN bool_or(j->>'gasto_ref' IS NULL AND (j->>'gasto')::numeric>0) THEN NULL ELSE sum((j->>'gasto_ref')::numeric) END gr,sum((j->>'gasto_trafego_ref')::numeric) gt
 FROM jsonb_array_elements(v_report->'daily') j GROUP BY 1,2,3,4) z;

 IF date_trunc('month',current_date)::date>=v_from AND current_date<=v_to THEN
 SELECT CASE WHEN bool_or(j->>'gasto_ref' IS NULL AND (j->>'gasto')::numeric>0) THEN NULL ELSE coalesce(round(sum((j->>'gasto_ref')::numeric),2),0) END INTO v_month FROM jsonb_array_elements(v_daily) j WHERE (j->>'dia')::date BETWEEN date_trunc('month',current_date)::date AND current_date;
 ELSE
 DECLARE month_report jsonb; BEGIN month_report:=public._artist_ads_investment_source(p_artist_id,date_trunc('month',current_date)::date,current_date);
 SELECT CASE WHEN bool_or(j->>'gasto_ref' IS NULL AND (j->>'gasto')::numeric>0) THEN NULL ELSE coalesce(round(sum((j->>'gasto_ref')::numeric),2),0) END INTO v_month FROM jsonb_array_elements(month_report->'daily') j; END;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('moeda',currency,'moeda_ref',v_ref,'fonte','BCE','taxa',public.fx_convert(1,currency,v_ref,d),'data',d) ORDER BY d,currency),'[]') INTO v_fx
 FROM (SELECT DISTINCT j->>'moeda' currency,(j->>'dia')::date d FROM jsonb_array_elements(v_daily) j WHERE j->>'moeda'<>v_ref) f;
 SELECT coalesce(jsonb_agg(jsonb_build_object('plataforma',c->>'platform','conta',c->>'account','campaign_id',c->>'cid','campanha',c->>'nome','objetivo',c->>'objective',
  'segmentacao',jsonb_build_object('pais',c->>'country','regioes',(SELECT jsonb_agg(p->'geo') FROM jsonb_array_elements(c->'parts') p WHERE p->'geo' IS NOT NULL)),
  'orcamento_dia',(c->>'daily_budget')::numeric,'orcamento_tipo',CASE WHEN c->>'daily_budget' IS NULL THEN NULL WHEN c->>'platform'='google' AND coalesce(c->'raw'->'campaignBudget'->>'period','DAILY')<>'DAILY' THEN 'derivado' ELSE 'diario' END,'moeda',c->>'currency','termina',c->'end_date','estado',c->>'status',
  'dias_projecao',greatest(0,least(coalesce((c->>'end_date')::date,(date_trunc('month',current_date)+interval '1 month - 1 day')::date),(date_trunc('month',current_date)+interval '1 month - 1 day')::date)-current_date))), '[]') INTO v_active
 FROM jsonb_array_elements(v_campaigns) c WHERE upper(c->>'status') IN ('ACTIVE','ENABLED','ENABLE','CAMPAIGN_STATUS_ENABLE')
 AND coalesce((c->>'start_date')::date,current_date)<=current_date AND coalesce((c->>'end_date')::date,current_date)>=current_date
 AND (jsonb_array_length(c->'parts')=0 OR EXISTS (SELECT 1 FROM jsonb_array_elements(c->'parts') p WHERE upper(p->>'state') IN ('ACTIVE','ENABLED','ENABLE','CAMPAIGN_STATUS_ENABLE') AND coalesce((p->>'start')::date,current_date)<=current_date AND coalesce((p->>'end')::date,current_date)>=current_date));
 SELECT coalesce(jsonb_agg(jsonb_build_object('plataforma',platform,'em_vigor_ref',amount,'orcamento_em_falta',missing)),'[]'),
 coalesce(round(sum(amount),2),0) INTO v_projection,v_projected
 FROM (SELECT c->>'plataforma' platform,round(sum((SELECT CASE WHEN (s->>'campaign_budget')::numeric>0 THEN public.fx_convert((c->>'orcamento_dia')::numeric,c->>'moeda',v_ref,current_date)*(c->>'dias_projecao')::integer
 ELSE (SELECT sum(public.fx_convert((p->>'budget')::numeric,c->>'moeda',v_ref,current_date)*greatest(0,least(coalesce(CASE WHEN (p->>'end')::date>current_date+365 THEN NULL ELSE (p->>'end')::date END,(s->>'end_date')::date,(date_trunc('month',current_date)+interval '1 month - 1 day')::date),(date_trunc('month',current_date)+interval '1 month - 1 day')::date)-current_date)) FROM jsonb_array_elements(s->'parts') p WHERE upper(p->>'state') IN ('ACTIVE','ENABLED','ENABLE','CAMPAIGN_STATUS_ENABLE') AND coalesce((p->>'start')::date,current_date)<=current_date AND coalesce((p->>'end')::date,current_date)>=current_date) END FROM jsonb_array_elements(v_campaigns) s WHERE s->>'platform'=c->>'plataforma' AND s->>'account'=c->>'conta' AND s->>'cid'=c->>'campaign_id' LIMIT 1)) FILTER (WHERE c->>'orcamento_dia' IS NOT NULL AND public.fx_convert((c->>'orcamento_dia')::numeric,c->>'moeda',v_ref,current_date) IS NOT NULL),2) amount,
 bool_or(c->>'orcamento_dia' IS NULL OR public.fx_convert((c->>'orcamento_dia')::numeric,c->>'moeda',v_ref,current_date) IS NULL) missing FROM jsonb_array_elements(v_active) c GROUP BY 1) q;
 SELECT coalesce(jsonb_agg(jsonb_build_object('plataforma',c->>'plataforma','campanha',c->>'campanha','motivo',CASE WHEN c->>'orcamento_dia' IS NULL THEN 'orcamento_desconhecido' ELSE 'cambio_indisponivel' END)),'[]') INTO v_missing
 FROM jsonb_array_elements(v_active) c WHERE c->>'orcamento_dia' IS NULL OR public.fx_convert((c->>'orcamento_dia')::numeric,c->>'moeda',v_ref,current_date) IS NULL;
 -- Seven series. Flow metrics are per day; social metrics are measured stocks, never invented zeroes.
 FOR spec IN SELECT * FROM (VALUES
 ('gasto_total','Gasto total',v_ref,'ads'),('chegadas_spotify','Chegadas ao Spotify','chegadas','song_link_events'),('custo_por_chegada','Custo por chegada',v_ref||'/chegada','D-ERP185'),
 ('ouvintes_mensais_spotify','Ouvintes mensais Spotify','ouvintes','artist_metrics_daily'),('streams_periodo','Streams das músicas no período','streams','artist_song_metrics_daily'),
 ('seguidores_tiktok','Seguidores TikTok','seguidores','artist_metrics_daily'),('seguidores_instagram','Seguidores Instagram','seguidores','artist_metrics_daily')) x(chave,rotulo,unit,source)
 LOOP
  v_base:=NULL;v_current:=NULL;pts:='[]';
  IF spec.chave IN ('ouvintes_mensais_spotify','seguidores_tiktok','seguidores_instagram') THEN
   WITH m AS (SELECT DISTINCT ON(metric_date) metric_date d,value v,source FROM public.artist_metrics_daily WHERE artist_id=p_artist_id AND platform=CASE spec.chave WHEN 'ouvintes_mensais_spotify' THEN 'spotify' WHEN 'seguidores_tiktok' THEN 'tiktok' ELSE 'instagram' END AND metric=CASE WHEN spec.chave='ouvintes_mensais_spotify' THEN 'monthly_listeners' ELSE 'followers' END AND metric_date<=v_to ORDER BY metric_date,CASE source WHEN 'aggregator' THEN 1 WHEN 'platform_api' THEN 2 WHEN 'public_page' THEN 3 ELSE 4 END,captured_at DESC NULLS LAST)
   SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'v',v) ORDER BY d) FILTER(WHERE d BETWEEN v_from AND v_to),'[]') INTO pts FROM m;
   SELECT (p->>'d')::date d,(p->>'v')::numeric v INTO v_base FROM jsonb_array_elements(pts) p ORDER BY abs((p->>'d')::date-v_from) LIMIT 1;
   SELECT (p->>'d')::date d,(p->>'v')::numeric v INTO v_current FROM jsonb_array_elements(pts) p ORDER BY p->>'d' DESC LIMIT 1;
  ELSIF spec.chave='streams_periodo' THEN
   WITH m AS (SELECT DISTINCT ON(song_id,metric_date) song_id,metric_date d,value v FROM public.artist_song_metrics_daily WHERE artist_id=p_artist_id AND metric='s4a_streams_day' AND metric_date BETWEEN v_from AND v_to ORDER BY song_id,metric_date,(source='s4a_api') DESC,captured_at DESC)
   SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'v',v) ORDER BY d),'[]'),sum(v) INTO pts,v_streams FROM (SELECT d,sum(v) v FROM m GROUP BY d) x;
   SELECT v_from d,0::numeric v INTO v_base; SELECT max((p->>'d')::date) d,v_streams v INTO v_current FROM jsonb_array_elements(pts) p;
  ELSE
   IF spec.chave='gasto_total' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'v',v) ORDER BY d),'[]') INTO pts FROM (SELECT j->>'dia' d,sum((j->>'gasto_ref')::numeric) v FROM jsonb_array_elements(v_daily) j GROUP BY 1) z;
    SELECT v_from d,0::numeric v INTO v_base;SELECT v_to d,v_spend v INTO v_current;
   ELSE
    -- Same effective-channel mapping as D-ERP185; test events excluded. No click fallback.

    WITH arr AS (SELECT (j->>'d')::date d,(j->>'v')::numeric n FROM jsonb_array_elements(v_report->'arrivals_daily') j),
    tr AS (SELECT (j->>'dia')::date d,sum((j->>'gasto_trafego_ref')::numeric) spend FROM jsonb_array_elements(v_daily) j GROUP BY 1)
    SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'v',CASE WHEN spec.chave='chegadas_spotify' THEN n ELSE CASE WHEN n>0 THEN round(spend/n,4) END END) ORDER BY d),'[]') INTO pts FROM arr LEFT JOIN tr USING(d);
    SELECT v_from d,CASE WHEN spec.chave='chegadas_spotify' THEN 0::numeric ELSE NULL::numeric END v INTO v_base;
    SELECT v_to d,CASE WHEN spec.chave='chegadas_spotify' THEN v_arrivals ELSE CASE WHEN v_arrivals>0 THEN round(v_traffic/v_arrivals,4) END END v INTO v_current;
   END IF;
  END IF;
  v_kpis:=v_kpis||jsonb_build_object('chave',spec.chave,'valor_inicial',v_base.v,'valor_atual',v_current.v,'delta',v_current.v-v_base.v,'unidade',spec.unit,'fonte',spec.source,'as_of',v_current.d,'base_data',v_base.d);
  v_series:=v_series||jsonb_build_object('chave',spec.chave,'rotulo',spec.rotulo,'pontos',pts,'fonte',spec.source,'as_of',v_current.d);
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('dia',d,'texto',txt) ORDER BY d,txt),'[]') INTO v_marks FROM (
 SELECT (c->>'start_date')::date d,'Início: '||(c->>'nome') txt FROM jsonb_array_elements(v_campaigns) c WHERE c->>'nome' ~* '^\s*\[mp\]' AND (c->>'start_date')::date BETWEEN v_from AND v_to
 UNION ALL SELECT (c->>'end_date')::date,'Fim: '||(c->>'nome') FROM jsonb_array_elements(v_campaigns) c WHERE c->>'nome' ~* '^\s*\[mp\]' AND (c->>'end_date')::date BETWEEN v_from AND v_to
 UNION ALL SELECT (j->>'d')::date,'Investimento diário acima de 2× a média do período' FROM jsonb_array_elements(v_series->0->'pontos') j WHERE (j->>'v')::numeric>2*v_spend/(v_to-v_from+1)) z;
 RETURN jsonb_build_object('artista_id',p_artist_id,'ref_currency',v_ref,'periodo',jsonb_build_object('de',v_from,'ate',v_to,'inicio_gestao',v_start,'dia_parcial',v_to>=current_date),
 'kpis',v_kpis,'gasto_diario',v_daily,'cambio',v_fx,'totais_plataforma',coalesce(v_totals,'[]'),'marcos',v_marks,'series',v_series,'campanhas_no_ar',v_active,
 'ritmo_diario_ref',v_spend/(v_to-v_from+1),'projecao',v_projection,'total_projetado_ref',coalesce(v_projected,0),'total_mes_ref',round(coalesce(v_month,0)+coalesce(v_projected,0),2),'parcial',jsonb_array_length(coalesce(v_missing,'[]'))>0 OR v_month IS NULL,'em_falta',coalesce(v_missing,'[]'),
 'fontes',jsonb_build_array('artist_ads_period_report: campanhas.gasto_ref, gasto_trafego e chegadas por canal (D-ERP185)','Insights diários: Meta, Google e TikTok; precedência campaign > adgroup','artist_metrics_daily: aggregator > platform_api > public_page','artist_song_metrics_daily: s4a_streams_day, soma diária por música','fx_convert: BCE do próprio dia; câmbio ausente = null; projeção exclui hoje','Orçamentos diários activos; lifetime não é orçamento diário'),
 'lacunas',jsonb_build_array('Chegadas ao Spotify são chegadas a smart links do artista nos canais pagos; não provam abertura nem stream no Spotify.','Streams: soma S4A diária das músicas do artista; sem medição retorna null.'));
END $function$

CREATE OR REPLACE FUNCTION public.crm_meta_audience_collect_upload_members(p_audience_local_id uuid)
 RETURNS TABLE(email_hash_sha256 text, phone_hash_sha256 text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_role text := current_setting('request.jwt.claims', true)::jsonb ->> 'role';
  v_company_id uuid;
BEGIN
  SELECT mca.company_id INTO v_company_id
  FROM public.meta_custom_audiences mca
  WHERE mca.id = p_audience_local_id;

  IF v_company_id IS NULL THEN
    RETURN;
  END IF;

  IF v_role IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'not authenticated';
    END IF;
    IF NOT row_belongs_to_current_company(v_company_id) THEN
      RAISE EXCEPTION 'company mismatch';
    END IF;
    IF NOT (
      has_role(auth.uid(), 'admin'::app_role)
      OR has_role(auth.uid(), 'platform_admin'::app_role)
      OR has_role(auth.uid(), 'marketing_manager'::app_role)
    ) THEN
      RAISE EXCEPTION 'insufficient role';
    END IF;
  END IF;

  RETURN QUERY
  SELECT DISTINCT m.email_hash_sha256, m.phone_hash_sha256
  FROM public.meta_audience_upload_members m
  WHERE m.audience_local_id = p_audience_local_id
    AND (m.email_hash_sha256 IS NOT NULL OR m.phone_hash_sha256 IS NOT NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_invariant_reference(_name text, _new_reference bigint, _note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'platform_admin')) THEN
    RAISE EXCEPTION 'Sem permissao para alterar valores de referencia';
  END IF;
  IF _note IS NULL OR btrim(_note) = '' THEN
    RAISE EXCEPTION 'Nota obrigatoria para aceitar uma nova referencia';
  END IF;
  IF _new_reference IS NULL OR _new_reference < 0 THEN
    RAISE EXCEPTION 'Valor de referencia invalido';
  END IF;

  UPDATE public.system_invariants
     SET reference_count = _new_reference,
         reference_updated_by = auth.uid(),
         reference_updated_at = now(),
         notes = COALESCE(notes || chr(10), '')
                 || to_char(now(), 'YYYY-MM-DD') || ' - referencia passou a ' || _new_reference || ': ' || btrim(_note),
         updated_at = now()
   WHERE name = _name;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Verificacao % nao existe', _name;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.ads_invoice_line_set_tour_split(_line_id uuid, _parts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE l record; inv record; v_uid uuid := auth.uid(); p jsonb; v_sum numeric := 0; v_ids uuid[] := '{}'; v_eid uuid; v_amt numeric;
BEGIN
  SELECT * INTO l FROM public.ads_invoice_line WHERE id = _line_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Linha não encontrada' USING ERRCODE = 'P0002'; END IF;
  IF v_uid IS NULL OR NOT (public.is_platform_admin(v_uid) OR (l.company_id = public.current_company_id() AND (
       public.has_role(v_uid,'admin') OR public.has_role(v_uid,'manager') OR public.has_role(v_uid,'editor') OR public.has_role(v_uid,'accountant')))) THEN
    RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO inv FROM public.ads_invoice WHERE id = l.invoice_id;
  IF inv.status = 'applied' OR inv.parent_transaction_id IS NOT NULL THEN
    RAISE EXCEPTION 'A fatura já foi lançada: reabre-a antes de repartir.' USING ERRCODE = '42501';
  END IF;
  IF _parts IS NULL OR jsonb_typeof(_parts) <> 'array' OR jsonb_array_length(_parts) = 0 THEN
    UPDATE public.ads_invoice_line SET event_split = NULL, updated_at = now() WHERE id = _line_id;
    RETURN jsonb_build_object('ok', true, 'cleared', true);
  END IF;
  IF l.is_adjustment OR l.event_id IS NULL THEN
    RAISE EXCEPTION 'Só linhas de campanha com evento podem ser repartidas.' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.events WHERE parent_event_id = l.event_id) THEN
    RAISE EXCEPTION 'O evento da linha não é Master de turnê.' USING ERRCODE = '23514';
  END IF;
  FOR p IN SELECT * FROM jsonb_array_elements(_parts) LOOP
    v_eid := (p->>'event_id')::uuid;
    v_amt := round((p->>'amount')::numeric, 2);
    IF v_amt IS NULL OR v_amt < 0 THEN RAISE EXCEPTION 'Valor inválido na repartição.' USING ERRCODE = '23514'; END IF;
    IF v_eid IS DISTINCT FROM l.event_id AND NOT EXISTS (SELECT 1 FROM public.events WHERE id = v_eid AND parent_event_id = l.event_id) THEN
      RAISE EXCEPTION 'Evento % não pertence à turnê.', v_eid USING ERRCODE = '23514';
    END IF;
    IF v_eid = ANY(v_ids) THEN RAISE EXCEPTION 'Evento repetido na repartição.' USING ERRCODE = '23514'; END IF;
    v_ids := v_ids || v_eid;
    v_sum := v_sum + v_amt;
  END LOOP;
  IF round(v_sum, 2) <> round(l.amount, 2) THEN
    RAISE EXCEPTION 'A soma das partes (%) não é o valor da linha (%).', round(v_sum,2), round(l.amount,2) USING ERRCODE = '23514';
  END IF;
  UPDATE public.ads_invoice_line
     SET event_split = (SELECT jsonb_agg(jsonb_build_object('event_id', x->>'event_id', 'amount', round((x->>'amount')::numeric, 2),
                                                            'source', COALESCE(x->>'source', 'manual')))
                          FROM jsonb_array_elements(_parts) x),
         matched_by = v_uid, matched_at = now(), updated_at = now()
   WHERE id = _line_id;
  RETURN jsonb_build_object('ok', true, 'parts', jsonb_array_length(_parts));
END $function$

CREATE OR REPLACE FUNCTION public.ads_invoice_line_tour_suggestion(_line_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE l record; inv record; v_uid uuid := auth.uid(); v_from date; v_to date; r jsonb;
BEGIN
  SELECT * INTO l FROM public.ads_invoice_line WHERE id = _line_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Linha não encontrada' USING ERRCODE = 'P0002'; END IF;
  IF v_uid IS NULL OR NOT (public.is_platform_admin(v_uid) OR (l.company_id = public.current_company_id() AND (
       public.has_role(v_uid,'admin') OR public.has_role(v_uid,'manager') OR public.has_role(v_uid,'editor') OR public.has_role(v_uid,'accountant')))) THEN
    RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO inv FROM public.ads_invoice WHERE id = l.invoice_id;
  v_from := date_trunc('month', COALESCE(inv.billing_period, inv.issue_date))::date;
  v_to := (v_from + interval '1 month')::date;
  SELECT jsonb_build_object(
    'line', jsonb_build_object('id', l.id, 'amount', l.amount, 'campaign_name', l.campaign_name,
                               'external_campaign_id', l.external_campaign_id, 'event_id', l.event_id),
    'month', to_char(v_from, 'YYYY-MM'),
    'master', (SELECT jsonb_build_object('id', e.id, 'name', e.name) FROM public.events e WHERE e.id = l.event_id),
    'cities', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', e.id, 'name', e.name, 'city', c.name) ORDER BY e.name)
                          FROM public.events e LEFT JOIN public.cities c ON c.id = e.city_id
                         WHERE e.parent_event_id = l.event_id), '[]'::jsonb),
    'adsets', COALESCE((SELECT jsonb_agg(jsonb_build_object('adset_name', a.adset_name, 'spend', a.spend) ORDER BY a.spend DESC)
                          FROM (SELECT d.adset_name, round(sum(d.spend_cents) / 100.0, 2) AS spend
                                  FROM crm.meta_adset_insights_daily d
                                 WHERE d.company_id = l.company_id
                                   AND d.date_start >= v_from AND d.date_start < v_to
                                   AND (d.external_campaign_id = l.external_campaign_id
                                        OR (l.external_campaign_id IS NULL AND d.campaign_name = l.campaign_name))
                                 GROUP BY d.adset_name) a), '[]'::jsonb)
  ) INTO r;
  RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.artist_s4a_seed_code_create(p_artist_id uuid)
 RETURNS TABLE(code text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_company uuid; v_code text; v_exp timestamptz := now() + interval '10 minutes';
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sessão obrigatória' USING ERRCODE = '42501'; END IF;
  SELECT a.company_id INTO v_company FROM public.artists a WHERE a.id = p_artist_id;
  IF v_company IS NULL THEN RAISE EXCEPTION 'artista inexistente' USING ERRCODE = 'P0002'; END IF;
  IF NOT (public.is_platform_admin(v_uid) OR EXISTS (
        SELECT 1 FROM public.user_roles ur
         WHERE ur.user_id = v_uid AND ur.company_id = v_company
           AND ur.role::text IN ('admin','platform_admin'))) THEN
    RAISE EXCEPTION 'sem permissão (admin da empresa do artista)' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.artist_channels ch
                  WHERE ch.artist_id = p_artist_id AND ch.platform = 'spotify') THEN
    RAISE EXCEPTION 'o artista não tem canal Spotify registado' USING ERRCODE = 'P0002';
  END IF;
  UPDATE public.artist_channel_seed_codes s SET used_at = now()
   WHERE s.provider = 'spotify' AND s.artist_id = p_artist_id AND s.used_at IS NULL;
  v_code := 'S4A-' || upper(encode(extensions.gen_random_bytes(6), 'hex'));
  INSERT INTO public.artist_channel_seed_codes
    (provider, artist_id, company_id, code_hash, created_by, expires_at)
  VALUES ('spotify', p_artist_id, v_company,
          encode(extensions.digest(v_code, 'sha256'), 'hex'), v_uid, v_exp);
  RETURN QUERY SELECT v_code, v_exp;
END $function$

CREATE OR REPLACE FUNCTION public.convert_transaction_to_partner_extra(p_tx_id uuid, p_partner_id uuid, p_event_id uuid, p_notes text DEFAULT NULL::text, p_clear_forecast boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_tx public.transactions; v_id uuid; v_rows int;
BEGIN
  SELECT * INTO v_tx FROM public.transactions WHERE id = p_tx_id FOR UPDATE;
  IF v_tx.id IS NULL OR NOT public.row_belongs_to_current_company(v_tx.company_id) THEN
    RAISE EXCEPTION 'Transação inexistente ou de outra empresa.' USING ERRCODE = 'P0403';
  END IF;
  IF p_partner_id IS NULL OR p_event_id IS NULL THEN RAISE EXCEPTION 'Sócio e evento são obrigatórios.'; END IF;
  PERFORM public._partner_extra_assert_can_write(p_event_id);
  IF v_tx.event_id IS DISTINCT FROM p_event_id THEN
    PERFORM public._partner_extra_assert_can_write(v_tx.event_id);
  END IF;

  SELECT id INTO v_id FROM public.partner_advance_expenses WHERE transaction_id = p_tx_id;
  IF v_id IS NULL THEN
    INSERT INTO public.partner_advance_expenses (event_id, partner_id, transaction_id, notes, company_id)
    VALUES (p_event_id, p_partner_id, p_tx_id, p_notes, v_tx.company_id)
    RETURNING id INTO v_id;
  END IF;

  UPDATE public.transactions
     SET is_transitory = true, transitory_reason = 'partner_advance', exclude_from_result = false,
         forecast_id = CASE WHEN p_clear_forecast THEN NULL ELSE forecast_id END
   WHERE id = p_tx_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN RAISE EXCEPTION 'A transação não foi actualizada.'; END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_meta_audience_collect_leads(p_audience_id uuid)
 RETURNS TABLE(email text, phone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_company_id uuid;
  v_filters jsonb;
  v_event_slugs text[];
  v_sources text[];
  v_since_days int;
  v_consent text;
  v_uid uuid;
  v_service boolean;
BEGIN
  v_uid := auth.uid();
  v_service := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role', '') = 'service_role';
  IF NOT v_service THEN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
    IF NOT (public.has_role(v_uid, 'admin'::app_role)
      OR public.has_role(v_uid, 'marketing_manager'::app_role)) THEN
      RAISE EXCEPTION 'forbidden';
    END IF;
  END IF;

  SELECT a.company_id, a.filters
    INTO v_company_id, v_filters
  FROM public.meta_custom_audiences a
  WHERE a.id = p_audience_id;

  IF v_company_id IS NULL THEN RAISE EXCEPTION 'audience_not_found'; END IF;

  IF NOT v_service AND NOT public.row_belongs_to_current_company(v_company_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF v_filters->>'source' = 'newgang_clube:v2' THEN
    IF v_company_id <> '7c858982-6ccd-47ca-bd65-e0dd3eebf01c'::uuid THEN
      RAISE EXCEPTION 'source_company_mismatch';
    END IF;
    RETURN QUERY
    SELECT DISTINCT lower(btrim(m.email)) AS email, NULL::text AS phone
    FROM public.club_members m
    JOIN public.portal_sites s ON s.id=m.site_id AND s.company_id=m.company_id
    JOIN public.club_member_profiles p ON p.member_id=m.id AND p.site_id=s.id AND p.company_id=m.company_id
    JOIN LATERAL (
      SELECT ev.id,ev.subject_id,ev.company_id,ev.portal,ev.purpose,ev.state,ev.banner_version,ev.revision
      FROM public.club_member_marketing_consents l JOIN public.marketing_consent_events ev ON ev.id=l.event_id
      WHERE l.member_id=m.id AND l.site_id=s.id AND l.company_id=m.company_id AND l.purpose='meta_ads'
        AND ev.subject_id=l.subject_id AND ev.company_id=l.company_id AND ev.portal='newgang' AND ev.purpose='meta_ads'
      ORDER BY ev.revision DESC,ev.id DESC LIMIT 1
    ) consent ON true
    JOIN LATERAL public.marketing_consent_effective(consent.subject_id,statement_timestamp()) effective
      ON effective.event_id=consent.id AND effective.valid_grant
    WHERE m.company_id=v_company_id AND s.domain='newgangfestival.pt' AND s.brand_key='newgang' AND s.active
      AND m.confirmed_at IS NOT NULL
      AND p.birth_date IS NOT NULL AND isfinite(p.birth_date)
      AND p.birth_date <= ((statement_timestamp() AT TIME ZONE 'Europe/Lisbon')::date-interval '13 years')::date
      AND consent.state='granted' AND consent.banner_version='anuncios-v1'
      AND NOT EXISTS(SELECT 1 FROM public.marketing_consent_events newer WHERE newer.subject_id=consent.subject_id AND newer.revision>consent.revision)
      AND length(lower(btrim(m.email))) BETWEEN 3 AND 254
      AND lower(btrim(m.email)) ~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'
      AND NOT EXISTS(SELECT 1 FROM public.suppressed_emails se WHERE lower(btrim(se.email))=lower(btrim(m.email))
        AND (se.company_id IS NULL OR se.company_id=v_company_id));
    RETURN;
  END IF;

  IF v_filters->>'source' = 'coala_list:eb2027' THEN
    IF v_company_id <> '7d831e59-6e82-427b-95a0-64904aae5dd2'::uuid THEN
      RAISE EXCEPTION 'source_company_mismatch';
    END IF;
    RETURN QUERY
    SELECT m.email, identity_capture.phone
    FROM (SELECT DISTINCT lower(btrim(cm.email)) AS email
          FROM public.coala_list_members cm
          WHERE nullif(btrim(cm.email), '') IS NOT NULL) m
    LEFT JOIN LATERAL (
      SELECT c.marketing_opt_in
      FROM public.coala_list_consents c
      WHERE c.company_id = v_company_id AND lower(btrim(c.email)) = m.email
      ORDER BY c.created_at DESC, c.id DESC LIMIT 1
    ) consent ON true
    LEFT JOIN LATERAL (
      SELECT lc.consent_email
      FROM public.lead_capture lc
      WHERE lc.company_id = v_company_id AND lower(btrim(lc.email)) = m.email
      ORDER BY lc.created_at DESC, lc.id DESC LIMIT 1
    ) latest_capture ON true
    LEFT JOIN LATERAL (
      SELECT nullif(btrim(lc.phone), '') AS phone
      FROM public.lead_capture lc
      WHERE lc.company_id = v_company_id AND lower(btrim(lc.email)) = m.email
      ORDER BY (nullif(btrim(lc.phone), '') IS NOT NULL) DESC, lc.created_at DESC, lc.id DESC LIMIT 1
    ) identity_capture ON true
    WHERE coalesce(consent.marketing_opt_in, latest_capture.consent_email, false)
      AND NOT EXISTS (
        SELECT 1 FROM public.suppressed_emails se
        WHERE lower(btrim(se.email)) = m.email
          AND (se.company_id IS NULL OR se.company_id = v_company_id)
      );
    RETURN;
  END IF;

  v_event_slugs := CASE WHEN jsonb_typeof(v_filters->'event_slugs') = 'array'
    THEN ARRAY(SELECT jsonb_array_elements_text(v_filters->'event_slugs')) ELSE NULL END;
  v_sources := CASE WHEN jsonb_typeof(v_filters->'sources') = 'array'
    THEN ARRAY(SELECT jsonb_array_elements_text(v_filters->'sources')) ELSE NULL END;
  v_since_days := nullif(v_filters->>'since_days','')::int;
  v_consent := v_filters->>'consent_required';

  RETURN QUERY
  SELECT DISTINCT lc.email, lc.phone
  FROM public.lead_capture lc
  JOIN public.events e ON e.slug = lc.event_slug
  WHERE e.company_id = v_company_id
    AND (lc.email IS NOT NULL OR lc.phone IS NOT NULL)
    AND (v_event_slugs IS NULL OR array_length(v_event_slugs,1) IS NULL OR lc.event_slug = ANY(v_event_slugs))
    AND (v_sources IS NULL OR array_length(v_sources,1) IS NULL OR lc.source = ANY(v_sources))
    AND (v_since_days IS NULL OR lc.created_at >= now() - (v_since_days || ' days')::interval)
    AND (
      v_consent IS NULL OR v_consent = ''
      OR (v_consent = 'email' AND lc.consent_email = true)
      OR (v_consent = 'whatsapp' AND lc.consent_whatsapp = true)
      OR (v_consent = 'any' AND (lc.consent_email = true OR lc.consent_whatsapp = true))
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_meta_audiences_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_company_id uuid;
  v_uid uuid;
  v_result jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  IF NOT (
    public.has_role(v_uid, 'admin'::app_role)
    OR public.has_role(v_uid, 'marketing_manager'::app_role)
    OR public.has_role(v_uid, 'platform_admin'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden: requires admin or marketing_manager';
  END IF;

  v_company_id := public.current_company_id();
  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'no_active_company';
  END IF;

  WITH audiences AS (
    SELECT
      a.id, a.name, a.description, a.audience_id_meta, a.enabled,
      a.connection_id, a.last_synced_at, a.last_sync_status, a.last_sync_error,
      a.total_records_local, a.total_records_meta, a.created_at, a.updated_at,
      l.ad_account_id, l.display_label AS ad_account_label,
      (SELECT row_to_json(s.*) FROM (
        SELECT id, started_at, finished_at, status, records_processed, error_message
        FROM public.meta_audience_sync_log
        WHERE audience_id = a.id
        ORDER BY started_at DESC LIMIT 1
      ) s) AS last_sync
    FROM public.meta_custom_audiences a
    JOIN crm.ad_platform_account_links l ON l.id = a.connection_id
    WHERE a.company_id = v_company_id
    ORDER BY a.created_at DESC
  ),
  stats AS (
    SELECT
      (SELECT count(*) FROM public.meta_custom_audiences WHERE company_id = v_company_id) AS total_audiences,
      (SELECT count(*) FROM public.meta_custom_audiences WHERE company_id = v_company_id AND enabled) AS enabled_audiences,
      (SELECT count(*) FROM public.meta_custom_audiences WHERE company_id = v_company_id AND last_sync_status = 'error') AS error_audiences,
      (SELECT coalesce(sum(records_processed), 0) FROM public.meta_audience_sync_log s
        JOIN public.meta_custom_audiences a ON a.id = s.audience_id
        WHERE a.company_id = v_company_id AND s.status IN ('ok','partial')
          AND s.started_at >= now() - interval '30 days') AS records_synced_30d,
      (SELECT count(*) FROM public.meta_custom_audiences
        WHERE company_id = v_company_id AND enabled
          AND (last_synced_at IS NULL OR last_synced_at < now() - interval '7 days')) AS stale_audiences
  )
  SELECT jsonb_build_object(
    'company_id', v_company_id,
    'generated_at', now(),
    'stats', (SELECT row_to_json(stats.*) FROM stats),
    'audiences', coalesce((SELECT jsonb_agg(row_to_json(audiences.*)) FROM audiences), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$function$

