CREATE OR REPLACE FUNCTION public.revert_partner_extra(p_tx_id uuid, p_clear_transitory boolean DEFAULT true)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_tx public.transactions; v_ev uuid; v_n int; v_rows int;
BEGIN
  SELECT * INTO v_tx FROM public.transactions WHERE id = p_tx_id FOR UPDATE;
  IF v_tx.id IS NULL OR NOT public.row_belongs_to_current_company(v_tx.company_id) THEN
    RAISE EXCEPTION 'Transação inexistente ou de outra empresa.' USING ERRCODE = 'P0403';
  END IF;
  FOR v_ev IN SELECT DISTINCT event_id FROM public.partner_advance_expenses WHERE transaction_id = p_tx_id LOOP
    PERFORM public._partner_extra_assert_can_write(v_ev);
  END LOOP;
  PERFORM public._partner_extra_assert_can_write(v_tx.event_id);
  DELETE FROM public.partner_advance_expenses WHERE transaction_id = p_tx_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF p_clear_transitory THEN
    UPDATE public.transactions SET is_transitory = false, transitory_reason = NULL WHERE id = p_tx_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN RAISE EXCEPTION 'A transação não foi actualizada.'; END IF;
  END IF;
  RETURN v_n;
END;
$function$

CREATE OR REPLACE FUNCTION public.song_growth_summary(p_song_id uuid, p_to date DEFAULT CURRENT_DATE, p_from date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
 s record; spec record; b record; a record; v jsonb; ln jsonb; groups_out jsonb := '[]'; lines jsonb;
 kpis jsonb := '[]'; kp jsonb; series_out jsonb := '{}'; ent record;
 pct numeric; prec numeric; tol integer; days integer; lo integer; hi integer;
BEGIN
 SELECT * INTO s FROM public.artist_songs WHERE id=p_song_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'música inexistente' USING ERRCODE='P0002'; END IF;
 PERFORM public.artist_access_check(s.artist_id,'read','songs');
 IF p_from IS NULL THEN RETURN public._song_growth_summary_initial(p_song_id,p_to); END IF;
 IF p_to IS NULL OR p_to<p_from THEN RAISE EXCEPTION 'período inválido' USING ERRCODE='22023'; END IF;
 v := public._song_growth_summary_initial(p_song_id,p_to);
 -- D-ERP186: ponto mais próximo; janela de tolerância ±5 dias (7: 2–12; 30: 25–35).
 tol:=5;
 FOR spec IN
 SELECT * FROM (VALUES
 ('musica','Spotify','streams','spotify','streams','song'),
 ('video_ugc','TikTok','ugc_creators','tiktok','ugc_creators','song'),
 ('video_ugc','TikTok','ugc_views','tiktok','ugc_views','song'),
 ('video_ugc','TikTok for Artists','ugc_videos_painel','tiktok','ugc_videos','panel'),
 ('video_ugc','TikTok','ugc_videos','tiktok','ugc_videos','app'),
 ('redes','Instagram','seguidores','instagram','followers','artist'),
 ('redes','TikTok','seguidores','tiktok','followers','artist'),
 ('redes','Spotify','ouvintes_mensais','spotify','monthly_listeners','artist'),
 ('redes','YouTube','inscritos','youtube','subscribers','artist')) x(grupo,canal,indicador,platform,metric,scope)
 UNION ALL SELECT 'musica','Spotify for Artists',metric,platform,metric,'s4a' FROM public.artist_song_metrics_daily
 WHERE song_id=p_song_id AND metric LIKE 's4a\_%' AND metric NOT LIKE '%\_day%' AND metric_date<=p_to AND EXISTS (SELECT 1 FROM jsonb_array_elements(v->'grupos') g,jsonb_array_elements(g->'linhas') l WHERE l->>'indicador'=metric) GROUP BY metric,platform
 LOOP
  b:=NULL; a:=NULL; prec:=NULL;
  IF spec.scope='artist' THEN
   SELECT metric_date d,value v,source src,source_ref ref INTO a FROM public.artist_metrics_daily
    WHERE artist_id=s.artist_id AND platform=spec.platform AND metric=spec.metric AND metric_date<=p_to
    ORDER BY metric_date DESC,CASE source WHEN 'aggregator' THEN 1 WHEN 'platform_api' THEN 2 WHEN 'public_page' THEN 3 ELSE 4 END,captured_at DESC NULLS LAST LIMIT 1;
   days:=a.d-p_from; lo:=days-tol; hi:=days+tol;
   SELECT metric_date d,value v,source src,source_ref ref INTO b FROM public.artist_metrics_daily
    WHERE artist_id=s.artist_id AND platform=spec.platform AND metric=spec.metric
     AND metric_date BETWEEN p_from-tol AND least(p_to,p_from+tol)
    ORDER BY abs(metric_date-p_from),CASE source WHEN 'aggregator' THEN 1 WHEN 'platform_api' THEN 2 WHEN 'public_page' THEN 3 ELSE 4 END,captured_at DESC NULLS LAST LIMIT 1;
   -- The helper's window is capped at p_to too, matching the base selection above.
   lo:=greatest(lo,a.d-p_to);
   pct:=public._artist_metric_pct_near(s.artist_id,spec.platform,spec.metric,a.d,a.v,days,lo,hi);
   prec:=public._artist_metric_precisao(s.artist_id,spec.platform,spec.metric,a.d,a.v,a.ref);
  ELSE
   SELECT metric_date d,value v,source src,source_ref ref INTO a FROM public.artist_song_metrics_daily
    WHERE song_id=p_song_id AND platform=spec.platform AND metric=spec.metric AND metric_date<=p_to
     AND CASE spec.scope WHEN 'app' THEN source IN ('ios_shortcut','manual') WHEN 'panel' THEN source='tiktok_artists' WHEN 's4a' THEN true ELSE source=CASE WHEN spec.platform='spotify' THEN 'aggregator' ELSE 'tiktok_artists' END END
    ORDER BY metric_date DESC,CASE source WHEN 'ios_shortcut' THEN 0 WHEN 'aggregator' THEN 1 WHEN 's4a_api' THEN 1 WHEN 'manual' THEN 2 ELSE 3 END,captured_at DESC NULLS LAST LIMIT 1;
   SELECT metric_date d,value v,source src,source_ref ref INTO b FROM public.artist_song_metrics_daily
    WHERE song_id=p_song_id AND platform=spec.platform AND metric=spec.metric
     AND metric_date BETWEEN p_from-tol AND least(p_to,p_from+tol)
     AND CASE spec.scope WHEN 'app' THEN source IN ('ios_shortcut','manual') WHEN 'panel' THEN source='tiktok_artists' WHEN 's4a' THEN true ELSE source=CASE WHEN spec.platform='spotify' THEN 'aggregator' ELSE 'tiktok_artists' END END
    ORDER BY abs(metric_date-p_from),CASE source WHEN 'ios_shortcut' THEN 0 WHEN 'aggregator' THEN 1 WHEN 's4a_api' THEN 1 WHEN 'manual' THEN 2 ELSE 3 END,captured_at DESC NULLS LAST LIMIT 1;
   pct:=CASE WHEN b.v<>0 THEN round((a.v-b.v)/b.v*100,2) END;
  END IF;
  ln:=jsonb_build_object('canal',spec.canal,'indicador',spec.indicador,'base',b.v,'base_data',b.d,'base_tipo','inicio_periodo',
   'atual',a.v,'atual_data',a.d,'delta',a.v-b.v,'variacao_pct',pct,'source',a.src,'base_source',b.src,
   'precisao',CASE WHEN spec.scope='app' THEN 'arredondado_app' WHEN spec.scope='panel' THEN 'painel_acumulado' ELSE 'serie' END,
   'precisao_valor',prec,'base_ausente',b.d IS NULL);
  IF a.d IS NOT NULL THEN
   groups_out:=groups_out||jsonb_build_object('grupo',spec.grupo,'linha',ln);
  END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('grupo',g,'linhas',coalesce((SELECT jsonb_agg(x->'linha') FROM jsonb_array_elements(groups_out) x WHERE x->>'grupo'=g),'[]'::jsonb))) INTO groups_out FROM unnest(ARRAY['musica','video_ugc','redes']) g;
 FOR kp IN SELECT * FROM jsonb_array_elements(v->'kpis') LOOP
  SELECT l INTO ln FROM jsonb_array_elements(groups_out) g,jsonb_array_elements(g->'linhas') l
   WHERE CASE kp->>'chave' WHEN 'streams_spotify' THEN l->>'indicador'='streams' WHEN 'streams_semana' THEN l->>'indicador'='streams' ELSE l->>'indicador'=kp->>'chave' END LIMIT 1;
  IF kp->>'chave'='streams_semana' THEN
   -- A comparison-period KPI must not carry a second, unrelated weekly base.
   kp:=jsonb_build_object('chave','streams_semana','valor',(ln->>'delta')::numeric,'anterior',NULL,'variacao_pct',ln->'variacao_pct',
    'fonte','aggregator_diferenca_periodo','periodo_de',p_from,'periodo_ate',p_to);
  END IF;
  kp:=kp||jsonb_build_object('base',ln->'base','base_data',ln->'base_data','base_tipo','inicio_periodo','atual',CASE WHEN kp->>'chave'='streams_semana' THEN ln->'delta' ELSE ln->'atual' END,'delta',ln->'delta','variacao_pct',ln->'variacao_pct');
  kpis:=kpis||kp;
 END LOOP;
 FOR ent IN SELECT * FROM jsonb_each(v->'series') LOOP
  SELECT coalesce(jsonb_agg(p ORDER BY p->>'d'),'[]') INTO lines FROM jsonb_array_elements(ent.value) p WHERE (p->>'d')::date BETWEEN p_from AND p_to;
  series_out:=series_out||jsonb_build_object(ent.key,lines);
 END LOOP;
 RETURN v||jsonb_build_object('periodo',jsonb_build_object('de',p_from,'ate',p_to),'grupos',groups_out,'kpis',kpis,'series',series_out,
  'notas',jsonb_build_array('Comparação com o ponto mais próximo do início do período; a data real da base consta em cada linha.','Publicações TikTok do app e do painel são métodos distintos; não se somam nem se comparam entre si.'),
  'notas_tecnicas',jsonb_build_array('Base inicio_periodo: ponto mais próximo a ±5 dias, nunca posterior a p_to; sem ponto na janela a base e o delta são null.','Precisão das métricas de artista pelo helper D-ERP186. Streams no período: diferença do acumulado, não soma de acumulados.'));
END $function$

CREATE OR REPLACE FUNCTION public.crm_rgpd_erase_contact(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_company uuid;
  v_email text;
  v_email_hash text;
  v_lead_count int := 0;
  v_lc_count int := 0;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = 'P0001';
  END IF;

  SELECT company_id, email, email_hash_sha256
    INTO v_company, v_email, v_email_hash
  FROM public.contacts
  WHERE id = p_contact_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'contact_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT (
    public.is_platform_admin(v_caller)
    OR public.has_role(v_caller, 'admin'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'P0003';
  END IF;

  IF NOT public.is_platform_admin(v_caller)
     AND NOT public.row_belongs_to_current_company(v_company) THEN
    RAISE EXCEPTION 'company_mismatch' USING ERRCODE = 'P0004';
  END IF;

  WITH d AS (
    DELETE FROM public.leads WHERE contact_id = p_contact_id RETURNING 1
  )
  SELECT COUNT(*) INTO v_lead_count FROM d;

  IF v_email IS NOT NULL AND btrim(v_email) <> '' THEN
    WITH d AS (
      DELETE FROM public.lead_capture
       WHERE lower(btrim(email)) = lower(btrim(v_email))
      RETURNING 1
    )
    SELECT COUNT(*) INTO v_lc_count FROM d;
  END IF;

  DELETE FROM public.contacts WHERE id = p_contact_id;

  RETURN jsonb_build_object(
    'contact_id',           p_contact_id,
    'email_hash_sha256',    v_email_hash,
    'leads_deleted',        v_lead_count,
    'lead_captures_deleted', v_lc_count,
    'erased_by',            v_caller,
    'erased_at',            now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_whatsapp_eligible(p_contact uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c public.contacts; latest record;
BEGIN
 SELECT * INTO c FROM public.contacts WHERE id=p_contact AND
 (public.row_belongs_to_current_company(company_id) OR auth.role()='service_role');
 IF NOT FOUND OR NOT c.consent_whatsapp OR c.phone_e164 IS NULL OR c.phone_e164 !~ '^\+[1-9][0-9]{7,14}$' THEN RETURN false; END IF;
 SELECT * INTO latest FROM public._crm_whatsapp_latest(c.id,c.company_id);
 IF FOUND THEN RETURN coalesce(latest.decision='granted' AND latest.phone=c.phone_e164
 AND latest.phone_fp=public._club332_whatsapp_fp(c.phone_e164),false); END IF;
 -- Pre-existing legacy true is preserved; explicit revocation above always prevails.
 RETURN c.consent_whatsapp_source IS DISTINCT FROM 'club_profile_whatsapp-v1';
END $function$

CREATE OR REPLACE FUNCTION public.list_endorsable_companies(p_portal_company_id uuid)
 RETURNS TABLE(id uuid, display_name text, legal_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid UUID;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid
      AND ur.role IN ('admin','platform_admin','marketing_manager')
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_portal_company_id IS NULL THEN
    RAISE EXCEPTION 'p_portal_company_id obrigatório';
  END IF;

  RETURN QUERY
  SELECT DISTINCT c.id, c.display_name, c.legal_name
  FROM public.events e
  JOIN public.companies c ON c.id = e.company_id
  WHERE e.company_id <> p_portal_company_id
  ORDER BY c.display_name NULLS LAST;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_lead_capture_vip_welcome()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  MP_COMPANY_ID constant uuid := '7c858982-6ccd-47ca-bd65-e0dd3eebf01c';
  PORTAL_URL_BASE constant text := 'https://www.mundopropicio.com';
  FROM_LINE constant text := 'Mundo Propício <noreply@mpgestaoeventos.com>';
  SENDER_DOM constant text := 'notify.mpgestaoeventos.com';
  v_locale text;
  v_lang text;
  v_coupon text;
  v_label text;
  v_email_lc text;
  v_event_name text;
  v_event_url text;
  v_unsub_token text;
  v_unsub_url text;
  v_unsub_label text;
  v_subject text;
  v_greeting text;
  v_html text;
  v_text text;
  v_message_id text;
  v_idem_key text;
  v_payload jsonb;
  v_event_coupon boolean;
BEGIN
  -- Guarda: só dispara para opt-in com email
  IF NEW.email IS NULL OR NEW.email = '' OR NEW.consent_email IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  -- Guarda: só dispara para leads da MP
  IF NEW.company_id IS DISTINCT FROM MP_COMPANY_ID THEN
    RETURN NEW;
  END IF;

  -- Salvaguarda extra: sources claramente não-MP (ex.: Coala) nunca recebem VIP MP
  IF NEW.source IS NOT NULL AND NEW.source LIKE 'coala%' THEN
    RETURN NEW;
  END IF;

  -- Clube Newgang (F2): só recebe newgang_club_welcome, nunca o VIP MP
  IF NEW.source = 'clube_newgang' THEN
    RETURN NEW;
  END IF;

  -- Supressão: evento com cupom próprio ativo -> vip-coupon-email cobre tudo
  IF NEW.source IS NOT NULL AND NEW.source LIKE 'vip%'
     AND NEW.event_slug IS NOT NULL AND NEW.event_slug <> '' THEN
    SELECT true INTO v_event_coupon
    FROM public.events e
    WHERE e.company_id = MP_COMPANY_ID
      AND e.slug = NEW.event_slug
      AND NULLIF(btrim(e.vip_coupon_code), '') IS NOT NULL
      AND e.vip_coupon_valid_until >= current_date
    LIMIT 1;

    IF v_event_coupon IS TRUE THEN
      RETURN NEW;
    END IF;
  END IF;

  BEGIN
  v_locale := lower(coalesce(NEW.raw->>'locale', ''));
  v_lang := CASE WHEN v_locale = 'en' THEN 'en' ELSE 'pt' END;

  SELECT NULLIF(btrim(value #>> '{}'), '')
    INTO v_coupon
  FROM public.portal_settings
  WHERE company_id = MP_COMPANY_ID
    AND key = 'general.vip_coupon_code'
  LIMIT 1;

  SELECT NULLIF(btrim(value #>> '{}'), '')
    INTO v_label
  FROM public.portal_settings
  WHERE company_id = MP_COMPANY_ID
    AND key = 'general.vip_coupon_discount_label'
  LIMIT 1;
  v_label := COALESCE(v_label,
    CASE WHEN v_lang = 'en' THEN 'VIP discount' ELSE 'desconto VIP' END);

  v_event_name := NULL;
  v_event_url := PORTAL_URL_BASE || '/eventos';
  IF NEW.event_slug IS NOT NULL AND NEW.event_slug <> '' THEN
    SELECT COALESCE(e.title_pt, e.title_en, e.name)
      INTO v_event_name
    FROM public.events e
    WHERE e.company_id = MP_COMPANY_ID AND e.slug = NEW.event_slug
    LIMIT 1;
    v_event_url := PORTAL_URL_BASE || '/eventos/' || NEW.event_slug;
  END IF;

  -- ── Unsubscribe (RGPD) ──
  v_email_lc := lower(NEW.email);
  SELECT token INTO v_unsub_token
    FROM public.email_unsubscribe_tokens
   WHERE email = v_email_lc AND company_id = MP_COMPANY_ID
   LIMIT 1;
  IF v_unsub_token IS NULL THEN
    v_unsub_token := encode(extensions.gen_random_bytes(32), 'hex');
    INSERT INTO public.email_unsubscribe_tokens (token, email, company_id)
      VALUES (v_unsub_token, v_email_lc, MP_COMPANY_ID)
    ON CONFLICT (email, company_id) DO NOTHING;
    SELECT token INTO v_unsub_token
      FROM public.email_unsubscribe_tokens
     WHERE email = v_email_lc AND company_id = MP_COMPANY_ID
     LIMIT 1;
  END IF;
  v_unsub_url := PORTAL_URL_BASE || '/unsubscribe?token=' || v_unsub_token;
  v_unsub_label := CASE WHEN v_lang = 'en' THEN 'Unsubscribe' ELSE 'Cancelar subscrição' END;

  v_message_id := 'vip-welcome:' || NEW.id::text;
  v_idem_key := v_message_id;

  IF v_lang = 'en' THEN
    v_greeting := CASE WHEN NEW.name IS NOT NULL AND btrim(NEW.name) <> ''
                       THEN 'Hi ' || NEW.name || ','
                       ELSE 'Hi,' END;

    IF v_coupon IS NOT NULL THEN
      v_subject := 'Welcome to VIP — your ' || v_label || ' code';
    ELSE
      v_subject := 'Welcome to VIP — you''re in';
    END IF;

