CREATE OR REPLACE FUNCTION public.can_delete_storage_object(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
BEGIN
  IF v_uid IS NULL OR p_name IS NULL OR p_name = '' OR p_name LIKE '%/' OR p_name LIKE '_trash/%' THEN
    RETURN false;
  END IF;
  IF p_bucket IN ('transaction-documents','closing-cost-documents','supplier-documents') THEN
    RETURN (has_role(v_uid,'admin'::app_role) OR has_role(v_uid,'manager'::app_role))
       AND storage_path_belongs_to_current_company(p_name);
  ELSIF p_bucket = 'ticket-office-settlements' THEN
    RETURN has_role(v_uid,'admin'::app_role) AND storage_path_belongs_to_current_company(p_name);
  ELSIF p_bucket = 'camarim-documents' THEN
    SELECT owner INTO v_owner FROM storage.objects WHERE bucket_id = p_bucket AND name = p_name;
    RETURN (has_role(v_uid,'admin'::app_role) OR has_role(v_uid,'manager'::app_role)
            OR has_permission(v_uid,'camarim_manage')
            OR (has_permission(v_uid,'camarim_team') AND v_owner = v_uid))
       AND storage_path_belongs_to_current_company(p_name);
  ELSIF p_bucket = 'card-documents' THEN
    RETURN can_manage_cards(v_uid) OR EXISTS (
      SELECT 1 FROM card_sessions s
      WHERE s.id::text = split_part(p_name, '/', 1) AND s.status = 'open' AND s.holder_profile_id = v_uid);
  ELSIF p_bucket = 'standalone-invoices' THEN
    RETURN split_part(p_name, '/', 1) = current_company_id()::text
       AND (has_role(v_uid,'admin'::app_role) OR has_role(v_uid,'platform_admin'::app_role)
            OR has_role(v_uid,'manager'::app_role) OR has_role(v_uid,'editor'::app_role));
  ELSIF p_bucket = 'bank-statements' THEN
    RETURN split_part(p_name, '/', 1) = current_company_id()::text
       AND (has_role(v_uid,'admin'::app_role) OR has_role(v_uid,'platform_admin'::app_role)
            OR has_role(v_uid,'manager'::app_role));
  ELSIF p_bucket IN ('event-forecast-attachments','event-ab-attachments') THEN
    RETURN is_platform_admin() OR (split_part(p_name, '/', 1) = current_company_id()::text
       AND (has_role(v_uid,'admin'::app_role) OR has_role(v_uid,'manager'::app_role) OR has_role(v_uid,'editor'::app_role)));
  END IF;
  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.data_entry_add_document(p_session uuid, p_name text, p_sha text, p_size integer, p_mime text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.data_entry_sessions; existing uuid; r uuid; p text;
BEGIN
 v := public.data_entry_own_session(p_session, true);
 PERFORM public.data_entry_preparation_gate();
 p := v.company_id::text||'/'||v.id::text||'/'||p_sha;
 IF NOT EXISTS(SELECT 1 FROM public.data_entry_storage_receipts WHERE bucket='data-entry-staging' AND path=p AND company_id=v.company_id AND sha256=p_sha AND size_bytes=p_size AND mime=p_mime) THEN
  RAISE EXCEPTION '#333: Documento não conferido no armazenamento' USING ERRCODE='42501'; END IF;
 SELECT id INTO existing FROM public.data_entry_documents WHERE session_id=v.id AND sha256=p_sha;
 IF existing IS NOT NULL THEN RETURN jsonb_build_object('id',existing,'reused',true); END IF;
 IF (SELECT count(*) FROM public.data_entry_documents WHERE session_id=v.id)>=20 THEN RAISE EXCEPTION '#333: Máximo 20 documentos por lote' USING ERRCODE='P0001'; END IF;
 INSERT INTO public.data_entry_documents(session_id,company_id,name,path,sha256,size_bytes,mime) VALUES(v.id,v.company_id,left(btrim(p_name),255),p,p_sha,p_size,p_mime) RETURNING id INTO r;
 RETURN jsonb_build_object('id',r,'reused',false);
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_attempt_333(p_action text, p_preview uuid, p_snapshot_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE p public.data_entry_previews; s public.data_entry_sessions; d public.data_entry_documents; e jsonb; h text; a public.standalone_attempts_333;
BEGIN
 SELECT * INTO p FROM public.data_entry_previews WHERE id=p_preview;
 IF p.id IS NULL THEN RAISE EXCEPTION '#333: Prévia indisponível' USING ERRCODE='42501'; END IF;
 s:=public.data_entry_own_session(p.session_id,true);
 IF p_snapshot_hash IS DISTINCT FROM p.snapshot_hash THEN RAISE EXCEPTION '#333: Prévia divergente' USING ERRCODE='40001'; END IF;
 SELECT * INTO d FROM public.data_entry_documents WHERE id=p.document_id AND company_id=s.company_id;
 e:=jsonb_build_object('payload',((p.snapshot->'fields')-'customer_nif'::text)||jsonb_build_object('file_name',d.name,'created_by',auth.uid()),
  'document',jsonb_build_object('sha256',d.sha256,'size_bytes',d.size_bytes,'mime',d.mime),'effects',p.snapshot->'effects','preview_id',p.id,'snapshot_hash',p.snapshot_hash);
 h:=encode(extensions.digest(convert_to(e::text,'UTF8'),'sha256'),'hex');
 IF p_action='prepare' THEN RETURN public.standalone_attempt_internal_333('prepare',NULL,'assistant_create',e,NULL,NULL,false); END IF;
 SELECT * INTO a FROM public.standalone_attempts_333 WHERE company_id=s.company_id AND principal=auth.uid()::text AND operation='assistant_create' AND envelope_hash=h;
 IF a.id IS NULL THEN RAISE EXCEPTION '#333: Reserva antes do upload obrigatória' USING ERRCODE='42501'; END IF;
 RETURN public.standalone_attempt_internal_333(p_action,a.id,'assistant_create',NULL,h,NULL,false);
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_commit(p_preview uuid, p_snapshot_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.data_entry_previews; s public.data_entry_sessions; d public.data_entry_documents; r public.data_entry_results; a record;
 f jsonb; mark text; final_path text; output jsonb; now_ts timestamptz := now();
BEGIN
 a := public.data_entry_actor();
 SELECT * INTO v FROM public.data_entry_previews WHERE id=p_preview;
 IF v.id IS NULL THEN RAISE EXCEPTION '#333: Prévia inexistente' USING ERRCODE='42501'; END IF;
 s := public.data_entry_own_session(v.session_id, true);  -- serialises executions of the same lote
 SELECT * INTO r FROM public.data_entry_results WHERE preview_id=v.id;
 IF r.preview_id IS NOT NULL THEN RETURN r.result; END IF;
 IF NOT public.data_entry_pilot8_gate('assistant_create') THEN RAISE EXCEPTION '#333: Execução não validada; indisponível' USING ERRCODE='42501'; END IF;
 IF v.snapshot_hash IS DISTINCT FROM p_snapshot_hash OR v.snapshot_hash <> encode(extensions.digest(convert_to(v.snapshot::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION '#333: Autorização não corresponde à prévia' USING ERRCODE='40001'; END IF;
 IF v.version<>(SELECT max(version) FROM public.data_entry_previews WHERE session_id=s.id) THEN RAISE EXCEPTION '#333: Prévia alterada; autoriza a versão atual' USING ERRCODE='40001'; END IF;
 SELECT * INTO d FROM public.data_entry_documents WHERE id=v.document_id;
 IF v.snapshot->'document'->>'sha256' IS DISTINCT FROM d.sha256 OR v.snapshot->'document'->>'path' IS DISTINCT FROM d.path THEN RAISE EXCEPTION '#333: Documento alterado' USING ERRCODE='40001'; END IF;
 final_path := s.company_id::text||'/assistant333/'||d.id::text||'/'||d.sha256||(CASE d.mime WHEN 'application/pdf' THEN '.pdf' WHEN 'image/jpeg' THEN '.jpg' ELSE '.png' END);
 IF NOT EXISTS(SELECT 1 FROM public.data_entry_storage_receipts WHERE bucket='standalone-invoices' AND path=final_path AND company_id=s.company_id AND sha256=d.sha256 AND size_bytes=d.size_bytes AND mime=d.mime) THEN
  RAISE EXCEPTION '#333: Arquivo final não conferido' USING ERRCODE='40001'; END IF;
 f := v.snapshot->'fields';
 IF (SELECT tax_id FROM public.companies WHERE id=s.company_id) IS DISTINCT FROM v.snapshot->>'company_tax'
  OR (SELECT nullif(btrim(full_name),'') FROM public.profiles WHERE id=(f->>'paid_by_partner_id')::uuid) IS DISTINCT FROM v.snapshot->>'payer_name'
  OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=(f->>'paid_by_partner_id')::uuid AND company_id=s.company_id) THEN
  RAISE EXCEPTION '#333: Dados do ERP mudaram; prepara nova prévia' USING ERRCODE='40001'; END IF;
 -- Serialises #333 executors; legacy writers are guarded only by the canonical unique index (exact spelling).
 PERFORM pg_advisory_xact_lock(hashtextextended(s.company_id::text||'|'||public.data_entry_identity(f->>'supplier_nif')||'|'||public.data_entry_identity(f->>'invoice_number'),333));
 -- Revalidate after potentially waiting for the identity lock; expiration cannot authorize INSERT.
 a := public.data_entry_actor();
 IF a.company IS DISTINCT FROM s.company_id OR NOT public.data_entry_pilot8_gate('assistant_create') THEN RAISE EXCEPTION '#333: Piloto indisponível' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.standalone_invoices WHERE company_id=s.company_id AND public.data_entry_identity(supplier_nif)=public.data_entry_identity(f->>'supplier_nif') AND public.data_entry_identity(invoice_number)=public.data_entry_identity(f->>'invoice_number')) THEN
  RAISE EXCEPTION '#333: Fatura já existe no ERP; nenhuma nova ação' USING ERRCODE='23505'; END IF;
 mark := 'Feito por LLM com autorização de '||a.actor_name||' em '||to_char(now_ts AT TIME ZONE 'Europe/Lisbon','DD/MM/YYYY')||'.';
 INSERT INTO public.standalone_invoices(id,company_id,storage_path,file_name,supplier_name,supplier_nif,invoice_number,invoice_date,currency,original_amount,fx_rate,fx_rate_source,total_amount,iva_amount,paid_by_partner_id,notes,status,created_by)
 VALUES(v.destination_id,s.company_id,final_path,d.name,f->>'supplier_name',f->>'supplier_nif',f->>'invoice_number',(f->>'invoice_date')::date,'EUR',NULL,NULL,NULL,(f->>'total_amount')::numeric,(f->>'iva_amount')::numeric,(f->>'paid_by_partner_id')::uuid,concat_ws(E'\n',nullif(f->>'notes',''),mark),'new',a.uid);
 output := jsonb_build_object('invoice_id',v.destination_id,'preview_id',v.id,'document_id',d.id,'path',final_path,'sha256',d.sha256,'status','new',
  'total_amount',(f->>'total_amount')::numeric,'iva_amount',(f->>'iva_amount')::numeric,'invoice_date',f->>'invoice_date','supplier_nif',f->>'supplier_nif','invoice_number',f->>'invoice_number',
  'approved_by',a.uid,'approved_name',a.actor_name,'approved_at',now_ts,'observation',mark);
 INSERT INTO public.data_entry_results(preview_id,company_id,document_id,invoice_id,approved_by,approved_name,approved_at,snapshot_hash,result)
 VALUES(v.id,s.company_id,d.id,v.destination_id,a.uid,a.actor_name,now_ts,v.snapshot_hash,output);
 RETURN output;
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_note(p_session uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v public.data_entry_sessions; r uuid;
BEGIN
 v := public.data_entry_own_session(p_session, true);
 PERFORM public.data_entry_preparation_gate();
 IF p_body IS NULL OR length(btrim(p_body)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION '#333: Nota inválida' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM public.data_entry_messages WHERE session_id=v.id)>=200 THEN RAISE EXCEPTION '#333: Limite de notas do lote' USING ERRCODE='P0001'; END IF;
 INSERT INTO public.data_entry_messages(session_id,company_id,author_id,body) VALUES(v.id,v.company_id,auth.uid(),btrim(p_body)) RETURNING id INTO r;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_prepare(p_session uuid, p_document uuid, p_fields jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s public.data_entry_sessions; d public.data_entry_documents; v public.data_entry_previews; a record;
 n integer; snap jsonb; payer uuid; payer_name text; company_tax text; total numeric; vat numeric; day date; k text;
 required text[] := ARRAY['supplier_name','supplier_nif','invoice_number','invoice_date','currency','total_amount','iva_amount','paid_by_partner_id','customer_nif','notes'];
BEGIN
 a := public.data_entry_actor();
 s := public.data_entry_own_session(p_session, true);
 PERFORM public.data_entry_preparation_gate();
 SELECT * INTO d FROM public.data_entry_documents WHERE id=p_document AND session_id=s.id;
 IF d.id IS NULL THEN RAISE EXCEPTION '#333: Documento inválido' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.data_entry_results WHERE document_id=d.id) THEN RAISE EXCEPTION '#333: Documento já registado; consulta o resultado' USING ERRCODE='23505'; END IF;
 IF jsonb_typeof(p_fields) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: Campos inválidos' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_fields) LOOP IF NOT k = ANY(required) THEN RAISE EXCEPTION '#333: Campo não permitido' USING ERRCODE='22023'; END IF; END LOOP;
 FOREACH k IN ARRAY required LOOP
  IF NOT p_fields ? k OR jsonb_typeof(p_fields->k) <> (CASE WHEN k IN ('total_amount','iva_amount') THEN 'number' ELSE 'string' END) THEN RAISE EXCEPTION '#333: Campo % em falta ou com tipo errado', k USING ERRCODE='22023'; END IF;
 END LOOP;
 IF length(btrim(p_fields->>'supplier_name')) NOT BETWEEN 1 AND 200 OR length(public.data_entry_norm(p_fields->>'supplier_nif')) NOT BETWEEN 5 AND 40
  OR length(btrim(p_fields->>'invoice_number')) NOT BETWEEN 1 AND 100 OR length(p_fields->>'notes')>2000 THEN RAISE EXCEPTION '#333: Confirma fornecedor, NIF, número e nota' USING ERRCODE='22023'; END IF;
 IF p_fields->>'currency' <> 'EUR' THEN RAISE EXCEPTION '#333: Só EUR nesta versão; outras moedas indisponíveis' USING ERRCODE='22023'; END IF;
 IF (p_fields->>'invoice_date') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION '#333: Data civil inválida' USING ERRCODE='22023'; END IF;
 BEGIN day := (p_fields->>'invoice_date')::date; EXCEPTION WHEN others THEN RAISE EXCEPTION '#333: Data civil inválida' USING ERRCODE='22023'; END;
 IF to_char(day,'YYYY-MM-DD') <> p_fields->>'invoice_date' THEN RAISE EXCEPTION '#333: Data civil inválida' USING ERRCODE='22023'; END IF;
 total := (p_fields->>'total_amount')::numeric; vat := (p_fields->>'iva_amount')::numeric;
 IF total<0 OR vat<0 OR vat>total OR total>99999999.99 OR round(total,2)<>total OR round(vat,2)<>vat THEN RAISE EXCEPTION '#333: Valores inválidos' USING ERRCODE='22023'; END IF;
 IF (p_fields->>'paid_by_partner_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION '#333: Pagador inválido' USING ERRCODE='22023'; END IF;
 payer := (p_fields->>'paid_by_partner_id')::uuid;
 SELECT nullif(btrim(pr.full_name),'') INTO payer_name FROM public.profiles pr WHERE pr.id=payer AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=payer AND ur.company_id=s.company_id);
 IF payer_name IS NULL THEN RAISE EXCEPTION '#333: Confirma um pagador membro desta empresa' USING ERRCODE='22023'; END IF;
 SELECT tax_id INTO company_tax FROM public.companies WHERE id=s.company_id;
 IF public.data_entry_norm(company_tax)='' OR public.data_entry_norm(company_tax)<>public.data_entry_norm(p_fields->>'customer_nif') THEN RAISE EXCEPTION '#333: NIF do destinatário não corresponde à empresa' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.standalone_invoices WHERE company_id=s.company_id AND public.data_entry_identity(supplier_nif)=public.data_entry_identity(p_fields->>'supplier_nif') AND public.data_entry_identity(invoice_number)=public.data_entry_identity(p_fields->>'invoice_number')) THEN
  RAISE EXCEPTION '#333: Fatura já existe no ERP; nenhuma nova ação' USING ERRCODE='23505'; END IF;
 SELECT coalesce(max(version),0)+1 INTO n FROM public.data_entry_previews WHERE session_id=s.id;
 snap := jsonb_build_object('schema_version',2,'operation','standalone_invoice_v1','company_id',s.company_id,'company_tax',company_tax,'event_id',s.event_id,
  'prepared_by',a.uid,'version',n,'document',jsonb_build_object('id',d.id,'path',d.path,'sha256',d.sha256,'mime',d.mime,'size_bytes',d.size_bytes,'name',d.name),
  'fields',jsonb_build_object('supplier_name',btrim(p_fields->>'supplier_name'),'supplier_nif',btrim(p_fields->>'supplier_nif'),'invoice_number',btrim(p_fields->>'invoice_number'),
    'invoice_date',p_fields->>'invoice_date','currency','EUR','total_amount',total,'iva_amount',vat,'paid_by_partner_id',payer,'customer_nif',btrim(p_fields->>'customer_nif'),'notes',p_fields->>'notes'),
  'payer_name',payer_name,'provenance','confirmed_by_user',
  'effects',jsonb_build_array('Criar 1 Fatura Avulsa (estado novo) com o documento anexado','Sem transação, BP, conta, lista de pagamento ou reembolso'));
 INSERT INTO public.data_entry_previews(session_id,company_id,document_id,version,created_by,operation,snapshot,snapshot_hash)
 VALUES(s.id,s.company_id,d.id,n,a.uid,'standalone_invoice_v1',snap,encode(extensions.digest(convert_to(snap::text,'UTF8'),'sha256'),'hex')) RETURNING * INTO v;
 RETURN to_jsonb(v);
END $function$

CREATE OR REPLACE FUNCTION crm.audience_validate(p_proposal jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
declare
  v_market text := coalesce(p_proposal->>'market_scope','PT');
  v_currency text := upper(coalesce(p_proposal->>'currency','EUR'));
  v_min_ev int := 5; v_veto_mult numeric := 3.0;
  v_roas_target numeric := nullif(p_proposal->>'roas_target','')::numeric;
  v_janela numeric := nullif(p_proposal->>'janela_dias','')::numeric;
  v_cpa    numeric := nullif(p_proposal->>'cpa_esperado_eur','')::numeric;
  v_n_adsets int; v_struct_p90 numeric; v_struct_max numeric; v_struct_carimbo text;
  v_currency_ok boolean; v_carimbos jsonb := '[]'::jsonb; v_rec record;
  v_n_ok int:=0; v_n_aviso int:=0; v_n_vermelho int:=0;
  v_n_sai int:=0; v_n_tarde int:=0; v_n_naosai int:=0; v_dias numeric; v_apr text;
  v_roas_block jsonb := null; v_roas_med numeric; v_verdict text;
begin
  v_currency_ok := case when v_market='PT' then v_currency='EUR' else true end;

  select round((percentile_cont(0.90) within group (order by k.n))::numeric,0), max(k.n)
    into v_struct_p90, v_struct_max
  from (select m.id, count(e.*) n from crm.campaign_memory m
          join crm.campaign_memory_element e on e.campaign_memory_id=m.id
         where m.market_scope=v_market and m.is_provisional=false group by m.id) k;

  v_n_adsets := jsonb_array_length(coalesce(p_proposal->'adsets','[]'::jsonb));
  v_struct_carimbo := case when v_struct_p90 is null then 'sem_evidencia'
    when v_n_adsets<=v_struct_p90 then 'ok' when v_n_adsets<=v_struct_max then 'aviso' else 'vermelho' end;

  for v_rec in
    with env as (
      select e.audience_archetype arquetipo, count(*) n_evidencia,
             round((percentile_cont(0.90) within group (order by e.daily_budget_cents))::numeric/100.0,0) p90_eur
        from crm.campaign_memory_element e join crm.campaign_memory m on m.id=e.campaign_memory_id
       where m.market_scope=v_market and m.is_provisional=false
         and e.daily_budget_cents is not null and e.daily_budget_cents>0
       group by e.audience_archetype),
    prop as (select a.ord::int idx, a.value->>'archetype' arquetipo,
                    (a.value->>'daily_budget_eur')::numeric orc_eur
               from jsonb_array_elements(coalesce(p_proposal->'adsets','[]'::jsonb)) with ordinality a(value,ord))
    select p.idx,p.arquetipo,p.orc_eur,env.p90_eur,env.n_evidencia,
           round(env.p90_eur*v_veto_mult,0) veto_eur,
           case when env.arquetipo is null then 'sem_evidencia'
                when env.n_evidencia<v_min_ev and p.orc_eur>env.p90_eur then 'aviso'
                when p.orc_eur<=env.p90_eur then 'ok'
                when p.orc_eur<=round(env.p90_eur*v_veto_mult,0) then 'aviso' else 'vermelho' end carimbo
      from prop p left join env on env.arquetipo=p.arquetipo order by p.idx
  loop
    if v_rec.carimbo='ok' then v_n_ok:=v_n_ok+1;
    elsif v_rec.carimbo='vermelho' then v_n_vermelho:=v_n_vermelho+1; else v_n_aviso:=v_n_aviso+1; end if;

    if v_cpa is null or v_janela is null or v_rec.orc_eur is null or v_rec.orc_eur<=0 then
      v_dias:=null; v_apr:='sem_dados';
    else
      v_dias := round(50*v_cpa/v_rec.orc_eur,0);
      v_apr := case when v_dias<=least(7,v_janela) then 'sai_a_tempo'
                    when v_dias<=v_janela then 'sai_tarde' else 'nao_sai_na_janela' end;
      if v_apr='sai_a_tempo' then v_n_sai:=v_n_sai+1;
      elsif v_apr='sai_tarde' then v_n_tarde:=v_n_tarde+1; else v_n_naosai:=v_n_naosai+1; end if;
    end if;

    v_carimbos := v_carimbos || jsonb_build_object('idx',v_rec.idx,'archetype',v_rec.arquetipo,
      'daily_budget_eur',v_rec.orc_eur,'ok_ate',v_rec.p90_eur,'vermelho_acima',v_rec.veto_eur,
      'n_evidencia',v_rec.n_evidencia,'carimbo',v_rec.carimbo,'dias_ate_50',v_dias,'aprendizado',v_apr);
  end loop;

  if v_roas_target is not null then
    select round((percentile_cont(0.5) within group (order by roas))::numeric,2) into v_roas_med
      from crm.campaign_memory where market_scope=v_market and is_provisional=false and roas is not null;
    v_roas_block := jsonb_build_object('valor',v_roas_target,'mediana_historica',v_roas_med,
      'carimbo',case when v_roas_med is not null and v_roas_target>v_roas_med*2 then 'aviso' else 'ok' end);
  end if;

  v_verdict := case
    when v_n_vermelho>0 or v_struct_carimbo='vermelho' or not v_currency_ok then 'exige_destrave'
    when v_n_aviso>0 or v_struct_carimbo='aviso'
         or (v_roas_block is not null and v_roas_block->>'carimbo'='aviso') then 'tem_avisos' else 'ok' end;

  return jsonb_build_object('market',v_market,'verdict',v_verdict,'currency_ok',v_currency_ok,
    'structure',jsonb_build_object('n_adsets',v_n_adsets,'ok_ate',v_struct_p90,'vermelho_acima',v_struct_max,'carimbo',v_struct_carimbo),
    'roas_target',v_roas_block,
    'aprendizado',jsonb_build_object('janela_dias',v_janela,'cpa_esperado_eur',v_cpa,
      'sai_a_tempo',v_n_sai,'sai_tarde',v_n_tarde,'nao_sai',v_n_naosai,
      'nota',case when v_cpa is null or v_janela is null then 'sem janela/CPA - aprendizado nao avaliado'
                  when v_n_naosai=v_n_adsets then 'Learning Limited a janela toda: pesa no quente, verba estavel no dia 1, sem saltos >20%'
                  when v_n_naosai>0 then 'parte dos adsets nao sai na janela - priorize os que saem ou consolide verba'
                  else 'sai do aprendizado dentro da janela' end),
    'adsets',v_carimbos,'resumo',jsonb_build_object('ok',v_n_ok,'aviso',v_n_aviso,'vermelho',v_n_vermelho));
end;
$function$

CREATE OR REPLACE FUNCTION public.artist_ads_refresh_claim(p_artist_id uuid, p_scheduled boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'crm'
AS $function$
DECLARE v_company uuid; v_now timestamptz:=clock_timestamp(); v_id uuid:=gen_random_uuid();
        v_row public.artist_ads_refresh_control%ROWTYPE;
BEGIN
  IF p_scheduled IS NULL THEN RAISE EXCEPTION 'p_scheduled obrigatório'; END IF;
  IF p_scheduled THEN
    IF coalesce(auth.role(),'')<>'service_role' THEN
      RAISE EXCEPTION 'sync agendado reservado ao serviço' USING ERRCODE='42501';
    END IF;
    SELECT a.company_id INTO v_company FROM public.artists a
      WHERE a.id=p_artist_id AND a.status='ativo' AND a.company_id IS NOT NULL FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'artista ativo inexistente ou sem empresa' USING ERRCODE='42501';
    END IF;
  ELSE
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'sessão obrigatória' USING ERRCODE='42501'; END IF;
    v_company:=public.artist_access_check(p_artist_id,'read','traffic');
    -- Lock por artista: permissão manual validada antes de consumir o limite.
    PERFORM 1 FROM public.artists WHERE id=p_artist_id AND company_id=v_company FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'artista alterado' USING ERRCODE='42501'; END IF;
  END IF;
  INSERT INTO public.artist_ads_refresh_control(artist_id,company_id,last_started_at)
    VALUES(p_artist_id,v_company,v_now) ON CONFLICT(artist_id) DO NOTHING;
  SELECT * INTO v_row FROM public.artist_ads_refresh_control WHERE artist_id=p_artist_id FOR UPDATE;
  IF v_row.company_id IS DISTINCT FROM v_company THEN
    RAISE EXCEPTION 'empresa do artista alterada; rever controlo' USING ERRCODE='42501';
  END IF;
  IF v_row.lease_until>v_now THEN
    RETURN jsonb_build_object('accepted',false,'reason','in_progress',
      'retry_after_seconds',ceil(extract(epoch FROM v_row.lease_until-v_now)),
      'last_synced_at',v_row.last_synced_at,'platforms',v_row.platform_results);
  END IF;
  IF NOT p_scheduled AND v_row.last_requested_at>v_now-interval '2 minutes' THEN
    RETURN jsonb_build_object('accepted',false,'reason','rate_limited',
      'retry_after_seconds',ceil(extract(epoch FROM v_row.last_requested_at+interval '2 minutes'-v_now)),
      'last_synced_at',v_row.last_synced_at,'platforms',v_row.platform_results);
  END IF;
  UPDATE public.artist_ads_refresh_control SET request_id=v_id,last_started_at=v_now,
    lease_until=v_now+interval '5 minutes',
    last_requested_at=CASE WHEN p_scheduled THEN last_requested_at ELSE v_now END
    WHERE artist_id=p_artist_id;
  RETURN jsonb_build_object('accepted',true,'request_id',v_id,'company_id',v_company,
    'lease_until',v_now+interval '5 minutes','last_synced_at',v_row.last_synced_at,
    'platforms',v_row.platform_results);
END $function$

CREATE OR REPLACE FUNCTION crm.get_meta_decrypted_token(p_connection_id uuid, p_master_key text)
 RETURNS TABLE(access_token text, external_business_id text, external_business_name text, company_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE
  v_encrypted text;
  v_business_id text;
  v_business_name text;
  v_company_id uuid;
  v_caller_company uuid;
BEGIN
  -- Guard 1: caller must have an active company resolvable via current_company_id()
  v_caller_company := public.current_company_id();
  IF v_caller_company IS NULL THEN
    RAISE EXCEPTION 'No active company for caller (auth.uid()=%)', auth.uid();
  END IF;

  -- Guard 2: connection must belong to caller's company
  SELECT apc.access_token_encrypted, apc.external_business_id, apc.external_business_name, apc.company_id
  INTO v_encrypted, v_business_id, v_business_name, v_company_id
  FROM crm.ad_platform_connections apc
  WHERE apc.id = p_connection_id
    AND apc.platform = 'meta'
    AND apc.status = 'active'
    AND apc.company_id = v_caller_company;

  IF v_encrypted IS NULL THEN
    RAISE EXCEPTION 'Active Meta connection not found or not authorised (id=%, caller_company=%)', p_connection_id, v_caller_company;
  END IF;

  RETURN QUERY SELECT
    extensions.pgp_sym_decrypt(decode(v_encrypted, 'base64'), p_master_key)::text,
    v_business_id,
    v_business_name,
    v_company_id;
END;
$function$

CREATE OR REPLACE FUNCTION crm.select_duel_candidate(p_duel_id uuid, p_winner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_company uuid := public.current_company_id();
  v_winner_company uuid;
BEGIN
  IF v_company IS NULL THEN
    RAISE EXCEPTION 'no_active_company';
  END IF;

  SELECT company_id INTO v_winner_company
  FROM crm.meta_campaign_strategies
  WHERE id = p_winner_id AND duel_id = p_duel_id;

  IF v_winner_company IS NULL THEN
    RAISE EXCEPTION 'winner_not_found_in_duel';
  END IF;

  IF v_winner_company <> v_company THEN
    RAISE EXCEPTION 'forbidden_company_mismatch';
  END IF;

  UPDATE crm.meta_campaign_strategies
  SET status = 'selected', updated_at = now()
  WHERE id = p_winner_id
    AND duel_id = p_duel_id
    AND company_id = v_company;

  -- Arquiva quaisquer irmãos (se não houver, simplesmente não afeta linhas)
  UPDATE crm.meta_campaign_strategies
  SET status = 'archived', updated_at = now()
  WHERE duel_id = p_duel_id
    AND id <> p_winner_id
    AND status = 'candidate'
    AND company_id = v_company;
END;
$function$

CREATE OR REPLACE FUNCTION public.data_entry_assistant_execute_333(p_mode text, p_authorization uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_company uuid; a public.data_entry_assistant_authorizations_333; v public.data_entry_assistant_review_versions_333;
  cur_version integer; act jsonb; e jsonb; c jsonb; ex public.data_entry_assistant_executions_333; res jsonb; dep text; x jsonb;
  v_office uuid; v_event uuid; v_st uuid; v_n int; v_sum numeric; s record; t record; v_amount numeric; v_date date;
  v_gross numeric; v_set uuid; v_email text; v_key text; v_legs int; v_bad int; v_paid int; v_div int; v_total bigint; v_sdate date;
  v_exp jsonb; v_act jsonb; v_to uuid; v_ok boolean;
BEGIN
  IF p_mode = 'probe' THEN
    RETURN jsonb_build_object('schema', '333-12f', 'enabled', coalesce((SELECT enabled FROM public.data_entry_assistant_executor_settings_333 WHERE singleton), false));
  END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  v_company := public.current_company_id();
  IF v_company IS NULL
     OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id = v_uid AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until <= now()))
     OR NOT EXISTS (SELECT 1 FROM public.companies WHERE id = v_company AND status = 'active')
     OR coalesce(public._effective_permissions_for(v_uid, v_company, '{}'::text[])->>'role', '') NOT IN ('admin', 'manager')
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;

  IF p_mode = 'status' THEN
    SELECT * INTO a FROM public.data_entry_assistant_authorizations_333 WHERE id = p_authorization;
    IF NOT FOUND OR a.owner_id IS DISTINCT FROM v_uid OR a.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    RETURN jsonb_build_object('authorization_id', a.id, 'action_ids', to_jsonb(a.action_ids), 'executions',
      coalesce((SELECT jsonb_agg(jsonb_build_object('action_id', y.action_id, 'status', y.status, 'result', y.result, 'at', y.created_at) ORDER BY y.created_at)
        FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id), '[]'::jsonb));
  END IF;
  IF p_mode <> 'execute' THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '22023'; END IF;
  IF NOT coalesce((SELECT enabled FROM public.data_entry_assistant_executor_settings_333 WHERE singleton), false) THEN RAISE EXCEPTION '#333: executor_closed' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.data_entry_assistant_scope_333 WHERE owner_id = v_uid AND company_id = v_company AND expires_at > now())
  THEN RAISE EXCEPTION '#333: scope_closed' USING ERRCODE = '42501'; END IF;

  SELECT * INTO a FROM public.data_entry_assistant_authorizations_333 WHERE id = p_authorization FOR UPDATE;
  IF NOT FOUND OR a.owner_id IS DISTINCT FROM v_uid OR a.company_id IS DISTINCT FROM v_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  SELECT * INTO ex FROM public.data_entry_assistant_executions_333 WHERE authorization_id = a.id AND action_id = p_action;
  IF FOUND THEN RETURN jsonb_build_object('action_id', p_action, 'status', ex.status, 'replayed', true, 'result', ex.result); END IF;
  IF p_action IS NULL OR NOT (p_action = ANY (a.action_ids)) THEN RAISE EXCEPTION '#333: action_not_authorized' USING ERRCODE = 'P0001'; END IF;

  -- 12h: FOR SHARE conflita com o FOR UPDATE do 'save' (nova versão): o executor espera e vê a versão nova (stale_version),
  -- em vez de executar uma versão revogada em simultâneo (bug confirmado com 2 ligações, grupo 24f).
  SELECT version INTO cur_version FROM public.data_entry_assistant_reviews_333 WHERE id = a.review_id FOR SHARE;
  IF cur_version IS DISTINCT FROM a.version THEN RAISE EXCEPTION '#333: stale_version' USING ERRCODE = '40001'; END IF;
  SELECT * INTO v FROM public.data_entry_assistant_review_versions_333 WHERE review_id = a.review_id AND version = a.version;
  IF NOT FOUND OR v.effects_hash IS DISTINCT FROM a.effects_hash
     OR encode(sha256(convert_to(public._de333_canon(jsonb_build_object('effects', v.proposal->'effects', 'actions', v.proposal->'actions')), 'UTF8')), 'hex') IS DISTINCT FROM a.effects_hash
  THEN RAISE EXCEPTION '#333: hash_mismatch' USING ERRCODE = '22023'; END IF;
  -- Contrato de ações fixo (server-owned): ids, tipos e dependências; a5 depende de a3 ou, com fecho já confirmado, de nada.
  IF jsonb_typeof(v.proposal->'actions') IS DISTINCT FROM 'array'
     OR (SELECT count(DISTINCT y->>'id') FROM jsonb_array_elements(v.proposal->'actions') y) IS DISTINCT FROM jsonb_array_length(v.proposal->'actions')::bigint
  THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  FOR x IN SELECT y FROM jsonb_array_elements(v.proposal->'actions') y LOOP
    IF ((x->>'id', x->>'kind', x->'depends_on') IN (('a1','create_statement','[]'::jsonb), ('a2','confirm_statement','["a1"]'::jsonb),
        ('a4','verify_deductions','["a2"]'::jsonb), ('a3','save_settlement','["a4"]'::jsonb), ('a5','register_liquidation','["a3"]'::jsonb), ('a5','register_liquidation','[]'::jsonb))) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  END LOOP;
  e := v.proposal->'effects';
  IF e->>'company' IS DISTINCT FROM v_company::text OR v.proposal->>'company_id' IS DISTINCT FROM v_company::text OR coalesce((e->>'human_reviewed')::boolean, false) IS NOT TRUE
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  SELECT y INTO act FROM jsonb_array_elements(v.proposal->'actions') y WHERE y->>'id' = p_action;
  IF act IS NULL OR act->'blocked_reason' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
  FOR dep IN SELECT jsonb_array_elements_text(act->'depends_on') LOOP
    IF NOT (dep = ANY (a.action_ids)) OR NOT EXISTS (SELECT 1 FROM public.data_entry_assistant_executions_333 WHERE authorization_id = a.id AND action_id = dep)
    THEN RAISE EXCEPTION '#333: dependency_pending' USING ERRCODE = 'P0001'; END IF;
  END LOOP;
  v_event := public._de333_req(e, 'event')::uuid;
  v_office := public._de333_req(e, 'office')::uuid;

  IF p_action IN ('a1', 'a2') THEN
    -- Efeitos do apuramento validados estruturalmente; linhas esperadas = lista ordenada completa (posição, tipo, descrição, cêntimos, evento).
    v_total := public._de333_cents(e->'total', NULL); v_sdate := public._de333_req(e, 'date')::date; PERFORM public._de333_req(e, 'number');
    IF jsonb_typeof(e->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(e->'lines') = 0
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(e->'lines') l WHERE jsonb_typeof(l->'line_type') IS DISTINCT FROM 'string' OR jsonb_typeof(l->'description') IS DISTINCT FROM 'string')
    THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    SELECT jsonb_agg(jsonb_build_array((o - 1)::int, l->>'line_type', left(l->>'description', 160), public._de333_cents(l->'amount_cents', NULL), v_event, true) ORDER BY o)
      INTO v_exp FROM jsonb_array_elements(e->'lines') WITH ORDINALITY AS z(l, o);
  END IF;

  IF p_action = 'a1' THEN
    IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_office AND company_id = v_company AND type = 'ticket_office' AND is_active IS TRUE)
       OR NOT EXISTS (SELECT 1 FROM public.events WHERE id = v_event AND company_id = v_company)
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    IF EXISTS (SELECT 1 FROM public.ticket_office_settlements WHERE event_id = v_event AND company_id = v_company AND status = 'confirmed' AND reversed_at IS NULL)
    THEN RAISE EXCEPTION '#333: event_sealed' USING ERRCODE = 'P0001'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('de333:stmt:' || v_company::text || ':' || upper(btrim(e->>'number'))));
    IF EXISTS (SELECT 1 FROM public.ticket_office_statements WHERE company_id = v_company AND upper(btrim(number)) = upper(btrim(e->>'number')))
    THEN RAISE EXCEPTION '#333: duplicate_statement' USING ERRCODE = '23505'; END IF;
    INSERT INTO public.ticket_office_statements(company_id, financial_account_id, number, statement_date, document_total, status, created_by, notes)
    VALUES (v_company, v_office, btrim(e->>'number'), v_sdate, v_total::numeric / 100, 'draft', v_uid,
            '#333 assistente: revisão ' || a.review_id || ' v' || a.version) RETURNING id INTO v_st;
    INSERT INTO public.ticket_office_statement_lines(statement_id, company_id, line_type, position, description, amount, event_id)
    SELECT v_st, v_company, l->>'line_type', (o - 1)::int, left(l->>'description', 160), (l->>'amount_cents')::numeric / 100, v_event
    FROM jsonb_array_elements(e->'lines') WITH ORDINALITY AS z(l, o);
  ELSE
    SELECT (y.result->>'statement_id')::uuid INTO v_st FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id AND y.action_id = 'a1';
  END IF;

  IF p_action IN ('a1', 'a2') THEN
    -- Cabeçalho e linhas têm de ser EXATAMENTE os efeitos autorizados (a1: readback; a2: antes da RPC canónica, com locks).
    SELECT * INTO s FROM public.ticket_office_statements WHERE id = v_st FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    PERFORM 1 FROM public.ticket_office_statement_lines WHERE statement_id = v_st ORDER BY id FOR UPDATE;
    SELECT jsonb_agg(jsonb_build_array(l.position, l.line_type, l.description, round(l.amount * 100)::bigint, l.event_id,
             (l.company_id = v_company AND l.ticket_office_settlement_id IS NULL AND l.transaction_id IS NULL AND l.previous_statement_id IS NULL AND l.invoice_group_id IS NULL) IS TRUE)
           ORDER BY l.position, l.id)
      INTO v_act FROM public.ticket_office_statement_lines l WHERE l.statement_id = v_st;
    v_ok := s.company_id = v_company AND s.financial_account_id = v_office AND s.status = 'draft' AND s.number = btrim(e->>'number')
      AND s.statement_date = v_sdate AND round(s.document_total * 100) = v_total AND v_act = v_exp;
    IF v_ok IS NOT TRUE THEN
      RAISE EXCEPTION '#333: %', CASE WHEN p_action = 'a1' THEN 'readback_mismatch' ELSE 'data_changed' END USING ERRCODE = 'P0001'; END IF;
    IF p_action = 'a1' THEN
      res := jsonb_build_object('statement_id', v_st, 'number', btrim(e->>'number'), 'office_id', v_office, 'lines', jsonb_array_length(v_exp), 'sum_cents',
        (SELECT sum((x2->>3)::bigint) FROM jsonb_array_elements(v_exp) x2));
    ELSE
      PERFORM public.confirm_ticket_office_statement(v_st);
      IF NOT EXISTS (SELECT 1 FROM public.ticket_office_statements WHERE id = v_st AND status = 'confirmed') THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('statement_id', v_st, 'number', s.number, 'office_id', s.financial_account_id, 'status', 'confirmed');
    END IF;

  ELSIF p_action IN ('a4', 'a3') THEN
    c := e->'closing';
    IF jsonb_typeof(c) IS DISTINCT FROM 'object' OR c->>'office' IS DISTINCT FROM v_office::text OR c->>'event' IS DISTINCT FROM v_event::text
    THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    PERFORM pg_advisory_xact_lock(hashtext('de333:close:' || v_office::text || ':' || v_event::text));
    v_gross := public._de333_closing_check(c, v_company);
    IF p_action = 'a4' THEN
      res := jsonb_build_object('event_id', v_event, 'deductions', jsonb_array_length(c->'deductions'), 'deductions_cents', (c->>'deductions_cents')::bigint,
        'gross_cents', round(v_gross * 100), 'net_cents', (c->>'net_cents')::bigint, 'writes', 0);
    ELSE
      SELECT email INTO v_email FROM auth.users WHERE id = v_uid;
      v_set := (public.save_ticket_office_settlement(NULL,
        jsonb_build_object('financial_account_id', v_office, 'event_id', v_event, 'settlement_date', c->>'settlement_date',
          'gross_revenue', v_gross, 'total_deductions', (c->>'deductions_cents')::numeric / 100, 'net_calculated', (c->>'net_cents')::numeric / 100,
          'net_adjusted', null, 'net_transferred', 0, 'transfer_account_id', null, 'venue_retained_amount', 0, 'venue_retained_invoice_id', null,
          'venue_invoice_remainder_paid', false, 'venue_invoice_remainder_amount', 0,
          'notes', '#333 assistente: revisão ' || a.review_id || ' v' || a.version, 'conciliated_by', coalesce(v_email, 'system')),
        true,
        (SELECT coalesce(jsonb_agg(jsonb_build_object('id', d->>'id', 'paid_amount', (d->>'gross_cents')::numeric / 100)), '[]'::jsonb) FROM jsonb_array_elements(c->'deductions') d),
        jsonb_build_object('amount', (c->>'net_cents')::numeric / 100, 'to_account_id', c->>'transfer_account', 'credited', false),
        NULL, NULL, coalesce(v_email, v_uid::text)) ->> 'settlement_id')::uuid;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE id = v_set;
      IF NOT FOUND OR (s.status = 'confirmed' AND s.company_id = v_company AND round(s.net_transferred * 100) = (c->>'net_cents')::bigint
         AND s.transfer_account_id = (c->>'transfer_account')::uuid AND s.transfer_transaction_id IS NOT NULL
         AND round(s.total_deductions * 100) = (c->>'deductions_cents')::bigint AND round(s.net_calculated * 100) = (c->>'net_cents')::bigint) IS NOT TRUE
      THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      SELECT operation_key INTO v_key FROM public.transactions WHERE id = s.transfer_transaction_id;
      SELECT count(*) FILTER (WHERE (status = 'pending' AND paid_amount = 0 AND round(amount * 100) = (c->>'net_cents')::bigint AND company_id = v_company) IS TRUE), count(*)
        INTO v_legs, v_n FROM public.transactions WHERE operation_key = v_key;
      SELECT count(*) FILTER (WHERE (t2.settlement_id = v_set AND t2.status = 'paid' AND round(t2.paid_amount * 100) = (d->>'gross_cents')::bigint
           AND round((SELECT sum(p.amount) FROM public.transaction_payments p WHERE p.transaction_id = t2.id AND p.status = 'paid' AND p.reversed_at IS NULL) * 100) = (d->>'gross_cents')::bigint) IS NOT TRUE)
        INTO v_bad FROM jsonb_array_elements(c->'deductions') d LEFT JOIN public.transactions t2 ON t2.id = (d->>'id')::uuid;
      IF v_key IS NULL OR v_legs IS DISTINCT FROM 2 OR v_n IS DISTINCT FROM 2 OR v_bad IS DISTINCT FROM 0 THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('settlement_id', v_set, 'event_id', v_event, 'office_id', v_office, 'net_cents', (c->>'net_cents')::bigint,
        'transfer_transaction_id', s.transfer_transaction_id, 'operation_key', v_key, 'deductions', jsonb_array_length(c->'deductions'));
    END IF;

  ELSIF p_action = 'a5' THEN
    IF jsonb_typeof(e->'settlement') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
    IF (public.has_role(v_uid, 'admin') OR public.is_platform_admin(v_uid) OR public.has_permission(v_uid, 'manage_accounts')) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    v_total := public._de333_cents(e->'settlement'->'amount_cents', 1); v_amount := v_total::numeric / 100;
    v_date := public._de333_req(e->'settlement', 'date')::date; v_to := public._de333_req(e->'settlement', 'account')::uuid;
    IF (v_date > (now() AT TIME ZONE 'Europe/Lisbon')::date) IS NOT FALSE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    IF 'a3' = ANY (a.action_ids) THEN
      -- Fecho gravado por esta autorização: a referência é o plano revisto (closing) e o resultado conferido de a3.
      SELECT (y.result->>'settlement_id')::uuid INTO v_set FROM public.data_entry_assistant_executions_333 y WHERE y.authorization_id = a.id AND y.action_id = 'a3';
      IF jsonb_typeof(e->'closing') IS DISTINCT FROM 'object' OR public._de333_req(e->'closing', 'transfer_account')::uuid IS DISTINCT FROM v_to
         OR public._de333_cents(e->'closing'->'net_cents', 1) IS DISTINCT FROM v_total
      THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE id = v_set AND company_id = v_company FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    ELSE
      IF jsonb_typeof(e->'canonical') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
      SELECT * INTO s FROM public.ticket_office_settlements WHERE event_id = v_event AND company_id = v_company AND status = 'confirmed' AND reversed_at IS NULL FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
      IF (s.transfer_account_id = public._de333_req(e->'canonical', 'transfer_account_id')::uuid
          AND round(s.net_transferred * 100) = public._de333_cents(e->'canonical'->'net_transferred_cents', 1)) IS NOT TRUE
      THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    END IF;
    IF (s.status = 'confirmed' AND s.reversed_at IS NULL AND s.transfer_transaction_id IS NOT NULL AND s.event_id = v_event AND s.company_id = v_company
        AND s.financial_account_id = v_office AND s.transfer_account_id = v_to AND round(s.net_transferred * 100) = v_total AND v_date >= s.settlement_date) IS NOT TRUE
    THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    -- Contas ativas da empresa NO MOMENTO (bilheteira e conta de destino).
    IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = s.financial_account_id AND company_id = v_company AND type = 'ticket_office' AND is_active IS TRUE)
       OR NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_to AND company_id = v_company AND is_active IS TRUE AND type IN ('bank','cash','venue'))
    THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    SELECT * INTO t FROM public.transactions WHERE id = s.transfer_transaction_id AND company_id = v_company;
    IF NOT FOUND OR (t.operation_key LIKE 'TRF-FECHO-%') IS NOT TRUE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    v_key := t.operation_key;
    PERFORM 1 FROM public.transactions WHERE operation_key = v_key ORDER BY id FOR UPDATE;
    PERFORM 1 FROM public.transaction_payments p JOIN public.transactions x0 ON x0.id = p.transaction_id WHERE x0.operation_key = v_key ORDER BY p.id FOR UPDATE OF p;
    -- Integridade do par TRF-FECHO (create_settlement_transfer), fail-closed: qualquer campo NULL/diferente conta como inválido.
    SELECT count(*), count(*) FILTER (WHERE (
      x2.company_id = v_company AND x2.event_id = s.event_id AND x2.amount = v_amount AND x2.iva_rate = 0 AND x2.reversed_at IS NULL
      AND x2.exclude_from_result AND x2.payment_method = 'transfer' AND x2.currency = 'EUR'
      AND ((x2.type = 'expense' AND x2.id = s.transfer_transaction_id AND x2.account_id = s.financial_account_id AND x2.settlement_id = s.id)
        OR (x2.type = 'income' AND x2.id <> s.transfer_transaction_id AND x2.account_id = s.transfer_account_id AND x2.settlement_id IS NULL))) IS NOT TRUE)
      INTO v_legs, v_bad FROM public.transactions x2 WHERE x2.operation_key = v_key;
    IF v_legs IS DISTINCT FROM 2 OR v_bad IS DISTINCT FROM 0 OR (SELECT count(DISTINCT type) FROM public.transactions WHERE operation_key = v_key) IS DISTINCT FROM 2
    THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    -- Por perna: liquidada EXATAMENTE como a evidência (1 pagamento, pago, valor, data, conta da perna, empresa, transferência, sem estorno)
    -- vs. limpa (pendente, 0 pago, sem pagamentos). Qualquer outro estado (pago com data/conta/valor divergente, estorno, planeado) não se adivinha.
    SELECT count(*) FILTER (WHERE (x3.status = 'paid' AND x3.paid_amount = v_amount AND x3.payment_date = v_date
             AND (SELECT count(*) FROM public.transaction_payments p WHERE p.transaction_id = x3.id) = 1
             AND EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x3.id AND p.status = 'paid' AND p.amount = v_amount
               AND p.payment_date = v_date AND p.account_id = x3.account_id AND p.company_id = v_company AND p.payment_method = 'transfer' AND p.reversed_at IS NULL)) IS TRUE),
           count(*) FILTER (WHERE (x3.status IN ('pending','approved') AND x3.paid_amount = 0 AND x3.payment_date IS NULL
             AND NOT EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x3.id)) IS TRUE),
           count(*) FILTER (WHERE x3.status IS NOT DISTINCT FROM 'paid')
      INTO v_paid, v_n, v_div FROM public.transactions x3 WHERE x3.operation_key = v_key;
    IF v_paid = 2 THEN
      res := jsonb_build_object('settlement_id', s.id, 'transfer_transaction_id', t.id, 'operation_key', v_key, 'already_liquidated', true, 'writes', 0,
        'payment_date', v_date, 'amount_cents', v_total);
    ELSIF v_n = 2 THEN
      UPDATE public.transactions SET status = 'paid', payment_date = v_date, paid_amount = amount WHERE operation_key = v_key;
      SELECT count(*) FILTER (WHERE (x4.status = 'paid' AND x4.paid_amount = v_amount AND x4.payment_date = v_date
        AND (SELECT count(*) FROM public.transaction_payments p WHERE p.transaction_id = x4.id) = 1
        AND EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id = x4.id AND p.status = 'paid' AND p.amount = v_amount
          AND p.payment_date = v_date AND p.account_id = x4.account_id AND p.company_id = v_company AND p.payment_method = 'transfer' AND p.reversed_at IS NULL)) IS NOT TRUE), count(*)
        INTO v_bad, v_legs FROM public.transactions x4 WHERE x4.operation_key = v_key;
      IF v_bad IS DISTINCT FROM 0 OR v_legs IS DISTINCT FROM 2 THEN RAISE EXCEPTION '#333: readback_mismatch' USING ERRCODE = 'P0001'; END IF;
      res := jsonb_build_object('settlement_id', s.id, 'transfer_transaction_id', t.id, 'operation_key', v_key, 'already_liquidated', false,
        'payment_date', v_date, 'amount_cents', v_total, 'writes', 2, 'payments', 2);
    ELSIF v_div = 2 THEN
      -- Crédito preexistente que NÃO corresponde à evidência autorizada: nunca se atribui como sucesso.
      RAISE EXCEPTION '#333: liquidated_divergent' USING ERRCODE = 'P0001';
    ELSE
      RAISE EXCEPTION '#333: partial_state_manual' USING ERRCODE = 'P0001';
    END IF;
  ELSE RAISE EXCEPTION '#333: action_not_authorized' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.data_entry_assistant_executions_333(authorization_id, action_id, owner_id, company_id, effects_hash, result)
  VALUES (a.id, p_action, v_uid, v_company, a.effects_hash, res) RETURNING * INTO ex;
  RETURN jsonb_build_object('action_id', p_action, 'status', ex.status, 'replayed', false, 'result', ex.result);
END $function$

CREATE OR REPLACE FUNCTION public.resolve_ads_event(p_company_id uuid, p_campaign_name text, p_billing_period date)
 RETURNS TABLE(event_id uuid, match_source text, note text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'crm', 'pg_temp'
AS $function$
DECLARE
  v_name  text := public.ads_norm_text(p_campaign_name);
  v_start date := date_trunc('month', p_billing_period)::date;
  v_end   date := (date_trunc('month', p_billing_period) + interval '1 month - 1 day')::date;
  v_locked uuid;
  v_roots  int;
  v_root   uuid;
  v_level  text;
  v_kids   int;
  v_child  uuid;
  v_link   uuid;
  v_link_level text;
  v_note2  text;
BEGIN
  IF v_name = '' THEN
    RETURN QUERY SELECT NULL::uuid, 'none'::text, 'sem correspondência'::text; RETURN;
  END IF;

  SELECT s.linked_event_id INTO v_locked
    FROM crm.meta_campaign_snapshot s
   WHERE s.company_id = p_company_id
     AND s.linked_event_locked IS TRUE
     AND s.linked_event_id IS NOT NULL
     AND public.ads_norm_text(s.name) = v_name
   LIMIT 1;
  IF v_locked IS NOT NULL THEN
    RETURN QUERY SELECT v_locked, 'erp_link'::text, 'vínculo trancado'::text; RETURN;
  END IF;

  -- Famílias com venda aberta no período. O reconhecimento é feito SÓ pelo nome
  -- e aliases do evento-mãe: os nomes dos filhos são cidades e apanhavam
  -- campanhas de outras turnês na mesma cidade.
  WITH w AS (SELECT * FROM public.ads_event_windows(p_company_id)),
  roots AS (
    SELECT DISTINCT coalesce(e.parent_event_id, e.id) AS root
      FROM public.events e
      JOIN w ON w.event_id = e.id
     WHERE e.company_id = p_company_id
       AND e.status = 'active'
       AND w.win_start IS NOT NULL
       AND w.win_start <= v_end
       AND w.win_end   >= v_start
  ),
  cand AS (
    SELECT r.root
      FROM roots r
      JOIN public.events p ON p.id = r.root
     WHERE (
        EXISTS (
          SELECT 1 FROM regexp_split_to_table(public.ads_norm_text(p.name), '[^a-z0-9]+') AS tok
           WHERE length(tok) >= 4 AND tok ~ '^[a-z]+$'
             AND v_name ~ ('(^|[^a-z0-9])' || tok || '([^a-z0-9]|$)')
        )
        OR EXISTS (
          SELECT 1 FROM unnest(p.ads_match_aliases) AS a
           WHERE public.ads_norm_text(a) <> ''
             AND v_name ~ ('(^|[^a-z0-9])'
                   || regexp_replace(public.ads_norm_text(a), '([^a-z0-9 ])', '\\\1', 'g')
                   || '([^a-z0-9]|$)')
        )
      )
  )
  SELECT count(*)::int, min(root::text)::uuid INTO v_roots, v_root FROM cand;

  IF v_roots = 1 THEN
    SELECT e.ads_allocation_level INTO v_level FROM public.events e WHERE e.id = v_root;

    IF v_level = 'externo' THEN
      RETURN QUERY SELECT NULL::uuid, 'none'::text, 'evento com tráfego externo'::text; RETURN;
    END IF;

    IF v_level = 'cidade' THEN
      WITH w AS (SELECT * FROM public.ads_event_windows(p_company_id))
      SELECT count(*)::int, min(e.id::text)::uuid INTO v_kids, v_child
        FROM public.events e
        JOIN w ON w.event_id = e.id
        JOIN public.cities c ON c.id = e.city_id
       WHERE e.parent_event_id = v_root
         AND e.status = 'active'
         AND w.win_start IS NOT NULL
         AND w.win_start <= v_end
         AND w.win_end   >= v_start
         AND v_name ~ ('(^|[^a-z0-9])'
               || regexp_replace(public.ads_norm_text(c.name), '([^a-z0-9 ])', '\\\1', 'g')
               || '([^a-z0-9]|$)');
      IF v_kids = 1 THEN
        RETURN QUERY SELECT v_child, 'regra'::text, NULL::text; RETURN;
      END IF;
      RETURN QUERY SELECT v_root, 'regra'::text, 'sem cidade identificada, lançado na tour'::text; RETURN;
    END IF;

    RETURN QUERY SELECT v_root, 'regra'::text, NULL::text; RETURN;
  END IF;

  v_note2 := CASE WHEN coalesce(v_roots,0) = 0
                  THEN 'sem candidato: nenhum evento à venda no período casa com o nome'
                  ELSE 'vários candidatos: nome casa com mais do que uma família' END;

  SELECT s.linked_event_id INTO v_link
    FROM crm.meta_campaign_snapshot s
   WHERE s.company_id = p_company_id
     AND s.linked_event_id IS NOT NULL
     AND public.ads_norm_text(s.name) = v_name
   LIMIT 1;

  IF v_link IS NOT NULL THEN
    SELECT coalesce(p.ads_allocation_level, e.ads_allocation_level) INTO v_link_level
      FROM public.events e
      LEFT JOIN public.events p ON p.id = e.parent_event_id
     WHERE e.id = v_link;
    IF v_link_level = 'externo' THEN
      RETURN QUERY SELECT NULL::uuid, 'none'::text, 'evento com tráfego externo'::text; RETURN;
    END IF;
    RETURN QUERY SELECT v_link, 'erp_link'::text, 'vínculo do ERP, sem regra'::text; RETURN;
  END IF;

  RETURN QUERY SELECT NULL::uuid, 'none'::text, v_note2; RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_tiktok_consume_oauth_state(p_state_id uuid)
 RETURNS TABLE(company_id uuid, user_id uuid, connection_id uuid, valid boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE v crm.oauth_states%ROWTYPE;
BEGIN
  SELECT * INTO v FROM crm.oauth_states s WHERE s.id = p_state_id AND s.platform = 'tiktok' AND s.expires_at > now();
  IF NOT FOUND THEN RETURN QUERY SELECT NULL::uuid, NULL::uuid, NULL::uuid, false; RETURN; END IF;
  DELETE FROM crm.oauth_states s WHERE s.id = p_state_id;
  RETURN QUERY SELECT v.company_id, v.user_id, v.connection_id, true;
END $function$

CREATE OR REPLACE FUNCTION public._cache_alloc(p_total numeric, p_weights numeric[], p_absorber integer)
 RETURNS numeric[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_sum numeric := 0; v_acc numeric := 0; v_out numeric[] := '{}'; i int;
BEGIN
  FOR i IN 1..coalesce(array_length(p_weights,1),0) LOOP v_sum := v_sum + p_weights[i]; END LOOP;
  IF v_sum <= 0 THEN RAISE EXCEPTION 'cache_alloc: pesos inválidos'; END IF;
  FOR i IN 1..array_length(p_weights,1) LOOP
    IF i = p_absorber THEN v_out := v_out || 0::numeric;
    ELSE v_out := v_out || round(p_total * p_weights[i] / v_sum, 2); v_acc := v_acc + round(p_total * p_weights[i] / v_sum, 2);
    END IF;
  END LOOP;
  v_out[p_absorber] := round(p_total,2) - v_acc;
  RETURN v_out;
END $function$

CREATE OR REPLACE FUNCTION public._cache_assert_actor()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT (
    public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'manager'::app_role)
    OR public.has_permission(v_uid, 'manage_transactions')
  ) THEN
    RAISE EXCEPTION 'permission_denied: sem permissão para lançar pagamentos de cachê' USING ERRCODE = '42501';
  END IF;
  RETURN v_uid;
END $function$

CREATE OR REPLACE FUNCTION public._cache_cancel_contract(p_uid uuid, p_contract uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_c public.cache_payment_contracts%ROWTYPE; m record; v_tx record; v_by text;
  v_roots uuid[]; v_children uuid[]; v_all uuid[]; v_fcs uuid[]; f record; v_next uuid;
BEGIN
  SELECT * INTO v_c FROM public.cache_payment_contracts WHERE id = p_contract FOR UPDATE;
  IF NOT FOUND OR v_c.company_id <> public.current_company_id() THEN RAISE EXCEPTION 'contrato_inexistente'; END IF;
  IF v_c.cancelled_at IS NOT NULL THEN RAISE EXCEPTION 'contrato_ja_cancelado'; END IF;
  PERFORM 1 FROM public.transactions WHERE id IN (v_c.artist_mother_id, v_c.withholding_mother_id) FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.transactions t WHERE t.id IN (v_c.artist_mother_id, v_c.withholding_mother_id)
               AND (t.paid_amount > 0 OR t.status = 'paid'))
     OR EXISTS (SELECT 1 FROM public.transaction_payments p WHERE p.transaction_id IN (v_c.artist_mother_id, v_c.withholding_mother_id))
     OR EXISTS (SELECT 1 FROM public.payment_list_items li JOIN public.payment_lists pl ON pl.id = li.payment_list_id
                 WHERE li.transaction_id IN (v_c.artist_mother_id, v_c.withholding_mother_id) AND li.removed_at IS NULL
                   AND pl.status IN ('approved','partially_approved'))
  THEN
    RAISE EXCEPTION 'contrato_com_pagamento: já há pagamento ou lista aprovada; estorne primeiro pelos fluxos normais';
  END IF;
  SELECT coalesce(email, id::text) INTO v_by FROM auth.users WHERE id = p_uid;

  SELECT coalesce(array_agg(id), '{}') INTO v_roots FROM public.transactions
   WHERE id IN (v_c.artist_mother_id, v_c.withholding_mother_id);
  PERFORM 1 FROM public.transactions WHERE parent_transaction_id = ANY(v_roots) FOR UPDATE;
  SELECT coalesce(array_agg(id), '{}') INTO v_children FROM public.transactions
   WHERE parent_transaction_id = ANY(v_roots) AND NOT (id = ANY(v_roots));
  v_all := v_roots || v_children;

  -- Lixo: uma entrada por mãe, com as próprias filhas (sem duplicar).
  FOR m IN SELECT t.* FROM public.transactions t WHERE t.id = ANY(v_roots) LOOP
    INSERT INTO public.trash(entity_type, entity_id, entity_data, related_data, deleted_by, company_id)
    VALUES ('transaction', m.id, to_jsonb(m) - 'updated_at',
            jsonb_build_object('transactions', (SELECT coalesce(jsonb_agg(to_jsonb(c) - 'updated_at'), '[]'::jsonb)
                                                  FROM public.transactions c WHERE c.parent_transaction_id = m.id)),
            coalesce(v_by,'sistema'), v_c.company_id);
  END LOOP;

  -- Dependências: mesmo tratamento de delete_transaction_cascade.
  SELECT coalesce(array_agg(id), '{}') INTO v_fcs FROM public.event_forecasts
   WHERE transaction_id = ANY(v_all) AND version_id IS NULL;
  UPDATE public.event_forecasts SET transaction_id = NULL WHERE transaction_id = ANY(v_all) AND version_id IS NULL;
  UPDATE public.event_cache_payments SET transaction_id = NULL WHERE transaction_id = ANY(v_all);
  UPDATE public.event_cache_payments SET withholding_transaction_id = NULL WHERE withholding_transaction_id = ANY(v_all);
  UPDATE public.ticket_office_settlements SET transfer_transaction_id = NULL WHERE transfer_transaction_id = ANY(v_all);
  UPDATE public.reimbursement_notes SET payment_transaction_id = NULL WHERE payment_transaction_id = ANY(v_all);
  DELETE FROM public.payment_list_items WHERE transaction_id = ANY(v_all);
  DELETE FROM public.reimbursement_note_items WHERE transaction_id = ANY(v_all);
  DELETE FROM public.partner_paid_expenses WHERE transaction_id = ANY(v_all);
  DELETE FROM public.partner_advance_expenses WHERE transaction_id = ANY(v_all);
  DELETE FROM public.supplier_credit_usages WHERE transaction_id = ANY(v_all);
  DELETE FROM public.transaction_payments WHERE transaction_id = ANY(v_all);
  DELETE FROM public.transaction_documents WHERE transaction_id = ANY(v_all);

  FOR v_tx IN SELECT * FROM public.transactions WHERE id = ANY(v_all) LOOP
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, metadata, company_id)
    VALUES ('transaction', v_tx.id::text, 'delete', coalesce(v_by, p_uid::text), to_jsonb(v_tx),
            jsonb_build_object('reason', coalesce(p_reason, 'cancelar contrato de cachê'), 'root', v_tx.id = ANY(v_roots),
                               'rpc', '_cache_cancel_contract', 'cache_contract_id', p_contract),
            v_tx.company_id);
  END LOOP;

  DELETE FROM public.transactions WHERE id = ANY(v_children);
  DELETE FROM public.transactions WHERE id = ANY(v_roots);

  UPDATE public.transactions SET cache_contract_id = NULL
   WHERE cache_contract_id = p_contract AND cache_role = 'advance';
  UPDATE public.cache_payment_contracts SET cancelled_at = now(), cancelled_by = p_uid, cancel_reason = p_reason,
         artist_mother_id = NULL, withholding_mother_id = NULL
   WHERE id = p_contract;

  -- Re-âncora: próxima transação existente na linha (regra de sync_tx_forecast_to_anchor), ou NULL.
  FOR f IN SELECT id, event_id, company_id FROM public.event_forecasts WHERE id = ANY(v_fcs) AND version_id IS NULL FOR UPDATE LOOP
    SELECT t.id INTO v_next FROM public.transactions t
     WHERE t.forecast_id = f.id AND public.bp_tx_link_allowed(t.event_id, t.company_id, f.event_id, f.company_id)
     ORDER BY t.date, t.created_at, t.id LIMIT 1;
    UPDATE public.event_forecasts SET transaction_id = v_next WHERE id = f.id AND transaction_id IS NULL;
    v_next := NULL;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._cache_create_contract(p_uid uuid, p_root uuid, p_artist uuid, p_beneficiary uuid, p_gross numeric, p_wh_applies boolean, p_wh_rate numeric, p_wh_due date, p_artist_due date, p_advance_ids uuid[], p_label text, p_key text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company uuid := public.current_company_id();
  v_cat uuid; v_at uuid; v_cid uuid; v_n int; v_absorber int;
  v_ids uuid[]; v_events uuid[]; v_names text[]; v_lines uuid[]; v_caps numeric[]; v_abs boolean[];
  v_total_cap numeric := 0; v_used numeric; v_free_other numeric;
  v_quota numeric[]; v_wh numeric[]; v_adv numeric[]; v_art numeric[];
  v_W numeric := 0; v_sum_art numeric := 0; v_sum_adv numeric := 0;
  v_mother uuid; v_wh_mother uuid; v_pct numeric; v_acc numeric; v_first_idx int;
  v_desc_artist text; v_artist_name text; v_contract_no int;
  r record; i int; v_city_other numeric; v_city_free numeric; v_today date := (now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
  IF p_key IS NOT NULL THEN
    SELECT id INTO v_cid FROM public.cache_payment_contracts WHERE company_id = v_company AND idempotency_key = p_key;
    IF FOUND THEN RETURN v_cid; END IF;
  END IF;
  IF p_wh_applies IS NULL THEN RAISE EXCEPTION 'retencao_sem_resposta: responda Sim ou Não à retenção IRS'; END IF;
  IF p_wh_applies AND (p_wh_rate IS NULL OR p_wh_rate <= 0 OR p_wh_rate >= 100) THEN RAISE EXCEPTION 'taxa_invalida: taxa de retenção inválida'; END IF;
  IF p_wh_applies AND p_wh_due IS NULL THEN RAISE EXCEPTION 'vencimento_retencao_obrigatorio: indique o vencimento da retenção'; END IF;
  IF p_gross IS NULL OR p_gross <= 0 OR p_gross <> round(p_gross,2) THEN RAISE EXCEPTION 'bruto_invalido: valor bruto inválido'; END IF;
  IF p_beneficiary IS NULL OR NOT EXISTS (SELECT 1 FROM public.suppliers WHERE id = p_beneficiary AND company_id = v_company) THEN
    RAISE EXCEPTION 'beneficiario_invalido: escolha o beneficiário desta empresa';
  END IF;

  SELECT count(*) INTO v_n FROM public.cache_payment_contracts
   WHERE root_event_id = p_root AND artist_supplier_id = p_artist AND cancelled_at IS NULL;
  IF v_n >= public.cache_max_contracts() THEN
    RAISE EXCEPTION 'limite_contratos: máximo de % contratos por cachê', public.cache_max_contracts();
  END IF;
  v_contract_no := v_n + 1;

  v_cat := public._cache_category(v_company);
  IF v_cat IS NULL THEN RAISE EXCEPTION 'categoria_em_falta: rubrica 2.1.01 não existe nesta empresa'; END IF;
  SELECT name INTO v_artist_name FROM public.suppliers WHERE id = p_artist;

  SELECT array_agg(event_id ORDER BY idx), array_agg(event_name ORDER BY idx), array_agg(forecast_id ORDER BY idx),
         array_agg(cap ORDER BY idx), array_agg(is_absorber ORDER BY idx)
    INTO v_events, v_names, v_lines, v_caps, v_abs
    FROM public._cache_cities(p_root, p_artist);
  IF v_events IS NULL THEN RAISE EXCEPTION 'sem_linha_cache: não há linha do cachê no BP das cidades; sincronize o cachê primeiro'; END IF;
  IF (SELECT count(DISTINCT e) FROM unnest(v_events) e) <> array_length(v_events,1) THEN
    RAISE EXCEPTION 'linha_cache_duplicada: uma cidade tem mais de uma linha do cachê deste artista';
  END IF;
  v_n := array_length(v_events,1);
  FOR i IN 1..v_n LOOP v_total_cap := v_total_cap + v_caps[i]; IF v_abs[i] THEN v_absorber := i; END IF; END LOOP;
  IF v_total_cap <= 0 THEN RAISE EXCEPTION 'cache_sem_valor: cachê efetivo é zero'; END IF;

  v_ids := coalesce((SELECT array_agg(DISTINCT x) FROM unnest(p_advance_ids) x), '{}');
  v_adv := array_fill(0::numeric, ARRAY[v_n]);
  FOR r IN SELECT t.* FROM public.transactions t WHERE t.id = ANY(v_ids) ORDER BY t.id FOR UPDATE LOOP NULL; END LOOP;
  IF (SELECT count(*) FROM public.transactions t WHERE t.id = ANY(v_ids)) <> coalesce(array_length(v_ids,1),0) THEN
    RAISE EXCEPTION 'adiantamento_inexistente';
  END IF;
  IF EXISTS (SELECT 1 FROM public.transactions t WHERE t.id = ANY(v_ids) AND t.cache_contract_id IS NOT NULL) THEN
    RAISE EXCEPTION 'adiantamento_ja_associado: um adiantamento já pertence a outro contrato';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_ids) x WHERE x NOT IN (SELECT tx_id FROM public._cache_free_advances(p_root, p_artist))) THEN
    RAISE EXCEPTION 'adiantamento_invalido: só adiantamentos livres do cachê nas cidades (não lançados no Master)';
  END IF;
  FOR r IN SELECT fa.event_id, sum(fa.amount) AS amt FROM public._cache_free_advances(p_root, p_artist) fa
            WHERE fa.tx_id = ANY(v_ids) GROUP BY fa.event_id LOOP
    i := array_position(v_events, r.event_id);
    v_adv[i] := v_adv[i] + r.amt; v_sum_adv := v_sum_adv + r.amt;
  END LOOP;

  SELECT coalesce(sum(gross),0) INTO v_used FROM public.cache_payment_contracts
   WHERE root_event_id = p_root AND artist_supplier_id = p_artist AND cancelled_at IS NULL;
  SELECT coalesce(sum(amount),0) INTO v_free_other FROM public._cache_free_advances(p_root, p_artist) WHERE NOT (tx_id = ANY(v_ids));
  IF p_gross + v_used + v_free_other > v_total_cap + 0.005 THEN
    RAISE EXCEPTION 'teto_excedido: bruto % excede o restante por contratar % (cachê efetivo %)',
      p_gross, v_total_cap - v_used - v_free_other, v_total_cap;
  END IF;

  v_quota := public._cache_alloc(p_gross, v_caps, v_absorber);
  IF p_wh_applies THEN
    v_W := round(p_gross * p_wh_rate / 100, 2);
    v_wh := public._cache_alloc(v_W, v_caps, v_absorber);
  ELSE
    v_wh := array_fill(0::numeric, ARRAY[v_n]);
  END IF;
  v_art := array_fill(0::numeric, ARRAY[v_n]);
  FOR i IN 1..v_n LOOP
    v_art[i] := v_quota[i] - v_wh[i] - v_adv[i];
    IF v_art[i] < 0 THEN
      RAISE EXCEPTION 'saldo_negativo: em % os adiantamentos (%) excedem a quota líquida (%) — saldo %',
        v_names[i], v_adv[i], v_quota[i] - v_wh[i], v_art[i];
    END IF;
    SELECT coalesce(sum(cc.quota),0) INTO v_city_other FROM public.cache_payment_contract_cities cc
      JOIN public.cache_payment_contracts k ON k.id = cc.contract_id
     WHERE k.root_event_id = p_root AND k.artist_supplier_id = p_artist AND k.cancelled_at IS NULL AND cc.event_id = v_events[i];
    SELECT coalesce(sum(amount),0) INTO v_city_free FROM public._cache_free_advances(p_root, p_artist)
     WHERE event_id = v_events[i] AND NOT (tx_id = ANY(v_ids));
    IF v_city_other + v_quota[i] + v_city_free > v_caps[i] + 0.005 THEN
      RAISE EXCEPTION 'teto_cidade_excedido: % ficaria com % acima do cachê da cidade %', v_names[i], v_city_other + v_quota[i] + v_city_free, v_caps[i];
    END IF;
    v_sum_art := v_sum_art + v_art[i];
  END LOOP;

  INSERT INTO public.cache_payment_contracts(company_id, root_event_id, artist_supplier_id, beneficiary_supplier_id, label, gross,
      withholding_applies, withholding_rate, withholding_amount, withholding_due_date, artist_due_date, advances_amount, idempotency_key, created_by)
  VALUES (v_company, p_root, p_artist, p_beneficiary, nullif(trim(p_label),''), p_gross,
      p_wh_applies, CASE WHEN p_wh_applies THEN p_wh_rate END, v_W, p_wh_due, p_artist_due, v_sum_adv, p_key, p_uid)
  RETURNING id INTO v_cid;

  FOR i IN 1..v_n LOOP
    INSERT INTO public.cache_payment_contract_cities(contract_id, company_id, event_id, forecast_id, cap, quota, withholding, advances, artist_balance, is_absorber)
    VALUES (v_cid, v_company, v_events[i], v_lines[i], v_caps[i], v_quota[i], v_wh[i], v_adv[i], v_art[i], i = v_absorber);
  END LOOP;

  v_desc_artist := 'Cachê ' || coalesce(v_artist_name,'') || ' — contrato ' || v_contract_no || coalesce(' (' || nullif(trim(p_label),'') || ')','');

  IF v_sum_art > 0 THEN
    INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        date, due_date, status, paid_amount, split_mode, company_id, cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
    VALUES (v_desc_artist || ' — saldo', 'expense', v_sum_art, 0, NULL, v_cat, NULL, p_beneficiary, NULL,
        v_today, p_artist_due, 'approved', 0, 'percentage', v_company, v_cid, 'artist_balance', p_root, p_artist)
    RETURNING id INTO v_mother;
    v_acc := 0; v_first_idx := NULL;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        IF v_first_idx IS NULL OR v_art[i] > v_art[v_first_idx] THEN v_first_idx := i; END IF;
      END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        v_pct := CASE WHEN i = v_first_idx THEN NULL ELSE round(v_art[i] / v_sum_art * 100, 4) END;
        IF v_pct IS NOT NULL THEN v_acc := v_acc + v_pct; END IF;
      END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_art[i] > 0 THEN
        INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
            date, due_date, status, paid_amount, parent_transaction_id, split_percentage, split_mode, company_id,
            cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
        VALUES (v_desc_artist || ' — saldo', 'expense', v_art[i], 0, v_events[i], v_cat, v_lines[i], p_beneficiary, NULL,
            v_today, p_artist_due, 'approved', 0, v_mother,
            CASE WHEN i = v_first_idx THEN 100 - v_acc ELSE round(v_art[i] / v_sum_art * 100, 4) END,
            'percentage', v_company, v_cid, 'artist_balance', p_root, p_artist);
      END IF;
    END LOOP;
  END IF;

  IF p_wh_applies AND v_W > 0 THEN
    SELECT id INTO v_at FROM public.suppliers WHERE company_id = v_company AND name = 'MINISTERIO DAS FINANCAS - IRS' LIMIT 1;
    IF v_at IS NULL THEN RAISE EXCEPTION 'fornecedor_at_em_falta: crie o fornecedor MINISTERIO DAS FINANCAS - IRS nesta empresa'; END IF;
    INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
        date, due_date, status, paid_amount, split_mode, company_id, cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
    VALUES ('Retenção IRS ' || p_wh_rate || '% — ' || v_desc_artist, 'expense', v_W, 0, NULL, v_cat, NULL, v_at, NULL,
        v_today, p_wh_due, 'approved', 0, 'percentage', v_company, v_cid, 'withholding', p_root, p_artist)
    RETURNING id INTO v_wh_mother;
    v_acc := 0;
    FOR i IN 1..v_n LOOP
      IF v_wh[i] > 0 AND i <> v_absorber THEN v_acc := v_acc + round(v_wh[i] / v_W * 100, 4); END IF;
    END LOOP;
    FOR i IN 1..v_n LOOP
      IF v_wh[i] > 0 THEN
        INSERT INTO public.transactions(description, type, amount, iva_rate, event_id, category_id, forecast_id, supplier_id, account_id,
            date, due_date, status, paid_amount, parent_transaction_id, split_percentage, split_mode, company_id,
            cache_contract_id, cache_role, cache_root_event_id, cache_artist_supplier_id)
        VALUES ('Retenção IRS ' || p_wh_rate || '% — ' || v_desc_artist, 'expense', v_wh[i], 0, v_events[i], v_cat, v_lines[i], v_at, NULL,
            v_today, p_wh_due, 'approved', 0, v_wh_mother,
            CASE WHEN i = v_absorber THEN 100 - v_acc ELSE round(v_wh[i] / v_W * 100, 4) END,
            'percentage', v_company, v_cid, 'withholding', p_root, p_artist);
      END IF;
    END LOOP;
  END IF;

  UPDATE public.cache_payment_contracts SET artist_mother_id = v_mother, withholding_mother_id = v_wh_mother WHERE id = v_cid;

  IF array_length(v_ids,1) > 0 THEN
    UPDATE public.transactions SET cache_contract_id = v_cid, cache_role = 'advance',
           cache_root_event_id = p_root, cache_artist_supplier_id = p_artist
     WHERE id = ANY(v_ids) OR parent_transaction_id = ANY(v_ids);
  END IF;
  RETURN v_cid;
END $function$

CREATE OR REPLACE FUNCTION public._cache_resolve_lines(p_root uuid, p_artist uuid, p_choices jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(event_id uuid, event_name text, event_date date, forecast_id uuid, cap numeric, source text, cache_config_id uuid, frozen boolean, candidates jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_company uuid; v_cat uuid; c record; r record; n int; v_raw text; v_choice uuid; v_cand uuid[]; v_pick uuid;
BEGIN
  SELECT e.company_id INTO v_company FROM public.events e WHERE e.id = p_root;
  v_cat := public._cache_category(v_company);
  IF p_choices IS NOT NULL AND jsonb_typeof(p_choices) <> 'object' THEN
    RAISE EXCEPTION 'linha_cache_invalida: escolha de linhas inválida';
  END IF;
  IF p_choices IS NOT NULL AND EXISTS (
       SELECT 1 FROM jsonb_object_keys(p_choices) k
        WHERE k NOT IN (SELECT e.id::text FROM public.events e WHERE e.parent_event_id = p_root
                        UNION ALL SELECT p_root::text WHERE NOT EXISTS (SELECT 1 FROM public.events x WHERE x.parent_event_id = p_root))) THEN
    RAISE EXCEPTION 'linha_cache_invalida: a linha escolhida não pertence a uma cidade deste cachê';
  END IF;
  FOR c IN
    SELECT e.id, e.name, e.date FROM public.events e WHERE e.parent_event_id = p_root
    UNION ALL
    SELECT e.id, e.name, e.date FROM public.events e
     WHERE e.id = p_root AND NOT EXISTS (SELECT 1 FROM public.events x WHERE x.parent_event_id = p_root)
  LOOP
    v_raw := CASE WHEN p_choices IS NULL THEN NULL ELSE nullif(p_choices ->> c.id::text, '') END;
    IF v_raw IS NOT NULL AND v_raw !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'linha_cache_invalida: linha escolhida inválida em %', c.name;
    END IF;
    v_choice := v_raw::uuid;
    n := 0;
    FOR r IN
      SELECT f.id, f.amount, cc.id AS cfg, coalesce(s.is_finalized, cc.is_finalized, false) AS fz
        FROM public.event_forecasts f
        JOIN public.event_cache_configs cc ON cc.id = f.cache_config_id AND cc.supplier_id = p_artist
        LEFT JOIN public.event_cache_city_settlements s ON s.cache_config_id = cc.id AND s.event_id = c.id
       WHERE f.event_id = c.id AND f.formula_type = 'cache_module' AND f.version_id IS NULL
    LOOP
      n := n + 1;
      IF v_choice IS NOT NULL AND v_choice <> r.id THEN
        RAISE EXCEPTION 'linha_cache_invalida: % já tem a linha do cachê configurado', c.name;
      END IF;
      event_id := c.id; event_name := c.name; event_date := c.date; forecast_id := r.id; cap := round(r.amount, 2);
      source := 'config'; cache_config_id := r.cfg; frozen := r.fz; candidates := NULL;
      RETURN NEXT;
    END LOOP;
    CONTINUE WHEN n > 0;

    SELECT array_agg(f.id ORDER BY f.amount DESC, f.id) INTO v_cand
      FROM public.event_forecasts f
     WHERE f.event_id = c.id AND f.category_id = v_cat AND f.version_id IS NULL AND f.cache_config_id IS NULL;
    IF v_cand IS NULL THEN
      IF v_choice IS NOT NULL THEN RAISE EXCEPTION 'linha_cache_invalida: a linha escolhida não é de cachê (2.1.01) ativa em %', c.name; END IF;
      CONTINUE;
    END IF;
    v_pick := NULL;
    IF v_choice IS NOT NULL THEN
      IF NOT (v_choice = ANY (v_cand)) THEN
        RAISE EXCEPTION 'linha_cache_invalida: a linha escolhida não é de cachê (2.1.01) ativa em %', c.name;
      END IF;
      v_pick := v_choice;
    ELSE
      SELECT pc.forecast_id INTO v_pick FROM public.cache_payment_contract_cities pc
        JOIN public.cache_payment_contracts k ON k.id = pc.contract_id
       WHERE k.root_event_id = p_root AND k.artist_supplier_id = p_artist AND k.cancelled_at IS NULL
         AND pc.event_id = c.id AND pc.forecast_id = ANY (v_cand) LIMIT 1;
      IF v_pick IS NULL THEN
        SELECT t.forecast_id INTO v_pick FROM public.transactions t
         WHERE t.cache_role = 'advance' AND t.parent_transaction_id IS NOT NULL AND t.reversed_at IS NULL
           AND t.cache_root_event_id = p_root AND t.cache_artist_supplier_id = p_artist
           AND t.event_id = c.id AND t.forecast_id = ANY (v_cand) LIMIT 1;
      END IF;
      IF v_pick IS NULL AND array_length(v_cand, 1) = 1 THEN v_pick := v_cand[1]; END IF;
    END IF;
    event_id := c.id; event_name := c.name; event_date := c.date; forecast_id := v_pick;
    cap := (SELECT round(f.amount, 2) FROM public.event_forecasts f WHERE f.id = v_pick);
    source := 'bp'; cache_config_id := NULL; frozen := false;
    candidates := CASE WHEN v_pick IS NULL THEN
      (SELECT jsonb_agg(jsonb_build_object('forecast_id', f.id, 'description', f.description, 'amount', f.amount) ORDER BY f.amount DESC, f.id)
         FROM public.event_forecasts f WHERE f.id = ANY (v_cand)) END;
    RETURN NEXT;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._capi_classify_lead(p_lead_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record; v_status text; v_reason text;
BEGIN
  SELECT id, kind, created_at, capi_status INTO l FROM public.leads WHERE id = p_lead_id FOR UPDATE;
  IF l.id IS NULL OR l.capi_status = 'sent' THEN RETURN l.capi_status; END IF;
  IF l.kind = 'redirect_click' THEN v_status := 'blocked_wrong_kind'; v_reason := 'redirect_click não gera ViewContent (D-ERP280.1)';
  ELSIF l.created_at < now() - interval '7 days' THEN v_status := 'expired'; v_reason := 'fora do prazo Meta de 7 dias';
  ELSIF NOT public.capi_consent_proof(l.id, 'ViewContent') THEN v_status := 'blocked_no_consent'; v_reason := 'sem prova de consentimento marketing por interacção';
  ELSE RETURN NULL; END IF;
  UPDATE public.leads SET capi_status_before = coalesce(capi_status_before, coalesce(capi_status, 'null')),
         capi_status = v_status, capi_block_reason = v_reason, capi_classified_at = now()
   WHERE id = l.id AND capi_status IS DISTINCT FROM 'sent';
  RETURN v_status;
END $function$

CREATE OR REPLACE FUNCTION public._club327_cohesion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; BEGIN
  SELECT company_id INTO s FROM portal_sites WHERE id = NEW.site_id;
  IF NOT FOUND OR s.company_id <> NEW.company_id THEN RAISE EXCEPTION '#327 coesão: site/empresa (%)', TG_TABLE_NAME; END IF;
  IF TG_TABLE_NAME IN ('club_level_floors','club_legacy_consumption','club_referral_events','club_purchase_evidence') THEN
    IF NOT EXISTS (SELECT 1 FROM club_members WHERE id = NEW.member_id AND site_id = NEW.site_id AND company_id = NEW.company_id) THEN
      RAISE EXCEPTION '#327 coesão: membro fora do site/empresa (%)', TG_TABLE_NAME; END IF;
  END IF;
  IF TG_TABLE_NAME = 'club_referral_events' THEN
    IF NOT EXISTS (SELECT 1 FROM club_members WHERE id = NEW.referee_id AND site_id = NEW.site_id) THEN
      RAISE EXCEPTION '#327 coesão: indicado fora do site'; END IF;
  END IF;
  IF TG_TABLE_NAME = 'club_level_floors' THEN
    IF NOT EXISTS (SELECT 1 FROM club_levels WHERE id = NEW.level_id AND site_id = NEW.site_id) THEN
      RAISE EXCEPTION '#327 coesão: nível fora do site'; END IF;
  END IF;
  IF TG_TABLE_NAME IN ('club_level_floors','club_legacy_consumption','club_points_cutover_log') THEN
    IF NOT EXISTS (SELECT 1 FROM club_points_config WHERE id = NEW.config_id AND site_id = NEW.site_id) THEN
      RAISE EXCEPTION '#327 coesão: config fora do site (%)', TG_TABLE_NAME; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club330_award_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.rule_key='profile_complete' THEN RAISE EXCEPTION 'profile_history_preserved'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND OLD.rule_key='profile_complete' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'profile_award_immutable'; END IF;
 IF NEW.rule_key='profile_complete' AND (NEW.points<>50 OR NOT EXISTS(
  SELECT 1 FROM club_member_profiles p JOIN club_profile_settings s ON s.site_id=p.site_id
  WHERE p.member_id=NEW.member_id AND p.company_id=NEW.company_id AND p.completed_at IS NOT NULL
   AND p.award_event_id=NEW.event_id AND NEW.ref_id=p.member_id::text AND p.award_id IS NULL AND s.enabled
 )) THEN RAISE EXCEPTION 'profile_award_invalid'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club330_profile_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'profile_history_preserved'; END IF;
 IF NOT EXISTS(SELECT 1 FROM portal_sites s WHERE s.id=NEW.site_id AND s.company_id=NEW.company_id) THEN RAISE EXCEPTION 'profile_scope'; END IF;
 IF TG_TABLE_NAME='club_member_profiles' THEN
  IF NOT EXISTS(SELECT 1 FROM club_members m WHERE m.id=NEW.member_id AND m.site_id=NEW.site_id AND m.company_id=NEW.company_id) THEN RAISE EXCEPTION 'profile_scope'; END IF;
  IF NEW.birth_date IS NOT NULL AND (NEW.birth_date>(now() AT TIME ZONE 'Europe/Lisbon')::date OR NOT isfinite(NEW.birth_date)) THEN RAISE EXCEPTION 'birth_date_invalid'; END IF;
  IF TG_OP='UPDATE' AND (OLD.member_id IS DISTINCT FROM NEW.member_id OR OLD.site_id IS DISTINCT FROM NEW.site_id OR OLD.company_id IS DISTINCT FROM NEW.company_id
    OR (OLD.completed_at IS NOT NULL AND (OLD.completed_at IS DISTINCT FROM NEW.completed_at OR OLD.award_event_id IS DISTINCT FROM NEW.award_event_id OR (OLD.award_id IS NOT NULL AND OLD.award_id IS DISTINCT FROM NEW.award_id)))) THEN RAISE EXCEPTION 'profile_completion_immutable'; END IF;
 ELSE
  IF TG_OP='UPDATE' AND (OLD.site_id IS DISTINCT FROM NEW.site_id OR OLD.company_id IS DISTINCT FROM NEW.company_id) THEN RAISE EXCEPTION 'profile_scope_immutable'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club330_rule_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; BEGIN
 IF TG_OP='DELETE' THEN IF OLD.rule_key='profile_complete' THEN RAISE EXCEPTION 'profile_rule_protected'; END IF; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.rule_key='profile_complete' AND (NEW.rule_key IS DISTINCT FROM OLD.rule_key OR NEW.site_id IS DISTINCT FROM OLD.site_id OR NEW.company_id IS DISTINCT FROM OLD.company_id) THEN RAISE EXCEPTION 'profile_rule_protected'; END IF;
 IF NEW.rule_key='profile_complete' THEN
  SELECT * INTO r FROM club_profile_settings WHERE site_id=NEW.site_id AND company_id=NEW.company_id;
  IF NOT FOUND OR NEW.points<>50 OR NEW.active IS DISTINCT FROM r.enabled THEN RAISE EXCEPTION 'profile_rule_protected'; END IF;
 END IF; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club_award_core(p_member uuid, p_rule text, p_ref text, p_points integer, p_evidence uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; cfg club_points_config; ev uuid; pts int := p_points; e record; n int;
        controlled boolean := p_rule IN ('join_confirmed','friend_joined','crew_complete','promo_lot_purchase'); BEGIN
  SELECT cm.id, cm.company_id, cm.site_id INTO m FROM club_members cm WHERE cm.id = p_member;
  IF NOT FOUND THEN RETURN 0; END IF;
  PERFORM _club_site_lock(m.site_id, false);           -- ANTES de ler config/edição
  SELECT event_id INTO ev FROM portal_sites WHERE id = m.site_id;
  cfg := _club_active_cfg(m.site_id);
  IF cfg.id IS NULL OR NOT controlled THEN
    -- Sem config ativa, ou regra não controlada: valores atuais; grava a edição corrente do site.
    IF p_rule = 'promo_lot_purchase' AND cfg.id IS NOT NULL THEN RETURN 0; END IF;
    IF coalesce(pts,0) <= 0 THEN RETURN 0; END IF;
  ELSE
    -- Config ativa mas de outra edição (site mudou de evento sem cutover): regras controladas falham fechadas.
    IF ev IS DISTINCT FROM cfg.event_id THEN RETURN 0; END IF;
    PERFORM pg_advisory_xact_lock(3271, hashtext(p_member::text || ':' || p_rule || ':' || ev::text));
    IF p_rule = 'join_confirmed' THEN
      pts := cfg.join_points;
      IF _club_rule_used(p_member, p_rule, cfg.id) > 0 THEN RETURN 0; END IF;
    ELSIF p_rule = 'friend_joined' THEN
      pts := cfg.referral_points;
      IF _club_rule_used(p_member, p_rule, cfg.id) + pts > cfg.referral_cap THEN RETURN 0; END IF;
    ELSIF p_rule = 'crew_complete' THEN
      pts := cfg.crew_points;
      IF _club_rule_used(p_member, p_rule, cfg.id) > 0 THEN RETURN 0; END IF;
    ELSE -- promo_lot_purchase: fail-closed, só com prova válida desta edição/membro/site e lote elegível.
      IF NOT cfg.purchase_enabled OR p_evidence IS NULL THEN RETURN 0; END IF;
      SELECT * INTO e FROM club_purchase_evidence WHERE id = p_evidence;
      IF NOT FOUND OR e.member_id <> p_member OR e.site_id <> m.site_id OR e.company_id <> m.company_id
         OR e.status <> 'valid' OR e.event_id <> ev OR NOT (e.lot_ref = ANY(cfg.purchase_lots)) THEN RETURN 0; END IF;
      pts := cfg.purchase_points;
      IF _club_rule_used(p_member, p_rule, cfg.id) > 0 THEN RETURN 0; END IF;
    END IF;
    IF coalesce(pts,0) <= 0 THEN RETURN 0; END IF;
  END IF;
  INSERT INTO club_points(company_id, member_id, rule_key, points, ref_id, event_id)
    VALUES (m.company_id, p_member, p_rule, pts, p_ref, ev) ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN CASE WHEN n > 0 THEN pts ELSE 0 END;
END $function$

CREATE OR REPLACE FUNCTION public._effective_permissions_for(_user_id uuid, _company_id uuid, _universe text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pa boolean := public.is_platform_admin(_user_id);
  v_roles text[];
  v_role text;
  v_full boolean;
  v_perms text[];
BEGIN
  IF _user_id IS NULL THEN
    RETURN jsonb_build_object('role', NULL, 'permissions', '[]'::jsonb);
  END IF;

  SELECT array_agg(DISTINCT role::text) INTO v_roles
    FROM public.user_roles
   WHERE user_id = _user_id
     AND (company_id = _company_id OR role = 'platform_admin'::app_role);

  SELECT r INTO v_role FROM unnest(coalesce(v_roles, '{}')) r
   ORDER BY CASE r WHEN 'platform_admin' THEN 0 WHEN 'admin' THEN 1 WHEN 'manager' THEN 2
     WHEN 'accountant' THEN 3 WHEN 'marketing_manager' THEN 4 WHEN 'content_manager' THEN 4
     WHEN 'editor' THEN 4 WHEN 'producer' THEN 4 WHEN 'field_producer' THEN 4
     WHEN 'partner' THEN 5 WHEN 'viewer' THEN 6 WHEN 'user' THEN 7 ELSE 99 END, r
   LIMIT 1;

  v_full := v_pa OR 'admin' = ANY(coalesce(v_roles, '{}'));

  WITH base AS (
    SELECT unnest(coalesce(_universe, '{}')) k WHERE v_full
    UNION SELECT permission FROM public.role_permissions WHERE v_pa
    UNION SELECT rp.permission FROM public.role_permissions rp
      WHERE rp.role::text = ANY(coalesce(v_roles, '{}'))
  ),
  ov AS (
    SELECT permission k, bool_and(granted) g FROM public.user_permissions
     WHERE user_id = _user_id AND company_id = _company_id GROUP BY 1
  ),
  eff AS (
    SELECT b.k FROM base b LEFT JOIN ov ON ov.k = b.k WHERE ov.g IS NULL OR ov.g
    UNION SELECT k FROM ov WHERE g
  )
  SELECT array_agg(k ORDER BY k) INTO v_perms FROM eff;

  RETURN jsonb_build_object(
    'role', coalesce(v_role, 'user'),
    'company_id', _company_id,
    'permissions', to_jsonb(coalesce(v_perms, '{}'))
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._leads_copy_consent_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE lc record;
BEGIN
  NEW.consent_subject_id := NULL; NEW.consent_event_id := NULL; NEW.consent_portal := NULL;
  IF NEW.meta ? 'lead_capture_id' THEN
    SELECT consent_subject_id, consent_event_id, consent_portal, company_id INTO lc
      FROM public.lead_capture WHERE id = (NEW.meta ->> 'lead_capture_id')::uuid;
    IF lc.consent_event_id IS NOT NULL AND lc.company_id = NEW.company_id THEN
      NEW.consent_subject_id := lc.consent_subject_id; NEW.consent_event_id := lc.consent_event_id; NEW.consent_portal := lc.consent_portal;
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  NEW.consent_subject_id := NULL; NEW.consent_event_id := NULL; NEW.consent_portal := NULL; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._marketing_consent_capture_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text; v_company uuid; v_ok boolean := false; v_prev bigint; v_dup boolean := false;
BEGIN
  BEGIN v_role := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  EXCEPTION WHEN OTHERS THEN v_role := ''; END;
  IF TG_TABLE_NAME = 'redirect_log' THEN v_company := NEW.consent_company_id; ELSE v_company := NEW.company_id; END IF;
  IF v_role = 'service_role' AND NEW.consent_subject_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('mcs:' || NEW.consent_subject_id::text, 0));
    v_ok := coalesce(public.marketing_consent_binding_valid(NEW.consent_subject_id, NEW.consent_event_id, v_company, NEW.consent_portal, clock_timestamp()), false);
    IF v_ok AND NEW.client_event_id IS NOT NULL THEN
      IF TG_TABLE_NAME = 'redirect_log' THEN
        SELECT true, consent_event_id INTO v_dup, v_prev FROM public.redirect_log WHERE client_event_id = NEW.client_event_id ORDER BY created_at LIMIT 1;
      ELSE
        SELECT true, consent_event_id INTO v_dup, v_prev FROM public.lead_capture WHERE client_event_id = NEW.client_event_id ORDER BY created_at LIMIT 1;
      END IF;
      IF coalesce(v_dup, false) AND v_prev IS DISTINCT FROM NEW.consent_event_id THEN v_ok := false; END IF;
    END IF;
  END IF;
  IF NOT v_ok THEN
    NEW.consent_subject_id := NULL; NEW.consent_event_id := NULL; NEW.consent_portal := NULL;
    NEW.fbc := NULL; NEW.fbp := NULL;
    IF TG_TABLE_NAME = 'redirect_log' THEN
      NEW.consent_company_id := NULL;
      NEW.referrer := public.marketing_strip_meta_params(NEW.referrer);
      NEW.destination_url := public.marketing_strip_meta_params(NEW.destination_url);
    ELSE
      NEW.raw := public.marketing_strip_meta_json(NEW.raw);
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._reverse_transaction_offsets_for(p_tx_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  o record; v_other uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM public.transaction_payments x
              WHERE x.transaction_id = p_tx_id AND x.payment_method <> 'compensation'
                AND x.status = 'paid' AND x.reversed_at IS NULL) THEN
    RETURN;
  END IF;
  FOR o IN SELECT * FROM public.transaction_offsets
            WHERE receivable_transaction_id = p_tx_id OR payable_transaction_id = p_tx_id
  LOOP
    v_other := CASE WHEN o.receivable_transaction_id = p_tx_id
                    THEN o.payable_transaction_id ELSE o.receivable_transaction_id END;
    UPDATE public.transaction_payments
       SET status = 'reversed', reversed_at = now(), reversed_by = (SELECT auth.uid()),
           reversal_reason = 'estorno do pagamento de origem'
     WHERE offset_id = o.id AND transaction_id = v_other
       AND status = 'paid' AND reversed_at IS NULL;
    IF FOUND THEN
      PERFORM public._derive_paid_amount(v_other);
    END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._revert_event_to_version(_event_id uuid, _target_version_id uuid, _performed_by uuid, _performed_by_label text, _force boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target RECORD;
  v_active_id uuid;
  v_linked_count int;
  v_now timestamptz := now();
  v_next_version int;
  v_new_version_id uuid;
  v_payload jsonb;
  v_row jsonb;
  v_tx_links jsonb;
  v_tx_result jsonb;
BEGIN
  SELECT * INTO v_target FROM public.bp_versions WHERE id = _target_version_id;
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Target version % not found', _target_version_id;
  END IF;
  IF v_target.event_id <> _event_id THEN
    RAISE EXCEPTION 'Version % does not belong to event %', _target_version_id, _event_id;
  END IF;

  v_linked_count := public.bp_version_linked_tx_count(_event_id);
  IF v_linked_count > 0 AND NOT _force THEN
    RAISE EXCEPTION 'Reversão bloqueada: existem % linha(s) do BP atual com transações vinculadas. Desvincule ou elimine essas transações antes de reverter.', v_linked_count
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO v_active_id
    FROM public.bp_versions
   WHERE event_id = _event_id AND state = 'active'
   LIMIT 1;

  -- Demote active BEFORE inserting new active to satisfy partial unique index.
  IF v_active_id IS NOT NULL THEN
    UPDATE public.bp_versions
       SET state = 'superseded',
           superseded_at = v_now
     WHERE id = v_active_id;
  END IF;

  -- Captura vínculos BP↔TX antes do DELETE (ON DELETE SET NULL apaga-os).
  v_tx_links := public.bp_capture_tx_links(_event_id);

  DELETE FROM public.event_forecasts WHERE event_id = _event_id;

  v_payload := COALESCE(v_target.snapshot_payload->'forecasts', '[]'::jsonb);
  FOR v_row IN SELECT * FROM jsonb_array_elements(v_payload)
  LOOP
    INSERT INTO public.event_forecasts (
      id, event_id, category_id, type, description, amount, currency,
      original_amount, fx_rate, fx_rate_source,
      formula_type, formula_value, iva_rate, status,
      approved_at, approved_by, transaction_id, cache_config_id,
      master_forecast_id, invoice_group_id, attachment_refs,
      historic_overrides, is_overhead, is_retroactive_override,
      is_transitory, exclude_from_result, notes, specification,
      created_at, updated_at
    )
    VALUES (
      COALESCE((v_row->>'id')::uuid, gen_random_uuid()),
      _event_id,
      NULLIF(v_row->>'category_id', '')::uuid,
      v_row->>'type',
      v_row->>'description',
      COALESCE((v_row->>'amount')::numeric, 0),
      COALESCE(v_row->>'currency', 'EUR'),
      NULLIF(v_row->>'original_amount', '')::numeric,
      NULLIF(v_row->>'fx_rate', '')::numeric,
      v_row->>'fx_rate_source',
      COALESCE(v_row->>'formula_type', 'fixed'),
      COALESCE((v_row->>'formula_value')::numeric, 0),
      COALESCE((v_row->>'iva_rate')::numeric, 0),
      COALESCE(v_row->>'status', 'pending'),
      NULLIF(v_row->>'approved_at', '')::timestamptz,
      NULLIF(v_row->>'approved_by', '')::uuid,
      NULL,
      NULLIF(v_row->>'cache_config_id', '')::uuid,
      NULLIF(v_row->>'master_forecast_id', '')::uuid,
      NULLIF(v_row->>'invoice_group_id', '')::uuid,
      COALESCE(v_row->'attachment_refs', '[]'::jsonb),
      COALESCE(v_row->'historic_overrides', '[]'::jsonb),
      COALESCE((v_row->>'is_overhead')::boolean, false),
      COALESCE((v_row->>'is_retroactive_override')::boolean, false),
      COALESCE((v_row->>'is_transitory')::boolean, false),
      COALESCE((v_row->>'exclude_from_result')::boolean, false),
      v_row->>'notes',
      v_row->>'specification',
      COALESCE(NULLIF(v_row->>'created_at', '')::timestamptz, v_now),
      v_now
    );
  END LOOP;

  v_tx_result := public.bp_restore_tx_links(_event_id, v_tx_links);

  SELECT COALESCE(MAX(version_number), 0) + 1
    INTO v_next_version
    FROM public.bp_versions
   WHERE event_id = _event_id;

  INSERT INTO public.bp_versions (
    event_id, version_number, state, created_by, created_by_label,
    description, snapshot_payload, approved_at, approved_by,
    is_retroactive_snapshot, cascaded_from_version_id
  )
  VALUES (
    _event_id, v_next_version, 'active', _performed_by, _performed_by_label,
    format('Reversão para v%s', v_target.version_number),
    v_target.snapshot_payload, v_now, _performed_by,
    true, NULL
  )
  RETURNING id INTO v_new_version_id;

  IF v_active_id IS NOT NULL AND v_active_id <> v_new_version_id THEN
    UPDATE public.bp_versions
       SET superseded_by_version_id = v_new_version_id
     WHERE id = v_active_id;

    INSERT INTO public.bp_version_audit_log (
      version_id, event_id, action, performed_by, performed_by_label, metadata
    ) VALUES (
      v_active_id, _event_id, 'superseded', _performed_by, _performed_by_label,
      jsonb_build_object('superseded_by_version_id', v_new_version_id, 'cause', 'revert')
    );
  END IF;

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    v_new_version_id, _event_id, 'reverted', _performed_by, _performed_by_label,
    jsonb_build_object(
      'reverted_to_version_id', _target_version_id,
      'reverted_to_version_number', v_target.version_number,
      'previous_active_id', v_active_id,
      'forced', _force,
      'linked_tx_count', v_linked_count,
      'tx_links', v_tx_result
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public._supplier_resolve_or_create(p_company_id uuid, p_name text, p_nif text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_nif_active uuid[]; v_flagged int := 0; r record;
BEGIN
  SELECT array_agg(c.id) INTO v_nif_active
    FROM public._supplier_similar_candidates(p_company_id, p_name, p_nif, NULL) c
   WHERE c.motivo = 'nif' AND c.is_active;
  IF coalesce(array_length(v_nif_active, 1), 0) = 1 THEN
    RETURN jsonb_build_object('id', v_nif_active[1], 'created', false, 'reused', true, 'flagged', 0);
  END IF;

  INSERT INTO public.suppliers (name, nif, company_id, is_active)
  VALUES (btrim(p_name), nullif(btrim(coalesce(p_nif, '')), ''), p_company_id, true)
  RETURNING id INTO v_id;

  FOR r IN SELECT c.id, c.motivo FROM public._supplier_similar_candidates(p_company_id, p_name, p_nif, v_id) c LOOP
    INSERT INTO public.supplier_similarity_flags (company_id, supplier_id, similar_supplier_id, motivo, source)
    VALUES (p_company_id, v_id, r.id, r.motivo, p_source) ON CONFLICT DO NOTHING;
    v_flagged := v_flagged + 1;
  END LOOP;
  RETURN jsonb_build_object('id', v_id, 'created', true, 'reused', false, 'flagged', v_flagged);
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_formalidade_suggestions(_forecast_ids uuid[], _new_state bp_formalidade)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_updated integer;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'manager')) THEN
    RAISE EXCEPTION 'Sem permissão para aplicar sugestões de formalidade';
  END IF;

  IF _forecast_ids IS NULL OR array_length(_forecast_ids, 1) IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.event_forecasts
  SET formalidade = _new_state,
      formalidade_changed_at = now(),
      formalidade_changed_by = auth.uid()
  WHERE id = ANY(_forecast_ids)
    AND formalidade <> _new_state;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_transaction_offsets()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  o record;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.payment_method = 'compensation' OR NEW.status <> 'paid' OR NEW.reversed_at IS NOT NULL THEN
      RETURN NEW;
    END IF;
    FOR o IN SELECT id FROM public.transaction_offsets
              WHERE receivable_transaction_id = NEW.transaction_id
                 OR payable_transaction_id = NEW.transaction_id
    LOOP
      PERFORM public._apply_transaction_offset(o.id, NEW.id);
    END LOOP;
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.payment_method <> 'compensation' AND OLD.status = 'paid' AND OLD.reversed_at IS NULL
       AND (NEW.status <> 'paid' OR NEW.reversed_at IS NOT NULL) THEN
      PERFORM public._reverse_transaction_offsets_for(NEW.transaction_id);
    END IF;
    RETURN NEW;
  ELSE
    IF OLD.payment_method <> 'compensation' AND OLD.status = 'paid' AND OLD.reversed_at IS NULL THEN
      PERFORM public._reverse_transaction_offsets_for(OLD.transaction_id);
    END IF;
    RETURN OLD;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_consume_oauth_state(p_state_id uuid)
 RETURNS TABLE(company_id uuid, user_id uuid, artist_channel_id uuid, provider text, return_url text, valid boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.artist_oauth_states%ROWTYPE;
BEGIN
  SELECT * INTO v FROM public.artist_oauth_states
  WHERE id = p_state_id AND expires_at > now();

  IF NOT FOUND THEN
    -- limpeza oportunista dos expirados
    DELETE FROM public.artist_oauth_states WHERE expires_at <= now();
    RETURN QUERY SELECT NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text, false;
    RETURN;
  END IF;

  DELETE FROM public.artist_oauth_states WHERE id = p_state_id;
  RETURN QUERY SELECT v.company_id, v.user_id, v.artist_channel_id, v.provider, v.return_url, true;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_delete_channel_connection(p_artist_channel_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_deleted int; v_google int;
BEGIN
  SELECT count(*) INTO v_google FROM public.artist_channel_connections
   WHERE artist_channel_id = p_artist_channel_id AND provider = 'google';
  DELETE FROM public.artist_channel_connections WHERE artist_channel_id = p_artist_channel_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  IF v_google > 0 THEN
    UPDATE public.artist_channels SET revoked_at = now() WHERE id = p_artist_channel_id;
  END IF;
  RETURN v_deleted > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_generic_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_entity_id text;
  v_old jsonb;
  v_new jsonb;
  v_user text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_old := NULL;
    v_new := to_jsonb(NEW);
    BEGIN v_entity_id := (NEW.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    BEGIN v_entity_id := (NEW.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_old := to_jsonb(OLD);
    v_new := NULL;
    BEGIN v_entity_id := (OLD.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  END IF;

  BEGIN
    v_user := COALESCE(auth.uid()::text, 'system');
  EXCEPTION WHEN OTHERS THEN
    v_user := 'system';
  END;

  INSERT INTO public.system_audit_log (
    entity_type, entity_id, action, changed_by, old_data, new_data, metadata
  ) VALUES (
    TG_TABLE_NAME,
    COALESCE(v_entity_id, gen_random_uuid()::text),
    v_action,
    v_user,
    v_old,
    v_new,
    jsonb_build_object('schema', TG_TABLE_SCHEMA, 'op', TG_OP)
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_create_initial_bp_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_should_create_initial boolean := false;
  v_should_snapshot_closing boolean := false;
  v_should_snapshot_reopen boolean := false;
  v_has_versions boolean := false;
  v_description text;
BEGIN
  IF NEW.parent_event_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT EXISTS (SELECT 1 FROM public.bp_versions WHERE event_id = NEW.id) INTO v_has_versions;
  IF NEW.status IN ('confirmed', 'active') THEN
    IF TG_OP = 'INSERT' THEN v_should_create_initial := NOT v_has_versions;
    ELSIF TG_OP = 'UPDATE' AND (OLD.status IS NULL OR OLD.status NOT IN ('confirmed', 'active'))
      AND NEW.status IN ('confirmed', 'active') AND NOT v_has_versions THEN
      v_should_create_initial := true;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status
    AND OLD.status = 'active' AND NEW.status = 'completed' THEN v_should_snapshot_closing := true; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status
    AND OLD.status = 'completed' AND NEW.status IN ('active', 'confirmed') THEN v_should_snapshot_reopen := true; END IF;
  IF v_should_create_initial THEN
    BEGIN PERFORM public.create_bp_snapshot(_event_id := NEW.id,
      _description := 'Versão inicial — auto-criada ao ' || CASE NEW.status WHEN 'confirmed' THEN 'confirmar evento' ELSE 'ativar evento' END,
      _approve_immediately := true, _created_by := NULL, _created_by_label := 'sistema (auto v1)');
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'auto initial failed for %: %', NEW.id, SQLERRM; END;
  END IF;
  IF v_should_snapshot_closing THEN
    IF NOT EXISTS (SELECT 1 FROM public.bp_versions WHERE event_id = NEW.id AND state = 'active' AND description LIKE '%Fecho automático%') THEN
      BEGIN v_description := 'Fecho automático — snapshot ao concluir evento (' || to_char(now(), 'DD/MM/YYYY HH24:MI') || ')';
      PERFORM public.create_bp_snapshot(_event_id := NEW.id, _description := v_description,
        _approve_immediately := true, _created_by := NULL, _created_by_label := 'sistema (auto fecho)');
      EXCEPTION WHEN OTHERS THEN RAISE WARNING 'auto closing failed for %: %', NEW.id, SQLERRM; END;
    END IF;
  END IF;
  IF v_should_snapshot_reopen THEN
    BEGIN v_description := 'Reabertura — snapshot ao reabrir evento concluído (' || to_char(now(), 'DD/MM/YYYY HH24:MI') || ')';
    PERFORM public.create_bp_snapshot(_event_id := NEW.id, _description := v_description,
      _approve_immediately := true, _created_by := NULL, _created_by_label := 'sistema (auto reabertura)');
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'auto reopen failed for %: %', NEW.id, SQLERRM; END;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.backup_identities_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_users jsonb;
  v_ids jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at), '[]'::jsonb) INTO v_users
  FROM (
    SELECT id, email, phone, created_at, last_sign_in_at,
           email_confirmed_at, banned_until, is_sso_user, raw_app_meta_data
      FROM auth.users
