  RETURN jsonb_build_object(
    'gerado_em', now(),
    'utilizadores', v_users,
    'identidades', v_ids,
    'contagens', jsonb_build_object(
      'utilizadores', jsonb_array_length(v_users),
      'identidades', jsonb_array_length(v_ids)
    ),
    'aviso', 'Sem hashes de palavra-passe e sem tokens. Recuperar acesso por reposição de palavra-passe forçada.'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.bp_restore_tx_links(_event_id uuid, _links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
  v_by_id int := 0;
  v_by_desc int := 0;
  v_ambiguous int := 0;
  v_unmatched int := 0;
  v_target uuid;
  v_cnt int;
BEGIN
  IF _links IS NULL OR jsonb_typeof(_links) <> 'array' THEN
    RETURN jsonb_build_object('relinked', 0, 'by_id', 0, 'by_description', 0,
                              'ambiguous', 0, 'unmatched', 0);
  END IF;

  FOR r IN
    SELECT (e->>'tx_id')::uuid AS tx_id,
           NULLIF(e->>'forecast_id','')::uuid AS forecast_id,
           NULLIF(e->>'category_id','')::uuid AS category_id,
           e->>'description' AS description
      FROM jsonb_array_elements(_links) AS e
  LOOP
    v_target := NULL;

    -- 1) mesma linha, se continuar viva
    SELECT f.id INTO v_target
      FROM public.event_forecasts f
     WHERE f.id = r.forecast_id
       AND f.event_id = _event_id
       AND f.version_id IS NULL;

    IF v_target IS NOT NULL THEN
      UPDATE public.transactions SET forecast_id = v_target WHERE id = r.tx_id;
      v_by_id := v_by_id + 1;
      CONTINUE;
    END IF;

    -- 2) (category_id, description) — só quando há exactamente uma candidata
    SELECT count(*) INTO v_cnt
      FROM public.event_forecasts f
     WHERE f.event_id = _event_id
       AND f.version_id IS NULL
       AND f.category_id IS NOT DISTINCT FROM r.category_id
       AND f.description IS NOT DISTINCT FROM r.description;

    IF v_cnt = 1 THEN
      SELECT f.id INTO v_target
        FROM public.event_forecasts f
       WHERE f.event_id = _event_id
         AND f.version_id IS NULL
         AND f.category_id IS NOT DISTINCT FROM r.category_id
         AND f.description IS NOT DISTINCT FROM r.description
       LIMIT 1;
      UPDATE public.transactions SET forecast_id = v_target WHERE id = r.tx_id;
      v_by_desc := v_by_desc + 1;
    ELSIF v_cnt > 1 THEN
      v_ambiguous := v_ambiguous + 1;
    ELSE
      v_unmatched := v_unmatched + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'relinked', v_by_id + v_by_desc,
    'by_id', v_by_id,
    'by_description', v_by_desc,
    'ambiguous', v_ambiguous,
    'unmatched', v_unmatched
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.capi_consent_proof(p_lead_id uuid, p_event_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record;
BEGIN
  IF p_event_name IS NULL OR p_event_name NOT IN ('ViewContent','Lead','InitiateCheckout') THEN RETURN false; END IF;
  SELECT id, company_id, created_at, consent_subject_id, consent_event_id, consent_portal INTO l FROM public.leads WHERE id = p_lead_id;
  IF l.id IS NULL THEN RETURN false; END IF;
  RETURN coalesce(public.marketing_consent_binding_valid(l.consent_subject_id, l.consent_event_id, l.company_id, l.consent_portal, l.created_at), false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.capi_guard_lead_dispatch(p_lead_id uuid, p_event_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record; v_reason text;
BEGIN
  IF NOT public.capi_dispatch_allowed() THEN RETURN jsonb_build_object('allowed', false, 'reason', 'suspended'); END IF;
  IF p_lead_id IS NULL THEN RETURN jsonb_build_object('allowed', false, 'reason', 'no_identity'); END IF;
  SELECT id, kind, created_at, capi_status INTO l FROM public.leads WHERE id = p_lead_id;
  IF l.id IS NULL THEN RETURN jsonb_build_object('allowed', false, 'reason', 'no_identity'); END IF;
  IF p_event_name IS DISTINCT FROM 'ViewContent' THEN RETURN jsonb_build_object('allowed', false, 'reason', 'wrong_event'); END IF;
  IF l.capi_status IS DISTINCT FROM 'processing' THEN RETURN jsonb_build_object('allowed', false, 'reason', 'not_claimed'); END IF;
  v_reason := public.capi_lead_block_reason(l.id);
  IF v_reason IS NOT NULL THEN RETURN jsonb_build_object('allowed', false, 'reason', v_reason); END IF;
  RETURN jsonb_build_object('allowed', true, 'reason', NULL, 'event_time', extract(epoch from l.created_at)::bigint);
END $function$

CREATE OR REPLACE FUNCTION public.capi_lead_block_reason(p_lead_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE l record;
BEGIN
  IF NOT public.capi_dispatch_allowed() THEN RETURN 'suspended'; END IF;
  SELECT id, kind, created_at, capi_status INTO l FROM public.leads WHERE id = p_lead_id;
  IF l.id IS NULL THEN RETURN 'not_found'; END IF;
  IF l.kind = 'redirect_click' THEN RETURN 'wrong_kind'; END IF;
  IF l.created_at < now() - interval '7 days' THEN RETURN 'expired'; END IF;
  IF NOT public.capi_consent_proof(l.id, 'ViewContent') THEN RETURN 'no_consent'; END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.capi_record_meta_error(p_lead_id uuid, p_code integer, p_subcode integer, p_detail text, p_source text DEFAULT 'process-leads-capi'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_code = 100 AND p_subcode = 33 THEN
    IF p_lead_id IS NOT NULL THEN
      UPDATE public.leads SET capi_status_before = coalesce(capi_status_before, coalesce(capi_status,'null')),
             capi_status = 'error_meta_access', capi_block_reason = 'Meta 100/33: objecto inexistente ou sem permissão',
             capi_classified_at = now()
       WHERE id = p_lead_id AND capi_status IS DISTINCT FROM 'sent';
    END IF;
    INSERT INTO public.capi_alerts (source, lead_id, meta_code, meta_subcode, kind, detail)
    VALUES (coalesce(p_source,'unknown'), p_lead_id, p_code, p_subcode, 'meta_access_100_33', left(p_detail, 500));
    RETURN 'error_meta_access';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.capi_recover_processing(p_older_than_minutes integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v text; n_blocked int := 0; n_retry int := 0;
BEGIN
  FOR r IN SELECT id FROM public.leads WHERE capi_status = 'processing'
            AND capi_sent_at < now() - make_interval(mins => greatest(p_older_than_minutes, 1))
            FOR UPDATE SKIP LOCKED LOOP
    v := public._capi_classify_lead(r.id);
    IF v IS NULL THEN
      IF public.capi_dispatch_allowed() THEN
        UPDATE public.leads SET capi_status = 'retry' WHERE id = r.id AND capi_status = 'processing';
        n_retry := n_retry + 1;
      END IF;
    ELSE n_blocked := n_blocked + 1; END IF;
  END LOOP;
  RETURN jsonb_build_object('blocked', n_blocked, 'retry', n_retry);
END $function$

CREATE OR REPLACE FUNCTION public.check_admin_windows_contiguous(p_company_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  p_name text; p_s date; p_e date;
  first boolean := true;
BEGIN
  FOR r IN
    SELECT id, name, admin_window_start AS s, admin_window_end AS e
      FROM public.events
     WHERE company_id = p_company_id
       AND absorbs_admin_costs = true
       AND parent_event_id IS NULL
     ORDER BY admin_window_start, id
  LOOP
    IF NOT first THEN
      IF p_e IS NULL THEN
        RAISE EXCEPTION 'Janelas administrativas: "%" (desde %) está em aberto, mas "%" começa depois (%). Só a última janela pode ficar em aberto.',
          p_name, to_char(p_s,'DD/MM/YYYY'), r.name, to_char(r.s,'DD/MM/YYYY');
      ELSIF r.s <= p_e THEN
        RAISE EXCEPTION 'Janelas administrativas sobrepostas: "%" (% a %) e "%" (desde %).',
          p_name, to_char(p_s,'DD/MM/YYYY'), to_char(p_e,'DD/MM/YYYY'), r.name, to_char(r.s,'DD/MM/YYYY');
      ELSIF r.s > p_e + 1 THEN
        RAISE EXCEPTION 'Janelas administrativas com buraco: "%" termina a % e "%" começa a %. O início tem de ser o dia seguinte ao fim da anterior (%).',
          p_name, to_char(p_e,'DD/MM/YYYY'), r.name, to_char(r.s,'DD/MM/YYYY'), to_char(p_e + 1,'DD/MM/YYYY');
      END IF;
    END IF;
    p_name := r.name; p_s := r.s; p_e := r.e;
    first := false;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_ticketing_sync_health(_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_items jsonb;
  v_alerts jsonb;
  v_recipients text[];
  v_last_notified timestamptz;
  v_run_at text := to_char(now() at time zone 'Europe/Lisbon', 'DD/MM/YYYY HH24:MI');
  v_today date := (now() at time zone 'Europe/Lisbon')::date;
  v_company uuid;
  v_company_alerts jsonb;
  v_plan jsonb := '[]'::jsonb;
  v_status text;
begin
  select coalesce(jsonb_agg(jsonb_build_object('evento', c.event_name, 'bilheteira', c.bilheteira, 'condicao', c.condicao,
           'nivel', c.nivel, 'detalhe', c.detalhe, 'desdeQuando', c.desde_quando,
           'config_id', c.config_id, 'company_id', c.company_id)), '[]'::jsonb)
    into v_items from public.ticketing_sync_conditions() c;

  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_alerts
    from jsonb_array_elements(v_items) x where x->>'condicao' <> 'c';

  if exists (select 1 from jsonb_array_elements(v_items) x where x->>'company_id' is null) then
    raise warning 'check_ticketing_sync_health: itens sem company_id';
    if not _dry_run then
      insert into public.system_audit_log (entity_type, entity_id, action, changed_by, metadata)
      values ('ticketing_sync_health','check_ticketing_sync_health','missing_company','sistema',
              jsonb_build_object('run_at', v_run_at,
                'itens', (select jsonb_agg(x) from jsonb_array_elements(v_items) x where x->>'company_id' is null)));
    end if;
  end if;

  for v_company in
    select distinct (x->>'company_id')::uuid from jsonb_array_elements(v_items) x where x->>'company_id' is not null
  loop
    select coalesce(jsonb_agg(x), '[]'::jsonb) into v_company_alerts
      from jsonb_array_elements(v_alerts) x where (x->>'company_id')::uuid = v_company;

    select array_agg(distinct lower(p.email) order by lower(p.email)) into v_recipients
      from public.user_roles ur join public.profiles p on p.id = ur.user_id
     where ur.company_id = v_company and ur.role in ('admin','manager','platform_admin')
       and p.email is not null and p.email <> '';

    select last_notified_at into v_last_notified from public.sync_notifications_sent
     where config_id = v_company and sync_type = 'health_company_daily';

    v_status := case
      when jsonb_array_length(v_company_alerts) = 0 then 'sem_alertas_email'
      when v_last_notified is not null and (v_last_notified at time zone 'Europe/Lisbon')::date >= v_today then 'ja_enviado_hoje'
      when v_recipients is null or array_length(v_recipients,1) is null then 'sem_destinatarios'
      else 'enviar' end;

    v_plan := v_plan || jsonb_build_object('company_id', v_company,
      'recipients', to_jsonb(coalesce(v_recipients,'{}'::text[])),
      'itens', v_company_alerts, 'status', v_status, 'idempotency_day', to_char(v_today,'YYYYMMDD'));
  end loop;

  return jsonb_build_object('run_at', v_run_at, 'dry_run', _dry_run, 'items', v_items,
    'plano_por_empresa', v_plan,
    'emails_que_sairiam', (select coalesce(sum(jsonb_array_length(p->'recipients')),0)
                             from jsonb_array_elements(v_plan) p where p->>'status' = 'enviar'));
end;
$function$

CREATE OR REPLACE FUNCTION public.club_award(p_member uuid, p_rule text, p_ref text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s uuid; pts int; BEGIN
  SELECT site_id INTO s FROM club_members WHERE id = p_member; IF NOT FOUND THEN RETURN 0; END IF;
  SELECT points INTO pts FROM club_point_rules WHERE site_id = s AND rule_key = p_rule AND active;
  IF pts IS NULL THEN RETURN 0; END IF;
  RETURN _club_award_core(p_member, p_rule, p_ref, pts, NULL);
END $function$

CREATE OR REPLACE FUNCTION public.club_award_purchase(p_evidence uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e record; g int; base text; ref text; got int; BEGIN
  SELECT * INTO e FROM club_purchase_evidence WHERE id = p_evidence;
  IF NOT FOUND THEN RETURN 0; END IF;
  PERFORM _club_site_lock(e.site_id, false);
  SELECT * INTO e FROM club_purchase_evidence WHERE id = p_evidence FOR UPDATE;
  IF e.status <> 'valid' THEN RETURN 0; END IF;
  base := 'purchase@' || e.event_id;
  IF (club_points_active(e.member_id, 'promo_lot_purchase', base)).id IS NOT NULL THEN RETURN 0; END IF;
  SELECT count(*) INTO g FROM club_points WHERE member_id = e.member_id AND rule_key = 'promo_lot_purchase' AND (ref_id = base OR ref_id LIKE base || '#%');
  ref := CASE WHEN g = 0 THEN base ELSE base || '#' || (g + 1) END;
  got := _club_award_core(e.member_id, 'promo_lot_purchase', ref, 0, p_evidence);
  IF got > 0 THEN UPDATE club_purchase_evidence SET credited_ref = ref WHERE id = p_evidence; END IF;
  RETURN got;
END $function$

CREATE OR REPLACE FUNCTION public.club_claim_attendance(p_member uuid, p_year integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; st text; BEGIN
  SELECT cm.*, ps.brand_key INTO m FROM club_members cm JOIN portal_sites ps ON ps.id = cm.site_id WHERE cm.id = p_member;
  IF NOT FOUND THEN RETURN NULL; END IF;
  st := CASE WHEN EXISTS (SELECT 1 FROM fever_buyers f WHERE f.company_id = m.company_id
            AND f.edition_label = m.brand_key||'-'||p_year AND lower(trim(f.email)) = lower(trim(m.email))) THEN 'valido' ELSE 'pendente' END;
  INSERT INTO club_attendance_claims(company_id, member_id, year, status, matched_source, decided_at)
    VALUES (m.company_id, p_member, p_year, st, CASE WHEN st='valido' THEN 'fever_buyers' END, CASE WHEN st='valido' THEN now() END)
    ON CONFLICT (member_id, year) DO NOTHING;
  SELECT status INTO st FROM club_attendance_claims WHERE member_id = p_member AND year = p_year;
  IF st = 'valido' THEN PERFORM club_award(p_member, 'attended_year', p_year::text); END IF;
  RETURN st;
END $function$

CREATE OR REPLACE FUNCTION public.club_confirm_member(p_member uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; s uuid; prev timestamptz; j jsonb; st text; got int; cfg club_points_config; ev uuid; BEGIN
  SELECT site_id INTO s FROM club_members WHERE id = p_member; IF NOT FOUND THEN RETURN; END IF;
  PERFORM _club_site_lock(s, false);
  SELECT confirmed_at INTO prev FROM club_members WHERE id = p_member FOR NO KEY UPDATE;
  UPDATE club_members SET confirmed_at = coalesce(confirmed_at, now()), updated_at = now() WHERE id = p_member RETURNING * INTO m;
  IF NOT FOUND THEN RETURN; END IF;
  PERFORM club_award(p_member, 'join_confirmed', p_member::text);
  IF prev IS NULL AND m.referred_by_member_id IS NOT NULL AND m.referred_by_member_id <> p_member THEN
    got := club_award(m.referred_by_member_id, 'friend_joined', p_member::text);
    SELECT event_id INTO ev FROM portal_sites WHERE id = m.site_id;
    INSERT INTO club_referral_events(company_id, site_id, member_id, referee_id, event_id, credited_points)
      VALUES (m.company_id, m.site_id, m.referred_by_member_id, p_member, ev, got) ON CONFLICT DO NOTHING;
  END IF;
  IF m.pending_crew_code IS NOT NULL AND m.pending_crew_status IS NULL THEN
    BEGIN
      j := club_crew_join(p_member, m.pending_crew_code);
      st := j->>'error';
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'club_confirm_member crew: %', SQLERRM; st := 'error'; END;
    IF st IS NULL OR st = 'already_in_crew' THEN
      UPDATE club_members SET pending_crew_code = NULL, pending_crew_status = NULL, pending_crew_checked_at = NULL WHERE id = p_member;
    ELSE
      UPDATE club_members SET pending_crew_status = CASE WHEN st IN ('crew_full','crew_not_found') THEN st ELSE 'error' END,
        pending_crew_checked_at = now() WHERE id = p_member;
    END IF;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_cfg(p_site uuid, OUT pts integer, OUT min_m integer, OUT max_m integer)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; BEGIN
  SELECT * INTO r FROM club_point_rules WHERE site_id = p_site AND rule_key = 'crew_complete';
  IF NOT FOUND THEN pts := 200; min_m := 4; max_m := 6; RETURN; END IF;
  pts := CASE WHEN r.active THEN r.points ELSE 0 END;
  min_m := coalesce(r.min_members, 4); max_m := greatest(coalesce(r.max_members, 6), coalesce(r.min_members, 4));
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_check(p_crew uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; cfg record; n int; r record; BEGIN
  SELECT * INTO c FROM club_crews WHERE id = p_crew; IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO cfg FROM club_crew_cfg(c.site_id);
  SELECT count(*) INTO n FROM club_crew_members cm JOIN club_members m ON m.id = cm.member_id
   WHERE cm.crew_id = p_crew AND m.confirmed_at IS NOT NULL;
  IF c.completed_at IS NULL AND n >= cfg.min_m THEN
    UPDATE club_crews SET completed_at = now() WHERE id = p_crew; c.completed_at := now();
  END IF;
  IF c.completed_at IS NOT NULL THEN
    FOR r IN SELECT cm.member_id FROM club_crew_members cm JOIN club_members m ON m.id = cm.member_id
              WHERE cm.crew_id = p_crew AND m.confirmed_at IS NOT NULL LOOP
      PERFORM club_award_fixed(r.member_id, 'crew_complete', p_crew::text, cfg.pts);
    END LOOP;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_create(p_member uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; cid uuid; cd text; nm text := regexp_replace(trim(coalesce(p_name,'')), '\s+', ' ', 'g'); BEGIN
  SELECT * INTO m FROM club_members WHERE id = p_member;
  IF NOT FOUND OR m.confirmed_at IS NULL THEN RETURN jsonb_build_object('error','no_session'); END IF;
  IF NOT club_crew_name_ok(nm) THEN RETURN jsonb_build_object('error','crew_name'); END IF;
  IF EXISTS (SELECT 1 FROM club_crew_members WHERE site_id = m.site_id AND member_id = p_member) THEN
    RETURN jsonb_build_object('error','already_in_crew'); END IF;
  cd := club_crew_gen_code();
  INSERT INTO club_crews(company_id, site_id, name, code, owner_member_id) VALUES (m.company_id, m.site_id, nm, cd, p_member) RETURNING id INTO cid;
  INSERT INTO club_crew_members(company_id, site_id, crew_id, member_id) VALUES (m.company_id, m.site_id, cid, p_member);
  PERFORM club_crew_check(cid);
  RETURN jsonb_build_object('id', cid, 'name', nm, 'code', cd);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('error','already_in_crew');
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_gen_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE a text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; c text; BEGIN
  LOOP
    c := ''; FOR i IN 1..6 LOOP c := c || substr(a, 1 + floor(random() * length(a))::int, 1); END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM club_crews WHERE code = c);
  END LOOP;
  RETURN c;
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_join(p_member uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; c record; cfg record; n int; BEGIN
  SELECT * INTO m FROM club_members WHERE id = p_member;
  IF NOT FOUND OR m.confirmed_at IS NULL THEN RETURN jsonb_build_object('error','no_session'); END IF;
  SELECT * INTO c FROM club_crews WHERE code = upper(trim(coalesce(p_code,''))) AND site_id = m.site_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','crew_not_found'); END IF;
  IF EXISTS (SELECT 1 FROM club_crew_members WHERE site_id = m.site_id AND member_id = p_member) THEN
    RETURN jsonb_build_object('error','already_in_crew'); END IF;
  SELECT * INTO cfg FROM club_crew_cfg(c.site_id);
  SELECT count(*) INTO n FROM club_crew_members WHERE crew_id = c.id;
  IF n >= cfg.max_m THEN RETURN jsonb_build_object('error','crew_full'); END IF;
  INSERT INTO club_crew_members(company_id, site_id, crew_id, member_id) VALUES (c.company_id, c.site_id, c.id, p_member);
  PERFORM club_crew_check(c.id);
  RETURN jsonb_build_object('crew_id', c.id);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('error','already_in_crew');
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_leave(p_member uuid, p_new_owner uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE cm record; c record; others int; BEGIN
  SELECT * INTO cm FROM club_crew_members WHERE member_id = p_member LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','not_in_crew'); END IF;
  SELECT * INTO c FROM club_crews WHERE id = cm.crew_id FOR UPDATE;
  SELECT count(*) INTO others FROM club_crew_members WHERE crew_id = c.id AND member_id <> p_member;
  IF c.owner_member_id = p_member AND others > 0 THEN
    IF p_new_owner IS NULL OR NOT EXISTS (SELECT 1 FROM club_crew_members WHERE crew_id = c.id AND member_id = p_new_owner AND member_id <> p_member) THEN
      RETURN jsonb_build_object('error','owner_transfer'); END IF;
    UPDATE club_crews SET owner_member_id = p_new_owner WHERE id = c.id;
  END IF;
  DELETE FROM club_crew_members WHERE id = cm.id;
  IF others = 0 THEN DELETE FROM club_crews WHERE id = c.id; END IF;
  RETURN jsonb_build_object('ok', true);
END $function$

CREATE OR REPLACE FUNCTION public.club_crew_pending(p_member uuid, p_action text DEFAULT 'status'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; j jsonb; st text; nm text; in_same boolean; in_any boolean; s uuid; BEGIN
  IF p_action IS NULL OR p_action NOT IN ('status','retry','dismiss') THEN RETURN jsonb_build_object('error','action'); END IF;
  SELECT site_id INTO s FROM club_members WHERE id = p_member;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','no_session'); END IF;
  PERFORM _club_site_lock(s, false);
  SELECT * INTO m FROM club_members WHERE id = p_member FOR NO KEY UPDATE;
  IF NOT FOUND OR m.confirmed_at IS NULL THEN RETURN jsonb_build_object('error','no_session'); END IF;
  IF m.pending_crew_code IS NULL OR m.pending_crew_status IS NULL THEN RETURN jsonb_build_object('pending', NULL); END IF;
  in_any := EXISTS (SELECT 1 FROM club_crew_members WHERE site_id = m.site_id AND member_id = p_member);
  in_same := EXISTS (SELECT 1 FROM club_crew_members cm JOIN club_crews c ON c.id = cm.crew_id
                     WHERE cm.site_id = m.site_id AND cm.member_id = p_member AND c.code = m.pending_crew_code);
  IF p_action = 'dismiss' OR in_same OR (in_any AND m.pending_crew_status <> 'already_in_crew') THEN
    UPDATE club_members SET pending_crew_code = NULL, pending_crew_status = NULL, pending_crew_checked_at = NULL WHERE id = p_member;
    RETURN jsonb_build_object('pending', NULL);
  END IF;
  IF p_action = 'retry' THEN
    BEGIN
      j := club_crew_join(p_member, m.pending_crew_code);
      st := j->>'error';
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'club_crew_pending retry: %', SQLERRM; j := NULL; st := 'error'; END;
    IF st IS NULL THEN
      UPDATE club_members SET pending_crew_code = NULL, pending_crew_status = NULL, pending_crew_checked_at = NULL WHERE id = p_member;
      RETURN jsonb_build_object('pending', NULL, 'crew_id', j->'crew_id');
    END IF;
    m.pending_crew_status := CASE WHEN st IN ('crew_full','crew_not_found','already_in_crew') THEN st ELSE 'error' END;
    UPDATE club_members SET pending_crew_status = m.pending_crew_status, pending_crew_checked_at = now() WHERE id = p_member;
  END IF;
  SELECT name INTO nm FROM club_crews WHERE site_id = m.site_id AND code = m.pending_crew_code;
  RETURN jsonb_build_object('pending', jsonb_build_object('status', m.pending_crew_status, 'code', m.pending_crew_code, 'crew_name', nm));
END $function$

CREATE OR REPLACE FUNCTION public.club_from_lead_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s uuid; c uuid; mid uuid; is_new boolean; cc text; j jsonb; st text; BEGIN
  IF NEW.source IS DISTINCT FROM 'clube_newgang' OR NEW.email IS NULL THEN RETURN NEW; END IF;
  SELECT id INTO s FROM portal_sites WHERE brand_key = 'newgang' AND active AND company_id = NEW.company_id ORDER BY created_at LIMIT 1;
  IF s IS NULL THEN RETURN NEW; END IF;
  SELECT id INTO c FROM contacts WHERE lower(trim(email)) = lower(trim(NEW.email)) AND company_id = NEW.company_id LIMIT 1;
  mid := club_upsert_member(s, NEW.email, split_part(coalesce(NEW.name,''),' ',1), NEW.phone, c, NEW.raw->>'referral_code', 'formulario');
  IF mid IS NOT NULL AND NEW.raw ? 'terms_version' THEN
    PERFORM club_record_terms(mid, NEW.raw->>'terms_version', NEW.created_at);
  END IF;
  IF mid IS NOT NULL AND coalesce(NEW.raw->>'crew_code','') <> '' THEN
    BEGIN
      cc := upper(trim(NEW.raw->>'crew_code'));
      IF cc !~ '^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{6,7}$' THEN
        RAISE WARNING 'club_from_lead_capture crew_code inválido';
        cc := left(regexp_replace(cc, '[^A-Z0-9]', '', 'g'), 7);
        IF cc <> '' THEN
          UPDATE club_members SET pending_crew_code = cc, pending_crew_status = 'crew_not_found', pending_crew_checked_at = now() WHERE id = mid;
        END IF;
      ELSIF EXISTS (SELECT 1 FROM club_members WHERE id = mid AND confirmed_at IS NOT NULL) THEN
        BEGIN
          j := club_crew_join(mid, cc);
          st := j->>'error';
        EXCEPTION WHEN OTHERS THEN RAISE WARNING 'club_from_lead_capture crew join: %', SQLERRM; st := 'error'; END;
        IF st IS NULL OR (st = 'already_in_crew' AND EXISTS (SELECT 1 FROM club_crew_members cm JOIN club_crews k ON k.id = cm.crew_id WHERE cm.member_id = mid AND k.code = cc)) THEN
          UPDATE club_members SET pending_crew_code = NULL, pending_crew_status = NULL, pending_crew_checked_at = NULL WHERE id = mid;
        ELSE
          UPDATE club_members SET pending_crew_code = cc,
            pending_crew_status = CASE WHEN st IN ('crew_full','crew_not_found','already_in_crew') THEN st ELSE 'error' END,
            pending_crew_checked_at = now() WHERE id = mid;
        END IF;
      ELSE
        UPDATE club_members SET pending_crew_code = cc, pending_crew_status = NULL, pending_crew_checked_at = NULL WHERE id = mid;
      END IF;
    EXCEPTION WHEN OTHERS THEN RAISE WARNING 'club_from_lead_capture crew: %', SQLERRM; END;
  END IF;
  IF mid IS NOT NULL THEN
    BEGIN
      SELECT (source = 'formulario' AND confirmed_at IS NULL AND created_at > now() - interval '1 minute')
        INTO is_new FROM club_members WHERE id = mid;
      IF is_new THEN
        PERFORM net.http_post(
          url := 'https://sfohvvlqccmmebvjgibx.supabase.co/functions/v1/newgang-portal',
          headers := jsonb_build_object('Content-Type','application/json'),
          body := jsonb_build_object('action','notify_member','member_id',mid));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'club_from_lead_capture notify: %', SQLERRM;
    END;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'club_from_lead_capture: %', SQLERRM; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.club_mission_submit(p_member uuid, p_mission uuid, p_url text, p_image text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE mb record; ms record; host text; url text := nullif(trim(p_url),''); img text := nullif(trim(p_image),'');
  st text; sid uuid; BEGIN
  SELECT * INTO mb FROM club_members WHERE id = p_member;
  IF NOT FOUND OR mb.confirmed_at IS NULL THEN RETURN jsonb_build_object('error','no_session'); END IF;
  SELECT * INTO ms FROM club_missions WHERE id = p_mission AND site_id = mb.site_id;
  IF NOT FOUND OR ms.status <> 'ativa' THEN RETURN jsonb_build_object('error','mission'); END IF;
  IF (ms.starts_at IS NOT NULL AND ms.starts_at > now()) OR (ms.ends_at IS NOT NULL AND ms.ends_at <= now()) THEN
    RETURN jsonb_build_object('error','closed'); END IF;
  IF ms.proof_type = 'link' AND url IS NULL THEN RETURN jsonb_build_object('error','proof_link'); END IF;
  IF ms.proof_type = 'imagem' AND img IS NULL THEN RETURN jsonb_build_object('error','proof_image'); END IF;
  IF ms.proof_type = 'link' THEN img := NULL; ELSIF ms.proof_type = 'imagem' THEN url := NULL; END IF;
  IF url IS NULL AND img IS NULL THEN RETURN jsonb_build_object('error','proof'); END IF;
  IF url IS NOT NULL THEN
    host := lower(substring(url from '^https://([^/?#:]+)'));
    IF host IS NULL THEN RETURN jsonb_build_object('error','url'); END IF;
    host := regexp_replace(host, '^(www\.|m\.|vm\.|vt\.)', '');
    IF NOT (
      (ms.network = 'instagram' AND host = 'instagram.com') OR
      (ms.network = 'tiktok' AND host = 'tiktok.com') OR
      (ms.network = 'qualquer' AND host IN ('instagram.com','tiktok.com','youtube.com','youtu.be','x.com','twitter.com','facebook.com','fb.watch'))
    ) THEN RETURN jsonb_build_object('error','network'); END IF;
    IF EXISTS (SELECT 1 FROM club_mission_submissions WHERE proof_url = url AND member_id <> p_member) THEN
      RETURN jsonb_build_object('error','duplicate'); END IF;
  END IF;
  IF img IS NOT NULL AND (img NOT LIKE mb.company_id::text || '/' || p_member::text || '/%'
       OR lower(img) !~ '\.(jpg|jpeg|png|webp)$' OR img LIKE '%..%') THEN
    RETURN jsonb_build_object('error','image'); END IF;
  IF EXISTS (SELECT 1 FROM club_mission_submissions WHERE mission_id = p_mission AND member_id = p_member AND status <> 'rejeitada') THEN
    RETURN jsonb_build_object('error','already_submitted'); END IF;
  st := CASE WHEN ms.kind = 'postar' AND ms.approval = 'automatica' THEN 'aprovada' ELSE 'pendente' END;
  INSERT INTO club_mission_submissions(company_id, mission_id, member_id, proof_url, proof_image_path, status, auto_approved, reviewed_at)
    VALUES (mb.company_id, p_mission, p_member, url, img, st, st = 'aprovada', CASE WHEN st = 'aprovada' THEN now() END)
    RETURNING id INTO sid;
  PERFORM club_mission_sync_points(sid);
  RETURN jsonb_build_object('status', st, 'submission_id', sid);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('error','already_submitted');
END $function$

CREATE OR REPLACE FUNCTION public.club_mission_sync_points(p_sub uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; why text; BEGIN
  SELECT x.*, m.points AS m_points, m.finalist_points, m.winner_points INTO s
    FROM club_mission_submissions x JOIN club_missions m ON m.id = x.mission_id WHERE x.id = p_sub;
  IF NOT FOUND THEN RETURN; END IF;
  why := CASE WHEN s.status = 'rejeitada' THEN coalesce(s.reject_reason, 'Submissão rejeitada')
              ELSE 'Estado da submissão alterado para ' || s.status END;
  PERFORM club_points_set(s.member_id, 'mission', p_sub::text, s.m_points, s.status IN ('aprovada','finalista','vencedora'), why);
  PERFORM club_points_set(s.member_id, 'mission_finalist', p_sub::text, s.finalist_points, s.status IN ('finalista','vencedora'), why);
  PERFORM club_points_set(s.member_id, 'mission_winner', p_sub::text, s.winner_points, s.status = 'vencedora', why);
END $function$

CREATE OR REPLACE FUNCTION public.club_points_cutover(p_config uuid, p_expected_levels jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c club_points_config; s uuid; ev uuid; before jsonb; after jsonb; rb jsonb; ra jsonb; nf int; nm int; nl int := 0; k text; BEGIN
  SELECT site_id INTO s FROM club_points_config WHERE id = p_config;
  IF NOT FOUND THEN RAISE EXCEPTION 'cutover: config inexistente'; END IF;
  PERFORM _club_site_lock(s, true);                 -- espera pelos créditos em curso; novos esperam por nós
  SELECT * INTO c FROM club_points_config WHERE id = p_config FOR UPDATE;
  IF c.status <> 'draft' THEN RAISE EXCEPTION 'cutover: config não está em draft'; END IF;
  SELECT event_id INTO ev FROM portal_sites WHERE id = s;
  IF ev IS DISTINCT FROM c.event_id THEN RAISE EXCEPTION 'cutover: site aponta para % e a config para %', ev, c.event_id; END IF;
  SELECT jsonb_object_agg(name, min_points) INTO before FROM club_levels WHERE site_id = s;
  IF before IS DISTINCT FROM p_expected_levels THEN RAISE EXCEPTION 'cutover: níveis atuais % <> esperados %', before, p_expected_levels; END IF;
  IF c.legacy_counts THEN
    INSERT INTO club_legacy_consumption(company_id, site_id, event_id, config_id, member_id, rule_key, points, rows_counted, first_at, last_at)
    SELECT c.company_id, s, c.event_id, c.id, p.member_id, p.rule_key, sum(p.points)::int, count(*)::int, min(p.created_at), max(p.created_at)
      FROM club_points p JOIN club_members cm ON cm.id = p.member_id
     WHERE cm.site_id = s AND p.event_id IS NULL
       AND p.rule_key IN ('join_confirmed','friend_joined','crew_complete','promo_lot_purchase')
       AND NOT EXISTS (SELECT 1 FROM club_points v WHERE v.member_id = p.member_id AND v.rule_key = 'void' AND v.ref_id = p.rule_key || ':' || p.ref_id)
     GROUP BY p.member_id, p.rule_key
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS nl = ROW_COUNT;
    -- Indicados confirmados antes do patch (sem registo de contagem): entram na contagem desta edição.
    INSERT INTO club_referral_events(company_id, site_id, member_id, referee_id, event_id, credited_points, source, created_at)
    SELECT x.company_id, s, x.referred_by_member_id, x.id, c.event_id,
           coalesce((SELECT sum(p.points) FROM club_points p WHERE p.member_id = x.referred_by_member_id AND p.rule_key = 'friend_joined' AND p.ref_id = x.id::text AND p.event_id IS NULL),0)::int,
           'legacy_snapshot', x.confirmed_at
      FROM club_members x
     WHERE x.site_id = s AND x.confirmed_at IS NOT NULL AND x.referred_by_member_id IS NOT NULL AND x.referred_by_member_id <> x.id
    ON CONFLICT (member_id, referee_id) DO NOTHING;
  END IF;
  INSERT INTO club_level_floors(member_id, config_id, company_id, site_id, level_id, level_name, points_at_cutover)
  SELECT cm.id, c.id, cm.company_id, s, l.id, l.name, t.pts
    FROM club_members cm
    CROSS JOIN LATERAL (SELECT coalesce(sum(points),0)::bigint pts FROM club_points WHERE member_id = cm.id) t
    CROSS JOIN LATERAL (SELECT * FROM club_levels l WHERE l.site_id = s AND l.min_points <= t.pts ORDER BY l.min_points DESC LIMIT 1) l
   WHERE cm.site_id = s AND l.min_points > 0
  ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS nf = ROW_COUNT;
  SELECT count(*) INTO nm FROM club_members WHERE site_id = s;
  FOR k IN SELECT jsonb_object_keys(c.levels) LOOP
    UPDATE club_levels SET min_points = (c.levels->>k)::int WHERE site_id = s AND name = k;
    IF NOT FOUND THEN RAISE EXCEPTION 'cutover: nível % não existe', k; END IF;
  END LOOP;
  SELECT jsonb_object_agg(name, min_points) INTO after FROM club_levels WHERE site_id = s;
  -- Regras visíveis (site, crew_cfg, CRM) = valores que o motor paga. Só as 4 regras aprovadas; as restantes intactas.
  SELECT jsonb_object_agg(rule_key, jsonb_build_object('points', points, 'active', active)) INTO rb FROM club_point_rules WHERE site_id = s;
  UPDATE club_point_rules SET points = CASE rule_key WHEN 'join_confirmed' THEN c.join_points WHEN 'friend_joined' THEN c.referral_points
           WHEN 'crew_complete' THEN c.crew_points WHEN 'promo_lot_purchase' THEN c.purchase_points END
   WHERE site_id = s AND rule_key IN ('join_confirmed','friend_joined','crew_complete','promo_lot_purchase');
  SELECT jsonb_object_agg(rule_key, jsonb_build_object('points', points, 'active', active)) INTO ra FROM club_point_rules WHERE site_id = s;
  UPDATE club_points_config SET status = 'retired' WHERE site_id = s AND status = 'active';
  UPDATE club_points_config SET status = 'active', effective_at = clock_timestamp() WHERE id = c.id;
  INSERT INTO club_points_cutover_log(config_id, company_id, site_id, site_event_id, levels_before, levels_after, rules_before, rules_after,
                                      members_total, floors_created, legacy_rows)
    VALUES (c.id, c.company_id, s, ev, before, after, coalesce(rb,'{}'), coalesce(ra,'{}'), nm, nf, nl);
  RETURN jsonb_build_object('levels_before', before, 'levels_after', after, 'rules_before', rb, 'rules_after', ra,
                            'members', nm, 'floors', nf, 'legacy_rows', nl);
END $function$

CREATE OR REPLACE FUNCTION public.club_points_set(p_member uuid, p_rule text, p_base text, p_points integer, p_want boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a club_points; g int; ref text; BEGIN
  a := club_points_active(p_member, p_rule, p_base);
  IF p_want THEN
    IF a.id IS NOT NULL OR coalesce(p_points,0) <= 0 THEN RETURN; END IF;
    SELECT count(*) INTO g FROM club_points WHERE member_id = p_member AND rule_key = p_rule AND (ref_id = p_base OR ref_id LIKE p_base || '#%');
    ref := CASE WHEN g = 0 THEN p_base ELSE p_base || '#' || (g + 1) END;
    PERFORM club_award_fixed(p_member, p_rule, ref, p_points);
  ELSE
    PERFORM _club_points_void_row(a, p_reason);
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.club_profile_configure(p_site uuid, p_version text, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; BEGIN
 IF p_version IS DISTINCT FROM 'profile-v1' OR p_enabled IS NULL THEN RAISE EXCEPTION 'profile_config_invalid'; END IF;
 PERFORM _club_site_lock(p_site,true);
 SELECT * INTO s FROM portal_sites WHERE id=p_site AND domain='newgangfestival.pt' AND brand_key='newgang' AND active;
 IF NOT FOUND THEN RAISE EXCEPTION 'profile_site_invalid'; END IF;
 INSERT INTO club_profile_settings(site_id,company_id,enabled) VALUES(s.id,s.company_id,p_enabled)
 ON CONFLICT(site_id) DO UPDATE SET enabled=EXCLUDED.enabled;
 INSERT INTO club_point_rules(company_id,site_id,rule_key,label,points,active) VALUES(s.company_id,s.id,'profile_complete','Completa o teu perfil',50,p_enabled)
 ON CONFLICT(site_id,rule_key) DO UPDATE SET points=50,active=EXCLUDED.active;
END $function$

CREATE OR REPLACE FUNCTION public.club_profile_confirm(p_site uuid, p_session_hash text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; s club_profile_settings; p club_member_profiles; bd date; bc text; rc text; ct text; ev uuid; aid uuid; gained int:=0; BEGIN
 -- Identité résolue depuis la session; aucun member/company/event fourni par le client.
 SELECT cm.* INTO m FROM club_member_sessions x JOIN club_members cm ON cm.id=x.member_id JOIN portal_sites ps ON ps.id=cm.site_id AND ps.company_id=cm.company_id
 WHERE x.site_id=p_site AND cm.site_id=p_site AND x.token_hash=p_session_hash AND x.purpose='access' AND x.expires_at>statement_timestamp() AND cm.confirmed_at IS NOT NULL AND ps.active AND ps.brand_key='newgang';
 IF NOT FOUND THEN RAISE EXCEPTION 'no_session'; END IF;
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('confirm','birth_date','birth_country','residence_country','city','phone','op')) THEN RAISE EXCEPTION 'profile_payload'; END IF;
 PERFORM _club_site_lock(p_site,false);
 PERFORM 1 FROM club_members WHERE id=m.id FOR NO KEY UPDATE;
 IF NOT EXISTS(SELECT 1 FROM club_member_sessions WHERE token_hash=p_session_hash AND site_id=p_site AND member_id=m.id AND purpose='access' AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'no_session'; END IF;
 SELECT * INTO p FROM club_member_profiles WHERE member_id=m.id;
 SELECT * INTO s FROM club_profile_settings WHERE site_id=p_site AND company_id=m.company_id;
 IF p_payload->>'op'='clear' THEN
  IF p_payload<>jsonb_build_object('op','clear') THEN RAISE EXCEPTION 'profile_payload'; END IF;
  UPDATE club_member_profiles SET birth_date=NULL,birth_country=NULL,residence_country=NULL,city=NULL,updated_at=now() WHERE member_id=m.id;
  RETURN jsonb_build_object('ok',true,'awarded',0,'profile',club_profile_state(p_site,p_session_hash));
 END IF;
 IF p_payload ? 'op' OR p_payload->'confirm' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'profile_confirmation_required'; END IF;
 IF jsonb_typeof(p_payload->'birth_date') IS DISTINCT FROM 'string' OR (p_payload->>'birth_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'birth_date_invalid'; END IF;
 BEGIN bd:=(p_payload->>'birth_date')::date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'birth_date_invalid'; END;
 IF NOT isfinite(bd) OR bd>(now() AT TIME ZONE 'Europe/Lisbon')::date THEN RAISE EXCEPTION 'birth_date_invalid'; END IF;
 IF bd>((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '13 years')::date THEN RAISE EXCEPTION 'parental_flow_required'; END IF;
 IF jsonb_typeof(p_payload->'birth_country') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'country_invalid'; END IF;
 bc:=upper(btrim(p_payload->>'birth_country'));
 IF NOT EXISTS(SELECT 1 FROM club_profile_countries WHERE code=bc) THEN RAISE EXCEPTION 'country_invalid'; END IF;
 IF jsonb_typeof(p_payload->'residence_country') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'country_invalid'; END IF;
 rc:=nullif(upper(btrim(p_payload->>'residence_country')),'');
 IF NOT EXISTS(SELECT 1 FROM club_profile_countries WHERE code=rc) THEN RAISE EXCEPTION 'country_invalid'; END IF;
 IF p_payload ? 'city' AND p_payload->'city'<>'null'::jsonb AND jsonb_typeof(p_payload->'city') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'city_invalid'; END IF;
 ct:=public.club_city_normalize(rc,p_payload->>'city');
 IF p_payload ? 'phone' AND p_payload->'phone'<>'null'::jsonb AND (jsonb_typeof(p_payload->'phone') IS DISTINCT FROM 'string' OR (p_payload->>'phone') !~ '^\+[1-9][0-9]{7,14}$') THEN RAISE EXCEPTION 'phone_invalid'; END IF;
 IF NOT coalesce(s.enabled,false) THEN RAISE EXCEPTION 'profile_unavailable'; END IF;
 SELECT event_id INTO ev FROM portal_sites WHERE id=p_site AND company_id=m.company_id;
 IF ev IS NULL OR NOT EXISTS(SELECT 1 FROM events WHERE id=ev AND company_id=m.company_id) THEN RAISE EXCEPTION 'profile_event_invalid'; END IF;
 INSERT INTO club_member_profiles(member_id,site_id,company_id,birth_date,birth_country,residence_country,city)
 VALUES(m.id,p_site,m.company_id,bd,bc,rc,ct) ON CONFLICT(member_id) DO UPDATE SET birth_date=EXCLUDED.birth_date,birth_country=EXCLUDED.birth_country,residence_country=EXCLUDED.residence_country,city=EXCLUDED.city,updated_at=now();
 IF p_payload ? 'phone' THEN UPDATE club_members SET phone=p_payload->>'phone',updated_at=now() WHERE id=m.id; END IF;
 IF p.completed_at IS NULL THEN
  UPDATE club_member_profiles SET completed_at=now(),award_event_id=ev WHERE member_id=m.id;
  gained:=_club_award_core(m.id,'profile_complete',m.id::text,50,NULL);
  IF gained<>50 THEN RAISE EXCEPTION 'profile_credit_failed'; END IF;
  SELECT id INTO aid FROM club_points WHERE member_id=m.id AND rule_key='profile_complete';
  UPDATE club_member_profiles SET award_id=aid WHERE member_id=m.id;
 END IF;
 RETURN jsonb_build_object('ok',true,'awarded',gained,'profile',club_profile_state(p_site,p_session_hash));
END $function$

CREATE OR REPLACE FUNCTION public.club_profile_state(p_site uuid, p_session_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE m record; p club_member_profiles; s club_profile_settings; n int; BEGIN
 SELECT cm.* INTO m FROM club_member_sessions x JOIN club_members cm ON cm.id=x.member_id
 JOIN portal_sites ps ON ps.id=cm.site_id AND ps.company_id=cm.company_id
 WHERE x.site_id=p_site AND cm.site_id=p_site AND x.token_hash=p_session_hash AND x.purpose='access' AND x.expires_at>statement_timestamp() AND cm.confirmed_at IS NOT NULL AND ps.active AND ps.brand_key='newgang';
 IF NOT FOUND THEN RAISE EXCEPTION 'no_session'; END IF;
 SELECT * INTO p FROM club_member_profiles WHERE member_id=m.id;
 SELECT * INTO s FROM club_profile_settings WHERE site_id=p_site;
 SELECT coalesce(sum(points),0)::int INTO n FROM club_points WHERE member_id=m.id AND (rule_key='profile_complete' OR (rule_key='void' AND ref_id='profile_complete:'||m.id::text));
 RETURN jsonb_build_object('birth_date',p.birth_date,'birth_country',p.birth_country,'residence_country',p.residence_country,'city',p.city,'phone',m.phone,
  'complete',p.birth_date IS NOT NULL AND p.birth_country IS NOT NULL AND p.residence_country IS NOT NULL AND (p.residence_country IS DISTINCT FROM 'PT' OR p.city IS NOT NULL),
  'completed_at',p.completed_at,'reward_claimed',p.completed_at IS NOT NULL,'eligible',coalesce(s.enabled,false) AND p.completed_at IS NULL,
  'available',coalesce(s.enabled,false),'points',n,'reward_points',50,'version',s.version,'scope','adesao','whatsapp',jsonb_build_object('status','adapter_pending','editable',false));
END $function$

CREATE OR REPLACE FUNCTION public.club_purchase_revoke(p_evidence uuid, p_status text, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e record; r club_points; BEGIN
  IF p_status IS NULL OR p_status NOT IN ('refunded','cancelled') OR coalesce(btrim(p_reason),'') = '' THEN
    RAISE EXCEPTION 'club_purchase_revoke: estado/motivo inválido' USING ERRCODE = '22023'; END IF;
  SELECT * INTO e FROM club_purchase_evidence WHERE id = p_evidence; IF NOT FOUND THEN RETURN 0; END IF;
  PERFORM _club_site_lock(e.site_id, false);          -- ordem global: site → linha
  SELECT * INTO e FROM club_purchase_evidence WHERE id = p_evidence FOR UPDATE; IF NOT FOUND THEN RETURN 0; END IF;
  UPDATE club_purchase_evidence SET status = p_status, status_reason = p_reason WHERE id = p_evidence;
  IF e.credited_ref IS NULL THEN RETURN 0; END IF;
  SELECT * INTO r FROM club_points WHERE member_id = e.member_id AND rule_key = 'promo_lot_purchase' AND ref_id = e.credited_ref;
  RETURN _club_points_void_row(r, p_reason);
END $function$

CREATE OR REPLACE FUNCTION public.club_record_terms(p_member uuid, p_version text, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v int; BEGIN
  IF p_member IS NULL OR p_version IS NULL OR trim(p_version) !~ '^[0-9]{1,6}$' THEN
    IF p_version IS NOT NULL THEN RAISE WARNING 'club_record_terms: versão inválida %', p_version; END IF;
    RETURN false;
  END IF;
  v := trim(p_version)::int;
  IF NOT EXISTS (SELECT 1 FROM club_terms t JOIN club_members m ON m.site_id = t.site_id
                  WHERE m.id = p_member AND t.version = v AND t.status = 'publicada') THEN
    RAISE WARNING 'club_record_terms: versão % não publicada', v; RETURN false;
  END IF;
  UPDATE club_members SET terms_version = v, terms_accepted_at = coalesce(p_at, now()), updated_at = now() WHERE id = p_member;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'club_record_terms: %', SQLERRM; RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.club_upsert_member(p_site uuid, p_email text, p_first_name text, p_phone text, p_contact uuid, p_referral text, p_source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s record; mid uuid; ref uuid; e text := lower(trim(p_email)); BEGIN
  IF e IS NULL OR e = '' THEN RETURN NULL; END IF;
  SELECT * INTO s FROM portal_sites WHERE id = p_site; IF NOT FOUND THEN RETURN NULL; END IF;
  -- #328: identidade = site + email normalizado (telefone nunca identifica). Lock ANTES da procura.
  PERFORM pg_advisory_xact_lock(hashtext('club_member_email:'||p_site||':'||e));
  SELECT id INTO mid FROM club_members WHERE site_id = p_site AND lower(trim(email)) = e;
  IF mid IS NOT NULL THEN
    UPDATE club_members SET contact_id = coalesce(contact_id, p_contact), first_name = coalesce(first_name, p_first_name),
      phone = coalesce(phone, nullif(p_phone,'')), updated_at = now() WHERE id = mid;
    RETURN mid;
  END IF;
  IF p_referral IS NOT NULL THEN
    SELECT id INTO ref FROM club_members WHERE site_id = p_site AND referral_code = upper(trim(p_referral));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('club_member_no:'||p_site));
  INSERT INTO club_members(company_id, site_id, contact_id, email, phone, first_name, member_no, referral_code, referred_by_member_id, source)
  VALUES (s.company_id, p_site, p_contact, e, nullif(p_phone,''), nullif(p_first_name,''),
          coalesce((SELECT max(member_no) FROM club_members WHERE site_id = p_site),0) + 1,
          club_gen_referral_code(), ref, p_source)
  ON CONFLICT (site_id, (lower(trim(email)))) DO NOTHING
  RETURNING id INTO mid;
  IF mid IS NULL THEN
    SELECT id INTO mid FROM club_members WHERE site_id = p_site AND lower(trim(email)) = e;
  END IF;
  RETURN mid;
END $function$

CREATE OR REPLACE FUNCTION public.coala_send_eb_invite_batch(p_daily_cap integer, p_dry_run boolean, p_only_emails text[], p_test_emails text[], p_test_locale text DEFAULT 'pt'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  COALA constant uuid := '7d831e59-6e82-427b-95a0-64904aae5dd2';
  FROM_LINE constant text := 'Coala Festival <noreply@news.coalafestival.pt>';
  SENDER_DOM constant text := 'news.coalafestival.pt';
  v_counts jsonb;
  v_sample jsonb;
  v_today int;
  v_room int;
  v_queued int := 0;
  r record;
  v_token text; v_url text; v_mid text;
  v_unsub_token text; v_unsub_url text; v_unsub_http text;
  v_subject text; v_html text; v_text text;
  v_only text[];
  v_test text[];
begin
  if p_dry_run is null then raise exception 'p_dry_run nao pode ser NULL'; end if;
  if p_test_locale is null or p_test_locale not in ('pt', 'en') then
    raise exception 'p_test_locale deve ser pt ou en';
  end if;
  if p_test_emails is not null and exists (select 1 from unnest(p_test_emails) e where e is null or btrim(e) !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$') then
    raise exception 'p_test_emails contem endereco invalido';
  end if;
  v_test := (select array_agg(distinct lower(btrim(e))) from unnest(p_test_emails) e);
  v_only := case when p_only_emails is null then null
                 else (select array_agg(lower(btrim(e))) from unnest(p_only_emails) e) end;

  -- D-ERP276: estado de entrega por email (base + reenvios :r<n>), uma leitura do log.
  drop table if exists _invlog;
  create temp table _invlog on commit drop as
  select x.e, bool_or(x.status = 'sent') has_sent,
         (array_agg(x.status order by x.created_at desc))[1] last_status,
         count(distinct x.message_id) filter (where x.message_id ~ ':r[0-9]+$') n_reenvios
    from (select regexp_replace(substr(l.message_id, 14), ':r[0-9]+$', '') e, l.message_id, l.status, l.created_at
            from public.email_send_log l where l.message_id like 'coala-eb-inv:%') x
   group by x.e;

  create temp table _inv on commit drop as
  with fb as (
    select lower(btrim(email)) e,
           (array_agg(language order by imported_at desc))[1] lang
      from public.fever_buyers
     where company_id = COALA and edition_label = 'coala-2026'
       and email is not null and btrim(email) <> ''
     group by 1
  )
  select fb.e, case when fb.lang = 'Pt' then 'pt' else 'en' end loc,
    case
      when exists (select 1 from public.suppressed_emails s where s.company_id = COALA and s.email = fb.e) then 'suprimido'
      when exists (select 1 from public.email_unsubscribe_tokens t where t.company_id = COALA and t.email = fb.e and t.used_at is not null) then 'descadastrado'
      when exists (select 1 from public.coala_list_members m where m.email = fb.e) then 'ja_na_lista'
      when exists (select 1 from public.coala_invites i where i.company_id = COALA and i.campaign = 'eb2027_invite' and i.email = fb.e) then 'ja_convidado'
      else null end motivo,
    exists (select 1 from public.coala_invites i
              join _invlog g on g.e = i.email
             where i.company_id = COALA and i.campaign = 'eb2027_invite' and i.email = fb.e
               and i.status <> 'confirmed' and g.last_status = 'dlq' and not g.has_sent) reenvio
    from fb;

  select jsonb_build_object(
    'emails_unicos', count(*),
    'excluidos', jsonb_build_object(
      'suprimido', count(*) filter (where motivo = 'suprimido'),
      'descadastrado', count(*) filter (where motivo = 'descadastrado'),
      'ja_na_lista', count(*) filter (where motivo = 'ja_na_lista'),
      'ja_convidado', count(*) filter (where motivo = 'ja_convidado')),
    'a_convidar', count(*) filter (where motivo is null),
    'reenvio_pendente', count(*) filter (where motivo = 'ja_convidado' and reenvio),
    'por_idioma', jsonb_build_object(
      'pt', count(*) filter (where motivo is null and loc = 'pt'),
      'en', count(*) filter (where motivo is null and loc = 'en')))
  into v_counts from _inv;

  -- Internal test recipients are added after base counts; never mutate fever_buyers.
  insert into _inv (e, loc, motivo, reenvio)
  select distinct e, 'pt'::text, null::text, false
    from unnest(v_only) as requested(e)
   where e ~ '^[^@[:space:]]+@mundopropicio[.]com$'
     and not exists (select 1 from _inv base where base.e = requested.e);

  -- Test mode selects only requested addresses; base counts stay unchanged.
  create temp table _eb_recipients on commit drop as
  select e, loc, false reenvio from _inv where p_test_emails is null and motivo is null
    and (v_only is null or e = any(v_only))
  union all
  -- Reenvio de convites perdidos (DLQ, sem 'sent'): mesmo token/confirm_url do convite.
  select inv.e, i.locale, true from _inv inv
    join public.coala_invites i on i.company_id = COALA and i.campaign = 'eb2027_invite' and i.email = inv.e
   where p_test_emails is null and inv.motivo = 'ja_convidado' and inv.reenvio
     and (v_only is null or inv.e = any(v_only))
  union all
  select e, coalesce((select case when fb.language = 'Pt' then 'pt' else 'en' end
    from public.fever_buyers fb where fb.company_id = COALA
      and fb.edition_label = 'coala-2026' and lower(btrim(fb.email)) = requested.e
    order by fb.imported_at desc limit 1), p_test_locale), false
  from unnest(v_test) requested(e)
  where not exists (select 1 from public.suppressed_emails s
    where s.company_id = COALA and lower(btrim(s.email)) = requested.e);

  select coalesce(jsonb_agg(jsonb_build_object('email', e, 'locale', loc,
           'confirm_url', 'https://coalafestival.pt/' || loc || '/confirmar?t=<token gerado no envio>')), '[]'::jsonb)
    into v_sample
    from (select e, loc from _eb_recipients order by md5(e), e
           limit case when p_test_emails is null then 3 else NULL end) s;

  if p_dry_run then
    return jsonb_build_object('dry_run', true, 'contagens', v_counts, 'amostra', v_sample,
      'only_emails', v_only, 'test', p_test_emails is not null, 'test_emails', v_test,
      'ordem', 'md5(email)',
      'primeiros', (select jsonb_build_object(
          '250', jsonb_build_object('pt', count(*) filter (where rn <= 250 and loc = 'pt'), 'en', count(*) filter (where rn <= 250 and loc = 'en')),
          '1000', jsonb_build_object('pt', count(*) filter (where rn <= 1000 and loc = 'pt'), 'en', count(*) filter (where rn <= 1000 and loc = 'en')))
        from (select loc, row_number() over (order by md5(e), e) rn from _eb_recipients) o),
      'ts', now());
  end if;

  if p_test_emails is null and (p_daily_cap is null or p_daily_cap < 1) then
    raise exception 'p_daily_cap obrigatorio fora do dry run';
  end if;

  if p_test_emails is not null then
    v_today := 0;
    select count(*) into v_room from _eb_recipients;
  else
    select count(*) into v_today from public.coala_invites
     where company_id = COALA and campaign = 'eb2027_invite'
       and (queued_at at time zone 'Europe/Lisbon')::date = (now() at time zone 'Europe/Lisbon')::date;
    v_room := greatest(p_daily_cap - v_today, 0);
  end if;

  for r in select e, loc, reenvio from _eb_recipients order by md5(e), e limit v_room
  loop
    v_token := encode(extensions.gen_random_bytes(32), 'hex');
    v_url := 'https://coalafestival.pt/' || r.loc || '/confirmar?t=' || v_token;
    if r.reenvio then
      v_mid := 'coala-eb-inv:' || r.e || ':r' || (coalesce((select g.n_reenvios from _invlog g where g.e = r.e), 0) + 1);
      update public.coala_invites
         set message_id = v_mid, queued_at = now()
       where company_id = COALA and campaign = 'eb2027_invite' and email = r.e and status <> 'confirmed'
      returning token, confirm_url into v_token, v_url;
      if not found then continue; end if;
    elsif p_test_emails is not null then
      v_mid := 'coala-eb-test:' || r.e || ':' || extract(epoch from clock_timestamp())::bigint;
      insert into public.coala_invites (company_id, campaign, email, token, confirm_url, locale, message_id)
      values (COALA, 'eb2027_invite_test', r.e, v_token, v_url, r.loc, v_mid)
      on conflict (company_id, campaign, email) do update
        set token = excluded.token, confirm_url = excluded.confirm_url, locale = excluded.locale,
            status = 'queued', queued_at = now(), confirmed_at = NULL, message_id = excluded.message_id;
    else
      v_mid := 'coala-eb-inv:' || r.e;
