CREATE OR REPLACE FUNCTION public.coala_send_eb_open_alert(p_daily_cap integer DEFAULT NULL::integer, p_dry_run boolean DEFAULT true, p_only_emails text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  COALA constant uuid := '7d831e59-6e82-427b-95a0-64904aae5dd2';
  FROM_LINE constant text := 'Coala Festival <noreply@news.coalafestival.pt>';
  SENDER_DOM constant text := 'news.coalafestival.pt';
  v_fever text;
  v_counts jsonb; v_sample jsonb;
  v_today int; v_room int; v_queued int := 0;
  r record; v_mid text;
  v_unsub_token text; v_unsub_url text; v_unsub_http text;
  v_subject text; v_html text; v_text text;
  v_only text[];
begin
  v_only := case when p_only_emails is null then null
                 else (select array_agg(lower(btrim(e))) from unnest(p_only_emails) e) end;

  select nullif(btrim(value #>> '{}'), '') into v_fever
    from public.portal_settings where company_id = COALA and key = 'early_bird.fever_url' limit 1;

  drop table if exists _alertlog;
  create temp table _alertlog on commit drop as
  select x.e, bool_or(x.status = 'sent') has_sent,
         (array_agg(x.status order by x.created_at desc))[1] last_status,
         count(distinct x.message_id) filter (where x.message_id ~ ':r[0-9]+$') n_reenvios
    from (select regexp_replace(substr(l.message_id, 15), ':r[0-9]+$', '') e, l.message_id, l.status, l.created_at
            from public.email_send_log l where l.message_id like 'coala-eb-open:%') x
   group by x.e;

  drop table if exists _alert;
  create temp table _alert on commit drop as
  select m.email e,
    coalesce(
      (select i.locale from public.coala_invites i where i.company_id = COALA and i.email = m.email and i.status = 'confirmed' limit 1),
      (select case when lower(lc.raw->>'locale') = 'en' then 'en' else 'pt' end from public.lead_capture lc
        where lc.company_id = COALA and lower(btrim(lc.email)) = m.email order by lc.created_at desc limit 1),
      'pt') loc,
    case
      when exists (select 1 from public.suppressed_emails s where s.company_id = COALA and s.email = m.email) then 'suprimido'
      when exists (select 1 from public.email_unsubscribe_tokens t where t.company_id = COALA and t.email = m.email and t.used_at is not null) then 'descadastrado'
      when exists (select 1 from _alertlog g where g.e = m.email) then 'ja_enviado'
      else null end motivo,
    coalesce((select g.last_status = 'dlq' and not g.has_sent from _alertlog g where g.e = m.email), false) reenvio,
    coalesce((select g.n_reenvios from _alertlog g where g.e = m.email), 0) n_reenvios
  from public.coala_list_members m;

  select jsonb_build_object('na_lista', count(*),
    'excluidos', jsonb_build_object(
      'suprimido', count(*) filter (where motivo = 'suprimido'),
      'descadastrado', count(*) filter (where motivo = 'descadastrado'),
      'ja_enviado', count(*) filter (where motivo = 'ja_enviado')),
    'a_enviar', count(*) filter (where motivo is null),
    'reenvio_pendente', count(*) filter (where motivo = 'ja_enviado' and reenvio),
    'por_idioma', jsonb_build_object(
      'pt', count(*) filter (where motivo is null and loc = 'pt'),
      'en', count(*) filter (where motivo is null and loc = 'en')))
  into v_counts from _alert;

  select coalesce(jsonb_agg(jsonb_build_object('email', e, 'locale', loc)), '[]'::jsonb) into v_sample
    from (select e, loc from _alert where (motivo is null or (motivo = 'ja_enviado' and reenvio)) and (v_only is null or e = any(v_only)) order by md5(e), e limit 3) s;

  if p_dry_run then
    return jsonb_build_object('dry_run', true, 'fever_url', coalesce(v_fever, '(vazio)'),
      'contagens', v_counts, 'amostra', v_sample, 'only_emails', v_only, 'ts', now());
  end if;

  if v_fever is null then
    raise exception 'early_bird.fever_url esta vazio em portal_settings (empresa Coala).';
  end if;
  if p_daily_cap is null or p_daily_cap < 1 then
    raise exception 'p_daily_cap obrigatorio fora do dry run';
  end if;

  select coalesce(sum(queued), 0) into v_today from public.coala_send_runs
   where company_id = COALA and function_name = 'coala_send_eb_open_alert'
     and (created_at at time zone 'Europe/Lisbon')::date = (now() at time zone 'Europe/Lisbon')::date;
  v_room := greatest(p_daily_cap - v_today, 0);

  for r in select e, loc, reenvio, n_reenvios from _alert
            where (motivo is null or (motivo = 'ja_enviado' and reenvio))
              and (v_only is null or e = any(v_only)) order by md5(e), e limit v_room
  loop
    v_mid := 'coala-eb-open:' || r.e || case when r.reenvio then ':r' || (r.n_reenvios + 1) else '' end;
    v_unsub_token := public.coala_unsub_token(r.e);
    v_unsub_url := 'https://coalafestival.pt/unsubscribe?token=' || v_unsub_token || '&lang=' || r.loc;
    v_unsub_http := 'https://sfohvvlqccmmebvjgibx.supabase.co/functions/v1/handle-email-unsubscribe?token=' || v_unsub_token;
    if r.loc = 'en' then
      v_subject := 'Early Bird 2027 is open — Coala Festival';
      v_html := '<div style="font-family:Helvetica,Arial,sans-serif;background:#FFFBF5;padding:32px;color:#141414"><img src="https://coalafestival.pt/email/logo.png" width="200" alt="Coala Festival Portugal" style="display:block;margin:0 auto 24px"/><p>Hi,</p><p>You are on the list: Early Bird tickets for Coala Festival Portugal 2027 are now open.</p><p style="text-align:center"><a href="' || v_fever || '" style="background:#141414;color:#FFFBF5;padding:14px 24px;text-decoration:none;border-radius:6px">Buy ticket</a></p></div>';
      v_text := 'Early Bird 2027 is open: ' || v_fever || E'\nUnsubscribe: ' || v_unsub_url;
    else
      v_subject := 'O Early Bird 2027 abriu — Coala Festival';
      v_html := '<div style="font-family:Helvetica,Arial,sans-serif;background:#FFFBF5;padding:32px;color:#141414"><img src="https://coalafestival.pt/email/logo.png" width="200" alt="Coala Festival Portugal" style="display:block;margin:0 auto 24px"/><p>Olá,</p><p>Estás na lista: os bilhetes Early Bird do Coala Festival Portugal 2027 já abriram.</p><p style="text-align:center"><a href="' || v_fever || '" style="background:#141414;color:#FFFBF5;padding:14px 24px;text-decoration:none;border-radius:6px">Comprar bilhete</a></p></div>';
      v_text := 'O Early Bird 2027 abriu: ' || v_fever || E'\nCancelar subscricao: ' || v_unsub_url;
    end if;
    perform public.enqueue_email('transactional_emails', jsonb_build_object(
      'company_id', COALA, 'message_id', v_mid, 'to', r.e, 'from', FROM_LINE,
      'sender_domain', SENDER_DOM, 'subject', v_subject, 'html', v_html, 'text', v_text,
      'purpose', 'marketing', 'label', 'coala_eb_open_alert', 'idempotency_key', v_mid,
      'unsubscribe_token', v_unsub_token, 'unsubscribe_url', v_unsub_url,
      'unsubscribe_http_url', v_unsub_http,
      'queued_at', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
    v_queued := v_queued + 1;
  end loop;

  insert into public.coala_send_runs (company_id, function_name, daily_cap, queued, details)
  values (COALA, 'coala_send_eb_open_alert', p_daily_cap, v_queued,
          jsonb_build_object('contagens', v_counts, 'only_emails', v_only));

  return jsonb_build_object('dry_run', false, 'queued', v_queued, 'ja_hoje', v_today, 'contagens', v_counts);
end
$function$

CREATE OR REPLACE FUNCTION public.coala_unsub_token(p_email text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  COALA constant uuid := '7d831e59-6e82-427b-95a0-64904aae5dd2';
  v_email text := lower(btrim(p_email));
  v_token text;
begin
  select token into v_token
    from public.email_unsubscribe_tokens
   where email = v_email and company_id = COALA
   limit 1;

  if v_token is null then
    v_token := encode(extensions.gen_random_bytes(32), 'hex');
    insert into public.email_unsubscribe_tokens (token, email, company_id)
         values (v_token, v_email, COALA)
    on conflict (email, company_id) do nothing;

    select token into v_token
      from public.email_unsubscribe_tokens
     where email = v_email and company_id = COALA
     limit 1;
  end if;

  return v_token;
end
$function$

CREATE OR REPLACE FUNCTION public.create_scenario_draft__impl(_event_id uuid, _scenario_label text, _scenario_assumptions jsonb DEFAULT NULL::jsonb, _description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_master_id uuid;
  v_event_record record;
  v_split_record record;
  v_new_version_id uuid;
  v_new_split_version_id uuid;
  v_next_number int;
  v_user_id uuid := auth.uid();
  v_user_label text;
BEGIN
  -- Resolve identidade
  SELECT COALESCE(full_name, email, 'Sistema') INTO v_user_label
    FROM public.profiles WHERE id = v_user_id;

  -- Permissão: admin/manager/editor
  IF NOT (
    public.has_role(v_user_id, 'admin'::app_role)
    OR public.has_role(v_user_id, 'manager'::app_role)
    OR public.has_role(v_user_id, 'editor'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para criar cenários';
  END IF;

  -- Identifica evento e Master (se for Split, sobe ao Master)
  SELECT id, parent_event_id INTO v_event_record
    FROM public.events WHERE id = _event_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Evento não encontrado';
  END IF;

  v_master_id := COALESCE(v_event_record.parent_event_id, v_event_record.id);

  -- Cria versão working_draft do Master
  SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_number
    FROM public.bp_versions WHERE event_id = v_master_id;

  INSERT INTO public.bp_versions (
    event_id, version_number, state, scenario_label, scenario_assumptions,
    description, created_by, created_by_label, is_pinned_scenario
  ) VALUES (
    v_master_id, v_next_number, 'working_draft', _scenario_label, _scenario_assumptions,
    _description, v_user_id, v_user_label, false
  )
  RETURNING id INTO v_new_version_id;

  -- Clona linhas Ativas do Master para o cenário
  INSERT INTO public.event_forecasts (
    event_id, category_id, type, description, amount, iva_rate, notes,
    status, specification, formula_type, formula_value, cache_config_id,
    is_transitory, exclude_from_result, master_forecast_id, attachment_refs,
    currency, original_amount, fx_rate, fx_rate_source, invoice_group_id,
    is_overhead, historic_overrides, ordering_partner_id, paying_partner_id, version_id
  )
  SELECT
    event_id, category_id, type, description, amount, iva_rate, notes,
    status, specification, formula_type, formula_value, cache_config_id,
    is_transitory, exclude_from_result, master_forecast_id, attachment_refs,
    currency, original_amount, fx_rate, fx_rate_source, invoice_group_id,
    is_overhead, historic_overrides, ordering_partner_id, paying_partner_id, v_new_version_id
  FROM public.event_forecasts
  WHERE event_id = v_master_id AND version_id IS NULL;

  -- Cascade para Splits
  FOR v_split_record IN
    SELECT id FROM public.events WHERE parent_event_id = v_master_id
  LOOP
    SELECT COALESCE(MAX(version_number), 0) + 1 INTO v_next_number
      FROM public.bp_versions WHERE event_id = v_split_record.id;

    INSERT INTO public.bp_versions (
      event_id, version_number, state, scenario_label, scenario_assumptions,
      description, created_by, created_by_label, cascaded_from_version_id,
      is_pinned_scenario
    ) VALUES (
      v_split_record.id, v_next_number, 'working_draft', _scenario_label,
      _scenario_assumptions, _description, v_user_id, v_user_label, v_new_version_id, false
    )
    RETURNING id INTO v_new_split_version_id;

    INSERT INTO public.event_forecasts (
      event_id, category_id, type, description, amount, iva_rate, notes,
      status, specification, formula_type, formula_value, cache_config_id,
      is_transitory, exclude_from_result, master_forecast_id, attachment_refs,
      currency, original_amount, fx_rate, fx_rate_source, invoice_group_id,
      is_overhead, historic_overrides, ordering_partner_id, paying_partner_id, version_id
    )
    SELECT
      event_id, category_id, type, description, amount, iva_rate, notes,
      status, specification, formula_type, formula_value, cache_config_id,
      is_transitory, exclude_from_result, master_forecast_id, attachment_refs,
      currency, original_amount, fx_rate, fx_rate_source, invoice_group_id,
      is_overhead, historic_overrides, ordering_partner_id, paying_partner_id, v_new_split_version_id
    FROM public.event_forecasts
    WHERE event_id = v_split_record.id AND version_id IS NULL;
  END LOOP;

  -- Audit log
  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    v_new_version_id, v_master_id, 'scenario_draft_created',
    v_user_id, v_user_label,
    jsonb_build_object('scenario_label', _scenario_label)
  );

  RETURN v_new_version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.discard_scenario_draft__impl(_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_version record;
  v_split_version record;
  v_user_label text;
BEGIN
  IF NOT (
    public.has_role(v_user_id, 'admin'::app_role)
    OR public.has_role(v_user_id, 'manager'::app_role)
    OR public.has_role(v_user_id, 'editor'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para descartar cenários';
  END IF;

  SELECT * INTO v_version FROM public.bp_versions WHERE id = _version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Versão não encontrada';
  END IF;

  IF v_version.state <> 'working_draft' THEN
    RAISE EXCEPTION 'Só é possível descartar cenários em construção (working_draft)';
  END IF;

  SELECT COALESCE(full_name, email, 'Sistema') INTO v_user_label
    FROM public.profiles WHERE id = v_user_id;

  -- Apaga cascades (Splits) — apaga forecasts e a versão
  FOR v_split_version IN
    SELECT id, event_id FROM public.bp_versions
    WHERE cascaded_from_version_id = _version_id
  LOOP
    INSERT INTO public.bp_version_audit_log (
      version_id, event_id, action, performed_by, performed_by_label, metadata
    ) VALUES (
      v_split_version.id, v_split_version.event_id, 'scenario_draft_discarded_cascade',
      v_user_id, v_user_label, jsonb_build_object('parent_version_id', _version_id)
    );
    DELETE FROM public.bp_versions WHERE id = v_split_version.id;
  END LOOP;

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    _version_id, v_version.event_id, 'scenario_draft_discarded',
    v_user_id, v_user_label, jsonb_build_object('scenario_label', v_version.scenario_label)
  );

  DELETE FROM public.bp_versions WHERE id = _version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_admin_window_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_flag boolean;
  v_code text;
  v_window uuid;
  v_window_name text;
  v_chosen_name text;
  v_uid uuid := auth.uid();
  v_reason text;
BEGIN
  -- Filhas de rateio e parcelas: a obrigação é da mãe (como D1/D8).
  IF NEW.parent_transaction_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.category_id IS NULL OR NEW.date IS NULL OR NEW.company_id IS NULL THEN RETURN NEW; END IF;

  -- UPDATE sem mudança real das chaves: nunca toca histórico.
  IF TG_OP = 'UPDATE'
     AND NEW.event_id IS NOT DISTINCT FROM OLD.event_id
     AND NEW.category_id IS NOT DISTINCT FROM OLD.category_id
     AND NEW.date IS NOT DISTINCT FROM OLD.date
     AND NEW.company_id IS NOT DISTINCT FROM OLD.company_id
     AND NEW.type IS NOT DISTINCT FROM OLD.type THEN
    RETURN NEW;
  END IF;

  SELECT allocate_to_active_event, code INTO v_flag, v_code
    FROM public.account_categories WHERE id = NEW.category_id;
  IF NOT coalesce(v_flag, false) THEN RETURN NEW; END IF;

  v_window := public.admin_window_event_for(NEW.company_id, NEW.date);
  IF v_window IS NULL OR NEW.event_id IS NOT DISTINCT FROM v_window THEN RETURN NEW; END IF;

  SELECT name INTO v_window_name FROM public.events WHERE id = v_window;
  SELECT name INTO v_chosen_name FROM public.events WHERE id = NEW.event_id;

  v_reason := nullif(btrim(coalesce(current_setting('mp.admin_cost_override_reason', true), '')), '');

  IF v_uid IS NULL OR v_reason IS NULL
     OR NOT public.has_permission_in(v_uid, 'admin_cost_override', NEW.company_id) THEN
    RAISE EXCEPTION 'Esta conta é custo do evento % nesta data. Escolhe esse evento ou pede a excepção.', v_window_name
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, company_id, new_data, metadata)
  VALUES ('transaction', NEW.id::text, 'admin_cost_override',
          coalesce(auth.jwt() ->> 'email', v_uid::text), NEW.company_id,
          jsonb_build_object('event_id', NEW.event_id, 'category_code', v_code, 'date', NEW.date, 'type', NEW.type, 'op', TG_OP),
          jsonb_build_object(
            'evento_da_janela', jsonb_build_object('id', v_window, 'nome', v_window_name),
            'evento_escolhido', CASE WHEN NEW.event_id IS NULL THEN NULL
                                     ELSE jsonb_build_object('id', NEW.event_id, 'nome', v_chosen_name) END,
            'justificacao', v_reason));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_artist_comparables_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count int;
BEGIN
  SELECT count(*) INTO v_count
    FROM public.artist_comparables c
   WHERE c.artist_id = NEW.artist_id
     AND c.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid);
  IF v_count >= 5 THEN
    RAISE EXCEPTION 'Máximo de 5 comparáveis por artista (artist_id=%)', NEW.artist_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_cache_config_master_or_children()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_parent uuid;
  v_parent_name text;
  v_children text;
BEGIN
  SELECT parent_event_id INTO v_parent FROM public.events WHERE id = NEW.event_id;

  IF v_parent IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.event_cache_configs WHERE event_id = v_parent AND id <> NEW.id) THEN
      SELECT name INTO v_parent_name FROM public.events WHERE id = v_parent;
      RAISE EXCEPTION 'O cachê deste artista já está configurado no Master %', v_parent_name
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT string_agg(DISTINCT e.name, ', ' ORDER BY e.name) INTO v_children
      FROM public.event_cache_configs c
      JOIN public.events e ON e.id = c.event_id
     WHERE e.parent_event_id = NEW.event_id AND c.id <> NEW.id;
    IF v_children IS NOT NULL THEN
      RAISE EXCEPTION 'O cachê já está configurado nos subeventos %; apaga-os antes de configurar no Master.', v_children
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_camarim_item_bp_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_master uuid;
  v_company uuid;
  v_target uuid;
  v_fc record;
  v_mode text;
  v_ev_name text;
  v_fc_ev_name text;
BEGIN
  IF NEW.status = 'rejected' THEN RETURN NEW; END IF;

  IF NEW.bp_scope = 'mixed' THEN
    IF NEW.bp_forecast_id IS NOT NULL THEN
      RAISE EXCEPTION 'Talão misto não leva linha de BP: a linha escolhe-se em cada parte da divisão.' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT s.master_event_id, s.company_id INTO v_master, v_company
    FROM public.camarim_sessions s WHERE s.id = NEW.session_id;

  -- Mesmo destino que a close-camarim-session: master_common -> Master da sessão
  -- (sem recurso ao evento local); o resto -> evento principal da sessão.
  IF NEW.bp_scope = 'master_common' THEN
    IF v_master IS NULL THEN
      RAISE EXCEPTION 'Verba "BP Master" escolhida, mas esta sessão não tem evento Master. Escolhe "BP Local (cidade)".' USING ERRCODE = '23514';
    END IF;
    v_target := v_master;
  ELSE
    v_target := COALESCE(
      (SELECT se.event_id FROM public.camarim_session_events se
        WHERE se.session_id = NEW.session_id
        ORDER BY se.is_primary DESC NULLS LAST, se.created_at LIMIT 1),
      NEW.event_id, v_master);
  END IF;
  IF v_target IS NULL THEN RETURN NEW; END IF;

  SELECT name INTO v_ev_name FROM public.events WHERE id = v_target;

  IF NEW.bp_forecast_id IS NOT NULL THEN
    SELECT f.event_id, f.company_id, f.version_id, c.code INTO v_fc
      FROM public.event_forecasts f
      LEFT JOIN public.account_categories c ON c.id = f.category_id
     WHERE f.id = NEW.bp_forecast_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'A linha de BP indicada não existe.' USING ERRCODE = '23514';
    END IF;
    IF v_fc.version_id IS NOT NULL THEN
      RAISE EXCEPTION 'A linha de BP pertence a uma versão/cenário. Só se usam linhas vivas do Business Plan.' USING ERRCODE = '23514';
    END IF;
    -- Mesma regra das transações (trg_enforce_tx_forecast_same_event).
    IF v_fc.event_id IS NULL OR NOT public.bp_tx_link_allowed(v_target, COALESCE(NEW.company_id, v_company), v_fc.event_id, v_fc.company_id) THEN
      SELECT name INTO v_fc_ev_name FROM public.events WHERE id = v_fc.event_id;
      RAISE EXCEPTION 'Linha de BP recusada: o item vai para o BP do evento "%" e a linha é do evento "%".',
        COALESCE(v_ev_name, '(sem evento)'), COALESCE(v_fc_ev_name, '(sem evento)') USING ERRCODE = '23514';
    END IF;
    IF COALESCE(v_fc.code, '') <> '2.6.04' THEN
      RAISE EXCEPTION 'A linha de BP tem de ser da rubrica 2.6.04 — Camarins (as despesas de camarim são integradas nessa rubrica).' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
  END IF;

  SELECT COALESCE(e.budget_mode, c.default_budget_mode, 'with_bp') INTO v_mode
    FROM public.events e JOIN public.companies c ON c.id = e.company_id
   WHERE e.id = v_target;

  IF v_mode = 'with_bp' AND NOT EXISTS (
    SELECT 1 FROM public.event_forecasts f
      JOIN public.account_categories c ON c.id = f.category_id
     WHERE f.event_id = v_target AND f.version_id IS NULL AND c.code = '2.6.04'
  ) THEN
    RAISE EXCEPTION 'O BP do evento "%" não tem nenhuma linha 2.6.04 — Camarins. Cria a linha no BP desse evento (ou muda a verba do item) antes de gravar.',
      COALESCE(v_ev_name, '(sem nome)') USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_forecast_amount_floor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_realized numeric;
  v_obs text;
  v_actor text;
BEGIN
  IF NEW.version_id IS NOT NULL OR NEW.status IS DISTINCT FROM 'approved'
     OR NEW.type IS DISTINCT FROM 'expense'
     OR COALESCE(NEW.amount, 0) >= COALESCE(OLD.amount, 0) THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(t.amount), 0) INTO v_realized
  FROM public.transactions t
  WHERE t.forecast_id = NEW.id
    AND t.type = 'expense'
    AND t.status IN ('approved','paid','partially_paid')
    AND COALESCE(t.is_transitory, false) = false
    AND COALESCE(t.exclude_from_result, false) = false
    AND t.reversed_at IS NULL
    AND COALESCE(t.is_hidden, false) = false;

  IF COALESCE(NEW.amount, 0) < v_realized - 0.005 THEN
    RAISE EXCEPTION 'A verba da linha de BP não pode ficar abaixo do realizado: pedido % €, realizado % €.',
      to_char(COALESCE(NEW.amount,0), 'FM999999999990.00'), to_char(v_realized, 'FM999999999990.00')
      USING ERRCODE = '22023';
  END IF;

  v_obs := NULLIF(btrim(COALESCE(current_setting('mp.bp_change_observation', true), '')), '');
  IF v_realized > 0 AND v_obs IS NULL THEN
    RAISE EXCEPTION 'Observação obrigatória para reduzir uma linha de BP com realizado.' USING ERRCODE = '22023';
  END IF;

  IF auth.uid() IS NULL THEN
    v_actor := 'service_role';
  ELSE
    SELECT COALESCE(p.email, auth.uid()::text) INTO v_actor FROM public.profiles p WHERE p.id = auth.uid();
    v_actor := COALESCE(v_actor, auth.uid()::text);
  END IF;

  -- baseline_amount nunca é tocado (D3)
  INSERT INTO public.forecast_audit_log (forecast_id, changed_by, field_name, old_value, new_value, observation, company_id)
  VALUES (NEW.id, v_actor, 'Redução de verba',
          to_char(COALESCE(OLD.amount,0), 'FM999999999990.00'),
          to_char(COALESCE(NEW.amount,0), 'FM999999999990.00'),
          v_obs, NEW.company_id);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_payment_list_batch_channel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_has_export boolean;
  v_in_export boolean;
  v_method text;
BEGIN
  IF NEW.payment_list_id IS NULL OR NEW.outside_batch THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.payment_list_items i
    WHERE i.payment_list_id = NEW.payment_list_id
      AND i.transaction_id = NEW.transaction_id
      AND i.removed_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Transação % não está ativa na lista de pagamento %.', NEW.transaction_id, NEW.payment_list_id
      USING ERRCODE = '22023';
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.payment_list_sepa_exports x WHERE x.payment_list_id = NEW.payment_list_id),
         EXISTS (SELECT 1 FROM public.payment_list_sepa_exports x WHERE x.payment_list_id = NEW.payment_list_id AND NEW.transaction_id = ANY (x.transaction_ids))
    INTO v_has_export, v_in_export;

  IF v_has_export THEN
    IF NOT v_in_export THEN
      RAISE EXCEPTION 'A transação % não foi no ficheiro SEPA desta lista: liquida-se uma a uma por outro canal.', NEW.transaction_id
        USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT coalesce(t.payment_method, 'transfer') INTO v_method FROM public.transactions t WHERE t.id = NEW.transaction_id;
    IF v_method <> 'transfer' THEN
      RAISE EXCEPTION 'A transação % é paga por % — não vai no lote; liquida-se uma a uma.', NEW.transaction_id, v_method
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_sepa_export_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text; v_company uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NEW; END IF;
  SELECT status, company_id INTO v_status, v_company FROM public.payment_lists WHERE id = NEW.payment_list_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'Lista de pagamento não encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF v_status NOT IN ('approved','partially_approved') THEN
    RAISE EXCEPTION 'Ficheiro SEPA só para listas aprovadas (estado actual: %).', v_status USING ERRCODE = '42501';
  END IF;
  IF NOT (public.is_platform_admin(auth.uid()) OR public.has_role_in(auth.uid(), 'admin', v_company)) THEN
    RAISE EXCEPTION 'Sem permissão para exportar o ficheiro SEPA (só quem aprova listas).' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_tx_forecast_same_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fc record;
  v_tx_company uuid;
  v_written boolean;
  v_consumes boolean;
  v_mode text;
  v_tx_ev_name text;
  v_fc_ev_name text;
BEGIN
  IF NEW.forecast_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE'
     AND OLD.forecast_id IS NOT DISTINCT FROM NEW.forecast_id
     AND OLD.event_id IS NOT DISTINCT FROM NEW.event_id THEN
    RETURN NEW;
  END IF;

  SELECT f.event_id, f.company_id, f.version_id INTO v_fc
    FROM public.event_forecasts f WHERE f.id = NEW.forecast_id;
  IF NOT FOUND THEN RETURN NEW; END IF; -- a FK trata

  v_written := TG_OP = 'INSERT' OR OLD.forecast_id IS DISTINCT FROM NEW.forecast_id;

  IF v_fc.version_id IS NOT NULL THEN
    IF v_written THEN
      RAISE EXCEPTION 'Vínculo recusado: a linha de BP pertence a uma versão/cenário. Só se vinculam transações a linhas vivas do Business Plan.' USING ERRCODE = '23514';
    END IF;
  END IF;

  -- no INSERT trg_set_company_id corre depois; resolve a empresa pelo evento
  v_tx_company := COALESCE(NEW.company_id,
    (SELECT e.company_id FROM public.events e WHERE e.id = NEW.event_id));

  IF v_fc.version_id IS NULL
     AND public.bp_tx_link_allowed(NEW.event_id, v_tx_company, v_fc.event_id, v_fc.company_id) THEN
    RETURN NEW;
  END IF;

  IF v_written THEN
    SELECT name INTO v_tx_ev_name FROM public.events WHERE id = NEW.event_id;
    SELECT name INTO v_fc_ev_name FROM public.events WHERE id = v_fc.event_id;
    RAISE EXCEPTION 'Vínculo recusado: a transação pertence ao evento "%" e a linha do Business Plan ao evento "%". Uma linha de BP só pode ser vinculada a transações do mesmo evento (ou sem evento, no desenho master/subeventos) e da mesma empresa.',
      COALESCE(v_tx_ev_name, '(sem evento)'), COALESCE(v_fc_ev_name, '(sem evento)');
  END IF;

  -- só mudou o event_id
  v_consumes := NEW.type = 'expense'
    AND COALESCE(NEW.is_transitory, false) = false
    AND COALESCE(NEW.exclude_from_result, false) = false
    AND NEW.reversed_at IS NULL
    AND COALESCE(NEW.is_hidden, false) = false
    AND NEW.shared_cost_account_id IS NULL;

  IF NEW.event_id IS NOT NULL THEN
    -- mesma expressão de public.event_budget_mode, sem a verificação de empresa activa
    SELECT COALESCE(e.budget_mode, c.default_budget_mode, 'with_bp') INTO v_mode
      FROM public.events e JOIN public.companies c ON c.id = e.company_id
     WHERE e.id = NEW.event_id;
  END IF;

  IF v_consumes AND NEW.status IN ('approved','paid','partially_paid')
     AND NEW.event_id IS NOT NULL AND v_mode = 'with_bp' THEN
    RAISE EXCEPTION 'Esta transação já está aprovada. Ao mudar de evento, escolhe no mesmo acto a linha de BP do evento novo.' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, metadata, company_id)
  VALUES ('transactions', NEW.id::text, 'auto_unlink_tx_forecast_event_change',
          COALESCE((SELECT email FROM public.profiles WHERE id = auth.uid()), auth.uid()::text, 'service_role'),
          jsonb_build_object('forecast_id', NEW.forecast_id, 'old_event_id', OLD.event_id, 'new_event_id', NEW.event_id),
          v_tx_company);
  NEW.forecast_id := NULL;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_whatsapp_notification(p_template_name text, p_recipient_profile_id uuid, p_params jsonb, p_event_id uuid DEFAULT NULL::uuid, p_context_type text DEFAULT NULL::text, p_context_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_template_id uuid;
  v_phone text;
  v_company_id uuid;
  v_queue_id uuid;
  v_opted_in boolean;
BEGIN
  SELECT id INTO v_template_id
    FROM public.notification_templates
    WHERE template_name = p_template_name AND status = 'approved';
  IF v_template_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT no.phone_number,
         (no.opted_in_at IS NOT NULL AND no.opted_out_at IS NULL)
    INTO v_phone, v_opted_in
    FROM public.notification_optin no
    WHERE no.profile_id = p_recipient_profile_id;

  IF v_phone IS NULL OR NOT COALESCE(v_opted_in,false) THEN
    RETURN NULL;
  END IF;

  IF p_event_id IS NOT NULL THEN
    SELECT company_id INTO v_company_id FROM public.events WHERE id = p_event_id;
  END IF;
  IF v_company_id IS NULL THEN
    SELECT company_id INTO v_company_id
      FROM public.user_companies WHERE user_id = p_recipient_profile_id LIMIT 1;
  END IF;
  IF v_company_id IS NULL THEN
    SELECT company_id INTO v_company_id FROM public.profiles WHERE id = p_recipient_profile_id;
  END IF;
  IF v_company_id IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.notification_queue (
    template_id, recipient_profile_id, recipient_phone, params,
    context_type, context_id, event_id, company_id
  ) VALUES (
    v_template_id, p_recipient_profile_id, v_phone, p_params,
    p_context_type, p_context_id, p_event_id, v_company_id
  ) RETURNING id INTO v_queue_id;

  RETURN v_queue_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.force_confidential_for_restricted_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.account_id IS NOT NULL AND NEW.is_confidential IS NOT TRUE THEN
    IF EXISTS (
      SELECT 1 FROM public.financial_accounts a
      WHERE a.id = NEW.account_id AND a.is_restricted = true
    ) THEN
      NEW.is_confidential := true;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_paid_amount_vs_payments()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sum numeric;
BEGIN
  IF NEW.paid_amount IS NOT DISTINCT FROM OLD.paid_amount THEN RETURN NEW; END IF;
  IF public._paid_guard_is_exempt(NEW) THEN RETURN NEW; END IF;
  SELECT COALESCE(SUM(amount), 0) INTO v_sum FROM public.transaction_payments
   WHERE transaction_id = NEW.id AND status = 'paid';
  IF COALESCE(NEW.paid_amount, 0) < v_sum - 0.01 AND pg_trigger_depth() <= 1 THEN
    RAISE EXCEPTION 'O valor pago (% €) não pode ficar abaixo da soma dos pagamentos registados (% €). Para reduzir, estorne ou apague o pagamento no separador Pagamento da transação.',
      round(COALESCE(NEW.paid_amount, 0), 2), round(v_sum, 2)
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company_id uuid;
BEGIN
  v_company_id := NULLIF(NEW.raw_user_meta_data->>'company_id', '')::uuid;
  IF v_company_id IS NULL THEN
    -- Fallback to first active company (default tenant) to avoid breaking signups
    SELECT id INTO v_company_id
    FROM public.companies
    WHERE status = 'active'
    ORDER BY created_at
    LIMIT 1;
  END IF;
  INSERT INTO public.profiles (id, full_name, email, company_id)
  VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', ''), NEW.email, v_company_id);
  INSERT INTO public.user_roles (user_id, role, company_id)
  VALUES (NEW.id, 'user', v_company_id);
  RETURN NEW;
END;
$function$

