CREATE OR REPLACE FUNCTION public.log_formalidade_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid;
  v_label text;
  v_auto boolean := false;
  v_setting text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.formalidade IS DISTINCT FROM OLD.formalidade THEN
    v_user := auth.uid();
    SELECT full_name INTO v_label FROM public.profiles WHERE id = v_user;

    -- Lê GUC de sessão; se for 'true', marca log como auto-sugerido.
    BEGIN
      v_setting := current_setting('app.formalidade_auto_suggested', true);
      IF v_setting IS NOT NULL AND lower(v_setting) IN ('true', 't', '1', 'on') THEN
        v_auto := true;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_auto := false;
    END;

    NEW.formalidade_changed_at := now();
    NEW.formalidade_changed_by := v_user;

    INSERT INTO public.event_forecast_formalidade_log
      (forecast_id, from_state, to_state, changed_by, changed_by_label, auto_suggested)
    VALUES
      (NEW.id, OLD.formalidade, NEW.formalidade, v_user, v_label, v_auto);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_table_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_entity_id text;
  v_old jsonb;
  v_new jsonb;
  v_user text;
  v_company uuid;
  v_row jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_old := NULL;
    v_new := to_jsonb(NEW);
    v_row := v_new;
    BEGIN v_entity_id := (NEW.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    v_row := v_new;
    BEGIN v_entity_id := (NEW.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_old := to_jsonb(OLD);
    v_new := NULL;
    v_row := v_old;
    BEGIN v_entity_id := (OLD.id)::text; EXCEPTION WHEN OTHERS THEN v_entity_id := NULL; END;
  END IF;

  BEGIN
    v_user := COALESCE(auth.uid()::text, 'system');
  EXCEPTION WHEN OTHERS THEN
    v_user := 'system';
  END;

  -- Resolver company_id de forma robusta:
  -- 1) Se a tabela é `companies`, usa o id da própria empresa (a auditoria pertence-lhe).
  -- 2) Senão, tenta a current_company_id() do utilizador autenticado.
  -- 3) Senão, tenta extrair `company_id` da própria linha.
  IF TG_TABLE_NAME = 'companies' THEN
    v_company := COALESCE(NULLIF(v_row->>'id','')::uuid, NULL);
  ELSE
    BEGIN
      v_company := current_company_id();
    EXCEPTION WHEN OTHERS THEN
      v_company := NULL;
    END;
    IF v_company IS NULL THEN
      BEGIN
        v_company := NULLIF(v_row->>'company_id','')::uuid;
      EXCEPTION WHEN OTHERS THEN
        v_company := NULL;
      END;
    END IF;
  END IF;

  -- D-ERP170: empresa já apagada (DELETE de companies ou cascata) → company_id NULL; o id fica em entity_id/old_data.
  IF v_company IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.companies c WHERE c.id = v_company) THEN
    v_company := NULL;
  END IF;

  BEGIN
    INSERT INTO public.system_audit_log (
      entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id
    ) VALUES (
      TG_TABLE_NAME,
      COALESCE(v_entity_id, gen_random_uuid()::text),
      v_action,
      v_user,
      v_old,
      v_new,
      jsonb_build_object('schema', TG_TABLE_SCHEMA, 'op', TG_OP),
      v_company
    );
  EXCEPTION WHEN not_null_violation THEN
    -- Última defesa: nunca bloquear a operação principal por falha de auditoria.
    NULL;
  END;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.marketing_consent_bind(p_company uuid, p_portal text, p_token text, p_receipt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sub public.marketing_consent_subjects%ROWTYPE; v_eff record; m text[]; v_ev public.marketing_consent_events%ROWTYPE;
BEGIN
  IF NOT public.marketing_consent_scope_ok(p_company, p_portal) THEN RETURN jsonb_build_object('proof', false, 'reason', 'scope_invalid'); END IF;
  IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('proof', false, 'reason', 'no_token'); END IF;
  m := regexp_match(coalesce(p_receipt, ''), '^([0-9]{1,18})\.([0-9]{1,18})\.([0-9a-f]{64})$');
  IF m IS NULL THEN RETURN jsonb_build_object('proof', false, 'reason', 'no_receipt'); END IF;
  SELECT * INTO v_sub FROM public.marketing_consent_subjects WHERE token_hash = encode(extensions.digest(p_token, 'sha256'), 'hex');
  IF v_sub.id IS NULL OR v_sub.company_id <> p_company OR v_sub.portal <> p_portal THEN
    RETURN jsonb_build_object('proof', false, 'reason', 'subject_invalid'); END IF;
  IF public.marketing_consent_receipt(p_token, m[1]::bigint, m[2]::bigint) <> p_receipt THEN
    RETURN jsonb_build_object('proof', false, 'reason', 'receipt_invalid'); END IF;
  SELECT * INTO v_ev FROM public.marketing_consent_events WHERE id = m[1]::bigint;
  IF v_ev.id IS NULL OR v_ev.subject_id <> v_sub.id OR v_ev.revision IS DISTINCT FROM m[2]::bigint OR v_ev.state <> 'granted' THEN
    RETURN jsonb_build_object('proof', false, 'reason', 'receipt_invalid'); END IF;
  SELECT * INTO v_eff FROM public.marketing_consent_effective(v_sub.id, clock_timestamp());
  IF v_eff.event_id IS DISTINCT FROM v_ev.id THEN RETURN jsonb_build_object('proof', false, 'reason', 'superseded'); END IF;
  IF NOT coalesce(v_eff.valid_grant, false) THEN RETURN jsonb_build_object('proof', false, 'reason', 'expired_or_policy'); END IF;
  RETURN jsonb_build_object('proof', true, 'subject_id', v_sub.id, 'event_id', v_ev.id);
END $function$

CREATE OR REPLACE FUNCTION public.marketing_consent_binding_valid(p_subject uuid, p_event bigint, p_company uuid, p_portal text, p_captured_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e public.marketing_consent_events%ROWTYPE; cap record; cur record;
BEGIN
  IF p_subject IS NULL OR p_event IS NULL OR p_company IS NULL OR p_portal IS NULL OR p_captured_at IS NULL THEN RETURN false; END IF;
  SELECT * INTO e FROM public.marketing_consent_events WHERE id = p_event;
  IF e.id IS NULL OR e.subject_id <> p_subject OR e.state <> 'granted' OR e.purpose <> 'meta_ads'
     OR e.company_id <> p_company OR e.portal <> p_portal OR e.revision IS NULL THEN RETURN false; END IF;
  SELECT * INTO cap FROM public.marketing_consent_effective(p_subject, p_captured_at);
  IF cap.event_id IS DISTINCT FROM e.id OR NOT coalesce(cap.valid_grant, false) THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.marketing_consent_events x WHERE x.subject_id = p_subject AND x.id <> e.id
             AND (coalesce(x.revision, 0) > e.revision OR x.id > e.id)) THEN RETURN false; END IF;
  SELECT * INTO cur FROM public.marketing_consent_effective(p_subject, clock_timestamp());
  RETURN cur.event_id = e.id AND coalesce(cur.valid_grant, false);
END $function$

CREATE OR REPLACE FUNCTION public.marketing_consent_record(p_company uuid, p_portal text, p_token text, p_state text, p_purpose text, p_policy text, p_banner text, p_seq bigint, p_client_at timestamp with time zone, p_idem uuid, p_origin text, p_path text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sub public.marketing_consent_subjects%ROWTYPE; v_ev public.marketing_consent_events%ROWTYPE;
        v_eff record; v_replay boolean := false; v_hash text; v_cur bigint; v_allowed boolean;
BEGIN
  IF NOT public.marketing_consent_scope_ok(p_company, p_portal) THEN RETURN jsonb_build_object('ok', false, 'error', 'scope_invalid'); END IF;
  IF p_state IS NULL OR p_state NOT IN ('granted','denied','revoked') THEN RETURN jsonb_build_object('ok', false, 'error', 'state_invalid'); END IF;
  IF p_purpose IS DISTINCT FROM 'meta_ads' THEN RETURN jsonb_build_object('ok', false, 'error', 'purpose_invalid'); END IF;
  IF p_idem IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'idempotency_key_required'); END IF;
  IF p_seq IS NULL OR p_seq <= 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'seq_invalid'); END IF;
  IF coalesce(length(p_policy),0) NOT BETWEEN 1 AND 64 OR coalesce(length(p_banner),0) NOT BETWEEN 1 AND 64 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'version_invalid'); END IF;
  IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RETURN jsonb_build_object('ok', false, 'error', 'subject_invalid'); END IF;
  IF p_state = 'granted' AND (p_expected_revision IS NULL OR p_expected_revision < 0) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'expected_revision_required'); END IF;

  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('mcs-tok:' || v_hash, 0));
  SELECT * INTO v_sub FROM public.marketing_consent_subjects WHERE token_hash = v_hash;
  IF v_sub.id IS NULL THEN
    INSERT INTO public.marketing_consent_subjects (company_id, portal, token_hash) VALUES (p_company, p_portal, v_hash) RETURNING * INTO v_sub;
  ELSIF v_sub.company_id <> p_company OR v_sub.portal <> p_portal THEN
    RETURN jsonb_build_object('ok', false, 'error', 'subject_invalid');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('mcs:' || v_sub.id::text, 0));
  SELECT * INTO v_ev FROM public.marketing_consent_events WHERE subject_id = v_sub.id AND idempotency_key = p_idem;
  IF v_ev.id IS NOT NULL THEN
    IF v_ev.state <> p_state OR v_ev.policy_version <> p_policy OR v_ev.banner_version <> p_banner
       OR v_ev.expected_revision IS DISTINCT FROM p_expected_revision THEN
      RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict'); END IF;
    v_replay := true;
  ELSE
    SELECT coalesce(max(revision), 0) INTO v_cur FROM public.marketing_consent_events WHERE subject_id = v_sub.id;
    IF p_state = 'granted' THEN
      IF NOT EXISTS (SELECT 1 FROM public.marketing_consent_policies
           WHERE portal = p_portal AND policy_version = p_policy AND valid_from <= now() AND (valid_to IS NULL OR valid_to > now())) THEN
        RETURN jsonb_build_object('ok', false, 'error', 'policy_invalid'); END IF;
      IF p_expected_revision <> v_cur THEN
        SELECT * INTO v_eff FROM public.marketing_consent_effective(v_sub.id, clock_timestamp());
        RETURN jsonb_build_object('ok', false, 'error', 'revision_conflict', 'effective_state', v_eff.state, 'effective_revision', v_cur);
      END IF;
    END IF;
    INSERT INTO public.marketing_consent_events (subject_id, company_id, portal, state, purpose, policy_version, banner_version,
      client_seq, client_decided_at, idempotency_key, origin, path, revision, expected_revision)
    VALUES (v_sub.id, p_company, p_portal, p_state, 'meta_ads', p_policy, p_banner, p_seq, p_client_at, p_idem,
      left(p_origin, 200), left(p_path, 300), v_cur + 1, p_expected_revision) RETURNING * INTO v_ev;
  END IF;
  SELECT * INTO v_eff FROM public.marketing_consent_effective(v_sub.id, clock_timestamp());
  v_allowed := v_ev.state = 'granted' AND v_eff.event_id = v_ev.id AND coalesce(v_eff.valid_grant, false);
  RETURN jsonb_build_object('ok', true, 'replay', v_replay, 'decision_id', v_ev.id, 'revision', v_ev.revision,
    'recorded_state', v_ev.state, 'server_received_at', v_ev.server_received_at,
    'effective_state', v_eff.state, 'effective_decision_id', v_eff.event_id, 'effective_revision', v_eff.revision,
    'marketing_allowed', v_allowed,
    'expires_at', CASE WHEN v_allowed THEN v_eff.expires_at END,
    'consent_receipt', CASE WHEN v_allowed THEN public.marketing_consent_receipt(p_token, v_ev.id, v_ev.revision) END);
END $function$

CREATE OR REPLACE FUNCTION public.marketing_filter_qs(p_qs text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE kept text; removed int;
BEGIN
  IF p_qs IS NULL OR p_qs = '' THEN RETURN p_qs; END IF;
  SELECT count(*) FILTER (WHERE public.marketing_is_meta_key(split_part(part, '=', 1))),
         string_agg(part, '&' ORDER BY ord) FILTER (WHERE NOT public.marketing_is_meta_key(split_part(part, '=', 1)))
    INTO removed, kept
    FROM unnest(string_to_array(p_qs, '&')) WITH ORDINALITY u(part, ord);
  IF removed = 0 THEN RETURN p_qs; END IF;
  RETURN coalesce(kept, '');
END $function$

CREATE OR REPLACE FUNCTION public.marketing_pct_decode_key(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE r text := p; i int;
BEGIN
  IF r IS NULL THEN RETURN NULL; END IF;
  r := replace(r, '+', ' ');
  FOR i IN 1..3 LOOP
    EXIT WHEN r !~ '%[0-9A-Fa-f]{2}';
    SELECT string_agg(CASE WHEN x.tok ~ '^%[0-9A-Fa-f]{2}$' AND ('x' || substr(x.tok, 2))::bit(8)::int > 0
                           THEN chr(('x' || substr(x.tok, 2))::bit(8)::int) ELSE x.tok END, '' ORDER BY x.ord)
      INTO r
      FROM (SELECT m[1] AS tok, ord FROM regexp_matches(r, '(%[0-9A-Fa-f]{2}|[^%]+|%)', 'g') WITH ORDINALITY AS t(m, ord)) x;
  END LOOP;
  RETURN lower(btrim(coalesce(r, '')));
END $function$

CREATE OR REPLACE FUNCTION public.marketing_strip_meta_json(j jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF j IS NULL THEN RETURN NULL; END IF;
  CASE jsonb_typeof(j)
    WHEN 'object' THEN
      RETURN coalesce((SELECT jsonb_object_agg(key, public.marketing_strip_meta_json(value))
                         FROM jsonb_each(j) WHERE NOT public.marketing_is_meta_key(key)), '{}'::jsonb);
    WHEN 'array' THEN
      RETURN coalesce((SELECT jsonb_agg(public.marketing_strip_meta_json(value) ORDER BY ord)
                         FROM jsonb_array_elements(j) WITH ORDINALITY a(value, ord)), '[]'::jsonb);
    WHEN 'string' THEN RETURN to_jsonb(public.marketing_strip_meta_params(j #>> '{}'));
    ELSE RETURN j;
  END CASE;
END $function$

CREATE OR REPLACE FUNCTION public.marketing_strip_meta_params(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE base text; frag text := NULL; q text := NULL; pos int; nq text; nf text;
BEGIN
  IF p_url IS NULL THEN RETURN NULL; END IF;
  pos := strpos(p_url, '#');
  IF pos > 0 THEN frag := substr(p_url, pos + 1); base := left(p_url, pos - 1); ELSE base := p_url; END IF;
  pos := strpos(base, '?');
  IF pos > 0 THEN q := substr(base, pos + 1); base := left(base, pos - 1); END IF;
  nq := public.marketing_filter_qs(q);
  nf := CASE WHEN frag IS NOT NULL AND strpos(frag, '=') > 0 THEN public.marketing_filter_qs(frag) ELSE frag END;
  IF nq IS NOT DISTINCT FROM q AND nf IS NOT DISTINCT FROM frag THEN RETURN p_url; END IF;
  RETURN base || CASE WHEN q IS NULL OR nq = '' THEN '' ELSE '?' || nq END
              || CASE WHEN frag IS NULL OR nf = '' THEN '' ELSE '#' || nf END;
END $function$

CREATE OR REPLACE FUNCTION public.materialize_paid_amount_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sum numeric; v_diff numeric; v_method text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.paid_amount IS NOT DISTINCT FROM OLD.paid_amount THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' AND COALESCE(NEW.paid_amount, 0) <= 0.01 THEN RETURN NULL; END IF;
  IF public._paid_guard_is_exempt(NEW) THEN RETURN NULL; END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_sum FROM public.transaction_payments
   WHERE transaction_id = NEW.id AND status = 'paid';
  v_diff := round(COALESCE(NEW.paid_amount, 0) - v_sum, 2);
  IF abs(v_diff) <= 0.01 THEN RETURN NULL; END IF;

  IF v_diff < 0 THEN
    UPDATE public.transaction_payments
       SET status = 'reversed', reversed_at = now(),
           reversal_reason = 'reajuste automático do valor pago (D-ERP157)'
     WHERE transaction_id = NEW.id AND status = 'paid' AND created_by = 'base D-ERP157';
    SELECT COALESCE(SUM(amount), 0) INTO v_sum FROM public.transaction_payments
     WHERE transaction_id = NEW.id AND status = 'paid';
    v_diff := round(COALESCE(NEW.paid_amount, 0) - v_sum, 2);
  END IF;

  IF v_diff > 0.01 THEN
    v_method := CASE WHEN NEW.account_id IS NULL THEN 'compensation'
                     WHEN NEW.payment_method IN ('transfer','service_payment','direct_debit','state_payment') THEN NEW.payment_method
                     ELSE 'transfer' END;
    INSERT INTO public.transaction_payments
      (transaction_id, amount, payment_date, account_id, payment_method, status,
       closes_transaction, company_id, created_by, notes)
    VALUES
      (NEW.id, v_diff, COALESCE(NEW.payment_date, NEW.date, current_date),
       CASE WHEN v_method = 'compensation' THEN NULL ELSE NEW.account_id END,
       v_method, 'paid', NEW.status = 'paid', NEW.company_id, 'base D-ERP157',
       'Criado pela base: transação gravada com valor pago sem linha de pagamento ('
         || COALESCE(auth.jwt() ->> 'email', current_user) || ')');
  END IF;

  PERFORM public._derive_paid_amount(NEW.id);
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.merge_forecasts_into_active_snapshot__impl(_event_id uuid, _forecast_ids uuid[])
 RETURNS TABLE(merged_into_master integer, merged_into_splits integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _role_ok boolean;
  _master_version_id uuid;
  _master_payload jsonb;
  _master_forecasts jsonb;
  _new_rows jsonb;
  _existing_ids uuid[];
  _master_count integer := 0;
  _split_count integer := 0;
  _split_event record;
  _split_version_id uuid;
  _split_payload jsonb;
  _split_forecasts jsonb;
  _split_new_rows jsonb;
  _split_existing_ids uuid[];
BEGIN
  -- Permission check
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid()
      AND role IN ('admin','manager','editor')
  ) INTO _role_ok;
  IF NOT _role_ok THEN
    RAISE EXCEPTION 'Permissão negada: só admin/manager/editor podem incorporar linhas no snapshot.';
  END IF;

  IF _forecast_ids IS NULL OR array_length(_forecast_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  -- ── MASTER ────────────────────────────────────────────────────────────
  SELECT id, snapshot_payload
    INTO _master_version_id, _master_payload
  FROM public.bp_versions
  WHERE event_id = _event_id AND state = 'active'
  LIMIT 1;

  IF _master_version_id IS NULL THEN
    RAISE EXCEPTION 'Evento sem versão ativa de BP — congele uma versão antes de incorporar.';
  END IF;

  _master_forecasts := COALESCE(_master_payload->'forecasts', '[]'::jsonb);

  -- IDs já existentes no snapshot
  SELECT COALESCE(array_agg((elem->>'id')::uuid), ARRAY[]::uuid[])
    INTO _existing_ids
  FROM jsonb_array_elements(_master_forecasts) elem;

  -- Build snapshot rows for forecasts not already in snapshot
  SELECT COALESCE(jsonb_agg(to_jsonb(f) - 'formalidade'), '[]'::jsonb)
    INTO _new_rows
  FROM public.event_forecasts f
  WHERE f.event_id = _event_id
    AND f.id = ANY(_forecast_ids)
    AND NOT (f.id = ANY(_existing_ids));

  IF jsonb_array_length(_new_rows) > 0 THEN
    _master_payload := jsonb_set(
      COALESCE(_master_payload, '{}'::jsonb),
      '{forecasts}',
      _master_forecasts || _new_rows,
      true
    );
    UPDATE public.bp_versions
       SET snapshot_payload = _master_payload
     WHERE id = _master_version_id;
    _master_count := jsonb_array_length(_new_rows);
  END IF;

  -- ── SPLITS (quando existirem linhas filhas via master_forecast_id) ────
  FOR _split_event IN
    SELECT DISTINCT ef.event_id AS split_event_id
    FROM public.event_forecasts ef
    WHERE ef.master_forecast_id = ANY(_forecast_ids)
      AND ef.event_id <> _event_id
  LOOP
    SELECT id, snapshot_payload
      INTO _split_version_id, _split_payload
    FROM public.bp_versions
    WHERE event_id = _split_event.split_event_id AND state = 'active'
    LIMIT 1;

    IF _split_version_id IS NULL THEN
      CONTINUE;
    END IF;

    _split_forecasts := COALESCE(_split_payload->'forecasts', '[]'::jsonb);

    SELECT COALESCE(array_agg((elem->>'id')::uuid), ARRAY[]::uuid[])
      INTO _split_existing_ids
    FROM jsonb_array_elements(_split_forecasts) elem;

    SELECT COALESCE(jsonb_agg(to_jsonb(f) - 'formalidade'), '[]'::jsonb)
      INTO _split_new_rows
    FROM public.event_forecasts f
    WHERE f.event_id = _split_event.split_event_id
      AND f.master_forecast_id = ANY(_forecast_ids)
      AND NOT (f.id = ANY(_split_existing_ids));

    IF jsonb_array_length(_split_new_rows) > 0 THEN
      _split_payload := jsonb_set(
        COALESCE(_split_payload, '{}'::jsonb),
        '{forecasts}',
        _split_forecasts || _split_new_rows,
        true
      );
      UPDATE public.bp_versions
         SET snapshot_payload = _split_payload
       WHERE id = _split_version_id;
      _split_count := _split_count + jsonb_array_length(_split_new_rows);
    END IF;
  END LOOP;

  RETURN QUERY SELECT _master_count, _split_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_split_absorbs_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.absorbs_admin_costs = true AND NEW.parent_event_id IS NOT NULL THEN
    RAISE EXCEPTION 'Apenas eventos Master ou Single podem absorver custos administrativos. Splits (eventos com parent_event_id) não são permitidos.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.promote_scenario_draft_to_active__impl(_scenario_version_id uuid, _new_active_label text DEFAULT NULL::text, _new_active_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_user_label text;
  v_scenario record;
  v_split_scenario record;
  v_old_active record;
  v_next_number int;
  v_tx_links jsonb;
  v_tx_result jsonb;
BEGIN
  IF NOT (
    public.has_role(v_user_id, 'admin'::app_role)
    OR public.has_role(v_user_id, 'manager'::app_role)
  ) THEN
    RAISE EXCEPTION 'Apenas admin ou manager pode promover cenários';
  END IF;

  SELECT COALESCE(full_name, email, 'Sistema') INTO v_user_label
    FROM public.profiles WHERE id = v_user_id;

  SELECT * INTO v_scenario FROM public.bp_versions WHERE id = _scenario_version_id;

  IF NOT FOUND OR v_scenario.state <> 'working_draft' THEN
    RAISE EXCEPTION 'Cenário inválido ou já promovido';
  END IF;

  -- ============ MASTER ============
  SELECT * INTO v_old_active
    FROM public.bp_versions
    WHERE event_id = v_scenario.event_id AND state = 'active'
    LIMIT 1;

  IF FOUND THEN
    UPDATE public.bp_versions
      SET state = 'superseded', superseded_at = now(), superseded_by_version_id = _scenario_version_id
      WHERE id = v_old_active.id;
  END IF;

  UPDATE public.bp_versions
    SET state = 'active',
        approved_at = now(),
        approved_by = v_user_id,
        description = COALESCE(_new_active_description, description, scenario_label),
        scenario_label = NULL
    WHERE id = _scenario_version_id;

  -- Captura vínculos BP↔TX antes de o DELETE disparar o ON DELETE SET NULL
  v_tx_links := public.bp_capture_tx_links(v_scenario.event_id);

  DELETE FROM public.event_forecasts
    WHERE event_id = v_scenario.event_id AND version_id IS NULL;

  UPDATE public.event_forecasts
    SET version_id = NULL
    WHERE version_id = _scenario_version_id;

  v_tx_result := public.bp_restore_tx_links(v_scenario.event_id, v_tx_links);

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    _scenario_version_id, v_scenario.event_id, 'scenario_promoted_to_active',
    v_user_id, v_user_label,
    jsonb_build_object('previous_active_id', v_old_active.id,
                      'scenario_label', v_scenario.scenario_label,
                      'tx_links', v_tx_result)
  );

  -- ============ SPLITS (cascade) ============
  FOR v_split_scenario IN
    SELECT * FROM public.bp_versions
    WHERE cascaded_from_version_id = _scenario_version_id AND state = 'working_draft'
  LOOP
    SELECT * INTO v_old_active
      FROM public.bp_versions
      WHERE event_id = v_split_scenario.event_id AND state = 'active'
      LIMIT 1;

    IF FOUND THEN
      UPDATE public.bp_versions
        SET state = 'superseded', superseded_at = now(), superseded_by_version_id = v_split_scenario.id
        WHERE id = v_old_active.id;
    END IF;

    UPDATE public.bp_versions
      SET state = 'active',
          approved_at = now(),
          approved_by = v_user_id,
          description = COALESCE(_new_active_description, description, scenario_label),
          scenario_label = NULL
      WHERE id = v_split_scenario.id;

    v_tx_links := public.bp_capture_tx_links(v_split_scenario.event_id);

    DELETE FROM public.event_forecasts
      WHERE event_id = v_split_scenario.event_id AND version_id IS NULL;

    UPDATE public.event_forecasts
      SET version_id = NULL
      WHERE version_id = v_split_scenario.id;

    v_tx_result := public.bp_restore_tx_links(v_split_scenario.event_id, v_tx_links);

    INSERT INTO public.bp_version_audit_log (
      version_id, event_id, action, performed_by, performed_by_label, metadata
    ) VALUES (
      v_split_scenario.id, v_split_scenario.event_id, 'scenario_promoted_to_active_cascade',
      v_user_id, v_user_label,
      jsonb_build_object('parent_scenario_id', _scenario_version_id,
                         'tx_links', v_tx_result)
    );
  END LOOP;

  RETURN _scenario_version_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_portal_error_log(p_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n integer;
BEGIN
  IF p_days IS NULL OR p_days < 30 THEN
    RAISE EXCEPTION 'Retenção mínima de 30 dias.';
  END IF;
  DELETE FROM public.portal_error_log WHERE created_at < now() - make_interval(days => p_days);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION public.purge_revoked_youtube_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; n_m int := 0; n_c int := 0; n_cm int := 0; n_d int := 0; x int; ch int := 0;
BEGIN
  FOR r IN SELECT ac.id, ac.artist_id FROM public.artist_channels ac
    WHERE ac.platform = 'youtube' AND ac.revoked_at IS NOT NULL AND ac.revoked_at < now() - interval '30 days'
      AND NOT EXISTS (SELECT 1 FROM public.artist_channel_connections k WHERE k.artist_channel_id = ac.id)
  LOOP
    ch := ch + 1;
    DELETE FROM public.artist_metrics_daily WHERE artist_id = r.artist_id AND (channel_id = r.id OR platform = 'youtube'); GET DIAGNOSTICS x = ROW_COUNT; n_m := n_m + x;
    DELETE FROM public.artist_content_metrics_daily WHERE artist_id = r.artist_id AND platform = 'youtube'; GET DIAGNOSTICS x = ROW_COUNT; n_cm := n_cm + x;
    DELETE FROM public.artist_content WHERE artist_id = r.artist_id AND platform = 'youtube'; GET DIAGNOSTICS x = ROW_COUNT; n_c := n_c + x;
    DELETE FROM public.artist_audience_demographics WHERE artist_id = r.artist_id AND platform = 'youtube'; GET DIAGNOSTICS x = ROW_COUNT; n_d := n_d + x;
    UPDATE public.artist_channels SET revoked_at = NULL, auth_status = 'revoked_purged' WHERE id = r.id;
  END LOOP;
  RETURN jsonb_build_object('channels', ch, 'metrics', n_m, 'content', n_c, 'content_metrics', n_cm, 'demographics', n_d);
END;
$function$

CREATE OR REPLACE FUNCTION public.realign_tx_category_from_forecast()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_forecast RECORD;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NULL; END IF;
  IF NEW.category_id IS NULL THEN RETURN NULL; END IF;

  SELECT id, category_id, event_id, company_id INTO v_forecast
    FROM public.event_forecasts
   WHERE transaction_id = NEW.id
     AND version_id IS NULL
     AND category_id IS NOT NULL
   ORDER BY created_at DESC
   LIMIT 1;

  IF v_forecast.id IS NULL THEN RETURN NULL; END IF;
  IF v_forecast.category_id IS NOT DISTINCT FROM NEW.category_id THEN RETURN NULL; END IF;

  IF NOT public.bp_tx_link_allowed(NEW.event_id, NEW.company_id, v_forecast.event_id, v_forecast.company_id) THEN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id)
    VALUES ('transaction', NEW.id, 'blocked_cross_event_category_sync', 'sistema (trigger)',
            jsonb_build_object('category_id', NEW.category_id),
            jsonb_build_object('category_id', v_forecast.category_id),
            jsonb_build_object('forecast_id', v_forecast.id, 'direction', 'tx_to_forecast',
                               'tx_event_id', NEW.event_id, 'forecast_event_id', v_forecast.event_id),
            COALESCE(NEW.company_id, v_forecast.company_id));
    RETURN NULL;
  END IF;

  UPDATE public.transactions
     SET category_id = v_forecast.category_id
   WHERE id = NEW.id;

  IF NEW.company_id IS NOT NULL THEN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id)
    VALUES ('transaction', NEW.id, 'auto_realign_tx_category', 'sistema (trigger)',
            jsonb_build_object('category_id', NEW.category_id),
            jsonb_build_object('category_id', v_forecast.category_id),
            jsonb_build_object('forecast_id', v_forecast.id, 'source', 'trigger', 'direction', 'tx_to_forecast'),
            NEW.company_id);
  END IF;

  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.relink_orphan_transactions(_event_id uuid, _pairs jsonb, _performed_by uuid DEFAULT NULL::uuid, _performed_by_label text DEFAULT NULL::text)
 RETURNS TABLE(relinked_count integer, skipped_count integer, details jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pair jsonb;
  v_tx_id uuid;
  v_fc_id uuid;
  v_relinked int := 0;
  v_skipped int := 0;
  v_details jsonb := '[]'::jsonb;
  v_forecast RECORD;
  v_tx RECORD;
BEGIN
  IF _pairs IS NULL OR jsonb_typeof(_pairs) <> 'array' THEN
    RAISE EXCEPTION 'Parameter _pairs must be a JSON array';
  END IF;

  FOR v_pair IN SELECT * FROM jsonb_array_elements(_pairs) LOOP
    v_tx_id := NULLIF(v_pair->>'transaction_id', '')::uuid;
    v_fc_id := NULLIF(v_pair->>'forecast_id', '')::uuid;

    IF v_tx_id IS NULL OR v_fc_id IS NULL THEN
      v_skipped := v_skipped + 1;
      v_details := v_details || jsonb_build_object('transaction_id', v_tx_id, 'forecast_id', v_fc_id, 'reason', 'invalid_pair');
      CONTINUE;
    END IF;

    SELECT id, event_id, transaction_id, category_id, amount INTO v_forecast
      FROM public.event_forecasts WHERE id = v_fc_id;

    IF v_forecast IS NULL OR v_forecast.event_id IS DISTINCT FROM _event_id THEN
      v_skipped := v_skipped + 1;
      v_details := v_details || jsonb_build_object('transaction_id', v_tx_id, 'forecast_id', v_fc_id, 'reason', 'forecast_not_in_event');
      CONTINUE;
    END IF;

    IF v_forecast.transaction_id IS NOT NULL AND v_forecast.transaction_id <> v_tx_id THEN
      v_skipped := v_skipped + 1;
      v_details := v_details || jsonb_build_object('transaction_id', v_tx_id, 'forecast_id', v_fc_id, 'reason', 'forecast_already_linked');
      CONTINUE;
    END IF;

    SELECT id, event_id INTO v_tx FROM public.transactions WHERE id = v_tx_id;
    IF v_tx IS NULL OR v_tx.event_id IS DISTINCT FROM _event_id THEN
      v_skipped := v_skipped + 1;
      v_details := v_details || jsonb_build_object('transaction_id', v_tx_id, 'forecast_id', v_fc_id, 'reason', 'transaction_not_in_event');
      CONTINUE;
    END IF;

    UPDATE public.event_forecasts SET transaction_id = v_tx_id, updated_at = now() WHERE id = v_fc_id;
    UPDATE public.transactions    SET forecast_id    = v_fc_id, updated_at = now() WHERE id = v_tx_id;

    v_relinked := v_relinked + 1;
    v_details := v_details || jsonb_build_object('transaction_id', v_tx_id, 'forecast_id', v_fc_id, 'reason', 'relinked');
  END LOOP;

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  )
  SELECT bv.id, _event_id, 'orphans_relinked', _performed_by, _performed_by_label,
    jsonb_build_object('relinked_count', v_relinked, 'skipped_count', v_skipped, 'details', v_details)
  FROM public.bp_versions bv
  WHERE bv.event_id = _event_id AND bv.state = 'active'
  LIMIT 1;

  RETURN QUERY SELECT v_relinked, v_skipped, v_details;
END;
$function$

CREATE OR REPLACE FUNCTION public.rename_bp_version__impl(_version_id uuid, _new_label text DEFAULT NULL::text, _new_description text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_user_label text;
  v_version record;
  v_new_label text;
  v_new_description text;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida — é necessário estar autenticado.';
  END IF;

  IF NOT (
    public.has_role(v_user_id, 'admin'::app_role)
    OR public.has_role(v_user_id, 'manager'::app_role)
  ) THEN
    RAISE EXCEPTION 'Apenas admin ou manager pode renomear versões do BP.';
  END IF;

  SELECT * INTO v_version FROM public.bp_versions WHERE id = _version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Versão do BP não encontrada.';
  END IF;

  -- scenario_label: só editável se já existir; nunca pode ficar vazio nem ser criado
  IF v_version.scenario_label IS NOT NULL THEN
    IF _new_label IS NULL THEN
      v_new_label := v_version.scenario_label;
    ELSIF btrim(_new_label) = '' THEN
      RAISE EXCEPTION 'Um cenário tem sempre de ter nome.';
    ELSE
      v_new_label := btrim(_new_label);
    END IF;
  ELSE
    v_new_label := NULL;
  END IF;

  IF _new_description IS NULL THEN
    v_new_description := v_version.description;
  ELSIF btrim(_new_description) = '' THEN
    v_new_description := NULL;
  ELSE
    v_new_description := btrim(_new_description);
  END IF;

  UPDATE public.bp_versions
    SET scenario_label = v_new_label,
        description = v_new_description
    WHERE id = _version_id;

  SELECT COALESCE(full_name, email, 'Sistema') INTO v_user_label
    FROM public.profiles WHERE id = v_user_id;

  INSERT INTO public.bp_version_audit_log (
    version_id, event_id, action, performed_by, performed_by_label, metadata
  ) VALUES (
    _version_id, v_version.event_id, 'renamed', v_user_id, COALESCE(v_user_label, 'Sistema'),
    jsonb_build_object(
      'old_scenario_label', v_version.scenario_label,
      'new_scenario_label', v_new_label,
      'old_description', v_version.description,
      'new_description', v_new_description
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.restore_apply_from_shadow(p_scope text, p_company_id uuid, p_tables text[], p_extra_deletes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order text[]; v_all text[]; k text; r record; v_cols text[]; v_list text;
  v_inserted jsonb := '{}'::jsonb; v_deleted jsonb := '{}'::jsonb;
  v_n bigint; v_n2 bigint; i int; v_has_shadow boolean;
  v_pk text[]; v_join text; v_extra jsonb; v_pklist text; v_set text;
BEGIN
  IF p_scope NOT IN ('company','global','rows') THEN
    RAISE EXCEPTION 'restore_apply_from_shadow: p_scope tem de ser company, global ou rows';
  END IF;
  IF p_scope = 'company' AND p_company_id IS NULL THEN
    RAISE EXCEPTION 'restore_apply_from_shadow: p_company_id obrigatório em scope company';
  END IF;
  IF p_tables IS NULL OR array_length(p_tables, 1) IS NULL THEN
    RAISE EXCEPTION 'restore_apply_from_shadow: p_tables vazio';
  END IF;

  v_all := p_tables;
  IF p_extra_deletes IS NOT NULL AND jsonb_typeof(p_extra_deletes) = 'object'
     AND p_extra_deletes <> '{}'::jsonb THEN
    IF p_scope <> 'rows' THEN
      RAISE EXCEPTION 'restore_apply_from_shadow: p_extra_deletes só é válido em scope rows';
    END IF;
    FOR k IN SELECT jsonb_object_keys(p_extra_deletes) LOOP
      IF NOT (k = ANY (v_all)) THEN v_all := v_all || k; END IF;
    END LOOP;
  END IF;

  SET CONSTRAINTS ALL DEFERRED;
  v_order := public.restore_topo_order(v_all);

  FOREACH k IN ARRAY v_order LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    v_has_shadow := to_regclass('restore_shadow.' || quote_ident(r.shadow)) IS NOT NULL;
    IF k = ANY (p_tables) AND NOT v_has_shadow THEN
      RAISE EXCEPTION 'restore_apply_from_shadow: sombra inexistente para %', k;
    END IF;
    IF p_scope = 'rows' AND public.restore_table_pk(k) IS NULL THEN
      RAISE EXCEPTION 'restore_apply_from_shadow: % não tem chave primária e o scope é rows', k;
    END IF;
    EXECUTE format('ALTER TABLE %I.%I DISABLE TRIGGER USER', r.sch, r.tbl);
  END LOOP;

  -- Fase de eliminação (filhos primeiro).
  -- Em scope 'rows' NÃO se apagam as linhas em âmbito: um DELETE na linha do
  -- evento arrastaria em cascata sub-eventos e tudo abaixo. As linhas em âmbito
  -- são repostas por UPSERT. Só se apaga o que existe hoje e não vem no backup.
  FOR i IN REVERSE array_length(v_order, 1) .. 1 LOOP
    k := v_order[i];
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    v_n := 0;
    IF p_scope = 'company' THEN
      IF EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema = r.sch AND table_name = r.tbl AND column_name = 'company_id') THEN
        EXECUTE format('DELETE FROM %I.%I WHERE company_id = $1', r.sch, r.tbl) USING p_company_id;
      ELSE
        RAISE EXCEPTION 'restore_apply_from_shadow: % não tem company_id e o scope é company', k;
      END IF;
      GET DIAGNOSTICS v_n = ROW_COUNT;
    ELSIF p_scope = 'global' THEN
      EXECUTE format('DELETE FROM %I.%I WHERE true', r.sch, r.tbl);
      GET DIAGNOSTICS v_n = ROW_COUNT;
    ELSE
      v_pk := public.restore_table_pk(k);
      SELECT COALESCE(jsonb_agg(CASE WHEN jsonb_typeof(e.value) = 'object'
                                     THEN e.value
                                     ELSE jsonb_build_object('id', e.value) END), '[]'::jsonb)
        INTO v_extra
        FROM jsonb_array_elements(COALESCE(p_extra_deletes -> k, '[]'::jsonb)) e;
      IF jsonb_array_length(v_extra) > 0 THEN
        SELECT string_agg(format('t.%I = d.%I', c, c), ' AND ') INTO v_join FROM unnest(v_pk) c;
        EXECUTE format(
          'DELETE FROM %I.%I t USING jsonb_populate_recordset(NULL::%I.%I, $1) d WHERE %s',
          r.sch, r.tbl, r.sch, r.tbl, v_join) USING v_extra;
        GET DIAGNOSTICS v_n2 = ROW_COUNT;
        v_n := v_n + v_n2;
      END IF;
    END IF;
    v_deleted := v_deleted || jsonb_build_object(k, v_n);
  END LOOP;

  -- Reposição (pais primeiro).
  FOREACH k IN ARRAY v_order LOOP
    IF NOT (k = ANY (p_tables)) THEN CONTINUE; END IF;
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    SELECT array_agg(p.column_name::text ORDER BY p.ordinal_position) INTO v_cols
      FROM information_schema.columns p
      WHERE p.table_schema = r.sch AND p.table_name = r.tbl
        AND EXISTS (SELECT 1 FROM information_schema.columns s
                    WHERE s.table_schema = 'restore_shadow' AND s.table_name = r.shadow
                      AND s.column_name = p.column_name);
    IF v_cols IS NULL THEN
      RAISE EXCEPTION 'restore_apply_from_shadow: sem colunas comuns em %', k;
    END IF;
    SELECT string_agg(quote_ident(c), ', ') INTO v_list FROM unnest(v_cols) c;

    IF p_scope = 'rows' THEN
      v_pk := public.restore_table_pk(k);
      SELECT string_agg(quote_ident(c), ', ') INTO v_pklist FROM unnest(v_pk) c;
      SELECT string_agg(format('%I = EXCLUDED.%I', c, c), ', ') INTO v_set
        FROM unnest(v_cols) c WHERE NOT (c = ANY (v_pk));
      IF v_set IS NULL THEN
        EXECUTE format('INSERT INTO %I.%I (%s) SELECT %s FROM restore_shadow.%I ON CONFLICT (%s) DO NOTHING',
                       r.sch, r.tbl, v_list, v_list, r.shadow, v_pklist);
      ELSE
        EXECUTE format('INSERT INTO %I.%I (%s) SELECT %s FROM restore_shadow.%I ON CONFLICT (%s) DO UPDATE SET %s',
                       r.sch, r.tbl, v_list, v_list, r.shadow, v_pklist, v_set);
      END IF;
    ELSE
      EXECUTE format('INSERT INTO %I.%I (%s) SELECT %s FROM restore_shadow.%I',
                     r.sch, r.tbl, v_list, v_list, r.shadow);
    END IF;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_inserted := v_inserted || jsonb_build_object(k, v_n);
  END LOOP;

  SET CONSTRAINTS ALL IMMEDIATE;

  FOREACH k IN ARRAY v_order LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    EXECUTE format('ALTER TABLE %I.%I ENABLE TRIGGER USER', r.sch, r.tbl);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'scope', p_scope, 'company_id', p_company_id,
    'order', to_jsonb(v_order), 'deleted', v_deleted, 'inserted', v_inserted);
END $function$

CREATE OR REPLACE FUNCTION public.restore_event_scope(p_event_ids uuid[], p_roots text[] DEFAULT NULL::text[])
 RETURNS TABLE(sch text, tbl text, tbl_key text, row_key jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  fk record; v_n bigint; v_total bigint; v_round int := 0; v_keep text[]; v_prev int;
  v_keyexpr text;
BEGIN
  IF p_event_ids IS NULL OR array_length(p_event_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'restore_event_scope: p_event_ids vazio';
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS _restore_scope (
    sch text, tbl text, key text, row_key jsonb, PRIMARY KEY (key, row_key)
  ) ON COMMIT DROP;
  DELETE FROM _restore_scope WHERE true;

  CREATE TEMP TABLE IF NOT EXISTS _restore_allowed (
    key text PRIMARY KEY, sch text, tbl text, pk text[]
  ) ON COMMIT DROP;
  DELETE FROM _restore_allowed WHERE true;

  INSERT INTO _restore_allowed (key, sch, tbl, pk)
  SELECT x.k, i.schema_name, i.tbl_name, public.restore_table_pk(x.k)
  FROM public.backup_table_inventory() i
  CROSS JOIN LATERAL (
    SELECT CASE WHEN i.schema_name = 'crm' THEN 'crm.' || i.tbl_name ELSE i.tbl_name END
  ) x(k)
  WHERE NOT EXISTS (
          SELECT 1 FROM public.backup_excluded_tables e WHERE e.table_name = i.tbl_name)
    AND public.restore_table_pk(x.k) IS NOT NULL;

  INSERT INTO _restore_scope (sch, tbl, key, row_key)
  SELECT 'public', 'events', 'events', jsonb_build_object('id', e.id)
  FROM public.events e WHERE e.id = ANY (p_event_ids)
  ON CONFLICT DO NOTHING;

  FOR fk IN
    SELECT a.key, a.sch, a.tbl, a.pk FROM _restore_allowed a
    WHERE a.key <> 'events'
      AND EXISTS (SELECT 1 FROM information_schema.columns c
                  WHERE c.table_schema = a.sch AND c.table_name = a.tbl
                    AND c.column_name = 'event_id' AND c.data_type = 'uuid')
  LOOP
    SELECT string_agg(format('%L, t.%I', c, c), ', ' ORDER BY ord)
      INTO v_keyexpr FROM unnest(fk.pk) WITH ORDINALITY u(c, ord);
    EXECUTE format(
      'INSERT INTO _restore_scope (sch, tbl, key, row_key)
         SELECT %L, %L, %L, jsonb_build_object(%s) FROM %I.%I t WHERE t.event_id = ANY ($1)
         ON CONFLICT DO NOTHING',
      fk.sch, fk.tbl, fk.key, v_keyexpr, fk.sch, fk.tbl) USING p_event_ids;
  END LOOP;

  LOOP
    v_round := v_round + 1;
    EXIT WHEN v_round > 30;
    v_total := 0;
    FOR fk IN
      SELECT DISTINCT l.child_key, l.c_sch, l.c_tbl, l.parent_key, l.child_col,
             (SELECT a.pk FROM _restore_allowed a WHERE a.key = l.child_key) AS pk
      FROM public.restore_fk_links() l
      WHERE NOT l.ambiguous
    LOOP
      IF fk.pk IS NULL THEN CONTINUE; END IF;
      IF NOT EXISTS (SELECT 1 FROM _restore_scope WHERE key = fk.parent_key) THEN CONTINUE; END IF;
      IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                     WHERE table_schema = fk.c_sch AND table_name = fk.c_tbl
                       AND column_name = fk.child_col AND data_type = 'uuid') THEN CONTINUE; END IF;
      SELECT string_agg(format('%L, t.%I', c, c), ', ' ORDER BY ord)
        INTO v_keyexpr FROM unnest(fk.pk) WITH ORDINALITY u(c, ord);
      EXECUTE format(
        'INSERT INTO _restore_scope (sch, tbl, key, row_key)
           SELECT %L, %L, %L, jsonb_build_object(%s) FROM %I.%I t
           WHERE t.%I IN (SELECT (s.row_key->>''id'')::uuid FROM _restore_scope s
                          WHERE s.key = %L AND s.row_key ? ''id'')
           ON CONFLICT DO NOTHING',
        fk.c_sch, fk.c_tbl, fk.child_key, v_keyexpr, fk.c_sch, fk.c_tbl, fk.child_col, fk.parent_key);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_total := v_total + v_n;
    END LOOP;
    EXIT WHEN v_total = 0;
  END LOOP;

  IF p_roots IS NOT NULL AND array_length(p_roots, 1) > 0 THEN
    v_keep := p_roots;
    LOOP
      v_prev := array_length(v_keep, 1);
      SELECT array_agg(DISTINCT x) INTO v_keep FROM (
        SELECT unnest(v_keep) AS x
        UNION
        SELECT DISTINCT l.child_key FROM public.restore_fk_links() l
        WHERE NOT l.ambiguous AND l.parent_key = ANY (v_keep)
      ) s;
      EXIT WHEN array_length(v_keep, 1) = v_prev;
    END LOOP;
    DELETE FROM _restore_scope WHERE NOT (key = ANY (v_keep));
  END IF;

  RETURN QUERY SELECT s.sch, s.tbl, s.key, s.row_key FROM _restore_scope s;
END $function$

CREATE OR REPLACE FUNCTION public.restore_event_scope_json(p_event_ids uuid[], p_roots text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_keys jsonb; v_ids jsonb; v_counts jsonb; v_allowed jsonb; v_pk jsonb; v_amb jsonb;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _restore_scope_out (key text, row_key jsonb) ON COMMIT DROP;
  DELETE FROM _restore_scope_out WHERE true;
  INSERT INTO _restore_scope_out (key, row_key)
  SELECT s.tbl_key, s.row_key FROM public.restore_event_scope(p_event_ids, p_roots) s;

  SELECT COALESCE(jsonb_object_agg(key, ks), '{}'::jsonb) INTO v_keys
  FROM (SELECT key, jsonb_agg(row_key) AS ks FROM _restore_scope_out GROUP BY key) x;

  SELECT COALESCE(jsonb_object_agg(key, ids), '{}'::jsonb) INTO v_ids
  FROM (SELECT key, jsonb_agg(row_key->>'id') AS ids FROM _restore_scope_out
        WHERE row_key ? 'id' GROUP BY key) xi;

  SELECT COALESCE(jsonb_object_agg(key, n), '{}'::jsonb) INTO v_counts
  FROM (SELECT key, count(*) AS n FROM _restore_scope_out GROUP BY key) y;

  SELECT COALESCE(jsonb_agg(z.k ORDER BY z.k), '[]'::jsonb),
         COALESCE(jsonb_object_agg(z.k, to_jsonb(public.restore_table_pk(z.k))), '{}'::jsonb)
    INTO v_allowed, v_pk
  FROM (
    SELECT CASE WHEN i.schema_name = 'crm' THEN 'crm.' || i.tbl_name ELSE i.tbl_name END AS k
    FROM public.backup_table_inventory() i
    WHERE NOT EXISTS (SELECT 1 FROM public.backup_excluded_tables x WHERE x.table_name = i.tbl_name)
  ) z
  WHERE public.restore_table_pk(z.k) IS NOT NULL;

  SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object(
           'child', l.child_key, 'parent', l.parent_key, 'child_col', l.child_col)), '[]'::jsonb)
    INTO v_amb
  FROM public.restore_fk_links() l WHERE l.ambiguous;

  RETURN jsonb_build_object('keys', v_keys, 'ids', v_ids, 'counts', v_counts,
                            'allowed', v_allowed, 'pk', v_pk, 'ambiguous_links', v_amb);
END $function$

CREATE OR REPLACE FUNCTION public.restore_event_snapshot(p_event_ids uuid[], p_roots text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_out jsonb := '{}'::jsonb; v_n bigint; v_md5 text; v_pk text[]; v_keyexpr text;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _restore_snap (sch text, tbl text, key text, row_key jsonb) ON COMMIT DROP;
  DELETE FROM _restore_snap WHERE true;
  INSERT INTO _restore_snap (sch, tbl, key, row_key)
  SELECT s.sch, s.tbl, s.tbl_key, s.row_key FROM public.restore_event_scope(p_event_ids, p_roots) s;

  FOR r IN SELECT DISTINCT sch, tbl, key FROM _restore_snap ORDER BY key LOOP
    v_pk := public.restore_table_pk(r.key);
    SELECT string_agg(format('%L, t.%I', c, c), ', ' ORDER BY ord)
      INTO v_keyexpr FROM unnest(v_pk) WITH ORDINALITY u(c, ord);
    EXECUTE format(
      'SELECT count(*), COALESCE(md5(string_agg(row_to_json(t)::text, %L ORDER BY jsonb_build_object(%s)::text)), %L)
         FROM %I.%I t
        WHERE jsonb_build_object(%s) IN (SELECT s.row_key FROM _restore_snap s WHERE s.key = %L)',
      '|', v_keyexpr, 'vazio', r.sch, r.tbl, v_keyexpr, r.key)
    INTO v_n, v_md5;
    v_out := v_out || jsonb_build_object(r.key, jsonb_build_object('n', v_n, 'md5', v_md5));
  END LOOP;

  RETURN v_out;
END $function$

CREATE OR REPLACE FUNCTION public.restore_shadow_cleanup(p_tables text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE k text; r record; n int := 0;
BEGIN
  FOREACH k IN ARRAY COALESCE(p_tables, '{}'::text[]) LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    IF to_regclass('restore_shadow.' || quote_ident(r.shadow)) IS NOT NULL THEN
      EXECUTE format('DROP TABLE restore_shadow.%I', r.shadow);
      n := n + 1;
    END IF;
  END LOOP;
  RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.restore_shadow_load(p_table text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_unknown text[]; v_n bigint; v_present text[]; v_list text;
BEGIN
  SELECT * INTO r FROM public.restore_shadow_ref(p_table);
  IF to_regclass('restore_shadow.' || quote_ident(r.shadow)) IS NULL THEN
    RAISE EXCEPTION 'restore_shadow_load: sombra inexistente para %', p_table;
  END IF;
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
    RAISE EXCEPTION 'restore_shadow_load: p_rows tem de ser um array jsonb';
  END IF;

  SELECT array_agg(DISTINCT kk) INTO v_unknown
  FROM jsonb_array_elements(p_rows) e, jsonb_object_keys(e.value) kk
  WHERE kk NOT IN (SELECT column_name FROM information_schema.columns
                   WHERE table_schema = 'restore_shadow' AND table_name = r.shadow);

  SELECT array_agg(c.column_name::text ORDER BY c.ordinal_position) INTO v_present
  FROM information_schema.columns c
  WHERE c.table_schema = 'restore_shadow' AND c.table_name = r.shadow
    AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_rows) e
                WHERE e.value ? c.column_name);

  IF v_present IS NULL THEN
    RAISE EXCEPTION 'restore_shadow_load: nenhuma coluna do backup existe hoje em %', p_table;
  END IF;

  SELECT string_agg(quote_ident(c), ', ') INTO v_list FROM unnest(v_present) c;
  EXECUTE format(
    'INSERT INTO restore_shadow.%I (%s) SELECT %s FROM jsonb_populate_recordset(NULL::restore_shadow.%I, $1)',
    r.shadow, v_list, v_list, r.shadow) USING p_rows;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('inserted', v_n, 'unknown_cols', COALESCE(to_jsonb(v_unknown), '[]'::jsonb),
                            'cols_defaulted', (SELECT COALESCE(to_jsonb(array_agg(c.column_name::text ORDER BY c.column_name)), '[]'::jsonb)
                                               FROM information_schema.columns c
                                               WHERE c.table_schema = 'restore_shadow' AND c.table_name = r.shadow
                                                 AND NOT (c.column_name::text = ANY (v_present))));
END $function$

CREATE OR REPLACE FUNCTION public.restore_shadow_prepare(p_tables text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE k text; r record; v_out jsonb := '{}'::jsonb; v_cols text[];
BEGIN
  FOREACH k IN ARRAY p_tables LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = r.sch AND table_name = r.tbl) THEN
      RAISE EXCEPTION 'restore_shadow_prepare: tabela % não existe em produção', k;
    END IF;
    EXECUTE format('DROP TABLE IF EXISTS restore_shadow.%I', r.shadow);
    EXECUTE format('CREATE TABLE restore_shadow.%I (LIKE %I.%I INCLUDING DEFAULTS)', r.shadow, r.sch, r.tbl);
    SELECT array_agg(column_name::text ORDER BY ordinal_position) INTO v_cols
      FROM information_schema.columns
      WHERE table_schema = 'restore_shadow' AND table_name = r.shadow;
    v_out := v_out || jsonb_build_object(k, to_jsonb(v_cols));
  END LOOP;
  RETURN v_out;
END $function$

CREATE OR REPLACE FUNCTION public.restore_shadow_validate(p_scope text, p_company_id uuid, p_tables text[], p_counts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  k text; r record; fk record; v_errors jsonb := '[]'::jsonb; v_counts jsonb := '{}'::jsonb;
  v_n bigint; v_exp bigint; v_bad bigint; v_parent text; v_skipped jsonb := '[]'::jsonb;
  v_fk_checked int := 0; v_prod text; v_cond text;
BEGIN
  FOREACH k IN ARRAY p_tables LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(k);
    EXECUTE format('SELECT count(*) FROM restore_shadow.%I', r.shadow) INTO v_n;
    v_counts := v_counts || jsonb_build_object(k, v_n);
    v_exp := COALESCE((p_counts ->> k)::bigint, 0);
    IF v_n <> v_exp THEN
      v_errors := v_errors || jsonb_build_object('table', k, 'kind', 'count',
        'detail', format('sombra tem %s linhas, manifesto diz %s', v_n, v_exp));
    END IF;

    IF p_scope = 'company' AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'restore_shadow' AND table_name = r.shadow AND column_name = 'company_id') THEN
      EXECUTE format('SELECT count(*) FROM restore_shadow.%I WHERE company_id IS DISTINCT FROM $1', r.shadow)
        INTO v_bad USING p_company_id;
      IF v_bad > 0 THEN
        v_errors := v_errors || jsonb_build_object('table', k, 'kind', 'company_id',
          'detail', format('%s linhas com company_id diferente de %s', v_bad, p_company_id));
      END IF;
    END IF;
  END LOOP;

  FOR fk IN
    SELECT c.conname,
           CASE WHEN cn.nspname = 'crm' THEN 'crm.' || cc.relname ELSE cc.relname END AS child_key,
           CASE WHEN pn.nspname = 'crm' THEN 'crm.' || pc.relname ELSE pc.relname END AS parent_key,
           pn.nspname AS p_sch, pc.relname AS p_tbl,
           array_length(c.conkey, 1) AS ncols,
           (SELECT a.attname FROM pg_attribute a WHERE a.attrelid = c.conrelid AND a.attnum = c.conkey[1]) AS child_col,
           (SELECT a.attname FROM pg_attribute a WHERE a.attrelid = c.confrelid AND a.attnum = c.confkey[1]) AS parent_col
    FROM pg_constraint c
    JOIN pg_class cc ON cc.oid = c.conrelid
    JOIN pg_namespace cn ON cn.oid = cc.relnamespace
    JOIN pg_class pc ON pc.oid = c.confrelid
    JOIN pg_namespace pn ON pn.oid = pc.relnamespace
    WHERE c.contype = 'f'
      AND (CASE WHEN cn.nspname = 'crm' THEN 'crm.' || cc.relname ELSE cc.relname END) = ANY (p_tables)
  LOOP
    SELECT * INTO r FROM public.restore_shadow_ref(fk.child_key);
    IF fk.ncols > 1 THEN
      v_skipped := v_skipped || jsonb_build_object('constraint', fk.conname, 'reason', 'FK multi-coluna');
      CONTINUE;
    END IF;
    v_prod := quote_ident(fk.p_sch) || '.' || quote_ident(fk.p_tbl);
    IF fk.parent_key = ANY (p_tables) THEN
      v_parent := 'restore_shadow.' || quote_ident((SELECT shadow FROM public.restore_shadow_ref(fk.parent_key)));
      IF p_scope = 'rows' THEN
        -- O pai pode estar fora do âmbito e permanecer em produção.
        v_cond := format('NOT EXISTS (SELECT 1 FROM %s p WHERE p.%I = c.%I)
                            AND NOT EXISTS (SELECT 1 FROM %s q WHERE q.%I = c.%I)',
                         v_parent, fk.parent_col, fk.child_col, v_prod, fk.parent_col, fk.child_col);
      ELSE
        v_cond := format('NOT EXISTS (SELECT 1 FROM %s p WHERE p.%I = c.%I)',
                         v_parent, fk.parent_col, fk.child_col);
      END IF;
    ELSE
      v_cond := format('NOT EXISTS (SELECT 1 FROM %s p WHERE p.%I = c.%I)',
                       v_prod, fk.parent_col, fk.child_col);
    END IF;
    EXECUTE format(
      'SELECT count(*) FROM restore_shadow.%I c WHERE c.%I IS NOT NULL AND %s',
      r.shadow, fk.child_col, v_cond) INTO v_bad;
    v_fk_checked := v_fk_checked + 1;
    IF v_bad > 0 THEN
      v_errors := v_errors || jsonb_build_object('table', fk.child_key, 'kind', 'fk',
        'detail', format('%s: %s valores sem pai (%s)', fk.conname, v_bad, fk.parent_key));
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', jsonb_array_length(v_errors) = 0,
    'tables', array_length(p_tables, 1),
    'scope', p_scope,
    'fks_checked', v_fk_checked,
    'fks_skipped', v_skipped,
    'counts', v_counts,
    'errors', v_errors);
END $function$

CREATE OR REPLACE FUNCTION public.restore_topo_order(p_tables text[])
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order text[] := '{}';
  v_rem text[] := p_tables;
  k text;
  v_progress boolean;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _restore_deps (child text, parent text) ON COMMIT DROP;
  DELETE FROM _restore_deps WHERE true;
  INSERT INTO _restore_deps (child, parent)
  SELECT DISTINCT
    CASE WHEN cn.nspname = 'crm' THEN 'crm.' || cc.relname ELSE cc.relname END,
    CASE WHEN pn.nspname = 'crm' THEN 'crm.' || pc.relname ELSE pc.relname END
  FROM pg_constraint c
  JOIN pg_class cc ON cc.oid = c.conrelid
  JOIN pg_namespace cn ON cn.oid = cc.relnamespace
  JOIN pg_class pc ON pc.oid = c.confrelid
  JOIN pg_namespace pn ON pn.oid = pc.relnamespace
  WHERE c.contype = 'f'
    AND c.conrelid <> c.confrelid
    AND (CASE WHEN cn.nspname = 'crm' THEN 'crm.' || cc.relname ELSE cc.relname END) = ANY (p_tables)
    AND (CASE WHEN pn.nspname = 'crm' THEN 'crm.' || pc.relname ELSE pc.relname END) = ANY (p_tables);

  LOOP
    EXIT WHEN array_length(v_rem, 1) IS NULL;
    v_progress := false;
    FOREACH k IN ARRAY v_rem LOOP
      IF NOT EXISTS (SELECT 1 FROM _restore_deps d WHERE d.child = k AND d.parent = ANY (v_rem)) THEN
        v_order := v_order || k;
        v_rem := array_remove(v_rem, k);
        v_progress := true;
      END IF;
    END LOOP;
    IF NOT v_progress THEN
      v_order := v_order || v_rem;
      EXIT;
    END IF;
  END LOOP;
  RETURN v_order;
END $function$

CREATE OR REPLACE FUNCTION public.run_operacao_sla_escalator()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_supabase_url text := 'https://sfohvvlqccmmebvjgibx.supabase.co';
  v_service_role text;
  r record;
  v_processed int := 0;
BEGIN
  SELECT decrypted_secret INTO v_service_role FROM vault.decrypted_secrets WHERE name='email_queue_service_role_key' LIMIT 1;
  IF v_service_role IS NULL THEN
    RAISE WARNING 'run_operacao_sla_escalator: service_role secret missing';
    RETURN jsonb_build_object('error','service_role_missing');
  END IF;

  FOR r IN SELECT id, frente_id, company_id, priority, text, etapa_id
    FROM public.operacao_registros
    WHERE kind='chamado' AND status='open' AND acked_at IS NULL
      AND escalation_level=0 AND sla_half_at IS NOT NULL AND sla_half_at <= now()
  LOOP
    UPDATE public.operacao_registros SET escalation_level=1 WHERE id=r.id;
    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/send-push-notification',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer ' || v_service_role),
      body := jsonb_build_object(
        'target', jsonb_build_object('type','frente_team','frente_id', r.frente_id),
        'title','Chamado sem resposta',
        'body', COALESCE(NULLIF(r.text,''),'Chamado aberto') || ' (50% SLA)',
        'url','/operacao/chamado/' || r.id::text,
        'whatsapp', false,
        'tag','op-sla1-' || r.id::text
      )
    );
    v_processed := v_processed + 1;
  END LOOP;

  FOR r IN SELECT id, frente_id, company_id, priority, text
    FROM public.operacao_registros
    WHERE kind='chamado' AND status IN ('open','in_progress')
      AND escalation_level < 2 AND sla_due_at IS NOT NULL AND sla_due_at <= now()
  LOOP
    UPDATE public.operacao_registros SET escalation_level=2 WHERE id=r.id;
    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/send-push-notification',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer ' || v_service_role),
      body := jsonb_build_object(
        'target', jsonb_build_object('type','company_admins','company_id', r.company_id),
        'title','🚨 SLA vencido — chamado',
        'body', COALESCE(NULLIF(r.text,''),'Chamado vencido') || ' (' || COALESCE(r.priority,'') || ')',
        'url','/operacao/chamado/' || r.id::text,
        'whatsapp', COALESCE(r.priority IN ('crit','high'), false),
        'tag','op-sla2-' || r.id::text
      )
    );
    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('processed', v_processed, 'ts', now());
END $function$

CREATE OR REPLACE FUNCTION public.run_vip_coupon_reminder()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_base text;
  v_key text;
  v_req bigint;
BEGIN
  v_base := public.vip_coupon_functions_base_url();
  SELECT decrypted_secret INTO v_key
  FROM vault.decrypted_secrets
  WHERE name = 'email_queue_service_role_key'
  LIMIT 1;

  IF v_base IS NULL OR v_key IS NULL THEN
    RAISE WARNING 'run_vip_coupon_reminder: base_url ou service_role secret em falta';
    RETURN jsonb_build_object('error', 'config_missing');
  END IF;

  SELECT net.http_post(
    url := v_base || '/functions/v1/vip-coupon-email?mode=reminder',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object('mode', 'reminder'),
    timeout_milliseconds := 30000
  ) INTO v_req;

  RETURN jsonb_build_object('request_id', v_req, 'ts', now());
END $function$

CREATE OR REPLACE FUNCTION public.set_company_id_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.company_id IS NULL THEN
    NEW.company_id := public.current_company_id();
    IF NEW.company_id IS NULL THEN
      RAISE EXCEPTION 'company_id cannot be NULL — user has no associated company';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

