CREATE OR REPLACE FUNCTION public.tg_sponsorship_pipeline_autolog()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.sponsorship_pipeline_activities(company_id, pipeline_id, user_id, kind, body, metadata)
    VALUES (NEW.company_id, NEW.id, auth.uid(), 'system',
      'Patrocinador adicionado ao pipeline',
      jsonb_build_object('stage', NEW.stage, 'supplier_name', NEW.supplier_name));
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.stage IS DISTINCT FROM OLD.stage THEN
      INSERT INTO public.sponsorship_pipeline_activities(company_id, pipeline_id, user_id, kind, body, metadata)
      VALUES (NEW.company_id, NEW.id, auth.uid(), 'stage_change',
        format('Estado: %s → %s', OLD.stage, NEW.stage),
        jsonb_build_object('from', OLD.stage, 'to', NEW.stage));
      IF NEW.stage IN ('closed','barter') AND OLD.stage NOT IN ('closed','barter') THEN
        NEW.closed_at := COALESCE(NEW.closed_at, now());
      END IF;
      IF NEW.stage NOT IN ('closed','barter') AND OLD.stage IN ('closed','barter') THEN
        NEW.closed_at := NULL;
      END IF;
    END IF;
    IF NEW.doc_status IS DISTINCT FROM OLD.doc_status THEN
      INSERT INTO public.sponsorship_pipeline_activities(company_id, pipeline_id, user_id, kind, body, metadata)
      VALUES (NEW.company_id, NEW.id, auth.uid(), 'doc_status_change',
        format('Estado documental: %s → %s', COALESCE(OLD.doc_status::text,'—'), COALESCE(NEW.doc_status::text,'—')),
        jsonb_build_object('from', OLD.doc_status, 'to', NEW.doc_status));
    END IF;
    RETURN NEW;
  END IF;

  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.tosl_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_status text; v_company uuid; v_parent record; v_old uuid; v_new uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN v_old := OLD.statement_id; END IF;
  IF TG_OP <> 'DELETE' THEN v_new := NEW.statement_id; END IF;
  -- Both parents, deduplicated and ordered before checking their current state.
  -- NO KEY UPDATE conflicts with confirmation's FOR UPDATE, but not FK KEY SHARE.
  FOR v_parent IN
    SELECT id, status, company_id FROM public.ticket_office_statements
    WHERE id IN (v_old, v_new) ORDER BY id FOR NO KEY UPDATE
  LOOP
    IF v_parent.status = 'confirmed' THEN
      RAISE EXCEPTION 'Apuramento Ticketline confirmado: as linhas não se alteram.';
    END IF;
    IF v_parent.id = v_new THEN v_company := v_parent.company_id; END IF;
  END LOOP;
  IF TG_OP <> 'DELETE' AND NEW.company_id IS DISTINCT FROM v_company THEN
    RAISE EXCEPTION 'A linha tem de ser da mesma empresa do apuramento.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $function$

