CREATE OR REPLACE FUNCTION public.trg_check_admin_windows_contiguous()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(current_setting('mp.admin_window_autoclose', true), '') = 'on' THEN
    RETURN NULL; -- fecho automático: a escrita exterior valida
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.absorbs_admin_costs THEN PERFORM public.check_admin_windows_contiguous(OLD.company_id); END IF;
    RETURN NULL;
  END IF;
  IF NEW.absorbs_admin_costs OR (TG_OP = 'UPDATE' AND OLD.absorbs_admin_costs) THEN
    PERFORM public.check_admin_windows_contiguous(NEW.company_id);
    IF TG_OP = 'UPDATE' AND OLD.company_id IS DISTINCT FROM NEW.company_id AND OLD.absorbs_admin_costs THEN
      PERFORM public.check_admin_windows_contiguous(OLD.company_id);
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_category_allocate_flag()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.allocate_to_active_event = true THEN
    IF NEW.code !~ '^10\.[0-9]+\.[0-9]+$' THEN
      RAISE EXCEPTION 'allocate_to_active_event só pode ser ligado em categorias de Nível 3 do Grupo 10 (formato 10.x.yy). Código atual: %', NEW.code;
    END IF;
    IF NEW.code ~ '^10\.(1|2|3|12)\.' THEN
      RAISE EXCEPTION 'A conta % não pode ser custo do evento da janela administrativa: 10.1, 10.2, 10.3 e 10.12 ficam sempre na empresa.', NEW.code;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_event_admin_absorption()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open_id uuid;
BEGIN
  IF NEW.absorbs_admin_costs = true THEN
    IF NEW.parent_event_id IS NOT NULL THEN
      RAISE EXCEPTION 'Apenas eventos Master ou Single podem absorver custos administrativos (não Splits).';
    END IF;
    IF NEW.admin_window_start IS NULL THEN
      RAISE EXCEPTION 'Quando o evento absorve custos administrativos, a data de início da janela é obrigatória.';
    END IF;
    IF NEW.admin_window_end IS NOT NULL AND NEW.admin_window_end < NEW.admin_window_start THEN
      RAISE EXCEPTION 'O fim da janela (%) não pode ser anterior ao início (%).',
        to_char(NEW.admin_window_end,'DD/MM/YYYY'), to_char(NEW.admin_window_start,'DD/MM/YYYY');
    END IF;

    -- Janela em aberto de outro evento que começa antes: fecha no dia antes.
    IF coalesce(current_setting('mp.admin_window_autoclose', true), '') <> 'on' THEN
      SELECT id INTO v_open_id
        FROM public.events
       WHERE company_id = NEW.company_id
         AND id <> NEW.id
         AND absorbs_admin_costs = true
         AND parent_event_id IS NULL
         AND admin_window_end IS NULL
         AND admin_window_start < NEW.admin_window_start
       ORDER BY admin_window_start DESC
       LIMIT 1;
      IF v_open_id IS NOT NULL THEN
        PERFORM set_config('mp.admin_window_autoclose', 'on', true);
        UPDATE public.events
           SET admin_window_end = NEW.admin_window_start - 1
         WHERE id = v_open_id;
        PERFORM set_config('mp.admin_window_autoclose', '', true);
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_transaction_offset()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record; p record; v_sum numeric;
BEGIN
  IF NEW.receivable_transaction_id = NEW.payable_transaction_id THEN
    RAISE EXCEPTION 'Compensação: a receita e a despesa têm de ser transações diferentes.' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO r FROM public.transactions WHERE id = NEW.receivable_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Compensação: a receita indicada não existe.' USING ERRCODE = 'check_violation'; END IF;
  SELECT * INTO p FROM public.transactions WHERE id = NEW.payable_transaction_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Compensação: a despesa indicada não existe.' USING ERRCODE = 'check_violation'; END IF;
  IF r.type <> 'income' THEN
    RAISE EXCEPTION 'Compensação: o lado a receber tem de ser uma receita (é "%").', r.type USING ERRCODE = 'check_violation';
  END IF;
  IF p.type <> 'expense' THEN
    RAISE EXCEPTION 'Compensação: o lado a pagar tem de ser uma despesa (é "%").', p.type USING ERRCODE = 'check_violation';
  END IF;
  IF r.company_id IS DISTINCT FROM p.company_id OR r.company_id IS DISTINCT FROM NEW.company_id THEN
    RAISE EXCEPTION 'Compensação: as duas transações têm de ser da mesma empresa.' USING ERRCODE = 'check_violation';
  END IF;
  IF r.supplier_id IS NULL OR p.supplier_id IS NULL THEN
    RAISE EXCEPTION 'Compensação: as duas transações têm de ter fornecedor/cliente.' USING ERRCODE = 'check_violation';
  END IF;
  IF r.supplier_id <> p.supplier_id THEN
    RAISE EXCEPTION 'Compensação: a receita e a despesa têm de ser do mesmo fornecedor/cliente.' USING ERRCODE = 'check_violation';
  END IF;
  IF r.reversed_at IS NOT NULL OR r.status = 'reversed' OR p.reversed_at IS NOT NULL OR p.status = 'reversed' THEN
    RAISE EXCEPTION 'Compensação: não se liga uma transação estornada.' USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(r.is_hidden, false) OR COALESCE(p.is_hidden, false) THEN
    RAISE EXCEPTION 'Compensação: não se liga uma transação escondida.' USING ERRCODE = 'check_violation';
  END IF;

  SELECT COALESCE(SUM(o.amount), 0) + NEW.amount INTO v_sum
    FROM public.transaction_offsets o
   WHERE o.receivable_transaction_id = NEW.receivable_transaction_id AND o.id <> NEW.id;
  IF v_sum > round(r.amount * (1 + COALESCE(r.iva_rate, 0) / 100.0), 2) + 0.01 THEN
    RAISE EXCEPTION 'Compensação: o total ligado à receita (% €) excede o seu valor bruto (% €).',
      round(v_sum, 2), round(r.amount * (1 + COALESCE(r.iva_rate, 0) / 100.0), 2) USING ERRCODE = 'check_violation';
  END IF;
  SELECT COALESCE(SUM(o.amount), 0) + NEW.amount INTO v_sum
    FROM public.transaction_offsets o
   WHERE o.payable_transaction_id = NEW.payable_transaction_id AND o.id <> NEW.id;
  IF v_sum > round(p.amount * (1 + COALESCE(p.iva_rate, 0) / 100.0), 2) + 0.01 THEN
    RAISE EXCEPTION 'Compensação: o total ligado à despesa (% €) excede o seu valor bruto (% €).',
      round(v_sum, 2), round(p.amount * (1 + COALESCE(p.iva_rate, 0) / 100.0), 2) USING ERRCODE = 'check_violation';
  END IF;

  IF TG_OP = 'INSERT' AND NEW.created_by IS NULL THEN
    NEW.created_by := COALESCE((SELECT auth.uid())::text, 'sistema');
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_tx_category_l2_match(_tx_category_id uuid, _forecast_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_fc_cat_id uuid;
  v_tx_l2 uuid;
  v_fc_l2 uuid;
  v_tx_parent uuid;
  v_tx_grand uuid;
  v_fc_parent uuid;
  v_fc_grand uuid;
BEGIN
  -- TX órfã: regra não se aplica
  IF _forecast_id IS NULL THEN RETURN true; END IF;
  IF _tx_category_id IS NULL THEN RETURN true; END IF;

  SELECT category_id INTO v_fc_cat_id
    FROM public.event_forecasts WHERE id = _forecast_id;

  -- BP sem categoria, ou já apagado: não bloquear
  IF v_fc_cat_id IS NULL THEN RETURN true; END IF;
  IF v_fc_cat_id = _tx_category_id THEN RETURN true; END IF;

  -- Resolver L2 da TX (parent se tx é L3, senão a própria)
  SELECT parent_id INTO v_tx_parent FROM public.account_categories WHERE id = _tx_category_id;
  IF v_tx_parent IS NULL THEN
    v_tx_l2 := _tx_category_id; -- tx categoria é L1 (caso raro)
  ELSE
    SELECT parent_id INTO v_tx_grand FROM public.account_categories WHERE id = v_tx_parent;
    v_tx_l2 := COALESCE(v_tx_parent, _tx_category_id);
    -- se tx é L3, parent é L2; se tx é L2, parent é L1 → usar a própria L2
    IF v_tx_grand IS NULL THEN
      v_tx_l2 := _tx_category_id;
    ELSE
      v_tx_l2 := v_tx_parent;
    END IF;
  END IF;

  -- Resolver L2 do BP
  SELECT parent_id INTO v_fc_parent FROM public.account_categories WHERE id = v_fc_cat_id;
  IF v_fc_parent IS NULL THEN
    v_fc_l2 := v_fc_cat_id;
  ELSE
    SELECT parent_id INTO v_fc_grand FROM public.account_categories WHERE id = v_fc_parent;
    IF v_fc_grand IS NULL THEN
      v_fc_l2 := v_fc_cat_id;
    ELSE
      v_fc_l2 := v_fc_parent;
    END IF;
  END IF;

  RETURN v_tx_l2 = v_fc_l2;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_alerts_run()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_run uuid; v_t0 timestamptz := clock_timestamp(); v_new int := 0; v_res int := 0; v_n int; r record;
BEGIN
  INSERT INTO public.sync_runs (function_name, trigger_source, dry_run, status)
  VALUES ('artist-ads-alerts', 'cron', false, 'running') RETURNING id INTO v_run;
  BEGIN
    CREATE TEMP TABLE IF NOT EXISTS _alerts_now (artist_id uuid, company_id uuid, connection_id uuid, platform text,
      kind text, severity text, message text, campaign_id text, day date) ON COMMIT DROP;
    DELETE FROM _alerts_now WHERE true;
    FOR r IN SELECT DISTINCT c.artist_id, c.company_id FROM crm.ad_platform_connections c
             WHERE c.connection_scope='artist' AND c.platform='tiktok' AND c.status='active' AND c.artist_id IS NOT NULL LOOP
      INSERT INTO _alerts_now SELECT r.artist_id, r.company_id, t.* FROM crm.artist_ads_tiktok_alerts_core(r.artist_id) t;
    END LOOP;
    INSERT INTO public.artist_ads_alert_log (company_id, artist_id, connection_id, platform, kind, severity, message, campaign_id, day)
    SELECT company_id, artist_id, connection_id, platform, kind, severity, message, campaign_id, day FROM _alerts_now
    ON CONFLICT (connection_id, kind, campaign_id) WHERE resolved_at IS NULL DO NOTHING;
    GET DIAGNOSTICS v_new = ROW_COUNT;
    UPDATE public.artist_ads_alert_log l SET resolved_at = now()
    WHERE l.resolved_at IS NULL AND l.platform = 'tiktok'
      AND l.kind NOT IN ('saldo_baixo','saldo_critico','saldo_ilegivel','entrega_parada')
      AND NOT EXISTS (SELECT 1 FROM _alerts_now a WHERE a.connection_id = l.connection_id AND a.kind = l.kind
        AND a.campaign_id IS NOT DISTINCT FROM l.campaign_id);
    GET DIAGNOSTICS v_res = ROW_COUNT;
    SELECT count(*) INTO v_n FROM _alerts_now;
    UPDATE public.sync_runs SET status = CASE WHEN v_new > 0 THEN 'success' ELSE 'no_data' END,
      finished_at = now(), duration_ms = (extract(epoch FROM clock_timestamp() - v_t0) * 1000)::int,
      rows_written = v_new, details = jsonb_build_object('a_disparar', v_n, 'novas', v_new, 'resolvidas', v_res)
    WHERE id = v_run;
    RETURN jsonb_build_object('a_disparar', v_n, 'novas', v_new, 'resolvidas', v_res);
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.sync_runs SET status = 'error', finished_at = now(), error_text = left(SQLERRM, 1000) WHERE id = v_run;
    RETURN jsonb_build_object('erro', SQLERRM);
  END;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_autolink_songs_internal(p_artist_id uuid)
