CREATE OR REPLACE FUNCTION public.artist_ads_balance_alerts_apply(p_scope text, p_connections uuid[], p_alerts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE v_kinds text[]; v_new uuid[] := '{}'; v_res uuid[] := '{}'; v_id uuid; v_ins boolean; r record;
BEGIN
  v_kinds := CASE p_scope WHEN 'balance' THEN ARRAY['saldo_baixo','saldo_critico','saldo_ilegivel']
                          WHEN 'delivery' THEN ARRAY['entrega_parada'] ELSE NULL END;
  IF v_kinds IS NULL THEN RAISE EXCEPTION 'scope inválido: %', p_scope; END IF;
  FOR r IN SELECT (x->>'connection_id')::uuid AS cid, x->>'kind' AS kind, x->>'severity' AS sev,
                  x->>'message' AS msg, nullif(x->>'days_left','')::numeric AS dl
           FROM jsonb_array_elements(coalesce(p_alerts,'[]'::jsonb)) x
           WHERE x->>'kind' = ANY(v_kinds) AND (x->>'connection_id')::uuid = ANY(p_connections) LOOP
    v_id := NULL; v_ins := NULL;
    INSERT INTO public.artist_ads_alert_log (company_id, artist_id, connection_id, platform, kind, severity, message, day, days_left)
    SELECT c.company_id, c.artist_id, c.id, c.platform, r.kind, r.sev, r.msg,
           (now() AT TIME ZONE 'America/Fortaleza')::date, r.dl
    FROM crm.ad_platform_connections c WHERE c.id = r.cid AND c.artist_id IS NOT NULL
    ON CONFLICT (connection_id, kind, campaign_id) WHERE resolved_at IS NULL
      DO UPDATE SET days_left = EXCLUDED.days_left
    RETURNING id, (xmax = 0) INTO v_id, v_ins;
    IF v_ins THEN v_new := v_new || v_id; END IF;
  END LOOP;
  FOR r IN SELECT l.id FROM public.artist_ads_alert_log l
           WHERE l.resolved_at IS NULL AND l.kind = ANY(v_kinds) AND l.connection_id = ANY(p_connections)
             AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(coalesce(p_alerts,'[]'::jsonb)) x
                             WHERE (x->>'connection_id')::uuid = l.connection_id AND x->>'kind' = l.kind) LOOP
    UPDATE public.artist_ads_alert_log SET resolved_at = now() WHERE id = r.id;
    v_res := v_res || r.id;
  END LOOP;
  FOREACH v_id IN ARRAY v_new LOOP PERFORM crm.artist_ads_alert_notify(v_id, 'opened'); END LOOP;
  FOREACH v_id IN ARRAY v_res LOOP PERFORM crm.artist_ads_alert_notify(v_id, 'resolved'); END LOOP;
  RETURN jsonb_build_object('novos', to_jsonb(v_new), 'resolvidos', to_jsonb(v_res));
END $function$

CREATE OR REPLACE FUNCTION public.anonymize_traffic_events(_days integer DEFAULT 180)
 RETURNS TABLE(leads_anonymized bigint, gclicks_anonymized bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm', 'pg_catalog'
AS $function$
DECLARE
  v_role text := COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  v_cutoff timestamptz;
  v_leads bigint := 0;
  v_clicks bigint := 0;
BEGIN
  -- #75: só service_role (cron/edge) ou sessão sem claims (postgres/migração).
  IF v_role NOT IN ('service_role', '') THEN
    RAISE EXCEPTION 'Apenas service_role pode anonimizar eventos de tráfego.' USING ERRCODE = '42501';
  END IF;

  v_cutoff := now() - make_interval(days => GREATEST(COALESCE(_days, 180), 0));

  WITH upd AS (
    UPDATE public.leads
       SET ip_inet = NULL, user_agent = NULL, fbc = NULL, fbp = NULL, mp_click_id = NULL
     WHERE kind = 'redirect_click'
       AND created_at < v_cutoff
       AND (ip_inet IS NOT NULL OR user_agent IS NOT NULL OR fbc IS NOT NULL
            OR fbp IS NOT NULL OR mp_click_id IS NOT NULL)
    RETURNING 1
  ) SELECT count(*) INTO v_leads FROM upd;

  WITH upd AS (
    UPDATE crm.google_click
       SET gclid = NULL, gbraid = NULL, wbraid = NULL, user_agent = NULL
     WHERE created_at < v_cutoff
       AND (gclid IS NOT NULL OR gbraid IS NOT NULL OR wbraid IS NOT NULL OR user_agent IS NOT NULL)
    RETURNING 1
  ) SELECT count(*) INTO v_clicks FROM upd;

  RETURN QUERY SELECT v_leads, v_clicks;
END;
$function$

CREATE OR REPLACE FUNCTION public.artist_content_link_songs__impl(p_artist_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true)
 RETURNS TABLE(content_id uuid, song_id uuid, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row record;
  v_match record;
  v_hits int;
  v_n int;
  v_reason text;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS _cand(base text, sid uuid, is_launch boolean, release_date date, how text) ON COMMIT DROP;

  FOR v_row IN
    SELECT c.id, c.artist_id, c.platform,
           lower(extensions.unaccent(coalesce(c.title, '') || ' ' || coalesce(c.caption_excerpt, ''))) AS hay
      FROM public.artist_content c
     WHERE c.song_id IS NULL
       AND coalesce(c.song_link_status, 'none') IN ('none', 'estimated')
       AND (p_artist_id IS NULL OR c.artist_id = p_artist_id)
  LOOP
    DELETE FROM _cand WHERE true;

    INSERT INTO _cand(base, sid, is_launch, release_date, how)
    SELECT b.base, b.id, b.is_launch, b.release_date,
           CASE WHEN position(b.base in v_row.hay) > 0 THEN 'menção' ELSE 'hashtag' END
      FROM (
        SELECT s.id, s.is_launch, s.release_date,
               public.artist_song_base_title(s.title) AS base
          FROM public.artist_songs s
         WHERE s.artist_id = v_row.artist_id
           AND coalesce(s.tracking_status, '') <> 'arquivado'
      ) b
     WHERE length(b.base) >= 4
       AND (
         position(b.base in v_row.hay) > 0
         OR position('#' || replace(b.base, ' ', '') in v_row.hay) > 0
       );

    SELECT count(DISTINCT base) INTO v_hits FROM _cand;

    IF v_hits = 0 THEN
      CONTINUE;
    ELSIF v_hits > 1 THEN
      RETURN QUERY SELECT v_row.id, NULL::uuid,
        'ambíguo: ' || (SELECT string_agg(DISTINCT base, ' | ') FROM _cand);
      CONTINUE;
    END IF;

    SELECT c.sid, c.base, c.how
      INTO v_match
      FROM _cand c
     ORDER BY c.is_launch DESC NULLS LAST, c.release_date ASC NULLS LAST
     LIMIT 1;

    SELECT count(*) INTO v_n FROM _cand;
    IF v_n > 1 THEN
      IF (SELECT count(*) FROM _cand c
           WHERE coalesce(c.is_launch,false) = (SELECT coalesce(max(is_launch::int),0)::boolean FROM _cand)
             AND c.release_date IS NOT DISTINCT FROM (
                 SELECT min(release_date) FROM _cand
                  WHERE coalesce(is_launch,false) = (SELECT coalesce(max(is_launch::int),0)::boolean FROM _cand))
         ) > 1 THEN
        RETURN QUERY SELECT v_row.id, NULL::uuid,
          'ambíguo: várias versões de "' || v_match.base || '" sem critério de desempate';
        CONTINUE;
      END IF;
    END IF;

    v_reason := v_match.how || ' ''' || v_match.base || ''' na descrição';

    IF NOT p_dry_run THEN
      UPDATE public.artist_content
         SET song_id = v_match.sid,
             song_link_status = 'estimated',
             song_link_reason = v_reason,
             updated_at = now()
       WHERE id = v_row.id;
    END IF;

    RETURN QUERY SELECT v_row.id, v_match.sid, v_reason;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.help_sync_article(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_slug text := _payload->>'slug';
  v_hash text := _payload->>'content_hash';
  v_existing record;
  v_article_id uuid;
  v_status text;
  v_section jsonb;
  v_chunk jsonb;
  v_section_id uuid;
  v_terms text[];
  v_chunks int := 0;
BEGIN
  IF v_slug IS NULL OR v_hash IS NULL THEN
    RAISE EXCEPTION 'help_sync_article: payload sem slug ou content_hash';
  END IF;

  SELECT id, content_hash INTO v_existing FROM public.help_articles WHERE slug = v_slug;

  IF v_existing.id IS NOT NULL AND v_existing.content_hash = v_hash THEN
    RETURN jsonb_build_object('slug', v_slug, 'status', 'unchanged', 'chunks', 0);
  END IF;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.help_articles (slug, title, module, updated_on, profiles, routes, sources, content_md, content_hash)
    VALUES (
      v_slug,
      _payload->>'title',
      _payload->>'module',
      (_payload->>'updated_on')::date,
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'profiles')), '{}'),
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'routes')), '{}'),
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'sources')), '{}'),
      _payload->>'content_md',
      v_hash
    ) RETURNING id INTO v_article_id;
    v_status := 'inserted';
  ELSE
    v_article_id := v_existing.id;
    UPDATE public.help_articles SET
      title = _payload->>'title',
      module = _payload->>'module',
      updated_on = (_payload->>'updated_on')::date,
      profiles = COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'profiles')), '{}'),
      routes = COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'routes')), '{}'),
      sources = COALESCE(ARRAY(SELECT jsonb_array_elements_text(_payload->'sources')), '{}'),
      content_md = _payload->>'content_md',
      content_hash = v_hash,
      synced_at = now()
    WHERE id = v_article_id;
    DELETE FROM public.help_sections WHERE article_id = v_article_id;
    v_status := 'updated';
  END IF;

  FOR v_section IN SELECT * FROM jsonb_array_elements(_payload->'sections')
  LOOP
    v_terms := COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_section->'terms')), '{}');

    INSERT INTO public.help_sections (article_id, anchor_id, heading, position, tooltip, screens, profiles, sources, terms, body_md)
    VALUES (
      v_article_id,
      v_section->>'anchor_id',
      v_section->>'heading',
      (v_section->>'position')::int,
      NULLIF(v_section->>'tooltip',''),
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_section->'screens')), '{}'),
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_section->'profiles')), '{}'),
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_section->'sources')), '{}'),
      v_terms,
      COALESCE(v_section->>'body_md','')
    ) RETURNING id INTO v_section_id;

    FOR v_chunk IN SELECT * FROM jsonb_array_elements(COALESCE(v_section->'chunks','[]'::jsonb))
    LOOP
      INSERT INTO public.help_chunks (section_id, position, content, search_text, embedding)
      VALUES (
        v_section_id,
        (v_chunk->>'position')::int,
        v_chunk->>'content',
        to_tsvector(
          'portuguese',
          extensions.unaccent(
            COALESCE(v_chunk->>'content','') || ' ' || COALESCE(array_to_string(v_terms, ' '), '')
          )
        ),
        CASE WHEN v_chunk->>'embedding' IS NULL THEN NULL ELSE (v_chunk->>'embedding')::extensions.vector END
      );
      v_chunks := v_chunks + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('slug', v_slug, 'status', v_status, 'chunks', v_chunks);
END;
$function$

CREATE OR REPLACE FUNCTION public.process_leads_capi_batch(p_batch_size integer DEFAULT 25)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  ld record; v_email text; v_phone text; v_phone_digits text; v_email_hash text; v_phone_hash text;
  v_event_name text; v_event_url text; v_pixel_id text; v_now timestamptz;
  v_user_data jsonb; v_custom_data jsonb; v_payload jsonb;
BEGIN
  IF NOT public.capi_dispatch_allowed() THEN RETURN; END IF;
  FOR ld IN
    SELECT l.* FROM public.leads l
    WHERE (l.capi_status IS NULL OR l.capi_status = 'retry')
      AND l.kind IS DISTINCT FROM 'redirect_click'
      AND l.created_at >= now() - interval '7 days'
    ORDER BY l.created_at DESC
    LIMIT GREATEST(p_batch_size, 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_now := now();
      IF ld.kind = 'redirect_click' OR ld.created_at < (v_now - interval '7 days')
         OR NOT public.capi_consent_proof(ld.id, 'ViewContent') THEN
        PERFORM public._capi_classify_lead(ld.id);
        CONTINUE;
      END IF;
      v_pixel_id := NULL; v_event_name := NULL; v_event_url := NULL;
      IF ld.event_id IS NOT NULL THEN
        SELECT NULLIF(btrim(coalesce(meta_pixel_id,'')), ''), name, ticketing_url
          INTO v_pixel_id, v_event_name, v_event_url FROM public.events WHERE id = ld.event_id LIMIT 1;
      END IF;
      IF v_pixel_id IS NULL THEN
        UPDATE public.leads SET capi_sent_at = v_now, capi_status = 'skipped_no_pixel' WHERE id = ld.id;
        CONTINUE;
      END IF;
      v_email := NULL; v_phone := NULL;
      IF ld.contact_id IS NOT NULL THEN
        SELECT NULLIF(lower(btrim(coalesce(email,''))), ''), NULLIF(btrim(coalesce(phone_e164,'')), '')
          INTO v_email, v_phone FROM public.contacts WHERE id = ld.contact_id LIMIT 1;
      END IF;
      v_phone_digits := NULLIF(regexp_replace(coalesce(v_phone,''), '[^0-9]', '', 'g'), '');
      v_email_hash := CASE WHEN v_email IS NOT NULL THEN encode(extensions.digest(v_email, 'sha256'), 'hex') END;
      v_phone_hash := CASE WHEN v_phone_digits IS NOT NULL THEN encode(extensions.digest(v_phone_digits, 'sha256'), 'hex') END;
      v_user_data := '{}'::jsonb;
      IF v_email_hash IS NOT NULL THEN v_user_data := v_user_data || jsonb_build_object('em', jsonb_build_array(v_email_hash)); END IF;
      IF v_phone_hash IS NOT NULL THEN v_user_data := v_user_data || jsonb_build_object('ph', jsonb_build_array(v_phone_hash)); END IF;
      IF ld.fbc IS NOT NULL AND ld.fbc <> '' THEN v_user_data := v_user_data || jsonb_build_object('fbc', ld.fbc); END IF;
      IF ld.fbp IS NOT NULL AND ld.fbp <> '' THEN v_user_data := v_user_data || jsonb_build_object('fbp', ld.fbp); END IF;
      IF ld.ip_inet IS NOT NULL THEN v_user_data := v_user_data || jsonb_build_object('client_ip_address', host(ld.ip_inet)); END IF;
      IF ld.user_agent IS NOT NULL AND ld.user_agent <> '' THEN v_user_data := v_user_data || jsonb_build_object('client_user_agent', ld.user_agent); END IF;
      v_custom_data := jsonb_build_object('content_name', coalesce(v_event_name, ''), 'content_category', 'event_ticket');
      v_payload := jsonb_build_object('pixel_id', v_pixel_id, 'event_name', 'ViewContent', 'event_id', ld.id::text,
        'event_time', extract(epoch from ld.created_at)::bigint, 'event_source_url', v_event_url,
        'user_data', v_user_data, 'custom_data', v_custom_data);
      UPDATE public.leads SET capi_sent_at = v_now, capi_status = 'processing' WHERE id = ld.id;
      RETURN NEXT jsonb_build_object('lead_id', ld.id, 'pixel_id', v_pixel_id, 'kind', ld.kind,
                                     'created_at', ld.created_at, 'payload', v_payload);
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.leads SET capi_status = 'error' WHERE id = ld.id;
    END;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._club332_consent_from_lead_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE s_id uuid; s_co uuid; mid uuid; v_email text; v_version text; v_key uuid;
BEGIN
  IF NEW.source IS DISTINCT FROM 'clube_newgang' OR NEW.email IS NULL THEN RETURN NEW; END IF;
  IF coalesce(NEW.consent_email,false) <> true THEN RETURN NEW; END IF;
  v_version := NEW.raw->>'consent_text_version';
  IF v_version IS DISTINCT FROM 'email-v3' THEN RETURN NEW; END IF;
  SELECT id, company_id INTO s_id, s_co FROM public.portal_sites
   WHERE brand_key='newgang' AND active AND company_id=NEW.company_id ORDER BY created_at LIMIT 1;
  IF s_id IS NULL THEN RETURN NEW; END IF;
  v_email := lower(btrim(NEW.email));
  IF EXISTS(SELECT 1 FROM public.suppressed_emails WHERE company_id=s_co AND email=v_email) THEN RETURN NEW; END IF;
  SELECT id INTO mid FROM public.club_members WHERE site_id=s_id AND lower(btrim(email))=v_email LIMIT 1;
  IF mid IS NULL THEN RETURN NEW; END IF;
  v_key := regexp_replace(md5('lc332:'||NEW.id::text),'(.{8})(.{4})(.{4})(.{4})(.{12})','\1-\2-\3-\4-\5')::uuid;
  BEGIN
    INSERT INTO public.club_member_email_consents(member_id,site_id,company_id,version,decision,decided_at,origin,idempotency_key)
    VALUES(mid,s_id,s_co,'email-v3','granted',NEW.created_at,'signup',v_key);
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '_club332_consent_from_lead_capture: %', SQLERRM; RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.process_lead_captures_batch(p_batch_size integer DEFAULT 50)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  MP_COMPANY_ID constant uuid := '7c858982-6ccd-47ca-bd65-e0dd3eebf01c';
  PORTAL_URL_BASE constant text := 'https://www.mundopropicio.com/eventos/';
  lc record;
  v_company_id uuid;
  v_email text;
  v_phone text;
  v_phone_digits text;
  v_email_hash text;
  v_phone_hash text;
  v_contact contacts%ROWTYPE;
  v_contact_id uuid;
  v_event_id uuid;
  v_pixel_id text;
  v_lead_id uuid;
  v_now timestamptz;
  v_user_data jsonb;
  v_payload jsonb;
BEGIN
  FOR lc IN
    SELECT * FROM public.lead_capture
    WHERE processed = false
    ORDER BY created_at ASC
    LIMIT GREATEST(p_batch_size, 1)
  LOOP
    BEGIN
      v_now := now();
      v_company_id := COALESCE(lc.company_id, MP_COMPANY_ID);
      v_email := NULLIF(lower(btrim(coalesce(lc.email, ''))), '');
      v_phone := NULLIF(btrim(coalesce(lc.phone, '')), '');
      v_phone_digits := NULLIF(regexp_replace(coalesce(v_phone, ''), '[^0-9]', '', 'g'), '');

      v_email_hash := CASE WHEN v_email IS NOT NULL
        THEN encode(extensions.digest(v_email, 'sha256'), 'hex') END;
      v_phone_hash := CASE WHEN v_phone_digits IS NOT NULL
        THEN encode(extensions.digest(v_phone_digits, 'sha256'), 'hex') END;

      v_contact := NULL;
      IF v_email IS NOT NULL THEN
        SELECT * INTO v_contact FROM public.contacts
        WHERE company_id = v_company_id AND email = v_email LIMIT 1;
      END IF;
      IF v_contact.id IS NULL AND v_phone IS NOT NULL THEN
        SELECT * INTO v_contact FROM public.contacts
        WHERE company_id = v_company_id AND phone_e164 = v_phone LIMIT 1;
      END IF;

      IF v_contact.id IS NOT NULL THEN
        UPDATE public.contacts SET
          email = coalesce(email, v_email),
          phone_e164 = coalesce(phone_e164, v_phone),
          name = coalesce(name, lc.name),
          source = coalesce(source, lc.source, 'portal_newsletter'),
          consent_email = consent_email OR coalesce(lc.consent_email, false),
          consent_whatsapp = consent_whatsapp OR coalesce(lc.consent_whatsapp, false),
          consent_email_at = CASE
            WHEN (consent_email OR coalesce(lc.consent_email,false))
              THEN coalesce(consent_email_at, v_now)
            ELSE NULL END,
          consent_whatsapp_at = CASE
            WHEN (consent_whatsapp OR coalesce(lc.consent_whatsapp,false))
              THEN coalesce(consent_whatsapp_at, v_now)
            ELSE NULL END,
          last_activity_at = v_now,
          updated_at = v_now
        WHERE id = v_contact.id;
        v_contact_id := v_contact.id;
      ELSE
        INSERT INTO public.contacts (
          company_id, email, phone_e164, name,
          consent_email, consent_whatsapp,
          consent_email_at, consent_whatsapp_at,
          source, last_activity_at
        ) VALUES (
          v_company_id, v_email, v_phone, lc.name,
          coalesce(lc.consent_email,false), coalesce(lc.consent_whatsapp,false),
          CASE WHEN coalesce(lc.consent_email,false) THEN v_now END,
          CASE WHEN coalesce(lc.consent_whatsapp,false) THEN v_now END,
          coalesce(lc.source,'portal_newsletter'), v_now
        )
        RETURNING id INTO v_contact_id;
      END IF;

      -- D-ERP276: confirmação por convite de email nunca gera conversão
      -- (sem linha em leads, sem payload CAPI). O contacto fica gravado.
      IF lc.source = 'coala_early_bird_invite' THEN
        UPDATE public.lead_capture
          SET processed = true, processed_at = v_now, processing_error = NULL
        WHERE id = lc.id;
        RETURN NEXT jsonb_build_object('skip', true, 'reason', 'no_conversion_source');
        CONTINUE;
      END IF;

      v_event_id := NULL; v_pixel_id := NULL;
      IF lc.event_slug IS NOT NULL THEN
        SELECT id, meta_pixel_id INTO v_event_id, v_pixel_id
        FROM public.events
        WHERE company_id = v_company_id AND slug = lc.event_slug
        LIMIT 1;
      END IF;

      INSERT INTO public.leads (
        company_id, contact_id, event_id, kind, source,
        utm_source, utm_medium, utm_campaign, utm_content,
        ip_inet, user_agent, fbc, fbp,
        geo_country, geo_city, geo_region
      ) VALUES (
        v_company_id, v_contact_id, v_event_id,
        CASE WHEN lc.event_slug IS NOT NULL THEN 'event_interest' ELSE 'newsletter_signup' END,
        lc.source, lc.utm_source, lc.utm_medium, lc.utm_campaign, lc.utm_content,
        lc.ip_inet, lc.user_agent, lc.fbc, lc.fbp,
        lc.geo_country, lc.geo_city, lc.geo_region
      )
      RETURNING id INTO v_lead_id;

      UPDATE public.lead_capture
        SET processed = true, processed_at = v_now, processing_error = NULL
      WHERE id = lc.id;

      IF v_pixel_id IS NULL THEN
        RETURN NEXT jsonb_build_object('skip', true, 'reason', 'no_pixel');
      ELSE
        v_user_data := '{}'::jsonb;
        IF v_email_hash IS NOT NULL THEN
          v_user_data := v_user_data || jsonb_build_object('em', jsonb_build_array(v_email_hash));
        END IF;
        IF v_phone_hash IS NOT NULL THEN
          v_user_data := v_user_data || jsonb_build_object('ph', jsonb_build_array(v_phone_hash));
        END IF;
        IF lc.fbc IS NOT NULL AND lc.fbc <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('fbc', lc.fbc);
        END IF;
        IF lc.fbp IS NOT NULL AND lc.fbp <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('fbp', lc.fbp);
        END IF;
        IF lc.ip_inet IS NOT NULL THEN
          v_user_data := v_user_data || jsonb_build_object('client_ip_address', host(lc.ip_inet));
        END IF;
        IF lc.user_agent IS NOT NULL AND lc.user_agent <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('client_user_agent', lc.user_agent);
        END IF;

        v_payload := jsonb_build_object(
          'pixel_id', v_pixel_id,
          'event_name', 'Lead',
          'event_id', coalesce(lc.client_event_id, v_lead_id),
          'event_source_url', PORTAL_URL_BASE || coalesce(lc.event_slug,''),
          'user_data', v_user_data,
          'custom_data', jsonb_build_object(
            'content_ids', CASE WHEN v_event_id IS NOT NULL
              THEN jsonb_build_array(v_event_id) ELSE '[]'::jsonb END,
            'content_name', 'event_interest',
            'content_category', 'event'
          )
        );
        RETURN NEXT v_payload;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      UPDATE public.lead_capture
        SET processing_error = left(SQLERRM, 500)
      WHERE id = lc.id;
      RETURN NEXT jsonb_build_object('skip', true, 'reason', 'error', 'detail', SQLERRM);
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_redirect_logs_batch(p_batch_size integer DEFAULT 50)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  MP_COMPANY_ID constant uuid := '7c858982-6ccd-47ca-bd65-e0dd3eebf01c';
  PORTAL_URL_BASE constant text := 'https://www.mundopropicio.com/eventos/';
  rl record;
  v_event_id uuid;
  v_pixel_id text;
  v_lead_id uuid;
  v_now timestamptz;
  v_user_data jsonb;
  v_payload jsonb;
BEGIN
  FOR rl IN
    SELECT * FROM public.redirect_log
    WHERE processed = false
    ORDER BY created_at ASC
    LIMIT GREATEST(p_batch_size, 1)
  LOOP
    BEGIN
      v_now := now();
      v_event_id := NULL; v_pixel_id := NULL;
      IF rl.event_slug IS NOT NULL THEN
        SELECT id, meta_pixel_id INTO v_event_id, v_pixel_id
        FROM public.events
        WHERE company_id = MP_COMPANY_ID AND slug = rl.event_slug
        LIMIT 1;
      END IF;

      INSERT INTO public.leads (
        company_id, contact_id, event_id, kind, source,
        utm_source, utm_medium, utm_campaign, utm_content,
        mp_click_id, ip_inet, user_agent, fbc, fbp,
        geo_country, geo_city, geo_region
      ) VALUES (
        MP_COMPANY_ID, NULL, v_event_id, 'redirect_click', 'portal_redirect',
        rl.utm_source, rl.utm_medium, rl.utm_campaign, rl.utm_content,
        rl.mp_click_id, rl.ip_inet, rl.user_agent, rl.fbc, rl.fbp,
        rl.geo_country, rl.geo_city, rl.geo_region
      )
      RETURNING id INTO v_lead_id;

      UPDATE public.redirect_log
        SET processed = true
      WHERE id = rl.id;

      IF v_pixel_id IS NULL THEN
        RETURN NEXT jsonb_build_object('skip', true, 'reason', 'no_pixel');
      ELSE
        v_user_data := '{}'::jsonb;
        IF rl.fbc IS NOT NULL AND rl.fbc <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('fbc', rl.fbc);
        END IF;
        IF rl.fbp IS NOT NULL AND rl.fbp <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('fbp', rl.fbp);
        END IF;
        IF rl.ip_inet IS NOT NULL THEN
          v_user_data := v_user_data || jsonb_build_object('client_ip_address', host(rl.ip_inet));
        END IF;
        IF rl.user_agent IS NOT NULL AND rl.user_agent <> '' THEN
          v_user_data := v_user_data || jsonb_build_object('client_user_agent', rl.user_agent);
        END IF;

        v_payload := jsonb_build_object(
          'pixel_id', v_pixel_id,
          'event_name', 'InitiateCheckout',
          'event_id', coalesce(rl.client_event_id, v_lead_id),
          'event_source_url', PORTAL_URL_BASE || coalesce(rl.event_slug,''),
          'user_data', v_user_data,
          'custom_data', jsonb_build_object(
            'content_ids', CASE WHEN v_event_id IS NOT NULL
              THEN jsonb_build_array(v_event_id) ELSE '[]'::jsonb END,
            'content_name', 'redirect_click',
            'content_category', 'event'
          )
        );
        RETURN NEXT v_payload;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      RETURN NEXT jsonb_build_object('skip', true, 'reason', 'error', 'detail', SQLERRM);
    END;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public._lead_capture_geo_local()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE r record; BEGIN
 IF NEW.ip_inet IS NOT NULL AND NEW.geo_country IS NULL AND NEW.geo_city IS NULL THEN
 BEGIN
 SELECT x.country,x.region,x.city,x.ip_to INTO r FROM public.ip_city_ranges x WHERE x.ip_from<=NEW.ip_inet ORDER BY x.ip_from DESC,x.source_month DESC LIMIT 1;
 IF FOUND AND r.ip_to>=NEW.ip_inet AND family(r.ip_to)=family(NEW.ip_inet) THEN
 NEW.geo_country:=nullif(btrim(r.country),''); NEW.geo_region:=nullif(btrim(r.region),''); NEW.geo_city:=nullif(btrim(r.city),'');
 END IF;
 EXCEPTION WHEN OTHERS THEN NULL; END;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._partner_extra_assert_can_write(p_event_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_status text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sem sessão.' USING ERRCODE = 'P0403'; END IF;
  IF public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'platform_admin'::app_role) THEN RETURN; END IF;
  IF NOT (public.has_role(v_uid, 'manager'::app_role) OR public.has_role(v_uid, 'editor'::app_role)) THEN
    RAISE EXCEPTION 'Sem permissão para gerir Extras do Sócio (só admin, manager ou editor).' USING ERRCODE = 'P0403';
  END IF;
  SELECT status INTO v_status FROM public.events WHERE id = p_event_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Evento inexistente ou sem acesso.' USING ERRCODE = 'P0403'; END IF;
  IF v_status = 'completed' THEN
    RAISE EXCEPTION 'O evento está concluído: só um admin pode criar ou reverter Extras do Sócio.' USING ERRCODE = 'P0403';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public._song_growth_summary_initial(p_song_id uuid, p_to date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  s record;
  v_artist_name text;
  v_notas jsonb := '[]'::jsonb;
  v_tec jsonb := '[]'::jsonb;
  v_rep_s text; v_rep_o text;
  g_musica jsonb := '[]'::jsonb;
  g_ugc jsonb := '[]'::jsonb;
  g_redes jsonb := '[]'::jsonb;
  b record; a record;
  spec record;
  v_line jsonb;
  v_pct numeric;
  v_last date; v_c0 numeric; v_c7 numeric; v_c14 numeric;
  v_sem_atual numeric; v_sem_ant numeric;
  v_streams_val numeric; v_streams_date date;
  v_ol jsonb; v_ugc jsonb;
  v_s4a_metric text;
  v_s4a_last date; v_s4a_n int; v_sem_fonte text; v_sem_fim date;
  v_agg_d date[]; v_agg_v numeric[]; v_d7 date; v_d14 date;
BEGIN
  SELECT * INTO s FROM public.artist_songs WHERE id = p_song_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'música inexistente' USING ERRCODE = 'P0002';
  END IF;
  PERFORM public.artist_access_check(s.artist_id,'read',NULL);
  SELECT name INTO v_artist_name FROM public.artists WHERE id = s.artist_id;

  IF s.release_date IS NULL THEN
    v_notas := v_notas || to_jsonb('Música sem data de lançamento: os valores iniciais são a primeira leitura disponível.'::text);
    v_tec := v_tec || to_jsonb('release_date NULL: todas as bases são primeira_medicao.'::text);
  END IF;

  FOR spec IN
    SELECT * FROM (VALUES
      ('musica','Spotify','streams','spotify','streams','aggregator','song'),
      ('video_ugc','TikTok','ugc_creators','tiktok','ugc_creators','tiktok_artists','song'),
      ('video_ugc','TikTok','ugc_views','tiktok','ugc_views','tiktok_artists','song'),
      ('video_ugc','TikTok for Artists','ugc_videos_painel','tiktok','ugc_videos','tiktok_artists','song'),
      ('redes','Instagram','seguidores','instagram','followers','aggregator','artist'),
      ('redes','TikTok','seguidores','tiktok','followers','aggregator','artist'),
      ('redes','Spotify','ouvintes_mensais','spotify','monthly_listeners','aggregator','artist'),
      ('redes','YouTube','inscritos','youtube','subscribers','aggregator','artist')
    ) t(grupo, canal, indicador, platform, metric, source, escopo)
  LOOP
    b := NULL; a := NULL;
    IF spec.escopo = 'song' THEN
      SELECT metric_date d, value v, 'lancamento' tipo INTO b FROM public.artist_song_metrics_daily
        WHERE song_id = p_song_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
          AND s.release_date IS NOT NULL AND metric_date <= s.release_date AND metric_date <= p_to
        ORDER BY metric_date DESC LIMIT 1;
      IF b.d IS NULL THEN
        SELECT metric_date d, value v, 'primeira_medicao' tipo INTO b FROM public.artist_song_metrics_daily
          WHERE song_id = p_song_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
            AND metric_date <= p_to
          ORDER BY metric_date ASC LIMIT 1;
      END IF;
      SELECT metric_date d, value v INTO a FROM public.artist_song_metrics_daily
        WHERE song_id = p_song_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
          AND metric_date <= p_to
        ORDER BY metric_date DESC LIMIT 1;
    ELSE
      SELECT metric_date d, value v, 'lancamento' tipo INTO b FROM public.artist_metrics_daily
        WHERE artist_id = s.artist_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
          AND s.release_date IS NOT NULL AND metric_date <= s.release_date AND metric_date <= p_to
        ORDER BY metric_date DESC LIMIT 1;
      IF b.d IS NULL THEN
        SELECT metric_date d, value v, 'primeira_medicao' tipo INTO b FROM public.artist_metrics_daily
          WHERE artist_id = s.artist_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
            AND metric_date <= p_to
          ORDER BY metric_date ASC LIMIT 1;
      END IF;
      SELECT metric_date d, value v INTO a FROM public.artist_metrics_daily
        WHERE artist_id = s.artist_id AND platform = spec.platform AND metric = spec.metric AND source = spec.source
          AND metric_date <= p_to
        ORDER BY metric_date DESC LIMIT 1;
    END IF;

    IF b.d IS NULL OR a.d IS NULL OR a.d = b.d THEN
      v_tec := v_tec || to_jsonb(format('%s %s: sem 2 medições em datas diferentes — linha omitida.', spec.canal, spec.indicador));
      CONTINUE;
    END IF;
    v_pct := CASE WHEN b.v = 0 THEN NULL ELSE (a.v - b.v) / b.v * 100 END;
    v_pct := CASE WHEN v_pct IS NULL THEN NULL WHEN abs(v_pct) < 0.1 THEN round(v_pct, 2) ELSE round(v_pct, 1) END;
    v_line := jsonb_build_object('canal', spec.canal, 'indicador', spec.indicador,
      'base', b.v, 'base_data', b.d, 'base_tipo', b.tipo, 'atual', a.v, 'atual_data', a.d,
      'variacao_pct', v_pct, 'source', spec.source, 'base_source', spec.source,
      'precisao', CASE WHEN spec.source = 'tiktok_artists' THEN 'painel_acumulado' ELSE 'serie' END);
    IF spec.grupo = 'musica' THEN g_musica := g_musica || v_line;
    ELSIF spec.grupo = 'video_ugc' THEN g_ugc := g_ugc || v_line;
    ELSE g_redes := g_redes || v_line; END IF;
    IF spec.metric = 'streams' THEN
      v_streams_val := a.v; v_streams_date := a.d;
      IF b.tipo = 'primeira_medicao' THEN
        v_notas := v_notas || to_jsonb(format('Streams medidos desde %s (primeira leitura disponível).', to_char(b.d,'DD/MM')));
      END IF;
    END IF;
    IF spec.indicador = 'ugc_videos_painel' THEN
      v_notas := v_notas || to_jsonb('Publicações no TikTok for Artists: contagem do painel, feita por outro método — não comparar com a do app.'::text);
    END IF;
    IF spec.metric = 'monthly_listeners' THEN
      v_ol := jsonb_build_object('chave','ouvintes_mensais','base',b.v,'atual',a.v,'variacao_pct',v_pct);
    END IF;
  END LOOP;

  FOR v_s4a_metric IN
    SELECT DISTINCT metric FROM public.artist_song_metrics_daily
    WHERE song_id = p_song_id AND metric LIKE 's4a\_%' AND metric_date <= p_to ORDER BY 1
  LOOP
    SELECT metric_date d, value v, source src INTO b FROM public.artist_song_metrics_daily
      WHERE song_id = p_song_id AND metric = v_s4a_metric AND metric_date <= p_to ORDER BY metric_date ASC LIMIT 1;
    SELECT metric_date d, value v, source src INTO a FROM public.artist_song_metrics_daily
      WHERE song_id = p_song_id AND metric = v_s4a_metric AND metric_date <= p_to ORDER BY metric_date DESC LIMIT 1;
    IF a.d = b.d THEN
      v_tec := v_tec || to_jsonb(format('S4A %s: só há registo em %s — linha omitida.', v_s4a_metric, b.d));
      CONTINUE;
    END IF;
    v_pct := CASE WHEN b.v = 0 THEN NULL ELSE (a.v - b.v) / b.v * 100 END;
    v_pct := CASE WHEN v_pct IS NULL THEN NULL WHEN abs(v_pct) < 0.1 THEN round(v_pct, 2) ELSE round(v_pct, 1) END;
    g_musica := g_musica || jsonb_build_object('canal','Spotify for Artists','indicador',v_s4a_metric,
      'base',b.v,'base_data',b.d,'base_tipo','primeira_medicao','atual',a.v,'atual_data',a.d,
      'variacao_pct',v_pct,'source',a.src,'base_source',b.src,'precisao','serie');
  END LOOP;

  WITH pts AS (
    SELECT DISTINCT ON (metric_date) metric_date d, value v, source src, source_ref ref
    FROM public.artist_song_metrics_daily
    WHERE song_id = p_song_id AND platform = 'tiktok' AND metric = 'ugc_videos'
      AND source IN ('ios_shortcut','manual') AND metric_date <= p_to
    ORDER BY metric_date, CASE source WHEN 'ios_shortcut' THEN 0 ELSE 1 END
  )
  SELECT
    (SELECT to_jsonb(x) FROM (SELECT * FROM pts WHERE s.release_date IS NOT NULL AND d <= s.release_date ORDER BY d DESC LIMIT 1) x) AS bl,
    (SELECT to_jsonb(x) FROM (SELECT * FROM pts ORDER BY d ASC LIMIT 1) x) AS bf,
    (SELECT to_jsonb(x) FROM (SELECT * FROM pts ORDER BY d DESC LIMIT 1) x) AS at
  INTO b;
  DECLARE vb jsonb; vt text; va jsonb; bv numeric; av numeric;
  BEGIN
    vb := coalesce(b.bl, b.bf); vt := CASE WHEN b.bl IS NOT NULL THEN 'lancamento' ELSE 'primeira_medicao' END;
    va := b.at;
    IF vb IS NULL OR va IS NULL OR (vb->>'d') = (va->>'d') THEN
      v_tec := v_tec || to_jsonb('TikTok ugc_videos: sem 2 medições em datas diferentes — linha omitida.'::text);
    ELSE
      bv := (vb->>'v')::numeric; av := (va->>'v')::numeric;
      v_pct := CASE WHEN bv = 0 THEN NULL ELSE (av - bv) / bv * 100 END;
      v_pct := CASE WHEN v_pct IS NULL THEN NULL WHEN abs(v_pct) < 0.1 THEN round(v_pct, 2) ELSE round(v_pct, 1) END;
      g_ugc := jsonb_build_object('canal','TikTok','indicador','ugc_videos',
        'base',bv,'base_data',(vb->>'d')::date,'base_tipo',vt,'atual',av,'atual_data',(va->>'d')::date,
        'variacao_pct',v_pct,'source',va->>'src','base_source',vb->>'src',
        'precisao', CASE WHEN va->>'src' = 'ios_shortcut' THEN 'arredondado_app' ELSE 'leitura_manual' END) || g_ugc;
      v_ugc := jsonb_build_object('chave','ugc_videos','base',bv,'atual',av,'variacao_pct',v_pct);
      IF va->>'src' = 'ios_shortcut' THEN
        v_notas := v_notas || to_jsonb('Publicações no TikTok: contagem aproximada do app.'::text);
      END IF;
      IF (vb->>'src') <> (va->>'src') THEN
        v_tec := v_tec || to_jsonb(format('ugc_videos: base %s (%s) e atual %s (%s) — excepção de precedência ios_shortcut > manual.',
          vb->>'d', vb->>'src', va->>'d', va->>'src'));
      END IF;
    END IF;
  END;

  -- Semana de streams: dia com valor igual ao do dia anterior (aggregator) = sem leitura Soundcharts.
  SELECT string_agg(to_char(d,'YYYY-MM-DD'), ', ' ORDER BY d) INTO v_rep_s FROM (
    SELECT metric_date d, value v, lag(value) OVER (ORDER BY metric_date) pv, lag(metric_date) OVER (ORDER BY metric_date) pd
    FROM public.artist_song_metrics_daily
    WHERE song_id=p_song_id AND platform='spotify' AND metric='streams' AND source='aggregator' AND metric_date <= p_to) x
  WHERE pd = d - 1 AND pv = v;
  IF v_rep_s IS NOT NULL THEN
    v_tec := v_tec || to_jsonb(format('streams aggregator: dias repetidos (Soundcharts sem actualização) omitidos: %s.', v_rep_s));
  END IF;
  -- Semana de streams (D-ERP54 adenda 26/09): fonte primária S4A diário (s4a_streams_day), 14 dias seguidos
  -- terminando perto de p_to; senão fallback aggregator por diferença do acumulado (tolerância ±1 dia).
  SELECT max(metric_date) INTO v_s4a_last FROM public.artist_song_metrics_daily
    WHERE song_id=p_song_id AND metric='s4a_streams_day' AND metric_date <= p_to;
  IF v_s4a_last IS NOT NULL AND v_s4a_last >= p_to - 5 THEN
    SELECT count(*), sum(v) FILTER (WHERE d > v_s4a_last-7), sum(v) FILTER (WHERE d <= v_s4a_last-7)
      INTO v_s4a_n, v_sem_atual, v_sem_ant
    FROM (SELECT DISTINCT ON (metric_date) metric_date d, value v FROM public.artist_song_metrics_daily
          WHERE song_id=p_song_id AND metric='s4a_streams_day' AND metric_date BETWEEN v_s4a_last-13 AND v_s4a_last
          ORDER BY metric_date, CASE source WHEN 's4a_api' THEN 0 ELSE 1 END) x;
  END IF;
  IF coalesce(v_s4a_n,0) = 14 THEN
    v_sem_fonte := 's4a_streams_day'; v_sem_fim := v_s4a_last;
    v_notas := v_notas || to_jsonb(format('Streams da semana até %s (Spotify for Artists).', to_char(v_s4a_last,'DD/MM')));
    v_tec := v_tec || to_jsonb(format('streams_semana: fonte s4a_streams_day, %s–%s vs %s–%s (atraso S4A %s dias face a p_to).',
      v_s4a_last-6, v_s4a_last, v_s4a_last-13, v_s4a_last-7, p_to - v_s4a_last));
  ELSE
    v_sem_atual := NULL; v_sem_ant := NULL;
    IF v_s4a_last IS NOT NULL THEN
      v_tec := v_tec || to_jsonb(format('streams_semana: S4A insuficiente (último %s, %s de 14 dias seguidos) — fallback aggregator.', v_s4a_last, coalesce(v_s4a_n,0)));
    ELSE
      v_tec := v_tec || to_jsonb('streams_semana: sem s4a_streams_day — fallback aggregator.'::text);
    END IF;
    SELECT array_agg(d ORDER BY d), array_agg(v ORDER BY d) INTO v_agg_d, v_agg_v FROM (
      SELECT d, v FROM (SELECT metric_date d, value v, lag(value) OVER (ORDER BY metric_date) pv, lag(metric_date) OVER (ORDER BY metric_date) pd
        FROM public.artist_song_metrics_daily WHERE song_id=p_song_id AND platform='spotify' AND metric='streams' AND source='aggregator' AND metric_date <= p_to) x0
      WHERE NOT (pd IS NOT NULL AND pd = d - 1 AND pv = v)) ss;
    IF v_agg_d IS NOT NULL THEN
      v_last := v_agg_d[array_length(v_agg_d,1)];
      v_c0 := v_agg_v[array_length(v_agg_v,1)];
      SELECT dd, vv INTO v_d7, v_c7 FROM unnest(v_agg_d, v_agg_v) u(dd, vv)
        WHERE abs(dd - (v_last-7)) <= 1 ORDER BY abs(dd - (v_last-7)), dd LIMIT 1;
      IF v_d7 IS NOT NULL THEN
        SELECT dd, vv INTO v_d14, v_c14 FROM unnest(v_agg_d, v_agg_v) u(dd, vv)
          WHERE abs(dd - (v_d7-7)) <= 1 ORDER BY abs(dd - (v_d7-7)), dd LIMIT 1;
      END IF;
      v_sem_fonte := 'aggregator_diferenca'; v_sem_fim := v_last;
      v_sem_atual := CASE WHEN v_c7 IS NOT NULL THEN v_c0 - v_c7 END;
      v_sem_ant := CASE WHEN v_c7 IS NOT NULL AND v_c14 IS NOT NULL THEN v_c7 - v_c14 END;
      IF v_d7 IS NOT NULL AND v_d7 <> v_last-7 THEN
        v_tec := v_tec || to_jsonb(format('streams_semana (fallback): %s ausente ou repetido — usado %s (semana de %s dias).', v_last-7, v_d7, v_last - v_d7));
      END IF;
      IF v_d14 IS NOT NULL AND v_d14 <> v_d7-7 THEN
        v_tec := v_tec || to_jsonb(format('streams_semana (fallback): %s ausente ou repetido — usado %s para a semana anterior.', v_d7-7, v_d14));
      END IF;
      IF v_c7 IS NULL THEN
        v_notas := v_notas || to_jsonb(format('Streams da semana não calculados: sem leitura perto de %s.', to_char(v_last-7,'DD/MM')));
        v_tec := v_tec || to_jsonb(format('streams_semana (fallback): sem ponto a ±1 dia de %s — semana atual null.', v_last-7));
      ELSIF v_c14 IS NULL THEN
        v_notas := v_notas || to_jsonb(format('Streams da semana anterior não calculados: sem leitura perto de %s.', to_char(v_d7-7,'DD/MM')));
        v_tec := v_tec || to_jsonb(format('streams_semana (fallback): sem ponto a ±1 dia de %s — semana anterior null.', v_d7-7));
      ELSE
        v_notas := v_notas || to_jsonb(format('Streams da semana até %s.', to_char(v_last,'DD/MM')));
      END IF;
    END IF;
  END IF;
  SELECT string_agg(to_char(d,'YYYY-MM-DD'), ', ' ORDER BY d) INTO v_rep_o FROM (
    SELECT metric_date d, value v, lag(value) OVER (ORDER BY metric_date) pv, lag(metric_date) OVER (ORDER BY metric_date) pd
    FROM public.artist_metrics_daily
    WHERE artist_id=s.artist_id AND platform='spotify' AND metric='monthly_listeners' AND source='aggregator' AND metric_date <= p_to) x
  WHERE pd = d - 1 AND pv = v AND (s.release_date IS NULL OR d >= s.release_date - 7);
  IF v_rep_o IS NOT NULL THEN
    v_tec := v_tec || to_jsonb(format('monthly_listeners aggregator: dias repetidos omitidos da série: %s.', v_rep_o));
  END IF;
  -- D-ERP160: limpeza do grupo musica (só grupos[]; kpis e series intactos).
  DECLARE v_out jsonb := '[]'::jsonb; v_ln jsonb; v_ind text; v_omit_day text[] := '{}'; v_omit_28 text[] := '{}';
    v_mais28 boolean := s.release_date IS NOT NULL AND p_to - s.release_date > 28;
  BEGIN
    FOR v_ln IN SELECT * FROM jsonb_array_elements(g_musica) LOOP
      v_ind := v_ln->>'indicador';
      IF v_ind LIKE 's4a\_%\_day' THEN
        v_omit_day := v_omit_day || v_ind; CONTINUE;
      END IF;
      IF v_mais28 AND v_ind LIKE 's4a\_%\_28d' THEN
        IF EXISTS (SELECT 1 FROM jsonb_array_elements(g_musica) g
                   WHERE g->>'indicador' = regexp_replace(v_ind, '_28d$', '_since_release')
                     AND g->'atual' IS NOT NULL AND g->'atual' <> 'null'::jsonb) THEN
          v_omit_28 := v_omit_28 || v_ind; CONTINUE;
        END IF;
        v_ln := v_ln || jsonb_build_object('janela', '28d');
      END IF;
      v_out := v_out || v_ln;
    END LOOP;
    g_musica := v_out;
    IF array_length(v_omit_day, 1) > 0 THEN
      v_tec := v_tec || to_jsonb(format('grupo musica: omitidas %s — valor de um dia contra base de outro dia não é crescimento (continuam em kpis/series quando usadas).', array_to_string(v_omit_day, ', ')));
    END IF;
    IF array_length(v_omit_28, 1) > 0 THEN
      v_tec := v_tec || to_jsonb(format('grupo musica: música com mais de 28 dias — omitidas %s porque existe a gémea *_since_release com valor; as *_28d sem gémea ficam com janela=28d.', array_to_string(v_omit_28, ', ')));
    END IF;
  END;

  v_pct := CASE WHEN v_sem_ant IS NULL OR v_sem_ant = 0 OR v_sem_atual IS NULL THEN NULL ELSE (v_sem_atual - v_sem_ant) / v_sem_ant * 100 END;
  v_pct := CASE WHEN v_pct IS NULL THEN NULL WHEN abs(v_pct) < 0.1 THEN round(v_pct, 2) ELSE round(v_pct, 1) END;

  RETURN jsonb_build_object(
    'musica', jsonb_build_object('song_id', s.id, 'titulo', s.title,
      'artistas', to_jsonb(ARRAY[v_artist_name] || coalesce(s.featuring, ARRAY[]::text[])),
      'lancamento', s.release_date, 'dias', CASE WHEN s.release_date IS NULL THEN NULL ELSE p_to - s.release_date END),
    'kpis', jsonb_build_array(
      jsonb_build_object('chave','streams_spotify','valor',v_streams_val,'data',v_streams_date),
      jsonb_build_object('chave','streams_semana','valor',v_sem_atual,'anterior',v_sem_ant,'variacao_pct',v_pct,'semana_ate',v_sem_fim,'fonte',v_sem_fonte),
      coalesce(v_ol, jsonb_build_object('chave','ouvintes_mensais','base',null,'atual',null,'variacao_pct',null)),
      coalesce(v_ugc, jsonb_build_object('chave','ugc_videos','base',null,'atual',null,'variacao_pct',null))),
    'grupos', jsonb_build_array(
      jsonb_build_object('grupo','musica','linhas',g_musica),
      jsonb_build_object('grupo','video_ugc','linhas',g_ugc),
      jsonb_build_object('grupo','redes','linhas',g_redes)),
    'series', jsonb_build_object(
      'streams_acumulados', coalesce((SELECT jsonb_agg(jsonb_build_object('d',d,'v',v) ORDER BY d) FROM (SELECT d, v FROM (SELECT metric_date d, value v, lag(value) OVER (ORDER BY metric_date) pv, lag(metric_date) OVER (ORDER BY metric_date) pd FROM public.artist_song_metrics_daily WHERE song_id=p_song_id AND platform='spotify' AND metric='streams' AND source='aggregator' AND metric_date <= p_to) x0 WHERE NOT (pd IS NOT NULL AND pd = d - 1 AND pv = v)) ss), '[]'::jsonb),
      'ouvintes_mensais', coalesce((SELECT jsonb_agg(jsonb_build_object('d',d,'v',v) ORDER BY d) FROM (
          SELECT metric_date d, value v, lag(value) OVER (ORDER BY metric_date) pv, lag(metric_date) OVER (ORDER BY metric_date) pd
          FROM public.artist_metrics_daily WHERE artist_id=s.artist_id AND platform='spotify' AND metric='monthly_listeners' AND source='aggregator'
            AND metric_date <= p_to) x
          WHERE NOT (pd IS NOT NULL AND pd = d - 1 AND pv = v) AND (s.release_date IS NULL OR d >= s.release_date - 7)), '[]'::jsonb)),
    'notas', v_notas,
    'notas_tecnicas', v_tec,
    'gerado_em', now());
END $function$

CREATE OR REPLACE FUNCTION public.audit_transactions_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  f text; o jsonb := '{}'; n jsonb := '{}'; v_old jsonb; v_new jsonb;
  fields constant text[] := ARRAY['status','amount','reversed_at','payment_date','account_id','event_id'];
BEGIN
  v_old := CASE WHEN TG_OP <> 'INSERT' THEN to_jsonb(OLD) END;
  v_new := CASE WHEN TG_OP <> 'DELETE' THEN to_jsonb(NEW) END;
  FOREACH f IN ARRAY fields LOOP
    IF TG_OP = 'UPDATE' AND (v_old -> f) IS NOT DISTINCT FROM (v_new -> f) THEN CONTINUE; END IF;
    IF v_old IS NOT NULL THEN o := o || jsonb_build_object(f, v_old -> f); END IF;
    IF v_new IS NOT NULL THEN n := n || jsonb_build_object(f, v_new -> f); END IF;
  END LOOP;
  IF TG_OP = 'UPDATE' AND n = '{}'::jsonb THEN RETURN NEW; END IF;
  BEGIN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id)
    VALUES ('transactions', coalesce(NEW.id, OLD.id)::text,
            CASE TG_OP WHEN 'INSERT' THEN 'create' WHEN 'UPDATE' THEN 'update' ELSE 'delete' END,
            coalesce(auth.uid()::text, 'system'),
            CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE o END,
            CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE n END,
            jsonb_build_object('op', TG_OP, 'fields', 'status,amount,reversed_at,payment_date,account_id,event_id'),
            coalesce(NEW.company_id, OLD.company_id));
  EXCEPTION WHEN foreign_key_violation OR not_null_violation THEN NULL;
  END;
  RETURN coalesce(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.backup_enqueue_slice(p_body jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE k text; rid bigint;
BEGIN
  SELECT decrypted_secret INTO k FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key' LIMIT 1;
  IF k IS NULL THEN RAISE EXCEPTION 'service role key indisponível'; END IF;
  SELECT net.http_post(
    url := 'https://sfohvvlqccmmebvjgibx.supabase.co/functions/v1/database-backup',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||k),
    body := p_body,
    timeout_milliseconds := 5000
  ) INTO rid;
  RETURN rid;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_reversal_on_repay()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_tx public.transactions; v_by text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'paid' OR NEW.reversed_at IS NOT NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_tx FROM public.transactions WHERE id = NEW.transaction_id;
  IF v_tx.id IS NULL OR v_tx.reversed_at IS NULL THEN RETURN NEW; END IF;
  v_by := coalesce(NEW.created_by, nullif(auth.jwt() ->> 'email', ''), 'sistema');
  UPDATE public.transactions
     SET reversed_at = NULL, reversed_by = NULL,
         status = CASE WHEN status = 'reversed' THEN 'approved' ELSE status END
   WHERE id = v_tx.id;
  INSERT INTO public.transaction_audit_log (transaction_id, changed_by, changed_at, field_name, old_value, new_value, company_id)
  VALUES (v_tx.id, v_by, now(), 'reversed_at',
          'Estornada em ' || to_char(v_tx.reversed_at, 'YYYY-MM-DD') || coalesce(' (' || v_tx.reversal_reason || ')', ''),
          'Repaga em ' || NEW.payment_date::text || ' — estorno limpo (#101)', v_tx.company_id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.club_profile_preferences(p_site uuid, p_session_hash text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE m uuid; again uuid; decision text; v_key uuid; purposes text[]; bd date; current_state jsonb; prior_key boolean; expected jsonb; purpose_name text;
BEGIN
 m:=public._club332_session(p_site,p_session_hash);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) fields(key) WHERE fields.key NOT IN ('channel','version','granted','platforms','idempotency_key','expected_dates')) OR jsonb_typeof(p_payload->'granted') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'consent_payload'; END IF;
 BEGIN v_key:=(p_payload->>'idempotency_key')::uuid; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'consent_payload'; END;
 IF v_key IS NULL THEN RAISE EXCEPTION 'consent_payload'; END IF;
 decision:=CASE WHEN (p_payload->>'granted')::boolean THEN 'granted' ELSE 'revoked' END;
 PERFORM public._club_site_lock(p_site,false);
 PERFORM 1 FROM public.club_members WHERE id=m FOR NO KEY UPDATE;
 again:=public._club332_session(p_site,p_session_hash);
 IF again<>m THEN RAISE EXCEPTION 'no_session'; END IF;
 IF decision='granted' THEN SELECT birth_date INTO bd FROM public.club_member_profiles WHERE member_id=m AND site_id=p_site; IF bd IS NULL OR bd>((clock_timestamp() AT TIME ZONE 'Europe/Lisbon')::date-interval '13 years')::date THEN RAISE EXCEPTION 'parental_flow_required'; END IF; END IF;
 IF p_payload->>'channel'='email' THEN
  IF p_payload->>'version' IS DISTINCT FROM 'email-v3' OR p_payload ? 'platforms' THEN RAISE EXCEPTION 'consent_payload'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.club_member_email_consents WHERE member_id=m AND site_id=p_site AND idempotency_key=v_key) INTO prior_key;
  IF decision='granted' AND NOT prior_key THEN current_state:=public._club332_state(m,p_site); expected:=p_payload->'expected_dates'; IF jsonb_typeof(expected) IS DISTINCT FROM 'object' OR NOT expected ? 'email' OR expected->'email' IS DISTINCT FROM current_state#>'{email,date}' THEN RAISE EXCEPTION 'consent_revision_conflict'; END IF; END IF;
  PERFORM public._club332_email_append(m,p_site,decision,v_key,'club_session');
 ELSIF p_payload->>'channel'='ads' THEN
  IF p_payload->>'version' IS DISTINCT FROM 'anuncios-v1' OR jsonb_typeof(p_payload->'platforms') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'platforms') v WHERE jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'consent_payload'; END IF;
  SELECT array_agg(v) INTO purposes FROM jsonb_array_elements_text(p_payload->'platforms') v;
  IF cardinality(purposes) IS NULL OR cardinality(purposes) NOT BETWEEN 1 AND 3 OR EXISTS(SELECT 1 FROM unnest(purposes) p WHERE p NOT IN ('meta_ads','tiktok_ads','google_ads')) OR cardinality(purposes)<>(SELECT count(DISTINCT p) FROM unnest(purposes) p) THEN RAISE EXCEPTION 'consent_payload'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.club_member_marketing_consents WHERE member_id=m AND site_id=p_site AND request_key=v_key) INTO prior_key;
  IF decision='granted' AND NOT prior_key THEN current_state:=public._club332_state(m,p_site); expected:=p_payload->'expected_dates'; IF jsonb_typeof(expected) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'consent_revision_conflict'; END IF; FOREACH purpose_name IN ARRAY purposes LOOP IF NOT expected ? purpose_name OR expected->purpose_name IS DISTINCT FROM current_state#>ARRAY['ads',purpose_name,'date'] THEN RAISE EXCEPTION 'consent_revision_conflict'; END IF; END LOOP; END IF;
  PERFORM public._club332_ads_append(m,p_site,decision,purposes,v_key,'club_session');
 ELSIF p_payload->>'channel'='whatsapp' THEN
  IF p_payload->>'version' IS DISTINCT FROM 'whatsapp-v1' OR p_payload ? 'platforms' THEN RAISE EXCEPTION 'consent_payload'; END IF;
  SELECT EXISTS(SELECT 1 FROM public.club_member_whatsapp_consents WHERE member_id=m AND site_id=p_site AND idempotency_key=v_key) INTO prior_key;
  IF decision='granted' AND NOT prior_key THEN current_state:=public._club332_state(m,p_site); expected:=p_payload->'expected_dates'; IF jsonb_typeof(expected) IS DISTINCT FROM 'object' OR NOT expected ? 'whatsapp' OR expected->'whatsapp' IS DISTINCT FROM current_state#>'{whatsapp,date}' THEN RAISE EXCEPTION 'consent_revision_conflict'; END IF; END IF;
  PERFORM public._club332_whatsapp_append(m,p_site,decision,v_key,'club_session');
 ELSE RAISE EXCEPTION 'consent_payload'; END IF;
 RETURN jsonb_build_object('ok',true,'consents',public._club332_state(m,p_site));
END $function$

CREATE OR REPLACE FUNCTION public.email_unsubscribe_atomic(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE tok public.email_unsubscribe_tokens; m record;
BEGIN
 SELECT * INTO tok FROM public.email_unsubscribe_tokens WHERE token=p_token FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('error','Invalid or expired token'); END IF;
 IF tok.used_at IS NOT NULL THEN RETURN jsonb_build_object('valid',false,'reason','already_unsubscribed'); END IF;
 FOR m IN SELECT DISTINCT cm.site_id FROM public.club_members cm JOIN public.portal_sites s ON s.id=cm.site_id AND s.company_id=cm.company_id WHERE (tok.company_id IS NULL OR cm.company_id=tok.company_id) AND lower(btrim(cm.email))=lower(btrim(tok.email)) AND s.brand_key='newgang' ORDER BY cm.site_id LOOP PERFORM public._club_site_lock(m.site_id,false); END LOOP;
 FOR m IN SELECT cm.id,cm.site_id FROM public.club_members cm JOIN public.portal_sites s ON s.id=cm.site_id AND s.company_id=cm.company_id WHERE (tok.company_id IS NULL OR cm.company_id=tok.company_id) AND lower(btrim(cm.email))=lower(btrim(tok.email)) AND s.brand_key='newgang' ORDER BY cm.site_id,cm.id LOOP
 PERFORM 1 FROM public.club_members WHERE id=m.id FOR NO KEY UPDATE;
 PERFORM public._club332_email_append(m.id,m.site_id,'revoked',tok.id,'email_unsubscribe');
 PERFORM public._club332_ads_append(m.id,m.site_id,'revoked',ARRAY['meta_ads','tiktok_ads','google_ads'],tok.id,'email_unsubscribe');
 END LOOP;
 INSERT INTO public.suppressed_emails(email,reason,company_id) VALUES(lower(btrim(tok.email)),'unsubscribe',tok.company_id) ON CONFLICT(email,company_id) DO UPDATE SET reason=EXCLUDED.reason;
 UPDATE public.email_unsubscribe_tokens SET used_at=clock_timestamp() WHERE id=tok.id;
 RETURN jsonb_build_object('success',true);
END $function$

CREATE OR REPLACE FUNCTION public.profiles_guard_active_company()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_via text := CASE WHEN current_setting('app.via_set_active_company', true) = 'on' THEN 'set_active_company' ELSE 'update_directo' END;
  v_uid uuid := auth.uid();
  v_h jsonb := nullif(current_setting('request.headers', true), '')::jsonb;
BEGIN
  IF NEW.active_company_id IS NOT DISTINCT FROM OLD.active_company_id THEN
    RETURN NEW;
  END IF;
  IF v_uid IS NOT NULL AND v_via = 'update_directo' THEN
    RAISE EXCEPTION 'active_company_id só pode mudar por set_active_company'
      USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.system_audit_log
    (entity_type, entity_id, action, changed_by, old_data, new_data, metadata, company_id)
  VALUES
    ('profile', NEW.id::text, 'active_company_changed',
     coalesce(v_uid::text, current_user),
     jsonb_build_object('active_company_id', OLD.active_company_id),
     jsonb_build_object('active_company_id', NEW.active_company_id),
     jsonb_build_object('via', v_via,
       'origin', v_h->>'origin', 'referer', v_h->>'referer', 'user_agent', v_h->>'user-agent'),
     NEW.active_company_id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ticketline_sync_runs_compact_audit(_days integer DEFAULT 7)
 RETURNS TABLE(compacted_rows bigint, before_bytes numeric, after_bytes numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_role text := COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  v_id uuid;
  v_old jsonb;
  v_new jsonb;
  v_n bigint := 0;
  v_before numeric := 0;
  v_after numeric := 0;
BEGIN
  -- #204: só service_role (cron/edge) ou sessão sem claims (postgres/migração).
  IF v_role NOT IN ('service_role', '') THEN
    RAISE EXCEPTION 'Apenas service_role pode compactar o histórico de sincronização.' USING ERRCODE = '42501';
  END IF;

  FOR v_id, v_old IN
    SELECT r.id, r.import_audit
      FROM public.ticketline_sync_runs r
     WHERE r.import_audit IS NOT NULL
       AND jsonb_typeof(r.import_audit) = 'object'
       AND r.import_audit->>'compacted_at' IS NULL
       AND COALESCE(r.created_at, r.started_at) < now() - make_interval(days => GREATEST(COALESCE(_days, 7), 0))
     ORDER BY COALESCE(r.created_at, r.started_at)
  LOOP
    v_before := v_before + pg_column_size(v_old);

    SELECT COALESCE(jsonb_object_agg(e.k,
             CASE
               WHEN jsonb_typeof(e.val) = 'array' THEN
                 jsonb_build_object('_array_count', jsonb_array_length(e.val))
               WHEN jsonb_typeof(e.val) = 'object' THEN
                 CASE WHEN pg_column_size(e.val) <= 2000 THEN e.val
                      ELSE jsonb_build_object('_keys',
                             (SELECT count(*) FROM jsonb_object_keys(e.val)))
                 END
               ELSE e.val
             END), '{}'::jsonb)
      INTO v_new
      FROM jsonb_each(v_old) AS e(k, val);

    -- preserva uma amostra dos avisos e dos erros para diagnóstico
    IF jsonb_typeof(v_old->'warnings') = 'array' THEN
      v_new := v_new || jsonb_build_object('warnings_sample',
        COALESCE((SELECT jsonb_agg(w) FROM (
          SELECT w FROM jsonb_array_elements(v_old->'warnings') w LIMIT 5
        ) s), '[]'::jsonb));
    END IF;
    IF jsonb_typeof(v_old->'errors') = 'array' THEN
      v_new := v_new || jsonb_build_object('errors_sample',
        COALESCE((SELECT jsonb_agg(w) FROM (
          SELECT w FROM jsonb_array_elements(v_old->'errors') w LIMIT 10
        ) s), '[]'::jsonb));
    END IF;

    v_new := v_new || jsonb_build_object('compacted_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'));

    UPDATE public.ticketline_sync_runs SET import_audit = v_new WHERE id = v_id;

    v_after := v_after + pg_column_size(v_new);
    v_n := v_n + 1;
  END LOOP;

  RETURN QUERY SELECT v_n, v_before, v_after;
END;
$function$

CREATE OR REPLACE FUNCTION public.club_welcome_mark(p_member_id uuid, p_status text, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n integer;
BEGIN
  IF p_status NOT IN ('enqueued','error_pre_send','unknown') OR p_status IS NULL THEN RAISE EXCEPTION 'invalid status'; END IF;
  UPDATE public.club_welcome_reservations SET status=p_status,error=left(p_error,300),updated_at=clock_timestamp(),
    retry_safe=(p_status='error_pre_send'),
    next_attempt_at=CASE WHEN p_status='error_pre_send' AND attempt_count<3 THEN clock_timestamp()+interval '5 minutes' END
  WHERE member_id=p_member_id AND (status='reserved' OR (status='unknown' AND p_status='enqueued'));
  GET DIAGNOSTICS n=ROW_COUNT;
  RETURN n>0;
END $function$

CREATE OR REPLACE FUNCTION public.crm_ingest_clube_captures_by_ids(p_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  MP_CO constant uuid := '7c858982-6ccd-47ca-bd65-e0dd3eebf01c';
  lc record; v_email text; v_contact_id uuid; v_n int; v_event_id uuid; v_lead_id uuid;
  res jsonb := '[]'::jsonb;
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 OR cardinality(p_ids) > 10 THEN
    RAISE EXCEPTION 'p_ids obrigatório (1..10 IDs explícitos)';
  END IF;
  FOR lc IN
    SELECT * FROM public.lead_capture WHERE id = ANY(p_ids) ORDER BY created_at, id FOR UPDATE
  LOOP
    IF lc.processed OR lc.source IS DISTINCT FROM 'clube_newgang' OR lc.company_id IS DISTINCT FROM MP_CO THEN
      res := res || jsonb_build_object('id', lc.id, 'result', 'skip_fora_de_ambito_ou_ja_processado');
      CONTINUE;
    END IF;
    v_email := NULLIF(lower(btrim(coalesce(lc.email,''))), '');
    IF v_email IS NULL THEN
      res := res || jsonb_build_object('id', lc.id, 'result', 'skip_sem_email');
      CONTINUE;
    END IF;
    SELECT count(*), min(id::text)::uuid INTO v_n, v_contact_id FROM public.contacts
     WHERE company_id = MP_CO AND lower(btrim(email)) = v_email;
    IF v_n > 1 THEN
      res := res || jsonb_build_object('id', lc.id, 'result', 'skip_identidade_ambigua');
      CONTINUE;
    END IF;
    BEGIN
      IF v_contact_id IS NOT NULL THEN
        UPDATE public.contacts SET
          name = coalesce(name, NULLIF(btrim(lc.name), '')),
          last_activity_at = greatest(last_activity_at, lc.created_at),
          updated_at = now()
        WHERE id = v_contact_id;
      ELSE
        INSERT INTO public.contacts (company_id, email, name, consent_email, consent_whatsapp,
          consent_email_at, consent_whatsapp_at, source, first_seen_at, last_activity_at)
        VALUES (MP_CO, v_email, NULLIF(btrim(lc.name), ''), coalesce(lc.consent_email,false),
          coalesce(lc.consent_whatsapp,false),
          CASE WHEN coalesce(lc.consent_email,false) THEN lc.created_at END,
          CASE WHEN coalesce(lc.consent_whatsapp,false) THEN lc.created_at END,
          lc.source, lc.created_at, lc.created_at)
        RETURNING id INTO v_contact_id;
      END IF;
      SELECT id INTO v_lead_id FROM public.leads WHERE meta->>'lead_capture_id' = lc.id::text LIMIT 1;
      IF v_lead_id IS NULL THEN
        v_event_id := NULL;
        IF lc.event_slug IS NOT NULL THEN
          SELECT id INTO v_event_id FROM public.events WHERE company_id = MP_CO AND slug = lc.event_slug LIMIT 1;
        END IF;
        INSERT INTO public.leads (company_id, contact_id, event_id, kind, source,
          utm_source, utm_medium, utm_campaign, utm_content, ip_inet, user_agent, fbc, fbp,
          geo_country, geo_city, geo_region, created_at, meta, capi_status, capi_block_reason, capi_classified_at)
        VALUES (MP_CO, v_contact_id, v_event_id,
          CASE WHEN lc.event_slug IS NOT NULL THEN 'event_interest' ELSE 'newsletter_signup' END,
          lc.source, lc.utm_source, lc.utm_medium, lc.utm_campaign, lc.utm_content,
          lc.ip_inet, lc.user_agent, lc.fbc, lc.fbp, lc.geo_country, lc.geo_city, lc.geo_region,
          lc.created_at,
          jsonb_build_object('lead_capture_id', lc.id, 'ingested_by', 'crm_ingest_clube_captures_by_ids', 'issue', 321),
          'blocked_no_consent',
          'ingestão interna #321 — sem prova de consentimento marketing por interacção; não elegível CAPI',
          now())
        RETURNING id INTO v_lead_id;
      END IF;
      -- Dispara o fluxo normal do Clube (membro + confirmação existente).
      UPDATE public.lead_capture SET processed = true, processed_at = now(), processing_error = NULL
       WHERE id = lc.id;
      res := res || jsonb_build_object('id', lc.id, 'result', 'processed', 'contact_id', v_contact_id, 'lead_id', v_lead_id);
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.lead_capture SET processing_error = left(SQLERRM, 500) WHERE id = lc.id;
      res := res || jsonb_build_object('id', lc.id, 'result', 'error');
    END;
  END LOOP;
  RETURN res;
END
$function$

CREATE OR REPLACE FUNCTION public.crm_ingest_lead_captures(p_batch_size integer DEFAULT 100, p_only_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  MP_CO    constant uuid := '7c858982-6ccd-47ca-bd65-e0dd3eebf01c';
  COALA_CO constant uuid := '7d831e59-6e82-427b-95a0-64904aae5dd2';
  MP_SOURCES constant text[] := ARRAY['portal','vip_event_page','sticky_cta','notify_me',
    'hero_vip','newsletter_homepage','vip_hero_coupon_chip',
    'clube_newgang'];
  COALA_SOURCES constant text[] := ARRAY['coala_hero_email','coala_early_bird',
    'coala_early_bird_invite','notify_me'];
  Q_SCOPE constant text := 'quarantine#321: empresa/origem fora do âmbito da ingestão interna';
  lc record;
  v_email text; v_phone text;
  v_by_email uuid; v_by_phone uuid; v_contact_id uuid;
  v_event_id uuid; v_lead_id uuid;
  n_ok int := 0; n_contacts_new int := 0; n_leads_new int := 0;
  n_invite int := 0; n_quarantine int := 0; n_error int := 0;
  n_club int := 0; n_club_deferred int := 0; d_c int; d_l int; v_club_seen text[] := ARRAY[]::text[];
BEGIN
  WITH oos AS (
    SELECT id FROM public.lead_capture
    WHERE processed = false
      AND (p_only_ids IS NULL OR id = ANY(p_only_ids))
      AND processing_error IS DISTINCT FROM Q_SCOPE
      AND (company_id IS NULL
           OR NOT ((company_id = MP_CO AND source = ANY(MP_SOURCES))
                OR (company_id = COALA_CO AND source = ANY(COALA_SOURCES))))
    LIMIT 1000 FOR UPDATE SKIP LOCKED)
  UPDATE public.lead_capture l SET processing_error = Q_SCOPE FROM oos WHERE l.id = oos.id;
  GET DIAGNOSTICS n_quarantine = ROW_COUNT;

  FOR lc IN
    SELECT * FROM public.lead_capture
    WHERE processed = false
      AND (p_only_ids IS NULL OR id = ANY(p_only_ids))
      AND company_id IS NOT NULL
      AND ((company_id = MP_CO AND source = ANY(MP_SOURCES))
        OR (company_id = COALA_CO AND source = ANY(COALA_SOURCES)))
    ORDER BY (processing_error IS NOT NULL), created_at ASC, id ASC
    LIMIT GREATEST(p_batch_size, 1)
    FOR UPDATE SKIP LOCKED
  LOOP
    IF lc.source = 'clube_newgang' AND NOT EXISTS (SELECT 1 FROM public.portal_sites
         WHERE brand_key = 'newgang' AND active AND company_id = lc.company_id) THEN
      UPDATE public.lead_capture SET processing_error = 'quarantine#321: clube sem site Newgang activo' WHERE id = lc.id;
      n_quarantine := n_quarantine + 1; CONTINUE;
    END IF;
    IF lc.source = 'clube_newgang' AND NULLIF(btrim(coalesce(lc.email,'')),'') IS NULL THEN
      UPDATE public.lead_capture SET processing_error = 'quarantine#321: clube sem email' WHERE id = lc.id;
      n_quarantine := n_quarantine + 1; CONTINUE;
    END IF;
    IF lc.source = 'clube_newgang' THEN
      IF lower(btrim(lc.email)) = ANY(v_club_seen) THEN
        n_club_deferred := n_club_deferred + 1; CONTINUE;
      END IF;
      v_club_seen := v_club_seen || lower(btrim(lc.email));
    END IF;

    v_email := NULLIF(lower(btrim(coalesce(lc.email, ''))), '');
    v_phone := NULLIF(btrim(coalesce(lc.phone, '')), '');
    IF v_email IS NULL AND v_phone IS NULL THEN
      UPDATE public.lead_capture SET processing_error = 'quarantine#321: sem email nem telefone'
       WHERE id = lc.id;
      n_quarantine := n_quarantine + 1;
      CONTINUE;
    END IF;

    d_c := 0; d_l := 0;
    BEGIN
      IF v_email IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('crm321:e:'||lc.company_id||':'||v_email, 0));
      END IF;
      IF v_phone IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtextextended('crm321:p:'||lc.company_id||':'||v_phone, 0));
      END IF;

      v_by_email := NULL; v_by_phone := NULL;
      IF v_email IS NOT NULL THEN
        SELECT id INTO v_by_email FROM public.contacts
         WHERE company_id = lc.company_id AND lower(btrim(email)) = v_email LIMIT 1;
      END IF;
      IF v_phone IS NOT NULL THEN
        SELECT id INTO v_by_phone FROM public.contacts
         WHERE company_id = lc.company_id AND phone_e164 = v_phone LIMIT 1;
      END IF;

      IF v_by_email IS NOT NULL AND v_by_phone IS NOT NULL AND v_by_email <> v_by_phone THEN
        RAISE EXCEPTION 'quarantine#321: email e telefone pertencem a contactos diferentes';
      END IF;
      v_contact_id := coalesce(v_by_email, v_by_phone);

      IF v_contact_id IS NOT NULL THEN
        UPDATE public.contacts SET
          email = coalesce(email, CASE WHEN v_by_email IS NULL THEN v_email END),
          phone_e164 = coalesce(phone_e164, CASE WHEN v_by_phone IS NULL THEN v_phone END),
          name = coalesce(name, NULLIF(btrim(lc.name), '')),
          last_activity_at = greatest(last_activity_at, lc.created_at),
          updated_at = now()
        WHERE id = v_contact_id;
      ELSE
        INSERT INTO public.contacts (company_id, email, phone_e164, name,
          consent_email, consent_whatsapp, consent_email_at, consent_whatsapp_at,
          source, first_seen_at, last_activity_at)
        VALUES (lc.company_id, v_email, v_phone, NULLIF(btrim(lc.name), ''),
          coalesce(lc.consent_email, false), coalesce(lc.consent_whatsapp, false),
          CASE WHEN coalesce(lc.consent_email, false) THEN lc.created_at END,
          CASE WHEN coalesce(lc.consent_whatsapp, false) THEN lc.created_at END,
          lc.source, lc.created_at, lc.created_at)
        RETURNING id INTO v_contact_id;
        d_c := 1;
      END IF;

      IF lc.source <> 'coala_early_bird_invite' THEN
        v_lead_id := NULL;
        SELECT id INTO v_lead_id FROM public.leads
         WHERE company_id = lc.company_id AND meta->>'lead_capture_id' = lc.id::text LIMIT 1;
        IF v_lead_id IS NULL THEN
          v_event_id := NULL;
          IF lc.event_slug IS NOT NULL THEN
            SELECT id INTO v_event_id FROM public.events
             WHERE company_id = lc.company_id AND slug = lc.event_slug LIMIT 1;
          END IF;
          INSERT INTO public.leads (company_id, contact_id, event_id, kind, source,
            utm_source, utm_medium, utm_campaign, utm_content,
            ip_inet, user_agent, fbc, fbp, geo_country, geo_city, geo_region,
            created_at, meta, capi_status, capi_block_reason, capi_classified_at)
          VALUES (lc.company_id, v_contact_id, v_event_id,
            CASE WHEN lc.event_slug IS NOT NULL THEN 'event_interest' ELSE 'newsletter_signup' END,
            lc.source, lc.utm_source, lc.utm_medium, lc.utm_campaign, lc.utm_content,
            lc.ip_inet, lc.user_agent, lc.fbc, lc.fbp, lc.geo_country, lc.geo_city, lc.geo_region,
            lc.created_at,
            jsonb_build_object('lead_capture_id', lc.id, 'ingested_by', 'crm_ingest_lead_captures', 'issue', 321),
            'blocked_no_consent',
            'ingestão interna #321 — sem prova de consentimento marketing por interacção; não elegível CAPI',
            now())
          RETURNING id INTO v_lead_id;
          d_l := 1;
        END IF;
      END IF;

      UPDATE public.lead_capture
         SET processed = true, processed_at = now(), processing_error = NULL
       WHERE id = lc.id;
      IF lc.source = 'clube_newgang' AND NOT EXISTS (SELECT 1 FROM public.club_members cm
           JOIN public.portal_sites ps ON ps.id = cm.site_id AND ps.brand_key = 'newgang' AND ps.company_id = lc.company_id
           WHERE lower(btrim(cm.email)) = v_email) THEN
        RAISE EXCEPTION 'clube#321: membro não criado pelo trigger do Clube';
      END IF;
      n_contacts_new := n_contacts_new + d_c; n_leads_new := n_leads_new + d_l;
      IF lc.source = 'coala_early_bird_invite' THEN n_invite := n_invite + 1; END IF;
      n_ok := n_ok + 1;
      IF lc.source = 'clube_newgang' THEN n_club := n_club + 1; END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.lead_capture SET processing_error = left(SQLERRM, 500) WHERE id = lc.id;
      IF SQLERRM LIKE 'quarantine#321:%' THEN n_quarantine := n_quarantine + 1;
      ELSE n_error := n_error + 1; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('processed', n_ok, 'contacts_new', n_contacts_new,
    'leads_new', n_leads_new, 'invite_no_interaction', n_invite,
    'quarantine', n_quarantine, 'errors', n_error,
    'clube_processed', n_club, 'clube_deferred_same_email', n_club_deferred);
END
$function$

CREATE OR REPLACE FUNCTION public.data_entry_record_receipt(p_bucket text, p_path text, p_sha text, p_size integer, p_mime text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c uuid; r public.data_entry_storage_receipts;
BEGIN
 IF p_path !~ '^[0-9a-f-]{36}/' THEN RAISE EXCEPTION '#333: Caminho inválido' USING ERRCODE='22023'; END IF;
 c := split_part(p_path,'/',1)::uuid;
 INSERT INTO public.data_entry_storage_receipts(bucket,path,company_id,sha256,size_bytes,mime) VALUES(p_bucket,p_path,c,p_sha,p_size,p_mime) ON CONFLICT DO NOTHING;
 SELECT * INTO r FROM public.data_entry_storage_receipts WHERE bucket=p_bucket AND path=p_path;
 IF r.sha256<>p_sha OR r.size_bytes<>p_size OR r.mime<>p_mime THEN RAISE EXCEPTION '#333: Objeto já registado com outro conteúdo' USING ERRCODE='23505'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_email_batch(p_queue_name text, p_payloads jsonb, p_batch_size integer DEFAULT 5000, p_interval_minutes integer DEFAULT 50)
 RETURNS TABLE(enqueued integer, batches integer, last_visible_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pgmq'
AS $function$
-- Enfileira uma lista grande em lotes espaçados: o lote k fica invisível
-- k*p_interval_minutes e o queued_at do payload é o momento em que fica visível,
-- para o TTL (60 min nas transacionais) contar a partir daí e nada expirar.
DECLARE
  v_item jsonb; v_i integer := 0; v_delay integer; v_at timestamptz := now();
BEGIN
  IF jsonb_typeof(p_payloads) <> 'array' THEN
    RAISE EXCEPTION 'p_payloads tem de ser um array JSON';
  END IF;
  IF p_batch_size < 1 OR p_interval_minutes < 1 THEN
    RAISE EXCEPTION 'p_batch_size e p_interval_minutes têm de ser >= 1';
  END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_payloads) LOOP
    v_delay := (v_i / p_batch_size) * p_interval_minutes * 60;
    v_at := now() + make_interval(secs => v_delay);
    BEGIN
      PERFORM pgmq.send(p_queue_name, v_item || jsonb_build_object('queued_at', v_at), v_delay);
    EXCEPTION WHEN undefined_table THEN
      PERFORM pgmq.create(p_queue_name);
      PERFORM pgmq.send(p_queue_name, v_item || jsonb_build_object('queued_at', v_at), v_delay);
    END;
    v_i := v_i + 1;
  END LOOP;
  RETURN QUERY SELECT v_i, CASE WHEN v_i = 0 THEN 0 ELSE ((v_i - 1) / p_batch_size) + 1 END, v_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_backups()
 RETURNS TABLE(deleted_count integer, oldest_kept timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
DECLARE v_deleted INTEGER := 0; v_oldest TIMESTAMPTZ; v_company UUID;
BEGIN
  WITH old AS (
    DELETE FROM storage.objects WHERE bucket_id='database-backups' AND created_at < (now() - interval '30 days')
    RETURNING 1
  ) SELECT count(*) INTO v_deleted FROM old;
  SELECT min(created_at) INTO v_oldest FROM storage.objects WHERE bucket_id='database-backups';
  SELECT id INTO v_company FROM public.companies WHERE status='active' ORDER BY created_at LIMIT 1;
  BEGIN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, new_data, company_id)
    VALUES ('backup_retention','cleanup','cleanup','system',
            jsonb_build_object('deleted_count',v_deleted,'oldest_kept',v_oldest,'retention_days',30), v_company);
  EXCEPTION WHEN undefined_column THEN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, new_data)
    VALUES ('backup_retention','cleanup','cleanup','system',
            jsonb_build_object('deleted_count',v_deleted,'oldest_kept',v_oldest,'retention_days',30));
  END;
  RETURN QUERY SELECT v_deleted, v_oldest;
END;
$function$

CREATE OR REPLACE FUNCTION public.test_latest_backup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'storage'
AS $function$
DECLARE v_name TEXT; v_size BIGINT; v_age INTERVAL; v_status TEXT; v_result JSONB; v_company UUID;
BEGIN
  SELECT name, (metadata->>'size')::bigint, (now()-created_at)
  INTO v_name, v_size, v_age
  FROM storage.objects WHERE bucket_id='database-backups'
  ORDER BY created_at DESC LIMIT 1;

  v_status := CASE
    WHEN v_name IS NULL THEN 'fail_no_backup'
    WHEN v_age > interval '36 hours' THEN 'fail_stale'
    WHEN COALESCE(v_size,0) < 10000 THEN 'fail_too_small'
    ELSE 'ok' END;

  v_result := jsonb_build_object('status',v_status,'latest_backup',v_name,'size_bytes',v_size,
                                 'age_hours', round(extract(epoch from v_age)/3600.0,2),'tested_at',now());

  SELECT id INTO v_company FROM public.companies WHERE status='active' ORDER BY created_at LIMIT 1;
  BEGIN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, new_data, company_id)
    VALUES ('backup_test', COALESCE(v_name,'none'),'test_restore','system', v_result, v_company);
  EXCEPTION WHEN undefined_column THEN
    INSERT INTO public.system_audit_log (entity_type, entity_id, action, changed_by, new_data)
    VALUES ('backup_test', COALESCE(v_name,'none'),'test_restore','system', v_result);
  END;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_vault_secret(_name text, _value text, _description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id FROM vault.secrets WHERE name = _name LIMIT 1;
  IF v_id IS NOT NULL THEN
    PERFORM vault.update_secret(v_id, _value, NULL, _description);
  ELSE
    v_id := vault.create_secret(_value, _name, COALESCE(_description, ''));
  END IF;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_email(queue_name text, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN pgmq.send(queue_name, payload);
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN pgmq.send(queue_name, payload);
END;
$function$

CREATE OR REPLACE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.read_email_batch(queue_name text, batch_size integer, vt integer)
 RETURNS TABLE(msg_id bigint, read_ct integer, message jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY SELECT r.msg_id, r.read_ct, r.message FROM pgmq.read(queue_name, vt, batch_size) r;
EXCEPTION WHEN undefined_table THEN
  PERFORM pgmq.create(queue_name);
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public._club332_state(p_member uuid, p_site uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE result jsonb; ads jsonb; em record; wa record; cur_phone text; wa_valid boolean; wa_masked text;
BEGIN
 SELECT decision,version,decided_at INTO em FROM public.club_member_email_consents WHERE member_id=p_member AND site_id=p_site ORDER BY id DESC LIMIT 1;
 SELECT jsonb_object_agg(p.purpose,jsonb_build_object('state',CASE WHEN e.state='granted' AND NOT coalesce(e.valid_grant,false) THEN 'expired' ELSE coalesce(e.state,'unknown') END,'version',e.banner_version,'date',e.server_received_at)) INTO ads FROM unnest(ARRAY['meta_ads','tiktok_ads','google_ads']) p(purpose) LEFT JOIN LATERAL (SELECT ev.state,ev.banner_version,ev.server_received_at,f.valid_grant FROM public.club_member_marketing_consents l JOIN public.marketing_consent_events ev ON ev.id=l.event_id LEFT JOIN LATERAL public.marketing_consent_effective(ev.subject_id,clock_timestamp()) f ON f.event_id=ev.id WHERE l.member_id=p_member AND l.site_id=p_site AND l.purpose=p.purpose ORDER BY ev.revision DESC,ev.id DESC LIMIT 1) e ON true;
 SELECT decision,version,decided_at,phone_fp INTO wa FROM public.club_member_whatsapp_consents WHERE member_id=p_member AND site_id=p_site ORDER BY id DESC LIMIT 1;
 SELECT phone INTO cur_phone FROM public.club_members WHERE id=p_member AND site_id=p_site;
 wa_valid:= wa.decision='granted' AND cur_phone IS NOT NULL AND wa.phone_fp IS NOT NULL
   AND wa.phone_fp=public._club332_whatsapp_fp(cur_phone);
 wa_masked:=CASE WHEN cur_phone IS NOT NULL AND length(cur_phone)>=6
   THEN left(cur_phone,4)||'•••••'||right(cur_phone,3) END;
 result:=jsonb_build_object(
  'email',jsonb_build_object('state',coalesce(em.decision,'unknown'),'version',em.version,'date',em.decided_at),
  'ads',ads,
  'whatsapp',jsonb_build_object('state',coalesce(wa.decision,'unknown'),'version',wa.version,'date',wa.decided_at,
    'number_masked',wa_masked,'valid_for_current_number',coalesce(wa_valid,false)));
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public._club332_whatsapp_append(p_member uuid, p_site uuid, p_decision text, p_key uuid, p_origin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE old public.club_member_whatsapp_consents; co uuid; ph text; fp text;
BEGIN
 IF p_decision IS NULL OR p_decision NOT IN ('granted','revoked') OR p_key IS NULL THEN RAISE EXCEPTION 'consent_payload'; END IF;
 SELECT company_id, phone INTO co, ph FROM public.club_members WHERE id=p_member AND site_id=p_site;
 IF co IS NULL THEN RAISE EXCEPTION 'consent_scope'; END IF;
 SELECT * INTO old FROM public.club_member_whatsapp_consents WHERE member_id=p_member AND site_id=p_site AND idempotency_key=p_key;
 IF FOUND THEN IF old.decision<>p_decision OR old.origin<>p_origin THEN RAISE EXCEPTION 'idempotency_conflict'; END IF; RETURN; END IF;
 IF p_decision='granted' THEN
   IF ph IS NULL OR ph !~ '^\+[1-9][0-9]{7,14}$' THEN RAISE EXCEPTION 'whatsapp_no_phone'; END IF;
 END IF;
 fp:=public._club332_whatsapp_fp(ph);
 INSERT INTO public.club_member_whatsapp_consents(member_id,site_id,company_id,version,decision,origin,phone_fp,idempotency_key)
 VALUES(p_member,p_site,co,'whatsapp-v1',p_decision,p_origin,fp,p_key);
END $function$

CREATE OR REPLACE FUNCTION public._club332_whatsapp_fp(p_phone text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_catalog'
AS $function$
DECLARE k text;
BEGIN
 IF p_phone IS NULL THEN RETURN NULL; END IF;
 SELECT value INTO k FROM public.app_secrets WHERE name='club_whatsapp_hmac_key';
 IF k IS NULL THEN RAISE EXCEPTION 'whatsapp_fp_unavailable'; END IF;
 RETURN encode(extensions.hmac(convert_to(p_phone,'UTF8'),convert_to(k,'UTF8'),'sha256'),'hex');
END $function$

CREATE OR REPLACE FUNCTION public._club332_ads_append(p_member uuid, p_site uuid, p_decision text, p_purposes text[], p_key uuid, p_origin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE co uuid; purpose_name text; sub uuid; eid bigint; rev bigint; policy text; payload jsonb; prior jsonb; sorted text[];
BEGIN
 IF p_decision IS NULL OR p_decision NOT IN ('granted','revoked') OR p_key IS NULL OR p_purposes IS NULL OR cardinality(p_purposes) NOT BETWEEN 1 AND 3 OR EXISTS(SELECT 1 FROM unnest(p_purposes) p WHERE p IS NULL OR p NOT IN ('meta_ads','tiktok_ads','google_ads')) OR cardinality(p_purposes)<>(SELECT count(DISTINCT p) FROM unnest(p_purposes) p) THEN RAISE EXCEPTION 'consent_payload'; END IF;
 SELECT array_agg(p ORDER BY p) INTO sorted FROM unnest(p_purposes) p;
 payload:=jsonb_build_object('decision',p_decision,'purposes',sorted,'version','anuncios-v1','origin',p_origin);
 SELECT request_payload INTO prior FROM public.club_member_marketing_consents WHERE member_id=p_member AND site_id=p_site AND request_key=p_key LIMIT 1;
 IF FOUND THEN IF prior<>payload THEN RAISE EXCEPTION 'idempotency_conflict'; END IF; RETURN; END IF;
 SELECT company_id INTO co FROM public.club_members WHERE id=p_member AND site_id=p_site;
 IF co IS NULL THEN RAISE EXCEPTION 'consent_scope'; END IF;
 SELECT policy_version INTO policy FROM public.marketing_consent_policies WHERE portal='newgang' AND valid_from<=clock_timestamp() AND (valid_to IS NULL OR valid_to>clock_timestamp()) ORDER BY valid_from DESC LIMIT 1;
 IF policy IS NULL AND p_decision='granted' THEN RAISE EXCEPTION 'consent_policy_unavailable'; END IF;
 policy:=coalesce(policy,'revoked');
 FOREACH purpose_name IN ARRAY sorted LOOP
 SELECT l.subject_id INTO sub FROM public.club_member_marketing_consents l WHERE l.member_id=p_member AND l.site_id=p_site AND l.purpose=purpose_name ORDER BY l.event_id DESC LIMIT 1;
 IF sub IS NULL THEN INSERT INTO public.marketing_consent_subjects(company_id,portal,token_hash) VALUES(co,'newgang',encode(extensions.digest(extensions.gen_random_bytes(32),'sha256'),'hex')) RETURNING id INTO sub; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('mcs:'||sub::text,0));
 SELECT coalesce(max(revision),0)+1 INTO rev FROM public.marketing_consent_events WHERE subject_id=sub;
 INSERT INTO public.marketing_consent_events(subject_id,company_id,portal,state,purpose,policy_version,banner_version,client_seq,idempotency_key,origin,path,revision,expected_revision) VALUES(sub,co,'newgang',p_decision,purpose_name,policy,'anuncios-v1',rev,p_key,p_origin,'/clube/perfil',rev,rev-1) RETURNING id INTO eid;
 INSERT INTO public.club_member_marketing_consents(event_id,member_id,site_id,company_id,subject_id,purpose,request_key,request_payload) VALUES(eid,p_member,p_site,co,sub,purpose_name,p_key,payload);
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public._club332_city_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE country text; city text; canonical text;
BEGIN
 IF NEW.source IS DISTINCT FROM 'clube_newgang' OR NEW.company_id IS DISTINCT FROM '7c858982-6ccd-47ca-bd65-e0dd3eebf01c'::uuid THEN
   IF TG_OP='INSERT' THEN RETURN NEW; END IF;
   IF OLD.source IS DISTINCT FROM 'clube_newgang' OR OLD.company_id IS DISTINCT FROM '7c858982-6ccd-47ca-bd65-e0dd3eebf01c'::uuid THEN RETURN NEW; END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.company_id IS NOT DISTINCT FROM OLD.company_id AND NEW.source IS NOT DISTINCT FROM OLD.source AND NEW.raw->'city' IS NOT DISTINCT FROM OLD.raw->'city'
   AND NEW.raw->'residence_country' IS NOT DISTINCT FROM OLD.raw->'residence_country' THEN RETURN NEW; END IF;
 IF NEW.raw ? 'city' AND NEW.raw->'city'<>'null'::jsonb AND jsonb_typeof(NEW.raw->'city') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'city_invalid'; END IF;
 city:=NEW.raw->>'city'; country:=NEW.raw->>'residence_country';
 -- Only explicit Portugal is required/validated. Missing country is never invented.
 IF upper(btrim(country))='PT' THEN canonical:=public.club_city_normalize('PT',city);
 ELSE
  -- Capture is not a completed profile: never infer or require country here.
  IF city IS NULL OR btrim(city)='' THEN canonical:=NULL;
  ELSE
   IF length(city)>500 OR city ~ '[<>[:cntrl:]]' THEN RAISE EXCEPTION 'city_invalid'; END IF;
   canonical:=regexp_replace(btrim(normalize(city,NFC)),'[[:space:]]+',' ','g');
   IF length(canonical) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'city_invalid'; END IF;
   canonical:=initcap(lower(canonical COLLATE pg_catalog."pg_c_utf8"));
  END IF;
 END IF;
 IF NEW.raw ? 'city' THEN NEW.raw:=jsonb_set(NEW.raw,'{city}',coalesce(to_jsonb(canonical),'null'::jsonb)); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club332_city_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.city IS NOT DISTINCT FROM OLD.city AND NEW.residence_country IS NOT DISTINCT FROM OLD.residence_country THEN RETURN NEW; END IF;
 -- Empty/cleared demographic records remain allowed; they are never complete.
 IF NEW.birth_date IS NULL AND NEW.birth_country IS NULL AND NEW.residence_country IS NULL AND NEW.city IS NULL THEN RETURN NEW; END IF;
 NEW.city:=public.club_city_normalize(NEW.residence_country,NEW.city);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._club332_email_append(p_member uuid, p_site uuid, p_decision text, p_key uuid, p_origin text)
 RETURNS void
