CREATE OR REPLACE FUNCTION public._crm_whatsapp_contact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE latest record;
BEGIN
 -- Unrelated ingestion updates must not perform the unapproved historical backfill.
 IF TG_OP='UPDATE' AND (NEW.consent_whatsapp,NEW.consent_whatsapp_at,NEW.consent_whatsapp_source)
 IS NOT DISTINCT FROM (OLD.consent_whatsapp,OLD.consent_whatsapp_at,OLD.consent_whatsapp_source) THEN RETURN NEW; END IF;
 SELECT * INTO latest FROM public._crm_whatsapp_latest(NEW.id,NEW.company_id);
 IF FOUND THEN
 NEW.consent_whatsapp:=latest.decision='granted';
 NEW.consent_whatsapp_at:=CASE WHEN latest.decision='granted' THEN latest.decided_at END;
 NEW.consent_whatsapp_source:='club_profile_whatsapp-v1';
 ELSIF NEW.consent_whatsapp THEN
 NEW.consent_whatsapp_source:='form_legacy_sem_prova';
 ELSE NEW.consent_whatsapp_at:=NULL; NEW.consent_whatsapp_source:=NULL;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public._crm_whatsapp_project()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE contact uuid; latest record;
BEGIN
 IF TG_TABLE_NAME='club_members' THEN
  contact:=NEW.contact_id;
 ELSE
  SELECT m.contact_id INTO contact FROM public.club_members m
  WHERE m.id=NEW.member_id AND m.site_id=NEW.site_id AND m.company_id=NEW.company_id;
 END IF;
 IF contact IS NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM public.contacts WHERE id=contact AND company_id=NEW.company_id FOR UPDATE;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO latest FROM public._crm_whatsapp_latest(contact,NEW.company_id);
 IF NOT FOUND THEN RETURN NEW; END IF;
 UPDATE public.contacts SET consent_whatsapp=latest.decision='granted',
 consent_whatsapp_at=CASE WHEN latest.decision='granted' THEN latest.decided_at END,
 consent_whatsapp_source='club_profile_whatsapp-v1'
 WHERE id=contact AND company_id=NEW.company_id AND
 (consent_whatsapp,consent_whatsapp_at,consent_whatsapp_source) IS DISTINCT FROM
 (latest.decision='granted',CASE WHEN latest.decision='granted' THEN latest.decided_at END,'club_profile_whatsapp-v1'::text);
 IF latest.decision='granted' AND latest.phone ~ '^\+[1-9][0-9]{7,14}$'
 AND latest.phone_fp=public._club332_whatsapp_fp(latest.phone) THEN
  -- A phone already owned by another contact must not abort a member's consent decision.
  BEGIN
   UPDATE public.contacts SET phone_e164=latest.phone
   WHERE id=contact AND company_id=NEW.company_id AND nullif(phone_e164,'') IS NULL
   AND NOT EXISTS(SELECT 1 FROM public.contacts other WHERE other.company_id=NEW.company_id
    AND other.id<>contact AND other.phone_e164=latest.phone);
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_actor(OUT uid uuid, OUT company uuid, OUT actor_name text, OUT actor_role text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 uid := auth.uid(); company := public.current_company_id();
 IF uid IS NULL OR company IS NULL THEN RAISE EXCEPTION '#333: Sessão ou empresa ativa inválida' USING ERRCODE='42501'; END IF;
 actor_role := public._effective_permissions_for(uid, company, '{}'::text[])->>'role';
 IF actor_role IS NULL OR actor_role NOT IN ('platform_admin','admin','manager') THEN RAISE EXCEPTION '#333: Sem permissão nesta empresa' USING ERRCODE='42501'; END IF;
 SELECT nullif(btrim(full_name),'') INTO actor_name FROM public.profiles WHERE id = uid;
 IF actor_name IS NULL THEN RAISE EXCEPTION '#333: Perfil sem nome; não é possível registar a autorização' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_own_session(p_session uuid, p_lock boolean DEFAULT false)
 RETURNS data_entry_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a record; v public.data_entry_sessions;
BEGIN
 a := public.data_entry_actor();
 IF p_lock THEN SELECT * INTO v FROM public.data_entry_sessions WHERE id=p_session AND owner_id=a.uid AND company_id=a.company FOR UPDATE;
 ELSE SELECT * INTO v FROM public.data_entry_sessions WHERE id=p_session AND owner_id=a.uid AND company_id=a.company; END IF;
 IF v.id IS NULL THEN RAISE EXCEPTION '#333: Lote indisponível nesta empresa' USING ERRCODE='42501'; END IF;
 RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.standalone_attempt_guard_333()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION '#333: Candidato preservado'; END IF;
 IF (to_jsonb(NEW)-ARRAY['state','original_result','completed_at','review_reason'])<>(to_jsonb(OLD)-ARRAY['state','original_result','completed_at','review_reason']) THEN RAISE EXCEPTION '#333: Identidade imutável'; END IF;
 IF NOT ((OLD.state='prepare' AND NEW.state='authorized') OR (OLD.state='authorized' AND NEW.state='inprogress') OR (OLD.state='inprogress' AND NEW.state IN ('completed','review'))) OR (NEW.review_reason IS DISTINCT FROM OLD.review_reason AND NOT (OLD.state='inprogress' AND NEW.state='review')) THEN RAISE EXCEPTION '#333: Transição recusada'; END IF;
 IF NEW.state<>'completed' AND (NEW.original_result IS NOT NULL OR NEW.completed_at IS NOT NULL) THEN RAISE EXCEPTION '#333: Resultado prematuro'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.standalone_attempt_internal_333(p_action text, p_id uuid, p_operation text, p_envelope jsonb, p_hash text, p_company uuid, p_service boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c uuid; u uuid; principal_value text; role_value text; v public.standalone_attempts_333;
 h text; payload jsonb; before_row jsonb; current_row jsonb; expected_row jsonb; result_row jsonb;
 inv public.standalone_invoices; allowed text[]; key text; new_id uuid; ext text; prior public.standalone_attempts_333; reason text;
BEGIN
 IF p_service THEN
  c:=p_company; principal_value:='ingest_service';
  IF p_operation IS DISTINCT FROM 'ingest_create' THEN RAISE EXCEPTION '#333: Operação recusada' USING ERRCODE='42501'; END IF;
 ELSE
  u:=auth.uid(); c:=public.current_company_id(); principal_value:=u::text;
  IF u IS NULL OR c IS NULL THEN RAISE EXCEPTION '#333: Sessão inválida' USING ERRCODE='42501'; END IF;
  role_value:=public._effective_permissions_for(u,c,'{}'::text[])->>'role';
  IF p_operation NOT IN ('scanner_create','accountant_edit','assistant_create') OR p_operation IS NULL THEN RAISE EXCEPTION '#333: Operação recusada' USING ERRCODE='42501'; END IF;
  IF p_operation='assistant_create' AND coalesce(role_value,'') NOT IN ('admin','platform_admin','manager') THEN RAISE EXCEPTION '#333: Sem permissão' USING ERRCODE='42501'; END IF;
  IF p_operation='scanner_create' AND coalesce(role_value,'') NOT IN ('admin','platform_admin','manager','editor') THEN RAISE EXCEPTION '#333: Sem permissão' USING ERRCODE='42501'; END IF;
 END IF;
 IF c IS NULL OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=c AND status='active') THEN RAISE EXCEPTION '#333: Empresa indisponível' USING ERRCODE='42501'; END IF;
 IF p_action NOT IN ('prepare','authorize','begin','commit','check','confirm_new_intent') OR p_action IS NULL THEN RAISE EXCEPTION '#333: Ação recusada' USING ERRCODE='22023'; END IF;
 -- Server gate checked before any persistent reservation/claim; check stays read-only recovery.
 IF p_action<>'check' AND NOT public.standalone_attempt_gate_333(p_operation) THEN RAISE EXCEPTION '#333: Operação ainda não ativada' USING ERRCODE='42501'; END IF;
 IF p_action='confirm_new_intent' THEN
  -- C: owner's typed confirmation of an additional intent over a COMPLETED prior attempt only.
  SELECT * INTO prior FROM public.standalone_attempts_333 WHERE id=p_id FOR UPDATE;
  IF prior.id IS NULL OR prior.company_id<>c OR prior.principal<>principal_value OR prior.operation<>p_operation OR p_operation='accountant_edit' THEN RAISE EXCEPTION '#333: Tentativa indisponível' USING ERRCODE='42501'; END IF;
  IF p_hash IS DISTINCT FROM prior.envelope_hash THEN RAISE EXCEPTION '#333: Hash divergente' USING ERRCODE='40001'; END IF;
  IF prior.state<>'completed' THEN RAISE EXCEPTION '#333: Resultado anterior por conferir' USING ERRCODE='40001'; END IF;
  IF prior.intent_seq<>(SELECT max(intent_seq) FROM public.standalone_attempts_333 WHERE company_id=c AND principal=principal_value AND operation=p_operation AND envelope_hash=prior.envelope_hash) THEN RAISE EXCEPTION '#333: Existe intenção mais recente' USING ERRCODE='40001'; END IF;
  IF public.standalone_strong_key_333(prior.envelope->'payload'->>'supplier_nif') IS NOT NULL AND public.standalone_strong_key_333(prior.envelope->'payload'->>'invoice_number') IS NOT NULL THEN RAISE EXCEPTION '#333: Duplicado forte' USING ERRCODE='23505'; END IF;
  new_id:=gen_random_uuid(); ext:=substring(prior.path from '\.[a-z]+$');
  INSERT INTO public.standalone_attempts_333(id,company_id,principal,operation,envelope,envelope_hash,destination_id,path,intent_seq,prior_attempt_id,intent_confirmed_at,intent_confirmation_hash)
  VALUES(new_id,c,principal_value,p_operation,prior.envelope,prior.envelope_hash,gen_random_uuid(),c::text||'/attempt333/'||new_id::text||'/'||(prior.envelope->'document'->>'sha256')||ext,prior.intent_seq+1,prior.id,now(),
   encode(extensions.digest(convert_to(prior.id::text||':'||prior.envelope_hash||':'||(prior.intent_seq+1)::text||':'||principal_value,'UTF8'),'sha256'),'hex')) RETURNING * INTO v;
 END IF;
 IF p_action='prepare' THEN
  IF jsonb_typeof(p_envelope) IS DISTINCT FROM 'object' OR
    (p_envelope - ARRAY['payload','document','effects','target','before','preview_id','snapshot_hash']) <> '{}'::jsonb OR
    jsonb_typeof(p_envelope->'payload') IS DISTINCT FROM 'object' OR
    jsonb_typeof(p_envelope->'effects') IS DISTINCT FROM 'array' OR
    jsonb_typeof(p_envelope->'document') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION '#333: Envelope inválido' USING ERRCODE='22023'; END IF;
  payload:=p_envelope->'payload';
  IF p_operation<>'assistant_create' AND (p_envelope ? 'preview_id' OR p_envelope ? 'snapshot_hash') THEN RAISE EXCEPTION '#333: Prévia recusada' USING ERRCODE='22023'; END IF;
  IF p_envelope->'effects' <> jsonb_build_array(p_operation) AND p_operation<>'assistant_create' THEN RAISE EXCEPTION '#333: Efeitos divergentes' USING ERRCODE='22023'; END IF;
  allowed:=ARRAY['supplier_name','supplier_nif','invoice_number','invoice_date','currency','original_amount','fx_rate','fx_rate_source','total_amount','iva_amount','paid_by_partner_id','notes','file_name','created_by'];
  FOR key IN SELECT jsonb_object_keys(payload) LOOP
   IF NOT key=ANY(allowed) THEN RAISE EXCEPTION '#333: Campo recusado' USING ERRCODE='22023'; END IF;
   IF payload->key <> 'null'::jsonb AND jsonb_typeof(payload->key) <> (CASE WHEN key IN ('original_amount','fx_rate','total_amount','iva_amount') THEN 'number' ELSE 'string' END) THEN RAISE EXCEPTION '#333: Tipo inválido' USING ERRCODE='22023'; END IF;
  END LOOP;
  IF payload->>'currency' IS NULL OR payload->>'currency' NOT IN ('EUR','USD','BRL','GBP') OR (p_operation='assistant_create' AND payload->>'currency'<>'EUR') THEN RAISE EXCEPTION '#333: Moeda inválida' USING ERRCODE='22023'; END IF;
  IF (payload->>'currency'<>'EUR' AND (payload->>'original_amount' IS NULL OR payload->>'fx_rate' IS NULL)) THEN RAISE EXCEPTION '#333: Câmbio não resolvido' USING ERRCODE='22023'; END IF;
  FOR key IN SELECT unnest(ARRAY['original_amount','fx_rate','total_amount','iva_amount']) LOOP
   IF payload->>key IS NOT NULL AND ((payload->>key)::numeric<0 OR (key IN ('total_amount','iva_amount','original_amount') AND round((payload->>key)::numeric,2)<>(payload->>key)::numeric) OR (key='fx_rate' AND (payload->>key)::numeric<=0)) THEN RAISE EXCEPTION '#333: Valor inválido' USING ERRCODE='22023'; END IF;
  END LOOP;
  -- Existing total EUR requirement, nullable legacy metadata, and ingest ±0.01 FX contract.
  IF payload->>'total_amount' IS NULL THEN RAISE EXCEPTION '#333: Total EUR obrigatório' USING ERRCODE='22023'; END IF;
  -- A: VAT above total is persisted only as technical review; never authorized nor written financially.
  IF payload->>'iva_amount' IS NOT NULL AND (payload->>'iva_amount')::numeric>(payload->>'total_amount')::numeric THEN reason:='iva_exceeds_total'; END IF;
  IF p_operation='ingest_create' AND payload->>'currency'<>'EUR' AND abs(round((payload->>'original_amount')::numeric*(payload->>'fx_rate')::numeric,2)-(payload->>'total_amount')::numeric)>0.01 THEN RAISE EXCEPTION '#333: Contravalor divergente' USING ERRCODE='22023'; END IF;
  -- Scanner/editor totals remain editable; no new equality rule is imposed on those contracts.
  IF length(coalesce(payload->>'supplier_name',''))>255 OR length(coalesce(payload->>'supplier_nif',''))>32 OR length(coalesce(payload->>'invoice_number',''))>100 OR length(coalesce(payload->>'fx_rate_source',''))>100 THEN RAISE EXCEPTION '#333: Texto demasiado longo' USING ERRCODE='22023'; END IF;
  IF payload->>'paid_by_partner_id' IS NOT NULL AND (payload->>'paid_by_partner_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR NOT EXISTS(SELECT 1 FROM public.profiles pr JOIN public.user_roles ur ON ur.user_id=pr.id WHERE pr.id=(payload->>'paid_by_partner_id')::uuid AND ur.company_id=c)) THEN RAISE EXCEPTION '#333: Pagador fora da empresa' USING ERRCODE='42501'; END IF;
  IF payload->>'created_by' IS NOT NULL AND (payload->>'created_by' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=(payload->>'created_by')::uuid AND company_id=c)) THEN RAISE EXCEPTION '#333: Autor fora da empresa' USING ERRCODE='42501'; END IF;
  IF length(coalesce(payload->>'notes',''))>2000 OR length(coalesce(payload->>'file_name','')) NOT BETWEEN 1 AND 255 THEN RAISE EXCEPTION '#333: Texto inválido' USING ERRCODE='22023'; END IF;
  IF payload->>'invoice_date' IS NOT NULL AND (payload->>'invoice_date' !~ '^\d{4}-\d{2}-\d{2}$' OR to_char((payload->>'invoice_date')::date,'YYYY-MM-DD')<>payload->>'invoice_date') THEN RAISE EXCEPTION '#333: Data inválida' USING ERRCODE='22023'; END IF;
  IF NOT p_service AND p_operation<>'accountant_edit' AND payload->>'created_by' IS DISTINCT FROM u::text THEN RAISE EXCEPTION '#333: Autor inválido' USING ERRCODE='42501'; END IF;
  IF ((p_envelope->'document') - ARRAY['sha256','size_bytes','mime'])<>'{}'::jsonb OR jsonb_typeof(p_envelope->'document'->'sha256') IS DISTINCT FROM 'string' OR
    coalesce(p_envelope->'document'->>'sha256','') !~ '^[a-f0-9]{64}$' OR
    jsonb_typeof(p_envelope->'document'->'size_bytes') IS DISTINCT FROM 'number' OR
    (p_envelope->'document'->>'size_bytes')::numeric NOT BETWEEN 1 AND 20971520 OR
    (p_envelope->'document'->>'size_bytes')::numeric<>trunc((p_envelope->'document'->>'size_bytes')::numeric) OR
    coalesce(p_envelope->'document'->>'mime','') NOT IN ('application/pdf','image/png','image/jpeg') THEN RAISE EXCEPTION '#333: Documento inválido' USING ERRCODE='22023'; END IF;
  IF p_operation='accountant_edit' THEN
   SELECT * INTO inv FROM public.standalone_invoices WHERE id=(p_envelope->>'target')::uuid AND company_id=c;
   IF inv.id IS NULL OR (coalesce(role_value,'') NOT IN ('admin','platform_admin','accountant') AND inv.created_by IS DISTINCT FROM u) THEN RAISE EXCEPTION '#333: Edição recusada' USING ERRCODE='42501'; END IF;
   IF p_envelope->'before' IS DISTINCT FROM to_jsonb(inv) OR payload->>'created_by' IS DISTINCT FROM inv.created_by::text OR payload->>'file_name' IS DISTINCT FROM inv.file_name THEN RAISE EXCEPTION '#333: Versão anterior alterada' USING ERRCODE='40001'; END IF;
  ELSE
   IF p_envelope ? 'before' OR p_envelope ? 'target' THEN RAISE EXCEPTION '#333: Alvo inválido' USING ERRCODE='22023'; END IF;
  END IF;
  h:=encode(extensions.digest(convert_to(p_envelope::text,'UTF8'),'sha256'),'hex');
  -- Serialization across NEW IDs with identical envelopes, not document-only identity.
  PERFORM pg_advisory_xact_lock(hashtextextended(c::text||principal_value||p_operation||h,3331));
  IF p_id IS NOT NULL THEN
   SELECT * INTO v FROM public.standalone_attempts_333 WHERE id=p_id FOR UPDATE;
   IF v.id IS NOT NULL AND (v.company_id<>c OR v.principal<>principal_value OR v.operation<>p_operation OR v.envelope_hash<>h OR v.envelope<>p_envelope) THEN RAISE EXCEPTION '#333: Tentativa divergente' USING ERRCODE='42501'; END IF;
  END IF;
  IF v.id IS NULL THEN SELECT * INTO v FROM public.standalone_attempts_333 WHERE company_id=c AND principal=principal_value AND operation=p_operation AND envelope_hash=h ORDER BY intent_seq DESC LIMIT 1 FOR UPDATE; END IF;
  IF v.id IS NULL THEN
   new_id:=coalesce(p_id,gen_random_uuid());
   ext:=CASE p_envelope->'document'->>'mime' WHEN 'application/pdf' THEN '.pdf' WHEN 'image/png' THEN '.png' ELSE '.jpg' END;
   INSERT INTO public.standalone_attempts_333(id,company_id,principal,operation,envelope,envelope_hash,state,review_reason,destination_id,path)
   VALUES(new_id,c,principal_value,p_operation,p_envelope,h,CASE WHEN reason IS NULL THEN 'prepare' ELSE 'review' END,reason,CASE WHEN p_operation='accountant_edit' THEN inv.id WHEN p_operation='assistant_create' THEN (SELECT destination_id FROM data_entry_previews WHERE id=(p_envelope->>'preview_id')::uuid) ELSE gen_random_uuid() END,
    CASE WHEN p_operation='accountant_edit' THEN inv.storage_path WHEN p_operation='assistant_create' THEN c::text||'/assistant333/'||(SELECT document_id::text FROM data_entry_previews WHERE id=(p_envelope->>'preview_id')::uuid)||'/'||(p_envelope->'document'->>'sha256')||ext ELSE c::text||'/attempt333/'||new_id::text||'/'||(p_envelope->'document'->>'sha256')||ext END) RETURNING * INTO v;
  END IF;
 ELSIF p_action<>'confirm_new_intent' THEN
  SELECT * INTO v FROM public.standalone_attempts_333 WHERE id=p_id FOR UPDATE;
  IF v.id IS NULL OR v.company_id<>c OR v.principal<>principal_value OR v.operation<>p_operation THEN RAISE EXCEPTION '#333: Tentativa indisponível' USING ERRCODE='42501'; END IF;
  IF p_hash IS DISTINCT FROM v.envelope_hash THEN RAISE EXCEPTION '#333: Hash divergente' USING ERRCODE=CASE WHEN p_action='check' THEN '42501' ELSE '40001' END; END IF;
  payload:=v.envelope->'payload';
  IF p_operation='accountant_edit' THEN
   SELECT * INTO inv FROM public.standalone_invoices WHERE id=v.destination_id AND company_id=c FOR UPDATE;
   IF inv.id IS NULL OR (coalesce(role_value,'') NOT IN ('admin','platform_admin','accountant') AND inv.created_by IS DISTINCT FROM u) THEN RAISE EXCEPTION '#333: Edição recusada' USING ERRCODE='42501'; END IF;
  END IF;
  IF payload->>'paid_by_partner_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=(payload->>'paid_by_partner_id')::uuid AND company_id=c) THEN RAISE EXCEPTION '#333: Pagador fora da empresa' USING ERRCODE='42501'; END IF;
  IF p_action='authorize' AND v.state='prepare' THEN UPDATE public.standalone_attempts_333 SET state='authorized' WHERE id=v.id RETURNING * INTO v; END IF;
  IF p_action='begin' AND v.state='authorized' THEN UPDATE public.standalone_attempts_333 SET state='inprogress' WHERE id=v.id RETURNING * INTO v; END IF;
  IF p_action='commit' AND v.state NOT IN ('completed','review') THEN
   -- Gate re-read after row lock: closing between check and commit authorizes no effect.
   IF NOT public.standalone_attempt_gate_333(p_operation) THEN RAISE EXCEPTION '#333: Operação ainda não ativada' USING ERRCODE='42501'; END IF;
   IF v.state<>'inprogress' THEN RAISE EXCEPTION '#333: Tentativa não autorizada' USING ERRCODE='42501'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.data_entry_storage_receipts WHERE bucket='standalone-invoices' AND path=v.path AND company_id=c AND sha256=v.envelope->'document'->>'sha256' AND size_bytes=(v.envelope->'document'->>'size_bytes')::integer AND mime=v.envelope->'document'->>'mime') THEN RAISE EXCEPTION '#333: Readback servidor pendente' USING ERRCODE='40001'; END IF;
   IF p_operation='accountant_edit' AND to_jsonb(inv) IS DISTINCT FROM v.envelope->'before' THEN
    UPDATE public.standalone_attempts_333 SET state='review',review_reason='before_changed' WHERE id=v.id RETURNING * INTO v;
   ELSIF p_operation<>'accountant_edit' AND public.standalone_strong_key_333(payload->>'supplier_nif') IS NOT NULL AND public.standalone_strong_key_333(payload->>'invoice_number') IS NOT NULL AND EXISTS(SELECT 1 FROM public.standalone_invoices x WHERE x.company_id=c AND x.id<>v.destination_id AND public.standalone_strong_key_333(x.supplier_nif)=public.standalone_strong_key_333(payload->>'supplier_nif') AND public.standalone_strong_key_333(x.invoice_number)=public.standalone_strong_key_333(payload->>'invoice_number')) THEN
    UPDATE public.standalone_attempts_333 SET state='review',review_reason='strong_duplicate' WHERE id=v.id RETURNING * INTO v;
   ELSE
    IF p_operation<>'accountant_edit' AND EXISTS(SELECT 1 FROM public.standalone_invoices WHERE id=v.destination_id) THEN RAISE EXCEPTION '#333: Destino ocupado sem auditoria' USING ERRCODE='40001'; END IF;
    -- Full row conversion validates UUID/date fields; only whitelisted fields are mutable.
    inv:=jsonb_populate_record(NULL::public.standalone_invoices,payload);
    IF p_operation='assistant_create' THEN
     -- Existing strict snapshot/role/settings/ERP validation + financial mutation preserved.
     PERFORM public.data_entry_commit((v.envelope->>'preview_id')::uuid,v.envelope->>'snapshot_hash');
     SELECT to_jsonb(i.*) INTO result_row FROM public.standalone_invoices i WHERE i.id=v.destination_id AND i.company_id=c;
    ELSIF p_operation='accountant_edit' THEN
     UPDATE public.standalone_invoices SET supplier_name=inv.supplier_name,supplier_nif=inv.supplier_nif,invoice_number=inv.invoice_number,invoice_date=inv.invoice_date,
      currency=inv.currency,original_amount=inv.original_amount,fx_rate=inv.fx_rate,fx_rate_source=inv.fx_rate_source,total_amount=inv.total_amount,iva_amount=inv.iva_amount,
      paid_by_partner_id=inv.paid_by_partner_id,notes=inv.notes WHERE id=v.destination_id AND company_id=c RETURNING to_jsonb(standalone_invoices.*) INTO result_row;
    ELSE
     INSERT INTO public.standalone_invoices(id,company_id,storage_path,file_name,supplier_name,supplier_nif,invoice_number,invoice_date,currency,original_amount,fx_rate,fx_rate_source,total_amount,iva_amount,paid_by_partner_id,notes,created_by,status)
     VALUES(v.destination_id,c,v.path,inv.file_name,inv.supplier_name,inv.supplier_nif,inv.invoice_number,inv.invoice_date,inv.currency,inv.original_amount,inv.fx_rate,inv.fx_rate_source,inv.total_amount,inv.iva_amount,inv.paid_by_partner_id,inv.notes,inv.created_by,'new') RETURNING to_jsonb(standalone_invoices.*) INTO result_row;
    END IF;
    INSERT INTO public.standalone_attempt_audit_333(attempt_id,company_id,principal,envelope_hash,result) VALUES(v.id,c,principal_value,v.envelope_hash,result_row);
    UPDATE public.standalone_attempts_333 SET state='completed',original_result=result_row,completed_at=now() WHERE id=v.id RETURNING * INTO v;
   END IF;
  END IF;
 END IF;
 SELECT to_jsonb(i.*) INTO current_row FROM public.standalone_invoices i WHERE id=v.destination_id AND company_id=c;
 RETURN jsonb_build_object('id',v.id,'hash',v.envelope_hash,'state',v.state,'review_reason',v.review_reason,'intent_seq',v.intent_seq,'prior_attempt_id',v.prior_attempt_id,'path',v.path,'destination_id',v.destination_id,
  'result',v.original_result,'current',current_row,'document',v.envelope->'document',
  'record_ok',coalesce(v.state='completed' AND (current_row-ARRAY['status','processed_at','processed_by','updated_at'])=(v.original_result-ARRAY['status','processed_at','processed_by','updated_at']) AND
   EXISTS(SELECT 1 FROM public.standalone_attempt_audit_333 WHERE attempt_id=v.id AND envelope_hash=v.envelope_hash AND result=v.original_result),false));
END $function$

CREATE OR REPLACE FUNCTION crm.cleanup_expired_oauth_states()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE
  v_deleted INT;
BEGIN
  DELETE FROM crm.oauth_states WHERE expires_at < now();
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$

CREATE OR REPLACE FUNCTION crm.consume_oauth_state(p_state_id uuid)
 RETURNS TABLE(company_id uuid, user_id uuid, platform text, valid boolean, artist_id uuid, return_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE
  v_state crm.oauth_states%ROWTYPE;
BEGIN
  SELECT * INTO v_state FROM crm.oauth_states WHERE id = p_state_id AND expires_at > now();
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, NULL::UUID, NULL::TEXT, FALSE, NULL::UUID, NULL::TEXT;
    RETURN;
  END IF;
  DELETE FROM crm.oauth_states WHERE id = p_state_id;
  RETURN QUERY SELECT v_state.company_id, v_state.user_id, v_state.platform, TRUE,
                      v_state.artist_id, v_state.return_url;
END;
$function$

CREATE OR REPLACE FUNCTION crm.select_artist_meta_ad_account(p_pending_id uuid, p_ad_account_id text, p_name text, p_currency text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE p record; v_id uuid; BEGIN
  SELECT * INTO p FROM crm.ad_platform_connections WHERE id = p_pending_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ligação não encontrada'; END IF;
  SELECT id INTO v_id FROM crm.ad_platform_connections
   WHERE company_id = p.company_id AND artist_id IS NOT DISTINCT FROM p.artist_id AND platform = p.platform
     AND connection_scope = p.connection_scope AND selected_ad_account_id = p_ad_account_id AND id <> p_pending_id
   LIMIT 1;
  IF v_id IS NULL THEN
    UPDATE crm.ad_platform_connections SET selected_ad_account_id = p_ad_account_id,
      selected_ad_account_name = p_name, selected_ad_account_currency = p_currency,
      status = 'active', last_error = NULL, disconnected_at = NULL WHERE id = p_pending_id;
    RETURN p_pending_id;
  END IF;
  IF p.selected_ad_account_id IS NOT NULL THEN RAISE EXCEPTION 'a ligação de origem já tem conta'; END IF;
  UPDATE crm.ad_platform_connections c SET
    access_token_encrypted = p.access_token_encrypted, token_type = p.token_type, expires_at = p.expires_at,
    available_ad_accounts = coalesce(p.available_ad_accounts, c.available_ad_accounts),
    selected_ad_account_name = coalesce(p_name, c.selected_ad_account_name),
    selected_ad_account_currency = coalesce(p_currency, c.selected_ad_account_currency),
    status = 'active', connected_by = coalesce(p.connected_by, c.connected_by),
    last_validated_at = now(), last_error = NULL, consecutive_failures = 0, disconnected_at = NULL
  WHERE c.id = v_id;
  DELETE FROM crm.ad_platform_connections WHERE id = p_pending_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION crm.write_audit_log(p_company_id uuid, p_user_id uuid, p_action text, p_entity_type text, p_entity_id uuid, p_payload_before jsonb DEFAULT NULL::jsonb, p_payload_after jsonb DEFAULT NULL::jsonb, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'crm', 'public'
AS $function$
DECLARE
  v_id BIGINT;
BEGIN
  INSERT INTO crm.ad_manager_audit_log (
    company_id, user_id, action, entity_type, entity_id,
    payload_before, payload_after, ip_address, user_agent
  ) VALUES (
    p_company_id, p_user_id, p_action, p_entity_type, p_entity_id,
    p_payload_before, p_payload_after, p_ip_address, p_user_agent
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.data_entry_analysis_transition_333(p_operation text, p_claim uuid DEFAULT NULL::uuid, p_revision bigint DEFAULT NULL::bigint, p_outcome text DEFAULT NULL::text, p_status integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.data_entry_analysis_control_333; old_claim uuid;
BEGIN
 IF p_operation IS NULL OR p_operation NOT IN ('read','claim','post','finish','pause') OR (p_status IS NOT NULL AND p_status NOT BETWEEN 100 AND 599) THEN RAISE EXCEPTION 'analysis_control_payload' USING ERRCODE='22023'; END IF;
 SELECT * INTO c FROM public.data_entry_analysis_control_333 WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'analysis_control_missing' USING ERRCODE='42501'; END IF;
 IF p_operation='read' THEN
   IF p_claim IS NOT NULL OR p_revision IS NOT NULL OR p_outcome IS NOT NULL OR p_status IS NOT NULL THEN RAISE EXCEPTION 'analysis_control_payload' USING ERRCODE='22023'; END IF;
 ELSE
   IF p_revision IS NULL OR c.revision<>p_revision THEN RAISE EXCEPTION 'analysis_control_revision' USING ERRCODE='40001'; END IF;
   old_claim:=c.active_claim;
   IF p_operation='claim' THEN
     IF p_claim IS NULL OR p_outcome IS NOT NULL OR p_status IS NOT NULL OR c.state<>'ready' OR NOT c.enabled OR NOT c.reviewed OR c.active_claim IS NOT NULL THEN RAISE EXCEPTION 'analysis_control_closed_or_busy' USING ERRCODE='42501'; END IF;
     c.active_claim:=p_claim; c.stage:='claimed'; c.reason_code:='none'; c.upstream_status:=NULL;
   ELSE
     IF p_claim IS DISTINCT FROM c.active_claim OR (p_operation<>'pause' AND p_claim IS NULL) THEN RAISE EXCEPTION 'analysis_control_claim' USING ERRCODE='42501'; END IF;
     IF p_operation='post' THEN
       IF c.state<>'ready' OR NOT c.enabled OR NOT c.reviewed OR c.stage<>'claimed' OR p_outcome IS NOT NULL OR p_status IS NOT NULL THEN RAISE EXCEPTION 'analysis_control_closed_or_stage' USING ERRCODE='42501'; END IF;
       c.stage:='post_started';
     ELSE
       IF p_outcome IS NULL OR p_outcome NOT IN ('success','request_refused','invalid_response','before_post_failure','cancelled_before_post','cancelled_after_post','transport_uncertain','credit_denied','provider_denied','provider_unavailable','http_failure') THEN RAISE EXCEPTION 'analysis_control_outcome' USING ERRCODE='22023'; END IF;
       IF (p_outcome='credit_denied' AND p_status IS DISTINCT FROM 402) OR (p_outcome='provider_denied' AND p_status IS DISTINCT FROM 403) OR (p_outcome='provider_unavailable' AND p_status IS DISTINCT FROM 404) OR (p_outcome IN ('success','request_refused','invalid_response') AND (p_status IS NULL OR p_status NOT BETWEEN 200 AND 299)) OR (p_outcome IN ('before_post_failure','cancelled_before_post') AND (c.stage<>'claimed' OR p_status IS NOT NULL)) OR (p_outcome IN ('cancelled_after_post','transport_uncertain','http_failure') AND c.stage<>'post_started') OR (p_outcome='http_failure' AND (p_status IS NULL OR p_status<400 OR p_status IN (402,403,404))) THEN RAISE EXCEPTION 'analysis_control_outcome_stage' USING ERRCODE='22023'; END IF;
       IF p_operation='pause' AND p_outcome NOT IN ('credit_denied','provider_denied','provider_unavailable','transport_uncertain') THEN RAISE EXCEPTION 'analysis_control_pause' USING ERRCODE='22023'; END IF;
       IF p_operation='finish' AND p_outcome NOT IN ('before_post_failure','cancelled_before_post') AND c.stage<>'post_started' THEN RAISE EXCEPTION 'analysis_control_post_required' USING ERRCODE='22023'; END IF;
       c.reason_code:=p_outcome; c.upstream_status:=p_status;
       IF p_outcome='credit_denied' THEN c.state:='paused_credit';
       ELSIF p_outcome='provider_denied' THEN c.state:='denied_provider';
       ELSIF p_outcome IN ('provider_unavailable','transport_uncertain','cancelled_after_post') THEN c.state:='unavailable'; END IF;
       IF c.state<>'ready' THEN c.enabled:=false; END IF;
       IF p_operation='pause' THEN NULL; -- preserve in-flight claim; old completion is fenced by revision
       ELSIF p_outcome IN ('transport_uncertain','cancelled_after_post') THEN c.stage:='uncertain';
       ELSE c.active_claim:=NULL; c.stage:='idle'; END IF;
     END IF;
   END IF;
   c.revision:=c.revision+1; c.changed_at:=clock_timestamp();
   UPDATE public.data_entry_analysis_control_333 SET revision=c.revision,state=c.state,enabled=c.enabled,reviewed=c.reviewed,active_claim=c.active_claim,stage=c.stage,reason_code=c.reason_code,upstream_status=c.upstream_status,changed_at=c.changed_at WHERE singleton;
   INSERT INTO public.data_entry_analysis_audit_333(revision,claim,stage,reason_code,upstream_status) VALUES(c.revision,coalesce(c.active_claim,old_claim),c.stage,c.reason_code,c.upstream_status);
 END IF;
 RETURN jsonb_build_object('revision',c.revision::text,'state',c.state,'enabled',c.enabled,'reviewed',c.reviewed,'claim',c.active_claim,'stage',c.stage,'reason',c.reason_code,'status',c.upstream_status);
END $function$

CREATE OR REPLACE FUNCTION public.song_link_arrivals_hour_delta(p_event song_link_events, p_delta integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_hour timestamptz; v_canal text; v_country text; v_os text; v_count integer;
BEGIN
 v_hour:=date_trunc('hour',p_event.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
 SELECT public.song_link_event_canal(l.canal,p_event.utm_source,p_event.utm_medium,p_event.utm_campaign)
 INTO v_canal FROM (SELECT 1) x LEFT JOIN public.song_links l ON l.id=p_event.link_id;
 v_country:=coalesce(p_event.country,'?');
 v_os:=CASE lower(coalesce(p_event.os,'')) WHEN 'android' THEN 'android' WHEN 'ios' THEN 'ios' ELSE 'outro' END;
 IF p_delta=1 THEN
  INSERT INTO public.song_link_arrivals_hourly(company_id,artist_id,hour_utc,canal,country,os,n)
  VALUES(p_event.company_id,p_event.artist_id,v_hour,v_canal,v_country,v_os,1)
  ON CONFLICT(artist_id,hour_utc,canal,country,os) DO UPDATE SET company_id=excluded.company_id,n=song_link_arrivals_hourly.n+1,updated_at=clock_timestamp();
 ELSE
  UPDATE public.song_link_arrivals_hourly SET n=n-1,updated_at=clock_timestamp()
  WHERE artist_id=p_event.artist_id AND hour_utc=v_hour AND canal=v_canal AND country=v_country AND os=v_os AND n>0;
  GET DIAGNOSTICS v_count=ROW_COUNT;
  IF v_count<>1 THEN RAISE EXCEPTION 'arrivals_hourly: missing old dimension' USING ERRCODE='P0002'; END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_arrivals_hourly_rebuild(p_artist uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_hour timestamptz; v_ids uuid[]; v_diff bigint; v_total bigint:=0; v_hours integer:=0;
BEGIN
 IF current_user<>'postgres' AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'service only' USING ERRCODE='42501'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '24 hours'
 OR p_from<>date_trunc('hour',p_from AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
 OR p_to<>date_trunc('hour',p_to AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN RAISE EXCEPTION 'bounded whole-hour range required'; END IF;
 FOR v_hour IN SELECT generate_series(p_from,p_to-interval '1 hour',interval '1 hour') LOOP
  PERFORM pg_advisory_xact_lock(public.song_link_arrivals_hour_key(p_artist,v_hour));
  -- Capture exact pending IDs BEFORE the source snapshot. Never acknowledge newer commits.
  SELECT array_agg(id) INTO v_ids FROM public.song_link_arrivals_hourly_log
   WHERE artist_id=p_artist AND hour_utc=v_hour AND kind='pending' AND repaired_at IS NULL;
  WITH src AS MATERIALIZED (
   SELECT e.company_id,e.artist_id,public.song_link_event_canal(l.canal,e.utm_source,e.utm_medium,e.utm_campaign) canal,
    coalesce(e.country,'?') country,CASE lower(coalesce(e.os,'')) WHEN 'android' THEN 'android' WHEN 'ios' THEN 'ios' ELSE 'outro' END os,count(*)::bigint n
   FROM public.song_link_events e LEFT JOIN public.song_links l ON l.id=e.link_id
   WHERE e.artist_id=p_artist AND e.event='arrival' AND e.created_at>=v_hour AND e.created_at<v_hour+interval '1 hour'
   GROUP BY 1,2,3,4,5
  ), old AS MATERIALIZED(SELECT * FROM public.song_link_arrivals_hourly WHERE artist_id=p_artist AND hour_utc=v_hour),
  diff AS(SELECT count(*) n FROM src s FULL JOIN old o USING(artist_id,canal,country,os)
    WHERE coalesce(s.n,0)<>coalesce(o.n,0) OR (s.n IS NOT NULL AND o.n IS NOT NULL AND s.company_id IS DISTINCT FROM o.company_id)),
  removed AS(DELETE FROM public.song_link_arrivals_hourly o WHERE o.artist_id=p_artist AND o.hour_utc=v_hour
    AND NOT EXISTS(SELECT 1 FROM src s WHERE s.canal=o.canal AND s.country=o.country AND s.os=o.os) RETURNING 1),
  written AS(INSERT INTO public.song_link_arrivals_hourly(company_id,artist_id,hour_utc,canal,country,os,n)
    SELECT company_id,artist_id,v_hour,canal,country,os,n FROM src
    ON CONFLICT(artist_id,hour_utc,canal,country,os) DO UPDATE SET company_id=excluded.company_id,n=excluded.n,updated_at=clock_timestamp()
    RETURNING 1)
  SELECT n INTO v_diff FROM diff;
  UPDATE public.song_link_arrivals_hourly_log SET repaired_at=clock_timestamp() WHERE id=ANY(coalesce(v_ids,ARRAY[]::uuid[]));
  INSERT INTO public.song_link_arrivals_hourly_log(artist_id,hour_utc,kind,divergent_rows) VALUES(p_artist,v_hour,'reconcile',v_diff);
  v_total:=v_total+v_diff; v_hours:=v_hours+1;
 END LOOP;
 RETURN jsonb_build_object('hours',v_hours,'divergent_rows',v_total);
END $function$

CREATE OR REPLACE FUNCTION public.song_link_arrivals_hourly_reconcile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_end timestamptz:=date_trunc('hour',clock_timestamp() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'+interval '1 hour';r record;v_result jsonb;v_total bigint:=0;v_hours bigint:=0;
BEGIN
IF current_user<>'postgres' AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'service only' USING ERRCODE='42501';END IF;
FOR r IN SELECT DISTINCT x.artist_id,x.hu FROM(SELECT artists.id artist_id,gs hu FROM public.artists CROSS JOIN LATERAL generate_series(v_end-interval '73 hours',v_end-interval '1 hour',interval '1 hour') gs WHERE EXISTS(SELECT 1 FROM public.song_link_events e WHERE e.artist_id=artists.id AND e.event='arrival') UNION ALL SELECT artist_id,hour_utc FROM public.song_link_report_hourly_log WHERE kind='pending' AND repaired_at IS NULL UNION ALL SELECT artist_id,hour_utc FROM public.song_link_arrivals_hourly_log WHERE kind='pending' AND repaired_at IS NULL AND artist_id IS NOT NULL)x ORDER BY x.artist_id,x.hu LOOP
v_result:=public.song_link_arrivals_hourly_rebuild(r.artist_id,r.hu,r.hu+interval '1 hour');v_total:=v_total+(v_result->>'divergent_rows')::bigint;
v_result:=public.song_link_report_hourly_rebuild(r.artist_id,r.hu,r.hu+interval '1 hour');v_total:=v_total+(v_result->>'divergent_rows')::bigint;v_hours:=v_hours+1;
END LOOP;RETURN jsonb_build_object('hours',v_hours,'divergent_rows',v_total);
END $function$

CREATE OR REPLACE FUNCTION public.song_link_arrivals_hourly_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_old boolean:=false; v_new boolean:=false; v_oh timestamptz; v_nh timestamptz;
 v_keys bigint[]; v_key bigint; v_timeout text; v_error text;
BEGIN
 IF TG_OP<>'INSERT' THEN v_old:=OLD.event='arrival'; END IF;
 IF TG_OP<>'DELETE' THEN v_new:=NEW.event='arrival'; END IF;
 IF NOT v_old AND NOT v_new THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND v_old AND v_new AND
  ROW(OLD.company_id,OLD.artist_id,OLD.created_at,OLD.country,OLD.os,OLD.utm_source,OLD.utm_medium,OLD.utm_campaign,OLD.utm_content,OLD.utm_term,OLD.link_id)
  IS NOT DISTINCT FROM
  ROW(NEW.company_id,NEW.artist_id,NEW.created_at,NEW.country,NEW.os,NEW.utm_source,NEW.utm_medium,NEW.utm_campaign,NEW.utm_content,NEW.utm_term,NEW.link_id) THEN RETURN NULL; END IF;
 IF v_old THEN v_oh:=date_trunc('hour',OLD.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; END IF;
 IF v_new THEN v_nh:=date_trunc('hour',NEW.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; END IF;
 v_timeout:=current_setting('lock_timeout');
 BEGIN
  PERFORM set_config('lock_timeout','25ms',true);
  SELECT array_agg(DISTINCT k ORDER BY k) INTO v_keys FROM unnest(ARRAY[
   CASE WHEN v_old THEN public.song_link_arrivals_hour_key(OLD.artist_id,v_oh) END,
   CASE WHEN v_new THEN public.song_link_arrivals_hour_key(NEW.artist_id,v_nh) END]) k WHERE k IS NOT NULL;
  FOREACH v_key IN ARRAY coalesce(v_keys,ARRAY[]::bigint[]) LOOP
   IF NOT pg_try_advisory_xact_lock(v_key) THEN RAISE EXCEPTION 'arrivals_hourly: busy hour' USING ERRCODE='55P03'; END IF;
  END LOOP;
  IF v_old THEN PERFORM public.song_link_arrivals_hour_delta(OLD,-1); END IF;
  IF v_new THEN PERFORM public.song_link_arrivals_hour_delta(NEW,1); END IF;
 EXCEPTION WHEN OTHERS THEN
  v_error:=SQLSTATE;
  BEGIN
   IF v_old THEN INSERT INTO public.song_link_arrivals_hourly_log(artist_id,hour_utc,kind,error_code) VALUES(OLD.artist_id,v_oh,'pending',v_error); END IF;
   IF v_new THEN INSERT INTO public.song_link_arrivals_hourly_log(artist_id,hour_utc,kind,error_code) VALUES(NEW.artist_id,v_nh,'pending',v_error); END IF;
  EXCEPTION WHEN OTHERS THEN RAISE WARNING 'arrivals_hourly log failed (%); capture retained',SQLSTATE; END;
 END;
 PERFORM set_config('lock_timeout',v_timeout,true);
 RETURN NULL;
EXCEPTION WHEN OTHERS THEN
 RAISE WARNING 'arrivals_hourly trigger failed (%); capture retained',SQLSTATE;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_hour_delta(p_event song_link_events, p_delta integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE h timestamptz;c text;d jsonb;k text;cnt integer;
BEGIN
h:=date_trunc('hour',p_event.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
PERFORM 1 FROM public.song_links WHERE id=p_event.link_id FOR SHARE;
SELECT public.song_link_event_canal(l.canal,p_event.utm_source,p_event.utm_medium,p_event.utm_campaign) INTO c FROM(SELECT 1)x LEFT JOIN public.song_links l ON l.id=p_event.link_id;
d:=jsonb_build_array(p_event.link_id,lower(coalesce(p_event.utm_source,'')),p_event.utm_medium,p_event.utm_campaign,p_event.country,c);
IF p_delta=1 THEN INSERT INTO public.song_link_report_hourly(company_id,artist_id,hour_utc,dim,n) VALUES(p_event.company_id,p_event.artist_id,h,d,1) ON CONFLICT(artist_id,hour_utc,dim) DO UPDATE SET n=song_link_report_hourly.n+1,company_id=excluded.company_id,updated_at=clock_timestamp();
ELSE UPDATE public.song_link_report_hourly SET n=n-1,updated_at=clock_timestamp() WHERE artist_id=p_event.artist_id AND hour_utc=h AND dim=d AND n>0; GET DIAGNOSTICS cnt=ROW_COUNT;IF cnt<>1 THEN RAISE EXCEPTION 'missing count dimension'; END IF;END IF;
FOREACH k IN ARRAY ARRAY['campaign','channel'] LOOP
 d:=CASE k WHEN 'campaign' THEN jsonb_build_array(lower(coalesce(p_event.utm_source,'')),p_event.utm_campaign,p_event.country,p_event.ip_hash) ELSE jsonb_build_array(c,p_event.country,p_event.ip_hash) END;
 IF p_delta=1 THEN INSERT INTO public.song_link_report_visitors_hourly(company_id,artist_id,hour_utc,kind,dim,n) VALUES(p_event.company_id,p_event.artist_id,h,k,d,1) ON CONFLICT(artist_id,hour_utc,kind,dim) DO UPDATE SET n=song_link_report_visitors_hourly.n+1,company_id=excluded.company_id;
 ELSE UPDATE public.song_link_report_visitors_hourly SET n=n-1 WHERE artist_id=p_event.artist_id AND hour_utc=h AND kind=k AND dim=d AND n>0;GET DIAGNOSTICS cnt=ROW_COUNT;IF cnt<>1 THEN RAISE EXCEPTION 'missing visitor dimension';END IF;END IF;
END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_hourly_rebuild(p_artist uuid, p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE h timestamptz;ids uuid[];diff bigint;total bigint:=0;hours integer:=0;
BEGIN
IF session_user<>'postgres' AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'service only' USING ERRCODE='42501';END IF;
IF p_from IS NULL OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>interval '24 hours' OR p_from<>date_trunc('hour',p_from AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR p_to<>date_trunc('hour',p_to AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' THEN RAISE EXCEPTION 'bounded whole UTC hours required';END IF;
FOR h IN SELECT generate_series(p_from,p_to-interval '1 hour',interval '1 hour') LOOP
PERFORM pg_advisory_xact_lock(public.song_link_arrivals_hour_key(p_artist,h));
PERFORM 1 FROM public.song_links l WHERE EXISTS(SELECT 1 FROM public.song_link_events e WHERE e.link_id=l.id AND e.artist_id=p_artist AND e.event='arrival' AND e.created_at>=h AND e.created_at<h+interval '1 hour') ORDER BY l.id FOR SHARE;
SELECT array_agg(id) INTO ids FROM public.song_link_report_hourly_log WHERE artist_id=p_artist AND hour_utc=h AND kind='pending' AND repaired_at IS NULL;
WITH src AS MATERIALIZED(SELECT e.company_id,e.artist_id,jsonb_build_array(e.link_id,lower(coalesce(e.utm_source,'')),e.utm_medium,e.utm_campaign,e.country,public.song_link_event_canal(l.canal,e.utm_source,e.utm_medium,e.utm_campaign)) dim,count(*)::bigint n FROM public.song_link_events e LEFT JOIN public.song_links l ON l.id=e.link_id WHERE e.artist_id=p_artist AND e.event='arrival' AND e.created_at>=h AND e.created_at<h+interval '1 hour' GROUP BY 1,2,3),
old AS MATERIALIZED(SELECT * FROM public.song_link_report_hourly WHERE artist_id=p_artist AND hour_utc=h),
dif AS(SELECT count(*) n FROM src s FULL JOIN old o USING(artist_id,dim) WHERE coalesce(s.n,0)<>coalesce(o.n,0) OR s.company_id IS DISTINCT FROM o.company_id),
removed AS(DELETE FROM public.song_link_report_hourly o WHERE o.artist_id=p_artist AND o.hour_utc=h AND NOT EXISTS(SELECT 1 FROM src s WHERE s.dim=o.dim) RETURNING 1),
written AS(INSERT INTO public.song_link_report_hourly(company_id,artist_id,hour_utc,dim,n) SELECT company_id,artist_id,h,dim,n FROM src ON CONFLICT(artist_id,hour_utc,dim) DO UPDATE SET company_id=excluded.company_id,n=excluded.n,updated_at=clock_timestamp() RETURNING 1)
SELECT n INTO diff FROM dif;total:=total+diff;
WITH e AS MATERIALIZED(SELECT e.*,public.song_link_event_canal(l.canal,e.utm_source,e.utm_medium,e.utm_campaign) canal FROM public.song_link_events e LEFT JOIN public.song_links l ON l.id=e.link_id WHERE e.artist_id=p_artist AND e.event='arrival' AND e.created_at>=h AND e.created_at<h+interval '1 hour'),
src AS MATERIALIZED(SELECT company_id,artist_id,'campaign'::text kind,jsonb_build_array(lower(coalesce(utm_source,'')),utm_campaign,country,ip_hash) dim,count(*)::bigint n FROM e GROUP BY 1,2,4 UNION ALL SELECT company_id,artist_id,'channel',jsonb_build_array(canal,country,ip_hash),count(*)::bigint FROM e GROUP BY 1,2,4),
old AS MATERIALIZED(SELECT * FROM public.song_link_report_visitors_hourly WHERE artist_id=p_artist AND hour_utc=h),
dif AS(SELECT count(*) n FROM src s FULL JOIN old o USING(artist_id,kind,dim) WHERE coalesce(s.n,0)<>coalesce(o.n,0) OR s.company_id IS DISTINCT FROM o.company_id),
removed AS(DELETE FROM public.song_link_report_visitors_hourly o WHERE o.artist_id=p_artist AND o.hour_utc=h AND NOT EXISTS(SELECT 1 FROM src s WHERE s.kind=o.kind AND s.dim=o.dim) RETURNING 1),
written AS(INSERT INTO public.song_link_report_visitors_hourly(company_id,artist_id,hour_utc,kind,dim,n) SELECT company_id,artist_id,h,kind,dim,n FROM src ON CONFLICT(artist_id,hour_utc,kind,dim) DO UPDATE SET company_id=excluded.company_id,n=excluded.n RETURNING 1)
SELECT n INTO diff FROM dif;total:=total+diff;
UPDATE public.song_link_report_hourly_log SET repaired_at=clock_timestamp() WHERE id=ANY(coalesce(ids,ARRAY[]::uuid[]));
INSERT INTO public.song_link_report_hourly_log(artist_id,hour_utc,kind,divergent_rows) VALUES(p_artist,h,'reconcile',diff);hours:=hours+1;
END LOOP;
RETURN jsonb_build_object('hours',hours,'divergent_rows',total);
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_hourly_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE vo boolean:=false;vn boolean:=false;oh timestamptz;nh timestamptz;ks bigint[];k bigint;timeout_old text;err text;
BEGIN
IF TG_OP<>'INSERT' THEN vo:=OLD.event='arrival';END IF;IF TG_OP<>'DELETE' THEN vn:=NEW.event='arrival';END IF;IF NOT vo AND NOT vn THEN RETURN NULL;END IF;
IF TG_OP='UPDATE' AND vo AND vn AND ROW(OLD.company_id,OLD.artist_id,OLD.created_at,OLD.country,OLD.ip_hash,OLD.utm_source,OLD.utm_medium,OLD.utm_campaign,OLD.link_id) IS NOT DISTINCT FROM ROW(NEW.company_id,NEW.artist_id,NEW.created_at,NEW.country,NEW.ip_hash,NEW.utm_source,NEW.utm_medium,NEW.utm_campaign,NEW.link_id) THEN RETURN NULL;END IF;
IF vo THEN oh:=date_trunc('hour',OLD.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';END IF;IF vn THEN nh:=date_trunc('hour',NEW.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';END IF;
timeout_old:=current_setting('lock_timeout');
BEGIN
PERFORM set_config('lock_timeout','25ms',true);
SELECT array_agg(DISTINCT x ORDER BY x) INTO ks FROM unnest(ARRAY[CASE WHEN vo THEN public.song_link_arrivals_hour_key(OLD.artist_id,oh) END,CASE WHEN vn THEN public.song_link_arrivals_hour_key(NEW.artist_id,nh) END]) x WHERE x IS NOT NULL;
FOREACH k IN ARRAY coalesce(ks,ARRAY[]::bigint[]) LOOP IF NOT pg_try_advisory_xact_lock(k) THEN RAISE EXCEPTION 'report hour busy' USING ERRCODE='55P03';END IF;END LOOP;
IF vo THEN PERFORM public.song_link_report_hour_delta(OLD,-1);END IF;IF vn THEN PERFORM public.song_link_report_hour_delta(NEW,1);END IF;
EXCEPTION WHEN OTHERS THEN err:=SQLSTATE;
BEGIN
IF vo THEN INSERT INTO public.song_link_report_hourly_log(artist_id,hour_utc,kind,error_code) VALUES(OLD.artist_id,oh,'pending',err);END IF;IF vn THEN INSERT INTO public.song_link_report_hourly_log(artist_id,hour_utc,kind,error_code) VALUES(NEW.artist_id,nh,'pending',err);END IF;
EXCEPTION WHEN OTHERS THEN
BEGIN UPDATE public.song_link_report_hourly_state SET ready=false WHERE artist_id IN(CASE WHEN vo THEN OLD.artist_id END,CASE WHEN vn THEN NEW.artist_id END);EXCEPTION WHEN OTHERS THEN RAISE WARNING 'report readiness invalidation failed (%)',SQLSTATE;END;
RAISE WARNING 'report log failed (%); capture retained',SQLSTATE;END;
END;
PERFORM set_config('lock_timeout',timeout_old,true);RETURN NULL;
EXCEPTION WHEN OTHERS THEN RAISE WARNING 'report trigger failed (%); capture retained',SQLSTATE;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_link_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
IF OLD.canal IS NOT DISTINCT FROM NEW.canal THEN RETURN NULL;END IF;
INSERT INTO public.song_link_report_hourly_log(artist_id,hour_utc,kind,error_code) SELECT DISTINCT artist_id,hour_utc,'pending','link_channel_changed' FROM public.song_link_report_hourly WHERE dim->>0=NEW.id::text AND n>0;RETURN NULL;
EXCEPTION WHEN OTHERS THEN
BEGIN UPDATE public.song_link_report_hourly_state SET ready=false WHERE artist_id IN(SELECT DISTINCT artist_id FROM public.song_link_report_hourly WHERE dim->>0=NEW.id::text);EXCEPTION WHEN OTHERS THEN RAISE WARNING 'report link invalidation failed (%); link retained',SQLSTATE;END;
RAISE WARNING 'report link tracking failed (%); link retained',SQLSTATE;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_visitor_daily_delta(a uuid, h timestamp with time zone, k text, d jsonb, delta bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE scope_key text;member_dim jsonb;total_dim jsonb;old_n bigint;new_n bigint;day_key date:=(h AT TIME ZONE 'UTC')::date;
BEGIN
IF delta=0 THEN RETURN;END IF;
FOREACH scope_key IN ARRAY ARRAY['all','country'] LOOP
member_dim:=CASE WHEN scope_key='country' THEN d WHEN k='campaign' THEN jsonb_build_array(d->0,d->1,NULL,d->3) ELSE jsonb_build_array(d->0,NULL,d->2) END;
total_dim:=CASE k WHEN 'campaign' THEN jsonb_build_array(member_dim->0,member_dim->1,member_dim->2) ELSE jsonb_build_array(member_dim->0,member_dim->1) END;
INSERT INTO public.song_link_report_visitor_refs_daily(artist_id,day_utc,kind,scope,dim,n) VALUES(a,day_key,k,scope_key,member_dim,0) ON CONFLICT DO NOTHING;
SELECT n INTO old_n FROM public.song_link_report_visitor_refs_daily WHERE artist_id=a AND day_utc=day_key AND kind=k AND scope=scope_key AND dim=member_dim FOR UPDATE;
new_n:=old_n+delta;
UPDATE public.song_link_report_visitor_refs_daily SET n=new_n WHERE artist_id=a AND day_utc=day_key AND kind=k AND scope=scope_key AND dim=member_dim;
IF(old_n=0 AND new_n>0) OR(old_n>0 AND new_n=0) THEN
INSERT INTO public.song_link_report_visitor_totals_daily(artist_id,day_utc,kind,scope,dim,v) VALUES(a,day_key,k,scope_key,total_dim,0) ON CONFLICT DO NOTHING;
UPDATE public.song_link_report_visitor_totals_daily SET v=v+CASE WHEN new_n>0 THEN 1 ELSE -1 END WHERE artist_id=a AND day_utc=day_key AND kind=k AND scope=scope_key AND dim=total_dim;
END IF;END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.song_link_report_visitor_daily_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
IF TG_OP='UPDATE' AND(OLD.artist_id,OLD.hour_utc,OLD.kind,OLD.dim) IS NOT DISTINCT FROM(NEW.artist_id,NEW.hour_utc,NEW.kind,NEW.dim) THEN PERFORM public.song_link_report_visitor_daily_delta(NEW.artist_id,NEW.hour_utc,NEW.kind,NEW.dim,NEW.n-OLD.n);
ELSE
IF TG_OP<>'INSERT' THEN PERFORM public.song_link_report_visitor_daily_delta(OLD.artist_id,OLD.hour_utc,OLD.kind,OLD.dim,-OLD.n);END IF;
IF TG_OP<>'DELETE' THEN PERFORM public.song_link_report_visitor_daily_delta(NEW.artist_id,NEW.hour_utc,NEW.kind,NEW.dim,NEW.n);END IF;
END IF;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION crm.ads_hourly_validate_connection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'crm'
AS $function$
DECLARE c record;
BEGIN
  SELECT company_id,platform,connection_scope,artist_id,selected_ad_account_id
    INTO c FROM crm.ad_platform_connections WHERE id=NEW.connection_id FOR SHARE;
  IF NOT FOUND OR c.company_id IS DISTINCT FROM NEW.company_id
     OR c.platform IS DISTINCT FROM NEW.platform OR c.connection_scope<>'artist'
     OR c.artist_id IS NULL OR c.selected_ad_account_id IS DISTINCT FROM NEW.ad_account_id THEN
    RAISE EXCEPTION 'hourly: ligação/empresa/plataforma/conta incompatíveis' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name=NEW.account_timezone) THEN
    RAISE EXCEPTION 'hourly: fuso da conta inválido' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.artist_ads_refresh_finish(p_artist_id uuid, p_request_id uuid, p_results jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'crm'
AS $function$
DECLARE v_row public.artist_ads_refresh_control%ROWTYPE; v_now timestamptz:=clock_timestamp();
BEGIN
  IF coalesce(auth.role(),'')<>'service_role' THEN
    RAISE EXCEPTION 'fecho reservado ao serviço' USING ERRCODE='42501';
  END IF;
  IF p_results IS NULL OR jsonb_typeof(p_results)<>'object' OR octet_length(p_results::text)>8192
     OR EXISTS(SELECT 1 FROM jsonb_each(p_results) e WHERE e.key NOT IN ('meta','tiktok','google')
       OR jsonb_typeof(e.value)<>'object' OR coalesce(e.value->>'status','') NOT IN ('success','partial','error','not_connected'))
     OR EXISTS(SELECT 1 FROM jsonb_each(p_results) e,
       LATERAL jsonb_object_keys(CASE WHEN jsonb_typeof(e.value)='object' THEN e.value ELSE '{}'::jsonb END) k
       WHERE k NOT IN ('status','last_synced_at','rows_written','api_calls','reason')) THEN
    RAISE EXCEPTION 'resultados inválidos';
  END IF;
  SELECT * INTO v_row FROM public.artist_ads_refresh_control WHERE artist_id=p_artist_id FOR UPDATE;
  IF NOT FOUND OR p_request_id IS NULL OR v_row.request_id IS DISTINCT FROM p_request_id
     OR v_row.lease_until IS NULL OR v_row.lease_until<=v_now THEN
    RETURN jsonb_build_object('accepted',false,'reason','stale_request');
  END IF;
  UPDATE public.artist_ads_refresh_control SET lease_until=NULL,request_id=NULL,
    platform_results=p_results,
    last_synced_at=CASE WHEN EXISTS(SELECT 1 FROM jsonb_each(p_results) e WHERE e.value->>'status'='success')
      AND NOT EXISTS(SELECT 1 FROM jsonb_each(p_results) e WHERE e.value->>'status' IN ('partial','error'))
      THEN v_now ELSE last_synced_at END WHERE artist_id=p_artist_id RETURNING * INTO v_row;
  RETURN jsonb_build_object('accepted',true,'last_synced_at',v_row.last_synced_at,'platforms',v_row.platform_results);
END $function$

CREATE OR REPLACE FUNCTION crm.artist_ads_alert_notify(p_alert_id uuid, p_event text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  a record; v_artist text; v_subject text; v_text text; v_msg_id text; v_ch text; v_tok text;
  v_channels text[] := ARRAY['email'];   -- 2.º canal (ex.: 'whatsapp') acrescenta-se aqui
  v_to constant text := 'pedroneto@mundopropicio.com';
BEGIN
  SELECT l.*, c.selected_ad_account_id AS acc INTO a
  FROM public.artist_ads_alert_log l JOIN crm.ad_platform_connections c ON c.id = l.connection_id
  WHERE l.id = p_alert_id;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT name INTO v_artist FROM public.artists WHERE id = a.artist_id;
  v_subject := '[ALERTA ADS] ' || coalesce(v_artist,'Artista') || ' · ' || initcap(a.platform) || ' ' || coalesce(a.acc,'?') || ' · ' || a.kind
               || CASE WHEN p_event = 'resolved' THEN ' · resolvido' ELSE '' END;
  v_text := CASE WHEN p_event = 'resolved'
    THEN 'Resolvido: ' || a.message || E'\nDetectado: ' || to_char(a.detected_at AT TIME ZONE 'America/Fortaleza','DD/MM HH24:MI')
         || E'\nResolvido: ' || to_char(coalesce(a.resolved_at, now()) AT TIME ZONE 'America/Fortaleza','DD/MM HH24:MI') || ' (Fortaleza)'
    ELSE a.message || E'\nGravidade: ' || a.severity || E'\nDetectado: '
         || to_char(a.detected_at AT TIME ZONE 'America/Fortaleza','DD/MM HH24:MI') || ' (Fortaleza)' END
    || E'\n\n— MP Gestão Eventos';
  v_msg_id := 'ads-alert-' || p_alert_id::text || '-' || p_event || '-' || to_char(clock_timestamp(),'YYYYMMDDHH24MISS');

  SELECT token INTO v_tok FROM public.email_unsubscribe_tokens WHERE email = v_to LIMIT 1;
  IF v_tok IS NULL THEN
    v_tok := encode(extensions.gen_random_bytes(32), 'hex');
    INSERT INTO public.email_unsubscribe_tokens (token, email, company_id) VALUES (v_tok, v_to, a.company_id)
    ON CONFLICT (email) DO NOTHING;
    SELECT token INTO v_tok FROM public.email_unsubscribe_tokens WHERE email = v_to LIMIT 1;
  END IF;

  FOREACH v_ch IN ARRAY v_channels LOOP
    IF v_ch = 'email' THEN
      PERFORM public.enqueue_email('transactional_emails', jsonb_build_object(
        'message_id', v_msg_id, 'to', v_to,
        'from', 'MP Gestão Eventos <noreply@mpgestaoeventos.com>',
        'sender_domain', 'notify.mpgestaoeventos.com',
        'subject', v_subject, 'text', v_text,
        'html', '<pre style="font-family:Helvetica,Arial,sans-serif;font-size:14px;white-space:pre-wrap">' ||
                replace(replace(v_text,'&','&amp;'),'<','&lt;') || '</pre>',
        'purpose', 'transactional', 'label', 'artist_ads_alert',
        'idempotency_key', v_msg_id, 'unsubscribe_token', v_tok,
        'queued_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')), a.company_id);
    END IF;
  END LOOP;
  IF p_event = 'resolved' THEN
    UPDATE public.artist_ads_alert_log SET resolved_notified_at = now() WHERE id = p_alert_id;
  ELSE
    UPDATE public.artist_ads_alert_log SET notified_at = now() WHERE id = p_alert_id;
  END IF;
END $function$

CREATE OR REPLACE FUNCTION crm.tiktok_manual_upsert_core(p_connection_id uuid, p_payload jsonb, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_conn record;
  v_camp jsonb := coalesce(p_payload->'campanha', '{}'::jsonb);
  v_cid text; v_name text; v_song uuid; v_currency text; v_existing_src text;
  g jsonb; d jsonb;
  v_level text; v_ext text; v_date date; v_spend numeric; v_src text;
  n_camp int := 0; n_camp_skip int := 0; n_grp int := 0; n_grp_skip int := 0;
  n_day_ins int := 0; n_day_upd int := 0; n_day_skip int := 0;
  k text;
BEGIN
  SELECT * INTO v_conn FROM crm.ad_platform_connections WHERE id = p_connection_id;
  IF NOT FOUND OR v_conn.platform <> 'tiktok' OR v_conn.connection_scope <> 'artist' THEN
    RAISE EXCEPTION 'ligação TikTok de artista não encontrada' USING ERRCODE = '22023';
  END IF;

  v_currency := v_conn.selected_ad_account_currency;
  v_name := nullif(trim(v_camp->>'name'), '');
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'campanha.name obrigatório' USING ERRCODE = '22023';
  END IF;
  IF (v_camp->>'budget_cents') IS NOT NULL AND (v_camp->>'budget_cents')::numeric < 0 THEN
    RAISE EXCEPTION 'campanha.budget_cents negativo' USING ERRCODE = '22023';
  END IF;
  v_song := nullif(v_camp->>'song_id','')::uuid;
  IF v_song IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.artist_songs s WHERE s.id = v_song AND s.artist_id = v_conn.artist_id
  ) THEN
    RAISE EXCEPTION 'song_id não pertence ao artista da ligação' USING ERRCODE = '22023';
  END IF;

  v_cid := nullif(trim(v_camp->>'external_campaign_id'), '');
  IF v_cid IS NULL THEN
    SELECT external_campaign_id INTO v_cid FROM crm.tiktok_campaign
     WHERE connection_id = p_connection_id AND source = 'api' AND name = v_name
     ORDER BY last_synced_at DESC LIMIT 1;
  END IF;
  IF v_cid IS NULL THEN
    v_cid := 'manual:' || public.tiktok_manual_slug(v_name);
  END IF;

  SELECT source INTO v_existing_src FROM crm.tiktok_campaign
   WHERE connection_id = p_connection_id AND external_campaign_id = v_cid;
  IF v_existing_src = 'api' THEN
    n_camp_skip := 1;
  ELSE
    INSERT INTO crm.tiktok_campaign (company_id, connection_id, external_campaign_id, name, status,
      objective, budget_cents, currency, source, last_synced_at, raw)
    VALUES (v_conn.company_id, p_connection_id, v_cid, v_name, v_camp->>'status', v_camp->>'objective',
      (v_camp->>'budget_cents')::bigint, v_currency, 'manual', now(), v_camp)
    ON CONFLICT (connection_id, external_campaign_id) DO UPDATE SET
      name = EXCLUDED.name, status = EXCLUDED.status, objective = EXCLUDED.objective,
      budget_cents = EXCLUDED.budget_cents, currency = EXCLUDED.currency,
      last_synced_at = now(), raw = EXCLUDED.raw
    WHERE crm.tiktok_campaign.source = 'manual';
    n_camp := 1;
  END IF;
  IF v_song IS NOT NULL THEN
    UPDATE crm.tiktok_campaign SET linked_song_id = v_song, linked_song_locked = true
     WHERE connection_id = p_connection_id AND external_campaign_id = v_cid;
  END IF;

  FOR g IN SELECT * FROM jsonb_array_elements(coalesce(p_payload->'grupos','[]'::jsonb)) LOOP
    v_ext := nullif(trim(g->>'external_adgroup_id'), '');
    IF v_ext IS NULL THEN
      RAISE EXCEPTION 'grupos[].external_adgroup_id obrigatório' USING ERRCODE = '22023';
    END IF;
    IF (g->>'budget_cents') IS NOT NULL AND (g->>'budget_cents')::numeric < 0 THEN
      RAISE EXCEPTION 'grupo % com budget_cents negativo', v_ext USING ERRCODE = '22023';
    END IF;
    SELECT source INTO v_src FROM crm.tiktok_adgroup WHERE connection_id = p_connection_id AND external_adgroup_id = v_ext;
    IF v_src = 'api' THEN
      n_grp_skip := n_grp_skip + 1;
    ELSE
      INSERT INTO crm.tiktok_adgroup (company_id, connection_id, external_campaign_id, external_adgroup_id,
        name, status, budget_cents, currency, source, last_synced_at, raw)
      VALUES (v_conn.company_id, p_connection_id, v_cid, v_ext, g->>'name', g->>'status',
        (g->>'budget_cents')::bigint, v_currency, 'manual', now(), g)
      ON CONFLICT (connection_id, external_adgroup_id) DO UPDATE SET
        external_campaign_id = EXCLUDED.external_campaign_id, name = EXCLUDED.name, status = EXCLUDED.status,
        budget_cents = EXCLUDED.budget_cents, currency = EXCLUDED.currency, last_synced_at = now(), raw = EXCLUDED.raw
      WHERE crm.tiktok_adgroup.source = 'manual';
      n_grp := n_grp + 1;
    END IF;
    v_src := NULL;
  END LOOP;

  FOR d IN SELECT * FROM jsonb_array_elements(coalesce(p_payload->'dias','[]'::jsonb)) LOOP
    v_level := coalesce(d->>'level', 'adgroup');
    IF v_level NOT IN ('campaign','adgroup') THEN
      RAISE EXCEPTION 'dias[].level inválido: %', v_level USING ERRCODE = '22023';
    END IF;
    v_date := (d->>'date')::date;
    IF v_date IS NULL OR v_date > current_date THEN
      RAISE EXCEPTION 'dias[].date inválida ou futura: %', d->>'date' USING ERRCODE = '22023';
    END IF;
    v_ext := coalesce(nullif(trim(d->>'external_id'),''), CASE WHEN v_level = 'campaign' THEN v_cid END);
    IF v_ext IS NULL THEN
      RAISE EXCEPTION 'dias[].external_id obrigatório no nível adgroup' USING ERRCODE = '22023';
    END IF;
    FOREACH k IN ARRAY ARRAY['spend','impressions','clicks','video_views_6s','video_views_2s','likes','follows','reach','view_content','button_click'] LOOP
      IF (d->>k) IS NOT NULL AND (d->>k)::numeric < 0 THEN
        RAISE EXCEPTION 'dias[].% negativo (%)', k, d->>'date' USING ERRCODE = '22023';
      END IF;
    END LOOP;
    v_spend := (d->>'spend')::numeric;

    SELECT source INTO v_src FROM crm.tiktok_insights_daily
     WHERE connection_id = p_connection_id AND level = v_level AND external_id = v_ext AND date_start = v_date;
    IF v_src = 'api' THEN
      n_day_skip := n_day_skip + 1;
    ELSE
      IF v_src IS NULL THEN n_day_ins := n_day_ins + 1; ELSE n_day_upd := n_day_upd + 1; END IF;
      INSERT INTO crm.tiktok_insights_daily (company_id, connection_id, level, external_id, external_campaign_id,
        date_start, spend_cents, impressions, clicks, video_views_6s, video_views_2s, likes, follows, reach,
        view_content, button_click, currency, source, recorded_at, raw)
      VALUES (v_conn.company_id, p_connection_id, v_level, v_ext, v_cid, v_date,
        CASE WHEN v_spend IS NULL THEN NULL ELSE round(v_spend * 100)::bigint END,
        (d->>'impressions')::bigint, (d->>'clicks')::bigint, (d->>'video_views_6s')::bigint,
        (d->>'video_views_2s')::bigint, (d->>'likes')::bigint, (d->>'follows')::bigint, (d->>'reach')::bigint,
        (d->>'view_content')::integer, (d->>'button_click')::integer,
        v_currency, 'manual', now(), d || jsonb_build_object('gravado_por', p_actor))
      ON CONFLICT (connection_id, level, external_id, date_start) DO UPDATE SET
        external_campaign_id = EXCLUDED.external_campaign_id, spend_cents = EXCLUDED.spend_cents,
        impressions = EXCLUDED.impressions, clicks = EXCLUDED.clicks, video_views_6s = EXCLUDED.video_views_6s,
        video_views_2s = EXCLUDED.video_views_2s, likes = EXCLUDED.likes, follows = EXCLUDED.follows,
        reach = EXCLUDED.reach,
        view_content = CASE WHEN d ? 'view_content' THEN EXCLUDED.view_content ELSE crm.tiktok_insights_daily.view_content END,
        button_click = CASE WHEN d ? 'button_click' THEN EXCLUDED.button_click ELSE crm.tiktok_insights_daily.button_click END,
        currency = EXCLUDED.currency, recorded_at = now(), raw = EXCLUDED.raw
      WHERE crm.tiktok_insights_daily.source = 'manual';
    END IF;
    v_src := NULL;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true, 'external_campaign_id', v_cid,
    'campanha', jsonb_build_object('gravada', n_camp, 'ignorada_api', n_camp_skip),
    'grupos', jsonb_build_object('gravados', n_grp, 'ignorados_api', n_grp_skip),
    'dias', jsonb_build_object('inseridos', n_day_ins, 'atualizados', n_day_upd, 'ignorados_api', n_day_skip));
END;
$function$

CREATE OR REPLACE FUNCTION public.data_entry_assistant_review_333(p_action text, p_actor uuid, p_company uuid, p_review uuid, p_expected_version integer, p_hash text, p_proposal jsonb, p_action_ids text[], p_replay uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.data_entry_assistant_reviews_333; v public.data_entry_assistant_review_versions_333;
  a public.data_entry_assistant_authorizations_333; open_ids text[]; sel text[]; x jsonb;
BEGIN
  IF p_action = 'probe' THEN
    RETURN jsonb_build_object('schema', '333-12f', 'enabled', coalesce((SELECT enabled FROM public.data_entry_assistant_review_settings_333 WHERE singleton), false));
  END IF;
  IF p_actor IS NULL OR p_company IS NULL THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  IF NOT coalesce((SELECT enabled FROM public.data_entry_assistant_review_settings_333 WHERE singleton), false) THEN RAISE EXCEPTION '#333: review_closed' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.data_entry_assistant_scope_333 WHERE owner_id = p_actor AND company_id = p_company AND expires_at > now())
  THEN RAISE EXCEPTION '#333: scope_closed' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until <= now()))
     OR NOT EXISTS (SELECT 1 FROM public.companies WHERE id = p_company AND status = 'active')
     OR coalesce(public._effective_permissions_for(p_actor, p_company, '{}'::text[])->>'role', '') NOT IN ('admin', 'manager')
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  IF p_hash IS NULL OR p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION '#333: stale_version' USING ERRCODE = '22023'; END IF;
  IF p_action = 'save' THEN
    IF p_proposal IS NULL OR p_proposal->>'company_id' IS DISTINCT FROM p_company::text OR p_proposal->'effects'->>'company' IS DISTINCT FROM p_company::text
       OR p_proposal->>'effects_hash' IS DISTINCT FROM p_hash
       OR encode(sha256(convert_to(public._de333_canon(jsonb_build_object('effects', p_proposal->'effects', 'actions', p_proposal->'actions')), 'UTF8')), 'hex') <> p_hash
    THEN RAISE EXCEPTION '#333: hash_mismatch' USING ERRCODE = '22023'; END IF;
    IF jsonb_typeof(p_proposal->'actions') <> 'array' OR jsonb_array_length(p_proposal->'actions') <> 5
       OR (SELECT array_agg(e->>'id' ORDER BY e->>'id') FROM jsonb_array_elements(p_proposal->'actions') e) IS DISTINCT FROM ARRAY['a1','a2','a3','a4','a5']
    THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
    IF p_review IS NULL THEN
      INSERT INTO public.data_entry_assistant_reviews_333(owner_id, company_id, version, effects_hash) VALUES (p_actor, p_company, 1, p_hash) RETURNING * INTO r;
    ELSE
      SELECT * INTO r FROM public.data_entry_assistant_reviews_333 WHERE id = p_review FOR UPDATE;
      IF NOT FOUND OR r.owner_id <> p_actor OR r.company_id <> p_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
      IF r.version IS DISTINCT FROM p_expected_version THEN RAISE EXCEPTION '#333: stale_version' USING ERRCODE = '40001'; END IF;
      UPDATE public.data_entry_assistant_reviews_333 SET version = version + 1, effects_hash = p_hash, updated_at = clock_timestamp() WHERE id = r.id RETURNING * INTO r;
    END IF;
    INSERT INTO public.data_entry_assistant_review_versions_333(review_id, version, effects_hash, proposal, created_by) VALUES (r.id, r.version, p_hash, p_proposal, p_actor);
    RETURN jsonb_build_object('review_id', r.id, 'version', r.version, 'effects_hash', r.effects_hash);
  ELSIF p_action = 'authorize' THEN
    SELECT * INTO r FROM public.data_entry_assistant_reviews_333 WHERE id = p_review FOR UPDATE;
    IF NOT FOUND OR r.owner_id <> p_actor OR r.company_id <> p_company THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
    SELECT * INTO a FROM public.data_entry_assistant_authorizations_333 WHERE owner_id = p_actor AND company_id = p_company AND replay_key = p_replay;
    IF FOUND THEN
      IF a.review_id = p_review AND a.version = p_expected_version AND a.effects_hash = p_hash AND a.action_ids = p_action_ids
      THEN RETURN jsonb_build_object('authorization_id', a.id, 'replayed', true, 'status', a.status, 'action_ids', to_jsonb(a.action_ids)); END IF;
      RAISE EXCEPTION '#333: replay_conflict' USING ERRCODE = '23505';
    END IF;
    IF r.version IS DISTINCT FROM p_expected_version OR r.effects_hash IS DISTINCT FROM p_hash THEN RAISE EXCEPTION '#333: stale_version' USING ERRCODE = '40001'; END IF;
    SELECT * INTO v FROM public.data_entry_assistant_review_versions_333 WHERE review_id = r.id AND version = r.version;
    IF p_action_ids IS NULL OR cardinality(p_action_ids) = 0 OR (SELECT count(DISTINCT e) FROM unnest(p_action_ids) e) <> cardinality(p_action_ids)
    THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
    SELECT coalesce(array_agg(e->>'id'), '{}') INTO open_ids FROM jsonb_array_elements(v.proposal->'actions') e WHERE e->'blocked_reason' = 'null'::jsonb;
    sel := p_action_ids;
    IF NOT (sel <@ open_ids) THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
    FOR x IN SELECT e FROM jsonb_array_elements(v.proposal->'actions') e WHERE e->>'id' = ANY (sel) LOOP
      IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(x->'depends_on') d WHERE NOT (d = ANY (sel))) THEN RAISE EXCEPTION '#333: actions_blocked' USING ERRCODE = 'P0001'; END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM public.data_entry_assistant_authorizations_333 WHERE review_id = r.id AND version = r.version) THEN RAISE EXCEPTION '#333: replay_conflict' USING ERRCODE = '23505'; END IF;
    INSERT INTO public.data_entry_assistant_authorizations_333(review_id, version, effects_hash, action_ids, replay_key, owner_id, company_id)
    VALUES (r.id, r.version, p_hash, p_action_ids, p_replay, p_actor, p_company) RETURNING * INTO a;
    RETURN jsonb_build_object('authorization_id', a.id, 'replayed', false, 'status', a.status, 'action_ids', to_jsonb(a.action_ids));
  END IF;
  RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '22023';
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_pilot8_receipt(p_owner uuid, p_company uuid, p_session uuid, p_bucket text, p_path text, p_sha text, p_size integer, p_mime text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s public.data_entry_sessions; d public.data_entry_documents; op text; permitted boolean; c uuid; pr public.profiles; pa boolean;
BEGIN
 IF p_owner IS NULL OR p_company IS NULL THEN RAISE EXCEPTION '#333: Contexto inválido' USING ERRCODE='42501'; END IF;
 SELECT * INTO pr FROM public.profiles WHERE id=p_owner;
 pa := public.is_platform_admin(p_owner);
 IF pr.active_company_id IS NOT NULL AND (pa OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_owner AND company_id=pr.active_company_id)) THEN c:=pr.active_company_id;
 ELSIF pr.company_id IS NOT NULL AND (pa OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_owner AND company_id=pr.company_id)) THEN c:=pr.company_id;
 ELSE SELECT ur.company_id INTO c FROM public.user_roles ur JOIN public.companies co ON co.id=ur.company_id WHERE ur.user_id=p_owner AND co.status='active' ORDER BY ur.id LIMIT 1; END IF;
 IF c IS DISTINCT FROM p_company OR coalesce(public._effective_permissions_for(p_owner,c,'{}'::text[])->>'role','') NOT IN ('admin','platform_admin','manager') OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=c AND status='active') THEN RAISE EXCEPTION '#333: Contexto alterado' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.data_entry_sessions WHERE id=p_session AND owner_id=p_owner AND company_id=c FOR UPDATE;
 IF s.id IS NULL THEN RAISE EXCEPTION '#333: Lote indisponível' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_owner FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=p_owner ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.companies WHERE id=c FOR SHARE;
 IF coalesce(public._effective_permissions_for(p_owner,c,'{}'::text[])->>'role','') NOT IN ('admin','platform_admin','manager') OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=c AND status='active') THEN RAISE EXCEPTION '#333: Contexto alterado' USING ERRCODE='42501'; END IF;
 SELECT * INTO pr FROM public.profiles WHERE id=p_owner;
 pa := public.is_platform_admin(p_owner);
 IF pr.active_company_id IS NOT NULL AND (pa OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_owner AND company_id=pr.active_company_id)) THEN c:=pr.active_company_id;
 ELSIF pr.company_id IS NOT NULL AND (pa OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_owner AND company_id=pr.company_id)) THEN c:=pr.company_id;
 ELSE SELECT ur.company_id INTO c FROM public.user_roles ur JOIN public.companies co ON co.id=ur.company_id WHERE ur.user_id=p_owner AND co.status='active' ORDER BY ur.id LIMIT 1; END IF;
 IF c IS DISTINCT FROM p_company THEN RAISE EXCEPTION '#333: Contexto alterado' USING ERRCODE='42501'; END IF;
 IF p_bucket='data-entry-staging' THEN
  op := 'preparation';
  IF p_path IS DISTINCT FROM s.company_id::text||'/'||s.id::text||'/'||p_sha THEN
   RAISE EXCEPTION '#333: Caminho inválido' USING ERRCODE='22023'; END IF;
 ELSIF p_bucket='standalone-invoices' THEN
  op := 'assistant_create';
  SELECT * INTO d FROM public.data_entry_documents WHERE session_id=s.id AND sha256=p_sha AND size_bytes=p_size AND mime=p_mime;
  IF d.id IS NULL OR p_path IS DISTINCT FROM s.company_id::text||'/assistant333/'||d.id::text||'/'||d.sha256||
   (CASE d.mime WHEN 'application/pdf' THEN '.pdf' WHEN 'image/jpeg' THEN '.jpg' ELSE '.png' END) THEN
   RAISE EXCEPTION '#333: Documento inválido' USING ERRCODE='22023'; END IF;
 ELSE RAISE EXCEPTION '#333: Destino inválido' USING ERRCODE='22023'; END IF;
 SELECT enabled INTO permitted FROM public.data_entry_pilot8_allowlist WHERE owner_id=p_owner AND company_id=c AND operation=op FOR SHARE;
 IF NOT coalesce(permitted,false) OR NOT EXISTS(SELECT 1 FROM public.data_entry_pilot8_allowlist WHERE owner_id=p_owner AND company_id=c AND operation=op AND enabled AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION '#333: Piloto indisponível' USING ERRCODE='42501'; END IF;
 PERFORM public.data_entry_record_receipt(p_bucket,p_path,p_sha,p_size,p_mime);
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_analysis_responsible_333(p_action text, p_revision bigint, p_claim uuid, p_review_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c public.data_entry_analysis_control_333; prior_claim uuid;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'analysis_responsible_owner_only' USING ERRCODE='42501'; END IF;
 IF p_action IS NULL OR p_action NOT IN ('close','confer','reopen') OR p_review_sha256 IS NULL OR p_review_sha256 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'analysis_responsible_payload' USING ERRCODE='22023'; END IF;
 SELECT * INTO c FROM public.data_entry_analysis_control_333 WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'analysis_control_missing' USING ERRCODE='42501'; END IF;
 IF p_revision IS NULL OR c.revision<>p_revision THEN RAISE EXCEPTION 'analysis_control_revision' USING ERRCODE='40001'; END IF;
 IF p_claim IS DISTINCT FROM c.active_claim THEN RAISE EXCEPTION 'analysis_control_claim' USING ERRCODE='42501'; END IF;
 prior_claim:=c.active_claim;
 IF p_action='reopen' THEN
   IF c.active_claim IS NOT NULL OR c.stage<>'idle' OR c.state<>'closed' THEN RAISE EXCEPTION 'analysis_responsible_conference_required' USING ERRCODE='42501'; END IF;
   c.state:='ready'; c.enabled:=true; c.reviewed:=true; c.reason_code:='none';
 ELSE
   c.state:='closed'; c.enabled:=false; c.reviewed:=false; c.reason_code:='closed';
   IF p_action='confer' THEN c.active_claim:=NULL; c.stage:='idle'; END IF;
 END IF;
 c.revision:=c.revision+1; c.upstream_status:=NULL; c.changed_at:=clock_timestamp();
 UPDATE public.data_entry_analysis_control_333 SET revision=c.revision,state=c.state,enabled=c.enabled,reviewed=c.reviewed,active_claim=c.active_claim,stage=c.stage,reason_code=c.reason_code,upstream_status=c.upstream_status,changed_at=c.changed_at WHERE singleton;
 INSERT INTO public.data_entry_analysis_audit_333(revision,claim,stage,reason_code,admin_action,review_sha256) VALUES(c.revision,prior_claim,c.stage,c.reason_code,p_action,p_review_sha256);
 RETURN jsonb_build_object('revision',c.revision::text,'state',c.state,'claim',c.active_claim,'stage',c.stage);
END $function$

CREATE OR REPLACE FUNCTION crm.event_active_triggers_write_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'crm'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO crm.event_active_triggers_log (
      company_id, event_id, active_trigger_id, trigger_id,
      changed_by, action, old_state, new_state
    ) VALUES (
      NEW.company_id, NEW.event_id, NEW.id, NEW.trigger_id,
      v_actor, 'insert', NULL, to_jsonb(NEW)
    );
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO crm.event_active_triggers_log (
      company_id, event_id, active_trigger_id, trigger_id,
      changed_by, action, old_state, new_state
    ) VALUES (
      NEW.company_id, NEW.event_id, NEW.id, NEW.trigger_id,
      v_actor, 'update', to_jsonb(OLD), to_jsonb(NEW)
    );
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO crm.event_active_triggers_log (
      company_id, event_id, active_trigger_id, trigger_id,
      changed_by, action, old_state, new_state
    ) VALUES (
      OLD.company_id, OLD.event_id, OLD.id, OLD.trigger_id,
      v_actor, 'delete', to_jsonb(OLD), NULL
    );
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public._de333_closing_check(c jsonb, p_company uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_office uuid := public._de333_req(c, 'office')::uuid; v_event uuid := public._de333_req(c, 'event')::uuid;
  v_to uuid := public._de333_req(c, 'transfer_account')::uuid; v_sdate date := public._de333_req(c, 'settlement_date')::date;
  v_gross_c bigint := public._de333_cents(c->'gross_cents', 1); v_ded_c bigint := public._de333_cents(c->'deductions_cents', 0);
  v_net_c bigint := public._de333_cents(c->'net_cents', 1); v_right_c bigint := public._de333_cents(c->'event_right_cents', 1);
  v_gross numeric; v_n int; d jsonb; t record; v_sum bigint := 0; v_dc bigint; v_ok boolean;
BEGIN
  IF jsonb_typeof(c->'deductions') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION '#333: data_incomplete' USING ERRCODE = 'P0001'; END IF;
  IF (v_sdate > (now() AT TIME ZONE 'Europe/Lisbon')::date) IS NOT FALSE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_office AND company_id = p_company AND type = 'ticket_office' AND is_active IS TRUE)
     OR NOT EXISTS (SELECT 1 FROM public.financial_accounts WHERE id = v_to AND company_id = p_company AND is_active IS TRUE AND type IN ('bank','cash','venue') AND id <> v_office)
     OR NOT EXISTS (SELECT 1 FROM public.events WHERE id = v_event AND company_id = p_company)
     OR NOT EXISTS (SELECT 1 FROM public.event_ticket_office_assignments WHERE event_id = v_event AND financial_account_id = v_office)
  THEN RAISE EXCEPTION '#333: context_mismatch' USING ERRCODE = '42501'; END IF;
  IF EXISTS (SELECT 1 FROM public.ticket_office_settlements WHERE event_id = v_event AND company_id = p_company AND status IS DISTINCT FROM 'reversed' AND reversed_at IS NULL)
  THEN RAISE EXCEPTION '#333: event_sealed' USING ERRCODE = 'P0001'; END IF;
  -- Venda com total_value e quantity×unit_price nulos não tem receita definida: recusa em vez de somar como 0.
  SELECT count(*), sum(coalesce(s.total_value, s.quantity * s.unit_price)), count(*) FILTER (WHERE coalesce(s.total_value, s.quantity * s.unit_price) IS NULL)
    INTO v_n, v_gross, v_dc
    FROM public.ticket_sales s JOIN public.event_ticket_zones z ON z.id = s.zone_id
   WHERE z.event_id = v_event AND s.financial_account_id = v_office;
  IF v_n = 0 OR v_dc <> 0 OR round(v_gross * 100) IS DISTINCT FROM v_gross_c THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
  IF (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(c->'deductions') x) IS DISTINCT FROM jsonb_array_length(c->'deductions')::bigint
  THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
  FOR d IN SELECT x FROM jsonb_array_elements(c->'deductions') x LOOP
    v_dc := public._de333_cents(d->'gross_cents', 1);
    SELECT * INTO t FROM public.transactions WHERE id = public._de333_req(d, 'id')::uuid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    v_ok := t.company_id = p_company AND t.type = 'expense' AND t.settlement_id IS NULL AND t.exclude_from_result IS FALSE
       AND coalesce(t.operation_key, '') NOT LIKE 'TRF-FECHO-%' AND t.reversed_at IS NULL
       AND (t.status IN ('pending','approved') OR (t.status = 'paid' AND t.account_id = v_office))
       AND (t.event_id = v_event OR EXISTS (SELECT 1 FROM public.transactions sp WHERE sp.parent_transaction_id = t.id AND sp.event_id = v_event AND sp.type = 'expense'))
       AND NOT EXISTS (SELECT 1 FROM public.event_ticket_office_advances a WHERE a.event_id = v_event AND a.financial_account_id = v_office AND a.transaction_id = t.id)
       AND NOT EXISTS (SELECT 1 FROM public.ticket_office_statement_lines l WHERE l.transaction_id = t.id AND l.line_type IN ('advance','carry_over'))
       AND round(round(t.amount * (1 + t.iva_rate / 100.0), 2) * 100) = v_dc;
    IF v_ok IS NOT TRUE THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
    v_sum := v_sum + v_dc;
  END LOOP;
  IF v_sum IS DISTINCT FROM v_ded_c OR v_net_c IS DISTINCT FROM v_gross_c - v_sum OR v_right_c IS DISTINCT FROM v_net_c
  THEN RAISE EXCEPTION '#333: data_changed' USING ERRCODE = 'P0001'; END IF;
  RETURN v_gross;
END $function$

CREATE OR REPLACE FUNCTION public.data_entry_pilot8_gate(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u uuid:=auth.uid(); c uuid:=public.current_company_id(); r text; permitted boolean:=false;
BEGIN
 IF u IS NULL OR c IS NULL OR p_operation NOT IN ('preparation','assistant_create') OR p_operation IS NULL THEN RETURN false; END IF;
 PERFORM 1 FROM public.profiles WHERE id=u FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=u ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.companies WHERE id=c FOR SHARE;
 IF public.current_company_id() IS DISTINCT FROM c THEN RETURN false; END IF;
 r:=public._effective_permissions_for(u,c,'{}'::text[])->>'role';
 IF coalesce(r,'') NOT IN ('admin','platform_admin','manager') OR NOT EXISTS(SELECT 1 FROM public.companies WHERE id=c AND status='active') THEN RETURN false; END IF;
 -- Shared lock prevents concurrent revocation overtaking this transaction's effect.
 SELECT enabled INTO permitted
 FROM public.data_entry_pilot8_allowlist WHERE owner_id=u AND company_id=c AND operation=p_operation FOR SHARE;
 RETURN coalesce(permitted,false) AND EXISTS(SELECT 1 FROM public.data_entry_pilot8_allowlist WHERE owner_id=u AND company_id=c AND operation=p_operation AND enabled AND expires_at>clock_timestamp());
END $function$

